Object.assign(window.DEEP = window.DEEP || {}, {
 "L'automne": {"pos":"n.m. 阳性名词，复数 automnes","s":"秋天。一年四季之一，通常指 9 月到 11 月。美式「fall」法语里没有对应词，只用 automne。","ipa":"[o.tɔn]","ph":"au [o]；单词中间的 m 不发音，所以是 [o.tɔn]，不是「奥-通-姆」。","pi":"automne 里的 m 不发音；n 要发出来。拼写别漏掉 m 和双 n 的位置：au-tom-ne。","et":"来自拉丁语 autumnus（秋天）。形容词：automnal（秋天的）。","ex":[["Les feuilles tombent en automne.","树叶在秋天掉落。"],["J'aime les couleurs de l'automne.","我喜欢秋天的颜色。"]],"co":[["en automne / à l'automne","在秋天"],["l'automne dernier / prochain","去年秋天 / 明年秋天"],["les feuilles d'automne","秋叶"]],"sy":[["saison","courant","上位词：季节"],["l'été","courant","前一个季节：夏天"]],"fq":"常用，日常和书面都有。","me":"au-to-mne：auto 开头，m 不发声，当它是「auto」加 n。","tr":{"zh":"秋天我们常常去森林里散步。","fr":"En automne, nous nous promenons souvent en forêt.","alt":"À l'automne, on se balade souvent en forêt.","note":"季节前用 en：en automne, en été, en hiver；只有 au printemps 例外。"}},
 "L'été": {"pos":"n.m. 阳性名词，复数 étés","s":"夏天。注意：été 同时也是动词 être 的过去分词（j'ai été = 我曾经是/去过）。","ipa":"[e.te]","ph":"两个 é 都读 [e]，嘴型较扁，不要读成「艾」[ɛ]；l'été 里 l' 与 é 连读成 [le.te]。","pi":"两个重音符号都是 é。别把它和 hiver 的 h 搞混；été 的开头是元音，所以用 l'。","et":"来自拉丁语 aestas（夏天）。词形缩短后只剩 été。","ex":[["Il fait chaud en été.","夏天很热。"],["En été, on mange des glaces.","夏天我们吃冰淇淋。"]],"co":[["en été","在夏天"],["l'été dernier / prochain","去年夏天 / 明年夏天"],["les vacances d'été","暑假"]],"sy":[["saison","courant","季节"],["l'hiver","courant","反义词：冬天"]],"fq":"极高频，日常常用。","me":"两个 é 像两个笑脸：été = 夏天很开心。","tr":{"zh":"夏天我们去海边。","fr":"En été, nous allons à la plage.","alt":"L'été, on va souvent à la plage.","note":"L'été 以元音开头，冠词变成 l'；「在夏天」说 en été。"}},
 "L'hiver": {"pos":"n.m. 阳性名词，复数 hivers","s":"冬天，12 月到 2 月左右。形容词是 hivernal；动词 hiverner = 过冬。","ipa":"[i.vɛʁ]","ph":"h 不发音（哑音 h）；i [i]；v [v]；er 结尾读 [ɛʁ]，r 在喉咙后部发音。","pi":"开头的 h 不发音，所以 l'hiver 要省音，同时 r 要真的读出来，不能吞掉。","et":"来自拉丁语 hibernum（冬天的），hiems 是「冬天」。同源：hiberner（冬眠）。","ex":[["Il fait froid en hiver.","冬天很冷。"],["J'adore les vacances d'hiver.","我超爱寒假。"]],"co":[["en hiver","在冬天"],["un hiver froid / doux","寒冷 / 温和的冬天"],["les sports d'hiver","冬季运动"]],"sy":[["saison","courant","季节"],["l'été","courant","反义词：夏天"]],"fq":"极高频。","me":"hiver：h 是隐形的，听到的是「伊-弗尔」。","tr":{"zh":"冬天山上下雪。","fr":"En hiver, il neige dans les montagnes.","alt":"L'hiver, il y a de la neige en montagne.","note":"h 哑音，冠词用 l'：l'hiver，不是 le hiver。"}},
 "Le printemps": {"pos":"n.m. 阳性名词，复数 printemps（单复数同形）","s":"春天，3 月到 5 月左右。口语里还有「新开始、青春」的意思：le printemps de la vie。","ipa":"[pʁɛ̃.tɑ̃]","ph":"pr [pʁ]；in [ɛ̃]；em+p 的 emp 读 [ɑ̃]，结尾 s 不发。","pi":"春天比较特殊：不是 en printemps，而是 au printemps。结尾的 ps 不发音。","et":"来自拉丁语 primum tempus，字面是「第一个时节」。","ex":[["Il y a des fleurs au printemps.","春天有花开。"],["Le printemps est ma saison préférée.","春天是我最喜欢的季节。"]],"co":[["au printemps","在春天"],["le printemps dernier / prochain","去年春天 / 明年春天"],["le retour du printemps","春天回来了"]],"sy":[["saison","courant","季节"],["l'hiver","courant","前一个季节"]],"fq":"极高频。","me":"prin-temps = prime time：春天是「第一个时节」。","tr":{"zh":"春天树木长出新叶。","fr":"Au printemps, les arbres ont de nouvelles feuilles.","alt":"Au printemps, les arbres reverdissent.","note":"只有春天用 au：au printemps；其他三季用 en。"}},
 "Un ami": {"pos":"n.m. 阳性名词，复数 amis；阴性 une amie（读音相同）","s":"朋友。男性 un ami，女性 une amie，读音一样，只靠冠词和拼写区分。注意 petit ami / petite amie 不是「小朋友」，而是男友 / 女友。","ipa":"[a.mi]","ph":"a [a]；m [m]；i [i]。un ami 要连读：[œ̃.na.mi]。","pi":"un ami 的 n 要连读到 a 上：[œ̃.na.mi]。别忘了阴性 amie 读音完全相同。","et":"来自拉丁语 amicus（朋友），同源 aimer（爱）、amour。","ex":[["C'est un bon ami.","他是一个好朋友。"],["Mon amie s'appelle Léa.","我的朋友（女）叫蕾雅。"]],"co":[["un ami d'enfance","儿时的朋友"],["un petit ami / une petite amie","男朋友 / 女朋友"],["un ami proche","亲密的朋友"],["se faire des amis","交朋友"]],"sy":[["copain / copine","familier","朋友；也可指男朋友 / 女朋友"],["camarade","courant","同学、同伴"],["pote","familier","哥们儿"]],"fq":"极高频。","me":"ami 里有 ami(e)：像「阿咪」，是个好朋友。","tr":{"zh":"我有一个朋友住在巴黎。","fr":"J'ai un ami qui habite à Paris.","alt":"Un pote à moi habite à Paris.","note":"un ami 需要连读 n；petit ami = 男朋友，不是小朋友。"}},
 "Un an": {"pos":"n.m. 阳性名词，复数 ans","s":"年；岁。数年数、说年龄时用 an(s)：J'ai vingt ans。强调这一年「过得怎样」则用 année。","ipa":"[ɑ̃]","ph":"an [ɑ̃]，鼻化元音，n 不单独发音；ans 的 s 不发音。后面是元音时连读：un an [œ̃.nɑ̃]。","pi":"an 与 en 读音一样 [ɑ̃]。说年龄必须用 avoir，不能用 être：J'ai 10 ans。","et":"来自拉丁语 annus（年）。同源：anniversaire，annuel。","ex":[["Elle a dix ans.","她十岁。"],["Je vais en France pour un an.","我要去法国待一年。"]],"co":[["avoir … ans","……岁"],["par an","每年"],["le Nouvel An","新年"],["tous les ans","每年"]],"sy":[["année","courant","强调一整年的时长"],["âge","courant","年龄"]],"fq":"极高频。","me":"an = 「昂」：一年一年地数。","tr":{"zh":"我在法国住过一年。","fr":"J'ai habité en France pendant un an.","alt":"J'ai vécu un an en France.","note":"说年龄用 avoir + ans，不用 être。"}},
 "Un chat": {"pos":"n.m. 阳性名词，复数 chats；阴性 une chatte","s":"猫。泛指猫时用 un chat；特指母猫才用 une chatte（该词在口语里另有粗俗意思，日常最好说 un chat）。","ipa":"[ʃa]","ph":"ch [ʃ]（舌头后缩，嘴唇微圆，像「诗」）；a [a]；t 不发音。","pi":"结尾 t 不发音：不是「chat」读 [ʃat]，而是 [ʃa]。复数 chats 也读 [ʃa]。","et":"来自晚期拉丁语 cattus。chaton = 小猫。","ex":[["Le chat dort.","猫在睡觉。"],["Elle a deux chats noirs.","她有两只黑猫。"]],"co":[["un chat noir","黑猫"],["une chatte","母猫"],["un chaton","小猫"],["avoir un chat dans la gorge","嗓子哑了"]],"sy":[["minou","familier","猫咪（亲昵）"],["félin","soutenu","猫科动物"]],"fq":"极高频。","me":"chat 读「沙」：猫一出现就沙沙作响。","tr":{"zh":"我有一只整天睡觉的猫。","fr":"J'ai un chat qui dort toute la journée.","alt":"Mon chat dort toute la journée.","note":"chat 是阳性名词；普通场合一般只说 un chat。"}},
 "Un chien": {"pos":"n.m. 阳性名词，复数 chiens；阴性 une chienne","s":"狗。小狗是 un chiot。比喻里常见：un temps de chien（糟糕的天气）；avoir du chien（有魅力）。","ipa":"[ʃjɛ̃]","ph":"ch [ʃ]；ie 合起来是 [jɛ̃]（后面带 n，鼻化）；结尾 n 不单独发音。","pi":"ien 读 [jɛ̃]，不是「ien」两个音；复数 s 不发音。","et":"来自拉丁语 canis（狗）。同源：canin（狗的），chenil（狗窝）。","ex":[["Le chien est petit.","这条狗很小。"],["Mon chien aime jouer dans le jardin.","我的狗喜欢在花园里玩。"]],"co":[["un chien de garde","看门狗"],["promener le chien","遛狗"],["une chienne","母狗"],["un chiot","小狗"]],"sy":[["toutou","familier","小狗狗（儿语）"],["clebs / cabot","familier","狗（口语）"]],"fq":"极高频。","me":"chien：像「香」 + 狗叫，一声「汪」。","tr":{"zh":"我每天早上遛狗。","fr":"Je promène mon chien tous les matins.","alt":"Tous les matins, je sors mon chien.","note":"promener le chien 是「遛狗」；chien 的阴性是 chienne。"}},
 "Un enfant": {"pos":"n.m. 阳性名词，复数 enfants；也可指女孩：une enfant / un enfant","s":"孩子；子女。男孩女孩都可叫 enfant，可以用 un 或 une。也指「儿子 / 女儿」：mes enfants = 我的孩子们。","ipa":"[ɑ̃.fɑ̃]","ph":"en [ɑ̃]；f [f]；ant [ɑ̃]，两个鼻化元音；t 不发音。les enfants 连读：[le.zɑ̃.fɑ̃]。","pi":"两个鼻化元音相同。les enfants 要连读成 z：[le.zɑ̃.fɑ̃]。","et":"来自拉丁语 infans（不会说话的），in-（不）+ fari（说）。","ex":[["Il a un enfant.","他有一个孩子。"],["Les enfants jouent dans la cour.","孩子们在院子里玩。"]],"co":[["un enfant unique","独生子女"],["un petit enfant","小孩"],["un enfant de dix ans","十岁的孩子"],["avoir un enfant","有一个孩子"]],"sy":[["gamin / gamine","familier","小孩（口语）"],["gosse","familier","孩子（口语）"],["bébé","courant","婴儿"]],"fq":"极高频。","me":"en-fant：英语 infant 的近亲。","tr":{"zh":"他们有两个孩子。","fr":"Ils ont deux enfants.","alt":"Eux, ils ont deux gamins.","note":"enfant 男女同形：un enfant / une enfant。"}},
 "Un euro": {"pos":"n.m. 阳性名词，复数 euros","s":"欧元。数字后 euro 要加 s：dix euros。价格可以说 Ça coûte / Ça fait… euros。","ipa":"[ø.ʁo]","ph":"eu [ø]（嘴唇圆，舌位在 é 的位置，像「欸」和「呜」之间）；r [ʁ]；o [o]。两音节：eu-ro。","pi":"eu [ø] 不是「尤」；r 在喉咙。dix euros 连读：[di.zø.ʁo]。","et":"来自 Europe（欧洲），拉丁语 Europa，源自希腊语 Eurōpē。","ex":[["Le café coûte un euro.","咖啡一欧元。"],["Ça fait dix euros.","一共十欧元。"]],"co":[["un euro","一欧元"],["cinq euros","五欧元"],["combien d'euros","多少欧元"],["des centimes d'euro","欧分"]],"sy":[["centime","courant","欧分（百分之一欧元）"],["balle","familier","（口语）一欧元"]],"fq":"极高频，买东西必用。","me":"euro：eu 的口型像吹口哨，「欧」。","tr":{"zh":"这本书十五欧元。","fr":"Ce livre coûte quinze euros.","alt":"Ce bouquin fait quinze euros.","note":"euro 数字大于 1 要加 s；价格常说 ça fait…euros。"}},
 "Un jour": {"pos":"n.m. 阳性名词，复数 jours","s":"天；白天（对 nuit）。数「天」用 jour(s)：trois jours。强调一整天的过程用 journée：bonne journée。","ipa":"[ʒuʁ]","ph":"j [ʒ]，像「日」；ou [u]；r [ʁ] 喉音。","pi":"j 是 [ʒ]，不是 [dʒ]。jour 与 journée 区分：jour = 数天数；journée = 一天里发生的事。","et":"来自晚期拉丁语 diurnum（白天的）。同源：journal，bonjour。","ex":[["C'est un beau jour.","这是美好的一天。"],["Il pleut tous les jours.","每天都下雨。"]],"co":[["tous les jours","每天"],["un jour","有一天"],["par jour","每天（每日）"],["le jour de l'an","元旦"]],"sy":[["journée","courant","一整天（强调时长、过程）"],["date","courant","日期"]],"fq":"极高频。","me":"jour 读「祖」，再带喉音：一天一天过。","tr":{"zh":"我一周工作六天。","fr":"Je travaille six jours par semaine.","alt":"Je bosse six jours par semaine.","note":"数天数用 jour；一整天用 journée。"}},
 "Un mois": {"pos":"n.m. 阳性名词，复数 mois（单复数同形）","s":"月；一个月。月份名在法语里小写：janvier, février。说「在五月」：en mai 或 au mois de mai。","ipa":"[mwa]","ph":"m [m]；oi [wa]；s 不发音，所以 mois 只有一个音节。","pi":"oi 读 [wa]，不是「奥伊」；s 不发音。mois / moi 读音几乎一样：mois [mwa]，moi [mwa]。","et":"来自拉丁语 mensis（月）。","ex":[["Février est un mois court.","二月是个很短的月份。"],["Je pars en voyage pour un mois.","我要去旅行一个月。"]],"co":[["ce mois-ci","这个月"],["le mois dernier / prochain","上个月 / 下个月"],["par mois","每月"],["au mois de mai","在五月"]],"sy":[["semaine","courant","比月短的单位：星期"],["quinze jours","courant","两周（字面：十五天）"]],"fq":"极高频。","me":"mois 与 moi 同音 [mwa]：s 不出声。","tr":{"zh":"我要去度假一个月。","fr":"Je pars en vacances pour un mois.","alt":"Je suis en vacances tout un mois.","note":"月份名小写；在某月用 en 或 au mois de。"}},
 "La bise": {"pos":"n.f. 阴性名词，复数 bises","s":"贴面吻：面颊轻碰、嘴里发出轻吻声，是法国朋友、家人见面的礼节。次数因地区不同（2 到 4 下）。另一个意思：la bise = 干冷的北风。","ipa":"[biz]","ph":"b [b]；i [i]；s 在元音间读 [z]；结尾 e 不发音：[biz]。","pi":"s 读 [z]，不是 [s]。别和 baiser 混淆：现代法语里 baiser 做动词是粗俗的「做爱」。","et":"贴面吻的词源不确定。北风意义的 bise 来自日耳曼语（法兰克语）。","ex":[["On fait la bise en France.","在法国人们互相贴面吻。"],["Je fais la bise à mes amis.","我跟朋友们贴面打招呼。"]],"co":[["faire la bise (à quelqu'un)","贴面吻（问候）"],["se faire la bise","互相贴面吻"],["grosses bises","（信末）亲亲你"],["la bise (vent)","北风"]],"sy":[["bisou","familier","小亲吻"],["poignée de main","courant","握手"],["embrasser","courant","亲吻；拥抱"]],"fq":"常用，日常问候。","me":"bise 读 [biz]：贴脸时「必兹」一声。","tr":{"zh":"法国人见面时互相贴面吻。","fr":"Les Français se font la bise quand ils se voient.","alt":"Entre amis, on se fait la bise.","note":"faire la bise à qqn 是固定搭配；不要用 baiser 表示亲吻。"}},
 "Une année": {"pos":"n.f. 阴性名词，复数 années","s":"一年；年度。强调这一年的时间跨度或经历：toute l'année, une bonne année。数数、年龄用 an(s)：deux ans。","ipa":"[a.ne]","ph":"a [a]；nn 读一个 [n]；ée 读 [e]：[a.ne]，两个音节。","pi":"année 里 nn 只读一个 n，ée 读 [e]，结尾的 e 不发音。别和 an 混用：J'ai vingt ans，不是 années。","et":"来自拉丁语 annus（年）+ 后缀 -ée，与 jour/journée 一样的构词。","ex":[["C'est une bonne année.","这是美好的一年。"],["Toute l'année, il fait beau ici.","这里全年天气都好。"]],"co":[["toute l'année","全年"],["bonne année !","新年快乐！"],["l'année dernière / prochaine","去年 / 明年"],["une année scolaire","学年"]],"sy":[["an","courant","年（用于数数、年龄）"],["annuel","courant","每年的（形容词）"]],"fq":"高频。","me":"an → année：多了 -ée，像 jour → journée，强调「整个一年」。","tr":{"zh":"今年我要学法语。","fr":"Cette année, je vais apprendre le français.","alt":"Cette année, je me mets au français.","note":"年龄用 an(s)；整个一年、一年的经历用 année。"}},
 "Une baguette": {"pos":"n.f. 阴性名词，复数 baguettes","s":"法棍面包，也是「小棍子」。同形还有：筷子（les baguettes）、魔杖（baguette magique）、指挥棒。","ipa":"[ba.gɛt]","ph":"ba [ba]；gue 里的 u 不发音，gu = [g]；ette = [ɛt]，t 要发。","pi":"gu 读 [g]，u 不发音。ette 的 t 要读出来。一个 baguette = 一根，也用于筷子复数。","et":"来自意大利语 bacchetta（小棍），源自拉丁语 baculum（棍）。","ex":[["J'achète une baguette.","我买一根法棍。"],["Elle mange une baguette avec du fromage.","她就着奶酪吃法棍。"]],"co":[["une baguette tradition","传统法棍"],["une baguette magique","魔杖"],["des baguettes (chinoises)","筷子"],["une baguette de pain","一根法棍"]],"sy":[["pain","courant","面包（泛指）"],["flûte","courant","更细的法棍"]],"fq":"高频。","me":"baguette = 一根「小棍」，法棍就是长长的小棍。","tr":{"zh":"我去面包店买一根法棍。","fr":"Je vais à la boulangerie acheter une baguette.","alt":"Je file à la boulangerie chercher une baguette.","note":"baguette 也指筷子：les baguettes。"}},
 "Une date": {"pos":"n.f. 阴性名词，复数 dates","s":"日期；年月日。问「几号」：Quelle est la date ? 或 On est le combien ? 注意：date 不是「约会」，约会用 rendez-vous。","ipa":"[dat]","ph":"d [d]；a [a]；t 要读：[dat]。一个音节，短促。","pi":"结尾 t 读出来 [dat]。英语 date（约会 / 椰枣）在法语里分别是 rendez-vous 和 datte。","et":"来自拉丁语 data（给出的），写在信末的「给出的日期」。","ex":[["Quelle est la date d'aujourd'hui ?","今天是几号？"],["Écris la date en haut de la page.","在页面上方写日期。"]],"co":[["la date de naissance","出生日期"],["à quelle date ?","哪一天？"],["une date limite","截止日期"],["la date d'aujourd'hui","今天的日期"]],"sy":[["jour","courant","一天（具体某一天）"],["rendez-vous","courant","约会、预约（不是 date）"]],"fq":"高频。","me":"date：写在信末的日子。","tr":{"zh":"你的生日是几号？","fr":"Quelle est la date de ton anniversaire ?","alt":"C'est quand, ton anniversaire ?","note":"问日期：Quelle est la date ? / On est le combien ?"}},
 "Une saison": {"pos":"n.f. 阴性名词，复数 saisons","s":"季节；时令。也指某事的最佳时期：la saison des fraises（草莓季）、la saison touristique。","ipa":"[sɛ.zɔ̃]","ph":"s [s]；ai [ɛ]；s 在元音之间读 [z]；on [ɔ̃] 鼻化。","pi":"中间的 s 读 [z]，不是 [s]；ai 读 [ɛ]，不是「爱」。on 鼻化，n 不发音。","et":"来自拉丁语 sationem（播种，种植时节）。","ex":[["Ma saison préférée est l'été.","我最喜欢的季节是夏天。"],["Il y a quatre saisons dans l'année.","一年有四个季节。"]],"co":[["la saison des pluies","雨季"],["haute / basse saison","旺季 / 淡季"],["les fruits de saison","应季水果"],["de saison","应季的"]],"sy":[["période","courant","一段时间"],["temps","courant","时节；天气"]],"fq":"高频。","me":"saison：「sé-zon」，像 season 一样只是拼法不同。","tr":{"zh":"你最喜欢哪个季节？","fr":"Quelle est ta saison préférée ?","alt":"C'est quoi, ta saison préférée ?","note":"应季：de saison。旺季 / 淡季：haute / basse saison。"}},
 "Une semaine": {"pos":"n.f. 阴性名词，复数 semaines","s":"星期；周。en semaine = 在工作日（周一到周五）。fin de semaine 指周末前后。「一星期」也可说 huit jours，两周说 quinze jours。","ipa":"[sə.mɛn]","ph":"se [sə]（e 很轻）；mai 读 [mɛ]；ne 里的 n 读 [n]，结尾 e 不发音：[sə.mɛn]。","pi":"ai 读 [mɛ]；最后的 ne 轻轻带出 n。semaine 和 semer（播种）发音不同。","et":"来自晚期拉丁语 septimana（七天的），septem = 七。","ex":[["Il y a sept jours dans une semaine.","一个星期有七天。"],["À la semaine prochaine !","下周见！"]],"co":[["cette semaine","这周"],["la semaine dernière / prochaine","上周 / 下周"],["toute la semaine","整个星期"],["en semaine","工作日"]],"sy":[["huit jours","courant","一星期（字面：八天）"],["quinze jours","courant","两周"]],"fq":"高频。","me":"semaine ← septem：七天。","tr":{"zh":"我整个星期，从周一到周五都工作。","fr":"Je travaille du lundi au vendredi toute la semaine.","alt":"Je bosse toute la semaine, du lundi au vendredi.","note":"en semaine = 工作日；huit jours = 一周。"}},
 "L'âge": {"pos":"n.m. 阳性名词，复数 âges","s":"年龄；年纪；时代。问年龄：Quel âge as-tu ? 回答：J'ai … ans。注意是阳性：l'âge，不是 la âge。","ipa":"[ɑʒ]","ph":"â [ɑ]（比 a 更靠后、更长）；ge [ʒ]；结尾 e 不发音：[ɑʒ]。","pi":"一个音节 [ɑʒ]。â 上面的帽子表示丢掉的字母（古法语 aage 有两个 a）。说年龄用 avoir：J'ai trente ans。","et":"来自古法语 aage，源自晚期拉丁语 aetaticum。英语 age 借自法语。","ex":[["Quel est ton âge ?","你多大了？"],["Il a l'âge de ma sœur.","他和我姐姐一样大。"]],"co":[["Quel âge as-tu ?","你几岁？"],["à mon âge","在我这个年纪"],["l'âge adulte","成年"],["un enfant en bas âge","幼儿"]],"sy":[["an","courant","岁（数年）"],["années","courant","岁月"]],"fq":"高频。","me":"âge ← aage：帽子替代了一个丢掉的 a。","tr":{"zh":"你哥哥几岁？","fr":"Quel âge a ton frère ?","alt":"Il a quel âge, ton frère ?","note":"年龄不用 être 而用 avoir + ans；âge 是阳性。"}},
 "Avoir": {"pos":"v. 动词，不规则：j'ai, tu as, il a, nous avons, vous avez, ils ont；助动词：avoir（passé composé 的主要助动词）","s":"有；拥有。还用于许多固定表达：avoir faim（饿）、avoir 20 ans（20 岁）、il y a（有）。同时是 passé composé 的助动词：j'ai mangé。","ipa":"[a.vwaʁ]","ph":"a [a]；v [v]；oi [wa]；r [ʁ]：[a.vwaʁ]。ils ont 连读：[il.zɔ̃]；j'ai 读 [ʒe]。","pi":"j'ai [ʒe]（≈ 英语 jay），tu as [ty.a]。ils ont [il.zɔ̃] 与 ils sont [il.sɔ̃] 只差 z / s。","et":"来自拉丁语 habere（有）。","ex":[["J'ai deux enfants.","我有两个孩子。"],["Il a vingt ans.","他二十岁。"]],"co":[["avoir faim / soif / froid / chaud","饿 / 渴 / 冷 / 热"],["avoir … ans","……岁"],["avoir besoin de","需要"],["il y a","有；存在"]],"sy":[["posséder","soutenu","拥有（书面）"],["être","courant","是（另一个最重要的助动词）"]],"fq":"极高频，必须掌握。","me":"avoir = 「阿-瓦」：我有，也能有岁数、有饥饿。","tr":{"zh":"我们在乡下有一栋房子。","fr":"Nous avons une maison à la campagne.","alt":"On a une maison à la campagne.","note":"avoir 用来说年龄、饿、渴、冷、热；不要用 être。"}},
 "Être": {"pos":"v. 动词，不规则：je suis, tu es, il est, nous sommes, vous êtes, ils sont；助动词：être（用于某些位移动词和代词式动词）","s":"是；在；处于某种状态。连接主语与名词、形容词、地点：Je suis fatigué。职业一般不加冠词：Il est médecin。也是 passé composé 的助动词，用于 aller, venir 等。","ipa":"[ɛtʁ]","ph":"ê [ɛ]；tre [tʁ]：[ɛtʁ]，一个音节。je suis [ʒə.sɥi]；vous êtes [vu.zɛt]。","pi":"est / et 分别读 [ɛ] 和 [e]，注意区分：Il est là（他在）vs et（和）。vous êtes 要连读：[vu.zɛt]。","et":"来自古法语 estre，源自拉丁语 essere（esse，是）。","ex":[["Je suis français.","我是法国人。"],["Nous sommes en classe.","我们在教室里。"]],"co":[["être à l'heure","准时"],["être d'accord","同意"],["être en train de","正在做"],["c'est","这是"]],"sy":[["exister","soutenu","存在"],["se trouver","courant","位于"]],"fq":"极高频，必须掌握。","me":"être：最基本的「是」；ê 上的帽子是丢掉的 s（estre）。","tr":{"zh":"我是学生，我哥哥是医生。","fr":"Je suis étudiant et mon frère est médecin.","alt":"Moi, je suis étudiant ; mon frère, il est médecin.","note":"职业前不加冠词：Il est médecin。"}},
 "S'appeler": {"pos":"v. 动词（代词式，第一组）：je m'appelle, tu t'appelles, il s'appelle, nous nous appelons, vous vous appelez, ils s'appellent","s":"名叫；字面是「称呼自己」。介绍名字：Je m'appelle… 。提问：Comment tu t'appelles ? / Comment vous appelez-vous ?","ipa":"[sa.ple]","ph":"s'ap-pe-ler：[sa.ple]；je m'appelle [ʒə.ma.pɛl]；pp 读一个 [p]；ll 读一个 [l]。","pi":"不能说 je suis appelé，要用代词式：je m'appelle。单数和 ils 形式双写 l（appelle），nous / vous 形式只有一个 l（appelons, appelez）。","et":"来自拉丁语 appellare（呼唤）。同源：appel（呼叫），appellation。","ex":[["Je m'appelle Thomas. Tu t'appelles comment ?","我叫托马斯。你叫什么名字？"],["Elle s'appelle Marie.","她叫玛丽。"]],"co":[["Comment tu t'appelles ?","你叫什么名字？"],["Comment vous appelez-vous ?","您叫什么名字？"],["Je m'appelle…","我叫……"],["appeler quelqu'un","叫（某人）；给……打电话"]],"sy":[["se nommer","soutenu","名叫"],["être prénommé","soutenu","名叫（名字）"]],"fq":"极高频，介绍时第一句。","me":"s'appeler = 「称呼自己」：je m'appelle 就是「我叫……」。","tr":{"zh":"我叫朱莉，我哥哥叫保罗。","fr":"Je m'appelle Julie et mon frère s'appelle Paul.","alt":"Moi, c'est Julie, et mon frère, c'est Paul.","note":"代词式动词：我 = je m'appelle，你 = tu t'appelles。"}},
 "Le premier / La première": {"pos":"adj. 形容词，阳性 premier，阴性 première；复数 premiers / premières","s":"第一个；第一的；最先的。也可作名词：le premier（男）/ la première（女）。日期：只有 1 号用序数 le premier mai，其余用基数 le deux mai。","ipa":"[pʁə.mje] / [pʁə.mjɛʁ]","ph":"premier [pʁə.mje]；première [pʁə.mjɛʁ]；ier 读 [je]；ière 读 [jɛʁ]（阴性末尾发 r）。","pi":"阳性结尾 r 不发音，阴性结尾 r 要发音：premier [e] vs première [ɛʁ]。法国的 premier étage = 二楼。","et":"来自拉丁语 primarius（第一等的），primus（第一）。","ex":[["C'est le premier jour du mois.","这是这个月的第一天。"],["Elle est la première de la classe.","她是班上的第一名。"]],"co":[["le premier janvier","一月一日"],["au premier étage","在二楼（法国的一楼是 rez-de-chaussée）"],["en premier","首先"],["le Premier ministre","总理"]],"sy":[["dernier / dernière","courant","反义词：最后的"],["initial","soutenu","最初的"]],"fq":"极高频。","me":"prem-ier：英语 premier、prime，一样的词根。","tr":{"zh":"这是我第一次来巴黎。","fr":"C'est la première fois que je viens à Paris.","alt":"C'est ma première fois à Paris.","note":"阴性 première 与阳性发音不同：r 要读。le 1er = le premier。"}},
 "Aujourd'hui": {"pos":"adv. 副词","s":"今天；如今。字面是「au jour d'hui」，hui 是古法语的「今天」。也可指「现在这个时代」。写作 aujourd'hui，一个词，中间有撇号。","ipa":"[o.ʒuʁ.dɥi]","ph":"au [o]；jour [ʒuʁ]；d'hui 读 [dɥi]：o.ʒuʁ.dɥi。","pi":"d'hui 读 [dɥi]，ui 是一个滑音，不是「迪伊」。拼写一定要写撇号：aujourd'hui。","et":"由 au + jour + d' + hui（古法语「今天」，来自拉丁语 hodie）组成，字面「在这一天的今天」。","ex":[["Aujourd'hui, il fait beau.","今天天气很好。"],["Qu'est-ce que tu fais aujourd'hui ?","你今天做什么？"]],"co":[["aujourd'hui même","就在今天"],["jusqu'à aujourd'hui","直到今天"],["d'aujourd'hui","今天的"],["de nos jours","如今"]],"sy":[["ce jour","soutenu","今天（书面）"],["maintenant","courant","现在"]],"fq":"极高频。","me":"aujourd'hui：au jour d'hui，今天就是「在这一天」。","tr":{"zh":"今天我很累。","fr":"Aujourd'hui, je suis très fatigué.","alt":"Aujourd'hui, je suis crevé.","note":"aujourd'hui 是一个词，永远写撇号。"}},
 "Demain": {"pos":"adv. 副词；也可作阳性名词：le demain","s":"明天。常用于约定：À demain ! 还有「未来」的意思：penser à demain。","ipa":"[də.mɛ̃]","ph":"de [də]；main 读 [mɛ̃]，鼻化；两音节 [də.mɛ̃]。","pi":"main 的 ain 是鼻化 [ɛ̃]，不是「麦因」。demain 和 main（手）后半部分相同。","et":"来自拉丁语 de mane（从早晨起）。main 来自拉丁语 mane（早晨）。","ex":[["Demain, je vais au cinéma.","明天我要去看电影。"],["À demain !","明天见！"]],"co":[["à demain","明天见"],["demain matin / soir","明天早上 / 晚上"],["après-demain","后天"],["le lendemain","第二天"]],"sy":[["hier","courant","反义词：昨天"],["bientôt","courant","很快"]],"fq":"极高频。","me":"demain：de + main，手里握着明天。","tr":{"zh":"明天我们去海边。","fr":"Demain, nous allons à la plage.","alt":"Demain, on va à la plage.","note":"demain + 将来时 / 近将来：Demain, je vais…"}},
 "Hier": {"pos":"adv. 副词","s":"昨天。用于过去：hier + passé composé。hier soir = 昨晚。","ipa":"[jɛʁ]","ph":"h 不发音；ie 读 [jɛ]；r 要读：[jɛʁ]，一个音节。","pi":"h 是哑音，不要读出来。r 要读出来：[jɛʁ]，不是「yé」。","et":"来自拉丁语 heri（昨天），与英语 yesterday 同属一个古老词根。","ex":[["Hier, j'ai mangé une pomme.","昨天我吃了一个苹果。"],["Hier soir, nous avons regardé un film.","昨晚我们看了一部电影。"]],"co":[["hier soir","昨晚"],["hier matin","昨天早上"],["avant-hier","前天"],["depuis hier","从昨天起"]],"sy":[["demain","courant","反义词：明天"],["avant-hier","courant","前天"]],"fq":"极高频。","me":"hier：[jɛʁ]，像「耶」，昨天是过去了。","tr":{"zh":"昨天我工作到八点。","fr":"Hier, j'ai travaillé jusqu'à huit heures.","alt":"Hier, j'ai bossé jusqu'à huit heures.","note":"hier + passé composé；hier soir 是「昨晚」。"}},
 "À bientôt": {"pos":"loc. 短语：à + bientôt（bien + tôt）","s":"回头见；很快再见。用于不确定具体时间但很快会再见时。bientôt 单独做副词，意思是「很快」。具体某一天用 à demain，同一天内用 à tout à l'heure。","ipa":"[a.bjɛ̃.to]","ph":"à [a]；bien [bjɛ̃]；tôt [to]，ô 读 [o]：[a.bjɛ̃.to]。","pi":"bien 读 [bjɛ̃]，鼻化；tôt 的 t 不发音，是 [to]。别忘了 ô 上的帽子。","et":"由 bien（很）+ tôt（早）构成，字面「很早」→「很快」。","ex":[["À bientôt, j'espère.","回头见，希望如此。"],["À très bientôt !","很快再见！"]],"co":[["à très bientôt","很快再见"],["à bientôt !","回头见"],["c'est pour bientôt","快了"],["à tout à l'heure","待会儿见"]],"sy":[["à demain","courant","明天见"],["à plus","familier","回见（短信、朋友）"],["à tout à l'heure","courant","待会儿见（当天）"]],"fq":"高频，告别语。","me":"bientôt = bien + tôt：很早就会再见。","tr":{"zh":"回头见，周末愉快！","fr":"À bientôt, passe un bon week-end !","alt":"À bientôt, bon week-end !","note":"à bientôt 没有具体时间；到明天用 à demain。"}},
 "Au revoir": {"pos":"loc. 短语，也作阳性名词：un au revoir","s":"再见。字面是「直到再次相见」（revoir = 再看到）。进店、离开时对店员也要说 Au revoir。比 adieu 轻，adieu 是永别。","ipa":"[o.ʁə.vwaʁ]","ph":"au [o]；re [ʁə]；voi [vwa]；r [ʁ]：[o.ʁə.vwaʁ]。re 里 e 很轻。","pi":"revoir 里 oi 读 [wa]，r 喉音。别写成 aurevoir（要分开写）。也别用 adieu，那太沉重。","et":"由 au + revoir 构成：re-（再次）+ voir（看见，拉丁语 videre）。","ex":[["Au revoir, bonne soirée !","再见，晚上愉快！"],["Il dit au revoir à ses amis.","他跟朋友们说再见。"]],"co":[["dire au revoir (à quelqu'un)","跟某人说再见"],["un au revoir","一次告别"],["Au revoir et merci","再见，谢谢"],["à la prochaine","下次见"]],"sy":[["salut","familier","嗨；拜拜"],["adieu","soutenu","永别（不再见）"],["ciao","familier","拜（来自意大利语）"]],"fq":"极高频。","me":"au revoir = 「再见」：直到我们再看见彼此。","tr":{"zh":"再见，明天见！","fr":"Au revoir, et à demain !","alt":"Salut, à demain !","note":"Au revoir 是通用的告别语；朋友间用 Salut。"}},
 "Bonjour": {"pos":"loc. 短语，也作阳性名词：un bonjour","s":"你好；早上好。白天（直到傍晚）都能用；晚上用 bonsoir。法国进商店、见邻居、上公交，都应先说 Bonjour。是 bon + jour，不是 bonne jour。","ipa":"[bɔ̃.ʒuʁ]","ph":"bon [bɔ̃]，鼻化；jour [ʒuʁ]；整词 [bɔ̃.ʒuʁ]。","pi":"bon 的 n 不发音，是鼻化元音；j 读 [ʒ]。不要说 bonne jour（jour 是阳性）。","et":"由 bon（好）+ jour（天）构成，字面「好天」。","ex":[["Bonjour, comment tu t'appelles ?","你好，你叫什么名字？"],["Bonjour madame, un café, s'il vous plaît.","您好，女士，请来一杯咖啡。"]],"co":[["dire bonjour","打招呼"],["bonjour tout le monde","大家好"],["bonjour à…","向……问好"],["un grand bonjour","热情问候"]],"sy":[["salut","familier","嗨"],["coucou","familier","嗨（亲昵）"],["bonsoir","courant","晚上好"]],"fq":"极高频。","me":"bonjour：好天，每天第一句。","tr":{"zh":"您好先生，我想要一杯咖啡。","fr":"Bonjour monsieur, je voudrais un café.","alt":"Bonjour, un café, s'il vous plaît.","note":"白天说 Bonjour；晚上说 Bonsoir。"}},
 "Bonne journée": {"pos":"loc. 短语（journée 为阴性，所以用 bonne）","s":"祝你今天愉快。告别时对店员、同事、邻居说。回答：Vous de même / Toi aussi / Merci, à vous aussi。","ipa":"[bɔn.ʒuʁ.ne]","ph":"bonne [bɔn]（n 要发）；jour [ʒuʁ]；née [ne]：[bɔn.ʒuʁ.ne]。","pi":"bonne 的 nn 发 [n]，和 bon [bɔ̃] 不同。journée 是阴性，所以 bonne，不是 bon。jour 与 journée 不要混用。","et":"由 bonne（好）+ journée（一整天）构成；journée = jour + -ée。","ex":[["Merci, bonne journée à toi aussi !","谢谢，你也祝你今天愉快！"],["Bonne journée, madame !","祝您今天愉快，女士！"]],"co":[["bonne journée à toi / vous","祝你 / 您今天愉快"],["Bonne soirée !","晚上愉快！"],["Bon week-end !","周末愉快！"],["Vous de même","您也一样"]],"sy":[["bonne soirée","courant","晚上愉快"],["bonne semaine","courant","一周愉快"]],"fq":"高频，告别语。","me":"bonne journée：给对方一整天的祝福。","tr":{"zh":"再见，祝你今天愉快！","fr":"Au revoir, bonne journée !","alt":"Salut, bonne journée !","note":"journée 阴性 → bonne。bon jour 不对。"}},
 "Bonsoir": {"pos":"loc. 短语，也作阳性名词：un bonsoir","s":"晚上好。傍晚（大约 18 点以后）见面或告别都可说 Bonsoir，既是「你好」也是「再见」。睡前才说 Bonne nuit。","ipa":"[bɔ̃.swaʁ]","ph":"bon [bɔ̃]；soir [swaʁ]：[bɔ̃.swaʁ]；oi 读 [wa]。","pi":"oi 读 [wa]，r 喉音。别把 bonsoir 当作睡前用语：睡前是 bonne nuit。","et":"由 bon + soir（傍晚，拉丁语 sero）构成。","ex":[["Bonsoir, à demain.","晚上好，明天见。"],["Bonsoir madame, une table pour deux ?","晚上好，女士，两位吗？"]],"co":[["dire bonsoir","说晚上好"],["bonsoir tout le monde","大家晚上好"],["Bonne soirée !","晚上愉快！"],["Bonne nuit","晚安（睡觉前）"]],"sy":[["bonjour","courant","白天的问候"],["salut","familier","嗨"],["bonne nuit","courant","晚安"]],"fq":"极高频。","me":"bonsoir：傍晚的「好」；睡觉才说 bonne nuit。","tr":{"zh":"晚上好，我想要一张两人的桌子。","fr":"Bonsoir, je voudrais une table pour deux.","alt":"Bonsoir, une table pour deux, s'il vous plaît.","note":"Bonsoir 见面、告别都能用；Bonne nuit 只用于睡前。"}},
 "Ça va ? / Ça va.": {"pos":"loc. 短语：ça + va（aller 的变位）","s":"「你好吗？」和「我很好」用同一个短语，靠语调区分：上扬是问，下降是答。也可用来问「行不行？」：Ça va comme ça ? 正式场合换成 Comment allez-vous ?","ipa":"[sa.va]","ph":"ç 读 [s]；a [a]；va [va]：[sa.va]。","pi":"ç（带小钩）读 [s]，不是 [k]。问句语调上扬，答句下降。正式场合换成 Comment allez-vous ?","et":"ça 是 cela 的口语缩写（ce + là）；va 是动词 aller 的变位，来自拉丁语 vadere（走）。","ex":[["Ça va bien, merci.","我很好，谢谢。"],["Salut, ça va ? Oui, ça va.","嗨，你好吗？嗯，我很好。"]],"co":[["Ça va bien / mal","很好 / 不好"],["Comment ça va ?","你好吗？"],["Pas mal / comme ci, comme ça","还行 / 一般般"],["Ça va ?","可以吗？行吗？"]],"sy":[["Comment allez-vous ?","soutenu","您好吗？（正式）"],["Quoi de neuf ?","familier","最近怎么样？"],["Tu vas bien ?","courant","你还好吗？"]],"fq":"极高频，每天都说。","me":"ça va ?：「撒哇」，一问一答同一个词。","tr":{"zh":"你好，你好吗？很好。","fr":"Bonjour, ça va ? Oui, ça va très bien.","alt":"Salut, ça va ? Ouais, ça va.","note":"同一个短语又问又答：上扬语调是问，下降是答。"}},
 "Enchanté(e)": {"pos":"adj. 形容词，阳性 enchanté，阴性 enchantée（读音相同）","s":"很高兴认识你。初次见面的客气话。男性说 Enchanté，女性说 Enchantée（读音一样）。它本来是动词 enchanter（使着迷）的过去分词。","ipa":"[ɑ̃.ʃɑ̃.te]","ph":"en [ɑ̃]；chan [ʃɑ̃]；té [te]：[ɑ̃.ʃɑ̃.te]；ch [ʃ]。","pi":"enchanté / enchantée 的区别只在写法，读音相同。en 与 an 都是 [ɑ̃]。","et":"来自 enchanter，源自拉丁语 incantare（in + cantare，唱咒语）。同源：chanter（唱）。","ex":[["Enchanté, je m'appelle Marie.","很高兴认识你，我叫玛丽。"],["Enchantée de faire votre connaissance.","很高兴认识您。"]],"co":[["Enchanté de faire ta connaissance","很高兴认识你"],["Enchanté(e) aussi","我也是"],["Moi de même","我也一样"],["Ravi(e) de vous rencontrer","很高兴见到您"]],"sy":[["ravi(e)","courant","很高兴"],["heureux / heureuse","courant","开心"],["content(e)","courant","高兴"]],"fq":"极高频，初次见面用。","me":"en-chant-é：被迷住了，所以很高兴。","tr":{"zh":"很高兴认识你，我叫皮埃尔。","fr":"Enchanté, je m'appelle Pierre.","alt":"Enchanté, moi c'est Pierre.","note":"男性 Enchanté，女性 Enchantée，读音相同。"}},
 "Merci": {"pos":"loc. 短语，也作阳性名词：un merci","s":"谢谢。回答：De rien / Je vous en prie / Il n'y a pas de quoi。注意：Non, merci 是礼貌拒绝（不用了，谢谢）；Oui, merci 是接受。","ipa":"[mɛʁ.si]","ph":"mer [mɛʁ]；ci [si]：[mɛʁ.si]；c 在 i 前读 [s]；r 喉音。","pi":"ci 读 [si]，不是「奇」；结尾 i 不要拖长。Merci pour + 名词；Merci de + 动词不定式。","et":"来自拉丁语 merces（报酬，酬劳），后来有「恩惠、怜悯」的意思。","ex":[["Merci pour ton aide.","谢谢你的帮助。"],["Un café ? Non, merci.","要咖啡吗？不用了，谢谢。"]],"co":[["merci pour …","谢谢你……"],["merci de + infinitif","谢谢你做……"],["merci bien","多谢"],["non merci","不用了，谢谢"]],"sy":[["remercier","courant","动词：感谢"],["je vous remercie","soutenu","我感谢您（正式）"],["mille mercis","courant","万分感谢"]],"fq":"极高频。","me":"merci = 「梅西」：想感谢就说梅西。","tr":{"zh":"谢谢你的礼物，太棒了！","fr":"Merci pour le cadeau, il est magnifique !","alt":"Merci pour le cadeau, il est super !","note":"非常重要：Non, merci 表示拒绝；Oui, merci 表示接受。"}},
 "Merci beaucoup": {"pos":"loc. 短语：merci + beaucoup（副词）","s":"非常感谢。比 merci 更热情。后面接 pour + 名词：Merci beaucoup pour ton aide。不要在 beaucoup 后加 de。","ipa":"[mɛʁ.si bo.ku]","ph":"beau [bo]；coup [ku]；p 不发音：[bo.ku]。整个短语 [mɛʁ.si bo.ku]。","pi":"beaucoup：eau 读 [o]，ou 读 [u]，结尾 p 不发音。不是「bo-ko-p」。","et":"由 merci + beaucoup（beau + coup，字面「一大击」）构成。","ex":[["Merci beaucoup pour le cadeau.","非常感谢你的礼物。"],["Merci beaucoup, c'est gentil !","非常感谢，你真好！"]],"co":[["merci beaucoup pour …","非常感谢……"],["merci mille fois","千恩万谢"],["un grand merci","一个大大的谢意"],["merci infiniment","万分感谢"]],"sy":[["merci bien","courant","多谢"],["merci infiniment","soutenu","万分感谢（正式）"],["mille mercis","courant","万分感谢"]],"fq":"极高频。","me":"merci beaucoup：像「梅西，包库」，很多很多谢谢。","tr":{"zh":"非常感谢您的帮助，女士。","fr":"Merci beaucoup pour votre aide, madame.","alt":"Merci beaucoup pour votre aide !","note":"beaucoup 的 p 不发音；Merci beaucoup pour + 名词。"}},
 "S'il te plaît / S'il vous plaît": {"pos":"loc. 短语：si + il + te / vous + plaît（动词 plaire）","s":"请。字面是「如果它让你高兴」。对朋友、家人、小孩用 s'il te plaît（tu）；对陌生人、长辈、多人用 s'il vous plaît（vous）。放在请求后面。","ipa":"[sil.tə.plɛ] / [sil.vu.plɛ]","ph":"s'il [sil]；te [tə]；plaît [plɛ]：[sil.tə.plɛ]；vous [vu]：[sil.vu.plɛ]。","pi":"plaît 的 î 帽子；t 不发音，读 [plɛ]。s'il = si + il，l 要读出来。","et":"由 si（如果）+ il（它）+ plaît（使喜欢，plaire）构成，源自拉丁语 placere。","ex":[["Un café, s'il te plaît.","请给我一杯咖啡。"],["Un billet, s'il vous plaît.","请给我一张票。"]],"co":[["s'il te plaît (à un ami)","请（对朋友）"],["s'il vous plaît (formel)","请（对不熟的人 / 您）"],["S.V.P.","请（缩写）"],["Merci, s'il vous plaît","谢谢，请"]],"sy":[["je vous en prie","soutenu","请（也可回答谢谢）"],["stp / svp","familier","请（短信）"],["pardon","courant","劳驾"]],"fq":"极高频，礼貌用语。","me":"s'il te plaît：「如果你愿意」。","tr":{"zh":"请给我一杯水。","fr":"Un verre d'eau, s'il vous plaît.","alt":"Un verre d'eau, s'il vous plaît, monsieur.","note":"朋友用 tu 形式，陌生人用 vous 形式。"}},
 "Salut": {"pos":"loc. 短语，也作阳性名词：le salut（致敬；救赎）","s":"嗨；拜拜。朋友、同龄人之间的随意打招呼，也用于告别。对陌生人、老师、老板要用 Bonjour / Au revoir。","ipa":"[sa.ly]","ph":"sa [sa]；lut [ly]；u 是 [y]（嘴唇圆，发「衣」）；t 不发音：[sa.ly]。","pi":"u 读 [y]，像「于」，不是「乌」。结尾 t 不发音。对长辈不要说 Salut。","et":"来自拉丁语 salus / salutem（健康，安好）。同源：saluer（致敬）。","ex":[["Salut, ça va ?","嗨，你好吗？"],["Salut, à demain !","拜拜，明天见！"]],"co":[["dire salut (à quelqu'un)","跟某人打招呼"],["Salut tout le monde !","大家好！"],["Salut, à plus !","拜拜，回见！"],["le salut","致敬；救赎"]],"sy":[["bonjour","courant","你好（更中性）"],["coucou","familier","嗨（亲昵）"],["ciao","familier","拜（来自意大利语）"]],"fq":"极高频，朋友之间。","me":"salut：[sa.ly]，轻松的一声招呼。","tr":{"zh":"嗨，保罗，你好吗？明天见！","fr":"Salut Paul, ça va ? À demain !","alt":"Salut Paul ! Ça va ? À demain !","note":"Salut 只用于熟人；陌生人用 Bonjour。"}},
 "L'art": {"pos":"n.m. 阳性名词，复数 arts","s":"艺术；技艺。le grand art = 高超的技艺。也可指一门技艺：l'art de cuisiner。艺术品是 une œuvre d'art（œuvre 在这里是阴性）。","ipa":"[aʁ]","ph":"a [a]；r [ʁ]；t 不发音：[aʁ]，一个音节。","pi":"结尾 t 不发音；和 are 一样只有一个音节。l'art 省音写作 l'art，不是 le art。","et":"来自拉丁语 ars（技艺）。同源：artiste，artisan，artificiel。","ex":[["J'aime l'art.","我喜欢艺术。"],["Il étudie l'histoire de l'art.","他学习艺术史。"]],"co":[["une œuvre d'art","一件艺术品"],["les beaux-arts","美术"],["l'art moderne","现代艺术"],["les arts martiaux","武术"]],"sy":[["la peinture","courant","绘画（具体的一种）"],["la création","soutenu","创作"]],"fq":"高频。","me":"art：[aʁ]，t 隐身，像 are。","tr":{"zh":"我喜欢参观艺术博物馆。","fr":"J'aime visiter les musées d'art.","alt":"J'adore les musées d'art.","note":"l'art 是阳性，但 une œuvre d'art 里的 œuvre 是阴性。"}},
 "Le basket": {"pos":"n.m. 阳性名词（运动）；une basket 阴性：一只运动鞋","s":"篮球（basket-ball 的简称）。同形词：les baskets / une basket = 运动鞋，是阴性。打球用 jouer au basket。","ipa":"[bas.kɛt]","ph":"ba [ba]；sket [skɛt]：[bas.kɛt]。结尾 t 要读出来。","pi":"借自英语，但重音在后：bas-KET。t 读出来。le basket（球）是阳性，une basket（鞋）是阴性。","et":"借自英语 basket-ball（basket + ball，篮子 + 球）。","ex":[["Nous jouons au basket.","我们打篮球。"],["Il regarde un match de basket.","他在看一场篮球赛。"]],"co":[["jouer au basket","打篮球"],["un match de basket","一场篮球比赛"],["un joueur de basket","篮球运动员"],["des baskets","运动鞋"]],"sy":[["basket-ball","courant","全称"],["des baskets","courant","运动鞋（阴性：une basket）"]],"fq":"高频。","me":"basket = 篮子；球进篮，鞋叫 baskets。","tr":{"zh":"我和朋友们每周六打篮球。","fr":"Mes amis et moi, nous jouons au basket le samedi.","alt":"Le samedi, on joue au basket avec mes potes.","note":"jouer au + 运动；baskets（鞋）与运动同形。"}},
 "Le café": {"pos":"n.m. 阳性名词，复数 cafés","s":"咖啡；咖啡馆。单说 un café 通常指一小杯浓缩咖啡（espresso）。想要加奶的：un café crème / un café au lait。咖啡馆是社交场所，可以坐很久。","ipa":"[ka.fe]","ph":"ca [ka]；fé [fe]：[ka.fe]；重音在最后一个音节。","pi":"é 读 [e]，重音落在 fé 上。不要把重音放在前面（不是 CA-fe）。","et":"经意大利语 caffè，源自土耳其语 kahve，来自阿拉伯语 qahwa。","ex":[["Je bois du café.","我喝咖啡。"],["On se retrouve au café ?","我们在咖啡馆见面吧？"]],"co":[["un café crème","奶咖啡"],["un café noir","黑咖啡"],["prendre un café","喝杯咖啡"],["un café-théâtre","咖啡馆剧场"]],"sy":[["expresso","courant","浓缩咖啡"],["caoua","argot","咖啡（俚语）"],["bistrot","courant","小酒馆；咖啡馆"]],"fq":"极高频。","me":"café：两个音节，重音在「啡」。","tr":{"zh":"你要咖啡还是茶？","fr":"Tu veux un café ou un thé ?","alt":"Tu prends un café ou un thé ?","note":"un café = 浓缩咖啡；有牛奶要说 café crème。"}},
 "Le chocolat": {"pos":"n.m. 阳性名词，复数 chocolats","s":"巧克力；热巧克力。泛指不可数：du chocolat；一块巧克力：un chocolat。点饮料时 un chocolat chaud = 热巧克力。","ipa":"[ʃɔ.kɔ.la]","ph":"ch [ʃ]；o [ɔ]；c [k]；o [ɔ]；la [la]；结尾 t 不发音：[ʃɔ.kɔ.la]。","pi":"结尾 t 不发音，读 [ʃɔ.kɔ.la]；三个音节，重音在最后。别读 chocolate。","et":"经西班牙语 chocolate，源自纳瓦特尔语（阿兹特克）。","ex":[["J'adore le chocolat.","我爱巧克力。"],["Elle boit un chocolat chaud.","她喝一杯热巧克力。"]],"co":[["un chocolat chaud","热巧克力"],["du chocolat noir / au lait","黑巧克力 / 牛奶巧克力"],["une tablette de chocolat","一块巧克力"],["un pain au chocolat","巧克力面包"]],"sy":[["cacao","courant","可可"],["bonbon","courant","糖果"]],"fq":"极高频。","me":"choco-lat：t 不发声，所以像「肖-可-拉」。","tr":{"zh":"我喝热巧克力，吃一个羊角面包。","fr":"Je prends un chocolat chaud avec un croissant.","alt":"Un chocolat chaud et un croissant, s'il vous plaît.","note":"du chocolat 是不可数；un chocolat 可以指一颗或一杯。"}},
 "Le cinéma": {"pos":"n.m. 阳性名词，复数 cinémas","s":"电影院；电影艺术（作为行业）。口语常缩写为 ciné。具体一部电影是 un film。Faire du cinéma = 装腔作势。","ipa":"[si.ne.ma]","ph":"ci [si]；né [ne]；ma [ma]：[si.ne.ma]；c 在 i 前读 [s]；重音在最后。","pi":"c 在 i 前读 [s]；é 读 [e]。重音在最后：ci-né-MA，不是 CI-ne-ma。","et":"缩写自 cinématographe（希腊语 kinēma 运动 + graphein 写）。","ex":[["Je vais au cinéma.","我去电影院。"],["J'aime le cinéma français.","我喜欢法国电影。"]],"co":[["aller au cinéma","去电影院"],["un film de cinéma","电影"],["le cinéma français","法国电影"],["faire du cinéma","装腔作势；表演"]],"sy":[["ciné","familier","电影院（口语简称）"],["salle","courant","放映厅"],["film","courant","电影"]],"fq":"极高频。","me":"ciné-ma：有三个音节，英语 cinema 的重音不同。","tr":{"zh":"周六晚上我们去电影院。","fr":"Samedi soir, nous allons au cinéma.","alt":"Samedi soir, on va au ciné.","note":"去电影院：aller au cinéma；一部电影：un film。"}},
 "Le cricket": {"pos":"n.m. 阳性名词（运动）","s":"板球。借自英语，法国不太流行，英国、印度、澳大利亚常见。注意：蟋蟀（昆虫）法语叫 un grillon，不是 cricket。","ipa":"[kʁi.kɛt]","ph":"cri [kʁi]；cket [kɛt]：[kʁi.kɛt]；t 要读出来。","pi":"借自英语，但 r 是法语喉音。t 读出来。昆虫是 grillon。","et":"借自英语 cricket（英语来源不确定）。","ex":[["Ils jouent au cricket.","他们打板球。"],["Le cricket est un sport anglais.","板球是一项英国运动。"]],"co":[["jouer au cricket","打板球"],["un match de cricket","一场板球比赛"],["une batte de cricket","板球球棒"],["un joueur de cricket","板球运动员"]],"sy":[["grillon","courant","蟋蟀（昆虫，不是运动）"],["baseball","courant","棒球（类似的运动）"]],"fq":"低频，体育词汇。","me":"cricket：英国人打的「蟋蟀」运动，法语里昆虫另有词。","tr":{"zh":"在英国，很多人打板球。","fr":"En Angleterre, beaucoup de gens jouent au cricket.","alt":"En Angleterre, plein de gens jouent au cricket.","note":"jouer au + 运动；昆虫「蟋蟀」是 grillon。"}},
 "Le foot": {"pos":"n.m. 阳性名词（football 的口语简称）","s":"足球。jouer au foot 或 faire du foot。注意：le foot ≠ 英语 foot（脚）；脚是 le pied。","ipa":"[fut]","ph":"f [f]；oo 读 [u]；t 要读出来：[fut]。","pi":"foot 的 oo 读 [u]，t 读出来。英语 foot（脚）在法语是 pied。","et":"football 的缩写，借自英语 football。","ex":[["Il joue au foot.","他踢足球。"],["Tu regardes le foot ce soir ?","你今晚看足球吗？"]],"co":[["jouer au foot","踢足球"],["un match de foot","一场足球赛"],["un joueur de foot","足球运动员"],["le foot féminin","女子足球"]],"sy":[["football","courant","全称"],["le ballon rond","familier","足球（比喻说法）"]],"fq":"极高频。","me":"foot = 足球，pied = 脚：两个词别搞混。","tr":{"zh":"我哥哥每周六踢足球。","fr":"Mon frère joue au foot tous les samedis.","alt":"Mon frère fait du foot le samedi.","note":"打球用 jouer au foot / faire du foot；脚是 pied。"}},
 "Le thé": {"pos":"n.m. 阳性名词，复数 thés","s":"茶；一杯茶。法国人说 un thé 指一杯茶；红茶是 thé noir（字面「黑茶」）。草本茶叫 infusion 或 tisane，不叫 thé。","ipa":"[te]","ph":"th 读 [t]，不像英语的 th；é 读 [e]：[te]，一个音节。","pi":"th 读 [t]，不是 [θ] 也不是 [s]。thé 与 tes（你的，复数）同音。","et":"最终来自闽南话「茶」(te)，经欧洲其他语言进入法语。","ex":[["Je préfère le thé.","我更喜欢茶。"],["Elle boit un thé vert.","她喝一杯绿茶。"]],"co":[["un thé vert / noir","绿茶 / 红茶"],["une tasse de thé","一杯茶"],["un thé au lait","奶茶"],["une théière","茶壶"]],"sy":[["infusion","courant","草本茶"],["tisane","courant","草药茶"]],"fq":"极高频。","me":"thé：th 就是 t，英语的 tea 也是同一个字。","tr":{"zh":"早上我喝加牛奶的茶。","fr":"Le matin, je bois du thé avec du lait.","alt":"Le matin, je prends un thé au lait.","note":"thé 的 th 读 [t]；thé 与 tes 同音。"}},
 "Le vocabulaire": {"pos":"n.m. 阳性名词，复数 vocabulaires","s":"词汇；用词。指一个人或一门语言的全部词语，不可数时用 du vocabulaire。单个词是 un mot。也指某个领域的术语。","ipa":"[vɔ.ka.by.lɛʁ]","ph":"vo [vɔ]；ca [ka]；bu [by]；laire [lɛʁ]：[vɔ.ka.by.lɛʁ]。u 读 [y]；-aire 读 [ɛʁ]。","pi":"u 读 [y]（嘴唇圆）；-aire 读 [ɛʁ]。重音在最后一个音节。","et":"来自拉丁语 vocabulum（名称，词），vocare（叫）。同源：voix（声音），vocal。","ex":[["J'étudie le vocabulaire.","我学习词汇。"],["Son vocabulaire est très riche.","他的词汇很丰富。"]],"co":[["apprendre du vocabulaire","学词汇"],["enrichir son vocabulaire","丰富词汇"],["une liste de vocabulaire","词汇表"],["un vocabulaire riche / pauvre","丰富 / 贫乏的词汇"]],"sy":[["lexique","soutenu","词汇；词典"],["mots","courant","单词"],["glossaire","soutenu","词汇表"]],"fq":"高频，学语言时常用。","me":"vocabulaire：英语 vocabulary，重音在最后。","tr":{"zh":"我想每天学新词汇。","fr":"Je veux apprendre du nouveau vocabulaire chaque jour.","alt":"Chaque jour, j'apprends de nouveaux mots.","note":"vocabulaire 不可数，单个词是 un mot。"}},
 "Un aéroport": {"pos":"n.m. 阳性名词，复数 aéroports","s":"机场。到机场：aller à l'aéroport；在机场：à l'aéroport。","ipa":"[a.e.ʁɔ.pɔʁ]","ph":"a [a]；é [e]；ro [ʁɔ]；port [pɔʁ]：[a.e.ʁɔ.pɔʁ]；t 不发音。","pi":"aé 是两个独立的音节：a-é；结尾 t 不发音。r 都在喉咙。","et":"由 aéro-（希腊语 aēr，空气）+ port（拉丁语 portus，港口）构成。","ex":[["Je vais à l'aéroport.","我去机场。"],["L'aéroport est loin de la ville.","机场离城市很远。"]],"co":[["à l'aéroport","在机场"],["un aéroport international","国际机场"],["aller à l'aéroport","去机场"],["l'aéroport Charles-de-Gaulle","戴高乐机场"]],"sy":[["gare","courant","火车站"],["port","courant","港口"]],"fq":"高频。","me":"aéroport = 空气的港口。","tr":{"zh":"出租车载我们去机场。","fr":"Le taxi nous emmène à l'aéroport.","alt":"Le taxi nous dépose à l'aéroport.","note":"aé 分两个音节；port 的 t 不发音。"}},
 "Un film": {"pos":"n.m. 阳性名词，复数 films","s":"电影；影片。看电影：regarder un film（在家）/ voir un film（在电影院）。电影院是 cinéma。","ipa":"[film]","ph":"f [f]；i [i]；lm [lm]：[film]，一个音节。","pi":"film 只有一个音节：不要加元音，不是「fi-lm-u」。m 和 l 紧紧相连。","et":"借自英语 film（薄膜），再指电影。","ex":[["Je regarde un film.","我看一部电影。"],["Ce film est très drôle.","这部电影很好笑。"]],"co":[["regarder un film","看电影"],["un film d'horreur / d'amour","恐怖 / 爱情电影"],["un film d'animation","动画片"],["un film en version originale","原声电影"]],"sy":[["long métrage","courant","故事片"],["ciné","familier","电影院"],["navet","familier","烂片"]],"fq":"极高频。","me":"film：一个音节，别拆开。","tr":{"zh":"昨晚我们看了一部法国电影。","fr":"Hier soir, nous avons regardé un film français.","alt":"Hier soir, on a maté un film français.","note":"regarder un film = 在家看；voir un film = 去影院看。"}},
 "Un fruit": {"pos":"n.m. 阳性名词，复数 fruits","s":"水果；成果。les fruits de mer = 海鲜（字面「海里的水果」）。比喻：le fruit de son travail（努力的成果）。","ipa":"[fʁɥi]","ph":"fr [fʁ]；ui [ɥi]；结尾 t 不发音：[fʁɥi]，一个音节。","pi":"ui 是 [ɥi]，快速滑音，不是「uii」；t 不发音。注意：les fruits（复数）里 s 也不发音。","et":"来自拉丁语 fructus（果实）。同源：fructose，fructifier。","ex":[["Je mange un fruit.","我吃一个水果。"],["Les fruits sont bons pour la santé.","水果对健康有益。"]],"co":[["manger des fruits","吃水果"],["un jus de fruit","果汁"],["les fruits de mer","海鲜"],["un fruit de saison","应季水果"]],"sy":[["légume","courant","蔬菜（对比词）"],["fruit sec","courant","干果"]],"fq":"极高频。","me":"fruit：ui 一滑而过，t 是沉默的。","tr":{"zh":"我每天早上吃一个水果。","fr":"Je mange un fruit chaque matin.","alt":"Chaque matin, je prends un fruit.","note":"fruit 常用复数：des fruits；les fruits de mer = 海鲜。"}},
 "Un homme": {"pos":"n.m. 阳性名词，复数 hommes","s":"男人；人类。l'homme 也指「人类」。反义词 une femme（女人，读 [fam]）。","ipa":"[ɔm]","ph":"h 不发音；o 读 [ɔ]；mm 读一个 [m]：[ɔm]。un homme 连读：[œ̃.nɔm]；les hommes 连读：[le.zɔm]。","pi":"h 不发音；hommes 的 s 不发音。homme [ɔm] 与 femme [fam] 的元音不同。","et":"来自拉丁语 homo（人）。同源：humain，homicide。","ex":[["C'est un homme grand.","他是一个高个子男人。"],["Cet homme est très gentil.","这个男人很友善。"]],"co":[["un jeune homme","年轻人"],["un homme d'affaires","商人"],["un homme politique","政治家"],["l'homme (l'humanité)","人类"]],"sy":[["monsieur","courant","先生"],["mec","familier","家伙；男人"],["type","familier","家伙"]],"fq":"极高频。","me":"homme：h 无声，只读 [ɔm]。","tr":{"zh":"一个男人和一个女人在等公交车。","fr":"Un homme et une femme attendent le bus.","alt":"Un mec et une nana attendent le bus.","note":"h 哑音：un homme 要连读，l'homme 要省音。"}},
 "Un lieu de naissance": {"pos":"n.m. 阳性名词词组，复数 des lieux de naissance","s":"出生地。表格和证件上常见的说法：lieu de naissance。lieu 本身是「地方」，复数 lieux。","ipa":"[ljø.də.nɛ.sɑ̃s]","ph":"lieu [ljø]；de 轻读 [də]；naissance 的 ai [ɛ]，an [ɑ̃]，ss 读 [s]，结尾 ce 读 [s]。","pi":"lieu 的复数是 lieux（x 不发音）；naissance 里 ss 不是 [z]。","et":"lieu 来自拉丁语 locus（地方）；naissance 来自动词 naître（出生）。","ex":[["Quel est ton lieu de naissance ?","你的出生地是哪里？"],["Mon lieu de naissance, c'est Lyon.","我的出生地是里昂。"]],"co":[["date et lieu de naissance","出生日期和地点"],["lieu de travail","工作地点"],["lieu de résidence","居住地"]],"sy":[["endroit","courant","地方（更口语）"],["origine","courant","出身、来源"]],"fq":"中频，填表时必见。","me":"lieu = 地方，naissance = 出生：「出生的地方」。","tr":{"zh":"你的出生地是哪里？","fr":"Quel est ton lieu de naissance ?","alt":"Tu es né où ?","note":"de 后面接名词，不加冠词。"}},
 "Un métier": {"pos":"n.m. 阳性名词，复数 métiers","s":"职业；行当（尤其指需要技能的工作）。问「你做什么工作？」常说 Quel est ton métier ? 或 Tu fais quoi dans la vie ?。比 travail（工作、劳动）更具体。","ipa":"[me.tje]","ph":"é [e]；t [t]；ier 读 [je]，结尾 r 不发音。","pi":"结尾 -ier 读 [je]，r 不发音，别读成 [mɛ.tiɛʁ]。","et":"来自古法语 mestier，源自拉丁语 ministerium（职务、服务）。","ex":[["Quel est ton métier ?","你做什么工作？"],["Mon père a un métier difficile.","我爸爸的工作很辛苦。"],["Elle aime son métier.","她喜欢自己的职业。"]],"co":[["exercer un métier","从事一个职业"],["changer de métier","换职业"],["un métier d'avenir","有前途的职业"],["les métiers de la santé","医疗行业"]],"sy":[["profession","soutenu","职业（更正式）"],["travail","courant","工作、劳动；不一定是职业名称"],["boulot","familier","活儿、工作"]],"fq":"高频，日常常用。","me":"métier 的 -ier 像「梅提耶」，最后的 r 不读。","tr":{"zh":"你做什么职业？","fr":"Quel est ton métier ?","alt":"Tu fais quoi dans la vie ?","note":"问职业用 Quel est ton métier ?，也可用 Tu fais quoi ?。"}},
 "Un nom de famille": {"pos":"n.m. 阳性名词词组，复数 des noms de famille","s":"姓；姓氏。nom 单独也常指「姓」，所以填表时 Nom = 姓。名字用 prénom，不要混。nom de famille 字面是「家族的名字」。","ipa":"[nɔ̃.də.fa.mij]","ph":"nom 的 om 是鼻化音 [ɔ̃]，m 不发音；famille 的 ille 读 [ij]，l 不读成 [l]。","pi":"nom 结尾 m 不发音，不读 [nɔm]；famille 里的 ille 读 [ij]（不是 [il]）。","et":"nom 来自拉丁语 nomen（名字）；famille 来自拉丁语 familia（家庭）。","ex":[["Mon nom de famille est Martin.","我姓马丁。"],["Quel est votre nom de famille ?","您贵姓？"],["Elle garde son nom de famille.","她保留了自己的姓。"]],"co":[["nom et prénom","姓和名"],["épeler son nom de famille","拼读姓氏"],["un nom de famille français","法国姓氏"]],"sy":[["nom","courant","姓（在表格上）"],["patronyme","soutenu","父系姓氏"]],"fq":"高频，自我介绍和填表常用。","me":"nom = 姓，prénom = 名：pré- 是「前」，名字在姓的前面。","tr":{"zh":"请拼一下你的姓。","fr":"Épelez votre nom de famille, s'il vous plaît.","alt":"Tu peux épeler ton nom ?","note":"nom 是姓，prénom 才是名。"}},
 "Un numéro de téléphone": {"pos":"n.m. 阳性名词词组，复数 des numéros de téléphone","s":"电话号码。法国手机号一般是 10 位数字，两位两位地读，如 06 12 34 56 78。numéro 单独也可指「号码」，如 numéro de rue（门牌号）。","ipa":"[ny.me.ʁo.də.te.le.fɔn]","ph":"u [y]（嘴唇圆，发「迂」）；é [e]；r 是小舌音 [ʁ]；o [o]；phone 的 ph 读 [f]，结尾 e 不发音。","pi":"numéro 的 u 读 [y]，不是 [u]；téléphone 里 ph 读 [f]；电话号码要两位两位读。","et":"numéro 来自意大利语 numero，源自拉丁语 numerus（数）；téléphone 来自希腊语 tēle（远）+ phōnē（声音）。","ex":[["Quel est ton numéro de téléphone ?","你的电话号码是多少？"],["Je te donne mon numéro de téléphone.","我把我的电话号码给你。"],["Tu as mon numéro ?","你有我的号码吗？"]],"co":[["donner son numéro de téléphone","给出电话号码"],["composer un numéro","拨号"],["un numéro de portable","手机号"],["faux numéro","打错的号码"]],"sy":[["numéro","courant","号码（口语里常省略 de téléphone）"],["numéro de portable","courant","手机号"]],"fq":"高频，日常常用。","me":"téléphone：tele（远）+ phone（声音）= 远处的声音。","tr":{"zh":"你有我的电话号码吗？","fr":"Tu as mon numéro de téléphone ?","alt":"Tu as mon numéro ?","note":"问对方的号码用 Quel est ton numéro ?。"}},
 "Un passeport": {"pos":"n.m. 阳性名词，复数 passeports","s":"护照。出国要带 le passeport；身份证是 la carte d'identité。passeport 常搭配 avoir（有）、présenter（出示）、renouveler（换新）。","ipa":"[pas.pɔʁ]","ph":"ss 读 [s]；port 的 o 是开口 [ɔ]，t 不发音，r 读 [ʁ]。","pi":"结尾 t 不发音：passeport 读 [pas.pɔʁ]，不是 [pas.pɔʁt]；拼写中间是 sse，不要拼成 pasport。","et":"passer（通过）+ port（港口）：原指通过港口的许可证。","ex":[["J'ai un passeport français.","我有法国护照。"],["N'oublie pas ton passeport !","别忘了你的护照！"],["Mon passeport est périmé.","我的护照过期了。"]],"co":[["renouveler son passeport","换护照"],["présenter son passeport","出示护照"],["un passeport biométrique","生物识别护照"]],"sy":[["carte d'identité","courant","身份证；不是护照"],["visa","courant","签证；不是护照"]],"fq":"中频，旅行时常用。","me":"pass + port：「过港口」就要出示护照。","tr":{"zh":"别忘了你的护照。","fr":"N'oublie pas ton passeport.","alt":"Prends bien ton passeport !","note":"否定祈使句：N'oublie pas。"}},
 "Un pays": {"pos":"n.m. 阳性名词，单复数同形 pays","s":"国家；地区。un pays 可以是 la France 这样的国家，也可指「家乡、乡下」（le pays = 故乡）。单数和复数都是 pays，靠冠词分辨：un pays / des pays。","ipa":"[pe.i]","ph":"pay 读 [pe.i]（两个音节）；结尾 s 不发音。","pi":"结尾 s 不发音；单复数同形，看冠词 un / des；注意不是 [pe]，而是 [pe.i]。","et":"来自古法语 païs，源自拉丁语 pagensis（乡镇的）。","ex":[["La France est un pays.","法国是一个国家。"],["Quel est ton pays d'origine ?","你的原籍国是哪里？"],["Il a visité beaucoup de pays.","他去过很多国家。"]],"co":[["un pays d'origine","原籍国"],["un pays étranger","外国"],["du même pays","同国的人"],["dans mon pays","在我的国家"]],"sy":[["nation","soutenu","民族国家"],["région","courant","地区"],["patrie","littéraire","祖国"]],"fq":"极高频，日常常用。","me":"pays 像「配-伊」：两个音节，最后的 s 不读。","tr":{"zh":"你来自哪个国家？","fr":"De quel pays viens-tu ?","alt":"Tu viens de quel pays ?","note":"来自某国：venir de + 国家。"}},
 "Un piano": {"pos":"n.m. 阳性名词，复数 pianos","s":"钢琴。弹钢琴用 jouer du piano（du = de + le）。piano 也是音乐术语「轻」，与 forte（强）相对。","ipa":"[pja.no]","ph":"pia 读 [pja]（i 变成半元音 [j]）；o 是闭口 [o]。","pi":"弹乐器要说 jouer du piano，不能说 jouer le piano（日常口语）；第一个音节是 [pja]，不是 [pi.a]。","et":"来自意大利语 piano，是 pianoforte（弱-强）的缩写。","ex":[["Je joue du piano.","我弹钢琴。"],["Elle prend des cours de piano.","她在上钢琴课。"],["Il y a un piano dans le salon.","客厅里有一架钢琴。"]],"co":[["jouer du piano","弹钢琴"],["un cours de piano","钢琴课"],["un piano à queue","三角钢琴"],["un pianiste","钢琴家"]],"sy":[["clavier","courant","键盘（电子琴、电脑）"],["synthétiseur","courant","合成器"]],"fq":"中频。","me":"piano = 钢琴，几乎和中文、英文一样；记住 jouer DU piano。","tr":{"zh":"我女儿每天弹钢琴。","fr":"Ma fille joue du piano tous les jours.","alt":"Ma fille fait du piano tous les jours.","note":"乐器前用 jouer de + 定冠词：du piano。"}},
 "Un prénom": {"pos":"n.m. 阳性名词，复数 prénoms","s":"名字（名，不含姓）。prénom 是「教名、名」，nom 是「姓」。介绍自己：Je m'appelle Paul（名）；全名是 prénom + nom。","ipa":"[pʁe.nɔ̃]","ph":"pr 中的 r 是小舌音 [ʁ]；é [e]；nom 读鼻化音 [ɔ̃]，m 不发音。","pi":"结尾 m 不发音，不读 [pʁe.nɔm]；别和 nom（姓）混淆。","et":"pré-（在前）+ nom（名字）：在姓之前的名字。","ex":[["Mon prénom est Paul.","我叫保罗。"],["Quel est ton prénom ?","你叫什么名字？"],["Ce prénom est très courant.","这个名字很常见。"]],"co":[["choisir un prénom","取名字"],["un prénom composé","复合名（如 Jean-Pierre）"],["son prénom et son nom","名和姓"]],"sy":[["nom","courant","姓（填表时）；注意不等于 prénom"],["petit nom","familier","昵称"]],"fq":"高频，自我介绍用。","me":"pré-nom：姓之前的名字。","tr":{"zh":"你叫什么名字？","fr":"Quel est ton prénom ?","alt":"Tu t'appelles comment ?","note":"Tu t'appelles comment ? 更口语。"}},
 "Un sport": {"pos":"n.m. 阳性名词，复数 sports","s":"体育运动；运动项目。faire du sport = 做运动；un sport = 一项运动（如足球）。「打球、练瑜伽」用 faire du / de la / de l' + 运动名；球类常用 jouer au。","ipa":"[spɔʁ]","ph":"sp 连读在一起 [sp]；o 是开口 [ɔ]；r [ʁ]；结尾 t 不发音。","pi":"结尾 t 不发音：sport 读 [spɔʁ]；开头 sp 不要加元音。","et":"来自英语 sport，英语又来自古法语 desport（消遣）。","ex":[["Je fais du sport.","我做运动。"],["Quel sport tu aimes ?","你喜欢什么运动？"],["Le tennis est un sport.","网球是一项运动。"]],"co":[["faire du sport","做运动"],["un sport d'équipe","团体项目"],["un sport de combat","格斗类运动"],["une salle de sport","健身房"]],"sy":[["activité physique","soutenu","体育活动"],["exercice","courant","锻炼"]],"fq":"极高频，日常常用。","me":"sport 来自英语，很像 sport；注意结尾 t 不读。","tr":{"zh":"你周末做运动吗？","fr":"Tu fais du sport le week-end ?","alt":"Tu fais du sport ce week-end ?","note":"faire du sport：做运动，不加具体项目。"}},
 "Un téléphone": {"pos":"n.m. 阳性名词，复数 téléphones","s":"电话；手机。口语里 téléphone 常指手机，也说 portable 或 smartphone。打电话：téléphoner à qqn；接电话：répondre au téléphone。","ipa":"[te.le.fɔn]","ph":"é [e]；ph 读 [f]；o 是开口 [ɔ]；n 后的 e 不发音。","pi":"ph 读 [f]，不是 [p]；重音在最后一个音节；téléphone 有两个 é，别漏掉重音。","et":"希腊语 tēle（远）+ phōnē（声音）。","ex":[["J'ai un nouveau téléphone.","我有一部新手机。"],["Mon téléphone sonne.","我的手机在响。"],["Je suis au téléphone.","我在打电话。"]],"co":[["au téléphone","在电话里"],["un téléphone portable","手机"],["répondre au téléphone","接电话"],["raccrocher le téléphone","挂电话"]],"sy":[["portable","courant","手机"],["mobile","courant","手机（较正式）"],["tél","familier","电话（缩写）"]],"fq":"极高频，日常常用。","me":"tele（远）+ phone（声音）。","tr":{"zh":"我在打电话，等我一下。","fr":"Je suis au téléphone, attends-moi un instant.","alt":"Là, je suis au téléphone, deux secondes.","note":"être au téléphone：正在通话。"}},
 "Un transport": {"pos":"n.m. 阳性名词，复数 transports","s":"运输；交通方式。常用复数：les transports (en commun) = 公共交通。un moyen de transport = 一种交通工具。单数也可指「运输」。","ipa":"[tʁɑ̃s.pɔʁ]","ph":"tr 中 r 是 [ʁ]；an 读鼻化音 [ɑ̃]；s 读 [s]；o 是开口 [ɔ]；结尾 t 不发音。","pi":"结尾 t 不发音；an 是鼻化音 [ɑ̃]，不要读 [an]。","et":"来自拉丁语 transportare：trans-（越过）+ portare（携带）。","ex":[["Je prends les transports.","我乘坐公共交通。"],["Le métro est un transport rapide.","地铁是一种快速的交通方式。"],["Quel moyen de transport tu utilises ?","你用什么交通工具？"]],"co":[["les transports en commun","公共交通"],["un moyen de transport","交通工具"],["prendre les transports","乘公共交通"],["un titre de transport","车票"]],"sy":[["véhicule","courant","车辆"],["moyen de locomotion","soutenu","出行方式"]],"fq":"高频，日常常用。","me":"trans-（越过）+ port：「越过」去别处。","tr":{"zh":"我每天乘公共交通上班。","fr":"Je prends les transports en commun pour aller au travail.","alt":"Je vais au boulot en transports.","note":"常用复数 les transports。"}},
 "De la musique": {"pos":"n.f. 阴性名词，复数 musiques","s":"音乐。de la musique 是部分冠词，表示「（不可数的）音乐」：écouter de la musique（听音乐）、faire de la musique（演奏音乐）。具体的一首曲子可说 un morceau。","ipa":"[my.zik]","ph":"u [y]；s 在两个元音之间读 [z]；结尾 que 读 [k]。","pi":"s 读 [z]；u 读 [y]（嘟起嘴发「迂」）；结尾 -que 读 [k]。","et":"来自拉丁语 musica，源自希腊语 mousikē（缪斯女神的艺术）。","ex":[["J'écoute de la musique.","我听音乐。"],["Tu fais de la musique ?","你玩音乐吗？"],["Quel type de musique tu aimes ?","你喜欢哪种音乐？"]],"co":[["écouter de la musique","听音乐"],["faire de la musique","做音乐、演奏"],["un morceau de musique","一首乐曲"],["de la musique classique","古典音乐"]],"sy":[["chanson","courant","歌曲（有歌词）"],["morceau","courant","乐曲、曲目"]],"fq":"极高频，日常常用。","me":"musique 来自「缪斯」Muse，艺术女神。","tr":{"zh":"我每天晚上听音乐。","fr":"J'écoute de la musique tous les soirs.","alt":"Le soir, j'écoute toujours de la musique.","note":"不可数名词用部分冠词 de la。"}},
 "De la salade": {"pos":"n.f. 阴性名词，复数 salades","s":"沙拉；生菜。de la salade 指「（一些）沙拉」；une salade 指一份沙拉；la salade 也指整棵生菜。口语里 raconter des salades = 瞎说、编故事。","ipa":"[sa.lad]","ph":"s 读 [s]；a [a]；d 读 [d]，结尾 e 不发音。","pi":"不是 [sa.la.de]；e 不发音，重音在 lad。","et":"来自意大利语 insalata，源自拉丁语 sal（盐）：加盐的菜。","ex":[["Je prépare de la salade.","我做沙拉。"],["Tu veux de la salade ?","你要沙拉吗？"],["Une salade verte, s'il vous plaît.","请来一份蔬菜沙拉。"]],"co":[["une salade verte","绿叶沙拉"],["une salade de tomates","番茄沙拉"],["une salade composée","什锦沙拉"],["raconter des salades","瞎编（口语）"]],"sy":[["laitue","courant","生菜（植物）"],["crudités","courant","生蔬菜拼盘"]],"fq":"高频，日常常用。","me":"salade 来自「盐」sal：撒了盐的菜。","tr":{"zh":"中午我吃了一份沙拉。","fr":"À midi, j'ai mangé une salade.","alt":"Ce midi, j'ai pris une salade.","note":"具体一份用 une，泛指用 de la。"}},
 "L'heure": {"pos":"n.f. 阴性名词，复数 heures","s":"小时；钟点；时间（几点）。Quelle heure est-il ? = 现在几点？；l'heure 是「钟点、时刻」，和 le temps（时间长短、天气）不同。le h 不发音，要省音：l'heure。","ipa":"[œʁ]","ph":"h 不发音；eu 在 r 前读开口 [œ]；r [ʁ]；l' 直接与 eu 相连。","pi":"h 不发音，所以是 l'heure，不是 la heure；heure 的发音只有 [œʁ]，别读成 [ɛʁ]。","et":"来自拉丁语 hora，源自希腊语 hōra（时间、季节）。","ex":[["Quelle heure est-il ?","现在几点了？"],["Il est huit heures.","现在八点。"],["Je suis à l'heure.","我准时。"]],"co":[["Quelle heure est-il ?","现在几点？"],["à quelle heure ?","几点？"],["à l'heure","准时"],["une heure","一个小时 / 一点钟"]],"sy":[["temps","courant","时间（长短）；不要和 l'heure 混淆"],["moment","courant","时刻"]],"fq":"极高频，日常常用。","me":"h 不读，l'heure = [lœʁ]，像「勒尔」。","tr":{"zh":"现在几点了？我要迟到了。","fr":"Quelle heure est-il ? Je vais être en retard.","alt":"Il est quelle heure ? Je vais être en retard.","note":"几点用 Quelle heure est-il ?。"}},
 "La France": {"pos":"n.f. 阴性名词专有名词","s":"法国。国名前一般要加定冠词：la France。「在法国」用 en France（阴性国名用 en），「来自法国」用 de France 或 venir de France。","ipa":"[fʁɑ̃s]","ph":"fr 里 r 是 [ʁ]；an 读鼻化音 [ɑ̃]；c 读 [s]，结尾 e 不发音。","pi":"an 是鼻化音 [ɑ̃]，不读 [an]；c 读 [s]，所以是 [fʁɑ̃s]。","et":"来自拉丁语 Francia，意为「法兰克人的土地」。","ex":[["J'habite en France.","我住在法国。"],["La France est un beau pays.","法国是个美丽的国家。"],["Je viens de France.","我来自法国。"]],"co":[["en France","在法国"],["venir de France","来自法国"],["la France entière","整个法国"],["le sud de la France","法国南部"]],"sy":[["l'Hexagone","courant","六边形；指法国本土（媒体常用）"]],"fq":"极高频，日常常用。","me":"法国的形状像六边形：l'Hexagone。","tr":{"zh":"我想去法国学习。","fr":"Je veux aller étudier en France.","alt":"J'aimerais étudier en France.","note":"阴性国名前用 en。"}},
 "La grammaire": {"pos":"n.f. 阴性名词，复数 grammaires","s":"语法。la grammaire 指学科，une grammaire 也可指「语法书」。常见搭配：règle de grammaire（语法规则）、faute de grammaire（语法错误）。","ipa":"[ɡʁa.mɛʁ]","ph":"gr 里 g 读 [ɡ]，r 读 [ʁ]；mm 只读一个 [m]；aire 读 [ɛʁ]。","pi":"mm 只读一个 m；结尾 aire 读 [ɛʁ]，不是 [ɛʁə]；拼写是 gram-maire，不是 grammer。","et":"来自拉丁语 grammatica，源自希腊语 grammatikē（与字母有关的技艺）。","ex":[["J'apprends la grammaire.","我学语法。"],["La grammaire française est difficile.","法语语法很难。"],["Il y a une faute de grammaire.","这里有个语法错误。"]],"co":[["une règle de grammaire","语法规则"],["une faute de grammaire","语法错误"],["un livre de grammaire","语法书"],["la grammaire française","法语语法"]],"sy":[["syntaxe","soutenu","句法"],["orthographe","courant","拼写；不同于语法"]],"fq":"高频，学习用语。","me":"grammaire 来自希腊语 gramma（字母）。","tr":{"zh":"语法对我来说很难。","fr":"La grammaire est difficile pour moi.","alt":"Pour moi, la grammaire, c'est dur.","note":"pour moi：对我来说。"}},
 "La littérature": {"pos":"n.f. 阴性名词，复数 littératures","s":"文学；文学作品总称。la littérature française = 法国文学。也可指某一领域的文献：la littérature scientifique。","ipa":"[li.te.ʁa.tyʁ]","ph":"tt 只读一个 [t]；é [e]；r [ʁ]；u 读 [y]；结尾 e 不发音。","pi":"tt 双写但只读一个 [t]；u 读 [y]，不是 [u]；别把它拼成 literature（少一个 t）。","et":"来自拉丁语 litteratura，源自 littera（字母）。","ex":[["J'étudie la littérature.","我学习文学。"],["Elle adore la littérature française.","她热爱法国文学。"],["C'est un classique de la littérature.","这是文学经典。"]],"co":[["la littérature française","法国文学"],["un cours de littérature","文学课"],["la littérature jeunesse","儿童文学"],["étudier la littérature","学习文学"]],"sy":[["lettres","courant","文学（常指大学院系：les lettres）"],["roman","courant","小说；只是文学的一类"]],"fq":"中频。","me":"literature 的 t 在法语里要写两个：littérature。","tr":{"zh":"我喜欢法国文学。","fr":"J'aime la littérature française.","alt":"Moi, j'adore la littérature française.","note":"语言+文学：la littérature + 形容词。"}},
 "La poésie": {"pos":"n.f. 阴性名词，复数 poésies","s":"诗歌；诗意。la poésie = 诗这种文学体裁；une poésie = 一首（短）诗，学校里常说背一首诗：réciter une poésie。写诗的人叫 poète。","ipa":"[pɔ.e.zi]","ph":"po 读 [pɔ]；é 读 [e]；s 在元音之间读 [z]；结尾 ie 读 [i]。","pi":"s 读 [z]；注意 o 和 é 分成两个音节：[pɔ.e.zi]；结尾 e 不发音。","et":"来自希腊语 poiēsis（创造、制作），经拉丁语 poesis 传入。","ex":[["J'écris de la poésie.","我写诗。"],["Elle lit de la poésie le soir.","她晚上读诗。"],["Il a récité une poésie.","他背了一首诗。"]],"co":[["écrire de la poésie","写诗"],["un recueil de poésie","诗集"],["réciter une poésie","背诵诗"],["un poème","一首诗"]],"sy":[["poème","courant","一首诗"],["vers","soutenu","诗句"],["poétique","courant","有诗意的"]],"fq":"中频。","me":"poésie ← poiein（创造）：诗 = 用语言「创造」。","tr":{"zh":"我喜欢读诗。","fr":"J'aime lire de la poésie.","alt":"Moi, j'adore lire de la poésie.","note":"泛指用 de la poésie。"}},
 "La prononciation": {"pos":"n.f. 阴性名词，复数 prononciations","s":"发音。学法语时常说 La prononciation est difficile。动词是 prononcer（发音）。","ipa":"[pʁɔ.nɔ̃.sja.sjɔ̃]","ph":"pro 读 [pʁɔ]；non 读鼻化音 [nɔ̃]；ci 读 [sja]；tion 读 [sjɔ̃]。","pi":"拼写是 prononciation（c 在 non 后面），不是 pronounciation；tion 读 [sjɔ̃]，不是 [tjɔ̃]。","et":"来自动词 prononcer（拉丁语 pronuntiare：pro-「向前」+ nuntiare「宣布」）+ -ation。","ex":[["La prononciation est difficile.","发音很难。"],["Ta prononciation est très bonne.","你的发音很好。"],["Je travaille ma prononciation.","我在练发音。"]],"co":[["une bonne prononciation","好的发音"],["améliorer sa prononciation","改善发音"],["la prononciation d'un mot","一个词的发音"],["une faute de prononciation","发音错误"]],"sy":[["accent","courant","口音"],["articulation","soutenu","咬字"]],"fq":"中频，学习常用。","me":"pro-non-ci-a-tion：多个鼻化音 [ɔ̃]，开口圆。","tr":{"zh":"我的发音还不够好。","fr":"Ma prononciation n'est pas encore très bonne.","alt":"Je dois encore améliorer ma prononciation.","note":"pas encore：还没有。"}},
 "La randonnée": {"pos":"n.f. 阴性名词，复数 randonnées","s":"徒步旅行；远足。aller en randonnée / faire de la randonnée = 去远足；une randonnée 也可指一次远足。比 promenade（散步）更长、更费力。","ipa":"[ʁɑ̃.dɔ.ne]","ph":"r [ʁ]；an 读鼻化音 [ɑ̃]；do [dɔ]；née 读 [ne]。","pi":"an 是鼻化音 [ɑ̃]；née 结尾读 [e]，不要读 [ne.e]。拼写是 randonnée（一个 d，两个 n）。","et":"来自 randonner，源自古法语 randon（急冲、迅疾）。","ex":[["J'aime la randonnée.","我喜欢徒步。"],["On fait une randonnée dimanche.","我们周日去远足。"],["Cette randonnée dure trois heures.","这条徒步路线要走三个小时。"]],"co":[["faire de la randonnée","去徒步"],["aller en randonnée","去远足"],["des chaussures de randonnée","登山鞋"],["un sentier de randonnée","徒步小径"]],"sy":[["promenade","courant","散步，比较短、轻松"],["marche","courant","走路、步行"],["trek","familier","长途徒步（外来词）"]],"fq":"中频。","me":"randonnée：随 rand 出发的长路线。","tr":{"zh":"周末我们去徒步。","fr":"Ce week-end, on fait une randonnée.","alt":"Ce week-end, on va faire de la randonnée.","note":"faire de la randonnée：活动名称，用部分冠词。"}},
 "La télévision": {"pos":"n.f. 阴性名词，复数 télévisions","s":"电视；电视机。regarder la télévision = 看电视；口语缩写 la télé。电视机本身说 un téléviseur 或 une télé。","ipa":"[te.le.vi.zjɔ̃]","ph":"é [e]；s 在元音间读 [z]；sion 读 [zjɔ̃]；结尾 on 鼻化 [ɔ̃]。","pi":"sion 读 [zjɔ̃]，s 读 [z]，不是 [s]；有两个 é 要加重音。","et":"希腊语 tēle（远）+ 拉丁语 visio（看）：远处的画面。","ex":[["Je regarde la télévision.","我看电视。"],["Il y a une télé dans la chambre.","卧室里有一台电视。"],["Qu'est-ce qu'il y a à la télé ?","电视上有什么节目？"]],"co":[["regarder la télévision","看电视"],["à la télévision","在电视上"],["allumer / éteindre la télé","开 / 关电视"],["une émission de télévision","电视节目"]],"sy":[["télé","familier","电视（缩写）"],["téléviseur","courant","电视机"],["petit écran","littéraire","电视（文学说法）"]],"fq":"极高频，日常常用。","me":"télé（远）+ vision（视）：远处的视觉。","tr":{"zh":"我晚上看一会儿电视。","fr":"Le soir, je regarde un peu la télévision.","alt":"Le soir, je regarde un peu la télé.","note":"regarder la télé：看电视。"}},
 "Une adresse": {"pos":"n.f. 阴性名词，复数 adresses","s":"地址；住址。une adresse 也指网址、电子邮箱（adresse email / adresse web）。une adresse 还有「灵巧、技巧」的意思（书面）。","ipa":"[a.dʁɛs]","ph":"a [a]；dr 里 r 读 [ʁ]；e 在 ss 前读 [ɛ]；ss 读 [s]；结尾 e 不发音。","pi":"只有一个 d；ss 读 [s]；不要拼成 adress（法语结尾要有 e）。","et":"来自动词 adresser（à + dresser，指向）。","ex":[["Quelle est ton adresse ?","你的地址是什么？"],["Je te donne mon adresse.","我把我的地址给你。"],["Il a changé d'adresse.","他换了地址。"]],"co":[["donner son adresse","给出地址"],["changer d'adresse","换地址"],["une adresse postale","邮寄地址"],["une adresse web","网址"]],"sy":[["domicile","soutenu","住所（行政用语）"],["coordonnées","courant","联系方式"]],"fq":"高频，填表常见。","me":"adresse：把信「指向」(adresser) 某地。","tr":{"zh":"请给我你的地址。","fr":"Donne-moi ton adresse, s'il te plaît.","alt":"Tu peux me donner ton adresse ?","note":"祈使句：Donne-moi。"}},
 "Une adresse email": {"pos":"n.f. 阴性名词词组，复数 des adresses email","s":"电子邮箱地址。email 也写作 e-mail 或 mail；口语里常说 une adresse mail。念 @ 时说 arobase；点说 point。","ipa":"[a.dʁɛs.i.mɛl]","ph":"adresse [a.dʁɛs]；email 读 [i.mɛl]（法语里 e 读 [i]，ai 读 [ɛ]）。","pi":"email 在法语里读 [i.mɛl]，不是 [e.mɛj]；念 @ 说 arobase。","et":"adresse（见上）；email 来自英语 e-mail（electronic mail）。","ex":[["Voici mon adresse email.","这是我的电子邮箱。"],["Quelle est ton adresse email ?","你的邮箱是什么？"],["Je t'envoie un email.","我给你发一封邮件。"]],"co":[["donner son adresse email","给出邮箱"],["envoyer un email","发邮件"],["une adresse mail","邮箱（口语）"],["avoir une adresse email","有一个邮箱"]],"sy":[["mail","familier","邮件（口语）"],["courriel","courant","电子邮件（魁北克更常用）"]],"fq":"高频，日常常用。","me":"email：e-mail，e 读 [i]，像英文。","tr":{"zh":"我把我的邮箱给你。","fr":"Je te donne mon adresse email.","alt":"Je te donne mon mail.","note":"adresse email 也可说成 adresse mail。"}},
 "Une application": {"pos":"n.f. 阴性名词，复数 applications","s":"应用程序；App；应用。口语常缩写为 une appli。也可指「应用、实施」（l'application d'une règle）。","ipa":"[a.pli.ka.sjɔ̃]","ph":"pp 只读一个 [p]；ca 读 [ka]；tion 读 [sjɔ̃]。","pi":"pp 只读一个 p；tion 读 [sjɔ̃]，不是 [tjɔ̃]。","et":"来自拉丁语 applicatio（应用），由动词 appliquer 派生。","ex":[["J'utilise cette application.","我用这个应用。"],["Tu as téléchargé l'appli ?","你下载 App 了吗？"],["Cette application est gratuite.","这个应用是免费的。"]],"co":[["télécharger une application","下载应用"],["ouvrir une appli","打开 App"],["une application mobile","手机应用"],["une application gratuite","免费应用"]],"sy":[["appli","familier","App（缩写）"],["logiciel","courant","软件"],["programme","courant","程序"]],"fq":"高频，日常常用。","me":"application ← appliquer：把功能「运用」到手机上。","tr":{"zh":"我下载了一个新 App。","fr":"J'ai téléchargé une nouvelle application.","alt":"J'ai téléchargé une nouvelle appli.","note":"télécharger：下载。"}},
 "Une carte SIM": {"pos":"n.f. 阴性名词词组，复数 des cartes SIM","s":"SIM 卡；手机卡。SIM 读作字母 [sim]。到了法国，可以买 une carte SIM prépayée（预付费卡）或用 une eSIM。","ipa":"[kaʁt.sim]","ph":"carte 读 [kaʁt]（e 不发音）；SIM 读 [sim]（像「西姆」）。","pi":"SIM 读 [sim]，不是逐个读字母；carte 里 r 要发 [ʁ]，t 要发音。","et":"carte 来自拉丁语 charta（纸）；SIM 是英语 Subscriber Identity Module 的缩写。","ex":[["J'achète une carte SIM.","我买一张 SIM 卡。"],["Elle change de carte SIM.","她换了一张 SIM 卡。"],["Où acheter une carte SIM ?","在哪儿能买到 SIM 卡？"]],"co":[["acheter une carte SIM","买 SIM 卡"],["une carte SIM prépayée","预付费 SIM 卡"],["insérer la carte SIM","插入 SIM 卡"],["une carte SIM française","法国 SIM 卡"]],"sy":[["puce","familier","芯片，手机卡（口语）"],["eSIM","courant","电子 SIM 卡"]],"fq":"中频，旅行常用。","me":"SIM 读 [sim]，像「西姆」。","tr":{"zh":"我需要一张法国 SIM 卡。","fr":"J'ai besoin d'une carte SIM française.","alt":"Il me faut une carte SIM française.","note":"avoir besoin de + 名词。"}},
 "Une date de naissance": {"pos":"n.f. 阴性名词词组，复数 des dates de naissance","s":"出生日期。date 是阴性：une date。法国日期格式是「日/月/年」，如 le 12 mars 2000 或 12/03/2000。","ipa":"[dat.də.nɛ.sɑ̃s]","ph":"date 读 [dat]，e 不发音；de 轻读 [də]；naissance 读 [nɛ.sɑ̃s]。","pi":"date 是阴性，用 une / la；结尾 e 不发音。","et":"date 来自拉丁语 data（「给出的」，指信上的日期）；naissance 来自 naître。","ex":[["Quelle est ta date de naissance ?","你的出生日期是什么时候？"],["Ma date de naissance, c'est le 5 mai.","我的生日是 5 月 5 日。"],["Écrivez votre date de naissance ici.","请在这里写您的出生日期。"]],"co":[["date et lieu de naissance","出生日期和地点"],["donner sa date de naissance","说出生日期"],["une date limite","截止日期"],["la date d'aujourd'hui","今天的日期"]],"sy":[["anniversaire","courant","生日（庆祝的日子）"],["âge","courant","年龄"]],"fq":"高频，填表常用。","me":"date de naissance：日期（date）+ 出生（naissance）。","tr":{"zh":"请告诉我你的出生日期。","fr":"Peux-tu me dire ta date de naissance ?","alt":"C'est quand, ta date de naissance ?","note":"Peux-tu me dire…：礼貌的请求。"}},
 "Une femme": {"pos":"n.f. 阴性名词，复数 femmes","s":"女人；妻子。une femme = 女人；ma femme = 我的妻子（口语）。「成年女子」用 femme，「女孩」用 fille。","ipa":"[fam]","ph":"e 在 fe- 中读 [a]（不是 [ɛ]）；mm 只读一个 [m]；结尾 e 不发音。","pi":"最大陷阱：femme 读 [fam]，不是 [fɛm]；也不读 [fə.mə]。","et":"来自拉丁语 femina（女人）。","ex":[["C'est une femme forte.","这是一位坚强的女人。"],["Cette femme est médecin.","这位女士是医生。"],["Il parle à sa femme.","他在跟他的妻子说话。"]],"co":[["une femme d'affaires","女商人"],["une femme médecin","女医生"],["la femme de ma vie","我一生所爱的女人"],["les droits des femmes","女性权利"]],"sy":[["dame","courant","女士（礼貌）"],["fille","courant","女孩；女儿"],["épouse","soutenu","妻子"]],"fq":"极高频，日常常用。","me":"femme 读成「法姆」，不是「费姆」。","tr":{"zh":"那位女士是我的老师。","fr":"Cette femme est ma professeure.","alt":"Cette dame, c'est ma prof.","note":"ma professeure：阴性形式。"}},
 "Une nationalité": {"pos":"n.f. 阴性名词，复数 nationalités","s":"国籍。问国籍：Quelle est ta nationalité ? 回答：Je suis français(e)。国籍形容词不大写：français, chinois；国籍名词大写：un Français。","ipa":"[na.sjɔ.na.li.te]","ph":"tio 读 [sjɔ]；na 读 [na]；li 读 [li]；té 读 [te]。","pi":"tio 读 [sjɔ]，不是 [tjo]；五个音节，节奏均匀。","et":"来自 national（拉丁语 natio，出生、民族）+ -ité。","ex":[["Quelle est ta nationalité ?","你的国籍是什么？"],["Il a la nationalité française.","他是法国国籍。"],["Elle a deux nationalités.","她有双重国籍。"]],"co":[["avoir la nationalité française","拥有法国国籍"],["la double nationalité","双重国籍"],["changer de nationalité","换国籍"],["demander la nationalité","申请入籍"]],"sy":[["citoyenneté","soutenu","公民身份"],["origine","courant","出身、背景"]],"fq":"中频，自我介绍用。","me":"nation + -alité：与「国」有关的身份。","tr":{"zh":"我有中国国籍。","fr":"J'ai la nationalité chinoise.","alt":"Je suis de nationalité chinoise.","note":"de nationalité + 形容词。"}},
 "Une université": {"pos":"n.f. 阴性名词，复数 universités","s":"大学。une université 指整个高校；à l'université = 在大学读书。口语缩写 la fac（faculté，学院）。大学生是 un étudiant。","ipa":"[y.ni.vɛʁ.si.te]","ph":"u 读 [y]；i 读 [i]；ver 读 [vɛʁ]；si 读 [si]；té 读 [te]。","pi":"开头 u 读 [y]（不是 [u]）；er 读 [ɛʁ]，r 要发音。","et":"来自拉丁语 universitas（整体、共同体）。","ex":[["J'étudie à l'université.","我在大学学习。"],["Elle est à l'université de Lyon.","她在里昂大学。"],["L'université est près d'ici.","大学离这里很近。"]],"co":[["étudier à l'université","在大学学习"],["entrer à l'université","上大学"],["une université publique","公立大学"],["un diplôme universitaire","大学文凭"]],"sy":[["fac","familier","大学（缩写）"],["faculté","courant","学院"],["grande école","courant","法国精英高等院校"]],"fq":"高频，日常常用。","me":"université：univers（整体）→ 学习一切的地方。","tr":{"zh":"我想在法国上大学。","fr":"Je veux étudier à l'université en France.","alt":"Je voudrais aller à la fac en France.","note":"à l'université：表示在学校学习。"}},
 "Une ville": {"pos":"n.f. 阴性名词，复数 villes","s":"城市；城里。Paris est une ville。「去城里」是 aller en ville。ville 比 village（村）大；capitale 是首都。","ipa":"[vil]","ph":"v [v]；i [i]；ll 在 ville 中读 [l]；结尾 e 不发音。","pi":"ville 里的 ll 读 [l]（不同于 famille 的 [ij]）；结尾 e 不发音。","et":"来自拉丁语 villa（乡间别墅），后来词义变成城镇。","ex":[["Paris est une ville.","巴黎是一座城市。"],["J'habite en ville.","我住在城里。"],["Quelle est ta ville préférée ?","你最喜欢哪座城市？"]],"co":[["en ville","在城里"],["une grande ville","大城市"],["le centre-ville","市中心"],["une ville moyenne","中等城市"]],"sy":[["village","courant","村庄；比 ville 小"],["cité","soutenu","城市；城邦"],["capitale","courant","首都"]],"fq":"极高频，日常常用。","me":"ville 来自 villa：从乡间别墅变成「城」。","tr":{"zh":"我住在一个大城市。","fr":"J'habite dans une grande ville.","alt":"J'habite dans une grosse ville.","note":"dans une grande ville：在大城市。"}},
 "Les devoirs": {"pos":"n.m.pl. 阳性复数名词（单数 un devoir）","s":"作业。「做作业」是 faire ses devoirs（常用复数）。单数 un devoir 指「义务；一次作业或小测」。devoirs 来自动词 devoir（应该）。","ipa":"[də.vwaʁ]","ph":"de 读轻的 [də]；voir 读 [vwaʁ]；结尾 s 不发音（但 les devoirs 开头 les 读 [le]）。","pi":"ou 在 devoir 里不是 [u]，而是 [wa]：[də.vwaʁ]；复数 s 不发音。","et":"来自动词 devoir（拉丁语 debere，应该）：必须要做的事。","ex":[["Je dois faire mes devoirs.","我得做作业。"],["Tu as fini tes devoirs ?","你做完作业了吗？"],["Il n'a pas de devoirs ce soir.","他今晚没有作业。"]],"co":[["faire ses devoirs","做作业"],["avoir des devoirs","有作业"],["les devoirs de maths","数学作业"],["finir ses devoirs","完成作业"]],"sy":[["exercices","courant","练习题"],["travail","courant","功课、工作"],["corvée","familier","苦差事"]],"fq":"高频，学生常用。","me":"devoirs = 应该做的事（devoir）：作业。","tr":{"zh":"我做完作业才能玩。","fr":"Je dois finir mes devoirs avant de jouer.","alt":"Je finis mes devoirs, puis je joue.","note":"devoir + 动词原形：必须。"}},
 "Les jeux-vidéos": {"pos":"n.m.pl. 阳性复数名词（单数 un jeu vidéo）","s":"电子游戏；视频游戏。常见规范写法是 les jeux vidéo（vidéo 不变）。玩游戏：jouer aux jeux vidéo；口语 les jeux vidéo 常简称 les jeux。","ipa":"[ʒø.vi.de.o]","ph":"jeux 读 [ʒø]（x 不发音）；vidéo 读 [vi.de.o]（三个音节）。","pi":"jeux 的 x 不发音；jeu 的复数是 jeux（不是 jeus）；vidéo 的 é 要加重音。","et":"jeu 来自拉丁语 jocus；vidéo 来自拉丁语 video（我看）。","ex":[["Je joue aux jeux-vidéos.","我玩电子游戏。"],["Il adore les jeux vidéo.","他热爱电子游戏。"],["Ce jeu vidéo est très populaire.","这款游戏很火。"]],"co":[["jouer aux jeux vidéo","玩电子游戏"],["un jeu vidéo","一款游戏"],["une console de jeux","游戏机"],["un joueur de jeux vidéo","游戏玩家"]],"sy":[["jeu","courant","游戏（泛指）"],["gaming","familier","游戏（外来词）"]],"fq":"高频，年轻人常用。","me":"jeu（游戏）+ vidéo（影像）。","tr":{"zh":"我周末玩电子游戏。","fr":"Le week-end, je joue aux jeux vidéo.","alt":"Le week-end, je fais des jeux vidéo.","note":"jouer à + 游戏：玩游戏。"}},
 "Les langues": {"pos":"n.f.pl. 阴性复数名词（单数 une langue）","s":"语言（复数）。une langue 也是「舌头」。les langues étrangères = 外语；la langue maternelle = 母语。学语言：apprendre une langue。","ipa":"[lɑ̃ɡ]","ph":"an 读鼻化音 [ɑ̃]；gu 读 [ɡ]（u 不发音）；结尾 es 不发音。","pi":"gu 里的 u 不发音：langue 读 [lɑ̃ɡ]；复数 -es 不发音。","et":"来自拉丁语 lingua（舌头；语言）。","ex":[["Je parle deux langues.","我会说两种语言。"],["Elle apprend les langues étrangères.","她在学外语。"],["Quelle est ta langue maternelle ?","你的母语是什么？"]],"co":[["parler plusieurs langues","会说好几种语言"],["apprendre une langue","学一门语言"],["la langue maternelle","母语"],["les langues étrangères","外语"]],"sy":[["idiome","soutenu","语言（书面）"],["dialecte","courant","方言"]],"fq":"高频，日常常用。","me":"langue 又是舌头又是语言：用舌头说话。","tr":{"zh":"我正在学三种语言。","fr":"J'apprends trois langues.","alt":"Je suis en train d'apprendre trois langues.","note":"être en train de：正在做。"}},
 "Un acteur / Une actrice": {"pos":"n. 名词，阳 acteur / 阴 actrice，复数 acteurs / actrices","s":"演员。阳性 un acteur，阴性 une actrice。注意：acteur 的阴性不是 acteuse；也可以说 comédien / comédienne（演员，尤其话剧）。","ipa":"[ak.tœʁ] / [ak.tʁis]","ph":"ac 读 [ak]；teur 读 [tœʁ]（eu 在 r 前为 [œ]）；actrice 读 [ak.tʁis]，c 读 [s]。","pi":"阴性是 actrice，不是 acteuse；acteur 结尾 r 要发 [ʁ]。","et":"来自拉丁语 actor（行动者，源自 agere 行动）。","ex":[["C'est un bon acteur.","他是个好演员。"],["Cette actrice joue très bien.","这位女演员演得很好。"],["Mon acteur préféré est français.","我最喜欢的演员是法国人。"]],"co":[["un acteur de cinéma","电影演员"],["une actrice célèbre","著名女演员"],["le rôle d'un acteur","演员的角色"],["jouer un rôle","演一个角色"]],"sy":[["comédien / comédienne","courant","演员（舞台、影视）"],["artiste","courant","艺术家"]],"fq":"中频。","me":"actor ← agere（行动）：演员 = 行动的人。","tr":{"zh":"我最喜欢的演员是法国人。","fr":"Mon acteur préféré est français.","alt":"Mon acteur préféré, c'est un Français.","note":"préféré：最喜欢的。"}},
 "Un auteur / Une autrice": {"pos":"n. 名词，阳 auteur / 阴 autrice（也写 auteure），复数 auteurs / autrices","s":"作者；作家。阴性有 une autrice、une auteure 两种写法，都在使用。auteur 也可指「创造者」（l'auteur d'un crime = 犯罪的人）。","ipa":"[o.tœʁ] / [o.tʁis]","ph":"au 读 [o]；teur 读 [tœʁ]；autrice 读 [o.tʁis]。","pi":"au 读 [o]，没有 h（不是 author）；阴性可用 autrice 或 auteure。","et":"来自拉丁语 auctor（创造者，源自 augere 增加）。","ex":[["C'est mon auteur préféré.","他是我最喜欢的作家。"],["Cette autrice écrit des romans.","这位女作家写小说。"],["Qui est l'auteur de ce livre ?","这本书的作者是谁？"]],"co":[["l'auteur du livre","书的作者"],["un auteur célèbre","著名作家"],["une autrice française","法国女作家"],["un auteur de romans","小说作者"]],"sy":[["écrivain","courant","作家（偏文学）"],["romancier","soutenu","小说家"]],"fq":"中频。","me":"auteur 没有 h：和英语 author 比，少一个 h。","tr":{"zh":"这本书的作者是谁？","fr":"Qui est l'auteur de ce livre ?","alt":"C'est qui, l'auteur de ce livre ?","note":"Qui est… 询问身份。"}},
 "Un chanteur / Une chanteuse": {"pos":"n. 名词，阳 chanteur / 阴 chanteuse，复数 chanteurs / chanteuses","s":"歌手。动词 chanter（唱）加 -eur / -euse。职业直接用名词，不加冠词：Il est chanteur。","ipa":"[ʃɑ̃.tœʁ] / [ʃɑ̃.tøz]","ph":"ch 读 [ʃ]；an 读 [ɑ̃]；chanteur 读 [ʃɑ̃.tœʁ]；chanteuse 读 [ʃɑ̃.tøz]。","pi":"ch 读 [ʃ]；阴性 chanteuse 的 s 读 [z]，是 [tøz]。","et":"来自动词 chanter（拉丁语 cantare）+ -eur / -euse。","ex":[["Il est chanteur.","他是歌手。"],["Cette chanteuse a une belle voix.","这位歌手嗓音很美。"],["Mon chanteur préféré est belge.","我最喜欢的歌手是比利时人。"]],"co":[["un chanteur célèbre","著名歌手"],["une chanteuse d'opéra","歌剧女歌手"],["un chanteur de rue","街头歌手"],["le chanteur du groupe","乐队主唱"]],"sy":[["artiste","courant","艺术家、艺人"],["interprète","soutenu","表演者"]],"fq":"中频。","me":"chanter + -eur：chanteur = 唱歌的人。","tr":{"zh":"她是我最喜欢的歌手。","fr":"C'est ma chanteuse préférée.","alt":"C'est ma chanteuse préférée, je l'adore.","note":"ma chanteuse：阴性物主形容词。"}},
 "Un sportif / Une sportive": {"pos":"n. 名词（也是形容词），阳 sportif / 阴 sportive，复数 sportifs / sportives","s":"运动员；爱运动的人。形容词也说 sportif：Il est très sportif（他很爱运动）。阳性 -f，阴性 -ve（f→v）。","ipa":"[spɔʁ.tif] / [spɔʁ.tiv]","ph":"sp 读 [sp]；port 读 [pɔʁ]；r 要发音；阳性结尾 f 读 [f]，阴性结尾 ve 读 [v]。","pi":"此处 t 要发音（和 sport 不同）；阳性 -f、阴性 -ve：sportif / sportive。","et":"sport（来自英语）+ -if / -ive。","ex":[["C'est une sportive.","她是运动员。"],["Mon frère est très sportif.","我哥哥很爱运动。"],["Les sportifs s'entraînent tous les jours.","运动员每天训练。"]],"co":[["un sportif de haut niveau","高水平运动员"],["être sportif","爱运动"],["une activité sportive","体育活动"],["un sportif professionnel","职业运动员"]],"sy":[["athlète","soutenu","田径运动员，运动员"],["joueur / joueuse","courant","球员"]],"fq":"中频。","me":"sportif：f → v，类似 actif / active。","tr":{"zh":"我妹妹是个运动员。","fr":"Ma sœur est une sportive.","alt":"Ma sœur est sportive de haut niveau.","note":"职业前可省略冠词，也可用 une sportive。"}},
 "Un(e) étudiant(e)": {"pos":"n. 名词，阳 étudiant / 阴 étudiante，复数 étudiants / étudiantes","s":"大学生；学生。étudiant 专指上大学或高校的学生；中小学生用 élève。职业常省略冠词：Je suis étudiant / étudiante。","ipa":"[e.ty.djɑ̃] / [e.ty.djɑ̃t]","ph":"é [e]；tu 读 [ty]（u 为 [y]）；dian 读 [djɑ̃]；阴性 -e 使 t 发音。","pi":"阳性结尾 -ant 读 [ɑ̃]，t 不发音；阴性 étudiante 的 t 要发 [t]。","et":"来自动词 étudier 的现在分词，源自拉丁语 studere（努力、学习）。","ex":[["Je suis étudiant.","我是大学生。"],["Elle est étudiante en médecine.","她是医学院的学生。"],["Les étudiants sont en cours.","学生们在上课。"]],"co":[["un étudiant en droit","法学学生"],["une étudiante étrangère","外国女留学生"],["la vie étudiante","大学生活"],["une carte d'étudiant","学生证"]],"sy":[["élève","courant","中小学生"],["lycéen / lycéenne","courant","高中生"],["fac","familier","大学（étudiant 常简称）"]],"fq":"高频，日常常用。","me":"étudiant 阴性加 -e：étudiante，t 要读出来。","tr":{"zh":"我是一名留学生。","fr":"Je suis étudiant(e) étranger / étrangère.","alt":"Je suis étudiant(e) à l'étranger.","note":"étudiant(e)：阳性 / 阴性。"}},
 "Adorer": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir","s":"热爱；非常喜欢。比 aimer 更强：J'adore ce film = 我超爱这部电影。后面可接名词或动词原形：J'adore danser。","ipa":"[a.dɔ.ʁe]","ph":"a [a]；do 读 [dɔ]；r [ʁ]；er 读 [e]，r 不发音。","pi":"结尾 -er 读 [e]，r 不发音；规则变位：j'adore, tu adores, il adore, nous adorons。","et":"来自拉丁语 adorare：ad-（向）+ orare（祈祷、说话）。","ex":[["J'adore ce film.","我很喜欢这部电影。"],["Elle adore voyager.","她热爱旅行。"],["Nous adorons la cuisine italienne.","我们爱意大利菜。"]],"co":[["adorer + 名词","热爱某物"],["adorer + 动词原形","热爱做某事"],["j'adore !","我超爱！"],["adorer les chats","爱猫"]],"sy":[["aimer","courant","喜欢（比 adorer 弱）"],["aimer beaucoup","courant","非常喜欢"],["raffoler de","soutenu","狂热喜欢"]],"fq":"高频，日常常用。","me":"adorer：ad + orer，原本是「向神祈祷」。","tr":{"zh":"我超爱听音乐。","fr":"J'adore écouter de la musique.","alt":"J'adore la musique !","note":"adorer + 动词原形。"}},
 "Aider": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir","s":"帮助。aider qqn = 帮助某人；aider qqn à + 动词原形 = 帮某人做某事。aide 作名词是「帮助」。","ipa":"[e.de]","ph":"ai 读 [e]；d 读 [d]；er 读 [e]，r 不发音。","pi":"ai 读 [e]（开头），不是 [ai]；aider qqn à + inf，别漏 à。","et":"来自拉丁语 adjutare（帮助），源自 adjuvare。","ex":[["Je peux t'aider.","我可以帮你。"],["Il aide sa mère à cuisiner.","他帮妈妈做饭。"],["Tu peux m'aider ?","你能帮我吗？"]],"co":[["aider quelqu'un","帮助某人"],["aider qqn à + inf","帮某人做某事"],["Au secours / à l'aide !","救命！"],["s'entraider","互相帮助"]],"sy":[["assister","soutenu","协助"],["donner un coup de main","familier","搭把手"],["secourir","soutenu","救助"]],"fq":"极高频，日常常用。","me":"aider ≈ aide：「艾德」，帮忙。","tr":{"zh":"你能帮我找我的钥匙吗？","fr":"Tu peux m'aider à trouver mes clés ?","alt":"Tu m'aides à chercher mes clés ?","note":"aider à + 动词原形。"}},
 "Aimer": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir","s":"喜欢；爱。aimer + 名词时要加冠词：J'aime le chocolat。对人：Je t'aime = 我爱你；Je l'aime bien = 我挺喜欢他。aimer + 动词原形 = 喜欢做某事。","ipa":"[e.me]","ph":"ai 读 [e]（开口 [ɛ] 也常见）；m [m]；er 读 [e]。","pi":"aimer 里 ai 读 [e]；j'aime 的 e 不发音；喜欢某物要用定冠词 le / la / les。","et":"来自拉丁语 amare（爱）。","ex":[["J'aime le chocolat.","我喜欢巧克力。"],["Elle aime danser.","她喜欢跳舞。"],["Tu aimes la musique ?","你喜欢音乐吗？"]],"co":[["aimer bien","挺喜欢"],["aimer mieux","更喜欢"],["aimer + 动词原形","喜欢做某事"],["Je t'aime.","我爱你。"]],"sy":[["adorer","courant","热爱（更强）"],["apprécier","soutenu","欣赏"],["kiffer","argot","超喜欢（年轻人）"]],"fq":"极高频，日常常用。","me":"aimer ← amare：amour 的动词。","tr":{"zh":"我喜欢咖啡，但是不喜欢茶。","fr":"J'aime le café, mais je n'aime pas le thé.","alt":"Le café, j'aime bien, mais pas le thé.","note":"否定：je n'aime pas。"}},
 "Arriver": {"pos":"v.i. 不及物动词，第一组（-er），助动词 être","s":"到达；发生。je suis arrivé(e) = 我到了（助动词用 être）。arriver à + 地点 = 到某地；arriver à + 动词原形 = 设法做成。Ça arrive ! = 这种事会有。","ipa":"[a.ʁi.ve]","ph":"a [a]；rr 读一个 [ʁ]；i [i]；v [v]；er 读 [e]。","pi":"助动词用 être：je suis arrivé，不是 j'ai arrivé；rr 只读一个 [ʁ]。","et":"来自拉丁语 ad ripam（到岸边）：ad + ripa（河岸），原指船靠岸。","ex":[["J'arrive demain.","我明天到。"],["Le train arrive à midi.","火车中午到。"],["Je n'arrive pas à dormir.","我睡不着。"]],"co":[["arriver à + 地点","到达某地"],["arriver à + 动词原形","设法做到"],["Ça arrive !","这种事会发生。"],["arriver en retard / à l'heure","迟到 / 准时到"]],"sy":[["parvenir","soutenu","到达；成功"],["venir","courant","来"],["se passer","courant","发生"]],"fq":"极高频，日常常用。","me":"arriver ← ad ripam：船「靠岸」就是到了。","tr":{"zh":"我晚上八点到。","fr":"J'arrive à huit heures du soir.","alt":"J'arrive vers vingt heures.","note":"arriver à + 时间。"}},
 "Contacter": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir","s":"联系；与……取得联系。contacter qqn 直接接宾语，不加介词：Je vais contacter le directeur。比 appeler（打电话）更广，可以是电话、邮件。","ipa":"[kɔ̃.tak.te]","ph":"con 读鼻化音 [kɔ̃]；tac 读 [tak]；ter 读 [te]。","pi":"ct 要两个音都读 [kt]：[tak.te]；con 是鼻化音 [kɔ̃]，不读 [kon]。","et":"来自 contact（拉丁语 contactus，接触）+ -er。","ex":[["Tu peux me contacter.","你可以联系我。"],["Je vais contacter la banque.","我要联系银行。"],["Contactez-nous par email.","请通过邮件联系我们。"]],"co":[["contacter quelqu'un","联系某人"],["contacter par email","通过邮件联系"],["rester en contact","保持联系"],["prendre contact avec","与……联系"]],"sy":[["joindre","courant","联系上（电话）"],["appeler","courant","打电话"],["écrire à","courant","写信给"]],"fq":"中频，工作和生活常用。","me":"contacter ← contact：取得「接触」。","tr":{"zh":"我明天联系你。","fr":"Je vais te contacter demain.","alt":"Je te contacte demain.","note":"contacter qqn：无介词。"}},
 "Être né(e)": {"pos":"v. 动词词组：être + 过去分词 né / née，复数 nés / nées","s":"出生。用 être + né：Je suis né(e) en 2000。男性写 né，女性写 née，复数 nés / nées。问：Tu es né où ? / Quand es-tu né(e) ?","ipa":"[ɛtʁ.ne]","ph":"être 读 [ɛtʁ]；né / née 读 [ne]，三者读音相同。","pi":"性别只在书面上区分：né（男）/ née（女），发音相同；不能说 j'ai né。","et":"être（拉丁语 esse）+ 过去分词 né（来自 naître，拉丁语 nasci）。","ex":[["Je suis né en mars.","我是三月出生的。"],["Elle est née à Lyon.","她在里昂出生。"],["Tu es né quand ?","你是什么时候出生的？"]],"co":[["être né(e) en + 年 / 月","在某年 / 某月出生"],["être né(e) à + 城市","在某地出生"],["être né(e) le + 日期","在某日出生"],["Je suis né(e) en France.","我在法国出生。"]],"sy":[["naître","soutenu","诞生（原形）"],["venir au monde","littéraire","来到人世"]],"fq":"高频，自我介绍用。","me":"né 对应男，née 对应女，读音一样。","tr":{"zh":"我 1998 年在上海出生。","fr":"Je suis né(e) à Shanghai en 1998.","alt":"Je suis né(e) en 1998, à Shanghai.","note":"né(e)：随主语性别变化。"}},
 "Étudier": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir","s":"学习；研究；学。étudier le français = 学法语；étudier à Paris = 在巴黎读书。口语里「上学」也常说 faire des études。étudier 通常指系统学习，不同于 apprendre（学会）。","ipa":"[e.ty.dje]","ph":"é [e]；tu 读 [ty]（u 为 [y]）；dier 读 [dje]，r 不发音。","pi":"u 读 [y]；结尾 -ier 读 [je]；变位：j'étudie, tu étudies, il étudie, nous étudions。","et":"来自拉丁语 studiare / studium（热忱、学习）。","ex":[["J'étudie à Paris.","我在巴黎学习。"],["Elle étudie le français.","她学法语。"],["Nous étudions la littérature.","我们学习文学。"]],"co":[["étudier à + 城市","在某地学习"],["étudier le français","学习法语"],["faire des études","读书（大学）"],["étudier un problème","研究一个问题"]],"sy":[["apprendre","courant","学会；学习新知识"],["travailler","courant","学习、工作"],["réviser","courant","复习"]],"fq":"高频，学生常用。","me":"étudier ← studium：从「热忱」到「学习」。","tr":{"zh":"我在巴黎学习法语。","fr":"J'étudie le français à Paris.","alt":"Je fais mes études de français à Paris.","note":"étudier + 科目。"}},
 "Habiter": {"pos":"v.t./v.i. 第一组（-er），助动词 avoir","s":"居住；住在。habiter à Paris, habiter en France, habiter au Japon。可以直接加宾语：Il habite un appartement。chez 表示在某人家：habiter chez mes parents。","ipa":"[a.bi.te]","ph":"h 不发音；a [a]；bi [bi]；ter 读 [te]；j'habite 要省音：[ʒa.bit]。","pi":"h 不发音，所以是 j'habite，不是 je habite；nous habitons，liaison 是 [z]：nous_habitons。","et":"来自拉丁语 habitare（经常居住）。","ex":[["J'habite en France.","我住在法国。"],["Il habite à Paris.","他住在巴黎。"],["Nous habitons dans un petit appartement.","我们住在一个小公寓里。"]],"co":[["habiter à + 城市","住在某城市"],["habiter en + 阴性国名","住在某国"],["habiter chez + 人","住在某人家"],["habiter près de","住在……附近"]],"sy":[["vivre","courant","生活、居住"],["loger","courant","住宿"],["résider","soutenu","居住（正式）"]],"fq":"极高频，日常常用。","me":"habiter 像 habitat：生物的「居住地」。","tr":{"zh":"我住在巴黎南部。","fr":"J'habite dans le sud de Paris.","alt":"J'habite au sud de Paris.","note":"dans le sud de：在……南部。"}},
 "Parler": {"pos":"v.i./v.t. 第一组（-er），助动词 avoir","s":"说；说话；会说。parler français = 会说法语（语言前不加冠词）；parler à qqn = 对某人说；parler de qqch = 谈论；parler avec qqn = 和某人谈。","ipa":"[paʁ.le]","ph":"par 读 [paʁ]（r 要发音）；ler 读 [le]，r 不发音。","pi":"parler + 语言，不加冠词：Je parle français；parler à + 人，parler de + 事。","et":"来自拉丁语 parabolare（讲话），源自 parabola（比喻、话）。","ex":[["Je parle français.","我说法语。"],["Il parle à son ami.","他在跟朋友说话。"],["On parle de quoi ?","我们在谈什么？"]],"co":[["parler français","说法语"],["parler à quelqu'un","对某人说话"],["parler de qqch","谈论某事"],["parler fort / doucement","大声 / 轻声说"]],"sy":[["dire","courant","说（内容）"],["discuter","courant","讨论、聊"],["bavarder","familier","闲聊"]],"fq":"极高频，日常常用。","me":"parler 与 parole（话语）同源。","tr":{"zh":"你会说英语吗？","fr":"Tu parles anglais ?","alt":"Est-ce que tu parles anglais ?","note":"语言前不加冠词。"}},
 "Préférer": {"pos":"v.t. 及物动词，第一组（-er，特殊变位），助动词 avoir","s":"更喜欢；偏爱。préférer A à B = 喜欢 A 胜过 B；préférer + 动词原形。变位特殊：je préfère, nous préférons（第二个 é 在不发音的 e 前变 è）。","ipa":"[pʁe.fe.ʁe]","ph":"pré 读 [pʁe]；fé 读 [fe]；rer 读 [ʁe]；je préfère 读 [ʒə.pʁe.fɛʁ]。","pi":"变位里的重音变化：je préfère（è），nous préférons（é）；préférer A à B。","et":"来自拉丁语 praeferre：prae-（在前）+ ferre（带、拿）。","ex":[["Je préfère le thé.","我更喜欢茶。"],["Tu préfères quoi, le thé ou le café ?","你更喜欢什么，茶还是咖啡？"],["Elle préfère rester à la maison.","她更喜欢待在家里。"]],"co":[["préférer A à B","喜欢 A 胜过 B"],["préférer + 动词原形","更喜欢做某事"],["je préfère que + 虚拟式","我希望（某人）……"],["ma couleur préférée","我最喜欢的颜色"]],"sy":[["aimer mieux","courant","更喜欢"],["privilégier","soutenu","优先选择"],["choisir","courant","选择"]],"fq":"高频，日常常用。","me":"pré-（在前）+ fér（带）：把它「放在前面」= 更喜欢。","tr":{"zh":"我更喜欢茶，不太喝咖啡。","fr":"Je préfère le thé, je bois peu de café.","alt":"Moi, je préfère le thé au café.","note":"préférer A à B。"}},
 "Trouver": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir","s":"找到；发现；觉得。Je trouve un fruit = 我找到一个水果。Je trouve que + 句子 = 我觉得……。se trouver = 位于；trouver 与 chercher（寻找）不同：先找，后找到。","ipa":"[tʁu.ve]","ph":"tr 读 [tʁ]；ou 读 [u]；ver 读 [ve]。","pi":"ou 读 [u]，不是 [o]；chercher（找）与 trouver（找到）要分清。","et":"古法语 trover，源自通俗拉丁语 *tropare（来源有争议）。","ex":[["Je trouve un fruit.","我找到一个水果。"],["Je trouve que c'est beau.","我觉得很美。"],["Où est-ce que je peux trouver un taxi ?","我在哪儿能找到出租车？"]],"co":[["trouver + 名词","找到某物"],["trouver que…","觉得……"],["trouver du travail","找到工作"],["se trouver à","位于"]],"sy":[["découvrir","courant","发现"],["chercher","courant","寻找；不同于 trouver"],["penser","courant","认为"]],"fq":"极高频，日常常用。","me":"chercher（找）先发生，trouver（找到）是结果。","tr":{"zh":"我觉得这本书很有意思。","fr":"Je trouve ce livre très intéressant.","alt":"Ce livre, je le trouve super intéressant.","note":"trouver + 宾语 + 形容词：觉得。"}},
 "Anglais(e)": {"pos":"adj. 及名词，阳 anglais / 阴 anglaise，复数 anglais / anglaises","s":"英国的；英国人；英语。形容词小写：Elle est anglaise。名词指人时大写：un Anglais, une Anglaise。英语（语言）是阳性名词 l'anglais，小写。","ipa":"[ɑ̃.ɡlɛ] / [ɑ̃.ɡlɛz]","ph":"an 读鼻化音 [ɑ̃]；gl 读 [ɡl]；ais 读 [ɛ]，s 不发音；阴性 anglaise 读 [ɑ̃.ɡlɛz]。","pi":"阳性结尾 -ais 读 [ɛ]，s 不发音；阴性 s 读 [z]：anglaise [ɑ̃.ɡlɛz]；国籍和语言小写。","et":"来自 Angle（日耳曼民族「盎格鲁人」，拉丁语 Anglus）+ -ais。","ex":[["Elle est anglaise.","她是英国人。"],["Je parle anglais.","我说英语。"],["C'est un Anglais qui habite à Paris.","这是个住在巴黎的英国人。"]],"co":[["parler anglais","说英语"],["un cours d'anglais","英语课"],["la cuisine anglaise","英国菜"],["un petit-déjeuner anglais","英式早餐"]],"sy":[["britannique","courant","英国的（泛指大不列颠）"],["anglophone","courant","讲英语的"]],"fq":"极高频，日常常用。","me":"anglais ← Angle：「盎格鲁」，英格兰得名于此。","tr":{"zh":"她是英国人，但是住在法国。","fr":"Elle est anglaise, mais elle habite en France.","alt":"Elle est anglaise, elle vit en France.","note":"国籍形容词要性数配合。"}},
 "Célèbre": {"pos":"adj. 形容词，阴阳同形 célèbre，复数 célèbres","s":"著名的，出名的。可指人、地方、作品。常用 être célèbre pour ...（因……而出名）。","ipa":"[se.lɛbʁ]","ph":"é [e]；è [ɛ]；结尾 -bre 轻轻带出 [bʁ]，e 不发音。","pi":"两个重音符号不同：célèbre。阴阳性同形：un homme célèbre / une femme célèbre。","et":"拉丁语 celeber（人多的，著名的）。同源：célébrer（庆祝）、célébrité（名人）。","ex":[["Il est très célèbre.","他非常有名。"],["Paris est célèbre pour sa tour Eiffel.","巴黎因埃菲尔铁塔而出名。"],["C'est une chanteuse célèbre.","她是一位著名的歌手。"]],"co":[["célèbre pour ...","因……而出名"],["un acteur célèbre","著名演员"],["devenir célèbre","成名"]],"sy":[["connu","courant","有名的，比 célèbre 弱"],["fameux","soutenu","著名的（也可指「很棒的」）"]],"fq":"中高频，日常常用。","me":"célèbre 像 celebrity：名人就是 célèbre。","tr":{"zh":"这位演员在法国很有名。","fr":"Cet acteur est très célèbre en France.","alt":"Cet acteur, il est connu en France.","note":"形容词放在名词后或用 être 连接；阴阳同形。"}},
 "Féminin": {"pos":"adj. 形容词，阴性 féminine，复数 féminins","s":"阴性的；女性的。语法上指阴性词（un mot féminin），也指女性的、女式的（la mode féminine）。反义词 masculin。","ipa":"[fe.mi.nɛ̃]","ph":"é [e]；in 在词尾读鼻化 [ɛ̃]，n 不单独发音。阴性 féminine 读 [fe.mi.nin]。","pi":"阳性 féminin 的 n 不发音，阴性 féminine 的 n 要发音。注意不是 femenin。","et":"拉丁语 femininus，来自 femina（女人）。同源：femme（女人，妻子）。","ex":[["\"Langue\" est un mot féminin.","「langue」是阴性词。"],["Le prénom Marie est féminin.","Marie 这个名字是女性名字。"],["Le féminin de \"acteur\" est \"actrice\".","「acteur」的阴性形式是「actrice」。"]],"co":[["un mot féminin","阴性词"],["le féminin / le masculin","阴性 / 阳性"],["au féminin","用阴性形式"],["la mode féminine","女装"]],"sy":[["masculin","courant","反义词：阳性的"],["féminine","courant","阴性形式（修饰阴性名词）"]],"fq":"中频，语法和日常都会遇到。","me":"fémin- 来自 femme：女人。","tr":{"zh":"「table」是阴性词。","fr":"« Table » est un mot féminin.","alt":"« Table », c'est un mot féminin.","note":"修饰 mot（阳性）用 féminin，不加 e。"}},
 "Français(e)": {"pos":"adj. / n. 形容词；名词。阴性 française，复数 français(es)","s":"法国的；法国人。形容词小写：Il est français。名词大写：un Français / une Française。le français = 法语（阳性名词，小写）。","ipa":"[fʁɑ̃.sɛ]","ph":"fr [fʁ]；an [ɑ̃]；ç [s]；ais [ɛ]，结尾 s 不发音。阴性 française [fʁɑ̃.sɛz]。","pi":"结尾 -ais 读 [ɛ]，不是 [ai]，s 不发音。阴性 française 的 s 读 [z]。","et":"来自 France，拉丁语 Francia，意为「法兰克人的土地」。-ais 是表示「属于某地」的后缀。","ex":[["Il est français.","他是法国人。"],["Elle parle français.","她说法语。"],["Les Français aiment le pain.","法国人爱面包。"]],"co":[["parler français","说法语"],["un cours de français","法语课"],["en français","用法语"],["à la française","法式的"]],"sy":[["francophone","courant","说法语的"],["de France","courant","来自法国（可替换）"]],"fq":"极高频，学习法语必备。","me":"française 的 s 发 [z]，像「法兰」+ 「斯」。","tr":{"zh":"她是法国人，但她不说法语。","fr":"Elle est française, mais elle ne parle pas français.","alt":"Elle est française, mais elle parle pas français.","note":"职业、国籍用 être + 无冠词；parler français 不加冠词。"}},
 "Masculin": {"pos":"adj. 形容词，阴性 masculine，复数 masculins","s":"阳性的；男性的。语法上指阳性词（un mot masculin），也指男子气概的。反义词 féminin。","ipa":"[mas.ky.lɛ̃]","ph":"u 读 [y]（圆唇的「于」）；结尾 -in 读鼻化 [ɛ̃]。阴性 masculine [mas.ky.lin]。","pi":"u 要发 [y]，不是 [u]。阳性词尾 n 不发音，阴性 masculine 的 n 发音。","et":"拉丁语 masculinus，来自 masculus（雄性的），而它来自 mas（男性）。","ex":[["\"Film\" est un mot masculin.","「film」是阳性词。"],["« Le » est l'article masculin.","« Le » 是阳性冠词。"],["Il a une voix masculine.","他的声音很有男子气。"]],"co":[["un mot masculin","阳性词"],["le masculin / le féminin","阳性 / 阴性"],["au masculin","用阳性形式"],["un prénom masculin","男性名字"]],"sy":[["féminin","courant","反义词：阴性的"],["mâle","courant","雄性（动物）"]],"fq":"中频，语法常用。","me":"masculin 的 u 像「于」：mas-ku-lin 要噘嘴。","tr":{"zh":"「livre」是阳性词。","fr":"« Livre » est un mot masculin.","alt":"« Livre », c'est un mot masculin.","note":"masculin 修饰阳性名词 mot，不加 e。"}},
 "Préféré(e)": {"pos":"adj. 形容词，阴性 préférée，复数 préféré(e)s","s":"最喜欢的。放在名词前面，也可作名词：mon préféré / ma préférée（我最喜欢的那个）。来自动词 préférer（更喜欢）的过去分词。","ipa":"[pʁe.fe.ʁe]","ph":"三个音节都以 é [e] 结尾：pré-fé-ré。阴性 préférée 读音相同。","pi":"三个 é 都有重音符号，别漏。préféré 阴性要加 e：ma chanson préférée。","et":"拉丁语 praeferre（放在前面，偏爱）。préférer 是动词，préféré 是它的过去分词。","ex":[["C'est mon livre préféré.","这是我最喜欢的书。"],["Ma couleur préférée est le bleu.","我最喜欢的颜色是蓝色。"],["Quel est ton plat préféré ?","你最喜欢的菜是什么？"]],"co":[["mon / ma ... préféré(e)","我最喜欢的……"],["le plat préféré","最喜欢的菜"],["mon sport préféré","我最喜欢的运动"],["C'est mon préféré.","这是我的最爱。"]],"sy":[["favori","courant","最爱的（常用于「最受欢迎的」）"],["chouchou","familier","宠儿，最受宠的"]],"fq":"高频，日常常用。","me":"pré-fé-ré：三个 é，像「喜欢一再喜欢」。","tr":{"zh":"我最喜欢的歌手是法国人。","fr":"Mon chanteur préféré est français.","alt":"Mon chanteur préféré, il est français.","note":"préféré 放在名词后，随名词变阴阳性和单复数。"}},
 "Le grand-père": {"pos":"n.m. 阳性名词，复数 grands-pères","s":"祖父；外祖父。法语不分父系母系，都叫 grand-père。口语常说 papi / papy（爷爷，外公）。","ipa":"[gʁɑ̃.pɛʁ]","ph":"gr [gʁ]；an [ɑ̃]；è [ɛ]；结尾 r 要发 [ʁ]。d 在 grand 里不发音。","pi":"复数是 grands-pères（grand 也要加 s）。grand 的 d 和 s 都不发音。","et":"grand（大）+ père（父亲，拉丁语 pater）。同源：paternel（父亲的）。","ex":[["Mon grand-père lit le journal.","我爷爷在看报纸。"],["Mes grands-pères sont à la retraite.","我的两位祖父都退休了。"],["Papi, tu viens manger ?","爷爷，你来吃饭吗？"]],"co":[["mon grand-père paternel / maternel","我的爷爷 / 外公"],["un arrière-grand-père","曾祖父"],["rendre visite à son grand-père","去看望爷爷"]],"sy":[["papi / papy","familier","爷爷（亲昵）"],["pépé","familier","爷爷（更口语）"],["aïeul","soutenu","祖先，祖辈"]],"fq":"高频，家庭话题必学。","me":"grand（大）+ père（爸爸）= 大爸爸 = 爷爷。","tr":{"zh":"我外公住在乡下。","fr":"Mon grand-père habite à la campagne.","alt":"Papi habite à la campagne.","note":"法语不分爷爷和外公；需要时加 paternel / maternel。"}},
 "Le mari": {"pos":"n.m. 阳性名词，复数 maris","s":"丈夫。口语里也常说 mon homme、mon époux（更正式）。注意妻子是 la femme，同一个词也有「女人」的意思。","ipa":"[ma.ʁi]","ph":"ma [ma]；ri [ʁi]；两个音节，重音在最后。","pi":"结尾的 i 要发，不发 [e]。注意 mari（丈夫）和 marié（新郎，已婚的）读音不同。","et":"拉丁语 maritus（已婚男人）。同源：marier（结婚）、mariage（婚姻）、marital。","ex":[["C'est le mari de Juliette.","这是朱丽叶的丈夫。"],["Son mari travaille à Lyon.","她丈夫在里昂工作。"],["Ils sont mari et femme.","他们是夫妻。"]],"co":[["le mari de ...","……的丈夫"],["mari et femme","夫妻"],["mon futur mari","我未来的丈夫"]],"sy":[["époux","soutenu","丈夫（较正式）"],["homme","familier","mon homme = 我老公"]],"fq":"高频，家庭话题。","me":"mari 像 marriage：结了婚的男人。","tr":{"zh":"我丈夫是医生。","fr":"Mon mari est médecin.","alt":"Mon mari, il est médecin.","note":"表示职业时 est médecin 不加冠词。"}},
 "Le père": {"pos":"n.m. 阳性名词，复数 pères","s":"父亲。口语中说 papa（爸爸）。le père 也可以指神父，也用于 le père Noël（圣诞老人）。","ipa":"[pɛʁ]","ph":"è [ɛ]；结尾 r 要发 [ʁ]。只有一个音节。","pi":"注意重音符号 è：père，不是 pere。r 在词尾要发出来。père 与 paire（一对）同音 [pɛʁ]，靠上下文区分。","et":"拉丁语 pater。同源：paternel（父亲的）、paternité（父亲身份）。","ex":[["Mon père travaille ici.","我爸爸在这里工作。"],["Le père de Paul est professeur.","保罗的父亲是老师。"],["Le père Noël arrive demain !","圣诞老人明天来！"]],"co":[["le père de ...","……的父亲"],["un père de famille","一家之长；有孩子的父亲"],["le père Noël","圣诞老人"],["de père en fils","代代相传"]],"sy":[["papa","familier","爸爸"],["paternel","familier","老爸（口语）"],["géniteur","soutenu","生父"]],"fq":"极高频，家庭必学。","me":"père 像 parent 的开头 par-：家长。","tr":{"zh":"我父亲每天早上看报纸。","fr":"Mon père lit le journal tous les matins.","alt":"Mon père, il lit le journal chaque matin.","note":"tous les matins = 每天早上。"}},
 "Un animal": {"pos":"n.m. 阳性名词，复数 animaux（不规则）","s":"动物。un animal de compagnie = 宠物。口语里「宠物」常说 animal domestique。","ipa":"[a.ni.mal]","ph":"a [a]；ni [ni]；mal [mal]，l 要发音。三个音节，重音在最后。","pi":"复数是 animaux，不是 animals。l 在 animal 里要发，animaux 读 [a.ni.mo]。","et":"拉丁语 animal，来自 anima（气息，灵魂）。同源：âme（灵魂）、animer（使有生气）。","ex":[["J'ai un animal de compagnie.","我有一只宠物。"],["Les animaux vivent dans la forêt.","动物生活在森林里。"],["Quel est ton animal préféré ?","你最喜欢什么动物？"]],"co":[["un animal de compagnie","宠物"],["un animal sauvage","野生动物"],["un animal domestique","家养动物"],["les animaux","动物（复数）"]],"sy":[["bête","courant","野兽，虫（也有「笨」的意思）"],["bestiole","familier","小动物，小虫"]],"fq":"高频，日常常用。","me":"animal → animaux：-al 变 -aux，和 cheval → chevaux 一样。","tr":{"zh":"你有宠物吗？","fr":"Tu as un animal de compagnie ?","alt":"T'as un animal ?","note":"animal de compagnie 是「宠物」的固定说法。"}},
 "Un anniversaire": {"pos":"n.m. 阳性名词，复数 anniversaires","s":"生日；周年纪念。法语生日就是 anniversaire：Bon anniversaire ! = 生日快乐！也指结婚纪念日等（un anniversaire de mariage）。","ipa":"[a.ni.vɛʁ.sɛʁ]","ph":"nn 只读一个 [n]；er 读 [ɛʁ]；四个音节，两个 -ɛʁ。","pi":"拼写：anni 中有两个 n，ver 里有 v，别写成 aniversaire。英文 anniversary 以 -ary 结尾，法语是 -aire。","et":"拉丁语 anniversarius：annus（年）+ vertere（转，回来）= 每年回来的日子。","ex":[["C'est mon anniversaire aujourd'hui.","今天是我的生日。"],["Bon anniversaire, Léa !","生日快乐，蕾娅！"],["Nous fêtons leur anniversaire de mariage.","我们庆祝他们的结婚纪念日。"]],"co":[["Bon anniversaire !","生日快乐！"],["fêter son anniversaire","庆祝生日"],["un cadeau d'anniversaire","生日礼物"],["un gâteau d'anniversaire","生日蛋糕"]],"sy":[["fête","courant","节日；聚会（也指命名日）"],["jour de naissance","soutenu","出生日（正式文件）"]],"fq":"高频，日常常用。","me":"anni-vers-aire：一年（anni）转一圈（vers）。","tr":{"zh":"明天是我姐姐的生日。","fr":"Demain, c'est l'anniversaire de ma sœur.","alt":"Demain, c'est l'anniv de ma sœur.","note":"l'anniversaire de + 人；口语缩写 anniv。"}},
 "Un appartement": {"pos":"n.m. 阳性名词，复数 appartements","s":"公寓；套房。法语里 un appartement 是整套房子的住宅单位，日常常缩写成 un appart。","ipa":"[a.paʁ.tə.mɑ̃]","ph":"pp 读一个 [p]；e 在 -te- 里轻读 [ə]（语速快时可省略）；结尾 -ment 读 [mɑ̃]，t 不发音。","pi":"拼写有两个 p；结尾 -ment 的 t 不发音。英语 apartment 只有一个 p。","et":"来自意大利语 appartamento（分开的房间），16 世纪借入法语。同源：à part（分开）。","ex":[["J'ai un bel appartement.","我有一套漂亮的公寓。"],["Leur appartement est au troisième étage.","他们的公寓在四楼。"],["Nous cherchons un appartement à louer.","我们在找出租的公寓。"]],"co":[["un appartement à louer","出租公寓"],["un appartement de deux pièces","两居室"],["habiter dans un appartement","住在公寓里"],["un immeuble d'appartements","公寓楼"]],"sy":[["appart","familier","公寓（口语缩写）"],["studio","courant","单间公寓"],["logement","courant","住所，住宅（通称）"]],"fq":"高频，日常常用。","me":"appartement = à part + ment：与别人「分开」的住处。","tr":{"zh":"我们的公寓有两个房间。","fr":"Notre appartement a deux pièces.","alt":"Notre appart a deux pièces.","note":"法语算房间用 pièces（不含厨房浴室）。"}},
 "Un arrondissement": {"pos":"n.m. 阳性名词，复数 arrondissements","s":"区；行政区。巴黎分为 20 个 arrondissements，缩写为 1er、2e ... 20e。里昂、马赛也有分区。","ipa":"[a.ʁɔ̃.dis.mɑ̃]","ph":"rr 读一个 [ʁ]；on [ɔ̃]；dis [dis]；ment [mɑ̃]。四个音节。","pi":"拼写：rr 和 ss 都是双写。词尾 t 不发音。序数写 18e 或 18ème 都可以。","et":"来自动词 arrondir（使变圆，划分），而 arrondir 来自 rond（圆的）。","ex":[["Elle habite dans le 18e arrondissement de Paris.","她住在巴黎 18 区。"],["Quel arrondissement préfères-tu ?","你最喜欢哪个区？"],["Le Louvre est dans le 1er arrondissement.","卢浮宫在 1 区。"]],"co":[["le 5e arrondissement","第 5 区"],["dans quel arrondissement ?","在哪个区？"],["un arrondissement de Paris","巴黎的一个区"]],"sy":[["quartier","courant","街区（不一定是官方行政区）"],["district","courant","地区（泛称）"]],"fq":"中频，主要用于巴黎话题。","me":"arrondissement ← rond：地图上被划成一圈圈的区。","tr":{"zh":"我朋友住在巴黎 11 区。","fr":"Mon ami habite dans le 11e arrondissement de Paris.","alt":"Mon pote habite dans le 11e, à Paris.","note":"说区号时常省略 arrondissement：le 11e。"}},
 "Un bar": {"pos":"n.m. 阳性名词，复数 bars","s":"酒吧；吧台。可指卖酒的小店，也可指柜台（comptoir）。法国人也在 bar 里喝咖啡。","ipa":"[baʁ]","ph":"结尾 r 要发 [ʁ]（喉音）。只有一个音节。","pi":"r 不能省略，也不是英语的 bar [bɑː]。复数 bars 的 s 不发音。","et":"19 世纪借自英语 bar（吧台，横木）。","ex":[["Il boit un verre au bar.","他在吧台喝一杯。"],["On se retrouve dans un bar ce soir ?","今晚我们在酒吧见吗？"],["Ce bar est très calme.","这家酒吧很安静。"]],"co":[["aller dans un bar","去酒吧"],["au bar","在吧台"],["un bar à vin","葡萄酒吧"],["un bar à cocktails","鸡尾酒吧"]],"sy":[["café","courant","咖啡馆（法国常见，也卖酒）"],["pub","courant","英式酒吧"],["troquet","familier","小酒馆"]],"fq":"中高频，日常常用。","me":"bar 的 r 要发出声，像在喉咙里轻轻「啊」。","tr":{"zh":"我们在酒吧见面吧。","fr":"On se retrouve au bar.","alt":"On se retrouve dans un bar ?","note":"on 口语中表示「我们」；se retrouver = 约见。"}},
 "Un cadeau": {"pos":"n.m. 阳性名词，复数 cadeaux","s":"礼物。送礼物：faire un cadeau (à qqn) 或 offrir un cadeau。Cadeau ! 在口语中也可以说「送你的！」","ipa":"[ka.do]","ph":"ca [ka]；eau [o]；两个音节。","pi":"复数是 cadeaux（加 x，不是 s）。eau 读 [o]，不读 [e]。","et":"来自普罗旺斯语 capdel，源自拉丁语 capitellum（小头）。本来指书法中的花饰，后来指宴会招待，最后才是「礼物」。","ex":[["J'ai un cadeau pour toi.","我有一份礼物给你。"],["Elle m'a offert un beau cadeau.","她送了我一份漂亮的礼物。"],["Les enfants ouvrent leurs cadeaux.","孩子们拆礼物。"]],"co":[["faire un cadeau à ...","送……一份礼物"],["un cadeau de Noël","圣诞礼物"],["un paquet cadeau","礼品包装"],["Ce n'est pas un cadeau.","这可不是好差事。"]],"sy":[["présent","soutenu","礼物（书面）"],["don","soutenu","捐赠；天赋"]],"fq":"高频，日常常用。","me":"cadeau 复数是 cadeaux：礼物多多，所以 x。","tr":{"zh":"这是给你的生日礼物。","fr":"C'est un cadeau d'anniversaire pour toi.","alt":"Tiens, c'est ton cadeau d'anniv !","note":"cadeau d'anniversaire = 生日礼物（de + 名词不加冠词）。"}},
 "Un champignon": {"pos":"n.m. 阳性名词，复数 champignons","s":"蘑菇；菌类。也说 champignon de Paris（白蘑菇）。在口语中 appuyer sur le champignon = 猛踩油门。","ipa":"[ʃɑ̃.pi.ɲɔ̃]","ph":"ch [ʃ]；am [ɑ̃]；gn [ɲ]（像「尼」）；on [ɔ̃]。三个音节。","pi":"gn 读 [ɲ]，不是分开的 g + n；结尾 n 不发音（鼻化）。","et":"源于拉丁语 campania（原野），与 champ（田野）同族：蘑菇生长在田野里。","ex":[["C'est un champignon rouge.","这是一个红蘑菇。"],["J'aime les champignons à la crème.","我爱奶油蘑菇。"],["Ne mange pas ce champignon, il est dangereux.","别吃这个蘑菇，它有危险。"]],"co":[["un champignon sauvage","野蘑菇"],["ramasser des champignons","采蘑菇"],["une omelette aux champignons","蘑菇煎蛋卷"],["appuyer sur le champignon","猛踩油门"]],"sy":[["cèpe","courant","牛肝菌（一种野蘑菇）"],["truffe","courant","松露（珍贵的菌类）"]],"fq":"中频，饮食话题常用。","me":"champ + ignon：长在 champ（田野）里的东西。","tr":{"zh":"我们去森林里采蘑菇。","fr":"Nous allons ramasser des champignons dans la forêt.","alt":"On va ramasser des champignons en forêt.","note":"aller + 动词原形表示近期的计划。"}},
 "Un escargot": {"pos":"n.m. 阳性名词，复数 escargots","s":"蜗牛。在餐馆里常指法式焗蜗牛（des escargots à l'ail）。比喻「很慢」：avancer comme un escargot。","ipa":"[ɛs.kaʁ.ɡo]","ph":"e 读 [ɛ]；sc 读 [sk]；ar [aʁ]；got 读 [ɡo]，结尾 t 不发音。","pi":"词尾 -ot 的 t 不发音；g 在 o 前读 [ɡ]。","et":"来自普罗旺斯语 escaragol；更早的来源不确定。","ex":[["Je vois un escargot.","我看到一只蜗牛。"],["Il pleut, les escargots sortent.","下雨了，蜗牛出来了。"],["Nous mangeons des escargots à Noël.","我们圣诞节吃蜗牛。"]],"co":[["des escargots à l'ail","蒜香蜗牛"],["lent comme un escargot","慢得像蜗牛"],["une coquille d'escargot","蜗牛壳"],["avancer comme un escargot","慢吞吞地走"]],"sy":[["limace","courant","蛞蝓（没有壳的）"],["tortue","courant","乌龟（也指慢）"]],"fq":"中低频；饮食和自然话题。","me":"es-car-GO：慢慢地「go」，像蜗牛。","tr":{"zh":"我不吃蜗牛。","fr":"Je ne mange pas d'escargots.","alt":"Je mange pas d'escargots.","note":"否定后 des 变 d'：pas d'escargots。"}},
 "Un fils": {"pos":"n.m. 阳性名词，单复数同形 fils","s":"儿子。单复数写法一样：un fils / des fils。注意 fils [fis] 里 s 要发音。le fils unique = 独生子。","ipa":"[fis]","ph":"f [f]；i [i]；s 在这个词里读 [s]（例外），l 不发音。","pi":"fils 读 [fis]，不是 [fil]。和 fil（线）、file（队列）不同。注意 fils 的 s 要读。","et":"拉丁语 filius（儿子）。同源：fille（女儿）、filial（子女的）。","ex":[["Ils ont un fils.","他们有一个儿子。"],["Mon fils a dix ans.","我儿子十岁。"],["Le fils de Marc est médecin.","马克的儿子是医生。"]],"co":[["le fils de ...","……的儿子"],["un fils unique","独生子"],["de père en fils","代代相传"],["le fils aîné / cadet","长子 / 小儿子"]],"sy":[["garçon","courant","男孩（也可指儿子）"],["gamin","familier","小孩，小家伙"]],"fq":"极高频，家庭话题。","me":"fils 的 s 要读：像「飞丝」，别读成 fil。","tr":{"zh":"我儿子喜欢踢足球。","fr":"Mon fils aime jouer au foot.","alt":"Mon fils, il adore jouer au foot.","note":"jouer au + 运动。"}},
 "Un frère": {"pos":"n.m. 阳性名词，复数 frères","s":"兄弟；哥哥；弟弟。法语不区分兄和弟：un grand frère = 哥哥，un petit frère = 弟弟。也可以指教会的修士。","ipa":"[fʁɛʁ]","ph":"fr [fʁ]；è [ɛ]；结尾 r 要发 [ʁ]。一个音节，有两个 r 音。","pi":"注意重音符号 è。词尾 r 要发。不能分哥哥弟弟，需要时加 grand / petit。","et":"拉丁语 frater。同源：fraternel（兄弟般的）、confrère（同行）。","ex":[["J'ai un frère.","我有一个兄弟。"],["Mon petit frère a six ans.","我弟弟六岁。"],["Mes frères jouent au foot.","我的兄弟们在踢足球。"]],"co":[["un grand frère","哥哥"],["un petit frère","弟弟"],["un demi-frère","同父异母 / 同母异父的兄弟"],["frère et sœur","兄妹，姐弟"]],"sy":[["frangin","familier","兄弟（口语）"],["bro","argot","兄弟（受英语影响）"]],"fq":"极高频，家庭话题。","me":"frère 与 fraternité 同族：兄弟情。","tr":{"zh":"我哥哥住在里昂。","fr":"Mon grand frère habite à Lyon.","alt":"Mon frère, il habite à Lyon.","note":"grand frère 指哥哥，petit frère 指弟弟。"}},
 "Un gâteau": {"pos":"n.m. 阳性名词，复数 gâteaux","s":"蛋糕；糕点。un gâteau d'anniversaire = 生日蛋糕。也可泛指饼干 (gâteau sec) 或甜点。c'est du gâteau ! = 小菜一碟！","ipa":"[ɡa.to]","ph":"â [ɑ] 或 [a]，现代发音 [a]；eau [o]。两个音节。","pi":"复数是 gâteaux，不是 gâteaus。别忘了 â 上的帽子（circonflexe）。","et":"古法语 gastel，可能来自法兰克语 *wastil（食物）。","ex":[["Je mange un gâteau.","我吃一块蛋糕。"],["Ma grand-mère fait des gâteaux.","我奶奶做蛋糕。"],["Ce gâteau au chocolat est délicieux.","这个巧克力蛋糕很好吃。"]],"co":[["un gâteau au chocolat","巧克力蛋糕"],["un gâteau d'anniversaire","生日蛋糕"],["faire un gâteau","做蛋糕"],["C'est du gâteau.","小菜一碟。"]],"sy":[["pâtisserie","courant","糕点（小的，店里买）"],["tarte","courant","馅饼，塔"]],"fq":"高频，日常常用。","me":"gâteau 的 â 像一顶帽子，戴在蛋糕上。","tr":{"zh":"我们明天做巧克力蛋糕吧。","fr":"Faisons un gâteau au chocolat demain.","alt":"On fait un gâteau au chocolat demain ?","note":"Faisons 是 nous 的命令式，表示「我们一起做」。"}},
 "Un instrument de musique": {"pos":"n.m. 阳性名词词组，复数 des instruments de musique","s":"乐器。instrument 单独也可指「工具」。演奏乐器用 jouer de + 乐器：jouer de la guitare。","ipa":"[ɛ̃s.tʁy.mɑ̃ də my.zik]","ph":"in [ɛ̃]；u 读 [y]；ment [mɑ̃]；de 轻读 [də]；mu [my]；si [zi]（s 在元音间读 [z]）；que [k]。","pi":"u 读 [y]，不是 [u]。musique 中的 s 读 [z]，qu 读 [k]。","et":"instrument 来自拉丁语 instrumentum（工具）；musique 来自拉丁语 musica，源自希腊语 mousikē（缪斯艺术）。","ex":[["Je joue d'un instrument de musique.","我会演奏乐器。"],["Le piano est un instrument de musique.","钢琴是一种乐器。"],["Quel instrument de musique joues-tu ?","你演奏什么乐器？"]],"co":[["jouer d'un instrument","演奏乐器"],["un instrument à cordes / à vent","弦乐器 / 管乐器"],["un instrument de musique traditionnel","传统乐器"]],"sy":[["instrument","courant","乐器（省略 de musique 也行）"],["outil","courant","工具（非音乐）"]],"fq":"中频，爱好话题。","me":"instrument 听起来像英语，但 u 要噘嘴 [y]。","tr":{"zh":"你会演奏乐器吗？","fr":"Tu joues d'un instrument de musique ?","alt":"Tu joues d'un instrument ?","note":"jouer DE + 乐器；jouer À + 游戏、运动。"}},
 "Un livre": {"pos":"n.m. 阳性名词，复数 livres","s":"书。注意：une livre（阴性）是「磅」或旧货币「里弗」。un livre 是书。","ipa":"[livʁ]","ph":"li [li]；vre 读 [vʁ]，e 不发音。一个音节。","pi":"结尾 -vre：e 不发音。小心：librairie 是书店，不是图书馆（bibliothèque）。","et":"拉丁语 liber（书，原义是树皮内层）。同源：librairie（书店）、bibliothèque 则来自希腊语。","ex":[["Je lis un livre.","我读一本书。"],["Ce livre est très intéressant.","这本书很有趣。"],["Elle écrit un livre sur Paris.","她在写一本关于巴黎的书。"]],"co":[["lire un livre","读书"],["un livre de cuisine","食谱"],["un livre de poche","袖珍书"],["traduire à livre ouvert","不经准备地直接翻译"]],"sy":[["bouquin","familier","书（口语）"],["ouvrage","soutenu","著作"]],"fq":"极高频，日常常用。","me":"livre 里有 liv，像 live 的开头；读书让你活。","tr":{"zh":"我正在读一本很好的书。","fr":"Je lis un très bon livre.","alt":"Je suis en train de lire un super livre.","note":"bon 放在 livre 前面。"}},
 "Un métro": {"pos":"n.m. 阳性名词，复数 métros","s":"地铁。是 métropolitain 的缩写。乘地铁：prendre le métro。巴黎地铁线用数字，如 ligne 1。","ipa":"[me.tʁo]","ph":"mé [me]；tro [tʁo]；两个音节，重音在最后。","pi":"é 有重音；r 要发 [ʁ]。别说成英语 [ˈmetroʊ]。","et":"métro 是 (chemin de fer) métropolitain 的缩写，由希腊语 metropolis（母邦，大城市）而来。","ex":[["Le métro est rapide.","地铁很快。"],["Je prends le métro tous les jours.","我每天坐地铁。"],["La station de métro est près d'ici.","地铁站离这里很近。"]],"co":[["prendre le métro","坐地铁"],["une station de métro","地铁站"],["un ticket de métro","地铁票"],["métro, boulot, dodo","朝九晚五的生活（通勤、工作、睡觉）"]],"sy":[["RER","courant","大巴黎区域快铁"],["tramway","courant","有轨电车"]],"fq":"高频，城市生活。","me":"métro 像 metropolis：大城市的列车。","tr":{"zh":"我每天坐地铁去上班。","fr":"Je prends le métro pour aller au travail tous les jours.","alt":"Je vais au boulot en métro.","note":"prendre le métro / aller en métro。"}},
 "Un oncle": {"pos":"n.m. 阳性名词，复数 oncles","s":"叔叔；舅舅；伯伯；姑父。法语不区分父亲这边和母亲这边，都是 oncle。","ipa":"[ɔ̃kl]","ph":"on [ɔ̃]；cle 读 [kl]，e 不发音。一个音节。","pi":"on 读鼻化 [ɔ̃]，不是 [on]。词尾 -cle 的 e 不发音：oncle = [ɔ̃kl]。","et":"拉丁语 avunculus（母亲的兄弟），后来泛指所有叔伯舅。","ex":[["Mon oncle habite ici.","我叔叔住在这里。"],["Mon oncle et ma tante arrivent demain.","我叔叔和阿姨明天到。"],["L'oncle de Paul est pilote.","保罗的叔叔是飞行员。"]],"co":[["un oncle paternel / maternel","叔伯 / 舅舅"],["oncle et tante","叔叔阿姨"],["mon grand-oncle","我的叔祖父"]],"sy":[["tonton","familier","叔叔（亲昵）"],["tante","courant","对应词：阿姨"]],"fq":"中高频，家庭话题。","me":"oncle 读 [ɔ̃kl]：on 像「翁」，后面接 kl。","tr":{"zh":"我舅舅在法国生活。","fr":"Mon oncle vit en France.","alt":"Mon oncle habite en France.","note":"国家（阴性）用 en：en France。"}},
 "Un petit-fils": {"pos":"n.m. 阳性名词，复数 petits-fils","s":"孙子；外孙。女孩是 petite-fille。法语不分孙子和外孙。","ipa":"[pə.ti.fis]","ph":"pe [pə]（轻读）；ti [ti]；fils [fis]（s 发音）。三个音节。","pi":"复数 petits-fils（petit 加 s，fils 不变）。fils 的 s 要读。","et":"petit（小）+ fils（儿子）= 儿子的儿子。petit 来自通俗拉丁语，来源不太确定。","ex":[["C'est mon petit-fils.","这是我的孙子。"],["Mon petit-fils a cinq ans.","我的孙子五岁。"],["Ses petits-fils jouent dans le jardin.","他的孙子们在花园里玩。"]],"co":[["mon petit-fils","我的孙子"],["un arrière-petit-fils","曾孙"],["les petits-enfants","孙子女"]],"sy":[["petit-enfant","courant","孙辈（泛称）"],["petite-fille","courant","孙女（阴性对应词）"]],"fq":"中频，家庭话题。","me":"petit-fils = 小小儿子 = 儿子的儿子。","tr":{"zh":"我的孙子喜欢蛋糕。","fr":"Mon petit-fils aime le gâteau.","alt":"Mon petit-fils adore les gâteaux.","note":"aimer + 定冠词（le gâteau）。"}},
 "Un quartier": {"pos":"n.m. 阳性名词，复数 quartiers","s":"街区；社区；地区。指城市里的一块区域，也可指「四分之一」（un quartier de lune）。","ipa":"[kaʁ.tje]","ph":"qu [k]；ar [aʁ]；tier 读 [tje]，ier 变成 [je]。两个音节。","pi":"qu 读 [k]，不读 [kw]。结尾 -ier 读 [je]，r 不发音。","et":"拉丁语 quartarius（四分之一），来自 quartus（第四）。同源：quart（四分之一）。","ex":[["Mon quartier est calme.","我的街区很安静。"],["Il y a une boulangerie dans mon quartier.","我的街区有一家面包店。"],["Nous habitons dans un quartier ancien.","我们住在一个老街区。"]],"co":[["dans le quartier","在这个街区"],["un quartier calme","安静的街区"],["le quartier latin","拉丁区（巴黎）"],["les gens du quartier","街坊邻居"]],"sy":[["arrondissement","courant","行政区（官方）"],["banlieue","courant","郊区"]],"fq":"高频，城市生活。","me":"quartier ← quart：城市的「四分之一」。","tr":{"zh":"我们的街区有很多商店。","fr":"Notre quartier a beaucoup de magasins.","alt":"Dans notre quartier, il y a plein de magasins.","note":"beaucoup de + 名词。"}},
 "Un restaurant": {"pos":"n.m. 阳性名词，复数 restaurants","s":"餐厅；饭馆。去餐厅：aller au restaurant，在餐厅：au restaurant。口语缩写 resto。","ipa":"[ʁɛs.tɔ.ʁɑ̃]","ph":"r [ʁ]；es [ɛs]；to [tɔ]；rant [ʁɑ̃]，t 不发音。法语是三个音节，英语是两个。","pi":"结尾 -ant 读 [ɑ̃]，t 不发音。结尾拼写是 -ant，不是 -ent。","et":"来自动词 restaurer（恢复），拉丁语 restaurare。最初指提神的浓汤。","ex":[["Nous allons au restaurant.","我们去餐厅。"],["Ce restaurant est très bon.","这家餐厅很好。"],["Je réserve une table au restaurant.","我在餐厅订一张桌子。"]],"co":[["aller au restaurant","去餐厅"],["réserver une table","订桌"],["un restaurant italien","意大利餐厅"],["manger au restaurant","在餐厅吃饭"]],"sy":[["resto","familier","餐馆（口语）"],["brasserie","courant","大众餐馆"],["bistrot","courant","小酒馆"]],"fq":"极高频，日常常用。","me":"res-to-rant：三拍，别漏掉中间的 to。","tr":{"zh":"今晚我们去餐厅吃饭吧。","fr":"Ce soir, nous mangeons au restaurant.","alt":"Ce soir, on va au resto.","note":"aller au restaurant 用 au (à + le)。"}},
 "Un train": {"pos":"n.m. 阳性名词，复数 trains","s":"火车。法国高速列车是 TGV。坐火车：prendre le train。en train de + 动词原形 = 正在做某事（不是名词的意思）。","ipa":"[tʁɛ̃]","ph":"tr [tʁ]；ain 读鼻化 [ɛ̃]；结尾 n 不单独发音。一个音节。","pi":"ain 读 [ɛ̃]，不读 [ain]；r 在 t 后要发。别说成英语 [treɪn]。","et":"与 traîner（拖，拉）同族。原指一列被拖着走的东西。","ex":[["Je prends le train.","我坐火车。"],["Le train part à huit heures.","火车八点出发。"],["Je suis en train de manger.","我正在吃饭。"]],"co":[["prendre le train","坐火车"],["rater son train","错过火车"],["en train de + inf.","正在……"],["une gare de train","火车站"]],"sy":[["TGV","courant","高速列车"],["RER","courant","区域快铁"]],"fq":"极高频，日常常用。","me":"train 和 pain（面包）的 ain 读音一样，都是 [ɛ̃]。","tr":{"zh":"我明天早上坐火车去巴黎。","fr":"Demain matin, je prends le train pour Paris.","alt":"Demain matin, je vais à Paris en train.","note":"prendre le train / aller en train。"}},
 "La danse": {"pos":"n.f. 阴性名词，复数 danses","s":"舞蹈；跳舞。也可指某一种舞，如 la danse classique（芭蕾）。动词是 danser。","ipa":"[dɑ̃s]","ph":"d [d]；an 读鼻化 [ɑ̃]；se 读 [s]，e 不发音。一个音节。","pi":"an 读 [ɑ̃]，不读 [æn]。结尾 -se 读 [s]，不读 [z]。","et":"来自动词 danser；来源不确定，可能来自日耳曼语。","ex":[["La danse est ma passion.","舞蹈是我的热情所在。"],["Elle fait de la danse classique.","她学古典芭蕾。"],["Il y a un cours de danse ce soir.","今晚有舞蹈课。"]],"co":[["faire de la danse","跳舞（学舞蹈）"],["un cours de danse","舞蹈课"],["la danse classique / moderne","古典 / 现代舞"],["une danse traditionnelle","传统舞"]],"sy":[["ballet","courant","芭蕾舞"],["bal","courant","舞会"]],"fq":"中高频，爱好话题。","me":"danse 像 dance，只是 an 变成鼻音。","tr":{"zh":"我女儿每周跳两次舞。","fr":"Ma fille fait de la danse deux fois par semaine.","alt":"Ma fille danse deux fois par semaine.","note":"faire de la + 活动（部分冠词）。"}},
 "La femme": {"pos":"n.f. 阴性名词，复数 femmes","s":"女人；妻子。ma femme = 我妻子，une femme = 一位女士。意思看上下文，有物主词时多指「妻子」。","ipa":"[fam]","ph":"f [f]；e 在 fem- 中读 [a]（特例），所以 femme = [fam]。mm 只读一个 [m]。","pi":"femme 读 [fam]，不是 [fɛm]。很多人会读错。","et":"拉丁语 femina（女人）。同源：féminin（阴性的）。","ex":[["C'est la femme de Thomas.","这是托马斯的妻子。"],["Cette femme est médecin.","这位女士是医生。"],["Ma femme et moi aimons voyager.","我妻子和我喜欢旅行。"]],"co":[["la femme de ...","……的妻子"],["une femme de ménage","家政女工"],["une femme d'affaires","女商人"],["une jeune femme","年轻女子"]],"sy":[["épouse","soutenu","妻子（正式）"],["dame","courant","女士"]],"fq":"极高频，日常常用。","me":"femme 读 [fam]：e 变成 a，像「发姆」。","tr":{"zh":"我妻子在银行工作。","fr":"Ma femme travaille dans une banque.","alt":"Ma femme bosse dans une banque.","note":"travailler dans une banque。"}},
 "La grand-mère": {"pos":"n.f. 阴性名词，复数 grands-mères","s":"祖母；外祖母。不分父系母系。口语 mamie / mémé 是「奶奶、外婆」。","ipa":"[ɡʁɑ̃.mɛʁ]","ph":"gr [gʁ]；an [ɑ̃]；è [ɛ]；r 要发。d 不发音。","pi":"复数 grands-mères（grand 加 s，mère 加 s）。grand 在这里不变阴性（不写 grande-mère）。","et":"grand + mère（拉丁语 mater）。同源：maternel（母亲的）。","ex":[["Ma grand-mère fait un gâteau.","我奶奶做了一个蛋糕。"],["Mamie, tu viens dîner ?","奶奶，你来吃晚饭吗？"],["Ma grand-mère habite à la campagne.","我外婆住在乡下。"]],"co":[["ma grand-mère maternelle / paternelle","我的外婆 / 奶奶"],["une arrière-grand-mère","曾祖母"],["recette de grand-mère","传统家常菜谱"]],"sy":[["mamie / mémé","familier","奶奶，外婆"],["aïeule","littéraire","祖母，祖先"]],"fq":"高频，家庭话题。","me":"grand（大）+ mère = 大妈妈 = 奶奶。","tr":{"zh":"我奶奶会做很好吃的饭。","fr":"Ma grand-mère fait de la très bonne cuisine.","alt":"Ma grand-mère cuisine super bien.","note":"faire de la cuisine = 做饭。"}},
 "La marche": {"pos":"n.f. 阴性名词，复数 marches","s":"步行；散步；台阶；游行。la marche = 走路这项活动，也说 faire de la marche。另有 une marche = 一级台阶。","ipa":"[maʁʃ]","ph":"ar [aʁ]；ch [ʃ]；e 不发音。一个音节。","pi":"la marche（走）与 le marché（市场）不同：marche 没有 é，读 [maʁʃ]；marché = [maʁ.ʃe]。","et":"来自动词 marcher；更早的来源不确定。","ex":[["La marche est bonne pour la santé.","步行对健康有益。"],["Attention à la marche !","小心台阶！"],["Elle fait de la marche tous les matins.","她每天早上去走路。"]],"co":[["faire de la marche","走路锻炼"],["la marche à pied","步行"],["une marche rapide","快走"],["en marche","运转中"]],"sy":[["promenade","courant","散步（轻松）"],["randonnée","courant","徒步"]],"fq":"中频，日常常用。","me":"marche 没有 é：「走」，而 marché 有 é：「市场」。","tr":{"zh":"我喜欢周末散步。","fr":"J'aime la marche le week-end.","alt":"J'adore marcher le week-end.","note":"la marche 是名词；动词用 marcher。"}},
 "La mère": {"pos":"n.f. 阴性名词，复数 mères","s":"母亲。口语是 maman。la mère de famille = 家庭主妇、母亲。","ipa":"[mɛʁ]","ph":"m [m]；è [ɛ]；r 要发 [ʁ]。一个音节。","pi":"mère 与 mer（海）、maire（市长）同音 [mɛʁ]，要靠上下文区分。","et":"拉丁语 mater。同源：maternel（母亲的）。","ex":[["Ma mère est à la maison.","我妈妈在家。"],["La mère de Léa est professeure.","蕾娅的妈妈是老师。"],["Maman prépare le dîner.","妈妈在准备晚饭。"]],"co":[["la mère de ...","……的母亲"],["une mère de famille","有孩子的母亲"],["la fête des mères","母亲节"],["une belle-mère","婆婆 / 岳母 / 继母"]],"sy":[["maman","familier","妈妈"],["génitrice","soutenu","生母"]],"fq":"极高频，家庭必学。","me":"mère 听起来像「mer」（海）：妈妈像大海。","tr":{"zh":"我妈妈每天做饭。","fr":"Ma mère fait la cuisine tous les jours.","alt":"Ma mère cuisine tous les jours.","note":"tous les jours = 每天。"}},
 "La musculation": {"pos":"n.f. 阴性名词，通常用单数","s":"肌肉训练；健身；重量训练。常说 faire de la musculation 或口语 faire de la muscu。","ipa":"[mys.ky.la.sjɔ̃]","ph":"u 读 [y]（两处）；ti 读 [sj]；on 读 [ɔ̃]。结尾 -tion 是 [sjɔ̃]。","pi":"mus-cu 两个 u 都读 [y]。-tion 读 [sjɔ̃]，不是英语的 [ʃən]。","et":"由 muscle（肌肉，拉丁语 musculus，「小老鼠」）+ 后缀 -ation 构成。","ex":[["Il fait de la musculation.","他在做肌肉训练。"],["Je fais de la musculation trois fois par semaine.","我每周做三次健身。"],["La salle de musculation est au sous-sol.","健身房在地下室。"]],"co":[["faire de la musculation","做肌肉训练"],["une salle de musculation","健身房"],["un cours de musculation","健身课"],["faire de la muscu","去健身（口语）"]],"sy":[["muscu","familier","健身（缩写）"],["fitness","courant","健身运动"],["gym","familier","健身房 / 体操"]],"fq":"中频，运动话题。","me":"musculation = muscle + action：让肌肉动起来。","tr":{"zh":"我每周去做两次健身。","fr":"Je fais de la musculation deux fois par semaine.","alt":"Je fais de la muscu deux fois par semaine.","note":"faire de la + 运动。"}},
 "La natation": {"pos":"n.f. 阴性名词，复数 natations（很少用）","s":"游泳（作为运动）。faire de la natation = 游泳。「游泳」这个动作是 nager。","ipa":"[na.ta.sjɔ̃]","ph":"na [na]；ta [ta]；ti 读 [sj]；on [ɔ̃]。四个音节。","pi":"-tion 读 [sjɔ̃]。别说成 swimming：natation 是体育项目，nager 是动作。","et":"拉丁语 natatio，来自 natare（游泳）。同源：nager（游）、nageur（游泳者）。","ex":[["J'aime la natation.","我喜欢游泳。"],["Elle fait de la natation le mardi.","她星期二游泳。"],["Il y a un cours de natation pour les enfants.","有儿童游泳课。"]],"co":[["faire de la natation","游泳（运动）"],["un cours de natation","游泳课"],["un maillot de natation","泳衣"],["une piscine","游泳池"]],"sy":[["nage","courant","游泳（泛指）"],["piscine","courant","游泳池（地方）"]],"fq":"中频，运动话题。","me":"na-ta-tion：两个 na-ta 像划水的节奏。","tr":{"zh":"我女儿每周六游泳。","fr":"Ma fille fait de la natation le samedi.","alt":"Ma fille nage le samedi.","note":"le samedi 表示每个星期六。"}},
 "Une famille": {"pos":"n.f. 阴性名词，复数 familles","s":"家庭；家人。une grande famille = 大家庭。也指家族、一类事物（la famille des mots = 词族）。","ipa":"[fa.mij]","ph":"fa [fa]；mille 读 [mij]（-ille 读 [ij]）。两个音节。","pi":"-ille 读 [ij]，不读 [il]。结尾 e 不发音。","et":"拉丁语 familia（一家人，含仆人）。","ex":[["J'ai une grande famille.","我有一个大家庭。"],["Ma famille habite à Lyon.","我家人住在里昂。"],["Nous mangeons en famille le dimanche.","我们星期天和家人一起吃饭。"]],"co":[["une grande famille","大家庭"],["en famille","和家人一起"],["un repas de famille","家庭聚餐"],["une famille nombreuse","多子女家庭"]],"sy":[["parents","courant","亲戚"],["foyer","soutenu","家庭，家"]],"fq":"极高频，日常常用。","me":"famille 像 family，但结尾读 [mij]。","tr":{"zh":"我和家人一起吃饭。","fr":"Je mange en famille.","alt":"Je mange avec ma famille.","note":"en famille = 和家人一起（无冠词）。"}},
 "Une fille": {"pos":"n.f. 阴性名词，复数 filles","s":"女儿；女孩。ma fille = 我女儿，une fille = 一个女孩。Jeune fille = 少女。","ipa":"[fij]","ph":"f [f]；-ille 读 [ij]。一个音节。","pi":"fille 读 [fij]，l 不单独发音。别和 file、fil 混。","et":"拉丁语 filia（女儿）。同源：fils（儿子）。","ex":[["C'est ma fille.","这是我的女儿。"],["Cette fille est très gentille.","这个女孩很友善。"],["Ils ont deux filles.","他们有两个女儿。"]],"co":[["la fille de ...","……的女儿"],["une jeune fille","少女"],["une petite fille","小女孩"],["une fille unique","独生女"]],"sy":[["gamine","familier","小姑娘"],["demoiselle","soutenu","小姐"]],"fq":"极高频，日常常用。","me":"fille 与 fils 一组：fille（女）/ fils（男）。","tr":{"zh":"我女儿八岁。","fr":"Ma fille a huit ans.","alt":"Ma fille a huit ans, elle est en CE2.","note":"年龄用 avoir ... ans。"}},
 "Une gare": {"pos":"n.f. 阴性名词，复数 gares","s":"火车站。la gare = 车站，la gare routière = 长途汽车站。去车站：aller à la gare。","ipa":"[ɡaʁ]","ph":"ga [ga]；re 读 [ʁ]，e 不发音。结尾 r 要发。","pi":"gare 不是 garage。单词里 r 要发。","et":"来自动词 garer（把船靠边），可能源自日耳曼语。","ex":[["La gare est près d'ici.","车站离这里很近。"],["Je retrouve mon frère à la gare.","我在车站见我哥哥。"],["Le train arrive en gare à midi.","火车中午进站。"]],"co":[["aller à la gare","去车站"],["la gare routière","长途汽车站"],["la gare de Lyon","里昂火车站"],["arriver en gare","进站"]],"sy":[["station","courant","站（地铁站、公交站）"],["terminus","courant","终点站"]],"fq":"高频，出行话题。","me":"gare [ɡaʁ] 和 guerre [ɡɛʁ]（战争）元音不同。","tr":{"zh":"火车站在哪儿？","fr":"Où est la gare ?","alt":"La gare, c'est où ?","note":"où est ... = 在哪儿。"}},
 "Une petite-fille": {"pos":"n.f. 阴性名词，复数 petites-filles","s":"孙女；外孙女。注意带连字符。une petite fille（无连字符）是「小女孩」。","ipa":"[pə.tit.fij]","ph":"pe [pə]；ti [ti]；te 读 [t]；fille [fij]。-tit 的 t 要发音（阴性）。","pi":"有连字符才是孙女。复数 petites-filles（两部分都加 s）。","et":"petite（小）+ fille（女儿）= 女儿的女儿。","ex":[["C'est ma petite-fille.","这是我的孙女。"],["Ma petite-fille a trois ans.","我的孙女三岁。"],["Elles sont les petites-filles de Marie.","她们是玛丽的孙女。"]],"co":[["ma petite-fille","我的孙女"],["une arrière-petite-fille","曾孙女"],["les petits-enfants","孙子女"]],"sy":[["petite fille","courant","小女孩（无连字符）"],["petit-enfant","courant","孙辈"]],"fq":"中频，家庭话题。","me":"连字符 = 家庭关系：petite-fille = 孙女。","tr":{"zh":"我的孙女喜欢画画。","fr":"Ma petite-fille aime dessiner.","alt":"Ma petite-fille adore dessiner.","note":"aimer + 动词原形。"}},
 "Une pomme": {"pos":"n.f. 阴性名词，复数 pommes","s":"苹果。une pomme de terre = 土豆。une pomme d'Adam = 喉结。","ipa":"[pɔm]","ph":"o 读 [ɔ]；mm 读一个 [m]；e 不发音。","pi":"pomme 不是 [pom]；o 开口。和 pomme de terre 一起记。","et":"拉丁语 pomum（果实），后来专指苹果。","ex":[["Je mange une pomme.","我吃一个苹果。"],["Ces pommes sont rouges.","这些苹果是红的。"],["Il aime les pommes de terre.","他喜欢土豆。"]],"co":[["une pomme rouge / verte","红 / 青苹果"],["une tarte aux pommes","苹果派"],["une pomme de terre","土豆"],["un jus de pomme","苹果汁"]],"sy":[["fruit","courant","水果（泛称）"],["patate","familier","土豆（pomme de terre）"]],"fq":"高频，日常常用。","me":"pomme de terre = 土里的苹果 = 土豆。","tr":{"zh":"我每天吃一个苹果。","fr":"Je mange une pomme tous les jours.","alt":"Je mange une pomme par jour.","note":"tous les jours / par jour。"}},
 "Une rue": {"pos":"n.f. 阴性名词，复数 rues","s":"街道；马路。dans la rue = 在街上。une rue piétonne = 步行街。","ipa":"[ʁy]","ph":"r [ʁ]；u 读 [y]（圆唇）。一个音节。","pi":"u 读 [y]，不读 [u]。rue 与 roue（轮子）不同。","et":"拉丁语 ruga（皱纹，沟），后来指街道。","ex":[["La rue est longue.","街道很长。"],["Il y a beaucoup de monde dans la rue.","街上有很多人。"],["J'habite rue Victor Hugo.","我住在雨果路。"]],"co":[["dans la rue","在街上"],["traverser la rue","穿过马路"],["une rue piétonne","步行街"],["au coin de la rue","在街角"]],"sy":[["avenue","courant","大街，林荫大道"],["boulevard","courant","大道"]],"fq":"极高频，日常常用。","me":"rue 读 [ʁy]：r 在喉咙，u 噘嘴。","tr":{"zh":"这条街很安静。","fr":"Cette rue est calme.","alt":"Cette rue est très tranquille.","note":"cette = 阴性名词前的「这」。"}},
 "Une soeur": {"pos":"n.f. 阴性名词，复数 sœurs（标准拼写 sœur）","s":"姐妹；姐姐；妹妹。不分长幼：une grande sœur = 姐姐，une petite sœur = 妹妹。也指修女（ma sœur）。","ipa":"[sœʁ]","ph":"s [s]；œu 读 [œ]；r 要发 [ʁ]。一个音节。","pi":"标准拼写是 sœur（œ 合字），打字时常简写成 soeur。读音 [sœʁ]，不是 [sør]。","et":"拉丁语 soror。同源：sororité（姐妹情谊）。","ex":[["J'ai une sœur.","我有一个姐妹。"],["Ma petite sœur a quatre ans.","我妹妹四岁。"],["Mes sœurs habitent à Paris.","我的姐妹们住在巴黎。"]],"co":[["une grande sœur","姐姐"],["une petite sœur","妹妹"],["une demi-sœur","同父异母 / 同母异父的姐妹"],["frères et sœurs","兄弟姐妹"]],"sy":[["frangine","familier","姐妹（口语）"],["sœurette","familier","小妹妹"]],"fq":"极高频，家庭必学。","me":"sœur 和 cœur 同韵：姐妹心连心。","tr":{"zh":"我姐姐在法国工作。","fr":"Ma grande sœur travaille en France.","alt":"Ma sœur travaille en France.","note":"grande sœur 指姐姐。"}},
 "Une tante": {"pos":"n.f. 阴性名词，复数 tantes","s":"姑姑；阿姨；舅妈；婶婶。不分父系母系。口语是 tata 或 tantine。","ipa":"[tɑ̃t]","ph":"t [t]；an [ɑ̃]；te 读 [t]。一个音节。","pi":"tante 的 an 是鼻音，后面的 t 要读出来：[tɑ̃t]。与 tant [tɑ̃]（那么多）不同。","et":"古法语 ante，来自拉丁语 amita（父亲的姐妹）；t 来自 ta ante 的连读。","ex":[["Ma tante est gentille.","我的阿姨很善良。"],["Ma tante habite à Marseille.","我姑姑住在马赛。"],["Tante Julie arrive demain.","朱莉姑姑明天到。"]],"co":[["ma tante","我的姑姑 / 阿姨"],["oncle et tante","叔叔阿姨"],["une grand-tante","姑婆 / 姨婆"],["la tante de Paul","保罗的阿姨"]],"sy":[["tata","familier","阿姨（亲昵）"],["tantine","familier","小阿姨（儿语）"]],"fq":"中高频，家庭话题。","me":"tante 的 t 要读两次：t-an-t。","tr":{"zh":"我阿姨明天来看我们。","fr":"Ma tante vient nous voir demain.","alt":"Ma tante passe nous voir demain.","note":"venir + 动词原形 = 来做某事。"}},
 "La copine / La petite-copine / La petite-amie / La meuf": {"pos":"n.f. 阴性名词（口语），复数 copines / petites-copines / petites-amies / meufs","s":"女朋友；女性朋友。copine 可以是女性朋友，也可以是女朋友，看上下文。petite amie 是标准说法。meuf 是口语，意思是「女人，女孩」，也可说「女朋友」。","ipa":"[kɔ.pin]","ph":"co [kɔ]；pi [pi]；ne 读 [n]。其他：meuf [mœf]。","pi":"copine 有两个意思，注意上下文。标准说法通常是 petite amie / petit ami，不带连字符。meuf 太随便，不要在正式场合用。","et":"copine 是 copain 的阴性；copain 来自拉丁语 companio（一起吃面包的人）。meuf 是 femme 的倒读（verlan）。","ex":[["C'est ma petite amie.","这是我的女朋友。"],["Ma copine s'appelle Léa.","我女朋友叫蕾娅。"],["Il sort avec une copine.","他和一位女性朋友出去。"]],"co":[["ma petite amie","我的女朋友"],["une copine de classe","女同学"],["sortir avec sa copine","和女朋友出去"],["une bonne copine","好朋友（女）"]],"sy":[["amie","courant","女性朋友（不一定是恋人）"],["compagne","soutenu","伴侣"],["meuf","argot","女人，女朋友"]],"fq":"高频，日常口语。","me":"copine ← copain ← 一起吃面包的人。","tr":{"zh":"我女朋友喜欢游泳。","fr":"Ma copine aime la natation.","alt":"Ma petite amie adore nager.","note":"aimer + 定冠词（la natation）。"}},
 "Le copain / Le petit-copain / Le petit-ami / Le mec": {"pos":"n.m. 阳性名词（口语），复数 copains / petits-amis / mecs","s":"男朋友；男性朋友。copain 可以是朋友，也可以是男朋友。petit ami 是标准说法。mec 是口语，意思是「家伙，男人」。","ipa":"[kɔ.pɛ̃]","ph":"co [kɔ]；pain 读 [pɛ̃]。其他：mec [mɛk]。","pi":"copain 的 ain 读 [ɛ̃]，不读 [ain]。copain 有两个意思。mec 是口语，别用于正式场合。","et":"来自拉丁语 companio（一起吃面包的人：con + panis）。mec 的来源不确定。","ex":[["C'est mon petit ami.","这是我的男朋友。"],["Mon copain travaille à Lyon.","我男朋友在里昂工作。"],["C'est un bon copain.","他是个好朋友。"]],"co":[["mon petit ami","我的男朋友"],["un copain d'école","同学"],["un bon copain","好朋友"],["un mec sympa","一个好人（口语）"]],"sy":[["ami","courant","朋友"],["compagnon","soutenu","伴侣"],["mec","argot","男人，家伙"]],"fq":"高频，日常口语。","me":"copain ← con + pain：一起吃面包的人。","tr":{"zh":"我男朋友是法国人。","fr":"Mon petit ami est français.","alt":"Mon copain est français.","note":"国籍作形容词，小写。"}},
 "Les grands-parents": {"pos":"n.m.pl. 阳性复数名词，单数很少用","s":"祖父母；外祖父母。指爷爷奶奶（或外公外婆）。口语 papi et mamie。","ipa":"[ɡʁɑ̃.pa.ʁɑ̃]","ph":"gr [gʁ]；an [ɑ̃]；pa [pa]；rents 读 [ʁɑ̃]，nts 不发音。d 和 s 不发音。","pi":"grands 的 d、s 都不发音；parents 结尾 -ents 读 [ɑ̃]。","et":"grand（大）+ parent（拉丁语 parens，生育者）。","ex":[["Je visite mes grands-parents.","我去看我的祖父母。"],["Mes grands-parents habitent à la campagne.","我的祖父母住在乡下。"],["On dîne chez les grands-parents dimanche.","周日我们在祖父母家吃晚饭。"]],"co":[["rendre visite à ses grands-parents","去看祖父母"],["chez mes grands-parents","在我祖父母家"],["les grands-parents paternels / maternels","爷爷奶奶 / 外公外婆"]],"sy":[["papi et mamie","familier","爷爷奶奶（亲昵）"],["aïeux","littéraire","祖先"]],"fq":"高频，家庭话题。","me":"grands-parents = 大家长们。","tr":{"zh":"我周末去看我祖父母。","fr":"Je rends visite à mes grands-parents le week-end.","alt":"Je vais voir mes grands-parents le week-end.","note":"rendre visite à + 人。"}},
 "Les parents": {"pos":"n.m.pl. 阳性复数名词","s":"父母；双亲。注意：法语 parents 也能指「亲戚」（un parent éloigné = 远房亲戚）。","ipa":"[pa.ʁɑ̃]","ph":"pa [pa]；rents 读 [ʁɑ̃]，nts 不发音。","pi":"结尾 -ents 读 [ɑ̃]，t 和 s 不发音。别读成英语 [ˈpɛərənts]。","et":"拉丁语 parens（生育者），来自 parere（生育）。同源：parent（亲戚）。","ex":[["Mes parents sont gentils.","我的父母很善良。"],["Mes parents habitent à Nice.","我父母住在尼斯。"],["Il est parent avec Marie.","他是玛丽的亲戚。"]],"co":[["mes parents","我的父母"],["les parents d'élèves","学生家长"],["un parent éloigné","远房亲戚"],["parents et amis","亲友"]],"sy":[["famille","courant","家人"],["père et mère","soutenu","父亲和母亲"]],"fq":"极高频，家庭必学。","me":"parents 双亲：par- 像 pair（一对）。","tr":{"zh":"我的父母住在尼斯。","fr":"Mes parents habitent à Nice.","alt":"Mes parents vivent à Nice.","note":"城市前用 à。"}},
 "Les petits-enfants": {"pos":"n.m.pl. 阳性复数名词，单数 petit-enfant","s":"孙子女；外孙子女。孙辈的总称，不分男女。","ipa":"[pə.ti.zɑ̃.fɑ̃]","ph":"petits 的 s 在后面元音前读 [z]（liaison）：petits-enfants = [pə.ti.zɑ̃.fɑ̃]。","pi":"要做联诵 petits_enfants。enfants 结尾的 -ts 不发音。","et":"petit（小）+ enfant（拉丁语 infans，不会说话的）。","ex":[["J'aime mes petits-enfants.","我爱我的孙子孙女们。"],["Ses petits-enfants viennent le dimanche.","他的孙辈星期天来。"],["Elle a quatre petits-enfants.","她有四个孙辈。"]],"co":[["avoir des petits-enfants","有孙辈"],["garder ses petits-enfants","照看孙辈"],["les petits-enfants de ...","……的孙辈"]],"sy":[["petite-fille","courant","孙女（阴性对应词）"],["petite-fille","courant","孙女"]],"fq":"中频，家庭话题。","me":"petits + enfants = 小小孩 = 孙辈。","tr":{"zh":"我外婆有五个孙辈。","fr":"Ma grand-mère a cinq petits-enfants.","alt":"Mamie a cinq petits-enfants.","note":"avoir + 数量 + 名词。"}},
 "Nord, Sud, Est, Ouest": {"pos":"n.m. 阳性名词（方向词）","s":"北，南，东，西。le nord, le sud, l'est, l'ouest。方向用 au nord de ... = 在……北边；l'est 和 l'ouest 要用 l' 缩合。","ipa":"[nɔʁ · syd · ɛst · wɛst]","ph":"nord [nɔʁ]（d 不发音）；sud [syd]（u 读 [y]，d 要发）；est [ɛst]；ouest [wɛst]（ou 读 [w]）。","pi":"nord 的 d 不发音，sud 的 d 要发。ouest 以 [w] 开头，est 和 ouest 要区分。","et":"这四个方向词借自日耳曼语（古英语）。","ex":[["Lille est au nord de Paris.","里尔在巴黎北边。"],["Marseille est dans le sud de la France.","马赛在法国南部。"],["Le soleil se couche à l'ouest.","太阳在西边落下。"]],"co":[["au nord / au sud de ...","在……北边 / 南边"],["à l'est / à l'ouest de ...","在……东边 / 西边"],["le nord-est / le sud-ouest","东北 / 西南"],["perdre le nord","迷失方向，不知所措"]],"sy":[["septentrion","littéraire","北方（文学用）"],["midi","courant","南方（法国南部）"]],"fq":"中高频，地理话题。","me":"SUD 的 d 响，NORD 的 d 静。","tr":{"zh":"尼斯在法国的南边。","fr":"Nice est dans le sud de la France.","alt":"Nice se trouve au sud de la France.","note":"dans le sud de ... = 在……南部。"}},
 "Un danseur / Une danseuse": {"pos":"n.m./n.f. 阳性 danseur，阴性 danseuse，复数 danseurs / danseuses","s":"舞者；舞蹈演员。阳性 danseur，阴性 danseuse。un danseur classique = 芭蕾舞者。","ipa":"[dɑ̃.sœʁ]","ph":"d [d]；an [ɑ̃]；seur [sœʁ]。阴性 danseuse [dɑ̃.søz]。","pi":"-seur 读 [sœʁ]，r 要发。阴性 -euse 读 [øz]，不是 [œz]。","et":"danser（跳舞）+ 后缀 -eur / -euse（表示做某事的人）。","ex":[["C'est un bon danseur.","他是个好舞者。"],["Elle est danseuse à l'Opéra.","她是歌剧院的舞者。"],["Les danseurs répètent chaque jour.","舞者们每天排练。"]],"co":[["un danseur classique","芭蕾舞者"],["une danseuse étoile","首席女舞者"],["un bon danseur / une bonne danseuse","舞跳得好的人"],["danseur de salon","交谊舞者"]],"sy":[["artiste","courant","艺术家，演员"],["ballerine","courant","芭蕾舞女演员"]],"fq":"中频，爱好话题。","me":"danse + -eur / -euse = 跳舞的人。","tr":{"zh":"她是一位很好的舞者。","fr":"C'est une très bonne danseuse.","alt":"Elle est très bonne danseuse.","note":"C'est + 冠词 + 名词；Elle est + 无冠词。"}},
 "Un infirmier / Une infirmière": {"pos":"n.m./n.f. 阳性 infirmier，阴性 infirmière，复数 infirmiers / infirmières","s":"护士。阳性 infirmier，阴性 infirmière。在医院、诊所、学校工作。infirmerie = 医务室。","ipa":"[ɛ̃.fiʁ.mje]","ph":"in [ɛ̃]；fir [fiʁ]；mier [mje]。阴性 infirmière [ɛ̃.fiʁ.mjɛʁ]。","pi":"注意 infirmier（阳）-ier [je]，infirmière（阴）-ière [jɛʁ]。别混。","et":"来自 infirme（虚弱的），拉丁语 infirmus（不强壮的）。infirmier 本指照顾病人的人。","ex":[["L'infirmière travaille à l'hôpital.","护士在医院工作。"],["Mon frère est infirmier.","我哥哥是护士。"],["L'infirmier prend ma tension.","护士给我量血压。"]],"co":[["une infirmière scolaire","校医，学校护士"],["un infirmier libéral","自由职业护士（上门护理）"],["appeler l'infirmière","叫护士"],["l'infirmerie","医务室"]],"sy":[["médecin","courant","医生（不同职业）"],["aide-soignant","courant","护理员"]],"fq":"中频，职业话题。","me":"infirm- 像「虚弱」：照顾 infirm 的人。","tr":{"zh":"我妈妈是护士。","fr":"Ma mère est infirmière.","alt":"Ma mère, elle est infirmière.","note":"职业前不加冠词：est infirmière。"}},
 "Un musicien / Une musicienne": {"pos":"n. 名词，阳 musicien，阴 musicienne，复数 musiciens / musiciennes","s":"音乐家；乐手；演奏者。职业名词，说职业时常不加冠词：Il est musicien.（他是乐手。）也可以是业余爱好者。","ipa":"[my.zi.sjɛ̃]","ph":"m-u 读 [y]（嘟嘴的 u）；s 在元音间读 [z]；-ien 读鼻化音 [jɛ̃]。阴性 musicienne 读 [my.zi.sjɛn]，n 要发出来。","pi":"u 读 [y]，不是 ou；阳性结尾不发 n，阴性要发 [ɛn]。","et":"来自 musique（音乐）+ 后缀 -ien（表示从事某事的人）。musique 源于希腊语 mousikê。","ex":[["Il est musicien.","他是音乐家。"],["Ma sœur est musicienne dans un orchestre.","我姐姐是乐团的乐手。"],["Les musiciens jouent ce soir.","乐手们今晚演出。"]],"co":[["un musicien de rue","街头艺人"],["être musicien(ne)","是乐手（不加冠词）"],["un bon musicien","一位优秀的音乐人"]],"sy":[["artiste","courant","艺术家，范围更广"],["instrumentiste","soutenu","器乐演奏者"]],"fq":"中高频，日常常用。","me":"musique + -ien：和音乐打交道的人。","tr":{"zh":"我的邻居是乐手。","fr":"Mon voisin est musicien.","alt":"Mon voisin, il est musicien.","note":"说职业时不加 un：Il est musicien。"}},
 "Un policier / Une policière": {"pos":"n. 名词，阳 policier，阴 policière，复数 policiers / policières","s":"警察。男女都说：un policier, une policière。口语里也常说 un flic（带点随便，有时不礼貌），正式场合用 policier。","ipa":"[pɔ.li.sje]","ph":"c 在 i 前读 [s]；-ier 读 [je]，r 不发音。阴性 policière 读 [pɔ.li.sjɛʁ]，r 要发。","pi":"阳性 -ier 结尾 r 不发音；阴性 -ière 的 r 要发。","et":"来自 police（警察，治安）+ 后缀 -ier。police 源自拉丁语 politia，再追溯到希腊语 politeia（城邦管理）。","ex":[["Le policier est dans la rue.","警察在街上。"],["La policière m'aide.","女警察帮助我。"],["Appelez la police !","叫警察！"]],"co":[["appeler la police","报警"],["un policier municipal","市警（城市警察）"],["un commissariat de police","警察局"]],"sy":[["agent de police","courant","警员"],["gendarme","courant","宪兵（军警，管乡村和公路）"],["flic","familier","条子；警察（口语）"]],"fq":"中高频，日常常用。","me":"police + -ier：「管治安的人」。police 是警察队，policier 是个人。","tr":{"zh":"警察在银行前面。","fr":"Le policier est devant la banque.","alt":"Le policier, il est devant la banque.","note":"女警察用 la policière。"}},
 "Un(e) colocataire": {"pos":"n.m./n.f. 名词，阴阳同形：un colocataire / une colocataire，复数 colocataires","s":"室友；合租的人。合租同一套房子的人。口语常缩成 un(e) coloc。注意：是住在同一套房子里，不是同班同学。","ipa":"[kɔ.lɔ.ka.tɛʁ]","ph":"每个 o 都读 [ɔ]；c 在 a 前读 [k]；-aire 读 [ɛʁ]。","pi":"阴阳同形，只靠冠词 un / une 区分性别；不是 cocataire。","et":"co-（共同）+ locataire（房客）。locataire 来自拉丁语 locare（出租）。","ex":[["Mon colocataire est sympa.","我的室友很友好。"],["Ma colocataire fait la vaisselle.","我的女室友在洗碗。"],["Nous cherchons un colocataire.","我们在找室友。"]],"co":[["chercher un colocataire","找室友"],["en colocation","合租"],["mon coloc / ma coloc","我的室友（口语）"]],"sy":[["coloc","familier","室友（缩写）"],["camarade de chambre","courant","同寝室的人（宿舍）"]],"fq":"中频，学生和年轻人常用。","me":"co（一起）+ locataire（房客）= 一起租房的人。","tr":{"zh":"我的室友今晚做饭。","fr":"Mon colocataire fait la cuisine ce soir.","alt":"Mon coloc cuisine ce soir.","note":"阴阳同形：女室友说 ma colocataire。"}},
 "Un(e) cousin(e)": {"pos":"n. 名词，阳 cousin，阴 cousine，复数 cousins / cousines","s":"堂兄弟姐妹；表兄弟姐妹。法语不分堂和表、不分年龄大小，只说 cousin / cousine。","ipa":"[ku.zɛ̃]","ph":"ou 读 [u]；s 在元音间读 [z]；-in 读鼻化音 [ɛ̃]。阴性 cousine 读 [ku.zin]。","pi":"阳性 cousin 结尾不发 n，鼻化音 [ɛ̃]；阴性 cousine 发 [zin]，n 发出来。s 读 [z]。","et":"来自晚期拉丁语 cosinus，与 consobrinus（母亲姐妹之子）有关。","ex":[["Je joue avec mon cousin.","我和我的表哥一起玩。"],["Ma cousine habite à Lyon.","我的表姐住在里昂。"],["Nous avons dix cousins.","我们有十个堂表兄弟姐妹。"]],"co":[["un cousin germain","亲堂（表）兄弟，父母的兄弟姐妹之子"],["un cousin éloigné","远房亲戚"],["mes cousins","我的堂表兄弟姐妹"]],"sy":[["parent","courant","亲戚（注意：不是「父母」，父母是 parents）"],["neveu / nièce","courant","侄子 / 侄女，不是 cousin"]],"fq":"中高频，家庭话题常用。","me":"cousin 读 [ku.zɛ̃]，像「库赞」。","tr":{"zh":"我的表姐今晚来吃饭。","fr":"Ma cousine vient dîner ce soir.","alt":"Ma cousine vient manger ce soir.","note":"cousine 要和 ma 搭配（阴性）。"}},
 "Un(e) fleuriste": {"pos":"n.m./n.f. 名词，阴阳同形：un fleuriste / une fleuriste，复数 fleuristes","s":"花店老板；卖花的人。也指花店：chez le fleuriste =「在花店」。法国街上常见 fleuriste。","ipa":"[flœ.ʁist]","ph":"eu 在 fl 后读 [œ]；r 是小舌音；结尾 -iste 读 [ist]，e 不发音。","pi":"不要把 eu 读成 [u]；-iste 的 t 要发。","et":"来自 fleur（花，拉丁语 flos, floris）+ 后缀 -iste（表示从事某职业的人）。","ex":[["J'achète des fleurs chez le fleuriste.","我在花店买花。"],["Elle est fleuriste.","她是花店店员。"],["Le fleuriste ouvre à huit heures.","花店八点开门。"]],"co":[["chez le fleuriste","在花店"],["acheter un bouquet chez le fleuriste","在花店买一束花"],["être fleuriste","是卖花的人（不加冠词）"]],"sy":[["la boutique de fleurs","courant","花店（地方）"],["horticulteur","soutenu","园艺师，种花的人"]],"fq":"中频，生活中常见。","me":"fleur + -iste：fleur（花）的人。","tr":{"zh":"我想在花店买一束花。","fr":"Je veux acheter un bouquet chez le fleuriste.","alt":"Je vais prendre un bouquet chez le fleuriste.","note":"chez + 人 表示去某人（商店）那里。"}},
 "Un(e) ingénieur(e)": {"pos":"n. 名词，阳 ingénieur，阴 ingénieure（也常见 une ingénieur），复数 ingénieurs / ingénieures","s":"工程师。法国人说 ingénieur 往往指读过工程师学校（grande école）的人。阴性 ingénieure 现在越来越常用。","ipa":"[ɛ̃.ʒe.njœʁ]","ph":"in- 读鼻化音 [ɛ̃]；g 在 é 前读 [ʒ]；-ieur 读 [jœʁ]，r 要发。","pi":"开头 in 读鼻化音 [ɛ̃]；g 读 [ʒ]，不是 [g]；结尾 r 要发音。","et":"来自古法语 engin（机巧、器械，拉丁语 ingenium 才智）+ 后缀 -ieur。同源：ingénieux（巧妙的）。","ex":[["Elle est ingénieure.","她是工程师。"],["Mon père est ingénieur dans une usine.","我爸爸是工厂的工程师。"],["Les ingénieurs travaillent sur un projet.","工程师们在做一个项目。"]],"co":[["un ingénieur informaticien","软件工程师"],["une école d'ingénieurs","工程师学校"],["un ingénieur du son","录音师；音响工程师"]],"sy":[["technicien","courant","技术员，没有工程师那么高的学历"],["ingénieux","courant","聪明巧妙的（形容词，同源）"]],"fq":"中频，职业话题常用。","me":"ingénieur 里有 génie（天才、才智）：用才智解决问题的人。","tr":{"zh":"我姐姐是工程师。","fr":"Ma sœur est ingénieure.","alt":"Ma sœur, elle est ingénieure.","note":"说职业时不加冠词；阴性可写 ingénieure。"}},
 "Un(e) peintre": {"pos":"n.m./n.f. 名词，阴阳同形：un peintre / une peintre，复数 peintres","s":"画家；也指油漆工、刷墙的工人（peintre en bâtiment）。看上下文区分是艺术家还是刷墙的人。","ipa":"[pɛ̃tʁ]","ph":"ein 读鼻化音 [ɛ̃]；结尾 tre 是 [tʁ]，只有一个音节。","pi":"ein 读 [ɛ̃]，不是 [ɛn]；结尾 -re 不读成「特」之后再加 e。","et":"来自拉丁语 pictor，和 peindre（画）、peinture（绘画）同一家族。","ex":[["Le peintre peint un tableau.","画家画了一幅画。"],["Ma tante est peintre.","我姨妈是画家。"],["Le peintre refait la chambre.","油漆工在重新粉刷房间。"]],"co":[["un peintre en bâtiment","油漆工"],["un peintre du dimanche","业余画家（不太专业）"],["un tableau de peintre","画家的画作"]],"sy":[["artiste peintre","courant","画家（正式说法）"],["barbouilleur","familier","乱涂的人，带贬义"]],"fq":"中频。","me":"peintre 和 peinture、peindre 是一家。","tr":{"zh":"这位画家很有名。","fr":"Ce peintre est très connu.","alt":"Ce peintre, il est très connu.","note":"阴阳同形：女画家用 cette peintre。"}},
 "Connaître": {"pos":"v. 动词，第三组（不规则），助动词 avoir，过去分词 connu；je connais, tu connais, il connaît, nous connaissons, ils connaissent","s":"认识（人）；熟悉（地方、作品）。后面直接接名词：connaître quelqu'un / un lieu。表示「知道一件事」用 savoir，不用 connaître。","ipa":"[kɔ.nɛtʁ]","ph":"o 读 [ɔ]；-aî- 读 [ɛ]；结尾 -tre 读 [tʁ]。注意 n 只读一个 [n]，而 gn 才读 [ɲ]。","pi":"connaître 和 savoir 容易混：认识人 / 地方用 connaître，知道事实 / 会做某事用 savoir。拼写 -aî- 有长音符，il connaît 的 î 要写。","et":"来自拉丁语 cognoscere（认识）。同源：connaissance（认识；知识）、reconnaître（认出）。","ex":[["Je connais cette ville.","我认识这座城市。"],["Tu connais Marie ?","你认识玛丽吗？"],["Je ne connais pas ce restaurant.","我不熟悉这家餐厅。"]],"co":[["connaître quelqu'un","认识某人"],["connaître par cœur","熟记于心；背下来"],["faire connaissance","认识；结识"],["Enchanté de vous connaître.","很高兴认识你。"]],"sy":[["savoir","courant","知道事实 / 会做某事"],["reconnaître","courant","认出"]],"fq":"极高频，日常常用。","me":"con + naître：con-（共同）+ naître（出生），像是「一起出生」，所以相熟。","tr":{"zh":"你认识这个街区吗？","fr":"Tu connais ce quartier ?","alt":"Vous connaissez ce quartier ?","note":"对人 / 地点用 connaître，不用 savoir。"}},
 "Danser": {"pos":"v. 动词，第一组（-er），助动词 avoir，过去分词 dansé","s":"跳舞。不及物：Elle danse bien.（她跳得好。）也可以说跳某种舞：danser la valse（跳华尔兹）。","ipa":"[dɑ̃.se]","ph":"an 读鼻化音 [ɑ̃]；s 在辅音前读 [s]；结尾 -er 读 [e]，r 不发音。","pi":"an 的 n 不发音，是鼻化音 [ɑ̃]；结尾 -er 读 [e]，不是 [ɛʁ]。","et":"来自古法语 danser，起源不确定（可能与日耳曼语有关），同家族：danse, danseur / danseuse。","ex":[["Elle aime danser.","她喜欢跳舞。"],["Nous dansons dans la cuisine.","我们在厨房里跳舞。"],["Tu veux danser avec moi ?","你想和我跳舞吗？"]],"co":[["danser avec quelqu'un","和某人跳舞"],["danser la valse / le tango","跳华尔兹 / 探戈"],["un cours de danse","舞蹈课"],["aller danser","去跳舞"]],"sy":[["sauter","courant","跳（不是跳舞）"],["se déhancher","familier","扭着腰跳"]],"fq":"高频，日常常用。","me":"danser 像英语 dance，只是词尾换成 -er。","tr":{"zh":"我们周六晚上去跳舞。","fr":"Nous allons danser samedi soir.","alt":"On va danser samedi soir.","note":"aller + 动词原形 表示近期的计划。"}},
 "Déménager": {"pos":"v. 动词，第一组（-er），助动词 avoir，过去分词 déménagé；nous déménageons（g 后加 e）","s":"搬家；迁居。不及物：Je déménage.（我搬家。）后面可接地点：déménager à Lyon。也可以说搬走东西：déménager un meuble。","ipa":"[de.me.na.ʒe]","ph":"é 读 [e]；g 在 é 前读 [ʒ]；结尾 -er 读 [e]。","pi":"nous déménageons 要保留 e，才能让 g 读 [ʒ]；别漏掉两个 é 的重音。","et":"dé-（离开）+ ménage（家、家庭）+ -er。同族：emménager（搬进）、ménage（家务；家庭）。","ex":[["Je vais déménager demain.","我明天搬家。"],["Ils ont déménagé à Paris.","他们搬到了巴黎。"],["Nous déménageons le 1er juin.","我们六月一日搬家。"]],"co":[["déménager à Paris","搬到巴黎"],["un camion de déménagement","搬家卡车"],["un déménageur","搬家工人"],["emménager","搬进新家"]],"sy":[["emménager","courant","搬进（反义：搬入新家）"],["partir","courant","离开，更宽泛"]],"fq":"中高频，日常常用。","me":"dé-（离开）+ ménage（家）：把家搬走。","tr":{"zh":"我们下个月搬家。","fr":"Nous déménageons le mois prochain.","alt":"On déménage le mois prochain.","note":"nous 形式要写 -geons。"}},
 "Détester": {"pos":"v. 动词，第一组（-er），助动词 avoir，过去分词 détesté","s":"讨厌；非常不喜欢。语气比 ne pas aimer 强，比 haïr 日常。后面可接名词或动词原形：Je déteste attendre.（我讨厌等人。）","ipa":"[de.tɛs.te]","ph":"é 读 [e]；e 在 -st- 前读 [ɛ]；结尾 -er 读 [e]。","pi":"不要读成英语 detest 的重音；每个音节都清楚：dé-tes-ter。","et":"来自拉丁语 detestari（咒骂，厌恶）。英语 detest 同源。","ex":[["Je déteste le froid.","我讨厌寒冷。"],["Elle déteste attendre.","她讨厌等待。"],["Ils détestent le bruit.","他们讨厌噪音。"]],"co":[["détester + 名词","讨厌某物"],["détester + 动词原形","讨厌做某事"],["Je déteste ça !","我讨厌这个！"],["détester quelqu'un","讨厌某人"]],"sy":[["haïr","soutenu","憎恨，更强烈"],["ne pas supporter","courant","受不了"],["ne pas aimer","courant","不喜欢，较温和"]],"fq":"高频，日常常用。","me":"像英语 detest；dé- 带点「相反」的意思。","tr":{"zh":"我讨厌在雨天走路。","fr":"Je déteste marcher sous la pluie.","alt":"Je déteste marcher quand il pleut.","note":"détester + 动词原形，不加介词。"}},
 "Expliquer": {"pos":"v. 动词，第一组（-er），助动词 avoir，过去分词 expliqué","s":"解释；讲解。常见结构：expliquer quelque chose à quelqu'un（向某人解释某事）。注意：是 expliquer à，不是 expliquer pour。","ipa":"[ɛks.pli.ke]","ph":"ex- 读 [ɛks]；qu 读 [k]；结尾 -er 读 [e]。","pi":"qu 读 [k]，不是 [kw]；拼写是 expliquer，别写成 explicar。","et":"来自拉丁语 explicare（展开）。英语 explain 同源，也可对照 explication（解释）。","ex":[["Il explique la leçon.","他讲解课程。"],["Tu peux m'expliquer ?","你可以给我解释一下吗？"],["Elle explique la règle aux enfants.","她向孩子们解释规则。"]],"co":[["expliquer quelque chose à quelqu'un","向某人解释某事"],["s'expliquer","说明自己；把话说清楚"],["Je m'explique.","我来说清楚。"],["une explication","解释"]],"sy":[["clarifier","soutenu","阐明，澄清"],["raconter","courant","讲述（故事，不是解释）"]],"fq":"高频，日常常用。","me":"ex- + pli（折）：把折起来的东西展开说清楚。","tr":{"zh":"老师向我们解释这个词。","fr":"Le professeur nous explique ce mot.","alt":"Le prof nous explique ce mot.","note":"向某人用 expliquer à，代词放动词前：nous explique。"}},
 "Faire": {"pos":"v. 动词，第三组（不规则），助动词 avoir，过去分词 fait；je fais, tu fais, il fait, nous faisons, vous faites, ils font","s":"做；制作；干。是法语最常用的动词之一：faire un gâteau（做蛋糕）、faire du sport（做运动）。天气也用它：Il fait beau.（天气好。）","ipa":"[fɛʁ]","ph":"ai 读 [ɛ]；r 要发音。变位注意：nous faisons 读 [fə.zɔ̃]，ai 在这里读 [ə]；vous faites 读 [fɛt]。","pi":"nous faisons 的 ai 读 [ə]，不是 [ɛ]；vous faites 和 ils font 都不规则。","et":"来自拉丁语 facere（做）。同族：fait（事实）、défaire、refaire、satisfaire。","ex":[["Je vais faire un gâteau.","我要做一个蛋糕。"],["Il fait beau aujourd'hui.","今天天气很好。"],["Qu'est-ce que tu fais ?","你在做什么？"]],"co":[["faire du sport","做运动"],["faire la cuisine","做饭"],["Il fait beau / froid.","天气好 / 冷。"],["faire attention","注意；小心"]],"sy":[["réaliser","soutenu","实现，完成"],["fabriquer","courant","制造"]],"fq":"极高频，几乎每天都用。","me":"faire = 做；和英语 do / make 都对应，范围很大。","tr":{"zh":"你周末做什么？","fr":"Qu'est-ce que tu fais le week-end ?","alt":"Tu fais quoi le week-end ?","note":"faire 的 tu 形式是 fais，结尾 s 不发音。"}},
 "Manger": {"pos":"v. 动词，第一组（-er），助动词 avoir，过去分词 mangé；nous mangeons（g 后加 e）","s":"吃。可及物，也可以不及物：Je mange une pomme. / Nous mangeons à midi.（我们中午吃饭。）名词 le manger 也指「吃的东西」。","ipa":"[mɑ̃.ʒe]","ph":"an 读鼻化音 [ɑ̃]；g 在 e 前读 [ʒ]；结尾 -er 读 [e]。","pi":"nous mangeons 要保留 e：mangeons，g 才读 [ʒ]；不要写成 mangons。","et":"来自拉丁语 manducare（咀嚼）。同族：mangeoire（食槽）、mangeable（可食用的）。","ex":[["Nous aimons manger.","我们喜欢吃饭。"],["Je mange une pomme.","我吃一个苹果。"],["On mange à midi ?","我们中午吃饭吗？"]],"co":[["manger à midi / le soir","中午 / 晚上吃饭"],["manger au restaurant","在餐厅吃饭"],["manger un morceau","随便吃点东西（口语）"],["bien manger","吃得好"]],"sy":[["dîner","courant","吃晚饭"],["bouffer","familier","吃（口语，较随便）"],["déguster","soutenu","品尝"]],"fq":"极高频，日常常用。","me":"manger ← manducare：想到 mange-tout（豆荚豆）。","tr":{"zh":"我们晚上八点吃饭。","fr":"Nous mangeons à huit heures du soir.","alt":"On mange à vingt heures.","note":"nous 形式要写 mangeons。"}},
 "Manquer": {"pos":"v. 动词，第一组（-er），助动词 avoir，过去分词 manqué","s":"缺少；想念；错过。想念时结构是反的：Tu me manques. 字面是「你对我来说缺少」，意思是「我想你」。也可 manquer le bus（错过公交车）。","ipa":"[mɑ̃.ke]","ph":"an 读鼻化音 [ɑ̃]；qu 读 [k]；结尾 -er 读 [e]。","pi":"「我想你」是 Tu me manques，不是 Je te manque（那就变成「你想我」）。别按英语 I miss you 的顺序来翻。","et":"可能来自意大利语 mancare，源自拉丁语 mancus（有缺陷的）。同族：manque（缺乏）、manquant。","ex":[["Tu me manques.","我想你。"],["Il manque du sel.","缺盐。"],["J'ai manqué le bus.","我错过了公交车。"]],"co":[["Tu me manques.","我想你。"],["Il manque du sel.","缺盐。"],["manquer le bus / le train","错过公交车 / 火车"],["manquer de temps","缺时间"]],"sy":[["rater","familier","错过；搞砸"],["faire défaut","soutenu","缺少"],["regretter","courant","怀念（人 / 过去）"]],"fq":"高频，日常常用。","me":"Tu me manques = 你「缺」在我身边 = 我想你。","tr":{"zh":"我想我的家人。","fr":"Ma famille me manque.","alt":"Mes parents me manquent.","note":"被想念的人是主语，想念的人用 me。"}},
 "Marcher": {"pos":"v. 动词，第一组（-er），助动词 avoir，过去分词 marché","s":"走路；步行；（机器、计划）运行、行得通。Ça marche ? =「行吗？」，Ça marche ! =「好的！可以！」。","ipa":"[maʁ.ʃe]","ph":"ar 读 [aʁ]；ch 读 [ʃ]；结尾 -er 读 [e]。","pi":"ch 读 [ʃ]，不是 [k] 也不是 [tʃ]；marcher 同时是「走」与「运行」，看语境。","et":"来自古法语 marchier（踏、走），可能源于法兰克语。同族：marche（步行；台阶）、marché（市场，另一个词源）。","ex":[["Nous aimons marcher.","我们喜欢走路。"],["Ça marche !","好的！可以！"],["Ma montre ne marche pas.","我的手表不走了。"]],"co":[["marcher dans la rue","在街上走"],["Ça marche ?","行得通吗？"],["marcher bien / mal","运行良好 / 不好"],["faire une marche","散步；徒步"]],"sy":[["se promener","courant","散步"],["fonctionner","courant","运行（机器）"],["aller à pied","courant","步行去"]],"fq":"极高频，日常常用。","me":"marcher：想到「march」行军：一步接一步地走。","tr":{"zh":"我每天走路去上班。","fr":"Je marche pour aller au travail tous les jours.","alt":"Je vais au travail à pied tous les jours.","note":"aller à pied 也表示「走路去」。"}},
 "Nager": {"pos":"v. 动词，第一组（-er），助动词 avoir，过去分词 nagé；nous nageons（g 后加 e）","s":"游泳。Je sais nager. =「我会游泳。」也可以是及物：nager le crawl（游自由泳）。","ipa":"[na.ʒe]","ph":"n 读 [n]；g 在 e 前读 [ʒ]；结尾 -er 读 [e]。","pi":"nous nageons 要保留 e；g 读 [ʒ]，不是 [g]。「会」用 savoir：Je sais nager，不要用 pouvoir。","et":"来自拉丁语 navigare（航行），同族：naviguer（航行；上网）。","ex":[["Je sais nager.","我会游泳。"],["Nous nageons dans la mer.","我们在海里游泳。"],["Elle nage tous les matins.","她每天早上游泳。"]],"co":[["savoir nager","会游泳"],["nager dans la piscine","在游泳池里游泳"],["nager le crawl / la brasse","游自由泳 / 蛙泳"],["un nageur / une nageuse","游泳者"]],"sy":[["se baigner","courant","洗澡；下水玩"],["faire de la natation","courant","做游泳运动"]],"fq":"高频，日常常用。","me":"nager ← navigare：「导航」也有水的联想。","tr":{"zh":"我周末去游泳。","fr":"Je vais nager le week-end.","alt":"Je vais à la piscine le week-end.","note":"aller + 动词原形 表示近期的计划。"}},
 "Plaisanter": {"pos":"v. 动词，第一组（-er），助动词 avoir，过去分词 plaisanté","s":"开玩笑；说笑。不及物：Tu plaisantes ? =「你开玩笑吧？」也可用 plaisanter sur quelque chose（拿某事开玩笑）。","ipa":"[plɛ.zɑ̃.te]","ph":"ai 读 [ɛ]；s 在元音间读 [z]；an 读鼻化音 [ɑ̃]；结尾 -er 读 [e]。","pi":"s 读 [z]，不是 [s]；ai 读 [ɛ]。Je plaisante ! 常用来澄清「我开玩笑的」。","et":"来自 plaisant（令人愉快的），源自 plaire（使喜欢，拉丁语 placere）。同族：plaisir、plaisanterie（玩笑）。","ex":[["Je plaisante !","我开玩笑呢！"],["Tu plaisantes ?","你在开玩笑吗？"],["Il aime plaisanter avec ses amis.","他喜欢和朋友开玩笑。"]],"co":[["Je plaisante !","开玩笑的！"],["Tu plaisantes ?","你开玩笑吧？"],["plaisanter sur quelque chose","拿某事开玩笑"],["sans plaisanter","说真的；不开玩笑"]],"sy":[["blaguer","familier","开玩笑（口语）"],["rigoler","familier","笑；闹着玩"],["badiner","littéraire","戏谑（书面）"]],"fq":"中高频，口语常用。","me":"plaisant（愉快的）+ -er：说让人愉快的话 = 开玩笑。","tr":{"zh":"你在开玩笑吗？","fr":"Tu plaisantes ?","alt":"Tu rigoles ?","note":"Tu plaisantes ? 是最常见的说法。"}},
 "Travailler": {"pos":"v. 动词，第一组（-er），助动词 avoir，过去分词 travaillé","s":"工作；学习用功；干活。Je travaille dans une banque. =「我在银行工作。」也可指「努力练习」：travailler son français（练习法语）。","ipa":"[tʁa.va.je]","ph":"tr 读 [tʁ]；-ill- 读 [j]；结尾 -er 读 [e]。","pi":"-ill- 读 [j]，像「呀」；不要读成 [l]。travail（名词）的 l 不发，读 [tʁa.vaj]。","et":"来自 travail（工作），常被追溯到拉丁语 tripalium（一种三根桩的刑具），这个说法被广泛接受。英语 travel 也与它同源。","ex":[["Je travaille tous les jours.","我每天工作。"],["Elle travaille dans une banque.","她在银行工作。"],["Nous travaillons le français.","我们在练习法语。"]],"co":[["travailler dans un hôpital","在医院工作"],["travailler comme + 职业","做……工作"],["travailler dur","拼命工作"],["bien travailler","工作努力"]],"sy":[["bosser","familier","干活（口语）"],["étudier","courant","学习"],["œuvrer","littéraire","致力于（书面）"]],"fq":"极高频，日常常用。","me":"travailler 里有 vail：想到英语 travail（辛劳）。","tr":{"zh":"我在一家小公司工作。","fr":"Je travaille dans une petite entreprise.","alt":"Je bosse dans une petite boîte.","note":"「在……工作」用 travailler dans / chez。"}},
 "Voyager": {"pos":"v. 动词，第一组（-er），助动词 avoir，过去分词 voyagé；nous voyageons（g 后加 e）","s":"旅行；出行。不及物：Il voyage beaucoup.（他经常出差 / 旅行。）名词是 un voyage（一次旅行）。","ipa":"[vwa.ja.ʒe]","ph":"oy 读 [wa]+[j]，即 voy- 读 [vwa.j]；g 在 e 前读 [ʒ]；结尾 -er 读 [e]。","pi":"voy- 读 [vwaj]，别读成 [vɔj]；nous voyageons 要保留 e。","et":"来自 voyage（旅行），源自拉丁语 viaticum（路上的盘缠）。英语 voyage 同源。","ex":[["Il aime voyager.","他喜欢旅行。"],["Nous voyageons en train.","我们坐火车旅行。"],["Elle voyage beaucoup pour son travail.","她因工作经常出差。"]],"co":[["voyager en train / en avion","坐火车 / 飞机旅行"],["voyager seul(e)","独自旅行"],["voyager léger","轻装旅行"],["un voyage d'affaires","出差"]],"sy":[["se déplacer","courant","出行；移动"],["partir en voyage","courant","去旅行"]],"fq":"高频，日常常用。","me":"voyager 像英语 voyage：出海远行。","tr":{"zh":"我们夏天去旅行。","fr":"Nous voyageons en été.","alt":"On voyage l'été.","note":"nous 形式 voyageons 要写 e。"}},
 "Asiatique": {"pos":"adj. 形容词，阴阳同形，复数 asiatiques；也可作名词 un(e) Asiatique","s":"亚洲的；亚洲人的。阴阳同形：un restaurant asiatique, une cuisine asiatique。作名词时首字母大写：un Asiatique（亚洲人）。","ipa":"[a.zja.tik]","ph":"As- 读 [az]（s 在元音间读 [z]）；-ia- 读 [ja]；-tique 读 [tik]。","pi":"s 读 [z]，不是 [s]；-que 读 [k]，e 不发音。阴阳同形，不用加 -e。","et":"来自 Asie（亚洲，希腊语 Asia）+ 后缀 -atique。","ex":[["Il y a beaucoup de restaurants asiatiques ici.","这里有很多亚洲餐厅。"],["J'aime la cuisine asiatique.","我喜欢亚洲菜。"],["Cette épicerie vend des produits asiatiques.","这家杂货店卖亚洲食品。"]],"co":[["la cuisine asiatique","亚洲菜"],["un restaurant asiatique","亚洲餐厅"],["l'Asie du Sud-Est","东南亚"]],"sy":[["oriental","courant","东方的（范围更模糊）"],["d'Asie","courant","来自亚洲的"]],"fq":"中频。","me":"Asie + -atique：和亚洲有关的。","tr":{"zh":"我喜欢亚洲菜。","fr":"J'aime la cuisine asiatique.","alt":"J'adore manger asiatique.","note":"asiatique 阴阳同形，放在名词后面。"}},
 "Bourgeois(e)": {"pos":"adj./n. 形容词，阳 bourgeois，阴 bourgeoise，复数 bourgeois / bourgeoises","s":"资产阶级的；中产的；（有时带贬义）循规蹈矩、保守的。un quartier bourgeois 是指有钱人住的区域。也作名词：un bourgeois。","ipa":"[buʁ.ʒwa]","ph":"ou 读 [u]；g 在 e 前读 [ʒ]；-eois 读 [wa]，其中 e 不发音，只是让 g 读 [ʒ]。阴性 bourgeoise 读 [buʁ.ʒwaz]。","pi":"bourgeois 的 e 不发音；阳性结尾 s 不发音，阴性 -se 读 [z]。","et":"来自 bourg（城镇，源自法兰克语 burg，意为设防的城）+ -ois。bourg 的居民 = bourgeois。","ex":[["C'est un quartier bourgeois.","这是个中产阶级街区。"],["Elle vient d'une famille bourgeoise.","她出身中产家庭。"],["Il est un peu bourgeois.","他有点资产阶级作风。"]],"co":[["un quartier bourgeois","中产阶级街区"],["une famille bourgeoise","中产家庭"],["la bourgeoisie","资产阶级"],["bon chic bon genre","体面讲究的（缩写 BCBG）"]],"sy":[["aisé","courant","富裕的"],["populaire","courant","平民的（反义）"],["bobo","familier","波波族（bourgeois-bohème）"]],"fq":"中频，政治、社会话题常见。","me":"bourg（城镇）+ -ois：城里人，后来指有钱的中产。","tr":{"zh":"这家人是中产家庭。","fr":"C'est une famille bourgeoise.","alt":"Ils viennent d'une famille bourgeoise.","note":"阴性是 bourgeoise，s 读 [z]。"}},
 "Branché(e)": {"pos":"adj. 形容词，阳 branché，阴 branchée，复数 branchés / branchées","s":"时髦的；潮的；跟得上潮流的。口语里常用，指地方、人或事物很「潮」。字面来自 brancher（插电）：像「接上电源」。","ipa":"[bʁɑ̃.ʃe]","ph":"an 读鼻化音 [ɑ̃]；ch 读 [ʃ]；-é 读 [e]。阴性 branchée 读法相同。","pi":"an 读鼻化音 [ɑ̃]，n 不发音；ch 读 [ʃ]。branché 是口语词，正式文章少用。","et":"来自动词 brancher（接上、连接），branche（树枝）+ -er。「接上线」的意思引申出「紧跟潮流」。","ex":[["Ce quartier est très branché.","这个街区很时髦。"],["Elle porte des vêtements branchés.","她穿时髦的衣服。"],["C'est un bar branché.","这是一家很潮的酒吧。"]],"co":[["un quartier branché","潮街区"],["un bar / un resto branché","潮酒吧 / 潮餐厅"],["être branché musique","迷音乐；懂音乐"],["brancher","接上（插头）"]],"sy":[["à la mode","courant","流行的；时髦的"],["tendance","courant","有趋势的；潮流的"],["cool","familier","酷"]],"fq":"中频，口语常用。","me":"branché = 接上电源 = 跟上潮流。","tr":{"zh":"这家餐厅很时髦。","fr":"Ce restaurant est très branché.","alt":"C'est un resto très branché.","note":"与阴性名词搭配写 branchée。"}},
 "Bruyant(e)": {"pos":"adj. 形容词，阳 bruyant，阴 bruyante，复数 bruyants / bruyantes","s":"吵闹的；喧闹的。可以形容地方、人或东西：une rue bruyante, des voisins bruyants。反义词是 calme 或 silencieux。","ipa":"[bʁɥi.jɑ̃]","ph":"br 读 [bʁ]；uy 读 [ɥi]（像 w + i）；-ant 读鼻化音 [ɑ̃]。阴性 bruyante 读 [bʁɥi.jɑ̃t]，t 要发。","pi":"uy 读 [ɥi.j]，不是 [uj]；阳性结尾 t 不发音，阴性要发。","et":"来自 bruit（噪音）+ -ant。bruit 的词源不确定。同族：bruit、bruyamment。","ex":[["Ma rue est trop bruyante.","我家的街太吵了。"],["Mes voisins sont bruyants.","我的邻居很吵。"],["Ce restaurant est bruyant le soir.","这家餐厅晚上很吵。"]],"co":[["une rue bruyante","吵闹的街"],["trop bruyant(e)","太吵"],["des voisins bruyants","吵闹的邻居"],["faire du bruit","发出声响"]],"sy":[["calme","courant","安静的（反义）"],["tapageur","soutenu","喧闹的"],["animé","courant","热闹的（褒义）"]],"fq":"中频，常用来描述住处。","me":"bruyant ← bruit：有噪音的。","tr":{"zh":"这条街晚上很吵。","fr":"Cette rue est très bruyante le soir.","alt":"Cette rue, elle est super bruyante le soir.","note":"形容 rue（阴性），用 bruyante。"}},
 "Calme": {"pos":"adj. 形容词，阴阳同形，复数 calmes；也是阳性名词 le calme（平静）","s":"安静的；平静的；冷静的。可形容地方，也可形容人：Reste calme.（保持冷静。）反义：bruyant, agité。","ipa":"[kalm]","ph":"c 读 [k]；a 读 [a]；结尾 -lme 读 [lm]，e 不发音，一个音节。","pi":"只有一个音节，不要读成「卡尔么」；结尾 e 不发音；l 要读出来。","et":"经意大利语 calma 进入法语，更早追溯到希腊语 kauma（炎热），与正午休息有关。","ex":[["Le parc est calme.","公园很安静。"],["Reste calme !","保持冷静！"],["J'habite dans un quartier calme.","我住在安静的街区。"]],"co":[["rester calme","保持冷静"],["un quartier calme","安静的街区"],["Calme-toi !","冷静下来！"],["dans le calme","在安静中"]],"sy":[["tranquille","courant","安静的；平静的"],["silencieux","courant","无声的，更强"],["serein","soutenu","安详的，内心平静的"]],"fq":"高频，日常常用。","me":"calme 和英语 calm 几乎一样。","tr":{"zh":"我喜欢安静的街区。","fr":"J'aime les quartiers calmes.","alt":"J'aime bien les coins tranquilles.","note":"calme 阴阳同形，复数加 s。"}},
 "Célibataire": {"pos":"adj./n. 形容词，阴阳同形，复数 célibataires；也可作名词 un(e) célibataire","s":"单身的；未婚的。指没有伴侣，或没有结婚。注意它不是宗教上的「独身（celibate）」。Il est célibataire. =「他单身。」","ipa":"[se.li.ba.tɛʁ]","ph":"c 在 é 前读 [s]；é 读 [e]；-aire 读 [ɛʁ]，r 要发音。","pi":"c 读 [s]；阴阳同形，不需要再加 e。","et":"来自拉丁语 caelibatus（独身状态）。同族：célibat（单身状态）。","ex":[["Il est célibataire.","他是单身。"],["Elle est célibataire depuis deux ans.","她单身两年了。"],["Je suis célibataire et heureux.","我单身，而且幸福。"]],"co":[["être célibataire","单身"],["un célibataire endurci","死硬的单身汉"],["une soirée célibataires","单身派对"],["le célibat","单身状态"]],"sy":[["seul(e)","courant","孤单的；没伴的"],["marié(e)","courant","已婚的（反义）"],["libre","courant","自由的；没有伴侣"]],"fq":"中高频，自我介绍时常用。","me":"célibataire：想到 célébrer 但「不庆祝婚礼」= 单身。","tr":{"zh":"我现在是单身。","fr":"Je suis célibataire en ce moment.","alt":"Je suis célibataire pour l'instant.","note":"阴阳同形：男女都说 célibataire。"}},
 "Enceinte": {"pos":"adj. 形容词，只用于阴性，复数 enceintes；另有名词 une enceinte（围墙；音箱）","s":"怀孕的。只形容女性：Elle est enceinte.（她怀孕了。）没有阳性形式。另有另一个意思：une enceinte = 围墙；也指音箱（enceinte acoustique）。","ipa":"[ɑ̃.sɛ̃t]","ph":"en 读 [ɑ̃]；c 在 e 前读 [s]；-ein 读 [ɛ̃]；结尾 -te 读 [t]。两个鼻化音：[ɑ̃.sɛ̃t]。","pi":"两个鼻化音不同：en = [ɑ̃]，ein = [ɛ̃]；不能说 un homme enceinte。别和英语 incense 混。","et":"来自拉丁语 incincta（没系腰带的），后来指怀孕。同族：enceinte（围墙），原指「围起来」。","ex":[["Elle est enceinte.","她怀孕了。"],["Ma sœur est enceinte de quatre mois.","我姐姐怀孕四个月了。"],["Cette enceinte est puissante.","这个音箱声音很大。"]],"co":[["être enceinte de trois mois","怀孕三个月"],["tomber enceinte","怀孕了"],["une femme enceinte","孕妇"],["une enceinte Bluetooth","蓝牙音箱"]],"sy":[["attendre un enfant","courant","怀着孩子，较温和"],["en cloque","argot","有喜了（俗语）"],["future maman","courant","准妈妈"]],"fq":"中频，家庭话题常用。","me":"enceinte：两个鼻化音，en 与 ein 听起来不同。","tr":{"zh":"我姐姐怀孕了。","fr":"Ma sœur est enceinte.","alt":"Ma sœur attend un bébé.","note":"enceinte 只形容女性，没有阳性形式。"}},
 "Grand(e)": {"pos":"adj. 形容词，阳 grand，阴 grande，复数 grands / grandes","s":"高的（人）；大的（东西）；成年的；伟大的。Il est grand. 说人是高的；une grande maison 是大房子。放在名词前还有「伟大」「大量」的意思：un grand homme。","ipa":"[gʁɑ̃]","ph":"g 读 [g]；an 读 [ɑ̃]；阳性 d 不发音；阴性 grande 读 [gʁɑ̃d]。后接元音时联诵：grand ami 读 [gʁɑ̃.t‿a.mi]（d 读成 [t]）。","pi":"阳性 d 不发音；联诵时 d 读 [t]；grand = 高 / 大，宽（长度）用 long 或 large。","et":"来自拉丁语 grandis（大的）。英语 grand 同源。","ex":[["Il est très grand.","他很高。"],["C'est une grande ville.","这是一座大城市。"],["Mon grand frère a vingt ans.","我哥哥二十岁。"]],"co":[["grand frère / grande sœur","哥哥 / 姐姐（年龄大的）"],["un grand homme","伟大的人"],["grand ouvert","大开着"],["pas grand-chose","没什么"]],"sy":[["gros","courant","粗大的；胖的"],["énorme","courant","巨大的"],["petit","courant","小的（反义）"]],"fq":"极高频，日常常用。","me":"grand 像英语 grand：大。","tr":{"zh":"我的哥哥很高。","fr":"Mon grand frère est très grand.","alt":"Mon frère est super grand.","note":"前一个 grand 是「年长的」，后一个是「个子高」。"}},
 "Normal(e)": {"pos":"adj. 形容词，阳 normal，阴 normale，阳性复数 normaux，阴性复数 normales","s":"正常的；平常的；理所当然的。C'est normal. =「这很正常。」也用来回应道谢或道歉：C'est normal.（这没什么。）","ipa":"[nɔʁ.mal]","ph":"o 读 [ɔ]；r 要发；-al 读 [al]。阴性 normale 读 [nɔʁ.mal]。阳复 normaux 读 [nɔʁ.mo]。","pi":"阳性复数是 normaux，不是 normals；阳性的 l 要读出来。","et":"来自拉丁语 normalis（合乎规矩的），源自 norma（标准）。英语 normal 同源。","ex":[["C'est une journée normale.","这是平常的一天。"],["C'est normal de se tromper.","犯错是正常的。"],["Il est normal qu'elle soit fatiguée.","她累是很正常的。"]],"co":[["C'est normal.","这很正常。"],["la vie normale","正常的生活"],["comme d'habitude","和平常一样"],["Ce n'est pas normal.","这不正常。"]],"sy":[["habituel","courant","惯常的"],["ordinaire","courant","普通的"],["naturel","courant","自然的，理所当然的"]],"fq":"极高频，日常常用。","me":"normal：和英语 normal 同形，但阳复是 normaux。","tr":{"zh":"这很正常，别担心。","fr":"C'est normal, ne t'inquiète pas.","alt":"C'est normal, t'inquiète pas.","note":"阳性复数是 normaux。"}},
 "Occupé(e)": {"pos":"adj. 形容词，阳 occupé，阴 occupée，复数 occupés / occupées","s":"忙的；被占用的。可指人忙：Je suis occupé.（我很忙。）也可指地方被占用：La ligne est occupée.（电话占线。）Cette place est occupée.（这个座位有人。）","ipa":"[ɔ.ky.pe]","ph":"oc-c 的两个 c 只读一个 [k]；u 读 [y]；p 读 [p]；-é 读 [e]。","pi":"occupé 的两个 c 只发一个 [k] 的音；u 读 [y]；别写成 ocupé。","et":"来自拉丁语 occupare（占据）。同族：occuper（占用）、occupation（占领；职业）。","ex":[["Je suis très occupé.","我很忙。"],["La ligne est occupée.","电话占线。"],["Cette place est occupée.","这个座位有人了。"]],"co":[["être très occupé(e)","很忙"],["La ligne est occupée.","占线。"],["Les toilettes sont occupées.","厕所有人。"],["s'occuper de","照看；负责"]],"sy":[["pris(e)","courant","被占用 / 有事"],["débordé","courant","忙不过来"],["libre","courant","空闲的（反义）"]],"fq":"高频，日常常用。","me":"occupé：像英语 occupied，里头有 occuper。","tr":{"zh":"对不起，我现在很忙。","fr":"Désolé, je suis très occupé en ce moment.","alt":"Désolé, je suis pris en ce moment.","note":"女性说 occupée，发音不变。"}},
 "Pauvre": {"pos":"adj. 形容词，阴阳同形，复数 pauvres；也可作名词 un pauvre","s":"穷的；贫穷的；可怜的。位置不同意思不同：un homme pauvre =「没钱的男人」，un pauvre homme =「可怜的人」。","ipa":"[povʁ]","ph":"au 读 [o]；结尾 -vre 读 [vʁ]，e 不发音，一个音节。","pi":"au 读 [o]，不是 [au]；结尾 -vre 要发 [vʁ]。注意位置：pauvre 放名词前 = 可怜，放后 = 穷。","et":"来自拉丁语 pauper（穷的）。同族：pauvreté（贫穷）、appauvrir。英语 poor 同源。","ex":[["C'est un pays pauvre.","这是一个贫穷的国家。"],["Le pauvre chien a froid.","可怜的小狗很冷。"],["Il est pauvre, mais heureux.","他穷，但很幸福。"]],"co":[["un pays pauvre","贫穷的国家"],["un pauvre homme","可怜的人"],["pauvre de moi !","我真可怜！"],["pauvre en","缺少……的"]],"sy":[["démuni","soutenu","一贫如洗的"],["fauché","familier","没钱的（口语）"],["riche","courant","富有的（反义）"]],"fq":"高频，日常常用。","me":"pauvre：像英语 poor / pauper。","tr":{"zh":"这个家庭很穷，但是很幸福。","fr":"Cette famille est pauvre, mais heureuse.","alt":"Cette famille n'a pas d'argent, mais elle est heureuse.","note":"pauvre 放在名词后表示「穷」。"}},
 "Petit(e)": {"pos":"adj. 形容词，阳 petit，阴 petite，复数 petits / petites","s":"小的；矮的；年幼的。Il est petit. 可以指个子矮；petit frère 是弟弟。口语里也有亲昵的意思：mon petit chat。","ipa":"[pə.ti]","ph":"p 后的 e 读 [ə]（轻）；t 在元音间读 [t]；阳性 t 不发音，阴性 petite 读 [pə.tit]。后接元音时联诵：petit ami 读 [pə.ti.t‿a.mi]。","pi":"阳性 t 不发音；联诵时 t 要发：un petit ami。petit ami =「男朋友」，不要和 petit 单独的意思混。","et":"来自通俗拉丁语，具体词源不太确定。同族：petitesse、rapetisser。","ex":[["Le chien est petit.","这条狗很小。"],["Ma petite sœur a six ans.","我妹妹六岁。"],["J'ai une petite maison.","我有一间小房子。"]],"co":[["un petit ami / une petite amie","男朋友 / 女朋友"],["petit frère / petite sœur","弟弟 / 妹妹"],["un petit peu","一点点"],["petit à petit","一点一点地"]],"sy":[["minuscule","courant","极小的"],["court","courant","短的"],["grand","courant","大的（反义）"]],"fq":"极高频，日常常用。","me":"petit：想到「小提琴 petit」，反义词是 grand。","tr":{"zh":"我的妹妹有一条小狗。","fr":"Ma petite sœur a un petit chien.","alt":"Ma petite sœur a un chiot.","note":"petite（阴性）配 sœur，petit（阳性）配 chien。"}},
 "Populaire": {"pos":"adj. 形容词，阴阳同形，复数 populaires","s":"受欢迎的；流行的；平民的。注意：un quartier populaire 是「平民区、工人区」，不一定「受欢迎」。","ipa":"[pɔ.py.lɛʁ]","ph":"o 读 [ɔ]；u 读 [y]；-aire 读 [ɛʁ]，r 要发。","pi":"u 读 [y]，不是 [u]；populaire 有两层意思，看语境：受欢迎 / 平民的。","et":"来自拉丁语 popularis，源自 populus（人民）。同族：population（人口）、populaire。","ex":[["C'est un chanteur populaire.","这是一位很受欢迎的歌手。"],["Ce quartier est populaire.","这个街区是平民区。"],["Ce plat est très populaire en France.","这道菜在法国很受欢迎。"]],"co":[["un chanteur populaire","受欢迎的歌手"],["un quartier populaire","平民街区"],["la musique populaire","大众音乐"],["très populaire auprès des jeunes","深受年轻人欢迎"]],"sy":[["célèbre","courant","有名的"],["connu","courant","出名的"],["cher au public","soutenu","受公众喜爱"]],"fq":"中高频。","me":"populaire：来自 peuple（人民）：「人民的」。","tr":{"zh":"这首歌在年轻人中很受欢迎。","fr":"Cette chanson est très populaire chez les jeunes.","alt":"Cette chanson plaît beaucoup aux jeunes.","note":"populaire 阴阳同形。"}},
 "Propre": {"pos":"adj. 形容词，阴阳同形，复数 propres","s":"干净的；自己的。放在名词后 = 干净：une chambre propre；放在名词前 = 自己的：ma propre chambre（我自己的房间）。","ipa":"[pʁɔpʁ]","ph":"pr 读 [pʁ]；o 读 [ɔ]；结尾 -pre 读 [pʁ]，e 不发音，一个音节。","pi":"位置改变意思：un homme propre（干净的人） vs son propre argent（他自己的钱）。别和英语 proper（适当的）混。","et":"来自拉丁语 proprius（自己的），同族：propriété（财产）、approprié。「干净」的意义由「合乎自己的规范」引申而来。","ex":[["Ma chambre est propre.","我的房间很干净。"],["Il a sa propre voiture.","他有自己的车。"],["Les mains propres, s'il vous plaît !","请把手洗干净！"]],"co":[["propre et net","干净整齐"],["ma propre maison","我自己的房子"],["le sens propre","本义（相对于比喻义）"],["nettoyer","打扫（让它干净）"]],"sy":[["net","courant","整洁的"],["nettoyé","courant","擦干净了的"],["sale","courant","脏的（反义）"]],"fq":"高频，日常常用。","me":"propre：位置决定意思：后 = 干净，前 = 自己的。","tr":{"zh":"我的房间干净，而且是我自己的。","fr":"Ma chambre est propre, et c'est ma propre chambre.","alt":"Ma chambre est propre et elle est à moi.","note":"propre 在名词后表示「干净」，在前表示「自己的」。"}},
 "Riche": {"pos":"adj. 形容词，阴阳同形，复数 riches；也可作名词 un(e) riche","s":"有钱的；富有的；丰富的。Il est riche. 说人有钱；une cuisine riche 说菜很浓、油腻；riche en vitamines 说富含维生素。","ipa":"[ʁiʃ]","ph":"r 是小舌音 [ʁ]；i 读 [i]；ch 读 [ʃ]。一个音节，结尾 e 不发音。","pi":"ch 读 [ʃ]，不是 [tʃ]；阴阳同形，不用加 e。","et":"来自法兰克语 *rīki（有权势的）。英语 rich 与它有同一日耳曼词根。","ex":[["Cet homme est riche.","这个男人很有钱。"],["C'est un pays riche.","这是一个富裕的国家。"],["Cette soupe est riche en légumes.","这汤蔬菜很丰富。"]],"co":[["riche en","富含……"],["une famille riche","富裕的家庭"],["un riche héritage","丰厚的遗产"],["devenir riche","变富有"]],"sy":[["aisé","soutenu","富裕的，较委婉"],["fortuné","soutenu","有财产的"],["pauvre","courant","穷的（反义）"]],"fq":"高频，日常常用。","me":"riche：和英语 rich 同根。","tr":{"zh":"这个国家很富裕。","fr":"Ce pays est riche.","alt":"C'est un pays très riche.","note":"riche 阴阳同形。"}},
 "Sale": {"pos":"adj. 形容词，阴阳同形，复数 sales","s":"脏的；不干净的。放在名词前口语里也能表示「讨厌的、糟糕的」：un sale temps（糟糕的天气）、un sale type（坏家伙）。","ipa":"[sal]","ph":"s 在词首读 [s]；a 读 [a]；l 读 [l]；结尾 e 不发音，一个音节。","pi":"sale 和 salle（房间）发音相同，拼写不同（salle 有两个 l）。别和英语 sale（促销）混：促销是 les soldes。","et":"来自法兰克语 *salo（昏暗的，脏的）。同族：salir（弄脏）、salissant（易脏的）。","ex":[["Le sol est sale.","地面很脏。"],["J'ai les mains sales.","我的手很脏。"],["Quel sale temps !","天气真糟糕！"]],"co":[["les mains sales","脏手"],["du linge sale","脏衣服"],["un sale temps","糟糕的天气"],["salir","弄脏"]],"sy":[["crasseux","familier","很脏的"],["souillé","soutenu","被弄脏的"],["propre","courant","干净的（反义）"]],"fq":"高频，日常常用。","me":"sale：一个 l = 脏；salle 两个 l = 房间。","tr":{"zh":"你的鞋子很脏。","fr":"Tes chaussures sont sales.","alt":"T'as les chaussures sales.","note":"复数加 s，但 s 不发音。"}},
 "Sympa": {"pos":"adj. 形容词（口语），不变阴阳，复数 sympas；是 sympathique 的缩写","s":"友好的；不错的；讨人喜欢的。可形容人：Il est sympa.（他人很好。）也可形容地方、事情：un quartier sympa, une soirée sympa。","ipa":"[sɛ̃.pa]","ph":"sym- 读 [sɛ̃]（y 和 m 联合成鼻化音）；pa 读 [pa]。","pi":"sym 读 [sɛ̃]，不是 [sim]；阴阳同形，不用加 e。口语词，正式场合用 sympathique。","et":"sympathique（令人愉快的，希腊语 sympatheia）的缩略。","ex":[["Ce quartier est très sympa.","这个街区很不错。"],["Ta sœur est vraiment sympa.","你姐姐人真好。"],["On a passé une soirée sympa.","我们度过了愉快的夜晚。"]],"co":[["c'est sympa !","真不错！"],["un type sympa","一个好人"],["Sois sympa !","帮个忙吧！"],["sympathique","友好的（完整形式）"]],"sy":[["sympathique","courant","友好的（完整形式）"],["gentil","courant","善良的"],["cool","familier","酷；不错"]],"fq":"极高频，口语常用。","me":"sympa = sympathique 的缩写：很亲切，所以不拘形式。","tr":{"zh":"你的朋友们很友好。","fr":"Tes amis sont très sympas.","alt":"Tes potes sont super sympas.","note":"sympa 阴阳同形；复数可加 s。"}},
 "Qui ?": {"pos":"pron. 疑问代词，不变化","s":"谁？问人用：Qui est-ce ? =「这是谁？」 Qui parle ?（谁在说话？）C'est qui ? 是口语。Qui 也可作关系代词「……的人」。","ipa":"[ki]","ph":"qu 读 [k]；i 读 [i]。一个音节。","pi":"qu 读 [k]，不是 [kw]；Qui ? 只问人，问事物用 Que ? / Quoi ?。","et":"来自拉丁语 qui（谁）。","ex":[["C'est qui ?","这是谁？"],["Qui est-ce ?","这是谁？"],["Avec qui tu vas au cinéma ?","你和谁去看电影？"]],"co":[["Qui est-ce ?","这是谁？"],["À qui est ce livre ?","这本书是谁的？"],["avec qui / pour qui","和谁 / 为谁"],["Qui parle ?","谁在说话？"]],"sy":[["Qui est-ce que...","courant","我问的是宾语：Qui est-ce que tu vois ?"],["Lequel ?","courant","哪一个？"]],"fq":"极高频，几乎每天都用。","me":"Qui = 问人，像「奇」：谁来了？","tr":{"zh":"你和谁一起去？","fr":"Tu y vas avec qui ?","alt":"Avec qui tu y vas ?","note":"介词 + qui：avec qui。"}},
 "(Faire) du sport": {"pos":"loc. 固定短语，faire du sport（faire + du + sport 阳性名词）","s":"做运动；锻炼身体。法语用 faire du + 运动名称：faire du football, faire du sport。泛指体育运动。否定用 de：Je ne fais pas de sport.","ipa":"[fɛʁ dy spɔʁ]","ph":"faire 读 [fɛʁ]；du 读 [dy]；sport 读 [spɔʁ]，结尾 t 不发音。","pi":"sport 的 t 不发音；否定时 du → de：pas de sport。","et":"sport 借自英语 sport，更早来自古法语 desport（消遣）。du 是 de + le 的缩合。","ex":[["Il fait du sport.","他做运动。"],["Tu fais du sport le week-end ?","你周末做运动吗？"],["Je ne fais pas de sport.","我不做运动。"]],"co":[["faire du sport","做运动"],["faire du football / du tennis","踢足球 / 打网球"],["faire de la natation","游泳（做游泳运动）"],["pas de sport","不做运动"]],"sy":[["s'entraîner","courant","训练；锻炼"],["bouger","familier","动一动；活动身体"]],"fq":"极高频，日常常用。","me":"faire + du + 运动：像英语 do sport，但要加 du。","tr":{"zh":"你每周做运动吗？","fr":"Tu fais du sport chaque semaine ?","alt":"Tu fais du sport toutes les semaines ?","note":"否定时 du 变 de：Je ne fais pas de sport。"}},
 "(Faire) la cuisine": {"pos":"loc. 固定短语，faire la cuisine（faire + la cuisine 阴性名词）","s":"做饭；烹饪。la cuisine 同时有「厨房」和「菜肴 / 烹饪」两个意思：Elle fait la cuisine.（她在做饭。）Ma cuisine est petite.（我的厨房很小。）","ipa":"[fɛʁ la kɥi.zin]","ph":"faire 读 [fɛʁ]；cuisine 读 [kɥi.zin]，ui 读 [ɥi]，s 读 [z]。","pi":"cuisine 里的 ui 读 [ɥi]，像「歪」；s 读 [z]，不是 [s]。","et":"cuisine 来自拉丁语 coquina（厨房），源自 coquere（煮，烹）。同族：cuisiner（烹饪）、cuisinier。","ex":[["Elle fait la cuisine.","她在做饭。"],["Je fais la cuisine pour mes amis.","我为朋友们做饭。"],["Qui fait la cuisine chez vous ?","你们家谁做饭？"]],"co":[["faire la cuisine","做饭"],["cuisiner","烹饪（动词）"],["la cuisine française","法国菜"],["un livre de cuisine","食谱书"]],"sy":[["cuisiner","courant","烹饪（动词）"],["préparer le repas","courant","准备饭菜"],["faire à manger","familier","做饭（口语）"]],"fq":"极高频，日常常用。","me":"cuisine：厨房和烹饪，用同一个词。","tr":{"zh":"我们晚上做饭。","fr":"Nous faisons la cuisine le soir.","alt":"On cuisine le soir.","note":"faire la cuisine = 做饭；Je cuisine 也可以。"}},
 "(Faire) la vaisselle": {"pos":"loc. 固定短语，faire la vaisselle（faire + la vaisselle，阴性，不加复数）","s":"洗碗；洗餐具。la vaisselle 指所有的碗、盘、餐具，是不可数名词，没有复数。","ipa":"[fɛʁ la vɛ.sɛl]","ph":"faire 读 [fɛʁ]；vaisselle 读 [vɛ.sɛl]，ai 读 [ɛ]，ss 读 [s]，-lle 读 [l]。","pi":"vaisselle 里 ai 读 [ɛ]，ss 读 [s]；别说 les vaisselles。","et":"来自通俗拉丁语 vascella（小器皿），源自 vas（器皿）。","ex":[["Je fais la vaisselle.","我洗碗。"],["Qui fait la vaisselle ce soir ?","今晚谁洗碗？"],["La vaisselle est sale.","餐具是脏的。"]],"co":[["faire la vaisselle","洗碗"],["un lave-vaisselle","洗碗机"],["du liquide vaisselle","洗洁精"],["essuyer la vaisselle","擦干餐具"]],"sy":[["laver les assiettes","courant","洗盘子"],["plonger","familier","在餐厅洗碗（plongeur）"]],"fq":"高频，日常常用。","me":"vaisselle：想到 vase（花瓶）：所有器皿。","tr":{"zh":"晚饭后我洗碗。","fr":"Je fais la vaisselle après le dîner.","alt":"Je lave la vaisselle après le repas.","note":"la vaisselle 是单数不可数名词。"}},
 "(Faire) le ménage": {"pos":"loc. 固定短语，faire le ménage（faire + le ménage，阳性名词）","s":"做家务；打扫房间。le ménage 是指日常的家务清洁。也可指「一个家庭；一对夫妻」，但在这个短语里是家务。","ipa":"[fɛʁ lə me.naʒ]","ph":"faire 读 [fɛʁ]；ménage 读 [me.naʒ]，é 读 [e]，g 在 e 前读 [ʒ]，结尾 e 不发音。","pi":"ménage 读 [me.naʒ]，只有两个音节，结尾 e 不发音；别和 manège（旋转木马）混。","et":"来自古法语 mesnage（住宅，家），同族：ménager（节约；爱护）、emménager。","ex":[["Je fais le ménage le samedi.","我星期六做家务。"],["Il fait le ménage chaque semaine.","他每周做家务。"],["Nous faisons le ménage ensemble.","我们一起做家务。"]],"co":[["faire le ménage","做家务；打扫"],["faire le ménage à fond","彻底大扫除"],["une femme de ménage","家政女工"],["un produit ménager","清洁用品"]],"sy":[["nettoyer","courant","清洁"],["passer l'aspirateur","courant","吸尘"],["astiquer","familier","擦亮"]],"fq":"极高频，日常常用。","me":"ménage：家务；ménager 是「爱惜」。","tr":{"zh":"我们周日做家务。","fr":"Nous faisons le ménage le dimanche.","alt":"On fait le ménage le dimanche.","note":"做家务不加复数，用 le ménage。"}},
 "(Faire) les courses": {"pos":"loc. 固定短语，faire les courses（faire + les courses，阴性复数）","s":"买东西；采购（尤其是买日用品和食物）。les courses 总用复数。Faire les courses 是去超市 / 市场买日常用品，不是去逛街买衣服（那是 faire du shopping）。","ipa":"[fɛʁ le kuʁs]","ph":"faire 读 [fɛʁ]；les 读 [le]；courses 读 [kuʁs]，ou 读 [u]，结尾 -es 不发音。","pi":"les courses 一定用复数；course（单数）是「赛跑；一次出行」。逛街买衣服用 faire du shopping 或 faire les magasins。","et":"course 来自意大利语 corsa，源自拉丁语 cursus（跑）。「买东西」的意思是由「跑（办事）」引申的。","ex":[["Nous faisons les courses.","我们去采购。"],["Je fais les courses le samedi matin.","我星期六早上买东西。"],["Tu peux faire les courses ?","你能去买东西吗？"]],"co":[["faire les courses","买东西；采购"],["une liste de courses","购物清单"],["un panier de courses","购物篮"],["faire du shopping","逛街购物（买衣服等）"]],"sy":[["faire ses achats","soutenu","购物"],["faire du shopping","courant","逛街购物"],["faire le marché","courant","去市场买菜"]],"fq":"极高频，日常常用。","me":"courses ← courir（跑）：跑来跑去买东西。","tr":{"zh":"我们周六去采购。","fr":"Nous faisons les courses le samedi.","alt":"On fait les courses le samedi.","note":"les courses 总是复数。"}},
 "De l'alcool": {"pos":"n.m. 阳性名词，不可数，复数 alcools（指不同种类的酒）；de l' 是部分冠词（元音前）","s":"酒精；酒（含酒精的饮料）。du / de l' 表示「一部分、一些」。Il ne boit pas d'alcool.（他不喝酒。）否定时 de l' 变 d'。","ipa":"[al.kɔl]","ph":"al 读 [al]；-coo- 读 [kɔ]；l 读 [l]。alcool 读 [al.kɔl]，两个 o 合并成一个 [ɔ]。","pi":"alcool 里只有一个 [ɔ]，两个 o 读起来是一个音，别读成 al-ko-ol；拼写没有 h（英语 alcohol 有 h）。","et":"来自阿拉伯语 al-kuḥl（最早指一种细粉末），后来指提炼出的「精华」。同族：alcoolique、alcoolisé。","ex":[["Il ne boit pas d'alcool.","他不喝酒。"],["Je bois un peu d'alcool.","我喝一点点酒。"],["Ce gâteau contient de l'alcool.","这个蛋糕含酒精。"]],"co":[["ne pas boire d'alcool","不喝酒"],["de l'alcool à 90°","90 度的酒精"],["sans alcool","不含酒精的"],["abuser de l'alcool","酗酒"]],"sy":[["boisson alcoolisée","courant","含酒精饮料"],["spiritueux","soutenu","烈酒"],["gnôle","argot","烈酒（俗语）"]],"fq":"高频，日常常用。","me":"alcool：al- + cool，没有 h，是「酒」的意思。","tr":{"zh":"我不喝酒。","fr":"Je ne bois pas d'alcool.","alt":"Je ne bois jamais d'alcool.","note":"否定后 de l' → d'：pas d'alcool。"}},
 "Du beurre": {"pos":"n.m. 阳性名词，不可数，复数 beurres（指不同种类）；du 是部分冠词","s":"黄油。du beurre 表示「一些黄油」。在法国饮食中非常重要：du pain et du beurre（面包和黄油）。否定时 du → de：pas de beurre。","ipa":"[bœʁ]","ph":"b 读 [b]；eu 读 [œ]（在 r 前，嘴型半开）；r 为小舌音；结尾 -rre 的 e 不发音。","pi":"eu 在 r 前读 [œ]，不是 [u]；两个 r 只读一个 [ʁ]。","et":"来自拉丁语 butyrum，源自希腊语 boutyron。英语 butter 同源。","ex":[["Il n'y a plus de beurre dans le frigo.","冰箱里没有黄油了。"],["Je mets du beurre sur mon pain.","我在面包上抹黄油。"],["Ce gâteau est fait avec du beurre.","这个蛋糕是用黄油做的。"]],"co":[["du beurre salé / doux","咸黄油 / 淡黄油"],["une plaquette de beurre","一块黄油"],["un beurre noisette","榛子黄油（焦黄油）"],["faire fondre du beurre","融化黄油"]],"sy":[["margarine","courant","人造黄油"],["crème","courant","奶油"]],"fq":"高频，饮食话题常用。","me":"beurre ≈ butter：都来自希腊语 boutyron。","tr":{"zh":"我想要一点黄油。","fr":"Je voudrais un peu de beurre.","alt":"Vous avez du beurre, s'il vous plaît ?","note":"un peu de + 名词，de 后不加冠词。"}},
 "Du boeuf": {"pos":"n.m. 阳性名词，作为肉不可数；复数 bœufs [bø]（f 不发音）；du 是部分冠词","s":"牛肉（作为肉）；也指阉牛（活的动物）。du bœuf = 牛肉。有名的菜：le bœuf bourguignon（红酒炖牛肉）。","ipa":"[bœf]","ph":"b 读 [b]；œu 读 [œ]；f 读 [f]。注意复数 bœufs 读 [bø]：eu 读 [ø]，f 不发音。","pi":"单数 f 要发（[bœf]），复数 bœufs 里 f 不发（[bø]）。œ 是连写字母，可写作 oe。","et":"来自拉丁语 bovem（牛）。同族：bovin（牛的），英语 beef 经诺曼法语 boef 而来。","ex":[["C'est de la viande de boeuf.","这是牛肉。"],["Je prends du bœuf avec des frites.","我点牛肉配薯条。"],["Le bœuf bourguignon est un plat célèbre.","红酒炖牛肉是一道名菜。"]],"co":[["du bœuf haché","牛肉馅"],["un steak de bœuf","牛排"],["le bœuf bourguignon","红酒炖牛肉"],["un bœuf / des bœufs","公牛 / 阉牛（复数读 [bø]）"]],"sy":[["viande rouge","courant","红肉"],["vache","courant","母牛（活的动物）"],["taureau","courant","公牛"]],"fq":"中高频，饮食话题常用。","me":"bœuf ≈ beef：都来自拉丁语 bovem。","tr":{"zh":"我想要一些牛肉。","fr":"Je voudrais du bœuf, s'il vous plaît.","alt":"Je prends du bœuf.","note":"表示一部分肉用 du bœuf。"}},
 "Du café": {"pos":"n.m. 阳性名词，不可数；复数 cafés（杯数；咖啡馆）；du 是部分冠词","s":"咖啡。du café 指咖啡这种饮品。un café 在法国是一小杯浓咖啡（espresso）；也指咖啡馆，如 aller au café。","ipa":"[ka.fe]","ph":"c 在 a 前读 [k]；é 读 [e]。一个重音符号只在 e 上，读 [ka.fe]。","pi":"é 要读 [e]，不是 [ə]；注意重音符号 café。一杯咖啡是 un café，一间咖啡馆也是 un café。","et":"经意大利语 caffè，更早来自土耳其语 kahve，源自阿拉伯语 qahwa。英语 coffee 同源。","ex":[["Un café, s'il vous plaît.","请给我一杯咖啡。"],["Je bois du café tous les matins.","我每天早上喝咖啡。"],["On se retrouve au café ?","我们在咖啡馆见面吧？"]],"co":[["un café crème","牛奶咖啡"],["un café serré / allongé","浓缩 / 加水咖啡"],["boire du café","喝咖啡"],["prendre un café","喝杯咖啡"]],"sy":[["expresso","courant","意式浓缩咖啡"],["thé","courant","茶（对比）"],["caoua","familier","咖啡（口语）"]],"fq":"极高频，日常常用。","me":"café：一个词两个意思：咖啡和咖啡馆。","tr":{"zh":"我每天早上喝一杯咖啡。","fr":"Je bois un café tous les matins.","alt":"Je prends un café chaque matin.","note":"boire du café = 喝咖啡；un café = 一杯。"}},
 "Du canard": {"pos":"n.m. 阳性名词，作为肉不可数；复数 canards（鸭子）；du 是部分冠词","s":"鸭肉；也指鸭子（动物）：un canard。du canard 是鸭肉；le canard 是活的鸭。母鸭是 la cane，小鸭是 le caneton。","ipa":"[ka.naʁ]","ph":"c 读 [k]；a 读 [a]；n 读 [n]；r 读 [ʁ]；结尾 d 不发音。","pi":"canard 的结尾 d 不发音，不是 [ka.nard]；r 要读。","et":"可能来自古法语 caner（嘎嘎叫），拟声词，来源不太确定。同族：cane（母鸭）、caneton（小鸭）。","ex":[["Le magret de canard est délicieux.","鸭胸肉很好吃。"],["Je prends du canard à l'orange.","我点橙汁鸭。"],["Il y a un canard sur le lac.","湖上有一只鸭子。"]],"co":[["le magret de canard","鸭胸肉"],["le confit de canard","油封鸭腿"],["du canard laqué","烤鸭"],["un canard / une cane","公鸭 / 母鸭"]],"sy":[["poulet","courant","鸡肉（对比）"],["cane","courant","母鸭"],["oie","courant","鹅"]],"fq":"中频，饮食话题常用。","me":"canard 的 d 不发音，读 [ka.naʁ]。","tr":{"zh":"我想吃鸭肉。","fr":"Je voudrais manger du canard.","alt":"J'ai envie de canard.","note":"du canard = 鸭肉；un canard = 一只鸭子。"}},
 "Du chocolat": {"pos":"n.m. 阳性名词，不可数；复数 chocolats（指各种巧克力糖）；du 是部分冠词","s":"巧克力。du chocolat 指巧克力这种食物；un chocolat 可指一杯热巧克力，或一颗巧克力糖。chocolat chaud = 热巧克力。","ipa":"[ʃɔ.kɔ.la]","ph":"ch 读 [ʃ]；o 读 [ɔ]；c 读 [k]；结尾 -at 读 [a]，t 不发音。","pi":"ch 读 [ʃ]；结尾 t 不发音，读 [la]，不是 [lat]。","et":"经西班牙语 chocolate，源自纳瓦特尔语。英语 chocolate 同源。","ex":[["Je mange un carré de chocolat.","我吃一块巧克力。"],["Je voudrais un chocolat chaud.","我想要一杯热巧克力。"],["Elle adore le chocolat noir.","她特别喜欢黑巧克力。"]],"co":[["du chocolat noir / au lait","黑巧克力 / 牛奶巧克力"],["un chocolat chaud","热巧克力"],["un carré de chocolat","一块巧克力"],["une mousse au chocolat","巧克力慕斯"]],"sy":[["cacao","courant","可可"],["bonbon","courant","糖果（对比）"],["chocolat chaud","courant","热巧克力"]],"fq":"高频，饮食话题常用。","me":"chocolat ≈ chocolate，只是结尾 t 不发音。","tr":{"zh":"我喜欢黑巧克力。","fr":"J'aime le chocolat noir.","alt":"J'adore le chocolat noir.","note":"表示一般喜好用 le chocolat，不用 du。"}},
 "Du fromage": {"pos":"n.m. 阳性名词，不可数；复数 fromages（指各种奶酪）；du 是部分冠词","s":"奶酪。du fromage 指奶酪这种食物；un fromage 是一种奶酪。法国有上百种奶酪：un plateau de fromages（奶酪拼盘）。","ipa":"[fʁɔ.maʒ]","ph":"fr 读 [fʁ]；o 读 [ɔ]；ma 读 [ma]；g 在 e 前读 [ʒ]，结尾 e 不发音。","pi":"fromage 重音在最后；-age 读 [aʒ]；别和英语 form 的音混。fromage 是阳性。","et":"来自拉丁语 formaticus（用模具制成的），源自 forma（模具）。同族：forme。","ex":[["La France est connue pour son fromage.","法国以奶酪闻名。"],["Je prends du fromage après le plat.","主菜后我吃奶酪。"],["Tu aimes le fromage de chèvre ?","你喜欢山羊奶酪吗？"]],"co":[["un plateau de fromages","奶酪拼盘"],["du fromage de chèvre","山羊奶酪"],["du fromage râpé","奶酪碎"],["fromage ou dessert ?","奶酪还是甜点？"]],"sy":[["camembert","courant","卡芒贝尔奶酪（一种）"],["laitage","courant","乳制品"],["fromage blanc","courant","鲜奶酪"]],"fq":"高频，饮食话题常用。","me":"fromage ← forma：用模具做成的奶酪。","tr":{"zh":"饭后我吃一点奶酪。","fr":"Après le repas, je mange un peu de fromage.","alt":"Après manger, je prends du fromage.","note":"un peu de + 名词，de 后不加冠词。"}},
 "Du jus (de fruit)": {"pos":"n.m. 阳性名词，复数 jus（单复数同形）","s":"果汁；汁液。jus de fruit = 水果汁，也说 jus d'orange、jus de pomme。还指肉汁（le jus de viande）。du = 部分冠词，表示「一些」果汁。","ipa":"[ʒy]","ph":"j 读 [ʒ]（类似「日」的浊音）；u 读 [y]（嘴圆如吹口哨，发「衣」）；s 不发音。","pi":"结尾 s 不发音；u 不是「乌」[u]，是 [y]；不要和 jeu（游戏）混淆。","et":"拉丁语 jus，原义「汤汁、肉汤」。","ex":[["Je bois un verre de jus de pomme.","我喝一杯苹果汁。"],["Tu veux du jus d'orange ?","你要橙汁吗？"]],"co":[["un jus d'orange","橙汁"],["un jus de fruit","果汁"],["un jus pressé","鲜榨果汁"]],"sy":[["nectar","courant","果浆（含果肉的果汁）"],["smoothie","courant","思慕雪（外来词）"]],"fq":"高频，日常常用。","me":"jus 听起来像「日」：橙汁 jus d'orange。","tr":{"zh":"早餐我喝橙汁。","fr":"Au petit-déjeuner, je bois du jus d'orange.","alt":"Le matin, je prends un jus d'orange.","note":"喝饮料用 boire + du / un verre de。"}},
 "Du lait": {"pos":"n.m. 阳性名词，不可数，复数 laits（较少用）","s":"牛奶。法国日常说 du lait 就是牛奶；其他奶要加说明：lait de soja（豆奶）、lait d'amande（杏仁奶）。也指植物或化妆品的「乳液」（lait corporel）。","ipa":"[lɛ]","ph":"ai 读 [ɛ]；结尾 t 不发音。","pi":"结尾 -t 不发音；注意 lait（牛奶）和 laid [lɛ]（丑）同音；阳性：le lait。","et":"拉丁语 lac, lactis（奶）。同源：lactose（乳糖）、laitier（乳制品的）。","ex":[["Je bois du lait chaud le soir.","晚上我喝热牛奶。"],["Du lait dans ton café ?","你的咖啡要加奶吗？"]],"co":[["un verre de lait","一杯牛奶"],["du lait entier / demi-écrémé","全脂 / 半脱脂牛奶"],["un café au lait","牛奶咖啡"],["du lait de soja","豆奶"]],"sy":[["crème","courant","奶油（比牛奶浓）"],["lactose","soutenu","乳糖（同源科学词）"]],"fq":"极高频，日常常用。","me":"lait 读 [lɛ]，像「累」：喝了牛奶就不累。","tr":{"zh":"我的咖啡里要加一点牛奶。","fr":"Je prends un peu de lait dans mon café.","alt":"Je mets du lait dans mon café.","note":"不可数名词前用部分冠词 du / un peu de。"}},
 "Du pain": {"pos":"n.m. 阳性名词，不可数，复数 pains","s":"面包（总称）；也可数：un pain = 一个（整条）面包。法国人日常主要吃的是长棍 la baguette。du pain = 一些面包。","ipa":"[pɛ̃]","ph":"ain 读鼻化元音 [ɛ̃]，类似「呃」带鼻音；结尾 n 不发音。","pi":"ain 不是「安」，是鼻化 [ɛ̃]；注意与 pan、peint 同音。","et":"拉丁语 panis（面包）。同源：panier（面包篮）、compagnon（伙伴，字面「一起吃面包的人」）。","ex":[["J'achète du pain tous les jours.","我每天买面包。"],["Passe-moi le pain, s'il te plaît.","请把面包递给我。"]],"co":[["une baguette de pain","一根长棍面包"],["du pain grillé","烤面包片"],["pain complet","全麦面包"],["acheter du pain","买面包"]],"sy":[["baguette","courant","长棍面包"],["miche","courant","圆面包"],["bouffe","familier","（泛指）吃的"]],"fq":"极高频，日常常用。","me":"pain [pɛ̃] ≈「朋」：好朋友一起分面包。","tr":{"zh":"我想买面包和牛奶。","fr":"Je voudrais acheter du pain et du lait.","alt":"Je vais prendre du pain et du lait.","note":"买「一些」东西用 du / de la；pain、lait 都是阳性。"}},
 "Du poisson": {"pos":"n.m. 阳性名词，复数 poissons","s":"鱼；鱼肉。活的鱼和盘中的鱼都叫 poisson。du poisson = 一些鱼肉（部分冠词）；un poisson = 一条鱼。","ipa":"[pwa.sɔ̃]","ph":"oi 读 [wa]；ss 读清音 [s]；结尾 on 读鼻化 [ɔ̃]，n 不发音。","pi":"poisson（鱼）和 poison [pwa.zɔ̃]（毒药）只差一个 s：ss 读 [s]，单个 s 读 [z]。","et":"拉丁语 piscis（鱼）。同源：pisciculture（养鱼业）。","ex":[["Je mange du poisson le vendredi.","我星期五吃鱼。"],["Il pêche un poisson dans la rivière.","他在河里钓到一条鱼。"]],"co":[["du poisson frais","新鲜的鱼"],["un poisson rouge","金鱼"],["poisson d'avril","愚人节玩笑（四月的鱼）"],["un filet de poisson","鱼排"]],"sy":[["fruits de mer","courant","海鲜（贝类虾蟹）"],["poiscaille","argot","鱼（俚语）"]],"fq":"高频，日常常用。","me":"poisson [pwa.sɔ̃]：两个 s = 鱼，一个 s = 毒药。","tr":{"zh":"我们今晚吃鱼和米饭。","fr":"Ce soir, on mange du poisson avec du riz.","alt":"Ce soir, c'est poisson et riz.","note":"on = nous，口语常用；avec 后接 du riz。"}},
 "Du poivre": {"pos":"n.m. 阳性名词，不可数，复数 poivres","s":"胡椒（黑胡椒粉）。常与 sel 连用：le sel et le poivre。du poivre = 一些胡椒。注意 poivre 不是辣椒，辣椒是 piment。","ipa":"[pwavʁ]","ph":"oi 读 [wa]；v 读 [v]；结尾 -re 读 [ʁ]（喉音），e 不发音。","pi":"结尾 e 不发音；r 是喉音 [ʁ]，不是中文的「r」；和 poivron（甜椒）区分。","et":"拉丁语 piper，来自希腊语 peperi，源自印度语。","ex":[["Je mets du sel et du poivre.","我放盐和胡椒。"],["Tu veux un peu de poivre ?","你要一点胡椒吗？"]],"co":[["du poivre noir","黑胡椒"],["un moulin à poivre","胡椒研磨器"],["sel et poivre","盐和胡椒"],["poivre et sel","黑白相间的（头发）"]],"sy":[["piment","courant","辣椒（更辣）"],["épice","courant","香料（泛称）"]],"fq":"中高频，烹饪常用。","me":"poivre [pwavʁ]：胡椒粉一撒，人就打喷嚏。","tr":{"zh":"请给我一点盐和胡椒。","fr":"Un peu de sel et de poivre, s'il vous plaît.","alt":"Passez-moi le sel et le poivre, s'il vous plaît.","note":"un peu de + 不可数名词，不加冠词。"}},
 "Du poulet": {"pos":"n.m. 阳性名词，复数 poulets","s":"鸡肉；小鸡。du poulet = 鸡肉（做菜）；un poulet = 一只鸡。母鸡是 la poule，公鸡是 le coq。口语中 un poulet 也可指警察（俚语）。","ipa":"[pu.lɛ]","ph":"ou 读 [u]；et 在词尾读 [ɛ]，t 不发音。","pi":"结尾 -et 读 [ɛ]，t 不发音；ou 读「乌」，不是「奥」。","et":"来自古法语 poul（小鸡，拉丁语 pullus）加指小后缀 -et。同源：poule（母鸡）。","ex":[["On mange du poulet ce midi.","今天中午吃鸡肉。"],["Le poulet rôti est délicieux.","烤鸡很好吃。"]],"co":[["du poulet rôti","烤鸡"],["un blanc de poulet","鸡胸肉"],["une cuisse de poulet","鸡腿"],["poulet frites","炸鸡配薯条"]],"sy":[["volaille","courant","禽肉（家禽总称）"],["poule","courant","母鸡"],["poulet (police)","argot","警察（俚语）"]],"fq":"高频，日常常用。","me":"poulet = 小 poule（母鸡）：一只「小鸡」。","tr":{"zh":"我们晚上吃烤鸡。","fr":"Ce soir, on mange du poulet rôti.","alt":"Ce soir, c'est poulet rôti.","note":"rôti 是形容词，跟在名词后面。"}},
 "Du riz": {"pos":"n.m. 阳性名词，不可数，复数 riz（单复数同形）","s":"米饭；大米。du riz = 一些米饭 / 大米。煮熟的饭和生米都叫 riz；日常说「吃饭」常说 manger du riz。","ipa":"[ʁi]","ph":"r 是喉音 [ʁ]；i 读 [i]；结尾 z 不发音。","pi":"结尾 z 不发音；riz（米）与 ris（rire 的变位）同音；r 是喉音，不是中文的「r」。","et":"来自意大利语 riso，拉丁语 oryza，希腊语 oruza，源头在东方。","ex":[["Je mange du riz avec le poulet.","我吃米饭配鸡肉。"],["Le riz cuit dix minutes.","米饭煮十分钟。"]],"co":[["du riz blanc / complet","白米 / 糙米"],["du riz au lait","米布丁（牛奶煮米）"],["du riz cantonais","扬州炒饭（广式炒饭）"],["cuire du riz","煮饭"]],"sy":[["céréale","courant","谷物（泛称）"],["pâtes","courant","意面（另一种主食）"]],"fq":"高频，日常常用。","me":"riz [ʁi]：一碗米饭，吃得笑（rire）起来。","tr":{"zh":"你想吃米饭还是意面？","fr":"Tu veux du riz ou des pâtes ?","alt":"Tu préfères du riz ou des pâtes ?","note":"pâtes 常用复数：des pâtes。"}},
 "Du saumon": {"pos":"n.m. 阳性名词，复数 saumons","s":"三文鱼；鲑鱼肉。du saumon = 一些三文鱼肉；un saumon = 一条鲑鱼。颜色形容词 saumon（粉橙色）不变化。","ipa":"[so.mɔ̃]","ph":"au 读 [o]；m 读 [m]；结尾 on 读鼻化 [ɔ̃]，n 不发音。","pi":"au 读「哦」[o]，不是「奥」；结尾鼻化音，不发 n。","et":"拉丁语 salmo, salmonis（鲑鱼）。","ex":[["Je prépare un pavé de saumon.","我做一块三文鱼。"],["Tu aimes le saumon fumé ?","你喜欢熏三文鱼吗？"]],"co":[["du saumon fumé","熏三文鱼"],["un pavé de saumon","一块厚三文鱼排"],["des sushis au saumon","三文鱼寿司"],["une robe saumon","粉橙色连衣裙"]],"sy":[["truite","courant","鳟鱼（相近的鱼）"],["poisson","courant","鱼（泛称）"]],"fq":"中高频，饮食常用。","me":"saumon：三文鱼 = 橙粉色，颜色词 saumon 也一样。","tr":{"zh":"我喜欢吃熏三文鱼。","fr":"J'aime manger du saumon fumé.","alt":"J'adore le saumon fumé.","note":"喜欢一类食物用定冠词：J'aime le saumon。"}},
 "Du sel": {"pos":"n.m. 阳性名词，不可数，复数 sels","s":"盐；食盐。du sel = 一些盐。也有「趣味、风趣」的意思：le sel d'une histoire = 故事的妙处。","ipa":"[sɛl]","ph":"s 读 [s]；e 读 [ɛ]；结尾 l 要发音 [l]。","pi":"结尾 l 要发音，不要吞掉；sel（盐）和 selle（马鞍）同音。","et":"拉丁语 sal, salis（盐）。同源：salé（咸的）、salaire（薪水，原指发盐的钱）。","ex":[["Passe-moi le sel, s'il te plaît.","请把盐递给我。"],["Il manque un peu de sel.","有点缺盐。"]],"co":[["sel et poivre","盐和胡椒"],["du gros sel","粗盐"],["du sel de mer","海盐"],["un grain de sel","一粒盐"]],"sy":[["salé","courant","咸的（形容词）"],["sucre","courant","糖（反义）"]],"fq":"极高频，日常常用。","me":"sel [sɛl] ≈「赛」：盐在海水里「赛」跑。","tr":{"zh":"汤里不要放太多盐。","fr":"Ne mets pas trop de sel dans la soupe.","alt":"Pas trop de sel dans la soupe !","note":"否定命令式：ne + 动词 + pas；trop de + 名词。"}},
 "Du thé": {"pos":"n.m. 阳性名词，不可数，复数 thés","s":"茶；一杯茶。du thé = 一些茶；un thé = 一杯茶。种类：thé noir（红茶）、thé vert（绿茶）。注意法语里 thé noir 是「红茶」。","ipa":"[te]","ph":"th 读 [t]，h 不发音；é 读 [e]（嘴角往两边拉）。","pi":"th 读 [t]，不是「s」；法语 thé noir = 红茶（直译「黑茶」，不是中文的黑茶）；é 的重音符号不能漏。","et":"来自荷兰语 thee，源自闽南话 te（茶）。","ex":[["Je bois du thé le matin.","我早上喝茶。"],["Un thé vert, s'il vous plaît.","请来一杯绿茶。"]],"co":[["du thé noir / vert","红茶 / 绿茶"],["une tasse de thé","一杯茶"],["du thé au citron","柠檬茶"],["l'heure du thé","下午茶时间"]],"sy":[["infusion","courant","花草茶（无茶叶的药草茶）"],["tisane","courant","花草茶（睡前常喝）"]],"fq":"高频，日常常用。","me":"thé [te] 像中文「特」：喝茶很特别。","tr":{"zh":"我想喝一杯热茶。","fr":"Je voudrais une tasse de thé chaud.","alt":"Je prendrais bien un thé chaud.","note":"une tasse de + 名词：不加冠词。"}},
 "Du thon": {"pos":"n.m. 阳性名词，复数 thons","s":"金枪鱼；吞拿鱼（罐头也常叫 thon）。du thon = 一些金枪鱼；thon en boîte = 罐头金枪鱼。","ipa":"[tɔ̃]","ph":"th 读 [t]，h 不发音；on 读鼻化 [ɔ̃]，n 不发音。","pi":"th 读 [t]；鼻化 [ɔ̃] 不要读成「东」或「通」；注意和 ton（你的）同音。","et":"拉丁语 thunnus，来自希腊语 thunnos。","ex":[["Je fais une salade au thon.","我做金枪鱼沙拉。"],["Une boîte de thon, s'il vous plaît.","请给我一罐金枪鱼。"]],"co":[["du thon en boîte","罐头金枪鱼"],["une salade au thon","金枪鱼沙拉"],["du thon rouge","蓝鳍金枪鱼"],["un sandwich au thon","金枪鱼三明治"]],"sy":[["saumon","courant","三文鱼（另一种常见鱼）"],["poisson","courant","鱼（泛称）"]],"fq":"中高频，饮食常用。","me":"thon 与 ton 同音：「你的」鱼 = ton thon。","tr":{"zh":"我午饭吃金枪鱼三明治。","fr":"Pour le déjeuner, je mange un sandwich au thon.","alt":"À midi, je prends un sandwich au thon.","note":"un sandwich au thon：au = à + le，表示「加了……」。"}},
 "Du vin (rouge, rosé, blanc)": {"pos":"n.m. 阳性名词，复数 vins","s":"葡萄酒。三种颜色：vin rouge（红）、vin blanc（白）、vin rosé（桃红）。du vin = 一些酒；un vin = 一种酒。法国人常在饭桌上喝酒。","ipa":"[vɛ̃]","ph":"v 读 [v]（上齿咬下唇）；in 读鼻化 [ɛ̃]，n 不发音。","pi":"v 要咬下唇，不是中文的 w；in 是鼻化，不读 in；和 vingt [vɛ̃]（二十）同音。","et":"拉丁语 vinum（酒）。同源：vigne（葡萄藤）、vinaigre（醋，字面「酸酒」）。","ex":[["Je bois un verre de vin rouge.","我喝一杯红酒。"],["Un verre de vin blanc, s'il vous plaît.","请来一杯白葡萄酒。"]],"co":[["un verre de vin","一杯酒"],["du vin rouge / blanc / rosé","红 / 白 / 桃红葡萄酒"],["une bouteille de vin","一瓶酒"],["la carte des vins","酒单"]],"sy":[["pinard","familier","红酒（口语）"],["boisson","courant","饮料（泛称）"]],"fq":"高频，日常常用。","me":"vin 与 vingt 同音：二十杯酒，太多了。","tr":{"zh":"我们点一瓶白葡萄酒吧。","fr":"On prend une bouteille de vin blanc ?","alt":"Si on commandait une bouteille de vin blanc ?","note":"On ... ? 口语里表示建议；une bouteille de + 名词。"}},
 "Du yahourt": {"pos":"n.m. 阳性名词，复数 yahourts（常拼 yaourt）","s":"酸奶。较常见的拼写是 yaourt，yahourt 是另一种拼法，读音相同。口语常缩成 yaourt / yop。du yahourt = 一些酸奶；un yahourt = 一杯酸奶。","ipa":"[ja.uʁt]","ph":"y 读 [j]；h 不发音；ou 读 [u]；r 读喉音 [ʁ]；结尾 t 要发音。","pi":"h 不发音：ya-ourt，分两个音节；结尾 t 要发音；拼写 yaourt / yahourt 都对。","et":"来自土耳其语 yoğurt。","ex":[["Je mange du yahourt au dessert.","甜点我吃酸奶。"],["Un yaourt nature, s'il vous plaît.","请来一杯原味酸奶。"]],"co":[["un yaourt nature","原味酸奶"],["un yaourt aux fruits","水果酸奶"],["un yaourt à boire","饮用型酸奶"],["un pot de yaourt","一杯酸奶"]],"sy":[["fromage blanc","courant","白奶酪（更浓稠）"],["dessert","courant","甜点（泛称）"]],"fq":"中高频，日常常用。","me":"ya-ourt：yeah + out，酸奶「出」冰箱。","tr":{"zh":"我早上吃酸奶和面包。","fr":"Le matin, je mange un yaourt et du pain.","alt":"Au petit-déjeuner, je prends un yaourt avec du pain.","note":"un yaourt 可数（一杯），du pain 不可数（一些）。"}},
 "Le déjeuner": {"pos":"n.m. 阳性名词，复数 déjeuners","s":"午饭；午餐。le déjeuner 在法国指中午的正餐，常在 12–14 点。动词 déjeuner = 吃午饭。注意在魁北克法语里 déjeuner 指早餐。","ipa":"[de.ʒœ.ne]","ph":"dé [de]；j 读 [ʒ]；eu 在非重读音节读 [œ]；-er 读 [e]。","pi":"是午饭，不是早饭（早饭是 petit-déjeuner）；j 读 [ʒ]，不是「j」；动词和名词拼写一样。","et":"古法语 desjeuner，由 des-（去掉）+ jeûner（禁食，拉丁语 jejunus）组成，字面意思「结束禁食」。","ex":[["Je prends mon déjeuner à midi.","我中午吃午饭。"],["On déjeune ensemble demain ?","明天一起吃午饭吗？"]],"co":[["prendre son déjeuner","吃午饭"],["un déjeuner d'affaires","商务午餐"],["à l'heure du déjeuner","午饭时间"],["pour le déjeuner","作为午饭"]],"sy":[["repas de midi","courant","中午那顿饭"],["dîner","courant","晚饭（对比）"],["casse-croûte","familier","点心、便餐"]],"fq":"高频，日常常用。","me":"dé-jeûner = 「解除禁食」：早上最先吃的，但今天指午饭。","tr":{"zh":"我们十二点半吃午饭。","fr":"On prend le déjeuner à midi et demi.","alt":"On déjeune à midi et demi.","note":"几点半：midi et demi（十二点半）；动词 déjeuner 更常用。"}},
 "Le dessert": {"pos":"n.m. 阳性名词，复数 desserts","s":"甜点；饭后甜食。法国午晚餐的最后一道：fromage 之后是 dessert。pour le dessert = 作为甜点。","ipa":"[de.sɛʁ]","ph":"dé [de]；ss 读清音 [s]；e 读 [ɛ]；结尾 t 不发音，r 读喉音 [ʁ]。","pi":"dessert（甜点）有两个 s，读 [s]；désert（沙漠）只有一个 s，读 [z]；结尾 t 不发音。","et":"来自 desservir（撤走餐具），字面「撤桌后的那道菜」，由 des- + servir 组成。","ex":[["Qu'est-ce qu'il y a pour le dessert ?","甜点有什么？"],["Je prends un dessert au chocolat.","我点一份巧克力甜点。"]],"co":[["au dessert","吃甜点时"],["pour le dessert","作为甜点"],["un dessert maison","自制甜点"],["entrée, plat, dessert","前菜、主菜、甜点"]],"sy":[["gâteau","courant","蛋糕"],["sucrerie","courant","糖果甜食"],["entrée","courant","前菜（对比）"]],"fq":"高频，日常常用。","me":"dessert：两个 s = 两份甜点；désert 一个 s = 沙漠。","tr":{"zh":"你想吃什么甜点？","fr":"Qu'est-ce que tu veux comme dessert ?","alt":"Tu prends quoi comme dessert ?","note":"comme + 名词，表示「作为……」。"}},
 "Le dîner": {"pos":"n.m. 阳性名词，复数 dîners","s":"晚饭；晚餐。在法国本土 le dîner 是晚上那顿正餐，常在 19–21 点。动词 dîner = 吃晚饭。在魁北克，dîner 指午饭。","ipa":"[di.ne]","ph":"î 读 [i]（只是长一点）；n 读 [n]；-er 读 [e]。","pi":"î 的帽子符号不影响读音；不要和 déjeuner（午饭）混淆；英语 dinner 有两个 n，法语只有一个。","et":"古法语 disner，来自 dis-（去掉）+ jeûner（禁食），与 déjeuner 同源。","ex":[["Le dîner est prêt.","晚饭好了。"],["On dîne à huit heures.","我们八点吃晚饭。"]],"co":[["préparer le dîner","准备晚饭"],["un dîner aux chandelles","烛光晚餐"],["inviter à dîner","邀请吃晚饭"],["un dîner de famille","家庭聚餐"]],"sy":[["souper","soutenu","晚餐（少用，或指夜宵）"],["repas du soir","courant","晚上那顿饭"],["déjeuner","courant","午饭（对比）"]],"fq":"极高频，日常常用。","me":"dîner = di + né：dì-nè，天黑了吃饭。","tr":{"zh":"今晚我邀请朋友来吃晚饭。","fr":"Ce soir, j'invite des amis à dîner.","alt":"Ce soir, j'ai des amis à dîner.","note":"inviter quelqu'un à + 动词原形。"}},
 "Le petit-déjeuner": {"pos":"n.m. 阳性名词，复数 petits-déjeuners","s":"早餐。字面是「小的午饭」。口语常缩写为 le petit-déj'。动词：prendre son petit-déjeuner。法国早餐常是咖啡、羊角面包或面包片。","ipa":"[pə.ti.de.ʒœ.ne]","ph":"petit 读 [pə.ti]：第一个 e 轻读 [ə]，t 读出来；déjeuner 同 le déjeuner。","pi":"复数两个词都变：des petits-déjeuners；口语中第一个 e 常被省略，说成 [pti.de.ʒœ.ne]；别和 déjeuner（午饭）混淆。","et":"petit（小）+ déjeuner（本指早上第一餐），后来 déjeuner 移到中午，早餐才加 petit。","ex":[["Je prends mon petit-déjeuner à 8h.","我八点吃早餐。"],["Au petit-déjeuner, je mange des tartines.","早餐我吃抹酱面包片。"]],"co":[["prendre son petit-déjeuner","吃早餐"],["le petit-déjeuner continental","欧陆式早餐"],["au petit-déjeuner","吃早餐时"],["un petit-déj'","（口语）早餐"]],"sy":[["petit-déj'","familier","早餐（口语缩写）"],["brunch","courant","早午餐（外来词）"],["déjeuner","courant","午饭（对比）"]],"fq":"高频，日常常用。","me":"petit + déjeuner = 小午饭 = 早餐。","tr":{"zh":"我每天早上八点吃早餐。","fr":"Je prends mon petit-déjeuner tous les matins à huit heures.","alt":"Tous les matins, je prends mon petit-déj' à huit heures.","note":"tous les matins = 每天早上。"}},
 "Le plat": {"pos":"n.m. 阳性名词，复数 plats","s":"一道菜；菜肴；盘子。le plat principal = 主菜；le plat du jour = 今日套餐；也指上菜用的大盘。plat 作形容词意为「平的」。","ipa":"[pla]","ph":"pl 连读 [pl]；a 读 [a]；结尾 t 不发音。","pi":"结尾 t 不发音；名词 le plat（菜）和形容词 plat（平的）同形；注意阳性：le plat。","et":"来自拉丁语通俗用语 plattus（平的），源自希腊语 platys（宽的、平的）。","ex":[["Le plat du jour est bon.","今日套餐很好吃。"],["Mon plat préféré, c'est le poulet.","我最爱的菜是鸡肉。"]],"co":[["le plat du jour","今日套餐"],["le plat principal","主菜"],["un plat chaud / froid","热菜 / 冷菜"],["un plat maison","家常菜"]],"sy":[["assiette","courant","盘子；一盘菜"],["repas","courant","一顿饭"],["mets","soutenu","菜肴（书面）"]],"fq":"高频，餐厅常用。","me":"plat：平平的盘子，端上来的就是一道菜。","tr":{"zh":"今日套餐是什么？","fr":"Quel est le plat du jour ?","alt":"C'est quoi, le plat du jour ?","note":"Quel est... ? 问「哪一个」；口语可用 C'est quoi ?"}},
 "Le prix": {"pos":"n.m. 阳性名词，复数 prix（单复数同形）","s":"价格；价钱；奖（le prix Nobel）。问价格：Quel est le prix ? 或 C'est combien ? le prix de... = ……的价格。","ipa":"[pʁi]","ph":"p + r（喉音 [ʁ]）+ i；结尾 x 不发音。","pi":"结尾 x 不发音；单复数同形 prix；r 是喉音；不要和 pris（prendre 的过去分词）混淆，两者同音。","et":"拉丁语 pretium（价值、价钱）。同源：précieux（珍贵的）、apprécier（欣赏）。","ex":[["Quel est le prix de cette robe ?","这条裙子多少钱？"],["Les prix sont élevés ici.","这里价格很高。"]],"co":[["à bas prix / à prix réduit","低价 / 折扣价"],["le prix d'un billet","票价"],["à tout prix","不惜一切代价"],["gagner un prix","获奖"]],"sy":[["tarif","courant","收费标准、价目"],["coût","soutenu","成本、花费"],["somme","courant","金额"]],"fq":"极高频，购物常用。","me":"prix 读 [pʁi]，像「批」：打折「批」价格。","tr":{"zh":"这个蛋糕的价格是多少？","fr":"Quel est le prix de ce gâteau ?","alt":"Ce gâteau, il coûte combien ?","note":"Quel est le prix de + 名词；口语用 coûter combien。"}},
 "Un abricot": {"pos":"n.m. 阳性名词，复数 abricots","s":"杏子；杏。un abricot = 一个杏；也说 abricotier（杏树）。夏天水果，常做果酱 confiture d'abricots。","ipa":"[a.bʁi.ko]","ph":"a [a]；b [b]；r 喉音 [ʁ]；结尾 t 不发音，读 [ko]。","pi":"结尾 t 不发音；开头 a 不是「奥」；r 是喉音。","et":"来自阿拉伯语 al-barqūq，经加泰罗尼亚语 / 西班牙语传入。","ex":[["Je mange un abricot.","我吃一个杏子。"],["J'aime la confiture d'abricots.","我喜欢杏子酱。"]],"co":[["un abricot mûr","熟杏子"],["de la confiture d'abricots","杏子酱"],["une tarte aux abricots","杏子馅饼"],["un abricot sec","杏干"]],"sy":[["pêche","courant","桃子（相近水果）"],["prune","courant","李子"]],"fq":"中频，夏季水果。","me":"abricot：a-bri-cot，「阿布里科」，夏天金黄的水果。","tr":{"zh":"我夏天喜欢吃杏子。","fr":"En été, j'aime manger des abricots.","alt":"L'été, j'adore les abricots.","note":"泛指喜欢的水果用 les。"}},
 "Un avocat": {"pos":"n.m. 阳性名词，复数 avocats；女律师 une avocate","s":"①牛油果（水果）；②律师。两个意思拼写相同，看上下文：manger un avocat 是吃牛油果；consulter un avocat 是请教律师。","ipa":"[a.vɔ.ka]","ph":"a [a]；v 咬下唇 [v]；o 读开口 [ɔ]；结尾 t 不发音。","pi":"结尾 t 不发音；avocat 有两个意思，别搞混；v 不是 w。","et":"「律师」来自拉丁语 advocatus（被请来辩护的人）；「牛油果」来自纳瓦特尔语 ahuacatl，经西班牙语 aguacate，法语受 avocat 影响。","ex":[["L'avocat est bon pour la santé.","牛油果有益健康。"],["Mon frère est avocat.","我哥哥是律师。"]],"co":[["une salade d'avocat","牛油果沙拉"],["un avocat mûr","熟透的牛油果"],["consulter un avocat","请教律师"],["une avocate","女律师"]],"sy":[["juriste","courant","法律工作者"],["fruit","courant","水果（泛称）"]],"fq":"中高频，两个义项都常用。","me":"avocat：avoca-t，一个词两个面：吃的 / 打官司的。","tr":{"zh":"我买了一个牛油果做沙拉。","fr":"J'ai acheté un avocat pour la salade.","alt":"J'ai pris un avocat pour faire une salade.","note":"avoir 的现在时 + 过去分词 acheté：复合过去时。"}},
 "Un burger": {"pos":"n.m. 阳性名词，复数 burgers","s":"汉堡。来自英语，法国年轻人很常吃。un burger 指一个汉堡；常配 frites（薯条）。也说 hamburger。","ipa":"[bœʁ.ɡœʁ]","ph":"法语读法：bur [bœʁ]，ger 读 [ɡœʁ]，g 是硬音 [ɡ]；两个 r 都是喉音。","pi":"法语里 -ger 的 g 读硬音 [ɡ]，不是英语的 [dʒ]；两个 r 都发喉音；不要按英语读 [bɜːɡə]。","et":"英语 burger，缩写自 hamburger，源于德国城市 Hambourg。","ex":[["Il mange un burger avec des frites.","他吃汉堡配薯条。"],["Je prends un burger au fromage.","我要一个芝士汉堡。"]],"co":[["un burger maison","自制汉堡"],["un burger au fromage","芝士汉堡"],["un burger-frites","汉堡配薯条"],["un burger végétarien","素汉堡"]],"sy":[["hamburger","courant","汉堡（全称）"],["sandwich","courant","三明治"]],"fq":"中高频，年轻人常用。","me":"burger：法语读 [bœʁ.ɡœʁ]，两个 r 都发喉音。","tr":{"zh":"我今晚想吃汉堡和薯条。","fr":"Ce soir, j'ai envie d'un burger avec des frites.","alt":"Ce soir, j'ai envie de burger-frites.","note":"avoir envie de + 名词 / 动词原形：想要。"}},
 "Un clafoutis": {"pos":"n.m. 阳性名词，复数 clafoutis（单复数同形）","s":"克拉芙缇：法国传统甜点，把樱桃（或其他水果）放进面糊后烤熟的布丁糕。clafoutis aux cerises 最经典。","ipa":"[kla.fu.ti]","ph":"cl [kl]；a [a]；ou 读 [u]；结尾 s 不发音。","pi":"结尾 s 不发音，单复数同形；ou 读「乌」；重音在最后一个音节。","et":"来自奥克语（法国南部）clafotis，与动词 clafir（填满）有关，指「塞满水果」。","ex":[["Ma grand-mère fait un clafoutis aux cerises.","奶奶做樱桃克拉芙缇。"],["Le clafoutis est encore chaud.","克拉芙缇还是热的。"]],"co":[["un clafoutis aux cerises","樱桃克拉芙缇"],["un clafoutis aux poires","梨子克拉芙缇"],["faire un clafoutis","做克拉芙缇"],["un clafoutis maison","自制克拉芙缇"]],"sy":[["tarte","courant","馅饼（有饼底）"],["flan","courant","布丁（更像蛋奶糕）"],["gâteau","courant","蛋糕"]],"fq":"低中频，传统甜点。","me":"clafoutis：把樱桃「塞满」面糊（clafir = 填满）。","tr":{"zh":"你会做樱桃克拉芙缇吗？","fr":"Tu sais faire un clafoutis aux cerises ?","alt":"Tu sais préparer un clafoutis aux cerises ?","note":"savoir + 动词原形：会做某事。"}},
 "Un commerce": {"pos":"n.m. 阳性名词，复数 commerces","s":"商店；店铺（un commerce de proximité = 社区小店）；生意；商业（le commerce）。un commerce 常指街边的小店，如面包店、水果店。","ipa":"[kɔ.mɛʁs]","ph":"c [k]；o 读开口 [ɔ]；mm 只读一个 [m]；e 读 [ɛ]；r 喉音 [ʁ]；s 读 [s]；结尾 ce 的 e 不发音。","pi":"mm 只读一个 m；结尾 -ce 读 [s]，e 不发音；un commerce 常指一家店，不只是「商业」。","et":"拉丁语 commercium，由 com-（一起）+ merx（商品）组成。同源：marchand、marché。","ex":[["Il y a un commerce ici.","这里有一家商店。"],["Les petits commerces ferment à 19h.","小商店晚上七点关门。"]],"co":[["un petit commerce","小店"],["le commerce en ligne","网上购物"],["un commerce de proximité","社区商店"],["faire du commerce","做生意"]],"sy":[["magasin","courant","商店"],["boutique","courant","小店、专卖店"],["affaire","courant","生意、事务"]],"fq":"中高频，生活与经济都用。","me":"commerce = com + merce：和「商品 (merx)」一起做生意。","tr":{"zh":"我们街上有很多小商店。","fr":"Il y a beaucoup de petits commerces dans notre rue.","alt":"Dans notre rue, il y a plein de petits commerces.","note":"il y a + 名词：有……；beaucoup de 后不加冠词。"}},
 "Un couteau": {"pos":"n.m. 阳性名词，复数 couteaux（-eau 的复数加 x）","s":"刀；餐刀。餐桌上的刀叉是 le couteau et la fourchette。Un couteau de cuisine 是菜刀。","ipa":"[ku.to]","ph":"ou 读 [u]；eau 读 [o]。","pi":"复数是 couteaux，不是 couteaus；eau 读 [o]，不读 [au]；复数的 x 不发音。","et":"拉丁语 cultellus，是 culter（刀）的指小词。","ex":[["Il me faut un couteau pour couper.","我需要一把刀来切。"],["Le couteau est sur la table.","刀在桌上。"]],"co":[["un couteau de cuisine","菜刀"],["un couteau à pain","面包刀"],["un couteau suisse","瑞士军刀"],["couper au couteau","用刀切"]],"sy":[["lame","courant","刀刃"],["canif","courant","小折刀"],["fourchette","courant","叉子（搭配）"]],"fq":"高频，餐桌常用。","me":"couteau → couteaux：eau + x，像 chapeau / bateau。","tr":{"zh":"请给我一把刀和一把叉子。","fr":"Un couteau et une fourchette, s'il vous plaît.","alt":"Je voudrais un couteau et une fourchette, s'il vous plaît.","note":"餐具搭配：le couteau et la fourchette。"}},
 "Un croissant": {"pos":"n.m. 阳性名词，复数 croissants","s":"羊角面包；牛角包。法国早餐代表，月牙形，所以叫 croissant（月牙）。也指月牙形：un croissant de lune。","ipa":"[kʁwa.sɑ̃]","ph":"cr [kʁ]；oi 读 [wa]；ss 读 [s]；an 读鼻化 [ɑ̃]；结尾 t 不发音。","pi":"结尾 t 不发音；oi 读 [wa]；an 是鼻化音，不发 n；别读成英语 [kwɑːsɒ̃]。","et":"croître（增长）的现在分词，原指「渐盈的月亮」（月牙）；面包因形似得名。","ex":[["Un café et un croissant, s'il vous plaît.","请来一杯咖啡和羊角面包。"],["Les croissants sont encore chauds.","羊角面包还是热的。"]],"co":[["un croissant au beurre","黄油羊角面包"],["un croissant aux amandes","杏仁羊角面包"],["un café-croissant","咖啡配羊角面包"],["un croissant de lune","月牙"]],"sy":[["viennoiserie","courant","维也纳式面点（泛称）"],["pain au chocolat","courant","巧克力面包"],["brioche","courant","奶油面包"]],"fq":"高频，早餐常用。","me":"croissant = 增长的月亮：形状像月牙。","tr":{"zh":"我早上喜欢吃羊角面包。","fr":"Le matin, j'aime manger un croissant.","alt":"Le matin, je prends souvent un croissant.","note":"j'aime + 动词原形：喜欢做某事。"}},
 "Un gramme": {"pos":"n.m. 阳性名词，复数 grammes；缩写 g","s":"克（重量单位）。100 grammes de beurre = 一百克黄油。常用缩写 g。1000 grammes = un kilo。","ipa":"[ɡʁam]","ph":"g 读硬音 [ɡ]；r 喉音 [ʁ]；mm 只读一个 [m]；结尾 e 不发音。","pi":"mm 只读一个 m；结尾 e 不发音；gramme（克）有两个 m，grammaire（语法）读 [ɡʁa.mɛʁ]。","et":"来自希腊语 gramma（小重量），经晚期拉丁语 gramma。同源：kilogramme。","ex":[["Ajoutez un gramme de sel.","加一克盐。"],["J'achète 200 grammes de fromage.","我买两百克奶酪。"]],"co":[["cent grammes de","一百克……"],["cinq cents grammes","五百克（半斤）"],["un demi-kilo","半公斤"],["en grammes","以克计"]],"sy":[["kilo","courant","公斤（更大单位）"],["livre","courant","斤（500 克）"]],"fq":"中高频，购物与烹饪常用。","me":"gramme：g + ramme，「一克」很轻。","tr":{"zh":"我要两百克奶酪。","fr":"Je voudrais deux cents grammes de fromage.","alt":"Je prendrais deux cents grammes de fromage.","note":"数量 + de + 名词：不加冠词；deux cents 后面还有名词，所以 cents 带 s。"}},
 "Un kebab": {"pos":"n.m. 阳性名词，复数 kebabs","s":"烤肉卷；土耳其烤肉三明治。法国街头快餐很流行：un kebab-frites。肉从旋转烤架切下，夹在饼里。","ipa":"[ke.bab]","ph":"k [k]；e 读 [e]；b [b]；a [a]；结尾 b 要发音。","pi":"结尾 b 要发音 [bab]；k 在这里读 [k]；整词重音在最后一个音节。","et":"来自土耳其语 kebap（烤肉），源于阿拉伯语 / 波斯语。","ex":[["Il achète un kebab.","他买一个烤肉卷。"],["Un kebab sans oignons, s'il vous plaît.","请来一个不加洋葱的烤肉卷。"]],"co":[["un kebab-frites","烤肉卷配薯条"],["un kebab sauce blanche","白酱烤肉卷"],["manger un kebab","吃烤肉卷"],["un resto kebab","烤肉卷小店"]],"sy":[["sandwich","courant","三明治"],["burger","courant","汉堡"],["gyros","courant","希腊烤肉卷"]],"fq":"中频，街头快餐常用。","me":"kebab [ke.bab]：两个 b，结尾的 b 要读出来。","tr":{"zh":"我们去买烤肉卷吧。","fr":"On va acheter un kebab ?","alt":"Si on allait chercher un kebab ?","note":"On va + 动词原形：近将来，口语建议。"}},
 "Un kilo": {"pos":"n.m. 阳性名词，复数 kilos；缩写 kg","s":"公斤；千克（kilogramme 的口语缩写）。买菜时 un kilo de pommes = 一公斤苹果。半公斤是 un demi-kilo 或 500 grammes。","ipa":"[ki.lo]","ph":"k [k]；i 读 [i]；l [l]；o 读 [o]。","pi":"是 kilo [ki.lo]，不是 [kai.lou]；重音在最后；kilo 是 kilogramme 的缩写。","et":"kilo- 来自希腊语 khilioi（一千）；un kilo 是 un kilogramme 的缩略。","ex":[["Un kilo de pommes, s'il vous plaît.","请给我一公斤苹果。"],["J'ai pris deux kilos.","我胖了两公斤。"]],"co":[["un kilo de","一公斤……"],["un demi-kilo","半公斤"],["à dix euros le kilo","十欧元一公斤"],["prendre / perdre des kilos","长胖 / 减肥"]],"sy":[["kilogramme","soutenu","千克（正式全称）"],["gramme","courant","克"],["livre","courant","斤（500 克）"]],"fq":"高频，购物常用。","me":"kilo = 一千克，k 开头就是「一千」的缩写。","tr":{"zh":"两公斤土豆多少钱？","fr":"Combien coûtent deux kilos de pommes de terre ?","alt":"Deux kilos de pommes de terre, ça fait combien ?","note":"Combien coûtent... ? 复数用 coûtent。"}},
 "Un kiwi": {"pos":"n.m. 阳性名词，复数 kiwis","s":"猕猴桃；奇异果。来自新西兰，皮毛绿肉。也指新西兰的国鸟。法语里水果和鸟都叫 kiwi。","ipa":"[ki.wi]","ph":"k [k]；i [i]；w 读 [w]；i [i]。","pi":"w 读 [w]：ki-wi；注意不要把词尾的 i 读成「爱」。","et":"来自毛利语 kiwi（新西兰几维鸟），水果因形似得名。","ex":[["Le kiwi est plein de vitamines.","猕猴桃富含维生素。"],["Je coupe un kiwi en tranches.","我把一个猕猴桃切片。"]],"co":[["un kiwi mûr","熟猕猴桃"],["une salade de kiwis","猕猴桃沙拉"],["un jus de kiwi","猕猴桃汁"],["riche en vitamine C","维生素 C 丰富"]],"sy":[["fruit","courant","水果（泛称）"],["groseille","courant","醋栗（也是小水果）"]],"fq":"中频，水果。","me":"ki-wi：kiwi 重复两个 i，像小鸟叫声。","tr":{"zh":"我每天吃一个猕猴桃。","fr":"Je mange un kiwi tous les jours.","alt":"Tous les jours, je prends un kiwi.","note":"tous les jours = 每天。"}},
 "Un légume": {"pos":"n.m. 阳性名词，复数 légumes","s":"蔬菜。法语用 des légumes 泛指蔬菜；常见：carotte（胡萝卜）、tomate（番茄）。les légumes verts = 绿叶蔬菜。","ipa":"[le.ɡym]","ph":"é 读 [e]；g 读硬音 [ɡ]；u 读 [y]（圆唇「衣」）；结尾 me 的 e 不发音。","pi":"g 在 gu- 前读硬音 [ɡ]；u 读 [y]；结尾 e 不发音；重音在最后一个音节 [gym]。","et":"拉丁语 legumen（豆类蔬菜）。同源英语 legume。","ex":[["La carotte est un légume.","胡萝卜是一种蔬菜。"],["Je mange beaucoup de légumes.","我吃很多蔬菜。"]],"co":[["des légumes verts","绿色蔬菜"],["une soupe de légumes","蔬菜汤"],["légumes de saison","时令蔬菜"],["des légumes frais","新鲜蔬菜"]],"sy":[["verdure","courant","绿叶菜"],["fruit","courant","水果（对比）"],["crudités","courant","生蔬菜"]],"fq":"高频，日常常用。","me":"légume：le-gum，吃很多 légumes 对身体好。","tr":{"zh":"孩子们应该多吃蔬菜。","fr":"Les enfants doivent manger beaucoup de légumes.","alt":"Les enfants, il faut qu'ils mangent plein de légumes.","note":"devoir + 动词原形：应该；beaucoup de + 名词。"}},
 "Un marché": {"pos":"n.m. 阳性名词，复数 marchés","s":"市场；集市。法国每个城镇都有露天 marché，常在周末，卖蔬果、奶酪、花。也指「交易」：bon marché = 便宜。","ipa":"[maʁ.ʃe]","ph":"ar 读 [aʁ]；ch 读 [ʃ]；é 读 [e]。","pi":"ch 读 [ʃ]（像中文「是」），不是「ch」；é 读 [e]；和动词 marcher（走路）同源但不同词。","et":"拉丁语 mercatus（市场、买卖）。同源：marchand（商人）、commerce。","ex":[["Je vais au marché le dimanche matin.","星期天早上我去市场。"],["Le marché est ouvert jusqu'à midi.","市场开到中午。"]],"co":[["aller au marché","去市场"],["un marché aux fleurs","花市"],["bon marché","便宜"],["le marché du travail","就业市场"]],"sy":[["foire","courant","集市、展销会"],["supermarché","courant","超市"],["halle","courant","室内菜市场"]],"fq":"高频，日常常用。","me":"marché：mar-ché，在市场里「马」上「谢」。","tr":{"zh":"星期六我们去市场买蔬菜。","fr":"Le samedi, on va au marché acheter des légumes.","alt":"Le samedi, on fait le marché pour les légumes.","note":"aller + 动词原形：去做……；au = à + le。"}},
 "Un melon": {"pos":"n.m. 阳性名词，复数 melons","s":"甜瓜；香瓜。夏天水果，法国人常把 melon 作前菜或甜点（有时配火腿：melon au jambon）。注意西瓜是 pastèque。","ipa":"[mə.lɔ̃]","ph":"me 轻读 [mə]；l [l]；on 读鼻化 [ɔ̃]，n 不发音。","pi":"第一个 e 读轻音 [ə]；结尾是鼻化音，不发 n；是阳性：un melon。","et":"拉丁语 melo, melonis，来自希腊语 mēlopepōn。","ex":[["Je mange un melon en été.","夏天我吃甜瓜。"],["Un melon bien mûr est très sucré.","熟透的甜瓜很甜。"]],"co":[["un melon mûr","熟甜瓜"],["melon au jambon","火腿甜瓜"],["un melon d'eau","西瓜（魁北克用法）"],["une tranche de melon","一片甜瓜"]],"sy":[["pastèque","courant","西瓜"],["fruit","courant","水果"]],"fq":"中频，夏季水果。","me":"melon：me-lon，像「梅」+「龙」：夏天的甜瓜。","tr":{"zh":"夏天我最喜欢吃甜瓜。","fr":"En été, ce que j'aime le plus, c'est le melon.","alt":"L'été, je préfère manger du melon.","note":"ce que j'aime le plus, c'est... 强调句型。"}},
 "Un oeuf": {"pos":"n.m. 阳性名词，复数 œufs（读 [ø]）","s":"蛋；鸡蛋。拼写 œuf 用连体 œ；oeuf 是分开写的变体。un œuf au plat = 煎蛋；un œuf dur = 煮硬的蛋；un œuf à la coque = 溏心蛋。","ipa":"[œf]","ph":"单数 œu 读 [œ]，f 要发音；复数 œufs 读 [ø]，f 和 s 都不发音。","pi":"单数 [œf] 和复数 [ø] 读音不同：复数 œufs 的 f 不发音；œ 是连写字母；一个蛋 un œuf，两个蛋 deux œufs。","et":"拉丁语 ovum（蛋）。同源：ovale、ovule。","ex":[["Je prépare un oeuf au plat.","我煎一个荷包蛋。"],["Deux œufs durs, s'il vous plaît.","请来两个煮鸡蛋。"]],"co":[["un œuf au plat","煎蛋"],["un œuf dur","煮熟的蛋"],["un œuf à la coque","溏心蛋"],["une omelette aux œufs","蛋饼"]],"sy":[["omelette","courant","蛋饼"],["blanc / jaune d'œuf","courant","蛋白 / 蛋黄"]],"fq":"高频，日常常用。","me":"un œuf [œf]，des œufs [ø]：单数有 f，复数没有。","tr":{"zh":"我早餐吃两个煎蛋。","fr":"Au petit-déjeuner, je mange deux œufs au plat.","alt":"Le matin, je me fais deux œufs au plat.","note":"deux œufs 要连读：[dø.zø]。"}},
 "Un pain au chocolat": {"pos":"n.m. 阳性名词，复数 pains au chocolat","s":"巧克力面包；法国早餐点心：酥皮卷着巧克力条。南方有些地方叫 chocolatine。","ipa":"[pɛ̃.o.ʃɔ.kɔ.la]","ph":"pain [pɛ̃]；au [o]；chocolat：ch [ʃ]，结尾 t 不发音。","pi":"只有 pain 变复数：des pains au chocolat；ch 读 [ʃ]；t 不发音。","et":"pain（面包）+ au（加了）+ chocolat（巧克力，来自阿兹特克纳瓦特尔语）。","ex":[["Je prends un pain au chocolat.","我买一个巧克力面包。"],["Un croissant et un pain au chocolat, s'il vous plaît.","请来一个羊角面包和一个巧克力面包。"]],"co":[["un pain au chocolat chaud","热的巧克力面包"],["des pains au chocolat","几个巧克力面包"],["une chocolatine","巧克力面包（西南叫法）"],["un café et un pain au chocolat","咖啡配巧克力面包"]],"sy":[["chocolatine","courant","（西南法国）同样的面包"],["croissant","courant","羊角面包"],["viennoiserie","courant","维也纳式面点"]],"fq":"高频，早餐常用。","me":"pain + au + chocolat：巧克力面包。","tr":{"zh":"我们买两个巧克力面包吧。","fr":"On achète deux pains au chocolat ?","alt":"On prend deux pains au chocolat ?","note":"复数只在 pain 上加 s。"}},
 "Un paquet de": {"pos":"n.m. 阳性名词，复数 paquets；常与 de 连用表示数量","s":"一包；一盒（量词）：un paquet de pâtes = 一包意面。也指包裹（un paquet-cadeau）。口语中可表示「一大堆」：un paquet de fric。","ipa":"[pa.kɛ]","ph":"p [p]；a [a]；qu 读 [k]；et 读 [ɛ]，t 不发音。","pi":"结尾 -et 读 [ɛ]，t 不发音；paquet de 后不加冠词：un paquet de pâtes，不是 un paquet des pâtes。","et":"源自古法语 pacque，来自荷兰语 pak（包裹）；后加指小后缀 -et。","ex":[["Un paquet de pâtes, s'il vous plaît.","请来一包意面。"],["J'achète un paquet de café.","我买一包咖啡。"]],"co":[["un paquet de pâtes","一包意面"],["un paquet de biscuits","一包饼干"],["un paquet-cadeau","礼物包裹"],["un paquet de cigarettes","一包烟"]],"sy":[["boîte","courant","盒、罐"],["sachet","courant","小袋"],["pot","courant","罐（对比）"]],"fq":"高频，购物常用。","me":"paquet de：一包什么，de 后不要冠词。","tr":{"zh":"我要一包咖啡和一包糖。","fr":"Je voudrais un paquet de café et un paquet de sucre.","alt":"Je prendrais un paquet de café et un paquet de sucre.","note":"paquet de + 名词，不加冠词。"}},
 "Un parapluie": {"pos":"n.m. 阳性名词，复数 parapluies","s":"雨伞。注意是阳性：un parapluie。前缀 para- 表示防，pluie 是「雨」，字面「挡雨的东西」。","ipa":"[pa.ʁa.plɥi]","ph":"pa [pa]；ra [ʁa]（喉音 r）；plui 读 [plɥi]（u 圆唇，快速滑到 i）。","pi":"是阳性名词（un parapluie），虽然 pluie 是阴性；ui 读 [ɥi]，快速滑到 i；结尾 e 不发音。","et":"para-（防护，来自意大利语 parare）+ pluie（雨，拉丁语 pluvia）。同源：parasol（遮阳伞）。","ex":[["Il pleut, je prends mon parapluie.","下雨了，我带伞。"],["Tu as un parapluie ?","你有伞吗？"]],"co":[["ouvrir / fermer un parapluie","打开 / 收起伞"],["prendre un parapluie","带伞"],["un parapluie pliant","折叠伞"],["oublier son parapluie","忘了带伞"]],"sy":[["ombrelle","soutenu","阳伞"],["parasol","courant","遮阳伞（海边）"]],"fq":"高频，天气相关。","me":"para- 防 + pluie 雨 = 防雨：对比 parasol 防太阳。","tr":{"zh":"快下雨了，带上你的伞。","fr":"Il va pleuvoir, prends ton parapluie.","alt":"Il va pleuvoir, n'oublie pas ton parapluie.","note":"il va pleuvoir：近将来；prends 是 prendre 的命令式。"}},
 "Un poireau": {"pos":"n.m. 阳性名词，复数 poireaux（-eau 的复数加 x）","s":"韭葱；西式大葱。法国常用来做汤和馅饼：soupe de poireaux、tarte aux poireaux。和中国韭菜、大葱不同。","ipa":"[pwa.ʁo]","ph":"oi 读 [wa]；r 喉音 [ʁ]；eau 读 [o]。","pi":"复数是 poireaux；eau 读 [o]；别与 poire（梨 [pwaʁ]）混淆。","et":"拉丁语 porrum（韭葱），法语加后缀 -eau。","ex":[["Je fais une soupe avec un poireau.","我用韭葱做汤。"],["Les poireaux sont de saison en hiver.","韭葱冬天是时令菜。"]],"co":[["une soupe de poireaux","韭葱汤"],["une tarte aux poireaux","韭葱馅饼"],["des poireaux vinaigrette","油醋汁韭葱"],["faire le poireau","傻等（口语）"]],"sy":[["oignon","courant","洋葱"],["ciboule","courant","小葱"],["échalote","courant","红葱头"]],"fq":"中频，蔬菜。","me":"poireau ≈ 「哇罗」：吃了韭葱汤，说「哇！」","tr":{"zh":"冬天我喜欢喝韭葱汤。","fr":"En hiver, j'aime manger de la soupe de poireaux.","alt":"L'hiver, j'adore la soupe aux poireaux.","note":"soupe de / aux + 名词，两种说法都对。"}},
 "Un poivron": {"pos":"n.m. 阳性名词，复数 poivrons","s":"甜椒；彩椒（红、绿、黄）。不辣，和 piment（辣椒）不同。un poivron rouge = 红甜椒。","ipa":"[pwa.vʁɔ̃]","ph":"oi 读 [wa]；v 咬下唇 [v]；r 喉音 [ʁ]；on 读鼻化 [ɔ̃]。","pi":"是甜椒，不是辣椒（piment）；结尾 n 不发音；和 poivre 容易混淆。","et":"来自 poivre + 后缀 -on。","ex":[["Je coupe un poivron rouge.","我切一个红甜椒。"],["Une pizza avec des poivrons, s'il vous plaît.","请来一份有甜椒的比萨。"]],"co":[["un poivron rouge / vert / jaune","红 / 绿 / 黄甜椒"],["un poivron farci","酿甜椒"],["une salade de poivrons","甜椒沙拉"],["couper un poivron","切甜椒"]],"sy":[["piment","courant","辣椒（辣的）"],["légume","courant","蔬菜"]],"fq":"中频，蔬菜。","me":"poivron：poivre 的「大个子」，但是甜的，不辣。","tr":{"zh":"我在沙拉里放一个红甜椒。","fr":"Je mets un poivron rouge dans la salade.","alt":"J'ajoute un poivron rouge à la salade.","note":"mettre / ajouter ... dans / à。"}},
 "Un pot de": {"pos":"n.m. 阳性名词，复数 pots；常与 de 连用表示容量","s":"一罐；一杯（量词）：un pot de confiture = 一罐果酱。也指罐子、花盆（un pot de fleurs）。口语 prendre un pot = 喝一杯。","ipa":"[po]","ph":"p [p]；o 读 [o]；结尾 t 不发音。","pi":"结尾 t 不发音；pot de 后不加冠词：un pot de miel；别和 pot 的其他义项混淆。","et":"来源不确定，一般认为是晚期拉丁语 / 前拉丁语词。","ex":[["Un pot de confiture, s'il vous plaît.","请来一罐果酱。"],["Elle achète un pot de miel.","她买一罐蜂蜜。"]],"co":[["un pot de confiture","一罐果酱"],["un pot de yaourt","一杯酸奶"],["un pot de fleurs","花盆"],["prendre un pot","喝一杯（口语）"]],"sy":[["bocal","courant","玻璃罐"],["boîte","courant","盒、罐"],["verre","courant","杯子"]],"fq":"高频，日常常用。","me":"pot [po]：t 不发音，像「破」。","tr":{"zh":"我要一罐蜂蜜。","fr":"Je voudrais un pot de miel.","alt":"Je prends un pot de miel, s'il vous plaît.","note":"un pot de + 名词，不加冠词。"}},
 "Un primeur": {"pos":"n.m. 阳性名词，复数 primeurs；常指商人也指新货","s":"蔬果商；卖蔬菜水果的人或店。其实 primeur 本义是「早上市的菜」（les primeurs）。chez le primeur = 在蔬果店。","ipa":"[pʁi.mœʁ]","ph":"p+r [pʁ]；i [i]；m [m]；eur 读 [œʁ]。","pi":"eur 读 [œʁ]；与 prime（奖金）不同；注意这是人（蔬果商）或店，不是「蔬菜」本身。","et":"来自 prime（拉丁语 primus「第一」），原指「最早上市的菜」。","ex":[["J'achète mes légumes chez le primeur.","我在蔬果店买蔬菜。"],["Le primeur a de beaux abricots.","蔬果商有很漂亮的杏子。"]],"co":[["chez le primeur","在蔬果店"],["les primeurs","早熟蔬果"],["un primeur du coin","街角的蔬果商"],["un marchand de primeurs","蔬果商"]],"sy":[["marchand de fruits et légumes","courant","水果蔬菜商人"],["maraîcher","courant","菜农"],["fruitier","soutenu","水果商"]],"fq":"中低频，购物用词。","me":"primeur ← prime（第一）：最早的新鲜菜。","tr":{"zh":"我在蔬果店买苹果和胡萝卜。","fr":"J'achète des pommes et des carottes chez le primeur.","alt":"Je prends mes pommes et mes carottes chez le primeur.","note":"chez + 人 / 商人：在……那里。"}},
 "Un steak-frite": {"pos":"n.m. 阳性名词，复数 steaks-frites","s":"牛排配薯条：法国小馆的经典菜。常说 steak-frites。steak 是牛排，frites 是薯条。","ipa":"[stɛk.fʁit]","ph":"steak 读 [stɛk]（ea 读 [ɛ]，k 发音）；frite：fr [fʁ]，i，结尾 e 不发音。","pi":"steak 的 k 要发音，ea 读 [ɛ]（不是英语的 [eɪ]）；frite 的 t 要发音，e 不发音。","et":"steak 来自英语（古北欧语 steik），frite 是 frire（油炸）的过去分词。","ex":[["Je prends un steak-frite.","我点牛排配薯条。"],["Un steak-frites, bien cuit, s'il vous plaît.","请来一份全熟牛排配薯条。"]],"co":[["un steak-frites","牛排配薯条"],["un steak saignant / à point / bien cuit","三分熟 / 五分熟 / 全熟牛排"],["des frites maison","自制薯条"],["un steak haché","牛肉饼"]],"sy":[["bifteck","familier","牛排（口语）"],["entrecôte","courant","肋眼牛排"],["viande","courant","肉（泛称）"]],"fq":"中频，餐厅常用。","me":"steak + frites：法国小馆的「国民菜」。","tr":{"zh":"今天我想吃牛排配薯条。","fr":"Aujourd'hui, j'ai envie d'un steak-frites.","alt":"Aujourd'hui, je prendrais bien un steak-frites.","note":"je prendrais bien：礼貌地说想点什么。"}},
 "Un supermarché": {"pos":"n.m. 阳性名词，复数 supermarchés","s":"超市。faire les courses au supermarché = 去超市买东西。比 hypermarché（大卖场）小，比 supérette（小超市）大。","ipa":"[sy.pɛʁ.maʁ.ʃe]","ph":"su 读 [sy]（u 圆唇）；per 读 [pɛʁ]；mar 读 [maʁ]；ché 读 [ʃe]。","pi":"u 读 [y]，不是「乌」；r 喉音；ch 读 [ʃ]；é 读 [e]。","et":"super-（超）+ marché（市场），来自英语 supermarket 的仿造。","ex":[["Je fais les courses au supermarché.","我在超市买东西。"],["Le supermarché ferme à vingt heures.","超市晚上八点关门。"]],"co":[["faire les courses au supermarché","去超市购物"],["un supermarché bio","有机超市"],["le rayon fruits et légumes","水果蔬菜区"],["la caisse du supermarché","超市收银台"]],"sy":[["hypermarché","courant","大卖场"],["supérette","courant","小超市"],["magasin","courant","商店"]],"fq":"极高频，日常常用。","me":"super + marché = 超级市场。","tr":{"zh":"我们周六去超市买东西。","fr":"Le samedi, on fait les courses au supermarché.","alt":"Samedi, on va au supermarché pour les courses.","note":"faire les courses = 买日用品和食物。"}},
 "Un tire-bouchon": {"pos":"n.m. 阳性名词，复数 tire-bouchons","s":"开瓶器；红酒起子。字面是「拉软木塞的东西」。ouvrir une bouteille avec un tire-bouchon。","ipa":"[tiʁ.bu.ʃɔ̃]","ph":"tire 读 [tiʁ]（r 喉音）；bou 读 [bu]；chon 读 [ʃɔ̃]。","pi":"tire-bouchon 中间有连字符；ch 读 [ʃ]；结尾 on 鼻化，n 不发音；复数只在后面加 s。","et":"tirer（拉）+ bouchon（塞子），字面「拉塞子」。","ex":[["Tu as un tire-bouchon pour le vin ?","你有开红酒的开瓶器吗？"],["Je ne trouve pas le tire-bouchon.","我找不到开瓶器。"]],"co":[["ouvrir avec un tire-bouchon","用开瓶器打开"],["un tire-bouchon à levier","杠杆式开瓶器"],["un tire-bouchon électrique","电动开瓶器"],["sortir le bouchon","取出塞子"]],"sy":[["décapsuleur","courant","开瓶盖器（啤酒）"],["ouvre-bouteille","courant","开瓶器（泛称）"]],"fq":"低中频，饮食用具。","me":"tire + bouchon：拉 + 塞子。","tr":{"zh":"你能给我拿开瓶器吗？","fr":"Tu peux me passer le tire-bouchon ?","alt":"Tu peux m'apporter le tire-bouchon ?","note":"Tu peux me passer... ? 礼貌请求。"}},
 "Un verre": {"pos":"n.m. 阳性名词，复数 verres","s":"杯子；玻璃杯；一杯（量词）：un verre d'eau。也指「玻璃」材料：du verre。prendre un verre = 喝一杯。眼镜片是 verres。","ipa":"[vɛʁ]","ph":"v 咬下唇 [v]；e 读 [ɛ]；rr 只读一个 [ʁ]；结尾 e 不发音。","pi":"rr 只读一个 r；结尾 e 不发音；与 ver（虫）、vert（绿）、vers（朝）同音。","et":"拉丁语 vitrum（玻璃）。同源：vitre（窗玻璃）。","ex":[["Un verre d'eau, s'il vous plaît.","请来一杯水。"],["On prend un verre ensemble ?","我们一起喝一杯吗？"]],"co":[["un verre d'eau / de vin","一杯水 / 一杯酒"],["un verre en plastique","塑料杯"],["prendre un verre","喝一杯（社交）"],["des verres de lunettes","眼镜片"]],"sy":[["tasse","courant","茶杯、咖啡杯"],["gobelet","courant","一次性杯、小杯"],["coupe","soutenu","高脚杯（香槟）"]],"fq":"极高频，日常常用。","me":"verre / ver / vers / vert 同音 [vɛʁ]：靠上下文分辨。","tr":{"zh":"你想喝一杯水吗？","fr":"Tu veux un verre d'eau ?","alt":"Tu veux boire un verre d'eau ?","note":"un verre de + 名词，不加冠词。"}},
 "De l'eau": {"pos":"n.f. 阴性名词，不可数，复数 eaux","s":"水。de l'eau = 一些水（部分冠词省音）。eau minérale（矿泉水）、eau du robinet（自来水）、eau gazeuse（气泡水）。注意是阴性：l'eau。","ipa":"[o]","ph":"eau 三个字母合起来读一个音 [o]；de l'eau 读 [də.lo]。","pi":"eau 只读 [o]，不是三个音；是阴性（la eau → l'eau 省音）；与 haut（高）、os（骨）同音。","et":"拉丁语 aqua（水）。同源：aquarium（水族馆）、aquatique（水生的）。","ex":[["Je bois de l'eau tous les jours.","我每天喝水。"],["Une bouteille d'eau, s'il vous plaît.","请来一瓶水。"]],"co":[["de l'eau minérale","矿泉水"],["de l'eau du robinet","自来水"],["de l'eau gazeuse / plate","气泡水 / 无气水"],["de l'eau chaude / froide","热水 / 冷水"]],"sy":[["flotte","familier","水（口语）"],["eau minérale","courant","矿泉水"],["boisson","courant","饮料"]],"fq":"极高频，日常常用。","me":"eau = o：三个字母，一个音。","tr":{"zh":"请给我一杯冰水。","fr":"Un verre d'eau fraîche, s'il vous plaît.","alt":"Je voudrais de l'eau fraîche, s'il vous plaît.","note":"eau 阴性，所以用 fraîche；de l'eau。"}},
 "De l'huile": {"pos":"n.f. 阴性名词，不可数，复数 huiles","s":"油；食用油。huile d'olive = 橄榄油；huile de tournesol = 葵花籽油。de l'huile = 一些油（部分冠词省音）。也指石油：huile de moteur 机油。","ipa":"[ɥil]","ph":"h 不发音；u 读 [ɥ]（圆唇滑音）；i 读 [i]；l 读 [l]；结尾 e 不发音。","pi":"h 是哑音 h，所以 la huile 要省音成 l'huile；ui 读 [ɥi]，快速滑动；e 不发音。","et":"拉丁语 oleum（油，橄榄油）。同源：oléagineux（含油的）。","ex":[["J'ajoute un peu d'huile d'olive.","我加一点橄榄油。"],["Il faut de l'huile pour faire frire.","炸东西需要油。"]],"co":[["de l'huile d'olive","橄榄油"],["de l'huile de tournesol","葵花籽油"],["une huile végétale","植物油"],["une goutte d'huile","一滴油"]],"sy":[["graisse","courant","油脂"],["beurre","courant","黄油（对比）"]],"fq":"高频，烹饪常用。","me":"huile [ɥil]：h 哑音，像「威尔」。","tr":{"zh":"我在平底锅里放一点油。","fr":"Je mets un peu d'huile dans la poêle.","alt":"Je verse un peu d'huile dans la poêle.","note":"un peu d'huile：d' 因元音省音。"}},
 "De la bière": {"pos":"n.f. 阴性名词，复数 bières","s":"啤酒。de la bière = 一些啤酒；une bière = 一杯 / 一瓶啤酒。bière blonde（淡啤）、brune（黑啤）、blanche（白啤）。une pression = 生啤。","ipa":"[bjɛʁ]","ph":"b + ière：ière 读 [jɛʁ]（i 变 j）；结尾 e 不发音。","pi":"i-è 连起来读 [jɛʁ]；è 的重音符号不能漏；是阴性。","et":"来自荷兰语 / 德语 bier，借入法语较晚。","ex":[["Il boit une bière fraîche.","他喝一杯冰啤酒。"],["Une bière, s'il vous plaît.","请来一杯啤酒。"]],"co":[["une bière blonde / brune","淡啤 / 黑啤"],["une bière pression","生啤"],["une bière sans alcool","无酒精啤酒"],["un demi","一小杯（25 cl）啤酒"]],"sy":[["demi","courant","一小杯生啤"],["mousse","familier","啤酒（口语）"],["boisson","courant","饮料"]],"fq":"高频，日常常用。","me":"bière ≈「比耶」：干杯，bière 比耶。","tr":{"zh":"我们喝杯啤酒吧。","fr":"On prend une bière ?","alt":"On va boire une bière ?","note":"On prend... ? 邀请用语。"}},
 "De la confiture": {"pos":"n.f. 阴性名词，复数 confitures","s":"果酱。de la confiture = 一些果酱；un pot de confiture。法国早餐把果酱抹在面包片 tartine 上。confiture de fraises = 草莓酱。","ipa":"[kɔ̃.fi.tyʁ]","ph":"con 读鼻化 [kɔ̃]；fi [fi]；tu 读 [ty]；r 读 [ʁ]；结尾 e 不发音。","pi":"con 是鼻化 [kɔ̃]，不读 n；u 读 [y]；不要和英语 confidence 混淆。","et":"来自 confire（腌制、浸泡，拉丁语 conficere）+ 后缀 -ure。","ex":[["Je mets de la confiture sur mon pain.","我在面包上抹果酱。"],["Ma grand-mère fait de la confiture de fraises.","我奶奶做草莓酱。"]],"co":[["de la confiture de fraises","草莓酱"],["une tartine de confiture","果酱面包片"],["un pot de confiture","一罐果酱"],["de la confiture maison","自制果酱"]],"sy":[["marmelade","courant","柑橘酱"],["gelée","courant","果冻、果胶酱"],["compote","courant","果泥"]],"fq":"高频，早餐常用。","me":"confiture：con + fit + ure：果酱，把水果「confit」起来。","tr":{"zh":"我早上喜欢吃果酱面包。","fr":"Le matin, j'aime les tartines de confiture.","alt":"Au petit-déjeuner, je prends du pain avec de la confiture.","note":"tartine = 抹了酱的面包片。"}},
 "De la farine": {"pos":"n.f. 阴性名词，不可数，复数 farines","s":"面粉。de la farine = 一些面粉；farine de blé（小麦粉）；farine de maïs（玉米粉）。做面包、蛋糕都要用。","ipa":"[fa.ʁin]","ph":"fa [fa]；ri 读 [ʁi]（喉音 r）；ne 读 [n]，结尾 e 不发音；in 在这里读 [in]，因为后面有 e。","pi":"ine 读 [in]，不是鼻化 [ɛ̃]（有 e 时 n 要发音）；对比 vin [vɛ̃]；r 喉音。","et":"拉丁语 farina（粉）。同源：farineux（含淀粉的）。","ex":[["Il faut de la farine pour le pain.","做面包需要面粉。"],["Ajoute de la farine petit à petit.","一点一点加面粉。"]],"co":[["de la farine de blé","小麦面粉"],["de la farine complète","全麦面粉"],["un sac de farine","一袋面粉"],["tamiser la farine","筛面粉"]],"sy":[["fécule","courant","淀粉"],["semoule","courant","粗粒面粉"]],"fq":"中高频，烹饪常用。","me":"farine ≈「发了你」：面粉发酵变面包。","tr":{"zh":"做蛋糕需要面粉、糖和鸡蛋。","fr":"Pour faire un gâteau, il faut de la farine, du sucre et des œufs.","alt":"Pour un gâteau, il vous faut de la farine, du sucre et des œufs.","note":"il faut + 名词 / 动词原形：需要。"}},
 "De la glace": {"pos":"n.f. 阴性名词，复数 glaces","s":"冰；冰淇淋。不可数的「冰」说 de la glace；一个/一份冰淇淋常说 une glace。另有「镜子；车窗玻璃」义：une glace。","ipa":"[glas]","ph":"g [g]，l [l]，a [a]；结尾 -ce 读 [s]，e 不发音。","pi":"结尾 -ce 读 [s]；de la 是部分冠词，表示「一些」，不是「的」。","et":"拉丁语 glacies（冰）。同族：glacier（冰川）、glaçon（冰块）、glacé（冰镇的）。","ex":[["Je voudrais de la glace à la vanille.","我想要香草冰淇淋。"],["Tu veux une glace ?","你想吃个冰淇淋吗？"],["Il y a de la glace sur le lac.","湖面上结了冰。"]],"co":[["une glace au chocolat","巧克力冰淇淋"],["une boule de glace","一球冰淇淋"],["de la glace pilée","碎冰"]],"sy":[["crème glacée","courant","冰淇淋的完整说法"],["glaçon","courant","饮料里的冰块"]],"fq":"高频，日常常用。","me":"glace 和 glacier（冰川）同根：都是冰。","tr":{"zh":"夏天我喜欢吃草莓冰淇淋。","fr":"En été, j'aime manger une glace à la fraise.","alt":"L'été, j'adore les glaces à la fraise.","note":"一份冰淇淋用 une glace；作为物质的冰用 de la glace。"}},
 "De la mayonnaise": {"pos":"n.f. 阴性名词，通常不加复数","s":"蛋黄酱，美乃滋。法国人常配薯条（frites）、水煮蛋、冷盘。不可数，所以用部分冠词 de la。","ipa":"[ma.jɔ.nɛz]","ph":"y 在这里读 [j]；-aise 读 [ɛz]，结尾 e 不发音。","pi":"ai 读 [ɛ]，不是 [aj]；s 在元音间读 [z]。口语常缩成 mayo [ma.jo]。","et":"来源不确定（有几种说法，没有定论）。","ex":[["Des frites avec de la mayonnaise.","薯条配蛋黄酱。"],["Tu veux de la mayonnaise ?","你要蛋黄酱吗？"],["Il met trop de mayonnaise.","他放太多蛋黄酱了。"]],"co":[["des œufs mayonnaise","蛋黄酱水煮蛋（经典前菜）"],["un pot de mayonnaise","一罐蛋黄酱"],["frites mayonnaise","蘸蛋黄酱的薯条"]],"sy":[["mayo","familier","口语缩写"],["sauce","courant","酱汁（泛称）"]],"fq":"中频，餐桌上常见。","me":"mayo-nnaise：mayo 的 yo 读 [jo]，像「摇」。","tr":{"zh":"我想要薯条和蛋黄酱。","fr":"Je voudrais des frites avec de la mayonnaise.","alt":"Des frites avec de la mayo, s'il vous plaît.","note":"酱料是不可数的，用 de la。"}},
 "De la moutarde": {"pos":"n.f. 阴性名词，复数 moutardes（很少用）","s":"芥末酱（法式黄芥末，味道冲）。特指 Dijon 一带的 moutarde de Dijon。不可数，用 de la。","ipa":"[mu.taʁd]","ph":"ou [u]；r 是喉音 [ʁ]；d 要读出来 [d]，结尾 e 不发音。","pi":"d 不是静音；ou 读 [u]，不是 [ɔ] 。注意不是日式绿芥末（wasabi）。","et":"传统认为来自 moût（葡萄汁）+ ardent（辣的）。同族：moût。","ex":[["Je mets de la moutarde.","我加芥末酱。"],["La moutarde de Dijon est très forte.","第戎芥末酱很冲。"],["Tu veux de la moutarde avec ta saucisse ?","你香肠要配芥末酱吗？"]],"co":[["la moutarde de Dijon","第戎芥末酱"],["moutarde à l'ancienne","颗粒芥末酱"],["un pot de moutarde","一罐芥末酱"],["la moutarde lui monte au nez","他火气上来了（习语）"]],"sy":[["sauce","courant","酱汁（泛称）"]],"fq":"中频。","me":"mou + tarde：想象「软软的、慢慢辣上来」。","tr":{"zh":"我的三明治里要加芥末酱。","fr":"Je mets de la moutarde dans mon sandwich.","alt":"Moi, je mets de la moutarde dans mon sandwich.","note":"酱料用 de la；mettre dans = 放进。"}},
 "De la soupe": {"pos":"n.f. 阴性名词，复数 soupes","s":"汤（较浓、较稠的家常汤）。法国人晚饭常喝 de la soupe。口语里 un soupe 不存在，永远是阴性。","ipa":"[sup]","ph":"ou [u]；p 在词尾读 [p]，e 不发音。","pi":"soupe 的 p 要读出来；不要和 supe 混淆。","et":"来自日耳曼语 *suppa（浸了汤汁的面包片）。同族：英语 soup, supper。","ex":[["Je mange de la soupe en hiver.","我冬天喝汤。"],["La soupe est chaude.","汤是热的。"],["Une soupe de légumes, s'il vous plaît.","请来一份蔬菜汤。"]],"co":[["une soupe de légumes","蔬菜汤"],["une soupe à l'oignon","洋葱汤"],["une cuillère à soupe","汤匙"],["manger de la soupe","喝汤（用 manger）"]],"sy":[["potage","soutenu","汤（比 soupe 稍文雅）"],["bouillon","courant","清汤"]],"fq":"高频，日常常用。","me":"soupe 读起来像「苏扑」，和英语 soup 一样。","tr":{"zh":"晚上我们喝蔬菜汤。","fr":"Ce soir, on mange de la soupe de légumes.","alt":"On prend une bonne soupe de légumes ce soir.","note":"喝汤用 manger（不是 boire），因为用勺子。"}},
 "De la viande": {"pos":"n.f. 阴性名词，复数 viandes","s":"肉（指猪牛羊等「红肉」，也泛指肉类）。鱼、禽有时单独说：poisson, volaille。","ipa":"[vjɑ̃d]","ph":"v [v]；ia 连读成 [jɑ̃]；d 读 [d]，结尾 e 不发音。","pi":"-an- 读鼻音 [ɑ̃]，d 要读出来。","et":"拉丁语 vivenda（生活所需之物）。","ex":[["Je ne mange pas de viande.","我不吃肉。"],["Tu préfères la viande ou le poisson ?","你更喜欢肉还是鱼？"],["Cette viande est très tendre.","这块肉很嫩。"]],"co":[["la viande rouge / blanche","红肉 / 白肉"],["de la viande hachée","肉末"],["ne pas manger de viande","不吃肉"],["une viande saignante","带血丝的肉"]],"sy":[["chair","littéraire","血肉（一般指人）"],["bidoche","argot","肉（俚语）"]],"fq":"高频。","me":"viande ← vivenda：肉是「维持生活」的食物。","tr":{"zh":"我不吃肉，我吃鱼。","fr":"Je ne mange pas de viande, je mange du poisson.","alt":"Pas de viande pour moi, du poisson.","note":"否定后 de la 变成 de：pas de viande。"}},
 "L'addition": {"pos":"n.f. 阴性名词，复数 additions","s":"账单（餐厅里的）；也指数学里的加法。餐馆要买单就说 L'addition, s'il vous plaît。","ipa":"[a.di.sjɔ̃]","ph":"a [a]，d [d]；-tion 读 [sjɔ̃]；l'a- 省音，读起来是一个词。","pi":"-tion 读 [sjɔ̃]，不是 [tion]；注意 d 只有一个。在餐厅不说 la facture。","et":"拉丁语 additio（加）。同族：ajouter（加）、英语 addition。","ex":[["L'addition, s'il vous plaît.","请买单。"],["On partage l'addition ?","我们分摊账单吧？"],["L'addition est de vingt euros.","账单是二十欧元。"]],"co":[["demander l'addition","要账单"],["payer l'addition","付账"],["partager l'addition","分摊账单"],["l'addition, s'il vous plaît","请买单"]],"sy":[["note","courant","账单（酒店、咖啡馆也用）"],["facture","courant","发票、账单（水电费等）"]],"fq":"高频，餐厅必用。","me":"addition = add + ition：把每道菜「加」起来。","tr":{"zh":"请买单，谢谢。","fr":"L'addition, s'il vous plaît.","alt":"Je peux avoir l'addition, s'il vous plaît ?","note":"餐厅用 addition，不用 facture。"}},
 "L'entrée": {"pos":"n.f. 阴性名词，复数 entrées","s":"前菜（正餐的第一道）；也指「入口；进入」。点餐时 entrée-plat-dessert 是常见三段式。","ipa":"[ɑ̃.tʁe]","ph":"en [ɑ̃]；tr 连读 [tʁ]；-ée 读 [e]，e 不发音。","pi":"结尾是 -ée（阴性），读 [e]。与英语不同：法语 entrée 是前菜，不是主菜。","et":"来自动词 entrer（进入）的过去分词，作名词。","ex":[["Je prends une salade en entrée.","前菜我点沙拉。"],["L'entrée du musée est gratuite.","博物馆入口免费。"],["Qu'est-ce que vous prenez en entrée ?","前菜您点什么？"]],"co":[["en entrée","作为前菜"],["l'entrée, le plat, le dessert","前菜、主菜、甜点"],["l'entrée du cinéma","电影院入口"],["entrée libre","免费入场"]],"sy":[["hors-d'œuvre","soutenu","前菜（较正式）"],["sortie","courant","反义：出口"],["plat","courant","主菜"]],"fq":"高频。","me":"entrée = 先「进入」正餐的第一道。","tr":{"zh":"前菜我要一份沙拉。","fr":"En entrée, je prends une salade.","alt":"Pour commencer, une salade, s'il vous plaît.","note":"en entrée = 作为前菜。"}},
 "La radio": {"pos":"n.f. 阴性名词，复数 radios","s":"收音机；广播（节目）。也可指 X 光片（une radio，radiographie 的缩写）。听广播说 écouter la radio。","ipa":"[ʁa.djo]","ph":"r 是喉音 [ʁ]；di 读 [dj]；o [o]。","pi":"阴性：la radio（不是 le radio）。o 读闭口 [o]，结尾不要拖长。","et":"来自 radio-（辐射）。radio 原指无线电波，同族：radiographie。","ex":[["J'écoute la radio dans la voiture.","我在车里听广播。"],["Il y a une radio dans la cuisine.","厨房里有一台收音机。"],["Le médecin fait une radio du pied.","医生给脚拍 X 光。"]],"co":[["écouter la radio","听广播"],["à la radio","在广播里"],["une station de radio","广播电台"],["passer à la radio","在广播里播出"]],"sy":[["poste","familier","收音机（老说法）"],["radiographie","soutenu","X 光检查"]],"fq":"高频。","me":"radio 在法语里是阴性：la radio。","tr":{"zh":"早上我在厨房听广播。","fr":"Le matin, j'écoute la radio dans la cuisine.","alt":"Le matin, je mets la radio dans la cuisine.","note":"写在广播里 = à la radio；听 = écouter。"}},
 "Une assiette": {"pos":"n.f. 阴性名词，复数 assiettes","s":"盘子；一盘（菜）。une assiette de + 名词 = 一盘……。不要和 plat（大盘、菜式）混：assiette 是每人面前的盘子。","ipa":"[a.sjɛt]","ph":"ss 读 [s]（两个 s 保持清音）；ie 在这里读 [jɛ]；结尾 -ette 读 [ɛt]，e 不发音。","pi":"ss 是 [s]，不是 [z]；t 要读出来。","et":"与 asseoir（坐）同族，原义「摆放的位置」。","ex":[["Je pose l'assiette sur la table.","我把盘子放在桌上。"],["Une assiette de fromages, s'il vous plaît.","请来一盘奶酪。"],["Ne laisse pas de nourriture dans ton assiette.","别在盘子里剩饭。"]],"co":[["une assiette creuse / plate","汤盘 / 平盘"],["une assiette de charcuterie","一盘冷切肉"],["laver les assiettes","洗盘子"],["ne pas être dans son assiette","身体不舒服、状态不好（习语）"]],"sy":[["plat","courant","大盘；一道菜"],["couvert","courant","餐具套（刀叉盘）"]],"fq":"高频，日常常用。","me":"asseoir 的「安放」：盘子是放食物的座位。","tr":{"zh":"请给我一个盘子。","fr":"Je voudrais une assiette, s'il vous plaît.","alt":"Vous pouvez m'apporter une assiette ?","note":"vouloir 的条件式 voudrais 更礼貌。"}},
 "Une aubergine": {"pos":"n.f. 阴性名词，复数 aubergines","s":"茄子。也是颜色名（紫黑色，作形容词时不变）：un pull aubergine。法国菜常见：ratatouille, moussaka。","ipa":"[o.bɛʁ.ʒin]","ph":"au [o]；er 读 [ɛʁ]；g 在 i 前读 [ʒ]；结尾 -ine 读 [in]，e 不发音。","pi":"au 读 [o]；g 在 i 前读 [ʒ]，不是 [g]。","et":"经加泰罗尼亚语 albergínia，源自阿拉伯语 al-bādhinjān（茄子）。","ex":[["Je cuisine une ratatouille avec une aubergine.","我用茄子做蔬菜杂烩。"],["Elle aime les aubergines grillées.","她喜欢烤茄子。"],["Un pull aubergine, c'est joli.","一件深紫色毛衣很好看。"]],"co":[["des aubergines grillées","烤茄子"],["une aubergine farcie","酿茄子"],["un caviar d'aubergine","茄泥"],["couleur aubergine","茄紫色"]],"sy":[["courgette","courant","西葫芦（常和茄子一起煮）"],["poivron","courant","彩椒"]],"fq":"中频，菜市场、菜谱常见。","me":"au-ber-gine：au 读 [o]，像「欧」。","tr":{"zh":"我今天买了一个茄子。","fr":"Aujourd'hui, j'ai acheté une aubergine.","alt":"J'ai pris une aubergine au marché aujourd'hui.","note":"复合过去时：j'ai acheté。"}},
 "Une banane": {"pos":"n.f. 阴性名词，复数 bananes","s":"香蕉。也有口语义：avoir la banane = 笑容满面、心情很好。les bananes 复数在俚语里也指腰包（sac banane）。","ipa":"[ba.nan]","ph":"两个 a 都读 [a]；n 读 [n]；结尾 -ane 读 [an]，e 不发音。","pi":"结尾 -ane 读 [an]，不鼻音；重音在最后一个音节。","et":"来自非洲语言，经葡萄牙语进入法语。","ex":[["Les singes aiment les bananes.","猴子喜欢香蕉。"],["Je mange une banane au petit-déjeuner.","我早餐吃一根香蕉。"],["Il a la banane aujourd'hui !","他今天心情特别好！"]],"co":[["une banane mûre","熟香蕉"],["un régime de bananes","一串香蕉"],["un milk-shake à la banane","香蕉奶昔"],["avoir la banane","笑容满面（口语）"]],"sy":[["fruit","courant","水果（泛称）"],["pomme","courant","苹果（对比）"]],"fq":"高频。","me":"ba-nane：重复的 [ba][na]，像在说「巴娜娜」。","tr":{"zh":"早餐我吃一根香蕉。","fr":"Au petit-déjeuner, je mange une banane.","alt":"Le matin, je prends une banane.","note":"une banane 指一根；一串用 un régime。"}},
 "Une boisson": {"pos":"n.f. 阴性名词，复数 boissons","s":"饮料；饮品。可以是冷饮或热饮，酒类也是 boisson alcoolisée。点餐时 une boisson chaude = 热饮。","ipa":"[bwa.sɔ̃]","ph":"oi [wa]；ss 读 [s]；-on 读鼻音 [ɔ̃]，n 不发音。","pi":"ss 读 [s]（不是 [z]）；对比 poison（毒药）[pwa.zɔ̃]。","et":"来自动词 boire（喝），拉丁语 bibere。","ex":[["Vous voulez une boisson ?","您想要饮料吗？"],["Une boisson chaude, s'il vous plaît.","请来一杯热饮。"],["Les boissons sont comprises dans le menu.","饮料包含在套餐里。"]],"co":[["une boisson chaude / froide","热饮 / 冷饮"],["une boisson gazeuse","汽水、气泡饮料"],["une boisson alcoolisée","含酒精饮料"],["boissons non comprises","饮料另计"]],"sy":[["consommation","soutenu","咖啡馆里点的饮品"],["verre","courant","一杯酒（口语）"]],"fq":"高频，餐厅必用。","me":"boire → boisson：喝 + 名词后缀 -son。","tr":{"zh":"您想喝什么饮料？","fr":"Vous voulez quelle boisson ?","alt":"Qu'est-ce que vous prenez comme boisson ?","note":"quelle 与阴性名词配合。"}},
 "Une boucherie": {"pos":"n.f. 阴性名词，复数 boucheries","s":"肉店。店主叫 un boucher / une bouchère。主要卖牛肉、猪肉、羊肉；鸡、鸭有时在 charcuterie 买。","ipa":"[bu.ʃʁi]","ph":"ou [u]；ch [ʃ]；r 喉音 [ʁ]；结尾 -ie 读 [i]。","pi":"ch 读 [ʃ]（不是 [tʃ]）；中间的 e 在口语里常不读，所以是 bou-che-rie 读作 [bu.ʃʁi]。","et":"boucher（肉贩）+ -erie；boucher 来自 bouc（公山羊）。","ex":[["Je vais à la boucherie pour la viande.","我去肉店买肉。"],["La boucherie est fermée le lundi.","肉店星期一不开门。"],["Elle travaille dans une boucherie.","她在一家肉店工作。"]],"co":[["aller à la boucherie","去肉店"],["une boucherie halal","清真肉店"],["acheter du bœuf à la boucherie","在肉店买牛肉"],["le boucher","肉贩"]],"sy":[["charcuterie","courant","熟肉、火腿、香肠店"],["boucherie-charcuterie","courant","肉店兼熟食店"]],"fq":"中频。","me":"boucher + -erie：卖肉的人的店。","tr":{"zh":"我去肉店买牛肉。","fr":"Je vais à la boucherie acheter du bœuf.","alt":"Je passe à la boucherie pour acheter du bœuf.","note":"à la + 店名：去某店。"}},
 "Une boulangerie": {"pos":"n.f. 阴性名词，复数 boulangeries","s":"面包店（卖面包，常也卖酥皮点心）。法国街头的象征。店主叫 un boulanger / une boulangère。","ipa":"[bu.lɑ̃ʒ.ʁi]","ph":"ou [u]；an [ɑ̃]；g 在 e 前读 [ʒ]；整体读 bou-lan-ge-rie，中间 e 常不读。","pi":"拼写 -ge- 的 g 读 [ʒ]，e 不单独读；an 是鼻音，不读 n。","et":"boulanger（面包师）+ -erie。boulanger 的更早来源不确定。","ex":[["J'achète mon pain à la boulangerie.","我在面包店买面包。"],["La boulangerie ouvre à sept heures.","面包店七点开门。"],["Il y a une boulangerie près d'ici ?","这附近有面包店吗？"]],"co":[["aller à la boulangerie","去面包店"],["une boulangerie-pâtisserie","面包糕点店"],["acheter du pain à la boulangerie","在面包店买面包"],["le boulanger","面包师"]],"sy":[["pâtisserie","courant","糕点店"],["boulange","familier","面包店（口语）"]],"fq":"极高频，日常必用。","me":"boulanger 是「面包人」，boulangerie 是他的店。","tr":{"zh":"面包店在银行旁边。","fr":"La boulangerie est à côté de la banque.","alt":"La boulangerie, c'est juste à côté de la banque.","note":"à côté de + 名词 = 在……旁边。"}},
 "Une bouteille (de)": {"pos":"n.f. 阴性名词，复数 bouteilles；表示量词，后接 de + 名词","s":"瓶；一瓶。une bouteille de + 名词（无冠词）= 一瓶……。也指瓶装之物：une bouteille de vin。","ipa":"[bu.tɛj]","ph":"ou [u]；t [t]；-eille 读 [ɛj]，ll 读 [j]，结尾 e 不发音。","pi":"-eille 读 [ɛj]，不是 [ij] 也不是 [el]。de 后不加冠词：une bouteille d'eau，不是 de l'eau。","et":"拉丁语 butticula（小桶）。英语 bottle 同源。","ex":[["Je voudrais une bouteille d'eau.","我想要一瓶水。"],["Une bouteille de vin rouge, s'il vous plaît.","请来一瓶红酒。"],["Il y a une bouteille dans le frigo.","冰箱里有一瓶饮料。"]],"co":[["une bouteille d'eau / de vin","一瓶水 / 一瓶酒"],["une bouteille en plastique","塑料瓶"],["ouvrir une bouteille","开一瓶"],["une demi-bouteille","半瓶"]],"sy":[["flacon","soutenu","小瓶（香水、药）"],["carafe","courant","水壶"],["canette","courant","易拉罐"]],"fq":"高频。","me":"bouteille 像英语 bottle：b-t 开头结尾相近。","tr":{"zh":"我想要一瓶水。","fr":"Je voudrais une bouteille d'eau.","alt":"Une bouteille d'eau, s'il vous plaît.","note":"une bouteille de + 名词，不加冠词。"}},
 "Une caisse": {"pos":"n.f. 阴性名词，复数 caisses","s":"收银台；收款处；也指箱子（une caisse de vin 一箱酒）。超市里结账说 payer à la caisse。","ipa":"[kɛs]","ph":"c [k]；ai [ɛ]；ss [s]；结尾 e 不发音。","pi":"ss 读 [s]；ai 读 [ɛ]，不是 [e]。","et":"拉丁语 capsa（盒子）。英语 case, cash 同族。","ex":[["Je paie à la caisse.","我在收银台付款。"],["La caisse est là-bas.","收银台在那边。"],["Il porte une caisse de légumes.","他搬着一箱蔬菜。"]],"co":[["payer à la caisse","在收银台付款"],["une caisse automatique","自助结账机"],["une caisse de vin","一箱酒"],["la caisse d'épargne","储蓄银行"]],"sy":[["comptoir","courant","柜台"],["boîte","courant","盒子"],["carton","courant","纸箱"]],"fq":"高频，购物常用。","me":"caisse ≈ cash：在收银台付现金。","tr":{"zh":"请到收银台付款。","fr":"Veuillez payer à la caisse.","alt":"Vous pouvez payer à la caisse, s'il vous plaît.","note":"Veuillez + 动词原形 = 请（礼貌命令）。"}},
 "Une carafe (d'eau)": {"pos":"n.f. 阴性名词，复数 carafes","s":"水壶；一壶（水）。在法国餐厅点 une carafe d'eau 是免费的自来水，和瓶装水（bouteille）不同。","ipa":"[ka.ʁaf]","ph":"两个 a 读 [a]；r 喉音 [ʁ]；f 读 [f]，结尾 e 不发音。","pi":"最后的 f 要读出来；de 后接 eau 时缩成 d'eau。","et":"经意大利语 caraffa，源自阿拉伯语。英语 carafe 是借词。","ex":[["Une carafe d'eau, s'il vous plaît.","请来一壶水。"],["La carafe est vide.","水壶空了。"],["On prend une carafe de vin ?","我们点一壶酒吧？"]],"co":[["une carafe d'eau","一壶水（自来水）"],["une carafe de vin","一壶酒"],["demander une carafe","要一壶水"],["une carafe en verre","玻璃水壶"]],"sy":[["pichet","courant","小壶、水罐"],["bouteille","courant","瓶子"],["broc","courant","大水壶"]],"fq":"中频，餐厅常用。","me":"carafe 和英语 carafe 一模一样。","tr":{"zh":"请给我们一壶水。","fr":"Une carafe d'eau, s'il vous plaît.","alt":"Pouvez-vous nous apporter une carafe d'eau ?","note":"nous 是间接宾语（给我们）。"}},
 "Une courgette": {"pos":"n.f. 阴性名词，复数 courgettes","s":"西葫芦；绿皮小南瓜。法国菜里常和茄子、西红柿一起做 ratatouille。","ipa":"[kuʁ.ʒɛt]","ph":"ou [u]；r 喉音 [ʁ]；g 在 e 前读 [ʒ]；-ette 读 [ɛt]，e 不发音。","pi":"g 读 [ʒ]；t 要读出来。别和 courage（勇气）混。","et":"courge（葫芦、瓜类）+ 缩小后缀 -ette，courge 来自拉丁语 cucurbita。","ex":[["Je cuisine une courgette.","我做一个西葫芦。"],["Elle coupe des courgettes pour la ratatouille.","她切西葫芦做蔬菜杂烩。"],["Une soupe de courgettes, c'est léger.","西葫芦汤很清淡。"]],"co":[["des courgettes grillées","烤西葫芦"],["une soupe de courgettes","西葫芦汤"],["un gratin de courgettes","焗西葫芦"],["couper une courgette","切西葫芦"]],"sy":[["courge","courant","南瓜、瓜类（更大）"],["aubergine","courant","茄子"]],"fq":"中频，菜市场常见。","me":"courgette = 小 courge（-ette 是「小」）。","tr":{"zh":"我用西葫芦做汤。","fr":"Je fais une soupe avec des courgettes.","alt":"Je prépare une soupe de courgettes.","note":"avec + 名词 = 用……。"}},
 "Une cuillère": {"pos":"n.f. 阴性名词，复数 cuillères（也写 cuiller）","s":"勺子；汤匙。une cuillère à soupe = 汤匙；une cuillère à café = 茶匙。喝汤、搅咖啡都用。","ipa":"[kɥi.jɛʁ]","ph":"c [k]；ui 读 [ɥi]（先圆唇 [ɥ] 再 [i]）；ll 在这里读 [j]；è [ɛ]；r 喉音 [ʁ]。","pi":"ui 是半元音 [ɥi]，不是 [wi]；ll 读 [j]；è 是 [ɛ]。","et":"拉丁语 cochlearium（螺壳勺），cochlea 是蜗牛。","ex":[["Je prends une cuillère pour la soupe.","我用勺子喝汤。"],["Une cuillère de sucre, s'il vous plaît.","请给我一勺糖。"],["Il manque une cuillère.","少了一把勺子。"]],"co":[["une cuillère à soupe","汤匙"],["une cuillère à café","茶匙"],["une cuillère de sucre","一勺糖"],["manger à la cuillère","用勺子吃"]],"sy":[["cuiller","soutenu","cuillère 的另一种拼写"],["louche","courant","汤勺（盛汤用的大勺）"]],"fq":"高频，餐桌常用。","me":"cuillère ← cochlea（蜗牛）：勺子像小螺壳。","tr":{"zh":"请给我一把勺子。","fr":"Je voudrais une cuillère, s'il vous plaît.","alt":"Vous pourriez m'apporter une cuillère ?","note":"voudrais 和 pourriez 是礼貌的条件式。"}},
 "Une endive": {"pos":"n.f. 阴性名词，复数 endives","s":"菊苣（比利时菊苣，白色长形、味微苦的蔬菜）。生吃做沙拉，或用火腿卷起来焗烤：endives au jambon。","ipa":"[ɑ̃.div]","ph":"en [ɑ̃]；d [d]；i [i]；v [v]；结尾 -ve 读 [v]，e 不发音。","pi":"en 读鼻音 [ɑ̃]；这个词的 d 要读，别吞掉。","et":"来源不确定（经中世纪拉丁语进入法语）。","ex":[["L'endive est un peu amère.","菊苣有点苦。"],["Je fais une salade d'endives.","我做菊苣沙拉。"],["Elle aime les endives au jambon.","她爱吃火腿焗菊苣。"]],"co":[["une salade d'endives","菊苣沙拉"],["des endives au jambon","火腿焗菊苣"],["endives braisées","焖菊苣"],["une endive amère","苦的菊苣"]],"sy":[["chicorée","courant","菊苣（相关蔬菜）"],["chicon","familier","endive 在北方的说法"]],"fq":"中低频，法国菜里常见。","me":"endive ≈ 英语 endive，但意思不全相同。","tr":{"zh":"我喜欢吃菊苣沙拉。","fr":"J'aime la salade d'endives.","alt":"J'adore les endives en salade.","note":"salade de + 名词 = ……沙拉。"}},
 "Une épicerie": {"pos":"n.f. 阴性名词，复数 épiceries","s":"杂货店；食品店（卖酱油、罐头、饮料等）。社区里的小店常叫 épicerie；épicerie fine = 高档美食店。","ipa":"[e.pis.ʁi]","ph":"é [e]；p [p]；i [i]；c 在 e/i 前读 [s]；r 喉音 [ʁ]。","pi":"c 在 i 前读 [s]；é 带重音符号，读 [e]。别以为是卖「香料」的店（épice 是香料，但 épicerie 是综合食品店）。","et":"épice（香料）+ -erie。épice 来自拉丁语 species（货物）。","ex":[["Je vais à l'épicerie pour acheter du lait.","我去杂货店买牛奶。"],["L'épicerie du coin est ouverte tard.","街角的杂货店营业到很晚。"],["Elle a une petite épicerie.","她开了一家小杂货店。"]],"co":[["aller à l'épicerie","去杂货店"],["une épicerie fine","高档食品店"],["une épicerie de quartier","社区杂货店"],["l'épicerie du coin","街角的杂货店"]],"sy":[["supérette","courant","小超市"],["supermarché","courant","超市"]],"fq":"中高频，日常常用。","me":"épice → épicerie：从「香料」引申为各种食品。","tr":{"zh":"我去杂货店买牛奶。","fr":"Je vais à l'épicerie acheter du lait.","alt":"Je passe à l'épicerie pour du lait.","note":"aller + 原形 = 去做某事。"}},
 "Une fourchette": {"pos":"n.f. 阴性名词，复数 fourchettes","s":"叉子。也指「范围；区间」：une fourchette de prix = 价格区间。","ipa":"[fuʁ.ʃɛt]","ph":"ou [u]；r 喉音 [ʁ]；ch [ʃ]；-ette 读 [ɛt]，e 不发音。","pi":"ch 读 [ʃ]；t 要读；别把 fourchette 读成 forchette。","et":"fourche（叉）+ -ette；拉丁语 furca（叉）。英语 fork 同源。","ex":[["Je mange avec une fourchette.","我用叉子吃饭。"],["Il manque une fourchette.","少了一把叉子。"],["Quelle est la fourchette de prix ?","价格范围是多少？"]],"co":[["un couteau et une fourchette","刀和叉"],["une fourchette de prix","价格区间"],["manger à la fourchette","用叉子吃"],["avoir un bon coup de fourchette","食量大、很能吃（习语）"]],"sy":[["couvert","courant","餐具"],["fourche","courant","农用叉（大叉）"]],"fq":"高频，餐桌常用。","me":"fourchette = 小的 fourche（叉）。","tr":{"zh":"我需要一把叉子。","fr":"J'ai besoin d'une fourchette.","alt":"Il me faut une fourchette.","note":"avoir besoin de + 名词。"}},
 "Une fromagerie": {"pos":"n.f. 阴性名词，复数 fromageries","s":"奶酪店；奶酪工厂。法国街区里卖各地奶酪的专门店。店主叫 un fromager / une fromagère。","ipa":"[fʁɔ.maʒ.ʁi]","ph":"f [f]；r 喉音 [ʁ]；o [ɔ]；ma [ma]；g 在 e 前读 [ʒ]；整体 fro-ma-ge-rie。","pi":"g 读 [ʒ]；o 读开口 [ɔ]，不是 [o]。fromage 的 -age 不读 [aɡ]。","et":"fromage + -erie。fromage 来自拉丁语 forma（模具）。","ex":[["J'achète du fromage à la fromagerie.","我在奶酪店买奶酪。"],["Cette fromagerie vend du fromage de chèvre.","这家奶酪店卖山羊奶酪。"],["Elle travaille dans une fromagerie.","她在一家奶酪店工作。"]],"co":[["aller à la fromagerie","去奶酪店"],["un fromage de chèvre","山羊奶酪"],["un plateau de fromages","奶酪拼盘"],["le fromager","奶酪师傅"]],"sy":[["crémerie","courant","乳品店（奶、奶油、奶酪）"],["fromage","courant","奶酪（本身）"]],"fq":"中频。","me":"fromage + -erie：奶酪的店。","tr":{"zh":"我去奶酪店买山羊奶酪。","fr":"Je vais à la fromagerie acheter du fromage de chèvre.","alt":"Je passe à la fromagerie pour du fromage de chèvre.","note":"du fromage 是部分冠词。"}},
 "Une orange": {"pos":"n.f. 阴性名词，复数 oranges；作颜色时形容词不变","s":"橙子。orange 也是颜色「橙色」，作形容词不变：des chaussures orange。果汁：un jus d'orange。","ipa":"[ɔ.ʁɑ̃ʒ]","ph":"o [ɔ]；r 喉音 [ʁ]；an [ɑ̃]；g 在 e 前读 [ʒ]；结尾 e 不发音。","pi":"an 读鼻音 [ɑ̃]；g 读 [ʒ]；果实是阴性 une orange，不说 un orange。","et":"源自阿拉伯语 nāranj（橙），经意大利语、普罗旺斯语进入法语。","ex":[["Je bois un jus d'orange.","我喝一杯橙汁。"],["Elle mange une orange.","她吃一个橙子。"],["Les feux sont orange.","信号灯是橙色的。"]],"co":[["un jus d'orange","橙汁"],["une orange pressée","鲜榨橙汁"],["une orange sanguine","血橙"],["un pull orange","橙色毛衣（颜色不变）"]],"sy":[["clémentine","courant","小柑橘"],["mandarine","courant","蜜橘"]],"fq":"高频，日常常用。","me":"orange 在果和色上同形，颜色不变形。","tr":{"zh":"早上我喝一杯橙汁。","fr":"Le matin, je bois un jus d'orange.","alt":"Au petit-déjeuner, je prends un jus d'orange.","note":"jus d'orange 不加冠词（d'）。"}},
 "Une pêche": {"pos":"n.f. 阴性名词，复数 pêches","s":"桃子。同形词 pêche 还有「钓鱼；捕鱼」义。口语：avoir la pêche = 精神饱满、状态极好。","ipa":"[pɛʃ]","ph":"ê [ɛ]；ch [ʃ]；结尾 e 不发音。","pi":"ê 读 [ɛ]，不是 [e]；与 péché（罪）[pe.ʃe] 区分；pêcher 既是「钓鱼」也是「桃树」。","et":"拉丁语 persica（波斯的）。同族：pêcher（桃树）。","ex":[["Cette pêche est sucrée.","这个桃子很甜。"],["Il aime la pêche en rivière.","他喜欢河里钓鱼。"],["J'ai la pêche ce matin !","我今天早上精神特别好！"]],"co":[["une pêche mûre","熟桃子"],["une tarte aux pêches","桃子派"],["aller à la pêche","去钓鱼"],["avoir la pêche","精神饱满（口语）"]],"sy":[["nectarine","courant","油桃"],["abricot","courant","杏"],["énergie","courant","精力"]],"fq":"中频，日常常用。","me":"pêche 的 ê 像小帽子盖住了桃子。","tr":{"zh":"夏天我爱吃桃子。","fr":"En été, j'adore manger des pêches.","alt":"L'été, j'aime bien les pêches.","note":"泛指一类用复数加定冠词。"}},
 "Une pizza": {"pos":"n.f. 阴性名词，复数 pizzas","s":"比萨。借自意大利语。法语里是阴性：une pizza。常说 une pizza margherita / quatre fromages。","ipa":"[pi.dza]","ph":"p [p]；i [i]；zz 读 [dz]；a [a]。","pi":"zz 读 [dz]，不是 [ts]；是阴性，不要说 un pizza。","et":"借自意大利语 pizza。","ex":[["On commande une pizza ce soir ?","今晚点个比萨好吗？"],["J'adore la pizza aux champignons.","我爱蘑菇比萨。"],["Cette pizzeria fait de très bonnes pizzas.","这家比萨店的比萨很好吃。"]],"co":[["commander une pizza","点一个比萨"],["une pizza margherita","玛格丽特比萨"],["une pizza quatre fromages","四种奶酪比萨"],["une part de pizza","一块比萨"]],"sy":[["tarte","courant","派、塔（对比）"],["pizzeria","courant","比萨店"]],"fq":"极高频，日常常用。","me":"pizza 在法语里是阴性：une pizza。","tr":{"zh":"我们今晚点个比萨吧。","fr":"Ce soir, on commande une pizza.","alt":"On se commande une pizza ce soir ?","note":"on = 我们（口语）。"}},
 "Une poire": {"pos":"n.f. 阴性名词，复数 poires","s":"梨。口语里 poire 也是「傻瓜；好欺负的人」（familier）：Quelle poire ! 也有 entre la poire et le fromage（饭后闲聊时）这样的说法。","ipa":"[pwaʁ]","ph":"oi [wa]；r 喉音 [ʁ]，结尾 e 不发音。","pi":"oi 读 [wa]，不是 [oi]；结尾 r 读 [ʁ]。别和 poivre（胡椒）混。","et":"拉丁语 pira（梨）。同族：poirier（梨树）。","ex":[["Cette poire est très juteuse.","这个梨很多汁。"],["Elle mange une poire au dessert.","她甜点吃一个梨。"],["Quelle poire, il a tout payé !","真是个冤大头，他全付了！"]],"co":[["une poire juteuse","多汁的梨"],["une tarte aux poires","梨子派"],["poire Belle-Hélène","巧克力酱煮梨（甜点）"],["entre la poire et le fromage","饭后闲谈时"]],"sy":[["pomme","courant","苹果"],["gogo","familier","傻瓜、好骗的人"],["naïf","courant","天真的人"]],"fq":"中频。","me":"poire ≈ 英语 pear：p-oi-r ↔ p-ea-r。","tr":{"zh":"我想要一个梨当甜点。","fr":"Je voudrais une poire comme dessert.","alt":"Une poire en dessert, s'il vous plaît.","note":"comme dessert = 作为甜点。"}},
 "Une poissonnerie": {"pos":"n.f. 阴性名词，复数 poissonneries","s":"鱼店；海鲜店。店主叫 un poissonnier / une poissonnière。卖鱼、贝类、虾蟹等。","ipa":"[pwa.sɔn.ʁi]","ph":"oi [wa]；ss [s]；onn 读 [ɔn]（不是鼻音）；r 喉音 [ʁ]；ie [i]。","pi":"poisson 的 -on 是鼻音 [ɔ̃]，但 poissonnerie 里 nn 双写，读 [ɔn]；ss 读 [s]（对比 poison [pwa.zɔ̃]）。","et":"poisson（鱼）+ -erie；poisson 来自拉丁语 piscis。","ex":[["Je vais à la poissonnerie pour le saumon.","我去鱼店买三文鱼。"],["La poissonnerie du marché est excellente.","市场里的鱼店很棒。"],["Il y a des crevettes à la poissonnerie.","鱼店有虾。"]],"co":[["aller à la poissonnerie","去鱼店"],["acheter du poisson frais","买新鲜的鱼"],["un étal de poissonnerie","鱼摊"],["le poissonnier","鱼贩"]],"sy":[["marchand de poisson","courant","鱼贩"],["marée","courant","海鲜（总称）"]],"fq":"中低频。","me":"poisson + -erie：卖鱼的店；ss = [s]，别读成毒药 poison。","tr":{"zh":"我去鱼店买新鲜的三文鱼。","fr":"Je vais à la poissonnerie acheter du saumon frais.","alt":"Je passe à la poissonnerie pour du saumon frais.","note":"du saumon 部分冠词（不可数）。"}},
 "Une pomme de terre": {"pos":"n.f. 阴性名词，复数 pommes de terre","s":"土豆。字面「土里的苹果」。复数是 pommes de terre（只有第一个词变复数）。口语说 patate。","ipa":"[pɔm.də.tɛʁ]","ph":"pomme 读 [pɔm]，mm 读一个 [m]；de 弱读 [də]；terre 读 [tɛʁ]。","pi":"复数写 des pommes de terre，不是 des pomme de terres；pomme 的 o 是开口 [ɔ]。","et":"pomme（苹果）+ de terre（地里的）。","ex":[["Je coupe une pomme de terre.","我切一个土豆。"],["Elle fait cuire des pommes de terre.","她煮土豆。"],["Une purée de pommes de terre, c'est facile.","土豆泥很容易做。"]],"co":[["une purée de pommes de terre","土豆泥"],["des pommes de terre sautées","炒土豆"],["des pommes de terre au four","烤土豆"],["éplucher des pommes de terre","削土豆皮"]],"sy":[["patate","familier","土豆（口语）"],["frite","courant","炸薯条（相关）"]],"fq":"极高频，日常常用。","me":"土豆 = 地里的苹果（pomme de terre）。","tr":{"zh":"我削四个土豆。","fr":"J'épluche quatre pommes de terre.","alt":"Je pèle quatre patates.","note":"复数：只有 pomme 变 pommes。"}},
 "Une quiche": {"pos":"n.f. 阴性名词，复数 quiches","s":"法式咸派（用蛋、奶油、培根或蔬菜烤的咸馅饼）。最经典是 quiche lorraine。","ipa":"[kiʃ]","ph":"qu 读 [k]；i [i]；ch 读 [ʃ]；结尾 e 不发音。","pi":"qu 读 [k]，不是 [kw]；ch 读 [ʃ]，不是 [tʃ]。","et":"来自洛林地区的日耳曼语方言（与德语 Kuchen「糕点」同族）。","ex":[["Elle prépare une quiche.","她做一个咸派。"],["La quiche lorraine est délicieuse.","洛林咸派很好吃。"],["On mange une quiche avec une salade.","我们吃咸派配沙拉。"]],"co":[["une quiche lorraine","洛林咸派"],["une quiche aux légumes","蔬菜咸派"],["une part de quiche","一块咸派"],["faire une quiche","做咸派"]],"sy":[["tarte salée","courant","咸派（通称）"],["flan","courant","蛋奶布丁、派"]],"fq":"中频。","me":"quiche 读 [kiʃ]，一口咬下去「kiʃ」。","tr":{"zh":"今天我做咸派配沙拉。","fr":"Aujourd'hui, je fais une quiche avec une salade.","alt":"Ce midi, je prépare une quiche et une salade.","note":"faire 可指「做菜」。"}},
 "Une tasse": {"pos":"n.f. 阴性名词，复数 tasses","s":"杯子（带柄的，喝咖啡、茶用）。une tasse de café = 一杯咖啡。没有柄的玻璃杯叫 verre。","ipa":"[tas]","ph":"t [t]；a [a]；ss [s]，结尾 e 不发音。","pi":"ss 读 [s]；与 verre（玻璃杯）、gobelet（纸杯）区分。","et":"多认为经意大利语 tazza，源自阿拉伯语。","ex":[["Une tasse de café, s'il vous plaît.","请来一杯咖啡。"],["La tasse est chaude.","杯子是热的。"],["Tu veux une tasse de thé ?","你要一杯茶吗？"]],"co":[["une tasse de café / de thé","一杯咖啡 / 茶"],["une tasse à café","咖啡杯"],["boire dans une tasse","用杯子喝"],["ce n'est pas ma tasse de thé","不合我的口味（习语）"]],"sy":[["verre","courant","玻璃杯（无柄）"],["mug","courant","马克杯"],["gobelet","courant","一次性杯"]],"fq":"高频，日常常用。","me":"tasse 和英语 tea 都有 t：喝茶用 tasse。","tr":{"zh":"请给我一杯茶。","fr":"Une tasse de thé, s'il vous plaît.","alt":"Je prendrais une tasse de thé, s'il vous plaît.","note":"une tasse de + 名词，不加冠词。"}},
 "Une tomate": {"pos":"n.f. 阴性名词，复数 tomates","s":"西红柿。法语里是阴性。生吃做沙拉，也做酱：sauce tomate。","ipa":"[tɔ.mat]","ph":"t [t]；o [ɔ]；m [m]；a [a]；t [t]；结尾 e 不发音。","pi":"o 读 [ɔ]，不是英语 [ə]；tomate 是阴性，不说 un tomate。","et":"经西班牙语 tomate，源自纳瓦特尔语 tomatl。","ex":[["Je coupe une tomate pour la salade.","我切一个西红柿做沙拉。"],["Ces tomates sont très mûres.","这些西红柿很熟。"],["On fait une sauce tomate.","我们做番茄酱。"]],"co":[["une salade de tomates","西红柿沙拉"],["une sauce tomate","番茄酱"],["des tomates cerises","小番茄"],["un jus de tomate","番茄汁"]],"sy":[["légume","courant","蔬菜（泛称）"],["tomate cerise","courant","小番茄"]],"fq":"极高频，日常常用。","me":"tomate = tomato 去掉 o，阴性。","tr":{"zh":"我买了三个西红柿。","fr":"J'ai acheté trois tomates.","alt":"J'ai pris trois tomates.","note":"复合过去时用 avoir。"}},
 "Bleu / Saignant / À point / Bien cuit": {"pos":"loc. 牛排熟度表达（形容词）：bleu、saignant、à point、bien cuit","s":"点牛排时的四种熟度：bleu（外面煎一下，几乎生）、saignant（三分熟，有血水）、à point（五分熟，刚好）、bien cuit（全熟）。法国人通常点 saignant 或 à point。","ipa":"[blø] [sɛ.ɲɑ̃] [a pwɛ̃] [bjɛ̃ kɥi]","ph":"bleu 读 [blø]；saignant 读 [sɛ.ɲɑ̃]，gn [ɲ]；à point 读 [a pwɛ̃]；bien cuit 读 [bjɛ̃ kɥi]，结尾 t 不发音。","pi":"saignant 的 -ant 是鼻音 [ɑ̃]；cuit 读 [kɥi]，t 不发音；point 的 t 也不发音。","et":"saignant 来自 saigner（流血），sang（血）；cuit 是 cuire（煮、烤）的过去分词。","ex":[["Je voudrais mon steak à point.","我想要五分熟的牛排。"],["Un steak saignant, s'il vous plaît.","请来一份三分熟的牛排。"],["Elle aime la viande bien cuite.","她喜欢全熟的肉。"]],"co":[["un steak saignant","三分熟牛排"],["une cuisson à point","五分熟"],["une viande bien cuite","全熟的肉"],["Quelle cuisson ?","您要几分熟？"]],"sy":[["rosé","courant","粉红色（介于三分和五分之间）"],["cuisson","courant","烹饪火候"]],"fq":"中频，点牛排时必用。","me":"bleu → saignant → à point → bien cuit：从最生到最熟。","tr":{"zh":"我的牛排要五分熟。","fr":"Je voudrais mon steak à point.","alt":"Mon steak, à point, s'il vous plaît.","note":"熟度作形容词说明牛排，如 saignant。"}},
 "Des biscuits": {"pos":"n.m.pl. 阳性复数名词（单数 un biscuit）","s":"饼干；曲奇。法语 biscuit 多指干的小饼干（un biscuit sec）。美式 cookie 一般说 un cookie。","ipa":"[bis.kɥi]","ph":"b [b]；i [i]；s [s]；c [k]；ui 读 [ɥi]；结尾 t 不发音。","pi":"结尾 t 不读；ui 读 [ɥi]；des biscuits 的 s 不读。","et":"拉丁语 bis coctus（煮两次、烤两次）。同族：cuire（烹饪）。","ex":[["Les enfants mangent des biscuits.","孩子们吃饼干。"],["Je prends un biscuit avec mon café.","我配咖啡吃一块饼干。"],["Ce sont des biscuits au chocolat.","这些是巧克力饼干。"]],"co":[["un paquet de biscuits","一包饼干"],["des biscuits secs","干饼干"],["des biscuits au beurre","黄油饼干"],["un biscuit apéritif","开胃小饼干"]],"sy":[["gâteau","courant","蛋糕、点心"],["cookie","courant","美式曲奇"],["petit-beurre","courant","经典黄油饼干"]],"fq":"高频，日常常用。","me":"bi-s-cuit：烤了两次（bis + cuit）。","tr":{"zh":"孩子们喝茶时吃饼干。","fr":"Les enfants mangent des biscuits avec leur thé.","alt":"Les enfants prennent des biscuits avec du thé.","note":"avec + 名词 = 配着……。"}},
 "Des carottes": {"pos":"n.f.pl. 阴性复数名词（单数 une carotte）","s":"胡萝卜。法国常见的家常菜是 carottes râpées（胡萝卜丝沙拉）。口语：Les carottes sont cuites = 一切都完了，没救了。","ipa":"[ka.ʁɔt]","ph":"c [k]；a [a]；r 喉音 [ʁ]；o 读 [ɔ]；tt 读一个 [t]；结尾 e 不发音。","pi":"tt 只读一个 [t]；o 读 [ɔ]，不是 [o]；s 不读。","et":"拉丁语 carota（胡萝卜），源自希腊语。","ex":[["Je mange des carottes râpées.","我吃胡萝卜丝。"],["Les carottes sont bonnes pour la vue.","胡萝卜对眼睛好。"],["Cette soupe contient des carottes.","这碗汤里有胡萝卜。"]],"co":[["des carottes râpées","胡萝卜丝"],["une soupe de carottes","胡萝卜汤"],["éplucher des carottes","削胡萝卜"],["Les carottes sont cuites.","大势已去（习语）"]],"sy":[["légume","courant","蔬菜（泛称）"],["navet","courant","芜菁（相关蔬菜）"]],"fq":"高频，日常常用。","me":"carotte ≈ carrot：car-rot 的发音相近。","tr":{"zh":"我每天吃胡萝卜丝。","fr":"Je mange des carottes râpées tous les jours.","alt":"Je prends des carottes râpées chaque jour.","note":"tous les jours = 每天。"}},
 "Des cerises": {"pos":"n.f.pl. 阴性复数名词（单数 une cerise）","s":"樱桃。复数用得多：un kilo de cerises。cerise 也是颜色「樱桃红」（形容词不变）。la cerise sur le gâteau = 锦上添花。","ipa":"[sə.ʁiz]","ph":"c 在 e 前读 [s]；e 弱读 [ə]；r [ʁ]；i [i]；s 在元音间读 [z]；结尾 e 不发音。","pi":"s 读 [z]，不是 [s]；结尾 s 复数不读。","et":"拉丁语 cerasia（樱桃），源自希腊语 kerasos。英语 cherry 同源。","ex":[["J'achète des cerises au marché.","我在市场买樱桃。"],["Une tarte aux cerises, c'est délicieux.","樱桃派很好吃。"],["C'est la cerise sur le gâteau !","这真是锦上添花！"]],"co":[["une tarte aux cerises","樱桃派"],["un kilo de cerises","一公斤樱桃"],["la cerise sur le gâteau","锦上添花（习语）"],["rouge cerise","樱桃红"]],"sy":[["griotte","soutenu","酸樱桃"],["fraise","courant","草莓"]],"fq":"中频，夏天常见。","me":"cerise ≈ cherry：c 读 [s] 像英语。","tr":{"zh":"夏天我爱吃樱桃。","fr":"En été, j'adore manger des cerises.","alt":"L'été, j'aime bien les cerises.","note":"j'adore + 复数名词。"}},
 "Des chips": {"pos":"n.f.pl. 阴性复数名词（通常只用复数）","s":"薯片。借自英语，但法语里 chips 是薯片，不是薯条（薯条是 des frites）。常配开胃酒：des chips à l'apéritif。","ipa":"[ʃips]","ph":"ch 读 [ʃ]；i [i]；p [p]；s 读 [s]（英语借词，s 要读）。","pi":"chips 的 s 要读出来 [s]，这是借词的例外；ch 读 [ʃ]，不是 [tʃ]。别和 frites（炸薯条）混。","et":"借自英语 chips。","ex":[["On mange des chips à l'apéritif.","开胃时吃薯片。"],["Tu veux des chips ?","你要薯片吗？"],["Un paquet de chips, s'il vous plaît.","请来一包薯片。"]],"co":[["un paquet de chips","一包薯片"],["des chips au paprika","红椒味薯片"],["des chips à l'ancienne","传统薯片"],["manger des chips","吃薯片"]],"sy":[["frites","courant","炸薯条"],["biscuit apéritif","courant","开胃小饼干"]],"fq":"高频，日常常用。","me":"chips = 薯片；frites = 薯条，别搞反。","tr":{"zh":"我们开胃时吃薯片。","fr":"On mange des chips à l'apéritif.","alt":"À l'apéro, on prend des chips.","note":"apéro 是 apéritif 的口语缩写。"}},
 "Des cigarettes": {"pos":"n.f.pl. 阴性复数名词（单数 une cigarette）","s":"香烟。买烟要去 tabac（烟草店）。un paquet de cigarettes = 一包烟。","ipa":"[si.ɡa.ʁɛt]","ph":"c 在 i 前读 [s]；g 读 [ɡ]；a [a]；r [ʁ]；-ette 读 [ɛt]；s 不读。","pi":"c 读 [s]；g 读 [ɡ]；-ette 的 t 要读；s 复数不读。","et":"cigare（雪茄）+ 缩小后缀 -ette，即「小雪茄」。","ex":[["Il achète des cigarettes.","他买香烟。"],["Il fume trop de cigarettes.","他抽太多烟。"],["Un paquet de cigarettes, s'il vous plaît.","请来一包烟。"]],"co":[["un paquet de cigarettes","一包烟"],["fumer une cigarette","抽一根烟"],["allumer une cigarette","点烟"],["une cigarette électronique","电子烟"]],"sy":[["clope","argot","烟（俚语）"],["tabac","courant","烟草；烟草店"]],"fq":"中频。","me":"cigare + -ette = 小雪茄 = 香烟。","tr":{"zh":"他每天买一包烟。","fr":"Il achète un paquet de cigarettes tous les jours.","alt":"Chaque jour, il prend un paquet de cigarettes.","note":"un paquet de + 复数名词。"}},
 "Des cornichons": {"pos":"n.m.pl. 阳性复数名词（单数 un cornichon）","s":"小酸黄瓜（用醋腌的小黄瓜）。法国人常配肉酱、冷切肉、raclette。口语里 cornichon 也骂人「笨蛋」（familier）。","ipa":"[kɔʁ.ni.ʃɔ̃]","ph":"c [k]；o 读 [ɔ]；r [ʁ]；n [n]；i [i]；ch [ʃ]；on 读鼻音 [ɔ̃]；s、n 不读。","pi":"ch 读 [ʃ]；on 是鼻音 [ɔ̃]，不读 n；注意复数 s 不读。","et":"可能来自 corne（角）加后缀，形似小角；这是通行说法。","ex":[["Je mets des cornichons dans mon sandwich.","我在三明治里加酸黄瓜。"],["Les cornichons vont bien avec la charcuterie.","酸黄瓜配熟肉很搭。"],["Quel cornichon, il a oublié ses clés !","真是个笨蛋，他忘了钥匙！"]],"co":[["un bocal de cornichons","一罐酸黄瓜"],["des cornichons au vinaigre","醋腌酸黄瓜"],["cornichons et charcuterie","酸黄瓜配熟肉"],["Espèce de cornichon !","你这个笨蛋！（口语）"]],"sy":[["concombre","courant","黄瓜（新鲜的）"],["andouille","familier","笨蛋（口语）"]],"fq":"中频。","me":"cornichon 像小小的 corne（角）：弯弯的小黄瓜。","tr":{"zh":"我在三明治里放酸黄瓜。","fr":"Je mets des cornichons dans mon sandwich.","alt":"Je glisse des cornichons dans mon sandwich.","note":"mettre dans = 放进。"}},
 "Des crevettes": {"pos":"n.f.pl. 阴性复数名词（单数 une crevette）","s":"虾（小虾到中等虾，包括 crevette rose 和 crevette grise）。大的对虾叫 gambas。","ipa":"[kʁə.vɛt]","ph":"cr 读 [kʁ]；e 弱读 [ə]，口语里常省略；v [v]；-ette 读 [ɛt]；s 不读。","pi":"cre 中的 e 弱读，常被吞掉；t 要读；s 复数不读。","et":"来源不确定。","ex":[["J'aime manger des crevettes.","我喜欢吃虾。"],["Une salade de crevettes, s'il vous plaît.","请来一份虾沙拉。"],["Elle fait cuire des crevettes à la poêle.","她用平底锅煎虾。"]],"co":[["une salade de crevettes","虾沙拉"],["des crevettes roses","红虾"],["des crevettes grillées","烤虾"],["un cocktail de crevettes","鸡尾虾杯"]],"sy":[["gambas","courant","大对虾"],["langoustine","courant","小龙虾（海螯虾）"]],"fq":"中频。","me":"crevette 和 crever 无关，只记「小虾」。","tr":{"zh":"我喜欢吃烤虾。","fr":"J'aime manger des crevettes grillées.","alt":"J'adore les crevettes grillées.","note":"grillées 与阴性复数 crevettes 配合。"}},
 "Des épices": {"pos":"n.f.pl. 阴性复数名词（单数 une épice）","s":"香料；调味料（胡椒、肉桂、咖喱等）。形容词 épicé = 辣的、有香料味的。","ipa":"[e.pis]","ph":"é [e]；p [p]；i [i]；c 在 e 前读 [s]；s 不读。","pi":"c 读 [s]；é 带重音符号读 [e]；注意重音在最后一个音节。","et":"拉丁语 species（种类；货物）。英语 spice 同源。","ex":[["J'ajoute des épices dans le plat.","我在菜里加香料。"],["Cette sauce est très épicée.","这个酱汁很辣。"],["Elle aime la cuisine aux épices.","她喜欢用香料的菜。"]],"co":[["ajouter des épices","加香料"],["un mélange d'épices","混合香料"],["du pain d'épices","香料蛋糕"],["un plat épicé","辛辣的菜"]],"sy":[["condiment","soutenu","调味品"],["aromate","soutenu","芳香调料（香草等）"]],"fq":"中频。","me":"épice ≈ spice：去掉 é 开头。","tr":{"zh":"我在汤里加了一些香料。","fr":"J'ajoute des épices dans la soupe.","alt":"Je mets des épices dans la soupe.","note":"ajouter ... dans = 往……里加。"}},
 "Des fraises": {"pos":"n.f.pl. 阴性复数名词（单数 une fraise）","s":"草莓。春夏的水果，法国人爱做草莓派（tarte aux fraises）。口语：ramener sa fraise = 出现；多嘴。","ipa":"[fʁɛz]","ph":"f [f]；r [ʁ]；ai 读 [ɛ]；s 在元音间读 [z]；结尾 e 不发音。","pi":"ai 读 [ɛ]；s 读 [z]；别把 fraise 和 frais（新鲜的、凉的）混淆。","et":"拉丁语 fragum（草莓）。","ex":[["J'adore les tartes aux fraises.","我爱草莓派。"],["Je mange des fraises avec de la crème.","我吃草莓配奶油。"],["Ces fraises viennent du jardin.","这些草莓来自花园。"]],"co":[["une tarte aux fraises","草莓派"],["de la confiture de fraises","草莓酱"],["des fraises des bois","野草莓"],["une glace à la fraise","草莓冰淇淋"]],"sy":[["framboise","courant","覆盆子"],["myrtille","courant","蓝莓"]],"fq":"高频，春夏常见。","me":"fraise 读 [fʁɛz]，别混 frais（凉的）。","tr":{"zh":"春天我爱吃草莓。","fr":"Au printemps, j'adore manger des fraises.","alt":"Au printemps, j'aime bien les fraises.","note":"au printemps = 在春天。"}},
 "Des haricots verts": {"pos":"n.m.pl. 阳性复数名词（单数 un haricot vert）","s":"四季豆；青豆角。haricot 单独是「豆子」（haricots blancs 白豆）。h 是「有声 h」（h aspiré），不能连读。","ipa":"[a.ʁi.ko vɛʁ]","ph":"h 不读；haricots 的 h 是有声 h，所以 des haricots 中 s 不连读 [de a.ʁi.ko]；ot 的 t 不读；verts 读 [vɛʁ]，t、s 不读。","pi":"h 是有声 h：des haricots 不连读，不要读成 [de.za.ʁi.ko]；结尾 t 不读；verts 的 r 要读。","et":"多认为来自纳瓦特尔语 ayacotli（豆子）。","ex":[["Je cuisine des haricots verts.","我煮四季豆。"],["Il mange des haricots verts avec du poisson.","他吃四季豆配鱼。"],["Ces haricots verts sont frais.","这些四季豆很新鲜。"]],"co":[["des haricots verts frais","新鲜四季豆"],["des haricots blancs","白豆"],["des haricots rouges","红豆（芸豆）"],["la fin des haricots","大势已去（习语）"]],"sy":[["petits pois","courant","豌豆"],["légume","courant","蔬菜"]],"fq":"中频。","me":"h 有声：不连读，des | haricots。","tr":{"zh":"我今晚煮四季豆。","fr":"Ce soir, je cuisine des haricots verts.","alt":"Ce soir, je fais cuire des haricots verts.","note":"haricot 的 h 阻止连读。"}},
 "Des ingrédients": {"pos":"n.m.pl. 阳性复数名词（单数 un ingrédient）","s":"配料；原料；食材。常用于食谱：les ingrédients de la recette。","ipa":"[ɛ̃.ɡʁe.djɑ̃]","ph":"in 读 [ɛ̃]；gr 读 [ɡʁ]；é [e]；di 读 [dj]；-ent 读 [ɑ̃]；t、s 不读。","pi":"-ent 读 [ɑ̃]，不读 t；-ients 整体是鼻音；注意 in 是 [ɛ̃]，不是英语 [in]。","et":"拉丁语 ingrediens（进入）。英语 ingredient 同源。","ex":[["Il me faut trois ingrédients pour la recette.","这个食谱需要三种配料。"],["Voici les ingrédients du gâteau.","这是蛋糕的配料。"],["Je n'ai pas tous les ingrédients.","我没有所有的配料。"]],"co":[["les ingrédients de la recette","食谱的配料"],["acheter des ingrédients","买配料"],["la liste des ingrédients","配料表"],["des ingrédients frais","新鲜食材"]],"sy":[["composant","soutenu","成分、组成部分"],["produit","courant","产品"]],"fq":"中频。","me":"ingrédients ≈ ingredients：把 -ent 读成鼻音。","tr":{"zh":"我需要买蛋糕的配料。","fr":"Je dois acheter les ingrédients du gâteau.","alt":"Il faut que j'achète les ingrédients du gâteau.","note":"devoir + 原形 = 必须。"}},
 "Des lasagnes": {"pos":"n.f.pl. 阴性复数名词（单数 une lasagne，少用）","s":"千层面（意大利菜）。法语通常用复数：des lasagnes。常见搭配 lasagnes à la bolognaise。","ipa":"[la.zaɲ]","ph":"l [l]；a [a]；s 在元音间读 [z]；gn 读 [ɲ]（像「娘」）；结尾 e 不发音。","pi":"gn 读 [ɲ]，不读 [gn]；s 读 [z]；法语里是阴性复数。","et":"来自意大利语 lasagne（宽面片），可追溯到拉丁语 lasanum。","ex":[["On mange des lasagnes ce soir.","今晚我们吃千层面。"],["Elle fait des lasagnes maison.","她做自制千层面。"],["Les lasagnes sont encore chaudes.","千层面还是热的。"]],"co":[["des lasagnes à la bolognaise","肉酱千层面"],["des lasagnes aux légumes","蔬菜千层面"],["des lasagnes maison","自制千层面"],["faire des lasagnes","做千层面"]],"sy":[["pâtes","courant","意面（泛称）"],["gratin","courant","焗菜"]],"fq":"中频。","me":"lasa-gnes：gn 读 [ɲ]，像「娘」。","tr":{"zh":"今晚我做千层面。","fr":"Ce soir, je fais des lasagnes.","alt":"Ce soir, on mange des lasagnes maison.","note":"faire 可指「做菜」。"}},
 "Des macarons": {"pos":"n.m.pl. 阳性复数名词（单数 un macaron）","s":"马卡龙（两片杏仁蛋白饼夹奶油馅的彩色小点心）。与英语 macaroon（椰蓉甜饼）不同。","ipa":"[ma.ka.ʁɔ̃]","ph":"m [m]；a [a]；c [k]；a [a]；r [ʁ]；on 读鼻音 [ɔ̃]；s 不读。","pi":"on 读 [ɔ̃]，n 不读；与 macaroni（通心粉）区分；英语 macaroon 是另一种点心。","et":"来自意大利语 maccarone，与 macaroni 同源。","ex":[["J'adore les macarons au chocolat.","我爱巧克力马卡龙。"],["Elle achète des macarons chez le pâtissier.","她在糕点店买马卡龙。"],["Ces macarons sont de toutes les couleurs.","这些马卡龙有各种颜色。"]],"co":[["des macarons au chocolat","巧克力马卡龙"],["une boîte de macarons","一盒马卡龙"],["des macarons colorés","彩色马卡龙"],["un macaron à la framboise","覆盆子马卡龙"]],"sy":[["pâtisserie","courant","糕点（总称）"],["biscuit","courant","饼干"]],"fq":"中频。","me":"macaron 的 -on 是鼻音：不是 macaroni。","tr":{"zh":"我爱吃巧克力马卡龙。","fr":"J'adore les macarons au chocolat.","alt":"Je suis fan des macarons au chocolat.","note":"être fan de 是口语表达。"}},
 "Des mouchoirs": {"pos":"n.m.pl. 阳性复数名词（单数 un mouchoir）","s":"纸巾；手帕。des mouchoirs en papier = 纸巾；un mouchoir en tissu = 布手帕。","ipa":"[mu.ʃwaʁ]","ph":"m [m]；ou [u]；ch [ʃ]；oi 读 [wa]；r 要读 [ʁ]；s 不读。","pi":"结尾 r 要读（不是静音）；ou 读 [u]；ch 读 [ʃ]。","et":"来自动词 moucher（擤鼻涕），拉丁语 muccare；加后缀 -oir。","ex":[["Tu as des mouchoirs ?","你有纸巾吗？"],["Je prends des mouchoirs en papier.","我拿些纸巾。"],["Il a un mouchoir dans sa poche.","他口袋里有块手帕。"]],"co":[["un paquet de mouchoirs","一包纸巾"],["des mouchoirs en papier","纸巾"],["un mouchoir en tissu","布手帕"],["se moucher","擤鼻涕"]],"sy":[["Kleenex","courant","纸巾（品牌名常借用）"],["serviette","courant","餐巾、毛巾"]],"fq":"中频，日常常用。","me":"moucher（擤鼻涕）+ -oir：擤鼻涕的工具。","tr":{"zh":"你有纸巾吗？我感冒了。","fr":"Tu as des mouchoirs ? Je suis enrhumé.","alt":"T'as des mouchoirs ? J'ai un rhume.","note":"être enrhumé / avoir un rhume = 感冒。"}},
 "Des noix": {"pos":"n.f.pl. 阴性复数名词（单复数同形 noix）","s":"核桃；也泛指坚果。单独说 noix 多指核桃。noix de coco 椰子，noix de cajou 腰果。","ipa":"[nwa]","ph":"n [n]；oi 读 [wa]；结尾 x 不读。","pi":"x 不读；单数复数都写 noix；与 noisette（榛子）区分。","et":"拉丁语 nux（坚果）。","ex":[["Je mange des noix avec du fromage.","我配奶酪吃核桃。"],["Ce gâteau contient des noix.","这个蛋糕里有核桃。"],["Tu veux une noix de coco ?","你要一个椰子吗？"]],"co":[["des noix de cajou","腰果"],["une noix de coco","椰子"],["une noix de beurre","一小块黄油"],["un gâteau aux noix","核桃蛋糕"]],"sy":[["noisette","courant","榛子"],["amande","courant","杏仁"]],"fq":"中频。","me":"noix = 核桃；x 不读。","tr":{"zh":"我在沙拉里放一些核桃。","fr":"Je mets des noix dans la salade.","alt":"J'ajoute des noix à la salade.","note":"noix 单复数同形。"}},
 "Des oignons": {"pos":"n.m.pl. 阳性复数名词（单数 un oignon）","s":"洋葱。切洋葱会流泪：pleurer en coupant des oignons。口语：Occupe-toi de tes oignons = 管好你自己的事。","ipa":"[ɔ.ɲɔ̃]","ph":"o 读 [ɔ]；ign 读 [ɲ]；on 读鼻音 [ɔ̃]；s 不读。","pi":"oi 在这里读 [ɔ]，不是 [wa]；gn 读 [ɲ]；这是个不规则拼写。","et":"拉丁语 unio（洋葱）。英语 onion 同源。","ex":[["Je pleure quand je coupe des oignons.","切洋葱时我会流泪。"],["Elle fait revenir les oignons dans l'huile.","她把洋葱放油里炒。"],["Occupe-toi de tes oignons !","管好你自己的事！"]],"co":[["une soupe à l'oignon","洋葱汤"],["éplucher des oignons","削洋葱"],["des oignons rouges","红洋葱"],["occupe-toi de tes oignons","少管闲事（口语）"]],"sy":[["échalote","courant","红葱头"],["ail","courant","大蒜"]],"fq":"高频，日常常用。","me":"oignon 读 [ɔ.ɲɔ̃]，不读 oi [wa]。","tr":{"zh":"切洋葱时我会流泪。","fr":"Je pleure quand je coupe des oignons.","alt":"Je pleure à chaque fois que je coupe des oignons.","note":"quand + 现在时，表示习惯。"}},
 "Des olives": {"pos":"n.f.pl. 阴性复数名词（单数 une olive）","s":"橄榄。绿橄榄 olives vertes，黑橄榄 olives noires。法国人开胃常吃。","ipa":"[ɔ.liv]","ph":"o 读 [ɔ]；l [l]；i [i]；v [v]；结尾 e 不发音；s 不读。","pi":"o 读 [ɔ]；重音在最后一个音节；v 要读出来。","et":"拉丁语 oliva（橄榄）。英语 olive 同源。","ex":[["J'achète des olives vertes.","我买绿橄榄。"],["On mange des olives à l'apéritif.","开胃时我们吃橄榄。"],["Ce pain contient des olives noires.","这个面包里有黑橄榄。"]],"co":[["de l'huile d'olive","橄榄油"],["des olives vertes / noires","绿橄榄 / 黑橄榄"],["un bol d'olives","一碗橄榄"],["un olivier","橄榄树"]],"sy":[["olivier","courant","橄榄树"],["huile","courant","油"]],"fq":"中频。","me":"olive ≈ olive：两种语言几乎一样。","tr":{"zh":"我们开胃时吃橄榄。","fr":"On mange des olives à l'apéritif.","alt":"À l'apéro, on prend des olives.","note":"apéritif 的口语是 apéro。"}},
 "Des pâtes": {"pos":"n.f.pl. 阴性复数名词（单数 la pâte = 面团）","s":"意面；泛指各种面食。几乎总用复数 des pâtes；单数 la pâte 是「面团、糊状物」，如 la pâte à pizza（比萨面团）。","ipa":"[pɑt]","ph":"â 读长音 [ɑ]；t 要发音；结尾 -es 不发音。des 读 [de]。","pi":"t 要读出来，不要吞掉；â 的帽子只表示长音，不是 [a] 加别的音。","et":"来自晚期拉丁语 pasta（面团），再往上追到希腊语。","ex":[["Je mange des pâtes avec de la sauce tomate.","我吃番茄酱意面。"],["Ce soir, on fait des pâtes.","今晚我们煮意面。"]],"co":[["des pâtes fraîches","新鲜意面"],["cuire les pâtes","煮意面"],["la pâte à pizza","比萨面团"]],"sy":[["spaghettis","courant","细长条意面，是 pâtes 的一种"],["nouilles","courant","面条（多指亚洲面条）"]],"fq":"高频，日常饮食必备。","me":"pâtes = pasta：想着一盘意面，â 头上戴小帽。","tr":{"zh":"今晚我们吃意面。","fr":"Ce soir, on mange des pâtes.","alt":"Ce soir, c'est pâtes !","note":"泛指食物用 des；on 在口语里常代替 nous。"}},
 "Des petits pois": {"pos":"n.m.pl. 阳性复数名词（单数 un petit pois）","s":"豌豆（青豆粒）。通常成组出现，用复数 des petits pois；是法国家常配菜，常配肉、胡萝卜。","ipa":"[pə.ti pwa]","ph":"petits 的 e 轻读 [ə]，ts 不发音；pois 读 [pwa]，s 不发音。petits 和 pois 之间不连读。","pi":"petits pois 里两个 s/ts 都不发音；别把 pois 读成 [pwaz]。","et":"petit + pois；pois 来自拉丁语 pisum（豌豆）。","ex":[["Je mange des petits pois avec la viande.","我吃豌豆配肉。"],["Les enfants n'aiment pas les petits pois.","孩子们不爱吃豌豆。"]],"co":[["des petits pois en boîte","罐装豌豆"],["des petits pois-carottes","豌豆胡萝卜（经典家常菜）"],["un petit pois","一粒豌豆"]],"sy":[["haricots verts","courant","四季豆（别和豌豆混淆）"],["pois chiches","courant","鹰嘴豆，另一种豆子"]],"fq":"中频，饮食话题常见。","me":"petits（小的）+ pois：「小粒的豆」。","tr":{"zh":"我喜欢豌豆配胡萝卜。","fr":"J'aime les petits pois avec des carottes.","alt":"J'adore les petits pois-carottes.","note":"表示喜欢某类食物，用 les（定冠词）。"}},
 "Des pruneaux": {"pos":"n.m.pl. 阳性复数名词（单数 un pruneau，复数 -eaux）","s":"梅干；李子干（prune 的干果）。注意：新鲜的李子是 une prune，pruneau 专指晒干的。","ipa":"[pʁy.no]","ph":"pr 中 r 是小舌音 [ʁ]；u [y] 嘴唇圆而紧；-eau 读 [o]。","pi":"u 读 [y]，不是 [u]；-eaux 的 x 不发音。","et":"prune（拉丁语 prunum，李子）+ 后缀 -eau。","ex":[["Je mange des pruneaux.","我吃梅干。"],["Elle fait un lapin aux pruneaux.","她做了梅干炖兔肉。"]],"co":[["des pruneaux d'Agen","阿让梅干（法国名产）"],["un jus de pruneau","梅干汁"],["des pruneaux secs","干梅子"]],"sy":[["prune","courant","新鲜的李子，不是干的"],["raisins secs","courant","葡萄干，另一种干果"]],"fq":"低中频，食品话题。","me":"pruneau = prune 的「干」版本。","tr":{"zh":"我早餐吃梅干。","fr":"Je mange des pruneaux au petit-déjeuner.","alt":"Au petit-déj', je prends des pruneaux.","note":"au petit-déjeuner 表示「早餐时」。"}},
 "Des sardines": {"pos":"n.f.pl. 阴性复数名词（单数 une sardine）","s":"沙丁鱼。常见的是罐头沙丁鱼 (sardines à l'huile)，也可烤着吃。être serrés comme des sardines =「挤得像沙丁鱼罐头」。","ipa":"[saʁ.din]","ph":"ar [aʁ]；in 在这里不是鼻音，因为 n 后有元音 e，读 [din]；结尾 -es 不发音。","pi":"sardine 里的 in 读 [in]，不是鼻化 [ɛ̃]。","et":"拉丁语 sardina，据说与撒丁岛 (Sardaigne) 有关，那里出产这种鱼。","ex":[["Il y a des sardines dans la boîte.","盒子里有沙丁鱼。"],["On grille des sardines sur la plage.","我们在沙滩上烤沙丁鱼。"]],"co":[["des sardines à l'huile","油浸沙丁鱼罐头"],["une boîte de sardines","一盒沙丁鱼"],["serrés comme des sardines","挤得像沙丁鱼（拥挤）"]],"sy":[["poisson","courant","鱼的总称"],["maquereau","courant","鲭鱼，另一种常见罐头鱼"]],"fq":"中频。","me":"sardine ← Sardaigne：来自撒丁岛的小鱼。","tr":{"zh":"我午饭吃了沙丁鱼。","fr":"J'ai mangé des sardines à midi.","alt":"À midi, j'ai pris des sardines.","note":"à midi = 中午；吃过了用 j'ai mangé。"}},
 "Des spaghettis": {"pos":"n.m.pl. 阳性复数名词","s":"意大利细面条。来自意大利语；法语里写作 des spaghettis（也可写 des spaghetti 不变）。通常指那种长长的圆面条。","ipa":"[spa.ɡe.ti]","ph":"gh 在 e 前读硬音 [ɡ]；tt 读单个 [t]；结尾 s 不发音。","pi":"gh = [ɡ]，不是 [ʒ]；双写 tt 不用读两遍。","et":"意大利语 spaghetti，是 spaghetto（细绳）的复数。","ex":[["Les enfants aiment les spaghettis.","孩子们爱吃意面。"],["Je fais des spaghettis à la bolognaise.","我做肉酱意面。"]],"co":[["des spaghettis à la bolognaise","肉酱意面"],["des spaghettis carbonara","卡邦那拉意面"],["cuire des spaghettis","煮意面"]],"sy":[["pâtes","courant","各种面食的总称"],["tagliatelles","courant","宽扁条意面"]],"fq":"中频，饮食常见。","me":"spaghetti = 「细绳」，一根根长长的。","tr":{"zh":"我想要肉酱意面。","fr":"Je voudrais des spaghettis à la bolognaise.","alt":"Je prends des spaghettis bolognaise.","note":"点菜用 je voudrais 更礼貌。"}},
 "Des sushis": {"pos":"n.m.pl. 阳性复数名词（也可写 sushi 不变）","s":"寿司。借自日语；法语常说 des sushis，也有人不加 s。点外卖、日料店都很常用。","ipa":"[su.ʃi]","ph":"s 在词首读 [s]；u 在这里读 [u]（外来词）；ch/sh 读 [ʃ]；结尾 s 不发音。","pi":"u 读 [u] 像「苏」，不是法语常见的 [y]。","et":"日语 sushi（寿司）。","ex":[["On commande des sushis ?","我们点寿司吧？"],["Je prends un plateau de sushis.","我要一份寿司拼盘。"]],"co":[["un plateau de sushis","寿司拼盘"],["un restaurant de sushis","寿司店"],["commander des sushis","点寿司"]],"sy":[["makis","courant","寿司卷，是寿司的一种"],["sashimi","courant","生鱼片，不含饭"]],"fq":"中频，年轻人常说。","me":"sushi 的读音和中文「苏什」很像。","tr":{"zh":"今晚我们点寿司吧。","fr":"Ce soir, on commande des sushis.","alt":"Ce soir, on se commande des sushis ?","note":"on commande = 我们点（口语里 on 代替 nous）。"}},
 "La carte / Le menu": {"pos":"n.f. / n.m. 名词（la carte 阴性；le menu 阳性，复数 menus）","s":"菜单。la carte 是完整的菜单（可单点），le menu 在法国多指「套餐」(固定价格的前菜+主菜+甜点)。日常口语里 le menu 也常泛指菜单。","ipa":"[kaʁt] / [mə.ny]","ph":"carte：ar [aʁ]，t 发音，结尾 e 不发音；menu：e 轻读 [ə]，u [y]。","pi":"menu 的 u 读 [y]，嘴唇要圆；carte 的 t 读出来。","et":"carte ← 拉丁语 charta（纸）；menu ← 拉丁语 minutus（小的、细的），原指「详细的小清单」。","ex":[["Je regarde le menu.","我看菜单。"],["On peut avoir la carte, s'il vous plaît ?","请给我们菜单好吗？"]],"co":[["demander la carte","要菜单"],["manger à la carte","单点（不点套餐）"],["le menu du jour","今日套餐"],["la carte des vins","酒单"]],"sy":[["formule","courant","套餐（午餐常见：plat + dessert）"],["la carte","courant","完整菜单，和 menu（套餐）对比"]],"fq":"高频，餐厅必备。","me":"carte = 一张「卡」；menu = 套餐，固定价格。","tr":{"zh":"请给我们菜单。","fr":"La carte, s'il vous plaît.","alt":"On pourrait avoir la carte, s'il vous plaît ?","note":"carte 阴性，所以用 la；menu 阳性，用 le。"}},
 "Le fromager / La fromagère": {"pos":"n.m. / n.f. 名词，阳 fromager / 阴 fromagère","s":"奶酪商；专门卖奶酪的店主。在法国有专门的奶酪店 la fromagerie，店主会给你推荐、切开试吃。","ipa":"[fʁɔ.ma.ʒe] / [fʁɔ.ma.ʒɛʁ]","ph":"fr [fʁ]；o 读开口 [ɔ]；g 在 e/è 前读 [ʒ]；阳性结尾 -er 读 [e]，阴性 -ère 读 [ɛʁ]。","pi":"阳性 -er 的 r 不发音，阴性 -ère 的 r 要发音；g 读 [ʒ]。","et":"fromage（来自拉丁语 formaticum，放进模具成形的东西）+ 后缀 -er。","ex":[["Le fromager me conseille un bon fromage.","奶酪商给我推荐好奶酪。"],["La fromagère coupe un morceau de comté.","女奶酪商切了一块孔泰奶酪。"]],"co":[["chez le fromager","在奶酪店"],["aller chez la fromagère","去女奶酪商那里"],["une fromagerie","奶酪店"]],"sy":[["crémier","soutenu","乳制品商（较老的说法）"],["commerçant","courant","商贩的总称"]],"fq":"低中频，购物话题。","me":"fromage + -er = 卖 fromage 的人。","tr":{"zh":"我去奶酪商那里买奶酪。","fr":"Je vais chez le fromager acheter du fromage.","alt":"Je passe chez le fromager pour prendre du fromage.","note":"chez + 人 = 去某人的店。"}},
 "Un boucher / Une bouchère": {"pos":"n.m. / n.f. 名词，阳 boucher / 阴 bouchère","s":"肉铺老板；卖肉的人（猪、牛、羊肉等）。店叫 la boucherie。书里译「屠夫」，现代法语里主要指卖肉的店主，不带贬义。","ipa":"[bu.ʃe] / [bu.ʃɛʁ]","ph":"ou [u]；ch [ʃ]；阳性 -er 读 [e]，阴性 -ère 读 [ɛʁ]。","pi":"ou 读 [u]；ch 读 [ʃ]，不是 [k]；阳性词尾 r 不发音。","et":"来自 bouc（公山羊）+ -er，最初指卖山羊肉的人。","ex":[["Le boucher prépare la viande.","屠夫在处理肉。"],["La bouchère coupe des steaks.","女肉铺老板在切牛排。"]],"co":[["chez le boucher","在肉铺"],["une boucherie","肉铺"],["acheter de la viande chez le boucher","在肉铺买肉"]],"sy":[["charcutier","courant","卖猪肉制品和熟食的人"],["boucherie","courant","肉铺（店，不是人）"]],"fq":"中频，购物话题。","me":"boucher ← bouc（山羊）：先卖羊肉的人。","tr":{"zh":"肉铺老板的肉很好。","fr":"La viande du boucher est très bonne.","alt":"Le boucher a de la très bonne viande.","note":"la viande du boucher：de 表示「属于」。"}},
 "Un boulanger / Une boulangère": {"pos":"n.m. / n.f. 名词，阳 boulanger / 阴 boulangère","s":"面包师；开面包店的人。店叫 la boulangerie，法国人每天早上买 baguette。注意 boulanger 做面包，pâtissier 做甜点。","ipa":"[bu.lɑ̃.ʒe] / [bu.lɑ̃.ʒɛʁ]","ph":"ou [u]；an 鼻化 [ɑ̃]；g 在 e 前读 [ʒ]；阳性 -er 读 [e]，阴性 -ère 读 [ɛʁ]。","pi":"an 是鼻化元音，不发 n；g 读 [ʒ]。阴性 -ère 的 r 要读。","et":"来源与 boule（圆面包）有关，经古皮卡第语演变；细节不完全确定。","ex":[["Le boulanger fait du bon pain.","面包师做好面包。"],["La boulangère nous donne une baguette.","女面包师递给我们一根法棍。"]],"co":[["chez le boulanger","在面包店"],["une boulangerie","面包店"],["une boulangerie-pâtisserie","面包甜点店"]],"sy":[["pâtissier","courant","做甜点和蛋糕的人"],["boulangerie","courant","面包店（店，不是人）"]],"fq":"中高频，日常购物。","me":"boulanger → boule：圆圆的面包。","tr":{"zh":"面包师每天早上做面包。","fr":"Le boulanger fait du pain tous les matins.","alt":"Tous les matins, le boulanger prépare le pain.","note":"faire du pain：不可数名词用 du。"}},
 "Un épicier / Une épicière": {"pos":"n.m. / n.f. 名词，阳 épicier / 阴 épicière","s":"杂货店老板；小食品店店主。店叫 l'épicerie，卖罐头、饮料、日用食品。很多小区里的 épicerie 营业到很晚。","ipa":"[e.pi.sje] / [e.pi.sjɛʁ]","ph":"é [e]；c 在 i 前读 [s]；-ier 读 [je]，阴性 -ière 读 [jɛʁ]。","pi":"c 读 [s]，不是 [k]；开头 é 要有重音符号。","et":"épice（拉丁语 species，货品、香料）+ -ier。","ex":[["L'épicier est très gentil.","杂货店老板人很好。"],["Je vais chez l'épicière du coin.","我去街角的杂货店老板娘那里。"]],"co":[["une épicerie","杂货店"],["l'épicier du coin","街角杂货店老板"],["une épicerie fine","精品食品店"]],"sy":[["commerçant","courant","商贩的总称"],["supermarché","courant","超市，更大"]],"fq":"中频。","me":"épicier ← épice：最早卖香料的人。","tr":{"zh":"街角的杂货店老板很友好。","fr":"L'épicier du coin est très sympa.","alt":"Le monsieur de l'épicerie du coin est super gentil.","note":"du coin = 附近、街角的。"}},
 "Un poissonnier / Une poissonnière": {"pos":"n.m. / n.f. 名词，阳 poissonnier / 阴 poissonnière","s":"鱼贩；卖鱼和海鲜的人。店叫 la poissonnerie。注意 poisson（鱼）和 poison（毒药）只差一个 s，别搞混。","ipa":"[pwa.sɔ.nje] / [pwa.sɔ.njɛʁ]","ph":"oi 读 [wa]；ss 读 [s]；-ier 读 [nje]，阴性 -ière 读 [njɛʁ]。","pi":"poisson [pwasɔ̃] 是鱼，poison [pwazɔ̃] 是毒药，s 的发音不同。","et":"poisson（拉丁语 piscis，鱼）+ -ier。","ex":[["Le poissonnier vend des huîtres.","鱼贩卖牡蛎。"],["La poissonnière a du saumon frais.","女鱼贩有新鲜三文鱼。"]],"co":[["une poissonnerie","鱼店"],["chez le poissonnier","在鱼店"],["le poissonnier du marché","市场里的鱼贩"]],"sy":[["marchand de poissons","courant","同义说法，较长"],["commerçant","courant","商贩的总称"]],"fq":"中低频，市场、购物话题。","me":"poisson（鱼）+ -ier = 卖鱼的人。","tr":{"zh":"我在市场的鱼贩那里买鱼。","fr":"J'achète du poisson chez le poissonnier du marché.","alt":"Je prends mon poisson chez le poissonnier du marché.","note":"chez le poissonnier = 在鱼贩那里。"}},
 "Un(e) commerçant(e)": {"pos":"n.m. / n.f. 名词（阴性 commerçante）；也可作形容词","s":"店主；商贩；做买卖的人。是 boucher、boulanger 等小店主的总称。形容词用法：une rue commerçante =「商业街」。","ipa":"[kɔ.mɛʁ.sɑ̃] / [kɔ.mɛʁ.sɑ̃t]","ph":"c 在 o 前读 [k]；ç 读 [s]；an 鼻化 [ɑ̃]；阴性 t 要发音。","pi":"ç 读 [s]；阳性不发 t，阴性 commerçante 要发 [t]。","et":"commerce（拉丁语 commercium，买卖）+ -ant。","ex":[["Ce commerçant travaille beaucoup.","这位店主很勤奋。"],["Elle est commerçante dans le centre-ville.","她在市中心做生意。"]],"co":[["une rue commerçante","商业街"],["un petit commerçant","小店主"],["les commerçants du quartier","街区的商家"]],"sy":[["marchand","courant","商人，卖货的人"],["vendeur","courant","售货员，打工的，不一定是店主"]],"fq":"中频。","me":"commerce + -ant = 做 commerce 的人。","tr":{"zh":"街区的商家都很友好。","fr":"Les commerçants du quartier sont très gentils.","alt":"Les commerçants du coin sont super sympas.","note":"commerçants 复数，形容词 gentils 也加 s。"}},
 "Je voudrais": {"pos":"v. vouloir 的条件式，第一人称单数","s":"我想要……（礼貌地提出请求）。点菜、买东西时最标准的说法：Je voudrais + 名词 / + 动词原形。比 Je veux 更客气，Je veux 听起来很直接。","ipa":"[ʒə vu.dʁɛ]","ph":"je 轻读 [ʒə]；ou [u]；-ais 读 [ɛ]，s 不发音；d 后 r 是小舌音 [ʁ]。","pi":"-ais 结尾读 [ɛ]，不读 s；voudrais 和 voudrai（将来时）读音接近，但意思不同。","et":"vouloir（拉丁语 volere）的条件式。条件式表示礼貌、委婉。","ex":[["Je voudrais un café, s'il vous plaît.","我想要一杯咖啡。"],["Je voudrais réserver une table pour deux.","我想订一张两人桌。"],["Je voudrais savoir où est la gare.","我想知道火车站在哪里。"]],"co":[["Je voudrais + 名词","我想要……"],["Je voudrais + 动词原形","我想（做）……"],["Je voudrais bien…","我真想……"],["Vous voudriez autre chose ?","您还想要别的吗？"]],"sy":[["j'aimerais","courant","同样礼貌，语气更柔和"],["je veux","courant","更直接，点菜时不够客气"],["je désirerais","soutenu","更正式，服务员常用"]],"fq":"极高频，购物、餐厅必备。","me":"voudrais = veux 的「礼貌版」，像英语 would like。","tr":{"zh":"我想要一杯水，谢谢。","fr":"Je voudrais un verre d'eau, merci.","alt":"Je pourrais avoir un verre d'eau, s'il vous plaît ?","note":"后接名词或动词原形；加 s'il vous plaît 更礼貌。"}},
 "Acheter": {"pos":"v.t. 及物动词，第一组，助动词 avoir（有 è 变化：j'achète, nous achetons）","s":"买。acheter + 东西 (à qqn)：向某人买。变位时 e 会变 è：j'achète, tu achètes, ils achètent，但 nous achetons, vous achetez 不变。","ipa":"[aʃ.te]","ph":"ch [ʃ]；e 在词中常不发音，读作 [aʃ.te]。变位 achète 读 [a.ʃɛt]。","pi":"j'achète 里的 è 读 [ɛ]，nous achetons 读 [aʃ.tɔ̃]；别忘了 achète 的重音。","et":"来自通俗拉丁语 accaptare（取得），由 ad- + captare 而来。","ex":[["Je vais acheter du pain.","我要去买面包。"],["Elle achète une robe rouge.","她买一条红裙子。"],["Tu achètes ça où ?","你在哪里买这个？"]],"co":[["acheter qqch à qqn","向某人买某物"],["acheter en ligne","在网上买"],["acheter à crédit","分期付款买"],["acheter pour + 价格","花多少钱买"]],"sy":[["se procurer","soutenu","弄到手、获得"],["prendre","courant","拿；在店里也可说「我要这个」"],["vendre","courant","反义词：卖"]],"fq":"极高频，购物必备。","me":"acheter：想「花钱 + 拿走」，a-ch。","tr":{"zh":"我去超市买牛奶。","fr":"Je vais au supermarché acheter du lait.","alt":"Je passe au supermarché pour acheter du lait.","note":"acheter du lait：不可数名词用 du。"}},
 "Ajouter": {"pos":"v.t. 及物动词，第一组，助动词 avoir","s":"加；添加。ajouter A à B =「把 A 加到 B 里」。也表示说话时「补充说」：Il ajoute que… =「他补充说……」。","ipa":"[a.ʒu.te]","ph":"j 读 [ʒ]；ou [u]；结尾 -er 读 [e]。","pi":"j 读 [ʒ]，不是 [dʒ]；ou 读 [u]，嘴圆。","et":"来自拉丁语 adjuxtare（靠近放），由 juxta（旁边）而来。","ex":[["Vous pouvez ajouter du sucre.","您可以加糖。"],["J'ajoute un peu de sel.","我加一点点盐。"],["Il ajoute qu'il est content.","他补充说他很高兴。"]],"co":[["ajouter du sel","加盐"],["ajouter A à B","把 A 加到 B"],["ajouter que…","补充说……"],["en ajoutant","加上……"]],"sy":[["rajouter","courant","再加、又添"],["mettre","courant","放（更口语）"],["enlever","courant","反义词：拿掉"]],"fq":"高频，做饭、说明时常用。","me":"ajouter ≈ a + joute：往上「叠加」。","tr":{"zh":"我在汤里加一点盐。","fr":"J'ajoute un peu de sel dans la soupe.","alt":"Je rajoute un peu de sel à la soupe.","note":"un peu de + 不可数名词；dans/à la soupe 都可以。"}},
 "Aller": {"pos":"v.i. 不规则动词，助动词 être（je vais, tu vas, il va, nous allons, vous allez, ils vont）","s":"去；也表示身体状况「Ça va ?」（还好吗）。aller + 动词原形 = 即将做某事（futur proche）：Je vais manger =「我要去吃饭了」。","ipa":"[a.le]","ph":"ll 读单个 [l]；结尾 -er 读 [e]。变位 vais [vɛ]、va [va]、vont [vɔ̃]。","pi":"vais 读 [vɛ]，s 不发音；vont 是鼻化 [vɔ̃]；复合时用 être：je suis allé。","et":"变位来自三个拉丁语动词：vadere（vais）、ire（irai）和 ambulare（aller）。","ex":[["Je vais au supermarché.","我去超市。"],["Ça va ? Oui, ça va bien.","还好吗？嗯，很好。"],["Nous allons manger ensemble.","我们要一起吃饭。"]],"co":[["aller à + 地点","去某地"],["aller bien / mal","身体好 / 不好"],["aller + 动词原形","即将做……"],["Ça va ?","还好吗？"]],"sy":[["se rendre","soutenu","前往"],["partir","courant","出发，离开"],["venir","courant","反义词：来"]],"fq":"极高频，必学。","me":"vais / va / vont：全是 v 开头，不像 aller。","tr":{"zh":"我明天去巴黎。","fr":"Je vais à Paris demain.","alt":"Demain, je vais à Paris.","note":"aller à + 城市；用 vais，不是 allez。"}},
 "Boire": {"pos":"v.t. 不规则动词，助动词 avoir（je bois, nous buvons, ils boivent；过去分词 bu）","s":"喝。boire + 饮料。也可不带宾语：Il boit trop. =「他喝多了（酒）」。喝汤用 manger de la soupe 更常见，不说 boire la soupe。","ipa":"[bwaʁ]","ph":"oi 读 [wa]；结尾 r 读 [ʁ]。nous buvons 的词干变成 buv-。","pi":"bois 读 [bwa]；nous buvons、ils boivent 词干变了；过去分词 bu 只有一个音 [by]。","et":"拉丁语 bibere（喝）。","ex":[["Il faut boire beaucoup d'eau.","要多喝水。"],["Qu'est-ce que tu bois ?","你喝什么？"],["Nous avons bu un café.","我们喝了一杯咖啡。"]],"co":[["boire de l'eau","喝水"],["boire un verre","喝一杯（常指喝点酒）"],["boire un coup","喝一杯（口语）"],["boire trop","喝多了"]],"sy":[["prendre","courant","点（饮料）：Je prends un café"],["siroter","familier","小口品着喝"],["manger","courant","吃，别和 boire 混"]],"fq":"极高频。","me":"boire ← bibere：像英语 beverage。","tr":{"zh":"你想喝点什么？","fr":"Qu'est-ce que tu veux boire ?","alt":"Tu veux boire quelque chose ?","note":"vouloir + 动词原形；boire 不变位。"}},
 "Casser": {"pos":"v.t. 及物动词，第一组，助动词 avoir；se casser = 断了","s":"打破；弄坏；折断。casser un verre =「打碎杯子」。se casser la jambe =「摔断腿」。口语里 se casser =「走人」，ça casse les pieds =「烦死了」。","ipa":"[ka.se]","ph":"ss 读 [s]；结尾 -er 读 [e]。","pi":"ss 读清音 [s]，不是 [z]；别和 casser 的名词 casse 混用。","et":"来自拉丁语 quassare（猛烈摇晃，打碎）。","ex":[["Il ne faut pas casser ce verre.","别把这个杯子打碎了。"],["Je me suis cassé le bras.","我摔断了手臂。"],["Le téléphone est cassé.","电话坏了。"]],"co":[["casser un verre","打碎杯子"],["se casser la jambe","摔断腿"],["être cassé","坏了、断了"],["casser les pieds à qqn","烦人（口语）"]],"sy":[["briser","soutenu","打碎，更书面"],["abîmer","courant","弄坏（不一定破碎）"],["réparer","courant","反义词：修理"]],"fq":"高频，日常常用。","me":"casser = 「咔嚓」一声。","tr":{"zh":"我不小心打碎了一个杯子。","fr":"J'ai cassé un verre sans faire exprès.","alt":"J'ai cassé un verre par accident.","note":"casser 复合过去时用 avoir：j'ai cassé。"}},
 "Choisir": {"pos":"v.t. 及物动词，第二组（-ir，变位 -issons），助动词 avoir","s":"选择；挑选。choisir + 名词 / 动词原形。点菜、买东西、做决定时常用。choisir entre A et B =「在 A 和 B 之间选」。","ipa":"[ʃwa.ziʁ]","ph":"ch [ʃ]；oi [wa]；s 在元音间读 [z]；结尾 r 读 [ʁ]。","pi":"s 读 [z]；变位时 nous choisissons，注意 -iss-；过去分词 choisi。","et":"来自法兰克语（日耳曼语）kausjan（品尝、试），与英语 choose 同源。","ex":[["Tu dois choisir un dessert.","你得选一个甜点。"],["Elle choisit une robe bleue.","她选了一条蓝裙子。"],["Vous avez choisi ?","您选好了吗？（服务员常说）"]],"co":[["choisir entre A et B","在 A 和 B 之间选择"],["choisir de + 动词原形","决定做……"],["bien choisir","选得好"],["Vous avez choisi ?","您选好了吗？"]],"sy":[["sélectionner","soutenu","挑选，更书面"],["prendre","courant","点：Je prends ça"],["hésiter","courant","犹豫，选不出来"]],"fq":"高频，餐厅、购物常用。","me":"choisir ≈ choose：同源词。","tr":{"zh":"你选好了吗？","fr":"Tu as choisi ?","alt":"Vous avez choisi ?","note":"复合过去时 tu as choisi；对陌生人用 vous。"}},
 "Commander": {"pos":"v.t. 及物动词，第一组，助动词 avoir","s":"点（菜）；订购。commander un café =「点一杯咖啡」。另一个意思是「指挥、命令」：commander à qqn de…。网购也用 commander。","ipa":"[kɔ.mɑ̃.de]","ph":"c [k]；o 开口 [ɔ]；an 鼻化 [ɑ̃]；结尾 -er 读 [e]。","pi":"an 鼻化 [ɑ̃]，不发 n；小心不要读成 commandé 以外的音。","et":"来自通俗拉丁语 commandare（交给、命令），由 com- + mandare 而来。","ex":[["On va commander une pizza.","我们点一个比萨吧。"],["J'ai commandé un livre en ligne.","我在网上订了一本书。"],["Je voudrais commander, s'il vous plaît.","我想点菜。"]],"co":[["commander un plat","点一道菜"],["commander en ligne","网上订购"],["commander à emporter","点外带"],["passer commande","下单"]],"sy":[["passer commande","courant","下单，稍正式"],["réserver","courant","预订（座位、房间）"],["ordonner","soutenu","命令（指挥义）"]],"fq":"高频，餐厅、网购常用。","me":"commander：像英语 command，但更常是「点菜」。","tr":{"zh":"我们点两杯咖啡吧。","fr":"On va commander deux cafés.","alt":"On commande deux cafés ?","note":"aller + 动词原形 = 将要做。"}},
 "Couper": {"pos":"v.t. 及物动词，第一组，助动词 avoir","s":"切；剪；切断。couper le gâteau =「切蛋糕」。也有「关掉」：couper le son/le gaz；「打断」：couper la parole。","ipa":"[ku.pe]","ph":"ou [u]；p [p]；结尾 -er 读 [e]。","pi":"ou 读 [u]，嘴圆；不要读成 [kupɛʁ]，-er 读 [e]。","et":"来自 coup（一击）+ -er；coup 来自拉丁语 colpus，经 colaphus（拳击）。","ex":[["Je vais couper le gâteau.","我来切蛋糕。"],["Coupe le pain en tranches.","把面包切成片。"],["Tu peux couper le son ?","你可以关掉声音吗？"]],"co":[["couper en morceaux","切成块"],["couper la parole à qqn","打断某人说话"],["se couper le doigt","割到手指"],["couper le courant","断电"]],"sy":[["trancher","courant","切成片"],["découper","courant","切开、裁开"],["éteindre","courant","关闭（灯、电视）"]],"fq":"高频，做饭、日常常用。","me":"couper ← coup（一击）：一刀切下去。","tr":{"zh":"请把面包切成片。","fr":"Coupe le pain en tranches, s'il te plaît.","alt":"Tu peux couper le pain en tranches ?","note":"命令式 tu：coupe（不加 s）。"}},
 "Coûter": {"pos":"v.i. 不及物动词，第一组，助动词 avoir；常用第三人称 ça coûte / ils coûtent","s":"价格为；花费。Combien ça coûte ? =「这个多少钱？」。也可指「付出代价」：Ça coûte cher =「很贵」；coûte que coûte =「不惜一切代价」。","ipa":"[ku.te]","ph":"ou [u]；û 只是长音符号，读 [u]；结尾 -er 读 [e]。","pi":"拼写有 û（带帽子）；coûter 是 cost，常加副词：cher, peu。","et":"来自拉丁语 constare（价格为），英语 cost 也是它的亲戚。","ex":[["Combien coûte ce livre ?","这本书多少钱？"],["Ça coûte dix euros.","这个十欧元。"],["Ce sac coûte très cher.","这个包很贵。"]],"co":[["Combien ça coûte ?","这个多少钱？"],["coûter cher","很贵"],["coûter peu","不贵"],["coûte que coûte","不惜一切代价"]],"sy":[["valoir","courant","值（价值）"],["faire","familier","Ça fait combien ? =「多少钱？」"],["gratuit","courant","反义：免费"]],"fq":"高频，购物必备。","me":"coûter = cost，û 帽子是「钱」的屋顶。","tr":{"zh":"这件外套多少钱？","fr":"Combien coûte ce manteau ?","alt":"Il coûte combien, ce manteau ?","note":"主语是物，coûte 用第三人称。"}},
 "Cuisiner": {"pos":"v.t./v.i. 第一组动词，助动词 avoir","s":"烹饪；做饭。可不带宾语：J'aime cuisiner =「我喜欢做饭」；也可带宾语：cuisiner un plat。名词 la cuisine 指「厨房」也指「菜肴」。","ipa":"[kɥi.zi.ne]","ph":"ui 读 [ɥi]（嘴唇圆再放开）；s 在元音间读 [z]；结尾 -er 读 [e]。","pi":"ui 是半元音，不是「库伊」；s 读 [z]，不是 [s]。","et":"cuisine（拉丁语 coquina，厨房）+ -er。","ex":[["J'aime cuisiner pour mes amis.","我喜欢给朋友做饭。"],["Il cuisine très bien.","他做饭做得很好。"],["Qu'est-ce que tu cuisines ce soir ?","你今晚做什么菜？"]],"co":[["cuisiner pour qqn","为某人做饭"],["cuisiner un plat","做一道菜"],["bien cuisiner","做饭好吃"],["cuisiner au beurre / à l'huile","用黄油 / 油烹饪"]],"sy":[["faire la cuisine","courant","做饭（更常说）"],["préparer","courant","准备（饭菜）"],["cuire","courant","煮、烤（食物本身受热）"]],"fq":"中高频，日常常用。","me":"cuisiner ← cuisine：在厨房里做。","tr":{"zh":"周末我喜欢做饭。","fr":"J'aime cuisiner le week-end.","alt":"Le week-end, j'adore faire la cuisine.","note":"aimer + 动词原形；le week-end 表示每个周末。"}},
 "Finir": {"pos":"v.t./v.i. 第二组动词（nous finissons），助动词 avoir","s":"完成；结束。finir son travail =「做完工作」；Le film finit à 10 h =「电影十点结束」。finir de + 动词原形 =「做完……」；finir par + 动词原形 =「终于……、最后……」。","ipa":"[fi.niʁ]","ph":"fi [fi]；ni [ni]；结尾 r 读 [ʁ]。","pi":"nous finissons，有 -iss-；finir 的 r 要读出来；注意 finir de ≠ finir par。","et":"来自拉丁语 finire，由 finis（边界、终点）而来。","ex":[["Je dois finir mon travail.","我得完成工作。"],["Le film finit à vingt-deux heures.","电影在二十二点结束。"],["Tu as fini de manger ?","你吃完了吗？"]],"co":[["finir de + 动词原形","做完……"],["finir par + 动词原形","最终……"],["finir tard / tôt","结束得晚 / 早"],["en finir avec…","了结……"]],"sy":[["terminer","courant","结束（几乎同义，稍书面）"],["achever","soutenu","完成、做完"],["commencer","courant","反义词：开始"]],"fq":"极高频。","me":"finir ← fin：到了「终点」。","tr":{"zh":"我下午六点下班。","fr":"Je finis le travail à dix-huit heures.","alt":"Je finis à six heures du soir.","note":"finir 可不带宾语，表示「结束」。"}},
 "Grandir": {"pos":"v.i. 第二组动词（nous grandissons），助动词 avoir","s":"长大；长高；变大。通常指人、孩子的成长：Les enfants grandissent vite。也可指规模变大，如 La ville grandit。","ipa":"[ɡʁɑ̃.diʁ]","ph":"gr [ɡʁ]；an 鼻化 [ɑ̃]；结尾 r 读 [ʁ]。","pi":"an 是鼻化元音 [ɑ̃]，不发 n；nous grandissons 有 -iss-。","et":"grand（拉丁语 grandis）+ -ir。","ex":[["Les enfants grandissent vite.","孩子们长得很快。"],["Tu as bien grandi !","你长高了好多！"],["J'ai grandi à la campagne.","我在乡下长大。"]],"co":[["grandir vite","长得快"],["grandir en âge","年龄渐长"],["avoir grandi","已长大"],["grandir à la campagne","在乡下长大"]],"sy":[["pousser","courant","（植物）生长"],["croître","soutenu","增长、成长"],["rapetisser","courant","反义词：变小"]],"fq":"中频。","me":"grandir ← grand：变「大」。","tr":{"zh":"我的孩子长得很快。","fr":"Mon enfant grandit très vite.","alt":"Mon fils grandit vraiment vite.","note":"grandir 不及物，后面不加宾语。"}},
 "Grossir": {"pos":"v.i. 第二组动词（nous grossissons），助动词 avoir","s":"变胖；发福；体重增加。反义词 maigrir（变瘦）。不要和 grossier（粗鲁的）混淆。也可指「扩大」：La rumeur grossit。","ipa":"[ɡʁo.siʁ]","ph":"gr [ɡʁ]；o [o]；ss 读 [s]；结尾 r 读 [ʁ]。","pi":"gros 里 s 不发音，但 grossir 里 ss 要发 [s]；nous grossissons。","et":"gros（晚期拉丁语 grossus，粗、厚）+ -ir。","ex":[["Je ne veux pas grossir.","我不想变胖。"],["Il a grossi pendant l'hiver.","他冬天胖了。"],["Les gâteaux font grossir.","蛋糕让人发胖。"]],"co":[["faire grossir","使人发胖"],["grossir de trois kilos","胖了三公斤"],["craindre de grossir","怕胖"],["ne pas grossir","不长胖"]],"sy":[["prendre du poids","courant","增重，更中性"],["engraisser","soutenu","长胖、养肥"],["maigrir","courant","反义词：变瘦"]],"fq":"中频，饮食、健康话题。","me":"grossir ← gros：变「粗」了。","tr":{"zh":"我吃太多甜食会变胖。","fr":"Je grossis si je mange trop de sucre.","alt":"Si je mange trop de sucre, je grossis.","note":"si + 现在时，结果用现在时。"}},
 "Inviter": {"pos":"v.t. 及物动词，第一组，助动词 avoir","s":"邀请。inviter qqn à + 名词 / 动词原形：邀请某人参加或做某事。Je t'invite. 也常用来表示「我请客」。","ipa":"[ɛ̃.vi.te]","ph":"in 鼻化 [ɛ̃]；v [v]；结尾 -er 读 [e]。","pi":"in 是鼻化元音 [ɛ̃]，不发 n；和 envoyer 的 en 不同。","et":"来自拉丁语 invitare（邀请）。","ex":[["Je vais inviter mes parents à dîner.","我要邀请父母来吃晚饭。"],["Je t'invite au restaurant.","我请你去餐厅（我请客）。"],["Elle m'a invité à sa fête.","她邀请我参加她的派对。"]],"co":[["inviter qqn à dîner","邀请某人吃晚饭"],["inviter qqn chez soi","邀请某人到家里"],["Je t'invite.","我请客。"],["être invité","被邀请"]],"sy":[["convier","soutenu","邀请，更正式"],["offrir","courant","请（客）、送"],["accepter","courant","接受邀请"]],"fq":"高频，社交场合常用。","me":"inviter ≈ invite：同形同义。","tr":{"zh":"我想请你周六来吃饭。","fr":"Je voudrais t'inviter à dîner samedi.","alt":"Je t'invite à dîner samedi, si tu veux.","note":"inviter qqn à + 动词原形。"}},
 "Mettre": {"pos":"v.t. 不规则动词，助动词 avoir（je mets, nous mettons, ils mettent；过去分词 mis）","s":"放；摆；穿上。mettre le couvert / la table =「摆桌子」；mettre un pull =「穿毛衣」；mettre du sucre =「放糖」。se mettre à + 动词原形 =「开始做……」。","ipa":"[mɛtʁ]","ph":"e 读 [ɛ]；tt 读单个 [t]；tre 的 r 不能丢，读 [tʁ]。","pi":"mets 读 [mɛ]，s/t 不发音；mettons 读出 t；过去分词 mis [mi]。","et":"来自拉丁语 mittere（派出、投）。","ex":[["Je mets la table.","我摆桌子。"],["Il met un manteau noir.","他穿一件黑大衣。"],["Mets du sel dans l'eau.","往水里放盐。"]],"co":[["mettre la table","摆桌子"],["mettre un vêtement","穿衣服"],["se mettre à + 动词原形","开始……"],["mettre du temps","花时间"]],"sy":[["poser","courant","放（平放）"],["placer","courant","安置、放置"],["enlever","courant","反义：脱下、拿掉"]],"fq":"极高频，必学。","me":"mettre = put：放、穿、摆都是它。","tr":{"zh":"天冷，穿上外套。","fr":"Il fait froid, mets ton manteau.","alt":"Mets ton manteau, il fait froid.","note":"命令式 tu：mets（带 s）。"}},
 "Partager": {"pos":"v.t. 及物动词，第一组，助动词 avoir（nous partageons，g 后加 e）","s":"分享；分担；分摊。partager l'addition =「分摊账单」；partager un gâteau =「分蛋糕」。也有「共同拥有」：partager une chambre。","ipa":"[paʁ.ta.ʒe]","ph":"ar [aʁ]；g 在 e/a 前读 [ʒ]；结尾 -er 读 [e]。","pi":"nous partageons 要加 e 保持 [ʒ]；别写成 partagons。","et":"part（拉丁语 pars，一部分）+ -ager（来自 partage）。","ex":[["On va partager l'addition.","我们来分摊账单。"],["Je partage un appartement avec ma sœur.","我和姐姐合租一间公寓。"],["Elle partage son gâteau.","她分享自己的蛋糕。"]],"co":[["partager l'addition","分摊账单"],["partager un repas","共进一餐"],["partager avec qqn","和某人分享"],["partager un avis","有同样看法"]],"sy":[["diviser","courant","分开、平分"],["répartir","soutenu","分配"],["garder","courant","反义：保留"]],"fq":"中高频，日常常用。","me":"partager = part（一份）+ ager：每人一份。","tr":{"zh":"我们分着吃这个甜点吧。","fr":"On partage ce dessert ?","alt":"On va partager ce dessert.","note":"on partage ? 用语调提问，很口语。"}},
 "Payer (par carte, en espèces, en liquide)": {"pos":"v.t./v.i. 第一组动词，助动词 avoir（je paie 或 je paye 都可以）","s":"付款；付钱。payer par carte =「刷卡」；payer en espèces / en liquide =「付现金」。payer qqch (pour qqn)：付某物的钱。payer un café à qqn =「请某人喝咖啡」。","ipa":"[pe.je]","ph":"pay 读 [pe.j]；结尾 -er 读 [e]；变位 paie 读 [pɛ]，nous payons 读 [pe.jɔ̃]。","pi":"ay 读 [ej]，不是「派」；espèces 里 s 读 [s]，结尾 -es 不发音。","et":"来自拉丁语 pacare（使平息、使债主满意），源自 pax（和平）。","ex":[["Je peux payer par carte ?","我可以刷卡吗？"],["Je paie en espèces.","我付现金。"],["C'est moi qui paie le café.","咖啡我来付。"]],"co":[["payer par carte","刷卡付款"],["payer en espèces","付现金"],["payer en liquide","付现金（口语）"],["payer l'addition","付账"]],"sy":[["régler","courant","结账（在餐厅常说 Je règle）"],["rembourser","courant","还钱、退款"],["offrir","courant","请客（送）"]],"fq":"极高频，购物必备。","me":"payer ← pax：付了钱就「和平」了。","tr":{"zh":"我可以用现金付款吗？","fr":"Je peux payer en espèces ?","alt":"Je peux payer en liquide ?","note":"payer par carte / en espèces：介词不同。"}},
 "Préparer": {"pos":"v.t. 及物动词，第一组，助动词 avoir；se préparer = 准备好自己","s":"准备；筹备；做（饭菜）。préparer le repas =「准备饭菜」；préparer un examen =「备考」。se préparer à + 动词原形 =「准备要……」。","ipa":"[pʁe.pa.ʁe]","ph":"pr [pʁ]；é [e]；pa [pa]；r [ʁ]；结尾 -er 读 [e]。","pi":"第一个 é 有重音符号；两个 r 都是小舌音 [ʁ]；不要读成 prepare 的英语音。","et":"来自拉丁语 praeparare（预先准备），由 prae-（先）+ parare 而来。","ex":[["Je prépare le repas.","我准备饭菜。"],["Elle prépare son voyage.","她在筹备旅行。"],["Il prépare un examen difficile.","他在备考一场难考试。"]],"co":[["préparer le dîner","准备晚饭"],["préparer un examen","备考"],["se préparer à + 动词原形","准备做……"],["préparer sa valise","收拾行李"]],"sy":[["cuisiner","courant","做饭"],["organiser","courant","组织、安排"],["apprêter","soutenu","把……备好"]],"fq":"极高频。","me":"préparer = prepare：同形，多了 é。","tr":{"zh":"我在准备晚饭。","fr":"Je prépare le dîner.","alt":"Je suis en train de préparer le dîner.","note":"être en train de + 动词原形 = 正在做。"}},
 "Vouloir": {"pos":"v.t. 不规则动词，助动词 avoir（je veux, tu veux, il veut, nous voulons, ils veulent；过去分词 voulu）","s":"想要；愿意。vouloir + 名词 / 动词原形。Je veux un café 较直接，点菜用 je voudrais 更礼貌。vouloir dire =「意思是」。","ipa":"[vu.lwaʁ]","ph":"ou [u]；oi [wa]；结尾 r 读 [ʁ]。变位 veux 读 [vø]，s/x 不发音。","pi":"veux 读 [vø]，不是 [vu]；nous voulons 词干变；veulent 读 [vœl]。","et":"来自通俗拉丁语 volere（想要），与英语 voluntary 同源。","ex":[["Je veux apprendre le français.","我想学法语。"],["Tu veux du thé ?","你要茶吗？"],["Qu'est-ce que ça veut dire ?","这是什么意思？"]],"co":[["vouloir + 动词原形","想做……"],["vouloir dire","意思是"],["Tu veux… ?","你要……吗？（询问）"],["bien vouloir","愿意、请"]],"sy":[["désirer","soutenu","渴望"],["avoir envie de","courant","想要、有……的欲望"],["souhaiter","soutenu","希望"]],"fq":"极高频，必学。","me":"veux / veut：读 [vø]，像「喔」。","tr":{"zh":"你想要什么？","fr":"Qu'est-ce que tu veux ?","alt":"Tu veux quoi ?","note":"tu veux：veux 的 x 不读。"}},
 "Antillais(e)": {"pos":"adj. 形容词，阴性 antillaise；复数 antillais / antillaises；也可作名词","s":"安的列斯的；与加勒比法属岛屿（瓜德罗普、马提尼克等）有关的。la cuisine antillaise =「安的列斯菜」。作名词时首字母大写：un Antillais。","ipa":"[ɑ̃.ti.jɛ] / [ɑ̃.ti.jɛz]","ph":"an 鼻化 [ɑ̃]；ill 读 [j]；阳性 -ais 读 [ɛ]，阴性 -aise 读 [ɛz]。","pi":"ill 在这里读 [j]；阳性词尾 s 不发音，阴性要读 [z]。","et":"Antilles（加勒比群岛）+ -ais。Antilles 来自中世纪地图上的传说岛 Antilia。","ex":[["La cuisine antillaise est bonne.","安的列斯菜很好吃。"],["C'est un chanteur antillais.","他是一位安的列斯歌手。"]],"co":[["la cuisine antillaise","安的列斯菜"],["un Antillais / une Antillaise","安的列斯人"],["la musique antillaise","安的列斯音乐"]],"sy":[["caribéen","courant","加勒比的，范围更广"],["créole","courant","克里奥尔的（语言、菜）"]],"fq":"低中频，地理、文化话题。","me":"Antilles + -aise：小岛上的人和菜。","tr":{"zh":"我喜欢安的列斯的音乐。","fr":"J'aime la musique antillaise.","alt":"J'adore la musique des Antilles.","note":"形容词跟阴性 musique：antillaise。"}},
 "Argentin(e)": {"pos":"adj. 形容词，阴性 argentine；复数 argentins / argentines；也可作名词","s":"阿根廷的；阿根廷人。Il est argentin =「他是阿根廷人」。作名词时首字母大写：un Argentin。国名是 l'Argentine。","ipa":"[aʁ.ʒɑ̃.tɛ̃] / [aʁ.ʒɑ̃.tin]","ph":"ar [aʁ]；g 在 e 前读 [ʒ]；en 读鼻化 [ɑ̃]；阳性 -in 读 [ɛ̃]，阴性 -ine 读 [in]。","pi":"阳性 argentin 结尾是鼻音 [ɛ̃]，阴性 argentine 是 [in]，两者不同。","et":"Argentine（拉丁语 argentum，银）+ -in。国名来自银（Río de la Plata「银河」）。","ex":[["Il est argentin.","他是阿根廷人。"],["Elle est argentine et elle parle espagnol.","她是阿根廷人，说西班牙语。"]],"co":[["un joueur argentin","阿根廷球员"],["le tango argentin","阿根廷探戈"],["la viande argentine","阿根廷牛肉"]],"sy":[["sud-américain","courant","南美的，范围更广"]],"fq":"中频，国籍话题。","me":"argent（银）→ Argentine：「银」之国。","tr":{"zh":"我的朋友是阿根廷人。","fr":"Mon ami est argentin.","alt":"Mon copain est argentin.","note":"国籍形容词小写，不加冠词。"}},
 "Brésilien(ne)": {"pos":"adj. 形容词，阴性 brésilienne；复数 brésiliens / brésiliennes；也可作名词","s":"巴西的；巴西人。Il parle portugais brésilien =「他说巴西葡萄牙语」。国名是 le Brésil（阳性）。","ipa":"[bʁe.zi.ljɛ̃] / [bʁe.zi.ljɛn]","ph":"é [e]；s 在元音间读 [z]；-ien 读 [jɛ̃]，阴性 -ienne 读 [jɛn]。","pi":"s 读 [z]；阳性结尾鼻音 [jɛ̃]，阴性是 [jɛn]，nn 只读一个 n。","et":"Brésil + -ien。国名来自 brésil（巴西红木），16 世纪欧洲人先知道这种木头。","ex":[["Il parle portugais brésilien.","他说巴西葡萄牙语。"],["Elle est brésilienne.","她是巴西人。"]],"co":[["le café brésilien","巴西咖啡"],["le football brésilien","巴西足球"],["un Brésilien / une Brésilienne","巴西人"]],"sy":[["sud-américain","courant","南美的，范围更广"]],"fq":"中频，国籍话题。","me":"Brésil + -ien：é 有重音，s 读 [z]。","tr":{"zh":"我邻居是巴西人。","fr":"Mon voisin est brésilien.","alt":"Mon voisin, c'est un Brésilien.","note":"名词用大写：un Brésilien；形容词用小写。"}},
 "Cher / Chère": {"pos":"adj. 形容词，阴性 chère；复数 chers / chères","s":"贵的（价格高）；亲爱的（放名词前）。Ce sac est cher =「这个包很贵」（放在名词后）；mon cher ami =「我亲爱的朋友」（放名词前）；Cher Paul, … 用于信的开头。","ipa":"[ʃɛʁ]","ph":"ch [ʃ]；è/e 读 [ɛ]；结尾 r 读 [ʁ]，阳性阴性读音相同。","pi":"阳性 cher 的 r 要读（和 -er 动词不同）；阴性 chère 多一个 è。","et":"来自拉丁语 carus（亲爱的；贵重的）。","ex":[["Ce sac est très cher.","这个包很贵。"],["Cher Paul, merci pour ta lettre.","亲爱的保罗，谢谢你的信。"],["La vie est chère à Paris.","巴黎生活费很高。"]],"co":[["coûter cher","价格昂贵"],["trop cher","太贵"],["Cher / Chère + 名字","亲爱的……（信的开头）"],["pas cher","便宜"]],"sy":[["coûteux","soutenu","昂贵的"],["bon marché","courant","反义：便宜"],["pas cher","courant","不贵"]],"fq":"极高频，购物必备。","me":"cher：贵也亲爱，都「很看重」。","tr":{"zh":"这家餐厅太贵了。","fr":"Ce restaurant est trop cher.","alt":"Ce resto est vraiment trop cher.","note":"cher 随名词性数变化：la vie est chère。"}},
 "Chinois(e)": {"pos":"adj. 形容词，阴性 chinoise；复数 chinois / chinoises；也可作名词（语言 le chinois）","s":"中国的；中文；中国人。le chinois =「中文」（语言，小写）；un Chinois =「中国人」（大写）。J'apprends le chinois。","ipa":"[ʃi.nwa] / [ʃi.nwaz]","ph":"ch [ʃ]；-ois 读 [wa]，阴性 -oise 读 [waz]。","pi":"ch 读 [ʃ]，不是「奇」；阳性结尾 -ois 读 [wa]，s 不发音；阴性读 [z]。","et":"Chine + -ois。Chine 来自梵语/波斯语对「秦」的称呼，经欧洲语言传入。","ex":[["J'apprends le chinois.","我在学中文。"],["La cuisine chinoise est délicieuse.","中国菜很好吃。"],["Il est chinois.","他是中国人。"]],"co":[["parler chinois","说中文"],["la cuisine chinoise","中国菜"],["le nouvel an chinois","春节"],["un restaurant chinois","中餐馆"]],"sy":[["mandarin","courant","普通话（指语言）"],["asiatique","courant","亚洲的，范围更广"]],"fq":"高频，语言、国籍话题。","me":"chinois：ch = [ʃ]，nois = [nwa]。","tr":{"zh":"我在学中文。","fr":"J'apprends le chinois.","alt":"Je suis en train d'apprendre le chinois.","note":"语言前用 le，小写：le chinois。"}},
 "Coréen(ne)": {"pos":"adj. 形容词，阴性 coréenne；复数 coréens / coréennes；也可作名词","s":"韩国的；韩语；韩国人。Le cinéma coréen est super =「韩国电影很棒」。国名 la Corée；le coréen =「韩语」。","ipa":"[kɔ.ʁe.ɛ̃] / [kɔ.ʁe.ɛn]","ph":"o 开口 [ɔ]；é [e]；en 在阳性读 [ɛ̃]，阴性 -enne 读 [ɛn]。","pi":"é 和 en 要分开读 [e.ɛ̃]；阴性 nn 只读一个 n。","et":"Corée + -en。Corée 来自朝鲜古国「高丽」(Koryŏ)。","ex":[["Le cinéma coréen est super.","韩国电影很棒。"],["Elle apprend le coréen.","她在学韩语。"]],"co":[["la cuisine coréenne","韩国菜"],["un film coréen","韩国电影"],["parler coréen","说韩语"]],"sy":[["asiatique","courant","亚洲的，范围更广"]],"fq":"中频，文化话题。","me":"Corée → coréen：é 在中间。","tr":{"zh":"我爱看韩国电影。","fr":"J'adore les films coréens.","alt":"J'aime beaucoup le cinéma coréen.","note":"films 复数，coréens 也加 s。"}},
 "Délicieux / Délicieuse": {"pos":"adj. 形容词，阴性 délicieuse；复数 délicieux / délicieuses","s":"美味的；令人愉悦的。Ce gâteau est délicieux =「这个蛋糕很好吃」。比 bon 更强，是「非常好吃」。也可形容香味、时光。","ipa":"[de.li.sjø] / [de.li.sjøz]","ph":"é [e]；c 在 i 前读 [s]；-ieux 读 [sjø]，阴性 -ieuse 读 [sjøz]。","pi":"c 读 [s]；阳性 x 不发音，阴性 -se 读 [z]。","et":"来自拉丁语 deliciosus，由 deliciae（乐趣、美味）而来。","ex":[["Ce gâteau est délicieux.","这个蛋糕很好吃。"],["La soupe est délicieuse.","汤很好喝。"],["Quel plat délicieux !","多好吃的菜！"]],"co":[["un plat délicieux","美味的一道菜"],["délicieux à manger","好吃"],["C'est délicieux !","真好吃！"],["une odeur délicieuse","好闻的香气"]],"sy":[["très bon","courant","很好吃"],["succulent","soutenu","多汁美味的"],["dégueulasse","familier","反义：很难吃"]],"fq":"高频，饮食话题。","me":"délicieux ≈ delicious：同形，c 读 [s]。","tr":{"zh":"这道菜真好吃！","fr":"Ce plat est délicieux !","alt":"Ce plat est trop bon !","note":"形容词随名词性别变化：délicieuse。"}},
 "Épicé(e)": {"pos":"adj. 形容词，阴性 épicée；复数 épicés / épicées","s":"辣的；加了香料的。épicé 指有香料味，不一定「辣椒辣」；真正很辣用 piquant 或 fort。J'aime manger épicé =「我喜欢吃辣口的」。","ipa":"[e.pi.se]","ph":"é [e]；c 在 e 前读 [s]；结尾 é 读 [e]；阴性 épicée 读音相同。","pi":"c 读 [s]；阳性阴性读音一样，只在书写上区分（épicé / épicée）。","et":"épice（拉丁语 species，货品、香料）+ -é。","ex":[["J'aime manger épicé.","我喜欢吃辣。"],["La sauce est trop épicée.","酱太辣了。"],["C'est un plat très épicé.","这是一道很辣的菜。"]],"co":[["un plat épicé","辣味菜"],["trop épicé","太辣"],["manger épicé","吃辣"],["peu épicé","不太辣"]],"sy":[["piquant","courant","辣（刺激口舌）"],["fort","courant","味道重、辣"],["doux","courant","反义：清淡、不辣"]],"fq":"中频，饮食话题。","me":"épice（香料）+ -é：加了香料的。","tr":{"zh":"这道菜太辣了，我吃不了。","fr":"Ce plat est trop épicé pour moi.","alt":"C'est trop épicé, je ne peux pas manger ça.","note":"trop … pour moi = 对我来说太……"}},
 "Espagnol(e)": {"pos":"adj. 形容词，阴性 espagnole；复数 espagnols / espagnoles；也可作名词（语言 l'espagnol）","s":"西班牙的；西班牙语；西班牙人。Je parle espagnol =「我说西班牙语」。国名是 l'Espagne。","ipa":"[ɛs.pa.ɲɔl]","ph":"es [ɛs]；gn 读 [ɲ]（像「尼」）；o 开口 [ɔ]；阳性阴性读音相同。","pi":"gn 读 [ɲ]，不是 [ɡn]；阳性阴性读音一样。","et":"Espagne + -ol（来自拉丁语 Hispaniolus，「西班牙的」）。","ex":[["Je parle espagnol.","我说西班牙语。"],["Elle est espagnole.","她是西班牙人。"]],"co":[["parler espagnol","说西班牙语"],["la cuisine espagnole","西班牙菜"],["un Espagnol / une Espagnole","西班牙人"]],"sy":[["hispanique","soutenu","西语系的"],["castillan","soutenu","卡斯蒂利亚语（西语的正式名称）"]],"fq":"高频，语言、国籍话题。","me":"Espagne + -ol：gn 读「尼」。","tr":{"zh":"我的邻居说西班牙语。","fr":"Mon voisin parle espagnol.","alt":"Mon voisin, il parle espagnol.","note":"parler + 语言，不加冠词。"}},
 "Gras / Grasse": {"pos":"adj. 形容词，阴性 grasse；复数 gras / grasses","s":"油腻的；肥的；含脂肪多的。La viande est trop grasse =「肉太肥了」。名词 le gras =「脂肪」。faire la grasse matinée =「睡懒觉」。","ipa":"[ɡʁɑ] / [ɡʁɑs]","ph":"gr [ɡʁ]；a 读长音 [ɑ]；阳性 s 不发音，阴性 -sse 读 [s]。","pi":"gras 的 s 不发音，grasse 的 ss 要发 [s]；很容易读错。","et":"来自拉丁语 crassus（厚的、肥的）。","ex":[["La viande est trop grasse.","肉太肥了。"],["Je n'aime pas les aliments gras.","我不喜欢油腻的食物。"],["Il a fait la grasse matinée.","他睡了个懒觉。"]],"co":[["trop gras","太油腻"],["faire la grasse matinée","睡懒觉"],["matières grasses","脂肪"],["des aliments gras","高脂肪食品"]],"sy":[["gros","courant","胖的（人）"],["huileux","courant","油腻的，沾油的"],["maigre","courant","反义：瘦的、低脂的"]],"fq":"中频，饮食、健康话题。","me":"gras 读 [ɡʁɑ]；grasse 多一个 s 音。","tr":{"zh":"这块肉太肥了。","fr":"Cette viande est trop grasse.","alt":"Cette viande, c'est trop gras.","note":"viande 阴性，所以 grasse。"}},
 "Grec(que)": {"pos":"adj. 形容词，阴性 grecque；复数 grecs / grecques；也可作名词","s":"希腊的；希腊语；希腊人。une salade grecque =「希腊沙拉」；le grec =「希腊语」。国名是 la Grèce。","ipa":"[ɡʁɛk] / [ɡʁɛk]","ph":"gr [ɡʁ]；e 读 [ɛ]；c/cque 读 [k]；阳性阴性读音相同。","pi":"阴性 grecque 写 -cque，读音和阳性一样；不要读成 [ɡʁɛs]。","et":"来自拉丁语 Graecus（希腊人）。","ex":[["Une salade grecque, s'il vous plaît.","请给我一份希腊沙拉。"],["Elle est grecque.","她是希腊人。"]],"co":[["une salade grecque","希腊沙拉"],["le yaourt grec","希腊酸奶"],["la mythologie grecque","希腊神话"],["parler grec","说希腊语"]],"sy":[["hellénique","littéraire","希腊的，较书面"]],"fq":"中频，饮食、国籍话题。","me":"grec / grecque：读音相同，只是拼写变。","tr":{"zh":"我想要一份希腊沙拉。","fr":"Je voudrais une salade grecque.","alt":"Je prends une salade grecque.","note":"salade 阴性，所以 grecque。"}},
 "Indien(ne)": {"pos":"adj. 形容词，阴性 indienne；复数 indiens / indiennes；也可作名词","s":"印度的；印度人。le thé indien =「印度茶」；un Indien =「印度人」。国名是 l'Inde。注意：les Indiens 有时也指美洲原住民。","ipa":"[ɛ̃.djɛ̃] / [ɛ̃.djɛn]","ph":"in 鼻化 [ɛ̃]；-ien 读 [djɛ̃]，阴性 -ienne 读 [djɛn]。","pi":"两个鼻音连着：[ɛ̃.djɛ̃]；阴性 nn 读一个 n。","et":"Inde + -ien。Inde 来自希腊语/拉丁语 India，源于印度河 (Indus)。","ex":[["Le thé indien est bon.","印度茶很好喝。"],["Elle est indienne.","她是印度人。"]],"co":[["la cuisine indienne","印度菜"],["un restaurant indien","印度餐馆"],["le thé indien","印度茶"]],"sy":[["asiatique","courant","亚洲的，范围更广"]],"fq":"中频，国籍、饮食话题。","me":"Inde → indien：开头 in 是鼻音。","tr":{"zh":"我爱吃印度菜。","fr":"J'adore la cuisine indienne.","alt":"J'aime beaucoup manger indien.","note":"cuisine 阴性，所以 indienne。"}},
 "Italien(ne)": {"pos":"adj. 形容词，阴性 italienne；复数 italiens / italiennes；也可作名词（语言 l'italien）","s":"意大利的；意大利语；意大利人。J'adore la cuisine italienne =「我爱意大利菜」。国名是 l'Italie。","ipa":"[i.ta.ljɛ̃] / [i.ta.ljɛn]","ph":"i [i]；ta [ta]；-lien 读 [ljɛ̃]，阴性 -lienne 读 [ljɛn]。","pi":"开头 i 要读 [i]，不是 [ɛ̃]；阴性 nn 读一个 n。","et":"Italie + -ien。Italie 来自拉丁语 Italia。","ex":[["J'adore la cuisine italienne.","我喜欢意大利菜。"],["Il parle italien.","他说意大利语。"]],"co":[["la cuisine italienne","意大利菜"],["un restaurant italien","意大利餐馆"],["parler italien","说意大利语"]],"sy":[["transalpin","soutenu","阿尔卑斯山那边的（指意大利）"]],"fq":"高频，饮食、国籍话题。","me":"Italie + -ien：开头两个元音 i-ta。","tr":{"zh":"我们去一家意大利餐馆吧。","fr":"On va dans un restaurant italien.","alt":"Allons dans un resto italien !","note":"restaurant 阳性，所以 italien。"}},
 "Ivoirien(ne)": {"pos":"adj. 形容词，阴性 ivoirienne；复数 ivoiriens / ivoiriennes；也可作名词","s":"科特迪瓦的；科特迪瓦人。Elle est ivoirienne =「她是科特迪瓦人」。国名是 la Côte d'Ivoire，字面「象牙海岸」。","ipa":"[i.vwa.ʁjɛ̃] / [i.vwa.ʁjɛn]","ph":"i [i]；oi [wa]；r [ʁ]；-ien 读 [jɛ̃]，阴性 -ienne 读 [jɛn]。","pi":"oi 读 [wa]；r 和 i 连读 [ʁj]；阴性 nn 读一个 n。","et":"ivoire（象牙）+ -ien。ivoire 来自拉丁语 eboreus（象牙的）。","ex":[["Elle est ivoirienne.","她是科特迪瓦人。"],["Le football ivoirien est connu.","科特迪瓦足球很有名。"]],"co":[["la cuisine ivoirienne","科特迪瓦菜"],["un Ivoirien / une Ivoirienne","科特迪瓦人"],["la Côte d'Ivoire","科特迪瓦"]],"sy":[["africain","courant","非洲的，范围更广"]],"fq":"低中频，国籍话题。","me":"ivoire（象牙）→ ivoirien：象牙海岸的人。","tr":{"zh":"我的同事是科特迪瓦人。","fr":"Mon collègue est ivoirien.","alt":"Mon collègue vient de Côte d'Ivoire.","note":"venir de + 国名 = 来自某国。"}},
 "Marocain(e)": {"pos":"adj. 形容词，阴性 marocaine；复数 marocains / marocaines；也可作名词","s":"摩洛哥的；摩洛哥人。Le couscous est marocain =「库斯库斯是摩洛哥的」（也流行于阿尔及利亚、突尼斯）。国名是 le Maroc。","ipa":"[ma.ʁɔ.kɛ̃] / [ma.ʁɔ.kɛn]","ph":"ma [ma]；ro 开口 [ʁɔ]；c [k]；阳性 -ain 读 [ɛ̃]，阴性 -aine 读 [ɛn]。","pi":"阳性 -ain 是鼻音 [ɛ̃]，阴性 -aine 是 [ɛn]。","et":"Maroc + -ain。Maroc 来自马拉喀什 (Marrakech) 城名。","ex":[["Le couscous est marocain.","库斯库斯是摩洛哥的。"],["Elle aime le thé marocain.","她爱喝摩洛哥茶。"]],"co":[["la cuisine marocaine","摩洛哥菜"],["le thé marocain","摩洛哥薄荷茶"],["un Marocain / une Marocaine","摩洛哥人"]],"sy":[["maghrébin","courant","马格里布地区的"]],"fq":"中频，饮食、国籍话题。","me":"Maroc → marocain：开头 ma-ro。","tr":{"zh":"我喜欢摩洛哥茶。","fr":"J'aime le thé marocain.","alt":"J'adore le thé à la menthe marocain.","note":"thé 阳性，所以 marocain。"}},
 "Mauvais(e)": {"pos":"adj. 形容词，阴性 mauvaise；复数 mauvais / mauvaises","s":"坏的；差的；不好的。Ce film est mauvais =「这部电影很烂」。放名词前：un mauvais film（糟糕的电影）。反义词是 bon。","ipa":"[mo.vɛ] / [mo.vɛz]","ph":"au 读 [o]；v [v]；阳性 -ais 读 [ɛ]，阴性 -aise 读 [ɛz]。","pi":"阳性 s 不发音，阴性 -aise 读 [z]；au 读 [o]，不是「奥」。","et":"古法语 malvais，与 mal（坏）有关；确切来源不太确定。","ex":[["Ce film est mauvais.","这部电影很烂。"],["Il fait mauvais aujourd'hui.","今天天气不好。"],["C'est une mauvaise idée.","这是个坏主意。"]],"co":[["un mauvais film","烂电影"],["il fait mauvais","天气不好"],["de mauvaise humeur","心情不好"],["mauvais en maths","数学很差"]],"sy":[["nul","familier","很烂、一无是处"],["médiocre","soutenu","平庸的"],["bon","courant","反义词：好"]],"fq":"极高频。","me":"mauvais = 「mal」的形容词。","tr":{"zh":"这是个坏主意。","fr":"C'est une mauvaise idée.","alt":"Ce n'est pas une bonne idée.","note":"idée 阴性，所以用 mauvaise。"}},
 "Pas mal": {"pos":"adj. 形容词（固定说法，不变化）","s":"不错；还可以。字面是「不坏」，口语里表示称赞：Ce restaurant est pas mal =「这家餐厅还不错」。注意：pas mal de + 名词 =「相当多的……」。","ipa":"[pa mal]","ph":"pas 的 s 不发音，读 [pa]；mal 读 [mal]，l 要发音。","pi":"pas 的 s 不读；mal 的 l 要读。不能写成 pas male。","et":"pas（否定词）+ mal（坏），字面「不坏」，是一种含蓄的赞扬。","ex":[["Ce restaurant est pas mal.","这家餐厅还不错。"],["Ça va ? Pas mal, merci.","还好吗？还不错，谢谢。"],["Il y a pas mal de monde.","有不少人。"]],"co":[["pas mal du tout","相当不错"],["pas mal de + 名词","不少的……"],["C'est pas mal !","还不错！"],["Pas mal, non ?","不赖吧？"]],"sy":[["bien","courant","好"],["correct","courant","还可以、说得过去"],["super","familier","太棒了"]],"fq":"极高频，口语常用。","me":"pas mal = 「不坏」= 其实挺好。","tr":{"zh":"这家咖啡馆还不错。","fr":"Ce café n'est pas mal.","alt":"Ce café, c'est pas mal.","note":"口语常省略 ne：c'est pas mal。"}},
 "Péruvien(ne)": {"pos":"adj. 形容词，阴性 péruvienne，复数 péruviens / péruviennes","s":"秘鲁的；秘鲁人的。可修饰人或物：un plat péruvien（秘鲁菜）。作名词指人时首字母大写：un Péruvien, une Péruvienne。","ipa":"[pe.ʁy.vjɛ̃]","ph":"é [e]；u [y]；-ien [jɛ̃]。阴性 péruvienne 读 [pe.ʁy.vjɛn]，n 要发出来。","pi":"阳性结尾是鼻音 [jɛ̃]，不发 n；阴性才发 [n]。作形容词时不大写（péruvien），作人称名词才大写。","et":"由国名 Pérou 加后缀 -ien 构成（和 italien, brésilien 一样）。","ex":[["Le ceviche est péruvien.","酸橘汁腌鱼是秘鲁的。"],["Elle est péruvienne, elle vient de Lima.","她是秘鲁人，来自利马。"],["J'adore la cuisine péruvienne.","我很爱秘鲁菜。"]],"co":[["la cuisine péruvienne","秘鲁菜"],["un plat péruvien","一道秘鲁菜"],["les Péruviens","秘鲁人（复数）"]],"sy":[["du Pérou","courant","来自秘鲁（更口语的说法）"],["andin","courant","安第斯的（地区，不等于秘鲁）"]],"fq":"中频，谈国家、美食时常用。","me":"Pérou + -ien：国名后面加 -ien，阴性多一个 n。","tr":{"zh":"我的朋友是秘鲁人。","fr":"Mon ami est péruvien.","alt":"Mon copain vient du Pérou.","note":"国籍用 être + 形容词，不加冠词；阴性加 -ne。"}},
 "Salé(e)": {"pos":"adj. 形容词，阴性 salée，复数 salés / salées；也可作阳性名词 le salé","s":"咸的；加了盐的。le salé 指「咸口的食物」，和 le sucré（甜食）相对。口语里 une addition salée 还表示「账单很贵」。","ipa":"[sa.le]","ph":"s [s]；a [a]；é [e]。阴性 salée 读音相同。","pi":"词尾 -é 读 [e]，t 之类的字母不发音。salé（咸）和 sucré（甜）别搞混；salé 来自 sel（盐），所以和 sale（脏）只差一个重音符号：sale [sal] 是「脏的」！","et":"来自 sel（盐），拉丁语 sal；salé 是过去分词做形容词（saler = 加盐）。","ex":[["C'est trop salé.","太咸了。"],["Tu préfères le salé ou le sucré ?","你喜欢咸的还是甜的？"],["L'addition est salée !","账单好贵！"]],"co":[["trop salé","太咸"],["le salé et le sucré","咸的和甜的食物"],["une eau salée","咸水（海水）"],["une addition salée","很贵的账单"]],"sy":[["sucré","courant","甜的（反义）"],["cher","courant","贵的（口语里 salé 的另一层意思）"]],"fq":"高频，谈食物时常用。","me":"sel（盐）→ salé。有重音 é 是咸，没有就是脏（sale）。","tr":{"zh":"这汤太咸了。","fr":"Cette soupe est trop salée.","alt":"Elle est vraiment trop salée, cette soupe.","note":"形容词和名词性别一致：la soupe → salée。"}},
 "Sénégalais(e)": {"pos":"adj. 形容词，阴性 sénégalaise，复数 sénégalais / sénégalaises","s":"塞内加尔的；塞内加尔人的。阳性单数和复数写法相同（sénégalais），阴性才加 -e：sénégalaise。","ipa":"[se.ne.ga.lɛ]","ph":"é [e]；n [n]；g [g]；-ais 读 [ɛ]，词尾 s 不发音。阴性 sénégalaise 读 [se.ne.ga.lɛz]，s 变成 [z]。","pi":"阳性词尾 -ais 里的 s 不发音；阴性 -aise 的 s 要读 [z]。g 在 a 前读 [g]，不是 [ʒ]。","et":"国名 Sénégal 加后缀 -ais（和 français, japonais 一样）。","ex":[["C'est un plat sénégalais.","这是一道塞内加尔菜。"],["Elle est sénégalaise.","她是塞内加尔人。"],["J'ai goûté du thieboudienne, un plat sénégalais.","我尝过 thieboudienne，一道塞内加尔菜。"]],"co":[["un plat sénégalais","一道塞内加尔菜"],["la cuisine sénégalaise","塞内加尔菜"],["un Sénégalais / une Sénégalaise","塞内加尔人"],["le français sénégalais","塞内加尔的法语"]],"sy":[["du Sénégal","courant","来自塞内加尔"],["africain","courant","非洲的（范围更大）"]],"fq":"中频，谈法语国家时常见。","me":"Sénégal + -ais：和 français 一样，词尾 s 不发音。","tr":{"zh":"我的邻居（女）是塞内加尔人。","fr":"Ma voisine est sénégalaise.","alt":"Ma voisine vient du Sénégal.","note":"阴性加 -e：sénégalais → sénégalaise。"}},
 "Sucré(e)": {"pos":"adj. 形容词，阴性 sucrée，复数 sucrés / sucrées；也可作阳性名词 le sucré","s":"甜的；加了糖的。le sucré 指「甜口的食物」，与 le salé 相对。boire un café sucré = 喝加了糖的咖啡。","ipa":"[sy.kʁe]","ph":"su [sy]；cr [kʁ]；é [e]。","pi":"u 读 [y]（嘴唇圆，发「于」的音），不是 [u]。词尾 -é 读 [e]。","et":"来自 sucre（糖），借自阿拉伯语 sukkar；sucré 是 sucrer（加糖）的过去分词。","ex":[["Je préfère le sucré.","我更喜欢甜的。"],["Ce thé est trop sucré.","这茶太甜了。"],["Tu veux un café sucré ?","你要加糖的咖啡吗？"]],"co":[["trop sucré","太甜"],["le salé et le sucré","咸的和甜的食物"],["un café sucré / non sucré","加糖 / 不加糖的咖啡"],["sans sucre ajouté","无添加糖"]],"sy":[["salé","courant","咸的（反义）"],["doux","courant","温和的；甘的（常指味道柔和或水果，不只是糖味）"],["sirupeux","soutenu","甜腻的，腻人的（偏书面）"]],"fq":"高频，谈食物、饮料时常用。","me":"sucre（糖）→ sucré：多了 é，就是「加了糖的」。","tr":{"zh":"这个蛋糕很甜。","fr":"Ce gâteau est très sucré.","alt":"Il est vraiment très sucré, ce gâteau.","note":"修饰阳性名词 gâteau，用阳性 sucré。"}},
 "Sud-africain(e)": {"pos":"adj. 形容词，阴性 sud-africaine，复数 sud-africains / sud-africaines","s":"南非的；南非人的。由 sud（南）+ africain（非洲的）构成，中间有连字符。作名词指人：un Sud-Africain（两个词首字母都大写）。","ipa":"[syd.a.fʁi.kɛ̃]","ph":"sud 读 [syd]，d 要发音；africain [a.fʁi.kɛ̃]；-ain 是鼻音 [ɛ̃]。阴性 sud-africaine 读 [syd.a.fʁi.kɛn]。","pi":"sud 里的 d 要读出来。ain 读鼻音 [ɛ̃]，阴性 aine 才读 [ɛn]。国名是 l'Afrique du Sud，但形容词是 sud-africain。","et":"sud（南）+ africain（Afrique + -ain）。sud 来自英语 south 的古形式，法语很早就借用了。","ex":[["Elle est sud-africaine.","她是南非人。"],["Mon voisin est sud-africain.","我的邻居是南非人。"],["Le vin sud-africain est très bon.","南非的葡萄酒很好喝。"]],"co":[["un vin sud-africain","南非葡萄酒"],["un Sud-Africain / une Sud-Africaine","南非人"],["l'équipe sud-africaine","南非队"],["la cuisine sud-africaine","南非菜"]],"sy":[["d'Afrique du Sud","courant","来自南非（更口语）"],["africain","courant","非洲的（范围更大）"]],"fq":"中频，谈国家、国籍时常用。","me":"sud（南）+ africain：南 + 非洲 = 南非。","tr":{"zh":"他是南非人，住在开普敦。","fr":"Il est sud-africain, il vit au Cap.","alt":"C'est un Sud-Africain, il habite au Cap.","note":"国籍用 être + 形容词，不加冠词。"}},
 "Thaïlandais(e)": {"pos":"adj. 形容词，阴性 thaïlandaise，复数 thaïlandais / thaïlandaises","s":"泰国的；泰国人的。常用来说菜系和餐馆：un restaurant thaïlandais。作名词指人：un Thaïlandais。","ipa":"[taj.lɑ̃.dɛ]","ph":"th 读 [t]；aï 读 [aj]；-ais 读 [ɛ]，词尾 s 不发音。阴性 thaïlandaise 读 [taj.lɑ̃.dɛz]。","pi":"th 在法语里读 [t]，不是英语的 [θ]。ï 上的两点表示 a 和 i 要分开读：[taj]，不是 [ɛ]。阳性 -ais 的 s 不发音，阴性才读 [z]。","et":"国名 Thaïlande 加后缀 -ais。Thaïlande 的意思是「泰人之地」，thaï 指泰语和泰人。","ex":[["Il mange un plat thaïlandais.","他吃一道泰国菜。"],["Elle est thaïlandaise.","她是泰国人。"],["J'aime beaucoup la cuisine thaïlandaise.","我非常喜欢泰国菜。"]],"co":[["un plat thaïlandais","一道泰国菜"],["la cuisine thaïlandaise","泰国菜"],["un restaurant thaïlandais","泰国餐馆"],["un Thaïlandais / une Thaïlandaise","泰国人"]],"sy":[["thaï","courant","泰国的；泰语的（thaï 更短，形容人和语言都可以）"],["de Thaïlande","courant","来自泰国"]],"fq":"中频，谈美食、旅行时常见。","me":"Thaï + land + -ais：「泰人之地」的人，th 读 t。","tr":{"zh":"我们在一家泰国餐馆吃晚饭。","fr":"On dîne dans un restaurant thaïlandais.","alt":"Ce soir, on mange thaïlandais.","note":"dîner dans + 地点；餐馆是阳性：un restaurant thaïlandais。"}},
 "Avoir faim": {"pos":"loc. 动词短语（avoir + 名词 faim），变位同 avoir","s":"饿。法语用 avoir faim（字面「有饥饿」），不能说 être faim。程度用 très、trop、un peu 加在 avoir 和 faim 之间：avoir très faim。","ipa":"[a.vwaʁ fɛ̃]","ph":"avoir [a.vwaʁ]；faim 读鼻音 [fɛ̃]，m 不发音。","pi":"faim 里的 m 不发音，整个读鼻音 [fɛ̃]，和 fin（结束）、feint 同音。不要说 être faim，要说 avoir faim。否定时 pas 在 ai 后：je n'ai pas faim。","et":"faim 来自拉丁语 fames（饥饿）。同源词：famine（饥荒）、affamé（饥饿的）。","ex":[["Je n'ai pas très faim ce matin.","我今天早上不太饿。"],["J'ai faim, on mange quand ?","我饿了，什么时候吃饭？"],["Les enfants ont très faim après l'école.","孩子们放学后很饿。"]],"co":[["avoir très faim","很饿"],["avoir une faim de loup","饿得像狼一样（饿极了）"],["mourir de faim","饿死了；饿得要命"],["la faim dans le monde","世界上的饥饿问题"]],"sy":[["avoir l'estomac dans les talons","familier","肚子都贴到脚后跟了（饿极了的口语说法）"],["avoir un petit creux","familier","有点饿；想吃点东西（口语）"],["avoir soif","courant","渴（相关词：avoir soif）"]],"fq":"极高频，日常口语必备。","me":"「有饥饿」：avoir faim，像 avoir soif（渴）、avoir chaud（热）一样用 avoir。","tr":{"zh":"我很饿，我想要一个三明治。","fr":"J'ai très faim, je voudrais un sandwich.","alt":"Je meurs de faim, je prendrais bien un sandwich.","note":"avoir faim 不加冠词；想要用条件式 je voudrais。"}},
 "Avoir la flemme de": {"pos":"loc. 口语动词短语，avoir la flemme de + 动词原形","s":"懒得做某事。是很常用的口语（familier），语气轻松。后面接动词原形：j'ai la flemme de cuisiner。也可单独用：J'ai la flemme.","ipa":"[a.vwaʁ la flɛm də]","ph":"avoir [a.vwaʁ]；flemme [flɛm]，fl 连读，e 在 flemme 里读 [ɛ]，不是鼻音；词尾 -mme 的 e 不发音。","pi":"flemme 里的 em 不是鼻音，要读 [ɛm]，m 要发出来。de 后面接动词原形，不接名词（接名词时说 la flemme du ménage 较少见）。这是口语词，写正式文章或对长辈不太合适。","et":"flemme 来自 flegme（冷淡，源自希腊语 phlegma），原指「迟钝、不爱动」。","ex":[["J'ai la flemme de faire du sport.","我懒得做运动。"],["Ce soir, j'ai la flemme de cuisiner.","今晚我懒得做饭。"],["Il a la flemme de se lever.","他懒得起床。"]],"co":[["avoir la flemme de + infinitif","懒得 + 动词"],["avoir la flemme","懒；不想动"],["quelle flemme !","真懒啊！/ 真不想动！"],["une grosse flemme","特别懒"]],"sy":[["ne pas avoir envie de","courant","不想（比较中性的说法）"],["être paresseux","courant","懒的（形容词，比较中性）"],["avoir la flemme","familier","懒得（口语）"]],"fq":"高频，年轻人和朋友间常用。","me":"flemme 听起来软绵绵，像人瘫在沙发上。","tr":{"zh":"今晚我懒得出门。","fr":"J'ai la flemme de sortir ce soir.","alt":"Ce soir, j'ai la flemme, je reste à la maison.","note":"avoir la flemme de + 动词原形；de 遇元音 sortir 不省音，因为后面是 s。"}},
 "Être en retard": {"pos":"loc. 动词短语（être + en retard）","s":"迟到；晚了。人、火车、航班都可以 être en retard。说迟到多久用 de：en retard de dix minutes。反义：être à l'heure（准时）、être en avance（提前）。","ipa":"[ɛtʁ ɑ̃ ʁə.taʁ]","ph":"en 读鼻音 [ɑ̃]；retard [ʁə.taʁ]，词尾 d 不发音，r 要读。","pi":"retard 词尾的 d 不发音（和 tard 一样），但最后的 r 要读出来。retard 是阳性名词：un retard。不要说 être retard，必须有 en。","et":"retard 来自动词 retarder，拉丁语 retardare（re- + tardare，使慢）。同源：tard（晚）。","ex":[["Désolé, je vais être en retard.","对不起，我要迟到了。"],["Le train est en retard de dix minutes.","火车晚点十分钟。"],["Tu es toujours en retard !","你总是迟到！"]],"co":[["arriver en retard","迟到（到达）"],["avoir du retard","晚点；有延误"],["être en retard de dix minutes","迟到十分钟"],["un retard de vingt minutes","二十分钟的延误"]],"sy":[["avoir du retard","courant","有延误（常用于交通工具）"],["être à l'heure","courant","准时（反义）"],["être en avance","courant","提前（反义）"]],"fq":"极高频，日常常用。","me":"en retard = 在「后面」（re-）：比别人慢，来得晚。","tr":{"zh":"不好意思，我迟到了。","fr":"Excusez-moi, je suis en retard.","alt":"Pardon, j'ai du retard, j'arrive !","note":"être en retard；延误用 avoir du retard。"}},
 "Carrefour": {"pos":"n.m. 阳性名词，复数 carrefours","s":"十字路口；交叉口。Carrefour（首字母大写）也是法国最大的连锁超市品牌，中文常译「家乐福」。在超市购物说 faire les courses à / chez Carrefour。","ipa":"[kaʁ.fuʁ]","ph":"car [kaʁ]；four [fuʁ]，ou 读 [u]，r 都要发音。","pi":"four 里的 ou 读 [u]，词尾 r 要读。注意不要把词尾读成 [fɔʁ]。作超市名时大写、不加冠词。","et":"来自晚期拉丁语 quadrifurcum，意为「四个岔口」（quadri- 四 + furca 叉）。","ex":[["Je fais mes courses à Carrefour.","我在家乐福买东西。"],["Tournez à gauche au carrefour.","在路口向左转。"],["Le carrefour est dangereux.","这个路口很危险。"]],"co":[["au carrefour","在路口"],["un carrefour dangereux","危险的路口"],["faire ses courses chez Carrefour","在家乐福购物"],["un carrefour de cultures","文化的交汇处（比喻）"]],"sy":[["croisement","courant","交叉口（也可指两条路相交）"],["intersection","courant","交叉点；路口（偏交通术语）"],["rond-point","courant","环岛（不一样的路口）"]],"fq":"高频，指路、购物都常用。","me":"来自「四个叉」：四条路在这里碰头。","tr":{"zh":"在下一个路口向右转。","fr":"Tournez à droite au prochain carrefour.","alt":"Au prochain carrefour, vous tournez à droite.","note":"表示「在路口」用 au carrefour；「下一个」是 prochain，放在名词前。"}},
 "Du maroilles": {"pos":"n.m. 阳性名词，不变（du maroilles = 部分冠词）","s":"玛瓦尔奶酪：法国北部的软质奶酪，外皮橙红，气味非常浓烈。通常不说 un maroilles 而说 du maroilles（不可数，部分冠词）。北方有名菜 tarte au maroilles（玛瓦尔奶酪塔）。","ipa":"[ma.ʁwal]","ph":"ma [ma]；roi [ʁwa]；lles [l]，词尾 -lles 读 [l]。","pi":"词尾 -illes 在这里读 [l]，不是 [ij]。oi 读 [wa]。因为是不可数的食物，前面用 du，不是 le + 数量。","et":"得名于法国北部 Nord 省的 Maroilles 村。","ex":[["Le maroilles est un fromage fort.","玛瓦尔奶酪味道很重。"],["On sent le maroilles à des kilomètres !","几公里外就能闻到玛瓦尔奶酪的味道！"],["Je mange du maroilles avec du pain.","我用面包配玛瓦尔奶酪吃。"]],"co":[["du maroilles","一些玛瓦尔奶酪"],["une tarte au maroilles","玛瓦尔奶酪塔"],["un fromage à pâte molle","软质奶酪"],["une croûte lavée","洗浸外皮（奶酪）"]],"sy":[["munster","courant","明斯特奶酪（另一种气味浓的洗浸外皮奶酪）"],["époisses","courant","埃普瓦斯奶酪（气味同样很重）"],["fromage","courant","奶酪（总称）"]],"fq":"低频，谈法国北部美食时才用。","me":"maroilles 闻起来重，但名字像「马」+「卢瓦」，记住 oi = wa。","tr":{"zh":"我想要一块玛瓦尔奶酪。","fr":"Je voudrais un morceau de maroilles.","alt":"Je prendrais bien un peu de maroilles.","note":"un morceau de + 无冠词名词：un morceau de maroilles。"}},
 "Du rhum": {"pos":"n.m. 阳性名词，复数 rhums（通常用 du rhum，不可数）","s":"朗姆酒。作物质时用 du rhum；点一杯或一种酒时可用 un rhum。法国海外省（安的列斯群岛）出产有名的朗姆酒。baba au rhum 是用朗姆酒浸的甜点。","ipa":"[ʁɔm]","ph":"rh 读 [ʁ]，h 不发音；um 读 [ɔm]，不是 [œm]。","pi":"h 不发音，rh 只读 [ʁ]。um 在这里读 [ɔm]，所以 rhum 和英语 rum 不一样，不读 [ʁœm]。拼写有 h，别漏掉。","et":"借自英语 rum；法语拼写加了 h（受 rhumatisme 之类词的影响不详）。","ex":[["Il y a du rhum dans ce cocktail.","这杯鸡尾酒里有朗姆酒。"],["Je prends un baba au rhum.","我吃一个朗姆酒蛋糕。"],["Le rhum vient des Antilles.","朗姆酒产自安的列斯群岛。"]],"co":[["un baba au rhum","朗姆酒蛋糕"],["du rhum blanc / ambré","白朗姆酒 / 陈年朗姆酒"],["un rhum arrangé","浸泡水果的朗姆酒"],["un verre de rhum","一杯朗姆酒"]],"sy":[["alcool","courant","酒精（总称）"],["eau-de-vie","soutenu","烈酒（偏书面）"]],"fq":"中低频，菜单、鸡尾酒里常见。","me":"rhum 写成 rh，读成 [ʁɔm]：像 rom。","tr":{"zh":"我想要一杯朗姆酒。","fr":"Je voudrais un verre de rhum.","alt":"Je prendrais bien un petit rhum.","note":"un verre de + 无冠词名词：un verre de rhum。"}},
 "Le centre": {"pos":"n.m. 阳性名词，复数 centres","s":"中心；中央。可指几何或地点的中心（le centre de la ville），也可指提供服务的场所：un centre sportif（体育中心）、un centre commercial（购物中心）。","ipa":"[sɑ̃tʁ]","ph":"c 在 e 前读 [s]；en 读鼻音 [ɑ̃]；-tre 读 [tʁ]，词尾 e 不发音。","pi":"cen 的 en 读鼻音 [ɑ̃]，不是 [ɛn]。词尾 -tre 读 [tʁ]，不要在后面加元音。与英语 center 拼写不同：法语是 centre。","et":"来自拉丁语 centrum，源自希腊语 kentron（圆规的尖）。","ex":[["Le centre est ici.","中心在这里。"],["Le bureau est au centre de la ville.","办公室在市中心。"],["Il y a un centre sportif près de chez moi.","我家附近有一个体育中心。"]],"co":[["au centre de","在……的中心"],["le centre-ville","市中心"],["un centre commercial","购物中心"],["un centre sportif","体育中心"]],"sy":[["milieu","courant","中间（位置上的中间）"],["cœur","courant","核心；心脏部位"],["périphérie","soutenu","外围；边缘（反义，偏书面）"]],"fq":"极高频，日常常用。","me":"centre = center 倒过来：re 在后。","tr":{"zh":"博物馆在城市中心。","fr":"Le musée est au centre de la ville.","alt":"Le musée, c'est en plein centre.","note":"au centre de + 名词（à + le → au）。"}},
 "Le centre-ville": {"pos":"n.m. 阳性名词，复数 centres-villes","s":"市中心。由 centre（中心）+ ville（城市）组成，中间有连字符。「在市中心」可说 dans le centre-ville，也很常说 en centre-ville（不带冠词）。反义：la banlieue（郊区）。","ipa":"[sɑ̃.tʁə.vil]","ph":"centre [sɑ̃tʁ] 与 ville [vil] 相连时，tre 的 e 常读出来，成 [sɑ̃.tʁə.vil]；ville 的 ll 在这里读 [l]。","pi":"ville 读 [vil]，ll 读单个 [l]，不是 [vij]。复数是 centres-villes（两个词都加 s），但很少用复数。","et":"centre（见 centre）+ ville（拉丁语 villa，农庄，后来指城镇）。","ex":[["J'habite dans le centre-ville.","我住在市中心。"],["Je travaille en centre-ville.","我在市中心工作。"],["Le centre-ville est piéton le dimanche.","市中心星期天是步行街。"]],"co":[["en centre-ville","在市中心"],["dans le centre-ville","在市中心里"],["un appartement en centre-ville","市中心的公寓"],["le centre-ville piétonnier","市中心步行街"]],"sy":[["le centre","courant","中心（更短，更宽泛）"],["la banlieue","courant","郊区（反义）"]],"fq":"高频，谈住址、购物时常用。","me":"centre + ville = 「城市的中心」，一个词顺着读。","tr":{"zh":"我的公寓在市中心。","fr":"Mon appartement est dans le centre-ville.","alt":"J'ai un appart en centre-ville.","note":"dans le centre-ville 或 en centre-ville 都可以。"}},
 "Le commissariat": {"pos":"n.m. 阳性名词，复数 commissariats","s":"警察局；派出所。在城镇里报案、丢东西时去的地方：commissariat de police。农村地区常是 gendarmerie（宪兵队）。","ipa":"[kɔ.mi.sa.ʁja]","ph":"com [kɔ]；mi [mi]；ssa 读 [sa]；-iat 读 [ja]，词尾 t 不发音。","pi":"拼写陷阱：commissariat 有两个 m、两个 s。词尾 t 不发音。ia 读 [ja]，不是两个元音分开。","et":"来自 commissaire（警官）+ 后缀 -at；commissaire 源自拉丁语 commissarius，「被委托的人」，同源 commettre（委托、犯下）。","ex":[["Le commissariat est ouvert.","警察局开门了。"],["Où est le commissariat ?","警察局在哪里？"],["Il va au commissariat pour déclarer le vol.","他去警察局报失窃案。"]],"co":[["un commissariat de police","警察局"],["aller au commissariat","去警察局"],["déposer plainte au commissariat","到警察局报案"],["un commissariat de quartier","社区派出所"]],"sy":[["poste de police","courant","警察局（说法更中性）"],["gendarmerie","courant","宪兵队（乡镇的警察机构）"],["le poste","familier","警局（口语简称）"]],"fq":"中频，求助、问路时会用到。","me":"commissaire（警官）+ -at = 警官办公的地方。","tr":{"zh":"请问，警察局在哪里？","fr":"Où est le commissariat, s'il vous plaît ?","alt":"Excusez-moi, il y a un commissariat près d'ici ?","note":"Où est ... ? 问地点；s'il vous plaît 放句末。"}},
 "Le Luxembourg": {"pos":"n.m. 阳性专有名词（国名），无复数","s":"卢森堡（国家）。国名是阳性：le Luxembourg；「在卢森堡」用 au Luxembourg，「来自卢森堡」用 du Luxembourg。巴黎也有著名的 jardin du Luxembourg（卢森堡公园）。","ipa":"[lyk.sɑ̃.buʁ]","ph":"lux [lyks]，x 读 [ks]；em 读鼻音 [ɑ̃]；bourg 读 [buʁ]，g 不发音。","pi":"x 读 [ks]；em 读 [ɑ̃]，不是 [ɛm]。bourg 里的 g 不发音，ou 读 [u]。形容词和人称是 luxembourgeois，不是 luxembourg。","et":"词尾 -bourg 来自日耳曼语 burg（堡垒、城镇），同源 Strasbourg。前半部分的来源不确定。","ex":[["Le Luxembourg est un petit pays.","卢森堡是个小国。"],["Elle habite au Luxembourg.","她住在卢森堡。"],["Nous nous promenons au jardin du Luxembourg.","我们在卢森堡公园散步。"]],"co":[["au Luxembourg","在卢森堡"],["du Luxembourg","来自卢森堡"],["le grand-duché de Luxembourg","卢森堡大公国"],["le jardin du Luxembourg","（巴黎的）卢森堡公园"]],"sy":[["luxembourgeois","courant","卢森堡的；卢森堡人（形容词与名词）"]],"fq":"中低频，谈欧洲国家时用。","me":"Luxe + bourg：「奢华」之堡，读 [lyk.sɑ̃.buʁ]（仅帮助记忆，非词源）。","tr":{"zh":"我在卢森堡工作。","fr":"Je travaille au Luxembourg.","alt":"Je bosse au Luxembourg.","note":"阳性国名用 au（在）/ du（来自）。"}},
 "Le matin": {"pos":"n.m. 阳性名词，复数 matins","s":"早上；上午。le matin（不加介词）表示「每天早上」；ce matin = 今天早上；demain matin = 明天早上；à sept heures du matin = 早上七点。","ipa":"[ma.tɛ̃]","ph":"ma [ma]；tin 读鼻音 [tɛ̃]，in 是鼻音，n 不发音。","pi":"不要说 dans le matin 或 en le matin；「早上」直接用 le matin。词尾 in 读 [ɛ̃]，不读 [in]。相近词：matinée 强调「整个上午这段时间」。","et":"来自拉丁语 matutinum（清晨的）。同源：matinal（早起的）、matinée。","ex":[["Je bois un café le matin.","早上我喝咖啡。"],["Ce matin, il pleut.","今天早上下雨。"],["Je me lève à sept heures du matin.","我早上七点起床。"]],"co":[["le matin","早上（习惯性）"],["ce matin","今天早上"],["demain matin","明天早上"],["à sept heures du matin","早上七点"]],"sy":[["la matinée","courant","上午这段时间（强调时长）"],["l'aube","littéraire","拂晓（文学用语）"],["le soir","courant","晚上（反义）"]],"fq":"极高频，日常常用。","me":"matin 里有 tin 的鼻音：早上总是 [ma.tɛ̃]，像「马丁」。","tr":{"zh":"早上我坐公共汽车。","fr":"Le matin, je prends le bus.","alt":"Tous les matins, je prends le bus.","note":"le matin = 每天早上；后面不用介词。"}},
 "Le monde": {"pos":"n.m. 阳性名词，复数 mondes","s":"世界；人群。常用意思：le monde = 世界；du monde / beaucoup de monde / trop de monde = 人很多；tout le monde = 大家、每个人（动词用单数）。","ipa":"[mɔ̃d]","ph":"mon 读鼻音 [mɔ̃]；de 的 d 要读，词尾 e 不发音，整体 [mɔ̃d]。","pi":"monde 的 d 要读出来 [mɔ̃d]。tout le monde 的动词用第三人称单数：Tout le monde est là，不是 sont。「人多」说 du monde，不说 des mondes。","et":"来自拉丁语 mundus（宇宙；世界）。同源：mondial（世界的）、mondain（社交界的）。","ex":[["Il y a trop de monde !","人太多了！"],["Tout le monde est là.","大家都到了。"],["J'aimerais voyager dans le monde entier.","我想环游全世界。"]],"co":[["tout le monde","大家；每个人"],["beaucoup de monde","人很多"],["dans le monde entier","全世界"],["le monde entier","整个世界"]],"sy":[["les gens","courant","人们（用复数 gens）"],["la Terre","courant","地球"],["l'univers","soutenu","宇宙（书面）"]],"fq":"极高频，日常常用。","me":"mon + de：「我的世界」——d 要读出来。","tr":{"zh":"地铁里有很多人。","fr":"Il y a beaucoup de monde dans le métro.","alt":"Y a un monde fou dans le métro.","note":"beaucoup de monde 表示人多，monde 不加冠词。"}},
 "Le soir": {"pos":"n.m. 阳性名词，复数 soirs","s":"晚上；傍晚。le soir 表示「每天晚上」；ce soir = 今晚；hier soir = 昨晚；à huit heures du soir = 晚上八点。","ipa":"[swaʁ]","ph":"oi 读 [wa]；词尾 r 要发音：[swaʁ]。","pi":"oi 读 [wa]，r 要读出来。le soir 不加介词（不说 dans le soir）。soir 指时间点，soirée 强调整个晚上或晚会。","et":"来自拉丁语 serum（晚上的），本义「晚了」。同源：bonsoir（晚上好）。","ex":[["Je lis un livre le soir.","晚上我读书。"],["Ce soir, on sort.","今晚我们出去玩。"],["Hier soir, nous avons dîné au restaurant.","昨晚我们在餐厅吃饭。"]],"co":[["le soir","晚上（习惯性）"],["ce soir","今晚"],["hier soir","昨晚"],["à huit heures du soir","晚上八点"]],"sy":[["la soirée","courant","整个晚上；晚会（强调时间段或活动）"],["la nuit","courant","夜晚（比 soir 更晚）"],["le matin","courant","早上（反义）"]],"fq":"极高频，日常常用。","me":"soir = 「索瓦」，晚上好说 bonsoir。","tr":{"zh":"晚上我看电影。","fr":"Le soir, je regarde un film.","alt":"Tous les soirs, je regarde un film.","note":"le soir = 每天晚上，无介词。"}},
 "Le soleil": {"pos":"n.m. 阳性名词，复数 soleils（很少用）","s":"太阳；阳光。Il y a du soleil = 出太阳了。un coup de soleil 是「晒伤」，不是「一下阳光」。prendre le soleil = 晒太阳。","ipa":"[sɔ.lɛj]","ph":"so [sɔ]；leil 读 [lɛj]，ei 读 [ɛ]，il 在 e 后读 [j]。","pi":"-eil 读 [ɛj]：soleil [sɔ.lɛj]，不是 [lɛl]。「出太阳」用 du soleil（部分冠词）。un coup de soleil 是 sunburn。","et":"来自晚期拉丁语 soliculus，是 sol（太阳）的小词；同源：solaire（太阳的）。","ex":[["Le soleil brille.","太阳照耀。"],["Il y a du soleil aujourd'hui.","今天出太阳。"],["J'ai pris un coup de soleil à la plage.","我在海滩上被晒伤了。"]],"co":[["il y a du soleil","出太阳了"],["un coup de soleil","晒伤"],["le lever / le coucher du soleil","日出 / 日落"],["prendre le soleil","晒太阳"]],"sy":[["astre","soutenu","天体；星辰（书面）"],["ensoleillé","courant","阳光充足的（形容词）"]],"fq":"极高频，谈天气时必备。","me":"soleil 里有 sol（太阳），像西班牙语 sol。","tr":{"zh":"出太阳了，我们去海滩吧。","fr":"Il y a du soleil, on va à la plage.","alt":"Avec ce soleil, allons à la plage !","note":"il y a du soleil 谈天气；on va à la plage 用 aller + à。"}},
 "Le sommet": {"pos":"n.m. 阳性名词，复数 sommets","s":"山顶；顶端。引申：高峰会议、首脑会议（un sommet）。le sommet de la montagne 是山顶；le sommet de l'État 指国家最高层。","ipa":"[sɔ.mɛ]","ph":"so [sɔ]；mm 只读一个 [m]；-et 读 [ɛ]，词尾 t 不发音。","pi":"词尾 t 不发音（和 sommeil 区别）。注意拼写有两个 m。au sommet de = 在……顶上。","et":"来自古法语 som（顶），拉丁语 summum（最高处）；加小词后缀 -et。","ex":[["Nous sommes au sommet.","我们到山顶了。"],["Le sommet de la montagne est couvert de neige.","山顶覆盖着雪。"],["Les chefs d'État se réunissent lors d'un sommet.","国家元首们在一次峰会上会面。"]],"co":[["atteindre le sommet","登顶"],["au sommet de","在……的顶端"],["un sommet international","国际峰会"],["le sommet de la montagne","山顶"]],"sy":[["cime","soutenu","山尖；顶峰（书面）"],["pic","courant","山峰（尖尖的峰）"],["haut","courant","高处（较口语）"]],"fq":"中频，登山、新闻中常见。","me":"sommet = som（顶）+ -et：最高点。","tr":{"zh":"我们到山顶了。","fr":"Nous arrivons au sommet de la montagne.","alt":"On est enfin arrivés au sommet !","note":"arriver au sommet de + 名词。"}},
 "Le surf": {"pos":"n.m. 阳性名词，不可数（也有动词 surfer）","s":"冲浪（运动）。运动用 faire du surf；冲浪板是 une planche de surf。动词是 surfer：Il surfe。surfer sur Internet 是「上网冲浪」。","ipa":"[sœʁf]","ph":"su 读 [sœ]（和 sœur 的音一样）；r 读 [ʁ]；f 读 [f]。","pi":"surf 里的 u 读 [œ]，不是 [y]，也不是英语的 [ɜː]；r 和 f 都要读。不要读成「苏夫」。","et":"借自英语 surf（海浪拍岸），20 世纪初进入法语。","ex":[["J'aime le surf.","我喜欢冲浪。"],["Il fait du surf tous les week-ends.","他每个周末都去冲浪。"],["Elle a une nouvelle planche de surf.","她有一块新冲浪板。"]],"co":[["faire du surf","冲浪"],["une planche de surf","冲浪板"],["un cours de surf","冲浪课"],["un spot de surf","冲浪点"]],"sy":[["bodyboard","courant","趴板冲浪（用短板趴着冲）"],["windsurf","courant","风帆冲浪"]],"fq":"中频，谈运动和度假时使用。","me":"surf [sœʁf]：读起来像 sœur（姐妹）加 f。","tr":{"zh":"假期我去冲浪。","fr":"Je fais du surf pendant les vacances.","alt":"En vacances, je surfe tous les jours.","note":"faire du + 运动：faire du surf。"}},
 "Un arrêt (de bus, de tram)": {"pos":"n.m. 阳性名词，复数 arrêts","s":"车站；停靠点（公交、电车）；停止。un arrêt de bus = 公交站；sans arrêt = 不停地；un arrêt maladie = 病假（医生开的休假单）。","ipa":"[a.ʁɛ]","ph":"a [a]；rr 读一个 [ʁ]；ê 读 [ɛ]，词尾 t 不发音。","pi":"词尾 t 不发音：arrêt [a.ʁɛ]。拼写有 ^ 和两个 r。注意：地铁、火车「站」多用 station 或 gare，公交和有轨电车用 arrêt。","et":"来自动词 arrêter，源自拉丁语 ad + restare（停住）。","ex":[["Je descends au prochain arrêt.","我下一站下车。"],["L'arrêt de bus est en face de la gare.","公交车站在火车站对面。"],["Il travaille sans arrêt.","他不停地工作。"]],"co":[["un arrêt de bus","公交站"],["un arrêt de tram","电车站"],["sans arrêt","不停地"],["un arrêt maladie","病假"]],"sy":[["station","courant","站（地铁站、车站）"],["halte","soutenu","停靠点（较书面，铁路、旅行中）"],["pause","courant","暂停"]],"fq":"高频，坐车、指路时常用。","me":"arrêt = arrêter（停下）：车在这里停。","tr":{"zh":"公交站就在我家附近。","fr":"L'arrêt de bus est près de chez moi.","alt":"Mon arrêt de bus est juste à côté.","note":"un arrêt de bus；près de chez moi = 在我家附近。"}},
 "Un ascenseur": {"pos":"n.m. 阳性名词，复数 ascenseurs","s":"电梯。常用搭配：prendre l'ascenseur（坐电梯）、en panne（坏了）。楼层用 au cinquième étage（在五楼）。","ipa":"[a.sɑ̃.sœʁ]","ph":"a [a]；sc 读 [s]；en 读鼻音 [ɑ̃]；-eur 读 [œʁ]，r 要发音。","pi":"sc 在 e/i 前读 [s]，不是 [sk]。en 读 [ɑ̃]，不是 [ɛn]。词尾 -eur 读 [œʁ]。ascenseur 是阳性名词，虽然 -eur 的词有些是阴性（如 la fleur）。","et":"来自拉丁语 ascendere（向上爬）；法语 ascenseur 由 ascension 一类词加 -eur 构成，意为「使上升的东西」。","ex":[["L'ascenseur est en panne.","电梯坏了。"],["Je prends l'ascenseur jusqu'au cinquième étage.","我坐电梯到五楼。"],["Il n'y a pas d'ascenseur dans ce bâtiment.","这座楼里没有电梯。"]],"co":[["prendre l'ascenseur","坐电梯"],["être en panne","坏了；出故障"],["appeler l'ascenseur","叫电梯"],["monter en ascenseur","坐电梯上楼"]],"sy":[["escalier","courant","楼梯"],["monte-charge","courant","货梯"],["escalator","courant","自动扶梯"]],"fq":"中高频，住宅和商场里常用。","me":"ascenseur = 「上升者」：ascend + -eur。","tr":{"zh":"电梯不能用，我们走楼梯吧。","fr":"L'ascenseur ne marche pas, prenons l'escalier.","alt":"L'ascenseur est en panne, on prend l'escalier.","note":"prendre l'escalier = 走楼梯；用 prendre 表示选择交通方式。"}},
 "Un avion": {"pos":"n.m. 阳性名词，复数 avions","s":"飞机。prendre l'avion = 坐飞机；voyager en avion = 乘飞机旅行；un billet d'avion = 机票。","ipa":"[a.vjɔ̃]","ph":"a [a]；vi 读 [vj]；-on 读鼻音 [ɔ̃]，n 不发音。","pi":"ion 读 [jɔ̃]，不要把 n 读出来。「坐飞机」用 en avion，不用 par avion（只用于航空邮件）。","et":"发明者 Clément Ader 在 19 世纪末造的词，来自拉丁语 avis（鸟）。","ex":[["Je prends l'avion pour Paris.","我坐飞机去巴黎。"],["L'avion décolle à dix heures.","飞机十点起飞。"],["Nous voyageons en avion.","我们乘飞机旅行。"]],"co":[["prendre l'avion","坐飞机"],["en avion","乘飞机"],["un billet d'avion","机票"],["rater son avion","误了飞机"]],"sy":[["appareil","courant","飞行器（较中性）"],["aéronef","soutenu","航空器（书面）"]],"fq":"高频，旅行时常用。","me":"avion 里有 avis（鸟）：飞的东西。","tr":{"zh":"我因为工作乘飞机旅行。","fr":"Je voyage en avion pour mon travail.","alt":"Pour le boulot, je voyage souvent en avion.","note":"voyager en avion；pour mon travail = 为了工作。"}},
 "Un bâtiment": {"pos":"n.m. 阳性名词，复数 bâtiments","s":"建筑物；楼房。可指任何有结构的建筑；le bâtiment 也指建筑行业：travailler dans le bâtiment。immeuble 更常指住宅或办公的多层楼。","ipa":"[bɑ.ti.mɑ̃]","ph":"bâ [bɑ]；ti [ti]；-ment 读鼻音 [mɑ̃]，t 不发音。","pi":"词尾 -ment 读 [mɑ̃]，不读 [mɛnt]。â 带 ^，读较长的 [ɑ]。bâtiment 不只指「大楼」，也可指「船舶」（旧义）。","et":"由动词 bâtir（建造）+ 后缀 -ment 构成；bâtir 源自日耳曼语，不是拉丁语。","ex":[["Ce bâtiment est grand.","这座建筑很大。"],["La mairie est un bâtiment ancien.","市政厅是一座古老的建筑。"],["Il travaille dans le bâtiment.","他在建筑行业工作。"]],"co":[["un bâtiment public","公共建筑"],["un bâtiment ancien","古老的建筑"],["travailler dans le bâtiment","在建筑行业工作"],["un bâtiment historique","历史建筑"]],"sy":[["immeuble","courant","楼房（住宅、办公楼）"],["édifice","soutenu","建筑（书面）"],["construction","courant","建筑物；工程"]],"fq":"高频，谈城市、地点时常用。","me":"bâtir（建）+ -ment：建出来的东西。","tr":{"zh":"这座建筑非常古老。","fr":"Ce bâtiment est très ancien.","alt":"C'est un très vieux bâtiment.","note":"ce bâtiment：bâtiment 是阳性，用 ce。"}},
 "Un bus": {"pos":"n.m. 阳性名词，复数 bus（单复数同形）","s":"公共汽车。日常最常用的短说法，全称是 autobus。长途大巴更常说 un car（注意：un car 不是汽车）。","ipa":"[bys]","ph":"b [b]；u 读 [y]；s 要发音：[bys]。","pi":"u 读 [y]（嘴唇圆），不是英语 [ʌ]；词尾 s 要读。复数 des bus 不加 s。「坐公交」说 en bus 或 prendre le bus。","et":"来自 autobus 的缩略；autobus = auto（自动）+ omnibus（拉丁语「为所有人」）。","ex":[["J'attends le bus.","我在等公交车。"],["Je prends le bus tous les matins.","我每天早上坐公交车。"],["Le bus est en retard.","公交车晚点了。"]],"co":[["prendre le bus","坐公交"],["attendre le bus","等公交"],["rater le bus","错过公交"],["un arrêt de bus","公交站"]],"sy":[["autobus","courant","公共汽车（全称）"],["autocar","courant","长途大巴"],["car","courant","大巴；客车（同 autocar）"]],"fq":"极高频，日常常用。","me":"bus 是 autobus 的尾巴，u 要圆嘴：[bys]。","tr":{"zh":"我坐公交去上班。","fr":"Je prends le bus pour aller au travail.","alt":"Pour aller au boulot, je prends le bus.","note":"prendre le bus + pour aller au travail。"}},
 "Un centre commercial": {"pos":"n.m. 阳性名词，复数 centres commerciaux","s":"购物中心。里面有很多商店、餐馆。注意复数：centre 加 s，commercial 变成 commerciaux。常用说法：aller au centre commercial，faire les magasins（逛商店）。","ipa":"[sɑ̃tʁ kɔ.mɛʁ.sjal]","ph":"centre [sɑ̃tʁ]；commercial [kɔ.mɛʁ.sjal]：c 在 i 前读 [s]，ia 读 [ja]，词尾 l 要发音。","pi":"commercial 里的 ci 读 [sj]。复数不是 commercials，而是 commerciaux（al → aux）。拼写：commercial 有两个 m，一个 c 在中间。","et":"centre（见 centre）+ commercial（commerce，拉丁语 commercium，买卖）。","ex":[["Il y a beaucoup de magasins dans le centre commercial.","购物中心里有很多商店。"],["Je vais au centre commercial samedi.","星期六我去购物中心。"],["Les centres commerciaux ferment à vingt heures.","购物中心晚上八点关门。"]],"co":[["aller au centre commercial","去购物中心"],["faire les magasins","逛商店"],["une galerie marchande","商场里的店铺走廊"],["un grand centre commercial","大型购物中心"]],"sy":[["galerie marchande","courant","商场里的商店走廊"],["grande surface","courant","大型超市（卖日用品的大店）"]],"fq":"高频，谈购物时常用。","me":"centre + commercial：「商业的中心」。","tr":{"zh":"星期六我们去购物中心。","fr":"Nous allons au centre commercial samedi.","alt":"Samedi, on va au centre commercial.","note":"au centre commercial（à + le = au）。"}},
 "Un croque-monsieur": {"pos":"n.m. 阳性名词，复数 croque-monsieur（有时写 croque-monsieurs）","s":"火腿奶酪烤三明治：两片面包夹火腿和奶酪，上面再撒奶酪烤。法国咖啡馆的常见简餐。加一个煎蛋就叫 croque-madame。","ipa":"[kʁɔk.mə.sjø]","ph":"croque [kʁɔk]；monsieur 读 [mə.sjø]，不是 [mɔ̃.sjø]。","pi":"monsieur 是特例：mon 读 [mə]（像 me），不读鼻音。croque-monsieur 的复数通常不变。英语 sieur 的读法与法语不同：法语是 [sjø]。","et":"由 croquer（咬，嚼出声）+ monsieur（先生）构成；为什么叫「先生」，说法不一，来源不确定。","ex":[["Je commande un croque-monsieur.","我点一个火腿奶酪三明治。"],["Un croque-monsieur et une salade, s'il vous plaît.","一个火腿奶酪三明治和一份沙拉，谢谢。"],["Elle préfère un croque-madame.","她更喜欢带煎蛋的那种。"]],"co":[["un croque-monsieur au jambon","火腿奶酪三明治"],["un croque-madame","加煎蛋的 croque-monsieur"],["commander un croque-monsieur","点一个 croque-monsieur"],["un croque-monsieur au fromage","奶酪三明治"]],"sy":[["croque-madame","courant","加煎蛋的 croque（croque-monsieur 的「女士版」）"],["sandwich","courant","三明治（总称）"],["un croque","familier","简称（口语）"]],"fq":"中频，咖啡馆菜单上常见。","me":"croque（咬）+ monsieur：「咬一口先生」，monsieur 读 [mə.sjø]。","tr":{"zh":"我想要一个火腿奶酪三明治和一杯咖啡。","fr":"Je voudrais un croque-monsieur et un café.","alt":"Un croque-monsieur et un café, s'il vous plaît.","note":"je voudrais + 名词；点餐时的礼貌说法。"}},
 "Un endroit": {"pos":"n.m. 阳性名词，复数 endroits","s":"地方；场所。比 lieu 更口语。也有「正面」之意：l'endroit（布的正面）与 l'envers（反面）相对：à l'endroit = 正着放。","ipa":"[ɑ̃.dʁwa]","ph":"en 读鼻音 [ɑ̃]；dr 读 [dʁ]；oi 读 [wa]；词尾 t 不发音。","pi":"词尾 t 不发音：endroit [ɑ̃.dʁwa]。别写成 un droit（权利）。形容词 beau 在阳性元音开头名词前变 bel：un bel endroit。","et":"由 en + droit（右、正）构成，本义「正面」，后来泛指「地方」。","ex":[["C'est un bel endroit.","这是个美丽的地方。"],["Ce restaurant est un endroit très calme.","这家餐厅很安静。"],["À quel endroit se trouve la gare ?","火车站在哪个位置？"]],"co":[["un endroit calme","安静的地方"],["à cet endroit","在这个地方"],["un endroit sympa","不错的地方"],["à l'endroit / à l'envers","正面 / 反面"]],"sy":[["lieu","soutenu","场所；地点（偏书面）"],["coin","familier","角落；小地方（口语）"],["place","courant","位置；空间"]],"fq":"极高频，日常常用。","me":"en + droit：在「正确」的位置上，就是一个地方。","tr":{"zh":"这是个非常舒服的地方。","fr":"C'est un endroit très agréable.","alt":"C'est vraiment un coin sympa.","note":"bel 用在元音开头的阳性名词前。"}},
 "Un festival": {"pos":"n.m. 阳性名词，复数 festivals","s":"艺术节；音乐节；电影节（有节目安排的活动）。注意：法语里 festival 多指音乐、电影等文艺活动，不是传统节日。节日、庆典要说 fête。","ipa":"[fɛs.ti.val]","ph":"fes [fɛs]；ti [ti]；val [val]；词尾 l 要发音。","pi":"复数是 festivals，不是 festivaux。s 在 fes 里读 [s]。节日（如春节、国庆日）用 la fête，而不是 festival。","et":"来自拉丁语 festum（节日）；和 fête、festif 同源。","ex":[["Je vais à un festival de musique.","我去参加音乐节。"],["Le festival de Cannes a lieu en mai.","戛纳电影节五月举行。"],["Nous avons acheté des billets pour le festival.","我们买了音乐节的票。"]],"co":[["un festival de musique","音乐节"],["un festival de cinéma","电影节"],["aller à un festival","去参加音乐节"],["le festival de Cannes","戛纳电影节"]],"sy":[["fête","courant","节日；聚会（传统节日用 fête）"],["concert","courant","音乐会（时间比较短）"]],"fq":"中高频，谈文化活动时常用。","me":"festival ~ fête：都和「节」有关。","tr":{"zh":"今年夏天我去一个爵士音乐节。","fr":"Je vais à un festival de jazz cet été.","alt":"Cet été, je vais à un festival de jazz.","note":"aller à un festival；de jazz 修饰 festival。"}},
 "Un jardin public": {"pos":"n.m. 阳性名词，复数 jardins publics","s":"公园（市民免费进入的花园）。比 parc 小，通常在城市里。jardin 是花园，public 是「公共的」，阴性是 publique。","ipa":"[ʒaʁ.dɛ̃ py.blik]","ph":"jar [ʒaʁ]；din 读鼻音 [dɛ̃]；public [py.blik]，u 读 [y]，词尾 c 读 [k]。","pi":"j 读 [ʒ]（像英语 measure 中的 s）。din 读鼻音 [dɛ̃]。public 里的 u 读 [y]，词尾 c 要读 [k]（阴性 publique 也一样 [py.blik]）。复数两个词都加 s。","et":"jardin 来自古法语 jart + -in，源自日耳曼语；public 来自拉丁语 publicus。","ex":[["Les enfants jouent dans le jardin public.","孩子们在公园玩。"],["Il y a un jardin public près de chez moi.","我家附近有一个公园。"],["On pique-nique dans le jardin public.","我们在公园里野餐。"]],"co":[["se promener dans un jardin public","在公园散步"],["un banc dans le jardin public","公园里的长椅"],["un jardin public fleuri","开满花的公园"],["les jardins publics","公园（复数）"]],"sy":[["parc","courant","公园（范围通常更大）"],["square","courant","小街心花园"]],"fq":"中高频，谈休闲时常用。","me":"jardin（花园）+ public（大家的）。","tr":{"zh":"我们在公园里散步。","fr":"Nous nous promenons dans le jardin public.","alt":"On se balade dans le jardin public.","note":"se promener dans；复数时 public 变 publics。"}},
 "Un magasin": {"pos":"n.m. 阳性名词，复数 magasins","s":"商店。faire les magasins = 逛街、逛店；un grand magasin = 百货公司。注意不要和 magazine（杂志）混淆。","ipa":"[ma.ga.zɛ̃]","ph":"ma [ma]；ga [ga]；s 在两个元音之间读 [z]；-in 读鼻音 [ɛ̃]。","pi":"s 读 [z]，所以是 [ma.ga.zɛ̃]，不是 [ma.ga.sɛ̃]。词尾 -in 是鼻音。magasin（商店）和 magazine（杂志）读音和意思都不同。","et":"来自阿拉伯语 makhāzin（仓库），经意大利语进入法语。英语 magazine 与它同源。","ex":[["J'achète des vêtements dans ce magasin.","我在这家店买衣服。"],["Le magasin ferme à dix-neuf heures.","商店晚上七点关门。"],["Nous faisons les magasins samedi.","我们星期六去逛街。"]],"co":[["faire les magasins","逛街；逛商店"],["un magasin de vêtements","服装店"],["un grand magasin","百货公司"],["ouvert / fermé","开门 / 关门"]],"sy":[["boutique","courant","小店；精品店"],["commerce","courant","商业；店铺"],["grande surface","courant","大型超市"]],"fq":"极高频，购物时必备。","me":"magasin 是「仓库」：从前商店就是放货的地方。","tr":{"zh":"这家商店星期天开门。","fr":"Ce magasin est ouvert le dimanche.","alt":"Le magasin ouvre même le dimanche.","note":"ce magasin；le dimanche = 每个星期天。"}},
 "Un magazine": {"pos":"n.m. 阳性名词，复数 magazines","s":"杂志；画报。也指电视或广播的专题节目：un magazine télévisé。注意不是「商店」，商店是 magasin。","ipa":"[ma.ga.zin]","ph":"ma [ma]；ga [ga]；zine 读 [zin]，z 读 [z]，词尾 e 不发音，-zine 读 [zin]。","pi":"词尾 -zine 读 [zin]，不是鼻音 [zɛ̃]（那是 magasin）。magazine（杂志）和 magasin（商店）容易混淆，注意区分。","et":"借自英语 magazine，而英语词来自法语 magasin，最终来自阿拉伯语 makhāzin（仓库）。","ex":[["Je lis un magazine.","我读杂志。"],["Elle achète un magazine de mode.","她买一本时尚杂志。"],["Il y a un magazine sur la table.","桌子上有一本杂志。"]],"co":[["lire un magazine","读杂志"],["un magazine de mode","时尚杂志"],["un magazine télé","电视杂志"],["un magazine mensuel","月刊"]],"sy":[["revue","courant","期刊；杂志（较学术）"],["périodique","soutenu","期刊（书面）"],["mag","familier","杂志（口语简称）"]],"fq":"中频，日常常用。","me":"magazine 以 -zine 结尾读 [zin]，magasin 以 -sin 读鼻音。","tr":{"zh":"我在候诊室里读一本杂志。","fr":"Je lis un magazine dans la salle d'attente.","alt":"En attendant, je feuillette un magazine.","note":"dans la salle d'attente = 在候诊室。"}},
 "Un miroir": {"pos":"n.m. 阳性名词，复数 miroirs","s":"镜子。se regarder dans le miroir = 照镜子。汽车后视镜是 le rétroviseur。口语和书面里也常说 une glace（镜子；也是「冰淇淋」「玻璃」）。","ipa":"[mi.ʁwaʁ]","ph":"mi [mi]；roir 读 [ʁwaʁ]，oi 读 [wa]，词尾 r 要发音。","pi":"oi 读 [wa]，词尾 r 要读出来：[mi.ʁwaʁ]。和 mirage（海市蜃楼）同源，但读音不同。","et":"来自古法语 mireor，源自动词 mirer（看），拉丁语 mirari（惊奇地看）。","ex":[["Je me regarde dans le miroir.","我照镜子。"],["Il y a un grand miroir dans l'entrée.","门厅里有一面大镜子。"],["Elle se maquille devant le miroir.","她在镜子前化妆。"]],"co":[["se regarder dans le miroir","照镜子"],["un miroir rond","圆镜子"],["un miroir de poche","随身小镜子"],["le miroir de la salle de bains","浴室镜子"]],"sy":[["glace","courant","镜子（也是玻璃、冰淇淋）"],["rétroviseur","courant","后视镜"],["psyché","soutenu","穿衣镜（书面）"]],"fq":"中高频，日常常用。","me":"miroir = mir-（看）+ -oir：「用来看的东西」。","tr":{"zh":"我在镜子里看自己。","fr":"Je me regarde dans le miroir.","alt":"Je me vois dans le miroir.","note":"se regarder dans le miroir：反身动词。"}},
 "Un morceau de": {"pos":"n.m. 阳性名词，复数 morceaux；后面用 de + 无冠词名词","s":"一块；一片；一段。un morceau de pain（一块面包）。也指音乐作品：un morceau de piano（一首钢琴曲）。manger un morceau = 吃点东西（口语）。","ipa":"[mɔʁ.so də]","ph":"mor [mɔʁ]；ceau 读 [so]，c 在 e 前读 [s]，eau 读 [o]。","pi":"复数是 morceaux（x），不是 morceaus。de 后面不加冠词：un morceau de pain，不是 de le pain。","et":"来自古法语 morsel，拉丁语 morsus（咬，咬下的一口），同源 mordre（咬）。","ex":[["Je voudrais un morceau de pastèque.","我想要一块西瓜。"],["Tu veux un morceau de gâteau ?","你要一块蛋糕吗？"],["Il écoute un morceau de piano.","他在听一首钢琴曲。"]],"co":[["un morceau de pain","一块面包"],["un morceau de sucre","一块方糖"],["manger un morceau","吃点东西"],["en morceaux","碎成块"]],"sy":[["bout","courant","一小块；一小段（口语）"],["part","courant","一份；一部分"],["tranche","courant","一片（薄片）"]],"fq":"高频，日常点餐、做饭时常用。","me":"morceau ← morsus（咬一口）：咬下来的一块。","tr":{"zh":"我拿一块奶酪。","fr":"Je prends un morceau de fromage.","alt":"Je vais prendre un petit bout de fromage.","note":"量词 + de + 无冠词名词。"}},
 "Un musée": {"pos":"n.m. 阳性名词，复数 musées","s":"博物馆；美术馆。visiter un musée = 参观博物馆；aller au musée = 去博物馆。展览是 une exposition，艺术画廊是 une galerie。","ipa":"[my.ze]","ph":"mu [my]，u 读 [y]；sée 读 [ze]，s 在元音间读 [z]，é 读 [e]。","pi":"u 读 [y]（嘴唇圆）。s 在两个元音之间读 [z]，所以是 [my.ze]，不是 [my.se]。词尾 -ée 的 e 读 [e]，不要发成两个音。","et":"来自拉丁语 museum，源自希腊语 mouseion（缪斯女神的神庙）。同源：music（音乐）。","ex":[["Je visite le musée du Louvre.","我参观卢浮宫博物馆。"],["Le musée est fermé le mardi.","博物馆星期二关门。"],["Nous allons au musée dimanche.","我们星期天去博物馆。"]],"co":[["visiter un musée","参观博物馆"],["aller au musée","去博物馆"],["un musée d'art","美术馆"],["le musée du Louvre","卢浮宫"]],"sy":[["galerie","courant","画廊（展览艺术品的店）"],["exposition","courant","展览（临时的）"]],"fq":"中高频，旅游时常用。","me":"musée 里有 Muse（缪斯）：艺术之神的家。","tr":{"zh":"我们星期天参观博物馆。","fr":"Nous visitons le musée dimanche.","alt":"Dimanche, on va visiter le musée.","note":"visiter + 地点；星期天用 dimanche，不加介词。"}},
 "Un opéra": {"pos":"n.m. 阳性名词，复数 opéras","s":"歌剧；歌剧院。可指艺术形式（un opéra de Mozart），也指建筑（l'Opéra de Paris）。aller à l'opéra = 去看歌剧、去歌剧院。","ipa":"[ɔ.pe.ʁa]","ph":"o 读开口的 [ɔ]；pé [pe]；ra [ʁa]。","pi":"é 带重音，读 [e]；词尾 a 读 [a]。开头 o 读 [ɔ]，不是英语的 [oʊ]。作建筑名时常大写：l'Opéra。","et":"来自意大利语 opera（作品），拉丁语 opus（作品）。","ex":[["Je vais à l'opéra ce soir.","今晚我去看歌剧。"],["L'Opéra de Paris est très célèbre.","巴黎歌剧院非常有名。"],["Elle adore l'opéra italien.","她很喜欢意大利歌剧。"]],"co":[["aller à l'opéra","去歌剧院；看歌剧"],["un opéra de Mozart","莫扎特的歌剧"],["l'Opéra de Paris","巴黎歌剧院"],["un chanteur d'opéra","歌剧演员"]],"sy":[["opérette","courant","轻歌剧"],["théâtre","courant","剧院（演话剧的地方）"]],"fq":"中频，谈艺术文化时使用。","me":"opéra ← opus（作品）：一件大型艺术作品。","tr":{"zh":"我和我姐姐去看歌剧。","fr":"Je vais à l'opéra avec ma sœur.","alt":"Ce soir, je vais à l'opéra avec ma sœur.","note":"aller à l'opéra；avec ma sœur = 和我姐姐。"}},
 "Un palais": {"pos":"n.m. 阳性名词，单复数同形 palais","s":"宫殿；大型豪华建筑。le palais de justice = 法院大楼。palais 还指「上颚」和「味觉」：avoir le palais fin = 味觉灵敏、挑剔。","ipa":"[pa.lɛ]","ph":"pa [pa]；lais 读 [lɛ]，ai 读 [ɛ]，词尾 s 不发音。","pi":"词尾 s 不发音。单数和复数相同：un palais, des palais。palais 和 palace（高级酒店，法语也有）读音不同。","et":"来自拉丁语 palatium（罗马帕拉蒂尼山上的宫殿）。同源：英语 palace。","ex":[["Le roi habite dans un palais.","国王住在宫殿里。"],["Nous visitons le palais de Versailles.","我们参观凡尔赛宫。"],["Ce plat plaît au palais.","这道菜合口味。"]],"co":[["un palais royal","皇宫"],["le palais de justice","法院大楼"],["le palais de l'Élysée","爱丽舍宫"],["avoir le palais fin","味觉灵敏"]],"sy":[["château","courant","城堡；庄园"],["résidence","soutenu","住所；官邸（书面）"]],"fq":"中频，旅游、新闻里常见。","me":"palais ~ palace：同源，s 不发音。","tr":{"zh":"国王住在一座很大的宫殿里。","fr":"Le roi habite dans un grand palais.","alt":"Le roi vit dans un immense palais.","note":"habiter dans + 建筑。"}},
 "Un parc": {"pos":"n.m. 阳性名词，复数 parcs","s":"公园；园区。un parc d'attractions = 游乐园；un parc national = 国家公园。parc 一般比 jardin public 大。","ipa":"[paʁk]","ph":"par [paʁ]；c 在词尾读 [k]：[paʁk]。","pi":"词尾 c 在 parc 里要读 [k]，不像 banc 里不读。「停车场」不是 parc，而是 un parking。","et":"来自古法语 parc，源自日耳曼语，原意「围起来的地」。英语 park 同源。","ex":[["Je me promène dans le parc.","我在公园散步。"],["Nous allons au parc d'attractions.","我们去游乐园。"],["Il y a un grand parc près de la gare.","火车站附近有一个大公园。"]],"co":[["se promener dans un parc","在公园散步"],["un parc d'attractions","游乐园"],["un parc national","国家公园"],["un parc naturel","自然公园"]],"sy":[["jardin public","courant","公共花园（较小）"],["square","courant","街心小公园"],["bois","courant","树林（城市附近的林地）"]],"fq":"高频，日常常用。","me":"parc = park，词尾 c 要读出来。","tr":{"zh":"星期天我们去公园。","fr":"Nous allons au parc dimanche.","alt":"Dimanche, on va faire un tour au parc.","note":"aller au parc；dimanche 无介词。"}},
 "Un quai": {"pos":"n.m. 阳性名词，复数 quais","s":"站台；码头；河岸路。火车站的 quai 是旅客等车的地方；塞纳河边的 quais 是河岸大道。Quai d'Orsay 指法国外交部。","ipa":"[ke]","ph":"qu 读 [k]；ai 读 [e]：[ke]，像英语的 key，s 不发音。","pi":"整个词读 [ke]，只有一个音节。qu 读 [k]，ai 读 [e]，词尾 s 不发音。和英语 quay 读音相同。","et":"来自高卢语的凯尔特词（意为「围栏」），经古法语 cai 进入法语。来源推测，不完全确定。","ex":[["Le train est à quai.","火车在站台上。"],["Le train part du quai numéro trois.","火车从三号站台出发。"],["Nous nous promenons sur les quais de la Seine.","我们沿着塞纳河岸散步。"]],"co":[["sur le quai","在站台上"],["le quai de la gare","火车站台"],["à quai","停靠在站台"],["les quais de la Seine","塞纳河岸"]],"sy":[["voie","courant","轨道；股道（站台号常叫 voie）"],["embarcadère","soutenu","登船处；小码头（书面）"]],"fq":"中频，坐火车、散步时常见。","me":"quai = 英语 key：读起来一样。","tr":{"zh":"火车从五号站台出发。","fr":"Le train part du quai numéro cinq.","alt":"Le train de Lyon est au quai cinq.","note":"le quai numéro cinq：数字放在名词后。"}},
 "Un scooter": {"pos":"n.m. 阳性名词，复数 scooters","s":"摩托滑板车；小型踏板摩托车（有发动机）。注意：法语 scooter 是有发动机的；没发动机、脚蹬的滑板车是 une trottinette。","ipa":"[sku.tɛʁ]","ph":"sc 读 [sk]；oo 读 [u]；ter 读 [tɛʁ]，r 要发音。","pi":"sc 在 o 前读 [sk]，不是 [s]。oo 读 [u]，不是 [ʊ]。词尾 -er 读 [ɛʁ]，r 要读。scooter 带发动机，trottinette 是脚蹬的。","et":"借自英语 scooter。","ex":[["Il a un nouveau scooter.","他有一辆新踏板车。"],["Elle va au travail en scooter.","她骑踏板摩托去上班。"],["Mon frère conduit un scooter électrique.","我哥哥骑一辆电动踏板车。"]],"co":[["aller en scooter","骑踏板摩托去"],["conduire un scooter","骑踏板车"],["un scooter électrique","电动踏板车"],["un casque de scooter","踏板车头盔"]],"sy":[["trottinette","courant","脚蹬滑板车（无发动机）"],["mobylette","courant","轻便摩托车（老牌子 Mobylette 的名字）"],["moto","courant","摩托车"]],"fq":"中频，城市交通话题里常见。","me":"scooter 有发动机；脚蹬的叫 trottinette。","tr":{"zh":"他骑踏板摩托去上班。","fr":"Il va au travail en scooter.","alt":"Il fait le trajet en scooter.","note":"aller au travail en scooter：en + 交通工具。"}},
 "Un taxi": {"pos":"n.m. 阳性名词，复数 taxis","s":"出租车。prendre un taxi = 打车；appeler un taxi = 叫车；un chauffeur de taxi = 出租车司机。","ipa":"[tak.si]","ph":"ta [tak]；xi 读 [si]：x 读 [ks]，所以整体 [tak.si]。","pi":"x 读 [ks]，不是 [z] 或 [ʃ]。重音在最后一个音节。","et":"是 taximètre（计价器）的缩写，taxi- 来自 taxe（税、费用），-mètre 表示测量。","ex":[["J'appelle un taxi.","我叫一辆出租车。"],["Je prends un taxi pour aller à la gare.","我打车去火车站。"],["Le taxi arrive dans cinq minutes.","出租车五分钟后到。"]],"co":[["prendre un taxi","打车"],["appeler un taxi","叫出租车"],["un chauffeur de taxi","出租车司机"],["une station de taxis","出租车站"]],"sy":[["VTC","courant","网约车（如 Uber 一类，有司机）"],["course","courant","一趟车程（计价的一次乘车）"]],"fq":"极高频，日常常用。","me":"taxi = taxe + mètre：按里程收费的车。","tr":{"zh":"我打车去火车站。","fr":"Je prends un taxi pour aller à la gare.","alt":"Je vais à la gare en taxi.","note":"prendre un taxi pour aller à + 地点。"}},
 "Un téléphérique": {"pos":"n.m. 阳性名词，复数 téléphériques","s":"缆车（吊在缆绳上的大车厢）。prendre le téléphérique = 坐缆车。télécabine 是小吊厢，télésiège 是座椅式，funiculaire 是轨道缆车。","ipa":"[te.le.fe.ʁik]","ph":"té [te]；lé [le]；phé [fe]，ph 读 [f]；ri [ʁi]；que 读 [k]：[te.le.fe.ʁik]。","pi":"ph 读 [f]，不是 [p]。四个音节，前三个都是 é，别漏掉一个。词尾 -que 读 [k]，e 不发音。","et":"由希腊语 tele（远）+ pherein（搬运）构成：「远距离搬运」。téléphérique 里的 -phérique 同源于「搬运」。","ex":[["Je prends le téléphérique.","我坐缆车。"],["Le téléphérique monte jusqu'au sommet.","缆车一直开到山顶。"],["Nous montons en téléphérique pour voir le glacier.","我们坐缆车上去看冰川。"]],"co":[["prendre le téléphérique","坐缆车"],["monter en téléphérique","乘缆车上山"],["la gare du téléphérique","缆车站"],["un billet de téléphérique","缆车票"]],"sy":[["télécabine","courant","小型吊厢缆车"],["télésiège","courant","座椅式缆车（滑雪场）"],["funiculaire","courant","轨道缆车（沿斜坡轨道行驶）"]],"fq":"中低频，山区旅游时才用。","me":"télé（远）+ phérique（搬运）：把人远远搬上去。","tr":{"zh":"我们坐缆车到山顶。","fr":"Nous montons au sommet en téléphérique.","alt":"On monte au sommet par le téléphérique.","note":"monter en téléphérique：en + 交通工具。"}},
 "Un théâtre": {"pos":"n.m. 阳性名词，复数 théâtres","s":"剧院；戏剧。aller au théâtre = 去剧院看戏；faire du théâtre = 演戏、学戏剧；une pièce de théâtre = 一出话剧；un coup de théâtre = 戏剧性的转折。","ipa":"[te.ɑtʁ]","ph":"th 读 [t]；é [e]；â 读 [ɑ]；tre 读 [tʁ]，词尾 e 不发音。","pi":"th 读 [t]，不是 [θ]。â 读较深的 [ɑ]。词尾 -tre 读 [tʁ]，不要加元音。拼写 théâtre 有两个重音：é 和 â。","et":"来自拉丁语 theatrum，源自希腊语 theatron（观看的地方）。","ex":[["Nous allons au théâtre.","我们去剧院。"],["Elle fait du théâtre depuis dix ans.","她演了十年戏剧。"],["La pièce commence à vingt heures au théâtre.","话剧晚上八点在剧院开演。"]],"co":[["aller au théâtre","去剧院"],["une pièce de théâtre","一出话剧"],["faire du théâtre","演戏；学戏剧"],["un coup de théâtre","戏剧性的转折"]],"sy":[["scène","courant","舞台；场景"],["salle","courant","观众席；演出厅"],["pièce","courant","剧本；一出戏"]],"fq":"中高频，谈文化娱乐时常用。","me":"théâtre ~ theatre：多一个 â 的小帽子。","tr":{"zh":"今晚我们去剧院。","fr":"Nous allons au théâtre ce soir.","alt":"Ce soir, on va au théâtre.","note":"aller au théâtre（à + le = au）。"}},
 "Un tram (tramway)": {"pos":"n.m. 阳性名词，复数 trams / tramways","s":"有轨电车。tram 是口语短说法，tramway 是全称。prendre le tram = 坐有轨电车。城市里它跑在街道的轨道上，比地铁慢，比公交准时。","ipa":"[tʁam]","ph":"tram 读 [tʁam]，m 要读，不是鼻音；全称 tramway 读 [tʁam.wɛ]。","pi":"tram 里的 am 不是鼻音，要读 [am]，所以和 temps 不同。tramway 里的 way 读 [wɛ]，不是英语 [weɪ]。","et":"借自英语 tramway（tram + way，意为「轨道路」）。","ex":[["Le tram est rapide.","电车很快。"],["Je prends le tramway pour aller au centre.","我坐有轨电车去市中心。"],["L'arrêt de tram est en face de la mairie.","电车站在市政厅对面。"]],"co":[["prendre le tram","坐有轨电车"],["un arrêt de tram","电车站"],["une ligne de tramway","有轨电车线路"],["en tramway","乘电车"]],"sy":[["tramway","courant","有轨电车（全称）"],["métro","courant","地铁"],["bus","courant","公共汽车"]],"fq":"中高频，在有电车的城市里常用。","me":"tram 读 [tʁam]，m 要闭上嘴。","tr":{"zh":"我坐有轨电车去市中心。","fr":"Je prends le tram pour aller au centre-ville.","alt":"Pour aller en centre-ville, je prends le tram.","note":"prendre le tram + pour aller + 地点。"}},
 "Un vélo": {"pos":"n.m. 阳性名词，复数 vélos","s":"自行车。faire du vélo = 骑自行车（运动或休闲）；aller à vélo = 骑车去；un vélo électrique = 电动自行车。比 bicyclette 更口语。","ipa":"[ve.lo]","ph":"vé [ve]；lo [lo]，o 读闭口的 [o]；词尾不发 s。","pi":"重音在最后一个音节。é 读 [e]，不是 [ɛ]。复数 vélos，s 不发音。「骑车去」可说 à vélo 或 en vélo，à vélo 更常见。","et":"是 vélocipède 的缩写：拉丁语 velox（快）+ pes（脚）。","ex":[["Je fais du vélo.","我骑自行车。"],["Elle va à l'école à vélo.","她骑车去上学。"],["J'ai acheté un vélo électrique.","我买了一辆电动自行车。"]],"co":[["faire du vélo","骑自行车"],["à vélo","骑车"],["un vélo électrique","电动自行车"],["louer un vélo","租一辆自行车"]],"sy":[["bicyclette","courant","自行车（略正式，也常见）"],["bécane","familier","破自行车；老车（口语）"],["VTT","courant","山地车（越野自行车）"]],"fq":"极高频，日常常用。","me":"vélo ← vélocipède：脚下快速的东西。","tr":{"zh":"我骑车去上班。","fr":"Je vais au travail à vélo.","alt":"Je vais bosser à vélo.","note":"aller à vélo：à + 交通工具（自行车）。"}},
 "Un milliard": {"pos":"n.m. 阳性名词，复数 milliards","s":"十亿（1 000 000 000）。后面接名词时用 de：un milliard d'euros。des milliards de = 数十亿、非常多。注意：法语 un billion 是 10^12（万亿），不是十亿。","ipa":"[mi.ljaʁ]","ph":"mi [mi]；lli 读 [lj]；ard 读 [aʁ]，d 不发音，r 要读。","pi":"lli 读 [lj]，不是 [li]。词尾 d 不发音，r 要读。和英语 billion 不同：法语 billion = 万亿（10^12），十亿用 milliard。","et":"由 million（百万）变形而成，加 -ard；16 世纪起使用。具体构成过程不太确定。","ex":[["Il y a des milliards d'étoiles.","有数十亿颗星星。"],["Cette entreprise gagne un milliard d'euros.","这家公司赚了十亿欧元。"],["La Terre compte plus de huit milliards d'habitants.","地球上有八十多亿人。"]],"co":[["un milliard d'euros","十亿欧元"],["des milliards de","数十亿的……"],["un milliard de personnes","十亿人"],["un milliardaire","亿万富翁"]],"sy":[["million","courant","百万"],["billion","courant","万亿（假朋友：和英语 billion 不同）"]],"fq":"中频，新闻、数据里常见。","me":"milliard = 1000 个 million；billion 反而更大。","tr":{"zh":"地球上有八十多亿人口。","fr":"La Terre compte plus de huit milliards d'habitants.","alt":"Il y a plus de huit milliards de personnes sur Terre.","note":"plus de huit milliards + de + 名词（d'habitants）。"}},
 "Un million": {"pos":"n.m. 阳性名词，复数 millions","s":"百万（1 000 000）。后面接名词要加 de：un million d'habitants。des millions de = 数百万、很多。2 million 要写 deux millions（加 s）。","ipa":"[mi.ljɔ̃]","ph":"mi [mi]；lli 读 [lj]；on 读鼻音 [ɔ̃]：[mi.ljɔ̃]。","pi":"lli 读 [lj]，不是 [li]。词尾 on 是鼻音，n 不发音。千万别说 million habitants，必须加 de。数字 1 000 000 要读 un million。","et":"来自意大利语 milione，由 mille（千）加增大后缀 -one，意为「大千」。","ex":[["Un million d'habitants.","一百万居民。"],["Cette ville a deux millions d'habitants.","这座城市有两百万居民。"],["Il a gagné un million d'euros.","他赢了一百万欧元。"]],"co":[["un million d'euros","一百万欧元"],["des millions de","数百万的……"],["un million de fois","无数次"],["un millionnaire","百万富翁"]],"sy":[["milliard","courant","十亿"],["millier","courant","约一千（millier = 大约一千）"]],"fq":"中频，谈数量、人口时常用。","me":"million = mille（千）+ 大后缀：「大千」。","tr":{"zh":"这座城市有一百万居民。","fr":"Cette ville a un million d'habitants.","alt":"Un million de personnes vivent dans cette ville.","note":"un million d'habitants：d' 在元音前省音。"}},
 "De la carbonnade": {"pos":"n.f. 阴性名词，复数 carbonnades（常用 de la carbonnade）","s":"佛兰芒炖牛肉（比利时和法国北部名菜）：牛肉和洋葱用啤酒慢炖，常配薯条。一般用 de la carbonnade（不可数）；完整名称 carbonnade flamande。","ipa":"[kaʁ.bɔ.nad]","ph":"car [kaʁ]；bo [bɔ]；nn 读一个 [n]；-ade 读 [ad]，词尾 e 不发音。","pi":"拼写有两个 n，读一个 [n]。它是阴性名词，所以用 de la（不是 du）。词尾 -ade 读 [ad]，e 不发音。","et":"来自 carbon-（炭，拉丁语 carbo）：本义「炭火烤的肉」，后来变成炖肉。这个演变细节不完全确定。","ex":[["Je mange de la carbonnade ce soir.","今晚我吃佛兰芒炖牛肉。"],["La carbonnade flamande se fait avec de la bière.","佛兰芒炖牛肉是用啤酒做的。"],["On sert la carbonnade avec des frites.","炖牛肉配薯条一起吃。"]],"co":[["une carbonnade flamande","佛兰芒炖牛肉"],["de la carbonnade de bœuf","炖牛肉"],["cuit à la bière","用啤酒炖"],["avec des frites","配薯条"]],"sy":[["ragoût","courant","炖菜（总称）"],["daube","courant","法国南部的红酒炖肉"],["bœuf bourguignon","courant","红酒炖牛肉（勃艮第名菜）"]],"fq":"低频，谈法国北部、比利时美食时才用。","me":"carbonnade = carbon + -ade：炭火上做的菜。","tr":{"zh":"今晚我们吃佛兰芒炖牛肉。","fr":"Ce soir, nous mangeons de la carbonnade.","alt":"Ce soir, on se fait une carbonnade.","note":"manger de la + 阴性不可数名词。"}},
 "De la vanille": {"pos":"n.f. 阴性名词，复数 vanilles（常不可数）","s":"香草；香草味。de la 是部分冠词，表示「一点香草」这种不可数的量。常说 à la vanille（香草味的）：une glace à la vanille。","ipa":"[va.nij]","ph":"ill 读 [ij]，所以是 va-nij；结尾 e 不发音。","pi":"ille 在这个词里读 [ij]，不是 [il]。不可数名词用 de la，不是 une。","et":"来自西班牙语 vainilla（小豆荚），源于 vaina（荚），再追溯到拉丁语 vagina（鞘）。","ex":[["J'aime la glace à la vanille.","我喜欢香草冰淇淋。"],["Je mets de la vanille dans le gâteau.","我在蛋糕里放一点香草。"]],"co":[["une glace à la vanille","香草冰淇淋"],["une gousse de vanille","一根香草荚"],["un yaourt à la vanille","香草酸奶"]],"sy":[["vanillé","courant","有香草味的（形容词）"],["parfum","courant","口味、香味"]],"fq":"中频，饮食场景常用。","me":"va-NIJ：想象香草冰淇淋 vanille，ill 读「伊」。","tr":{"zh":"我想要一个香草冰淇淋。","fr":"Je voudrais une glace à la vanille.","alt":"Je prends une glace vanille, s'il vous plaît.","note":"口味用 à la + 名词；点单时可省略成 glace vanille。"}},
 "L'Europe": {"pos":"n.f. 阴性名词（专有名词，大写）","s":"欧洲。国家、大洲名多数有冠词：l'Europe。在欧洲用 en Europe，从欧洲来用 d'Europe。形容词 européen / européenne。","ipa":"[ø.ʁɔp]","ph":"eu 读 [ø]；r 是小舌音 [ʁ]；结尾 pe 的 e 不发音。L' 是 la 的省音（元音前）。","pi":"eu 不读「尤」[ju]，读圆唇的 [ø]。结尾 e 不发音，只发 [ɔp]。","et":"来自拉丁语 Europa，源自希腊语 Eurōpē（神话中的欧罗巴公主）。","ex":[["La France est en Europe.","法国在欧洲。"],["Il voyage souvent en Europe.","他经常在欧洲旅行。"],["Elle est d'origine européenne.","她有欧洲血统。"]],"co":[["en Europe","在欧洲"],["l'Union européenne","欧盟"],["l'Europe de l'Est / de l'Ouest","东欧 / 西欧"]],"sy":[["le Vieux Continent","courant","「旧大陆」，指欧洲"]],"fq":"高频，新闻和旅行常见。","me":"L'Eu-rope：eu 圆着嘴读 [ø]，像「额」加圆唇。","tr":{"zh":"我明年想去欧洲旅行。","fr":"L'année prochaine, je veux voyager en Europe.","alt":"L'an prochain, j'aimerais partir en Europe.","note":"阴性大洲用 en 表示「在、去」。"}},
 "L'histoire": {"pos":"n.f. 阴性名词，复数 histoires","s":"历史（学科、过去）；故事；事情。une histoire 常指「故事」：raconter une histoire。口语里 une histoire 也可以是「麻烦事」：Quelle histoire !。","ipa":"[is.twaʁ]","ph":"h 不发音（h muet），所以 la 要省音成 l'histoire；oi 读 [wa]；结尾 e 不发音。","pi":"h 不发音，不要读成 [h]。oi 读 [wa]。一个词有两义：历史、故事，看语境。","et":"来自拉丁语 historia，源自希腊语 historía（探究、调查）。英语 history 和 story 同源。","ex":[["J'aime l'histoire.","我喜欢历史。"],["Raconte-moi une histoire, papa.","爸爸，给我讲个故事。"],["C'est une drôle d'histoire.","这是件奇怪的事。"]],"co":[["le cours d'histoire","历史课"],["raconter une histoire","讲故事"],["l'histoire de France","法国史"],["une histoire d'amour","爱情故事"]],"sy":[["récit","soutenu","叙述、故事"],["conte","courant","童话、民间故事"],["passé","courant","过去"]],"fq":"极高频，日常常用。","me":"histoire = history + story：一个词装下两个英文词。","tr":{"zh":"我最喜欢的课是历史课。","fr":"Mon cours préféré, c'est le cours d'histoire.","alt":"Ma matière préférée, c'est l'histoire.","note":"matière = 学科；histoire 前面用 l'（h 不发音）。"}},
 "La banlieue": {"pos":"n.f. 阴性名词，复数 banlieues","s":"郊区；大城市周边的市镇。la banlieue parisienne = 巴黎郊区。在法国，这个词有时带社会色彩（工薪阶层居住区），但字面只是「城市外围」。","ipa":"[bɑ̃.ljø]","ph":"an 读 [ɑ̃]；ieu 读 [jø]；结尾 e 不发音。","pi":"ieu 读 [jø]，不是「伊尤」。banlieue 是阴性。说「在郊区」用 en banlieue，不是 dans la banlieue（口语里 en banlieue 更常见）。","et":"由 ban（辖区的法令）+ lieue（古里，距离单位）构成，指城市周围约一里格范围内的地带。","ex":[["Il habite en banlieue.","他住在郊区。"],["Je prends le RER pour aller en banlieue.","我坐区域快铁去郊区。"]],"co":[["habiter en banlieue","住在郊区"],["la banlieue parisienne","巴黎郊区"],["le train de banlieue","市郊火车"]],"sy":[["périphérie","soutenu","外围、边缘"],["faubourg","littéraire","（旧时）城郊"],["centre-ville","courant","反义：市中心"]],"fq":"中高频，谈居住时常用。","me":"ban + lieue：离城「一里」的地方，就是郊区。","tr":{"zh":"我住在郊区，但在市中心工作。","fr":"J'habite en banlieue mais je travaille en centre-ville.","alt":"J'habite en banlieue, et je travaille dans le centre.","note":"habiter en banlieue；与 centre-ville 对比。"}},
 "La banque": {"pos":"n.f. 阴性名词，复数 banques","s":"银行；（血液、数据等的）库。aller à la banque = 去银行。une banque de données = 数据库。","ipa":"[bɑ̃k]","ph":"an 读鼻化音 [ɑ̃]；qu 读 [k]；结尾 -ue 不发音。","pi":"qu 读 [k]，不读 [kw]。结尾 e 不发音，只有一个音节 [bɑ̃k]。","et":"借自意大利语 banca（长凳、兑换商的柜台）。同族：banc（长凳）、banquier（银行家）。","ex":[["Je dois aller à la banque.","我得去银行。"],["Ma carte de banque ne marche pas.","我的银行卡不能用。"]],"co":[["aller à la banque","去银行"],["un compte en banque","银行账户"],["une carte bancaire","银行卡"],["la banque est fermée","银行关门了"]],"sy":[["établissement bancaire","soutenu","银行机构"],["agence","courant","（银行）网点"]],"fq":"高频，生活办事常用。","me":"banque ≈ 长凳 banc：最早的银行家坐在长凳上换钱。","tr":{"zh":"银行下午五点关门。","fr":"La banque ferme à cinq heures de l'après-midi.","alt":"La banque ferme à 17 h.","note":"时间 à + 小时；banque 阴性。"}},
 "La campagne": {"pos":"n.f. 阴性名词，复数 campagnes","s":"乡下；田野。à la campagne = 在乡下。另有「运动、宣传活动」义：une campagne électorale（竞选）、une campagne de pub（广告宣传）。","ipa":"[kɑ̃.paɲ]","ph":"an 读 [ɑ̃]；gn 读 [ɲ]（类似「尼」的鼻音）；结尾 e 不发音。","pi":"gn 读 [ɲ]，不是 [gn]。在乡下用 à la campagne，不用 dans。","et":"来自拉丁语 campania（平原、开阔地），与 champ（田）、champagne 同族。","ex":[["J'aime le calme de la campagne.","我喜欢乡下的宁静。"],["Ils ont une maison à la campagne.","他们在乡下有一栋房子。"]],"co":[["à la campagne","在乡下"],["vivre à la campagne","住在乡下"],["une campagne électorale","竞选活动"],["la campagne française","法国乡村"]],"sy":[["champs","courant","田野"],["province","courant","外省（与巴黎相对）"],["ville","courant","反义：城市"]],"fq":"高频，谈居住和假期常用。","me":"campagne ← champ：有田野的地方。","tr":{"zh":"周末我们去乡下看奶奶。","fr":"Ce week-end, on va voir mamie à la campagne.","alt":"Ce week-end, nous allons chez ma grand-mère à la campagne.","note":"à la campagne 表示「在 / 到乡下」。"}},
 "La cuisine": {"pos":"n.f. 阴性名词，复数 cuisines","s":"厨房；烹饪；菜系。la cuisine française = 法国菜。faire la cuisine = 做饭。动词 cuisiner 是「烹饪」。","ipa":"[kɥi.zin]","ph":"ui 读 [ɥi]（先圆唇再发 i）；s 在元音之间读 [z]；结尾 e 不发音。","pi":"s 读 [z]，不是 [s]。ui 不是「库伊」，要快速滑过去。一个词三种意思：厨房、做饭、菜系。","et":"来自拉丁语 coquina（厨房），源于 coquere（煮）。同族：cuire、cuisinier。","ex":[["La cuisine italienne est délicieuse.","意大利菜很好吃。"],["Je suis dans la cuisine.","我在厨房里。"],["Qui fait la cuisine ce soir ?","今晚谁做饭？"]],"co":[["faire la cuisine","做饭"],["la cuisine française","法国菜"],["une cuisine équipée","带设备的厨房"],["un livre de cuisine","菜谱"]],"sy":[["gastronomie","soutenu","美食文化"],["cuisiner","courant","烹饪（动词）"],["cantine","courant","食堂"]],"fq":"极高频，日常常用。","me":"cuisine = 厨房 = 菜：[kɥi-zin]，像「奎—精」。","tr":{"zh":"我爸爸做饭做得很好。","fr":"Mon père fait très bien la cuisine.","alt":"Mon père cuisine très bien.","note":"faire la cuisine = cuisiner。"}},
 "La culture": {"pos":"n.f. 阴性名词，复数 cultures","s":"文化；教养；栽培（种植）。la culture générale = 常识、通识。la culture du riz = 种稻。形容词 culturel(le)。","ipa":"[kyl.tyʁ]","ph":"u 读 [y]（嘴圆，发「衣」）；两个 u 都读 [y]；r 是小舌音。","pi":"u 读 [y]，不是「乌」[u]。结尾 e 不发音。","et":"来自拉丁语 cultura（耕作、培育），源于 colere（耕种；培养）。同族：cultiver、agriculture。","ex":[["La culture française est riche.","法国文化很丰富。"],["Il a beaucoup de culture générale.","他的常识很丰富。"],["Cette région vit de la culture du vin.","这个地区靠种葡萄酿酒为生。"]],"co":[["la culture générale","常识、通识"],["un centre culturel","文化中心"],["la culture populaire","大众文化"],["la culture du blé","小麦种植"]],"sy":[["civilisation","soutenu","文明"],["coutumes","courant","习俗"],["éducation","courant","教养、教育"]],"fq":"高频，学习和新闻常见。","me":"culture ← colere：「耕耘」心田，就是文化。","tr":{"zh":"我想多了解法国文化。","fr":"Je voudrais mieux connaître la culture française.","alt":"Je veux en savoir plus sur la culture française.","note":"connaître + 名词；mieux = 更好地。"}},
 "La droite": {"pos":"n.f. 阴性名词，复数 droites","s":"右边；右侧；（政治上的）右派；直线。à droite = 向右 / 在右边。tout droit 是「一直走」，不是右边。","ipa":"[dʁwat]","ph":"d + r + oi：oi 读 [wa]；t 要发音 [t]；结尾 e 不发音。","pi":"droit(e) 是「右」还是「直」要看搭配：à droite 向右，tout droit 直走。droite 里的 t 要发音。","et":"来自拉丁语 directus（笔直的），经古法语演变。「右手」被视为「正确的、直的」一边。同族：droit（权利；直的）、direct。","ex":[["Tourne à droite.","向右转。"],["La pharmacie est sur votre droite.","药店在您的右手边。"],["Il vote à droite.","他投右派的票。"]],"co":[["à droite","向右、在右边"],["tourner à droite","右转"],["sur la droite","在右侧"],["tout droit","一直走（直行）"]],"sy":[["à gauche","courant","反义：左边"],["côté droit","courant","右侧"]],"fq":"极高频，问路必备。","me":"droite ≈ direct：向右就是「对的」那边。","tr":{"zh":"在红绿灯那里向右转。","fr":"Au feu rouge, tourne à droite.","alt":"Au feu, tu tournes à droite.","note":"à droite 不加冠词；à + 方向。"}},
 "La gauche": {"pos":"n.f. 阴性名词，复数 gauches","s":"左边；左侧；（政治上的）左派。à gauche = 向左 / 在左边。gauche 作形容词还有「笨拙的」义。","ipa":"[goʃ]","ph":"au 读 [o]；ch 读 [ʃ]（类似「舍」）；结尾 e 不发音。","pi":"au 读 [o]，不是「奥乌」。ch 读 [ʃ]。左边 gauche 是阴性词，à gauche 不加冠词。","et":"来自动词 gauchir（歪斜、扭曲）。词的更早来源不确定。同族：gaucher（左撇子）、gauchiste（左派分子）。","ex":[["Tourne à gauche.","向左转。"],["La boulangerie est sur votre gauche.","面包店在您的左手边。"],["Il écrit de la main gauche.","他用左手写字。"]],"co":[["à gauche","向左、在左边"],["sur la gauche","在左侧"],["tourner à gauche","左转"],["un gaucher / une gauchère","左撇子"]],"sy":[["à droite","courant","反义：右边"],["côté gauche","courant","左侧"]],"fq":"极高频，问路必备。","me":"gauche [goʃ]：左手是「歪」的那一边。","tr":{"zh":"银行在街的左边。","fr":"La banque est à gauche dans la rue.","alt":"La banque, c'est sur la gauche de la rue.","note":"est à gauche：位置用 être à + 方位。"}},
 "La mer": {"pos":"n.f. 阴性名词，复数 mers","s":"海；大海。aller à la mer = 去海边。la mer et la plage：海与海滩。注意同音词：mer（海）、mère（母亲）、maire（市长）。","ipa":"[mɛʁ]","ph":"e 在 r 前读 [ɛ]；结尾 r 读小舌音 [ʁ]，要发出来。","pi":"mer / mère / maire 三个词同音，靠拼写和语境分。结尾 r 要发音，不要吞掉。","et":"来自拉丁语 mare（海）。同族：marin（水手）、maritime（海的）、outre-mer（海外）。","ex":[["La mer est bleue.","大海是蓝色的。"],["Nous allons à la mer cet été.","今年夏天我们去海边。"],["Il y a beaucoup de poissons dans la mer.","海里有很多鱼。"]],"co":[["au bord de la mer","在海边"],["la mer Méditerranée","地中海"],["partir à la mer","去海边度假"],["un fruit de mer","海鲜（贝类）"]],"sy":[["océan","courant","大洋（比 mer 更大）"],["littoral","soutenu","沿海地带"]],"fq":"极高频，日常常用。","me":"mer = mère = maire：三个词同一个音 [mɛʁ]。","tr":{"zh":"我们家离海边只有十分钟。","fr":"Notre maison est à dix minutes de la mer.","alt":"On habite à dix minutes de la mer.","note":"à + 时间 + de + 地点 = 离……多远。"}},
 "La montagne": {"pos":"n.f. 阴性名词，复数 montagnes","s":"山；山区。à la montagne = 在山里 / 去山里。les montagnes 可指山脉。形容词 montagneux。","ipa":"[mɔ̃.taɲ]","ph":"on 读 [ɔ̃]；gn 读 [ɲ]；结尾 e 不发音。","pi":"gn 读 [ɲ]，不是 [gn]。不要把 on 读成「昂」。在山里用 à la montagne（不是 dans）。","et":"来自拉丁语 montanea，源于 mons, montis（山）。同族：mont（山，如 Mont-Blanc）、monter（上）。","ex":[["Je vais à la montagne.","我去山里。"],["En hiver, on fait du ski à la montagne.","冬天我们在山里滑雪。"]],"co":[["à la montagne","在山里、去山里"],["faire de la montagne","爬山、登山"],["une randonnée en montagne","山地徒步"],["la haute montagne","高山地区"]],"sy":[["mont","soutenu","山（多用于专名）"],["colline","courant","小山丘"],["alpes","courant","阿尔卑斯山（专名）"]],"fq":"高频，假期和旅行常用。","me":"mon-TA-gne：mont（山）+ gne。","tr":{"zh":"夏天我喜欢在山里散步。","fr":"L'été, j'aime me promener à la montagne.","alt":"En été, j'adore marcher à la montagne.","note":"l'été / en été 都可以说「夏天」。"}},
 "La nourriture": {"pos":"n.f. 阴性名词，不可数（一般不加复数）","s":"食物；饮食。泛指吃的东西：la nourriture est bonne ici。可以指一个地方的饭菜质量，也可以指总体饮食。动词是 nourrir（喂养）。","ipa":"[nu.ʁi.tyʁ]","ph":"ou 读 [u]；ri 读 [ʁi]；u 读 [y]；结尾 e 不发音。","pi":"ou [u] 与 u [y] 在同一个词里出现，注意区分。r 是小舌音。不要和 aliment（某种食物）混用：la nourriture 是总称。","et":"由动词 nourrir + 后缀 -ure 构成，nourrir 来自拉丁语 nutrire（喂养）。同族：nourrisson（婴儿）、nutrition。","ex":[["La nourriture est bonne ici.","这里的食物很好吃。"],["Ils achètent de la nourriture pour le chien.","他们给狗买吃的。"]],"co":[["acheter de la nourriture","买吃的"],["la nourriture bio","有机食品"],["la nourriture pour chiens","狗粮"],["manquer de nourriture","缺少食物"]],"sy":[["repas","courant","一顿饭"],["aliment","soutenu","某种食物（可数）"],["bouffe","familier","吃的、伙食"]],"fq":"高频，日常常用。","me":"nourriture ← nourrir：给人「营养」的东西。","tr":{"zh":"这家餐厅的食物很不错。","fr":"La nourriture de ce restaurant est très bonne.","alt":"On mange très bien dans ce restaurant.","note":"nourriture 不可数，用 de la / la。"}},
 "La plage": {"pos":"n.f. 阴性名词，复数 plages","s":"海滩；沙滩。aller à la plage = 去海滩。plage 还可指「（时间、价格的）区间」：une plage horaire（时间段）。","ipa":"[plaʒ]","ph":"pl 连读；a 读 [a]；g 在 e 前读 [ʒ]（类似「日」）；结尾 e 不发音。","pi":"ge 里的 g 读 [ʒ]，不是 [g]。plage 里 a 读 [a]，不是 [ɑ]。","et":"借自意大利语（piaggia 一类的词，指斜坡、岸边），更早的来源我不确定。","ex":[["Je vais à la plage.","我去海边。"],["Nous restons sur la plage jusqu'au soir.","我们在沙滩上待到晚上。"]],"co":[["aller à la plage","去海滩"],["sur la plage","在沙滩上"],["une serviette de plage","沙滩巾"],["une plage horaire","时间段"]],"sy":[["bord de mer","courant","海边"],["rivage","soutenu","岸边"],["littoral","soutenu","沿海地带"]],"fq":"高频，夏天和假期常用。","me":"plage [plaʒ]：像「拉雨日」，g 读「日」。","tr":{"zh":"天气很好，我们去海滩吧。","fr":"Il fait beau, allons à la plage !","alt":"Il fait beau, on va à la plage ?","note":"allons à = 我们去吧（建议）。"}},
 "La poste": {"pos":"n.f. 阴性名词，复数 postes（但 la Poste 作机构时大写）","s":"邮局；邮政。aller à la poste = 去邮局。La Poste（大写）是法国邮政公司。不要和 un poste（职位；电视机；分机）混淆，一个阴性一个阳性。","ipa":"[pɔst]","ph":"o 读 [ɔ]；s 和 t 都要发音 [st]；结尾 e 不发音。","pi":"la poste（邮局，阴性）与 le poste（职位、分机，阳性）读音相同、意义不同。s 要发音，不是沉默。","et":"借自意大利语 posta，原指沿路设置的驿站。同族：postal、poster（寄出）、timbre-poste。","ex":[["Je vais à la poste pour envoyer une lettre.","我去邮局寄信。"],["La poste ferme à midi le samedi.","邮局周六中午关门。"]],"co":[["aller à la poste","去邮局"],["un bureau de poste","邮局（营业所）"],["la poste restante","留局待取"],["la carte postale","明信片"]],"sy":[["bureau de poste","courant","邮局（正式说法）"],["facteur","courant","邮递员"]],"fq":"高频，办事场景常用。","me":"la poste（阴）= 邮局；le poste（阳）= 岗位。","tr":{"zh":"我要去邮局寄一个包裹。","fr":"Je dois aller à la poste pour envoyer un colis.","alt":"Je vais à la poste envoyer un colis.","note":"pour + 动词原形 = 为了……。"}},
 "Une bibliothèque": {"pos":"n.f. 阴性名词，复数 bibliothèques","s":"图书馆；书架、书柜。à la bibliothèque = 在图书馆。une bibliothèque 也可以是家里的书柜。图书馆里借书的人叫 un lecteur。","ipa":"[bi.bli.jɔ.tɛk]","ph":"b-i-b-l-i-o-t-h-è-q-u-e：th 读 [t]；è 读 [ɛ]；qu 读 [k]；结尾 e 不发音。","pi":"不要把 bibliothèque 和 librairie（书店）搞混：图书馆 = bibliothèque，书店 = librairie。th 读 [t]。","et":"来自希腊语 biblion（书）+ thêkê（存放处、盒子）。同族：bibliographie。","ex":[["J'étudie à la bibliothèque.","我在图书馆学习。"],["Il y a une grande bibliothèque dans le salon.","客厅里有一个大书柜。"]],"co":[["emprunter un livre à la bibliothèque","从图书馆借书"],["une carte de bibliothèque","借书证"],["une bibliothèque municipale","市立图书馆"],["rendre un livre","还书"]],"sy":[["médiathèque","courant","媒体图书馆（含影音）"],["librairie","courant","书店（易混淆）"]],"fq":"高频，学习和生活常用。","me":"biblio = 书 + thèque = 存放处：存书的地方。","tr":{"zh":"我每个星期六都去图书馆。","fr":"Je vais à la bibliothèque tous les samedis.","alt":"Tous les samedis, je passe à la bibliothèque.","note":"tous les samedis = 每个星期六。"}},
 "Une boutique": {"pos":"n.f. 阴性名词，复数 boutiques","s":"小店；专卖店；精品店。通常指卖衣服、礼品等的小店。une boutique de mode = 时装店。较大的商店用 magasin。","ipa":"[bu.tik]","ph":"ou 读 [u]；qu 读 [k]；结尾 e 不发音。","pi":"qu 读 [k]。ou 读 [u]，不要读成 [bo]。","et":"来自古普罗旺斯语 botica，源于拉丁语 apotheca（仓库），再往前是希腊语 apothêkê。同族：apothicaire。","ex":[["C'est une petite boutique.","这是一家小店。"],["Elle travaille dans une boutique de vêtements.","她在一家服装店工作。"]],"co":[["une boutique de mode","时装店"],["une boutique en ligne","网店"],["fermer boutique","关门歇业"],["une boutique de souvenirs","纪念品店"]],"sy":[["magasin","courant","商店（更泛指，规模不限）"],["échoppe","littéraire","小店铺"],["commerce","courant","店铺、商业"]],"fq":"中高频，逛街时常见。","me":"boutique ← 仓库：小店就是一个小仓库。","tr":{"zh":"我在一家小店里买了一条围巾。","fr":"J'ai acheté une écharpe dans une petite boutique.","alt":"J'ai pris une écharpe dans une petite boutique.","note":"acheter qqch dans une boutique；过去时用 j'ai acheté。"}},
 "Une carte postale": {"pos":"n.f. 阴性名词，复数 cartes postales","s":"明信片。envoyer une carte postale = 寄明信片。carte 本身是「卡片、地图、菜单」，postale 是形容词，随 carte 变阴性。","ipa":"[kaʁt pɔs.tal]","ph":"carte：a [a]，r [ʁ]，t 发音；postale：s 与 t 都发音，结尾 e 不发音。","pi":"postale 是阴性（因为 carte 是阴性）。复数是 des cartes postales，两个词都加 s。","et":"carte 来自拉丁语 charta（纸），postale 来自 poste（邮政）。","ex":[["J'envoie une carte postale.","我寄一张明信片。"],["Elle m'a écrit une carte postale de Nice.","她从尼斯给我寄来一张明信片。"]],"co":[["envoyer une carte postale","寄明信片"],["recevoir une carte postale","收到明信片"],["un timbre pour carte postale","明信片用的邮票"],["une jolie carte postale","一张漂亮的明信片"]],"sy":[["carte","courant","卡片、明信片（简称）"],["lettre","courant","信件"],["souvenir","courant","纪念品"]],"fq":"中频，旅行场景常见。","me":"carte（卡片）+ postale（邮政的）：邮局的卡片。","tr":{"zh":"我从巴黎给你寄一张明信片。","fr":"Je t'envoie une carte postale de Paris.","alt":"Je vais t'envoyer une carte postale de Paris.","note":"t'envoie：te 省音成 t'；de Paris = 从巴黎。"}},
 "Une cathédrale": {"pos":"n.f. 阴性名词，复数 cathédrales","s":"大教堂；主教座堂。如巴黎圣母院 Notre-Dame、兰斯大教堂。cathédrale 比普通教堂 église 更大、更重要。","ipa":"[ka.te.dʁal]","ph":"th 读 [t]；é 读 [e]；dr 连读 [dʁ]；结尾 -ale 读 [al]，e 不发音。","pi":"th 读 [t]，不读 [θ]。重音在最后一个音节 -dral。","et":"来自拉丁语 cathedralis（与主教座位有关），源自 cathedra（座椅），再追溯到希腊语 kathédra。","ex":[["La cathédrale est très grande.","大教堂非常高大。"],["On visite la cathédrale de Chartres.","我们参观沙特尔大教堂。"]],"co":[["visiter une cathédrale","参观大教堂"],["la cathédrale Notre-Dame","巴黎圣母院"],["une cathédrale gothique","哥特式大教堂"],["monter en haut de la cathédrale","登上大教堂顶"]],"sy":[["église","courant","教堂（泛指，更小）"],["basilique","soutenu","圣殿、大殿"],["chapelle","courant","小礼拜堂"]],"fq":"中频，旅游场景常见。","me":"cathédrale ← cathedra（主教的座位）：主教坐镇的教堂。","tr":{"zh":"我们明天去参观大教堂。","fr":"Demain, nous allons visiter la cathédrale.","alt":"Demain, on va voir la cathédrale.","note":"aller + 原形 = 近将来时。"}},
 "Une destination": {"pos":"n.f. 阴性名词，复数 destinations","s":"目的地；旅行去的地方。une destination touristique = 旅游目的地。à destination de Paris = 开往巴黎的。","ipa":"[dɛs.ti.na.sjɔ̃]","ph":"tion 读 [sjɔ̃]；des 读 [dɛs]；最后的 n 不发音，只表示鼻化。","pi":"-tion 读 [sjɔ̃]，不是 [tion]。s 在 des 里读 [s]。","et":"来自拉丁语 destinatio，源于 destinare（确定、指定）。同族：destiner、destin（命运）。","ex":[["C'est ma destination préférée.","这是我最喜欢的目的地。"],["Le train à destination de Lyon part à 8 h.","开往里昂的火车 8 点出发。"]],"co":[["une destination touristique","旅游目的地"],["à destination de","开往……的、前往……"],["arriver à destination","抵达目的地"],["choisir sa destination","选择目的地"]],"sy":[["but","courant","目的、终点"],["lieu","courant","地点"],["arrivée","courant","到达"]],"fq":"中频，旅行常用。","me":"destination ≈ English destination，只是 -tion 读 [sjɔ̃]。","tr":{"zh":"这趟列车的目的地是马赛。","fr":"La destination de ce train est Marseille.","alt":"Ce train va à Marseille.","note":"à destination de + 地名：开往。"}},
 "Une direction": {"pos":"n.f. 阴性名词，复数 directions","s":"方向；管理层、领导；指导。dans quelle direction ? = 往哪个方向？la direction d'une entreprise = 公司管理层。","ipa":"[di.ʁɛk.sjɔ̃]","ph":"di + rec + tion：tion 读 [sjɔ̃]；c 读 [k]；结尾鼻化音。","pi":"-tion 读 [sjɔ̃]。不要把 direction 读成 [di-rek-tion]。","et":"来自拉丁语 directio，源于 dirigere（引导）。同族：diriger（指挥）、directeur（主管）、direct。","ex":[["C'est la bonne direction.","这个方向是对的。"],["Le métro va en direction de la gare.","地铁开往火车站方向。"],["La direction a pris une décision.","领导层做了决定。"]],"co":[["en direction de","朝……方向"],["dans la bonne direction","朝正确的方向"],["changer de direction","改变方向"],["la direction générale","总部（总管理层）"]],"sy":[["sens","courant","方向、意义"],["orientation","soutenu","朝向、定位"],["chef","courant","领导（人）"]],"fq":"高频，问路和工作常用。","me":"direction ← diriger：往哪个方向「指」。","tr":{"zh":"请问去火车站是哪个方向？","fr":"Excusez-moi, quelle direction pour la gare ?","alt":"Pardon, c'est par où, la gare ?","note":"quelle direction pour…：问路用。"}},
 "Une école": {"pos":"n.f. 阴性名词，复数 écoles","s":"学校（尤指小学）；各类专门学校。aller à l'école = 上学。école primaire = 小学。大学用 université，中学用 collège / lycée。","ipa":"[e.kɔl]","ph":"é 读 [e]；c 读 [k]；o 读 [ɔ]；l 要发音。une école 要连读：[yn‿e.kɔl]。","pi":"école 以元音开头，所以 une école 要连读，la 要变成 l'école。不要把 é 读成 [ɛ]。","et":"来自拉丁语 schola，源于希腊语 skholê（闲暇；学习）。英语 school 同源。","ex":[["Mon enfant va à l'école.","我的孩子去上学。"],["L'école commence à huit heures et demie.","学校八点半开始上课。"],["C'est une bonne école de cuisine.","这是一所好的烹饪学校。"]],"co":[["aller à l'école","上学"],["une école primaire","小学"],["une école de langues","语言学校"],["à la sortie de l'école","放学时"]],"sy":[["collège","courant","初中"],["lycée","courant","高中"],["classe","courant","班级、教室"]],"fq":"极高频，日常常用。","me":"école ← schola ← skholê：「闲暇」才有时间学习。","tr":{"zh":"我儿子明天不去上学。","fr":"Mon fils ne va pas à l'école demain.","alt":"Mon fils n'a pas école demain.","note":"n'a pas école：口语里「不用上学」。"}},
 "Une église": {"pos":"n.f. 阴性名词，复数 églises","s":"教堂。较小的教堂、城镇或村里的教堂。l'Église（大写）指教会、天主教会。cathédrale 是更大的主教座堂。","ipa":"[e.gliz]","ph":"é 读 [e]；g 读 [g]；s 在 i 和 e 之间读 [z]；结尾 e 不发音。une église 连读。","pi":"s 读 [z]，不是 [s]。é 读 [e]，不是 [ɛ]。","et":"来自拉丁语 ecclesia，源于希腊语 ekklêsia（集会）。","ex":[["L'église est ancienne.","教堂很古老。"],["On se retrouve devant l'église à midi.","中午我们在教堂前面见。"]],"co":[["aller à l'église","去教堂"],["une vieille église","一座古老的教堂"],["le clocher de l'église","教堂钟楼"],["se marier à l'église","在教堂结婚"]],"sy":[["cathédrale","courant","大教堂"],["chapelle","courant","小礼拜堂"],["temple","courant","新教教堂 / 寺庙"]],"fq":"中高频，旅行和文化常见。","me":"église：é-gliz，s 读「z」。","tr":{"zh":"那座教堂建于十二世纪。","fr":"Cette église date du XIIe siècle.","alt":"Cette église a été construite au XIIe siècle.","note":"dater de = 追溯到；XIIe 读 douzième。"}},
 "Une expérience": {"pos":"n.f. 阴性名词，复数 expériences","s":"经验；经历；体验；实验。avoir de l'expérience = 有经验。une expérience scientifique = 科学实验。une belle expérience = 一次美好的体验。","ipa":"[ɛk.spe.ʁjɑ̃s]","ph":"ex 读 [ɛk]；p 读 [p]；ien 读 [jɑ̃]；结尾 ce 读 [s]。","pi":"ex- 在这里读 [ɛk]，接着是 sp [sp]。-ence 读 [ɑ̃s]，不是 [ɛns]。","et":"来自拉丁语 experientia（试验、经验），源于 experiri（试，尝试）。同族：expert、expérimenter。","ex":[["C'est une bonne expérience.","这是个好经历。"],["Il a dix ans d'expérience.","他有十年经验。"],["On fait une expérience en classe de chimie.","我们在化学课上做实验。"]],"co":[["avoir de l'expérience","有经验"],["une expérience professionnelle","工作经历"],["faire une expérience","做实验"],["une première expérience","第一次经历"]],"sy":[["pratique","courant","实践"],["épreuve","soutenu","考验、磨难"],["essai","courant","尝试、试验"]],"fq":"高频，工作和生活常用。","me":"expérience ≈ experience，ien 读 [jɑ̃]。","tr":{"zh":"我在法国有两年的工作经验。","fr":"J'ai deux ans d'expérience professionnelle en France.","alt":"Je travaille en France depuis deux ans.","note":"avoir + 数量 + d'expérience。"}},
 "Une exposition": {"pos":"n.f. 阴性名词，复数 expositions","s":"展览；展出；（朝向）日照。une exposition d'art = 艺术展。aller voir une exposition = 看展览。还可指房屋朝向：exposition sud。","ipa":"[ɛk.spo.zi.sjɔ̃]","ph":"ex 读 [ɛk]；s 在元音之间读 [z]；tion 读 [sjɔ̃]。","pi":"s 读 [z]，不是 [s]。-tion 读 [sjɔ̃]。展览是 exposition，不是 exhibition。","et":"来自拉丁语 expositio，源于 exponere（摆出、陈列）。同族：exposer、exposé（报告）。","ex":[["C'est une exposition d'art.","这是一个艺术展览。"],["L'exposition est ouverte jusqu'au 30 juin.","展览开放到 6 月 30 日。"]],"co":[["une exposition de peinture","绘画展"],["visiter une exposition","参观展览"],["une exposition temporaire","临时展览"],["l'entrée de l'exposition","展览入口"]],"sy":[["salon","courant","展销会、博览会"],["vernissage","courant","开幕式"],["musée","courant","博物馆"]],"fq":"中频，文化活动常见。","me":"exposition ← exposer：把东西「摆出来」给人看。","tr":{"zh":"这个周末有一个摄影展。","fr":"Il y a une exposition de photos ce week-end.","alt":"Ce week-end, il y a une expo photo.","note":"expo 是 exposition 的口语缩写。"}},
 "Une fontaine": {"pos":"n.f. 阴性名词，复数 fontaines","s":"喷泉；泉水；饮水处。une fontaine publique 是街边的公共水龙头或水池。la fontaine de Trevi 是罗马的特雷维喷泉。","ipa":"[fɔ̃.tɛn]","ph":"on 读 [ɔ̃]；ai + n 读 [ɛn]（因为后面还有元音 e，n 要发出来）；结尾 e 不发音。","pi":"fon 是鼻音 [fɔ̃]，tai 是 [tɛn]，n 要发出来，因为后面有 e。","et":"来自拉丁语 fontana，源于 fons, fontis（泉水）。同族：font（洗礼池）、fonts baptismaux。","ex":[["Il y a une fontaine dans le parc.","公园里有一座喷泉。"],["Je remplis ma bouteille à la fontaine.","我在饮水处灌水瓶。"]],"co":[["une fontaine publique","公共喷泉 / 水龙头"],["une fontaine à eau","饮水机"],["la fontaine de la place","广场上的喷泉"],["jeter une pièce dans la fontaine","往喷泉里扔硬币"]],"sy":[["source","courant","泉源"],["jet d'eau","courant","水柱喷泉"],["bassin","courant","水池"]],"fq":"中频，城市景点常见。","me":"fontaine ← fons：「泉」的拉丁词，font- 和 fontaine 同根。","tr":{"zh":"我们在广场的喷泉旁见面。","fr":"On se retrouve près de la fontaine sur la place.","alt":"Rendez-vous à la fontaine de la place.","note":"se retrouver = 约见面。"}},
 "Une galette": {"pos":"n.f. 阴性名词，复数 galettes","s":"咸可丽饼（荞麦薄饼，galette bretonne）；也指圆形扁平的饼。la galette des Rois 是主显节吃的国王饼。Crêpe 通常是甜的，galette 通常是咸的。","ipa":"[ga.lɛt]","ph":"ga 读 [ga]；le 读 [lɛ]（因为后面 tt）；tt 读 [t]；结尾 e 不发音。","pi":"注意区分：galette（咸，荞麦）与 crêpe（甜，小麦）。tt 读一个 [t]。","et":"来自 galet（光滑的小石子）+ -ette，形容扁平圆润的形状。","ex":[["Les galettes bretonnes ont souvent un œuf et du fromage.","布列塔尼咸饼常配蛋和奶酪。"],["En janvier, on mange la galette des Rois.","一月我们吃国王饼。"]],"co":[["une galette bretonne","布列塔尼荞麦饼"],["la galette des Rois","国王饼"],["une galette complète","全配咸饼（火腿、蛋、奶酪）"],["une galette de sarrasin","荞麦饼"]],"sy":[["crêpe","courant","可丽饼（多为甜）"],["gaufre","courant","华夫饼"],["blé noir","courant","荞麦（原料）"]],"fq":"中频，美食话题常见。","me":"galette ← galet：像一块扁圆的小石子。","tr":{"zh":"我要一块加火腿和奶酪的咸可丽饼。","fr":"Je voudrais une galette au jambon et au fromage.","alt":"Une galette jambon-fromage, s'il vous plaît.","note":"au jambon：au = à + le。"}},
 "Une librairie": {"pos":"n.f. 阴性名词，复数 librairies","s":"书店（卖书的店）。注意：librairie 是书店，不是图书馆。图书馆叫 bibliothèque。librairie 里的人叫 libraire（书商）。","ipa":"[li.bʁɛ.ʁi]","ph":"li 读 [li]；brai 读 [bʁɛ]；rie 读 [ʁi]；整词四个音节。","pi":"librairie ≠ library：这是最典型的「假朋友」。书店 = librairie，图书馆 = bibliothèque。","et":"来自 libraire（书商），源于拉丁语 librarius（与书相关的），而 liber 是「书」。","ex":[["J'achète un livre à la librairie.","我在书店买书。"],["La librairie du quartier ouvre à dix heures.","街区的书店十点开门。"]],"co":[["aller à la librairie","去书店"],["une librairie indépendante","独立书店"],["une librairie en ligne","网上书店"],["le libraire / la libraire","书商"]],"sy":[["bibliothèque","courant","图书馆（别混淆）"],["papeterie","courant","文具店"],["maison de la presse","courant","报刊亭 / 报刊店"]],"fq":"中频，购物时常用。","me":"librairie = 卖书的；bibliothèque = 借书的。","tr":{"zh":"我在书店给妈妈买了一本书。","fr":"J'ai acheté un livre pour ma mère à la librairie.","alt":"J'ai pris un livre pour maman à la librairie.","note":"acheter qqch pour qqn à + 地点。"}},
 "Une ligne (de bus, de métro)": {"pos":"n.f. 阴性名词，复数 lignes","s":"线路（公交、地铁线）；线；行。prendre la ligne 1 = 坐 1 号线。une ligne 也可以是「电话线」「一行字」「身材线条」：garder la ligne = 保持身材。","ipa":"[liɲ]","ph":"gn 读 [ɲ]（类似「尼」的鼻音）；结尾 e 不发音。","pi":"gn 读 [ɲ]，不是 [gn]，也不是 [n]。括号里是用法说明，实际说 la ligne 1 / la ligne de bus。","et":"来自拉丁语 linea（麻线、线），源于 linum（亚麻）。同族：linéaire、aligner。","ex":[["Je prends la ligne 1.","我坐一号线。"],["Quelle ligne de bus va à la gare ?","哪条公交线路去火车站？"],["Il faut garder la ligne !","要保持身材！"]],"co":[["prendre la ligne 1","坐 1 号线"],["changer de ligne","换线"],["une ligne de bus","公交线路"],["en ligne","在线"]],"sy":[["trajet","courant","行程、路程"],["itinéraire","soutenu","路线"],["file","courant","队列、车道"]],"fq":"高频，交通场景常用。","me":"ligne [liɲ]：像「里尼」，gn 就是 ny。","tr":{"zh":"你要在这一站换乘 4 号线。","fr":"Il faut changer ici pour prendre la ligne 4.","alt":"Tu changes ici et tu prends la ligne 4.","note":"changer pour prendre：换乘去乘。"}},
 "Une mairie": {"pos":"n.f. 阴性名词，复数 mairies","s":"市政厅；镇公所。办结婚登记、户籍、各种证明的地方。la mairie de Paris = 巴黎市政厅。maire（市长）+ -ie。","ipa":"[mɛ.ʁi]","ph":"mai 读 [mɛ]；rie 读 [ʁi]；整词两个音节。","pi":"mairie 读 [mɛʁi]，不是「马里」。mairie（市政厅）和 maire（市长）、mer（海）、mère（母亲）都以 [mɛʁ] 开头，别混。","et":"由 maire（市长）+ 后缀 -ie 构成；maire 来自拉丁语 maior（更大的、更重要的）。","ex":[["La mairie est au centre-ville.","市政厅在市中心。"],["On s'est marié à la mairie.","我们在市政厅结的婚。"]],"co":[["aller à la mairie","去市政厅"],["se marier à la mairie","在市政厅登记结婚"],["la mairie de Paris","巴黎市政厅"],["un mariage à la mairie","市政厅婚礼"]],"sy":[["hôtel de ville","courant","市政厅（大城市）"],["préfecture","courant","省政府"]],"fq":"中频，办理手续常用。","me":"mairie = maire 的办公室。","tr":{"zh":"我明天要去市政厅办手续。","fr":"Demain, je dois aller à la mairie pour une démarche.","alt":"Demain, je vais à la mairie faire des papiers.","note":"démarche = 办手续；devoir + 原形。"}},
 "Une maison": {"pos":"n.f. 阴性名词，复数 maisons","s":"房子；住宅；家。une maison 一般是独栋房子，公寓叫 un appartement。à la maison = 在家（口语常用）。公司也可叫 une maison（如 une maison d'édition 出版社）。","ipa":"[mɛ.zɔ̃]","ph":"ai 读 [ɛ]；s 在元音间读 [z]；on 读 [ɔ̃]，n 不发音。","pi":"s 读 [z]，不是 [s]。ai 读 [ɛ]，不是「阿伊」。「在家」是 à la maison，不是 dans la maison（那是「在房子里面」）。","et":"来自拉丁语 mansio（停留处、住所），源于 manere（停留）。同族：manoir、demeurer。","ex":[["J'habite dans une maison.","我住在一栋房子里。"],["Je reste à la maison ce soir.","今晚我在家。"],["C'est une maison de campagne.","这是一栋乡村别墅。"]],"co":[["à la maison","在家"],["une maison individuelle","独栋房子"],["une maison de campagne","乡下的房子"],["rentrer à la maison","回家"]],"sy":[["domicile","soutenu","住所"],["logement","courant","住房"],["chez soi","courant","自己家"]],"fq":"极高频，日常常用。","me":"maison ← mansio：人「停留」的地方。","tr":{"zh":"我们想在乡下买一栋房子。","fr":"Nous voulons acheter une maison à la campagne.","alt":"On veut acheter une maison à la campagne.","note":"vouloir + 原形；à la campagne 表示在乡下。"}},
 "Une peinture": {"pos":"n.f. 阴性名词，复数 peintures","s":"绘画；画作；颜料；油漆。une peinture à l'huile = 油画。de la peinture = 涂料、颜料（不可数）。画家叫 un peintre / une peintre。","ipa":"[pɛ̃.tyʁ]","ph":"ein 读鼻化音 [ɛ̃]；t 读 [t]；u 读 [y]；r 小舌音；结尾 e 不发音。","pi":"ein 读 [ɛ̃]（像「安」而不是「恩」）。u 读 [y]。不要把 peinture 和 tableau（一幅画作品）混用：peinture 更偏技法或颜料。","et":"来自拉丁语 pictura，源于 pingere（绘画）。同族：peindre（画）、peintre（画家）。","ex":[["C'est une belle peinture.","这是一幅美丽的画。"],["Attention, la peinture est fraîche !","小心，油漆未干！"],["Il aime la peinture impressionniste.","他喜欢印象派绘画。"]],"co":[["une peinture à l'huile","油画"],["la peinture murale","壁画"],["de la peinture fraîche","油漆未干"],["un pot de peinture","一桶油漆"]],"sy":[["tableau","courant","一幅画、画作"],["toile","courant","画布、油画"],["dessin","courant","素描、绘图"]],"fq":"中频，艺术和装修常见。","me":"peinture ← pingere：peindre 的名词。","tr":{"zh":"这幅画是我祖母画的。","fr":"Cette peinture a été faite par ma grand-mère.","alt":"C'est ma grand-mère qui a peint ce tableau.","note":"被动 a été faite par；或 c'est … qui 强调。"}},
 "Une pharmacie": {"pos":"n.f. 阴性名词，复数 pharmacies","s":"药店；药房；药学。法国药店门口常有绿色十字标志。pharmacien / pharmacienne 是药剂师。aller à la pharmacie = 去药店。","ipa":"[faʁ.ma.si]","ph":"ph 读 [f]；cie 读 [si]，所以整词 far-ma-si；结尾 e 不发音。","pi":"ph 读 [f]，不是 [p]。结尾 -cie 读 [si]，不读 [s-ie]。","et":"来自希腊语 pharmakon（药、药物），经拉丁语传入。同族：pharmacien、pharmaceutique。","ex":[["Je vais à la pharmacie.","我去药店。"],["Il y a une pharmacie de garde près d'ici ?","附近有值班药店吗？"]],"co":[["aller à la pharmacie","去药店"],["une pharmacie de garde","值班药店"],["une ordonnance de médecin","医生开的处方"],["acheter un médicament à la pharmacie","在药店买药"]],"sy":[["officine","soutenu","药房（行业用语）"],["droguerie","courant","日用杂货店"],["parapharmacie","courant","保健品店"]],"fq":"高频，生活和旅行必备。","me":"pharmacie ≈ pharmacy，ph = f，-cie = si。","tr":{"zh":"附近哪里有药店？","fr":"Où est la pharmacie la plus proche, s'il vous plaît ?","alt":"Il y a une pharmacie près d'ici ?","note":"la plus proche = 最近的。"}},
 "Une piscine": {"pos":"n.f. 阴性名词，复数 piscines","s":"游泳池。aller à la piscine = 去游泳。une piscine municipale = 市政游泳馆。nager = 游泳（动词）。","ipa":"[pi.sin]","ph":"sc 读 [s]；i 读 [i]；结尾 ine 读 [in]，e 不发音，n 要发出来。","pi":"sc 读 [s]，不是 [sk]。n 要发音，因为后面有 e。","et":"来自拉丁语 piscina（鱼池），源于 piscis（鱼）。同族：poisson（鱼）。","ex":[["Je nage à la piscine.","我在游泳池游泳。"],["La piscine ouvre à neuf heures.","游泳池九点开门。"]],"co":[["aller à la piscine","去游泳"],["une piscine municipale","市立游泳馆"],["une piscine couverte","室内游泳池"],["un maillot de bain pour la piscine","泳衣"]],"sy":[["bassin","courant","水池、泳池"],["baignade","courant","（在海里、河里）游泳"]],"fq":"高频，运动和夏天常用。","me":"piscine ← piscis：原来是「养鱼的池子」，和 poisson 同源。","tr":{"zh":"我每周二去游泳池。","fr":"Je vais à la piscine tous les mardis.","alt":"Le mardi, je vais nager à la piscine.","note":"le mardi = 每周二。"}},
 "Une place": {"pos":"n.f. 阴性名词，复数 places","s":"广场；位置；座位；车位；名次。Place de la Concorde = 协和广场。une place assise = 座位。une place de parking = 停车位。","ipa":"[plas]","ph":"pl 连读；a 读 [a]；ce 读 [s]；结尾 e 不发音。","pi":"place 有很多意思：广场、座位、位置、名次，要看语境。「地点、地方」用 lieu / endroit。","et":"来自拉丁语 platea（宽阔的街道），源于希腊语 plateia。英语 place 同源。","ex":[["J'habite près de la place Saint-Michel.","我住在圣米歇尔广场附近。"],["Il y a encore une place libre.","还有一个空位。"],["Il n'y a plus de place dans le train.","火车上没有座位了。"]],"co":[["une place libre","空位"],["la place du village","村里的广场"],["une place de parking","停车位"],["prendre la place de qqn","占别人的位置"]],"sy":[["endroit","courant","地方"],["siège","courant","座椅"],["emplacement","soutenu","位置、场地"]],"fq":"极高频，日常常用。","me":"place = 广场 = 座位：一个词，多个意思。","tr":{"zh":"我们在广场中央见面吧。","fr":"On se retrouve au milieu de la place ?","alt":"Rendez-vous au milieu de la place.","note":"au milieu de + 名词：在……中间。"}},
 "Une région": {"pos":"n.f. 阴性名词，复数 régions","s":"地区；大区。法国的行政区域叫 région（如 Île-de-France、Bretagne）。une région viticole = 葡萄酒产区。","ipa":"[ʁe.ʒjɔ̃]","ph":"r 小舌音；é 读 [e]；g 在 i 前读 [ʒ]；ion 读 [jɔ̃]。","pi":"g 读 [ʒ]（不是 [g]）。-ion 读 [jɔ̃]。r 是小舌音，不要读成 l。","et":"来自拉丁语 regio（方向、区域），源于 regere（引导、统治）。同族：régional、roi、règle。","ex":[["C'est une belle région.","这是一个美丽的地区。"],["Dans quelle région habites-tu ?","你住在哪个地区？"]],"co":[["la région parisienne","巴黎地区"],["une région viticole","葡萄酒产区"],["dans la région","在这一带"],["une spécialité de la région","当地特产"]],"sy":[["zone","courant","区域"],["territoire","soutenu","领土"],["pays","courant","国家、乡"]],"fq":"中高频，旅行和地理常用。","me":"région ← regio：被「管理」的一片地方。","tr":{"zh":"这个地区以奶酪闻名。","fr":"Cette région est célèbre pour ses fromages.","alt":"Cette région est connue pour son fromage.","note":"être célèbre pour = 以……闻名。"}},
 "Une rivière": {"pos":"n.f. 阴性名词，复数 rivières","s":"河；河流（一般比 fleuve 小，汇入别的河）。fleuve 是直接流入海的大河，如 la Seine。rivière 汇入 fleuve 或另一条 rivière。","ipa":"[ʁi.vjɛʁ]","ph":"r 小舌音；vi 读 [vi]；ière 读 [jɛʁ]，结尾 r 要发音。","pi":"ière 读 [jɛʁ]，r 要发出来。rivière（河）与 rive（岸）相关。","et":"来自拉丁语 riparia（岸边的、河岸），源于 ripa（岸）。同族：rive（岸）、arriver（原指「靠岸」）。","ex":[["Je nage dans la rivière.","我在河里游泳。"],["Une petite rivière traverse le village.","一条小河穿过村子。"]],"co":[["au bord de la rivière","在河边"],["pêcher dans la rivière","在河里钓鱼"],["traverser la rivière","过河"],["une rivière sauvage","野河"]],"sy":[["fleuve","courant","大河（直接入海）"],["ruisseau","courant","小溪"],["cours d'eau","courant","河流（统称）"]],"fq":"中频，自然和旅行常见。","me":"rivière ← rive：靠着「岸」的水。","tr":{"zh":"我们在河边野餐。","fr":"Nous faisons un pique-nique au bord de la rivière.","alt":"On pique-nique au bord de la rivière.","note":"au bord de = 在……边。"}},
 "Une sortie": {"pos":"n.f. 阴性名词，复数 sorties","s":"出口；出门；外出；（电影、书的）上映、发行。la sortie de secours = 紧急出口。une sortie scolaire = 学校组织的外出活动。来自动词 sortir。","ipa":"[sɔʁ.ti]","ph":"o 读 [ɔ]；r 小舌音；ti 读 [ti]；结尾 e 不发音，所以只有两个音节。","pi":"sortie 读 [sɔʁti]，e 不发音。注意 à la sortie de = 在……出口处 / 下班放学时。","et":"是动词 sortir 的过去分词 sorti 加阴性词尾 -e 变成名词。sortir 的更早来源不确定。","ex":[["Je t'attends à la sortie du métro.","我在地铁出口等你。"],["La sortie est à droite.","出口在右边。"],["Ce film sort demain : la sortie est prévue le 12.","这部电影明天上映：定于 12 号上映。"]],"co":[["la sortie de secours","紧急出口"],["à la sortie de l'école","放学时、校门口"],["une sortie en famille","全家外出活动"],["la sortie d'un film","电影上映"]],"sy":[["issue","soutenu","出路、出口"],["balade","familier","散步、外出"],["entrée","courant","反义：入口"]],"fq":"高频，日常常用。","me":"sortie ← sortir：出去 → 出口。","tr":{"zh":"出口在这条走廊的尽头。","fr":"La sortie est au bout de ce couloir.","alt":"La sortie, c'est tout au bout du couloir.","note":"au bout de = 在……的尽头。"}},
 "Une station de métro": {"pos":"n.f. 阴性名词，复数 stations de métro","s":"地铁站。station 是「站」，可以搭配 de métro、de bus、de ski（滑雪场）。la station Châtelet = 夏特莱站。les stations 复数。","ipa":"[sta.sjɔ̃ də me.tʁo]","ph":"station：tion 读 [sjɔ̃]；de 弱读 [də]；métro：é 读 [e]，o 读 [o]，r 小舌音。","pi":"station 读 [stasjɔ̃]，-tion 读 [sjɔ̃]。métro 不读 [metrou]，o 是 [o]。火车站用 gare，不是 station。","et":"station 来自拉丁语 statio（停留，站立），源于 stare（站）。métro 是 métropolitain 的缩写，指「都会铁路」。","ex":[["La station de métro est proche.","地铁站很近。"],["Descends à la prochaine station.","在下一站下车。"]],"co":[["la station de métro","地铁站"],["descendre à la station","在这一站下车"],["une station de bus","公交车站"],["une station de ski","滑雪场"]],"sy":[["arrêt","courant","（公交）站点"],["gare","courant","火车站"],["bouche de métro","courant","地铁入口"]],"fq":"高频，交通场景常用。","me":"station ← statio：「站」着停下来的地方。","tr":{"zh":"最近的地铁站在哪里？","fr":"Où est la station de métro la plus proche ?","alt":"La station de métro, c'est par où ?","note":"la plus proche：最高级。"}},
 "Une statue": {"pos":"n.f. 阴性名词，复数 statues","s":"雕像；塑像。une statue de bronze = 青铜像。la statue de la Liberté = 自由女神像。statuette 是小雕像。","ipa":"[sta.ty]","ph":"st 连读；a 读 [a]；ue 读 [y]（u 读 [y]，e 不发音）。","pi":"statue 的结尾是 [ty]，不是 [tu]。ue 不发音 e，所以只有两个音节。","et":"来自拉丁语 statua，源于 stare（站立）。「立着的像」。同族：station、statut、stable。","ex":[["C'est une statue célèbre.","这是一座著名的雕像。"],["Il y a une statue devant la mairie.","市政厅前面有一座雕像。"]],"co":[["une statue en bronze","青铜雕像"],["la statue de la Liberté","自由女神像"],["une statue de marbre","大理石雕像"],["élever une statue","立一座雕像"]],"sy":[["sculpture","courant","雕塑（泛指）"],["buste","courant","半身像"],["monument","courant","纪念碑"]],"fq":"中频，旅游和艺术常见。","me":"statue ← stare：站着的像。","tr":{"zh":"广场中央有一座大雕像。","fr":"Au milieu de la place, il y a une grande statue.","alt":"Il y a une grande statue au centre de la place.","note":"il y a + 名词：有。"}},
 "Une trottinette (électrique)": {"pos":"n.f. 阴性名词，复数 trottinettes","s":"（电动）滑板车。une trottinette électrique 是城市里租用或自备的电动滑板车。小孩玩的脚踏滑板车也叫 trottinette。","ipa":"[tʁɔ.ti.nɛt]","ph":"tr 读 [tʁ]；o 读 [ɔ]；tt 读一个 [t]；ine 读 [i.nɛt]。","pi":"tt 读一个 [t]，不要发成两个。结尾 -ette 读 [ɛt]，t 要发出来。","et":"由 trotter（小跑）+ 后缀 -inette 构成，指「小小一跑」的玩具车。trotter 来自日耳曼语源。","ex":[["Je loue une trottinette.","我租一辆滑板车。"],["Il va au travail en trottinette électrique.","他骑电动滑板车去上班。"]],"co":[["louer une trottinette","租滑板车"],["aller en trottinette","骑滑板车去"],["une trottinette électrique","电动滑板车"],["faire de la trottinette","玩滑板车"]],"sy":[["patinette","courant","（儿童）滑板车"],["vélo","courant","自行车"],["skate","familier","滑板"]],"fq":"中频，城市生活常见。","me":"trotter + -inette：小步快走的小车。","tr":{"zh":"我骑滑板车去上班。","fr":"Je vais au travail en trottinette.","alt":"Je vais bosser en trottinette.","note":"en trottinette：en + 交通工具。"}},
 "Une université (la fac)": {"pos":"n.f. 阴性名词，复数 universités；la fac = faculté 的口语缩写","s":"大学。à l'université = 在大学。口语里常说 la fac（本义是学院 faculté）：Je vais à la fac。大学生叫 un étudiant / une étudiante。","ipa":"[y.ni.vɛʁ.si.te]","ph":"u 读 [y]；i 读 [i]；ver 读 [vɛʁ]；si 读 [si]；té 读 [te]。une université 连读为 [yn‿y.ni…]。","pi":"u 是 [y]，不是「乌」。结尾 -té 读 [te]，不是 [ti]。一个词里有三个 i，要读清楚。","et":"来自中世纪拉丁语 universitas（共同体，整体），源于 universus（全体的）。同族：universel、univers。","ex":[["J'étudie à l'université.","我在大学学习。"],["Elle va à la fac en vélo.","她骑自行车去学校。"],["Il a fait ses études à l'université de Lyon.","他在里昂大学读的书。"]],"co":[["étudier à l'université","在大学学习"],["aller à la fac","去上大学（口语）"],["un étudiant en fac","大学生"],["l'université de Paris","巴黎大学"]],"sy":[["fac","familier","大学（口语）"],["grande école","courant","精英学院"],["école","courant","学校"]],"fq":"高频，学习和工作常用。","me":"université ← universus：在这里汇集「全部」知识。","tr":{"zh":"我姐姐在大学学医。","fr":"Ma sœur étudie la médecine à l'université.","alt":"Ma sœur fait médecine à la fac.","note":"faire médecine：口语，学医。"}},
 "Une voiture": {"pos":"n.f. 阴性名词，复数 voitures","s":"汽车；轿车；（火车的）车厢。en voiture = 开车 / 乘车。la voiture de tête = 车头车厢。口语里 bagnole 是「车」的随意说法。","ipa":"[vwa.tyʁ]","ph":"oi 读 [wa]；u 读 [y]；r 小舌音；结尾 e 不发音。","pi":"oi 读 [wa]，不是「欧伊」。u 读 [y]。「坐车去」用 en voiture，不是 dans la voiture（那是「在车里」）。","et":"来自拉丁语 vectura（运输），源于 vehere（载运）。同族：véhicule、voiturer。","ex":[["Ma voiture est rouge.","我的车是红色的。"],["Je vais au travail en voiture.","我开车去上班。"],["Il monte dans la voiture.","他上车。"]],"co":[["en voiture","开车、坐车"],["garer sa voiture","停车"],["louer une voiture","租车"],["une voiture de location","租来的车"]],"sy":[["auto","courant","汽车（略旧）"],["bagnole","familier","车（口语）"],["véhicule","soutenu","车辆"]],"fq":"极高频，日常常用。","me":"voiture [vwatyʁ]：oi = wa。","tr":{"zh":"我今天没有开车。","fr":"Je n'ai pas pris la voiture aujourd'hui.","alt":"Aujourd'hui, je suis venu sans voiture.","note":"prendre la voiture = 开车去。"}},
 "Des cannelés": {"pos":"n.m.pl. 阳性复数名词，单数 un cannelé","s":"可露丽（波尔多的小蛋糕，外脆内软，带朗姆酒和香草味）。通常用于复数：des cannelés。名字来自模具上的「凹槽」。有时拼成 canelé。","ipa":"[kan.le]","ph":"nn 读一个 [n]；é 读 [e]；结尾 s 不发音。","pi":"cannelé 的结尾 s 不发音，所以单复数同音。注意 nn 只发一个 n。","et":"来自形容词 cannelé（有凹槽的），源于 cannelure（凹槽），词根与 canne（芦苇、管）有关，细节不确定。","ex":[["Les cannelés sont un dessert de Bordeaux.","可露丽是波尔多的甜点。"],["Je prends deux cannelés pour le goûter.","我拿两个可露丽当下午茶点心。"]],"co":[["les cannelés de Bordeaux","波尔多可露丽"],["un cannelé encore tiède","还温热的可露丽"],["un moule à cannelés","可露丽模具"]],"sy":[["pâtisserie","courant","糕点（泛指）"],["gâteau","courant","蛋糕"],["madeleine","courant","玛德琳"]],"fq":"中低频，美食话题常见。","me":"cannelé = 有凹槽的：烤出一圈沟纹。","tr":{"zh":"我想买几个波尔多可露丽。","fr":"Je voudrais acheter des cannelés de Bordeaux.","alt":"Je prends quelques cannelés de Bordeaux, s'il vous plaît.","note":"des + 复数名词；cannelé 阳性。"}},
 "Des frites": {"pos":"n.f.pl. 阴性复数名词（pommes frites 的简称），单数 une frite","s":"薯条。des frites = 一份薯条。常说 steak-frites、moules-frites。frit / frite 是动词 frire（炸）的过去分词。","ipa":"[fʁit]","ph":"fr 读 [fʁ]；i 读 [i]；t 要发音；结尾 es 不发音。","pi":"t 要发音，不要读成 [fʁi]（阳性 frit 的 t 不发音，阴性 frite 的 t 发音）。des frites 之间没有连读。","et":"来自动词 frire（炸），源于拉丁语 frigere（煎、炸）。frites 是 pommes de terre frites（炸土豆）的省略。","ex":[["J'adore les frites.","我爱薯条。"],["Je prends un steak avec des frites.","我点一份牛排配薯条。"]],"co":[["un steak-frites","牛排配薯条"],["une portion de frites","一份薯条"],["des frites maison","自制薯条"],["un cornet de frites","一筒薯条"]],"sy":[["pommes frites","courant","炸薯条（全称）"],["patates","familier","土豆、薯条（口语）"],["chips","courant","薯片"]],"fq":"高频，餐厅常见。","me":"frites ← frire：炸的东西。","tr":{"zh":"我要一份牛排配薯条。","fr":"Je voudrais un steak avec des frites.","alt":"Un steak-frites, s'il vous plaît.","note":"avec des frites；steak-frites 是固定菜名。"}},
 "Des moules": {"pos":"n.f.pl. 阴性复数名词，单数 une moule；另有 n.m. un moule（模具）","s":"青口贝；贻贝。des moules 常配薯条：moules-frites，是比利时和法国北方的名菜。注意：un moule（阳性）= 模具，une moule（阴性）= 贻贝。","ipa":"[mul]","ph":"ou 读 [u]；l 要发音；结尾 e 不发音；s 不发音（但 des moules 里 des 后面是辅音，没有连读）。","pi":"moule 的 ou 读 [u]，不是 [o]。一个阴性一个阳性：une moule（贝）vs un moule（模具）。","et":"来自拉丁语 musculus（小肌肉；后也指贝类），一般认为这是 moule（贻贝）的来源。模具 moule 是另一个词，来自拉丁语 modulus。","ex":[["Je mange des moules-frites.","我吃青口贝配薯条。"],["Les moules sont fraîches aujourd'hui.","今天的青口贝很新鲜。"]],"co":[["des moules marinières","白酒煮青口贝"],["des moules-frites","青口贝配薯条"],["ouvrir les moules","开贝壳"],["un kilo de moules","一公斤青口贝"]],"sy":[["coquillage","courant","贝类（统称）"],["fruits de mer","courant","海鲜"],["huître","courant","牡蛎"]],"fq":"中频，餐厅常见。","me":"une moule（贝）≠ un moule（模具）：性别决定意思。","tr":{"zh":"今晚我们吃青口贝配薯条。","fr":"Ce soir, on mange des moules-frites.","alt":"Ce soir, c'est moules-frites !","note":"moules-frites 作为一道菜，常省去冠词。"}},
 "Des transports publics": {"pos":"n.m.pl. 阳性复数名词，单数 un transport public","s":"公共交通。更常说 les transports en commun。包括公交、地铁、电车、火车：prendre les transports en commun。transport 单数还有「运输」的意思。","ipa":"[tʁɑ̃s.pɔʁ py.blik]","ph":"trans 读 [tʁɑ̃s]；port 读 [pɔʁ]（t 不发音）；public 读 [py.blik]，c 要发音；复数 s 不发音。","pi":"transports 里最后的 t 和 s 都不发音。public 的 c 要发音 [pyblik]，阴性是 publique。","et":"transport 来自动词 transporter（拉丁语 transportare，「越过携带」）；public 来自拉丁语 publicus（属于人民的）。","ex":[["Je prends les transports publics.","我乘公共交通。"],["Les transports publics sont chers à Paris.","巴黎的公共交通很贵。"]],"co":[["les transports en commun","公共交通"],["prendre les transports publics","乘公共交通"],["un abonnement de transports","交通月票"],["la grève des transports","交通罢工"]],"sy":[["transports en commun","courant","公共交通（更常用说法）"],["voiture","courant","反义：私家车"],["bus","courant","公交车"]],"fq":"高频，城市生活常用。","me":"transport + public：大家一起搭的车。","tr":{"zh":"我每天乘公共交通上班。","fr":"Je prends les transports en commun pour aller au travail.","alt":"Je vais bosser en transports en commun.","note":"transports en commun 比 transports publics 更口语。"}},
 "Des viennoiseries": {"pos":"n.f.pl. 阴性复数名词，单数 une viennoiserie","s":"维也纳酥点；甜酥点心（可颂 croissant、巧克力面包 pain au chocolat、葡萄干面包 pain aux raisins 等）。在面包店里买早餐：des viennoiseries。","ipa":"[vjɛ.nwa.zʁi]","ph":"vienn 读 [vjɛn]，nn 只发一个 n；oi 读 [wa]；s 读 [z]；rie 读 [ʁi]。","pi":"ienn（双 n）读 [jɛn]，不是鼻化 [jɛ̃]。s 读 [z]，不是 [s]。","et":"由 viennois（维也纳的）+ -erie 构成，原指从奥地利传来的点心。","ex":[["J'achète des viennoiseries à la boulangerie.","我在面包店买酥点。"],["On prend des viennoiseries au petit déjeuner.","我们早餐吃酥点。"]],"co":[["acheter des viennoiseries","买酥点"],["un croissant et un pain au chocolat","可颂和巧克力面包"],["des viennoiseries et du café","酥点配咖啡"],["une boulangerie-pâtisserie","面包甜点店"]],"sy":[["pâtisserie","courant","糕点"],["croissant","courant","可颂"],["brioche","courant","布里欧修"]],"fq":"中频，早餐和面包店常见。","me":"viennoiserie ← Vienne：从维也纳来的甜点。","tr":{"zh":"周日早上我们买一些酥点当早餐。","fr":"Le dimanche matin, on achète des viennoiseries pour le petit déjeuner.","alt":"Dimanche matin, c'est viennoiseries !","note":"le dimanche matin = 每周日早上。"}},
 "Les Jeux-Olympiques": {"pos":"n.m.pl. 阳性复数名词（常写作 les Jeux olympiques，缩写 les JO）","s":"奥运会。les JO（[ʒi.o]）是口语缩写。les Jeux olympiques de Paris 2024 = 2024 年巴黎奥运会。Jeux 始终是复数。","ipa":"[ʒø.zɔ.lɛ̃.pik]","ph":"jeux 读 [ʒø]（x 不发音）；与 olympiques 连读，x 读 [z]：[ʒø.zɔ.lɛ̃.pik]；ym 读 [ɛ̃]；qu 读 [k]。","pi":"Jeux 的 x 平时不发音，但后面是元音时要连读成 [z]。olympique 里的 ym 读 [ɛ̃]，不是 [im]。","et":"来自古希腊的奥林匹亚（Olympie / Olympia），古代奥运会在那里举行。形容词 olympique。","ex":[["Je regarde les Jeux olympiques.","我看奥运会。"],["Les JO de Paris ont lieu en 2024.","巴黎奥运会在 2024 年举行。"]],"co":[["les Jeux olympiques d'été / d'hiver","夏季 / 冬季奥运会"],["les JO","奥运会（缩写）"],["une médaille olympique","奥运奖牌"],["un athlète olympique","奥运选手"]],"sy":[["les JO","familier","奥运会（缩写）"],["compétition","courant","比赛"],["championnat","courant","锦标赛"]],"fq":"中频，体育新闻常见。","me":"Jeux + z + olympiques：连读加个 [z]。","tr":{"zh":"我们在电视上看奥运会。","fr":"Nous regardons les Jeux olympiques à la télé.","alt":"On regarde les JO à la télé.","note":"à la télé = 在电视上。"}},
 "Les touristes": {"pos":"n.m./f.pl. 复数名词，单数 un touriste / une touriste（阴阳同形）","s":"游客。un touriste（男）、une touriste（女）同形。les touristes visitent la ville。形容词 touristique。","ipa":"[tu.ʁist]","ph":"ou 读 [u]；r 小舌音；ist 读 [ist]，t 要发音；结尾 e 不发音；les 的 s 不发音，不连读。","pi":"touriste 里 t 要发音；ou 读 [u]。阴阳同形：un / une touriste。","et":"由 tour（旅行、一圈）+ -iste 构成；英语 tourist 同源。","ex":[["Les touristes visitent la ville.","游客参观这座城市。"],["Il y a beaucoup de touristes en été.","夏天游客很多。"]],"co":[["un guide pour touristes","游客指南"],["un office de tourisme","旅游咨询处"],["un piège à touristes","宰客的地方"],["un site touristique","旅游景点"]],"sy":[["voyageur","courant","旅行者"],["visiteur","courant","参观者"],["vacancier","courant","度假的人"]],"fq":"高频，旅行场景常用。","me":"touriste ≈ tourist：多一个 e，t 要读出来。","tr":{"zh":"夏天，这里到处都是游客。","fr":"En été, il y a des touristes partout ici.","alt":"L'été, c'est plein de touristes ici.","note":"partout = 到处；plein de = 很多。"}},
 "Les vacances": {"pos":"n.f.pl. 阴性名词，只用复数 vacances","s":"假期；度假。几乎总用复数：les vacances。「去度假」说 partir en vacances；「在度假」说 être en vacances。","ipa":"[va.kɑ̃s]","ph":"va [va]；an 读鼻化音 [ɑ̃]；结尾 -ces 读 [s]，不发 e。les 后接辅音，s 不连读。","pi":"只有复数，不能说 une vacance（那是「职位空缺」）。结尾 -es 不发音。","et":"来自拉丁语 vacare（空着、闲着）。同源：vacant（空缺的）。","ex":[["J'aime les vacances.","我喜欢假期。"],["Nous partons en vacances demain.","我们明天去度假。"],["Il est en vacances en Italie.","他在意大利度假。"]],"co":[["partir en vacances","去度假"],["être en vacances","在度假"],["bonnes vacances !","假期愉快！"],["les grandes vacances","暑假"]],"sy":[["congé","courant","休假（工作上的）"],["repos","courant","休息"],["férié (jour)","courant","法定假日"]],"fq":"极高频，日常常用。","me":"vacances 和英语 vacation 像：都是「空出来」的时间。","tr":{"zh":"暑假我们去海边。","fr":"Pendant les grandes vacances, nous allons à la mer.","alt":"Cet été, on va à la mer en vacances.","note":"vacances 永远用复数；去度假用 en vacances。"}},
 "Un(e) artiste": {"pos":"n.m./f. 名词，阴阳同形：un artiste / une artiste，复数 artistes","s":"艺术家；也指演员、歌手等表演者。男女同形，只改冠词：un artiste（男）/ une artiste（女）。","ipa":"[aʁ.tist]","ph":"ar [aʁ]（r 在喉咙里发）；t 要发音；结尾 e 不发音。","pi":"r 是法语的喉音 [ʁ]，不是中文的 r。结尾 -e 不发，所以 un artiste 和 une artiste 读音相同，靠冠词区分。","et":"ars（拉丁语：技艺）+ 后缀 -iste（做……的人）。同类词：dentiste, journaliste。","ex":[["C'est un artiste connu.","这是一位著名的艺术家。"],["Elle est artiste peintre.","她是画家。"],["Cet artiste chante très bien.","这位艺术家唱得很好。"]],"co":[["un artiste peintre","画家"],["un artiste de rue","街头艺人"],["un artiste connu","知名艺术家"]],"sy":[["peintre","courant","画家（更具体）"],["acteur / actrice","courant","演员"],["créateur","courant","创作者"]],"fq":"高频，日常常用。","me":"artiste = art + iste：做艺术的人，男女同形。","tr":{"zh":"我的姐姐是艺术家。","fr":"Ma sœur est artiste.","alt":"Ma sœur, elle est artiste.","note":"说职业时可省略冠词：Elle est artiste。"}},
 "Un(e) habitant(e)": {"pos":"n.m./f. 名词，阳性 habitant，阴性 habitante，复数 habitants / habitantes","s":"居民；居住者。指住在某个城市、国家或地区的人。常说 les habitants de Paris。统计人口时用 habitants：Paris a deux millions d'habitants。","ipa":"[a.bi.tɑ̃]","ph":"h 不发音（哑音 h）；an 鼻化 [ɑ̃]；结尾 t 不发。阴性 habitante 读 [a.bi.tɑ̃t]，t 要发。","pi":"h 不发音，所以 un habitant 要连读：[œ̃.na.bi.tɑ̃]。阳性结尾 -t 不发，阴性 -te 的 t 要发。","et":"来自拉丁语 habitare（居住）。同源：habiter（居住）, habitat（栖息地）。","ex":[["C'est un habitant de Paris.","他是巴黎居民。"],["Les habitants du village sont gentils.","村里的居民很友善。"],["Cette ville a dix mille habitants.","这座城市有一万居民。"]],"co":[["un habitant de + 地名","某地居民"],["le nombre d'habitants","居民人数"],["par habitant","人均"]],"sy":[["résident","courant","常住者（更正式）"],["citoyen","courant","公民"],["voisin","courant","邻居"]],"fq":"中高频，常见于介绍城市时。","me":"habiter（住）+ -ant：住在那里的人。","tr":{"zh":"这个小镇有五千名居民。","fr":"Cette petite ville a cinq mille habitants.","alt":"Il y a cinq mille habitants dans cette petite ville.","note":"说人口用 avoir ... habitants。"}},
 "Attendre": {"pos":"v.t. 及物动词，第三组（-re），助动词 avoir，过去分词 attendu","s":"等；等待。直接接宾语，不加介词：attendre le bus（等公交），不是 attendre pour。attendre que + 虚拟式：J'attends qu'il arrive。","ipa":"[a.tɑ̃dʁ]","ph":"att- 的 tt 只读一个 [t]；en 鼻化 [ɑ̃]；结尾 dre 读 [dʁ]。变位：j'attends [a.tɑ̃]，d 不发。","pi":"不要加介词：attendre quelqu'un，不是 attendre pour quelqu'un。je/tu/il attends 里的 d 和 s 都不发音。","et":"来自拉丁语 attendere（把心思伸向……），由 ad + tendere（伸展）组成。同源：tendre, attention。","ex":[["J'attends le bus.","我在等公交车。"],["Attends-moi, j'arrive !","等等我，我马上到！"],["Nous attendons nos amis devant le cinéma.","我们在电影院前等朋友。"]],"co":[["attendre quelqu'un / quelque chose","等某人 / 某物"],["attendre que + 虚拟式","等到……"],["Attendez un instant.","请稍等。"],["faire attendre quelqu'un","让某人等"]],"sy":[["patienter","courant","耐心等候（更礼貌）"],["espérer","courant","盼望；希望"],["poireauter","familier","苦等、干等"]],"fq":"极高频，日常常用。","me":"attendre ≈ attention：「把注意力伸向」要来的人。","tr":{"zh":"我在咖啡馆门口等你。","fr":"Je t'attends devant le café.","alt":"Je t'attends à l'entrée du café.","note":"attendre 后直接跟宾语（t' = te）。"}},
 "Chercher": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir，过去分词 cherché","s":"找；寻找。直接接宾语：chercher ses clés，不加介词。aller chercher = 去接、去拿。chercher à + 动词原形 = 设法做某事。","ipa":"[ʃɛʁ.ʃe]","ph":"ch 读 [ʃ]（像「西」的送气音，比 s 更圆唇）；er 读 [ɛʁ]；结尾 -er 读 [e]。","pi":"两个 ch 都读 [ʃ]。不加介词：chercher quelque chose，不是 chercher pour。","et":"来自拉丁语 circare（绕着走、四处转），由 circus（圆）而来。同源：circuler。","ex":[["Je cherche mes clés.","我在找钥匙。"],["Elle cherche un appartement à Lyon.","她在里昂找公寓。"],["Je vais chercher les enfants à l'école.","我去学校接孩子。"]],"co":[["chercher quelqu'un / quelque chose","找某人 / 某物"],["aller chercher","去接；去拿"],["chercher à + 动词原形","设法……"],["chercher du travail","找工作"]],"sy":[["rechercher","soutenu","寻求；搜寻（更正式）"],["trouver","courant","找到（反义）"],["fouiller","courant","翻找"]],"fq":"极高频，日常常用。","me":"chercher = cherche（找）：像「谁在找 [ʃɛʁʃe]」一样连着读。","tr":{"zh":"我在找一家便宜的餐厅。","fr":"Je cherche un restaurant pas cher.","alt":"Je cherche un resto pas cher.","note":"chercher 后直接接宾语，不用介词。"}},
 "Continuer": {"pos":"v. 动词，第一组（-er），助动词 avoir，过去分词 continué","s":"继续；接着做。continuer à/de + 动词原形 = 继续做某事；continuer + 名词 = 继续某事；continuer tout droit = 继续直走。","ipa":"[kɔ̃.ti.nɥe]","ph":"on 鼻化 [ɔ̃]；ti 读 [ti]；nu 读 [nɥ]（u 变成半元音，像「怀」的开头）；结尾 -er 读 [e]。","pi":"不要读成 con-ti-nu-er 四个重音；-uer 要连成 [nɥe]。变位时 je continue / tu continues / il continue 读音相同。","et":"来自拉丁语 continuare，由 continuus（连续的）而来。同源：continu（连续的）, continent。","ex":[["Continue tout droit.","继续一直往前走。"],["Il continue à pleuvoir.","雨还在继续下。"],["Elle continue ses études à Paris.","她在巴黎继续读书。"]],"co":[["continuer à / de + 动词原形","继续做……"],["continuer tout droit","继续直走"],["continuer ses études","继续学业"],["Continuez !","继续！"]],"sy":[["poursuivre","soutenu","继续进行（更正式）"],["reprendre","courant","重新开始"],["arrêter","courant","停止（反义）"]],"fq":"高频，日常常用，问路时常听到。","me":"continuer ≈ continue：英语 continue 的法语版，去掉尾巴加 -er。","tr":{"zh":"继续往前走，然后右转。","fr":"Continuez tout droit, puis tournez à droite.","alt":"Continue tout droit, puis tourne à droite.","note":"对陌生人用 vous（Continuez），对朋友用 tu（Continue）。"}},
 "Courir": {"pos":"v.i. 不及物动词，第三组，助动词 avoir，过去分词 couru，不规则：je cours, nous courons","s":"跑；跑步。je cours, tu cours, il court, nous courons, ils courent。courir 也可指「奔忙」：courir partout。将来时 je courrai（两个 r）。","ipa":"[ku.ʁiʁ]","ph":"ou 读 [u]；r 是喉音 [ʁ]；结尾 -ir 读 [iʁ]。je cours [kuʁ]，s 不发音。","pi":"单数变位 cours/court 里的 s 和 t 都不发音，读音一样 [kuʁ]。将来时和条件式要写双 r：je courrai, je courrais。","et":"来自拉丁语 currere（跑）。同源：courant（水流；电流）, cours（课程）, concours。","ex":[["Je cours tous les matins.","我每天早上跑步。"],["Les enfants courent dans le jardin.","孩子们在花园里跑。"],["Il court très vite.","他跑得很快。"]],"co":[["courir un marathon","跑马拉松"],["courir après le bus","追公交车"],["courir après quelqu'un","追某人"],["courir partout","到处乱跑；忙得团团转"]],"sy":[["foncer","familier","冲；飞奔"],["galoper","familier","飞跑（本指马）"],["marcher","courant","走（反义）"]],"fq":"高频，日常常用。","me":"courir 的名词是 la course（赛跑）；cours 和 court 读音相同。","tr":{"zh":"他每周跑三次。","fr":"Il court trois fois par semaine.","alt":"Il fait de la course trois fois par semaine.","note":"court 读 [kuʁ]，t 不发音。"}},
 "Descendre": {"pos":"v. 动词，第三组（-re），助动词 être（不及物时）或 avoir（及物时），过去分词 descendu","s":"下去；下来；下车。descendre du bus / du train = 下公交 / 下火车。不及物（下车、下楼）用 être：Je suis descendu。带宾语（把东西拿下来、走下楼梯）用 avoir：J'ai descendu l'escalier。","ipa":"[de.sɑ̃dʁ]","ph":"de [de]；sc 在 e 前读 [s]；en 鼻化 [ɑ̃]；结尾 dre 读 [dʁ]。je descends 里的 d 和 s 不发音。","pi":"sc 读 [s]，不是 [sk]。完成时助动词别搞混：Elle est descendue（下车），J'ai descendu la valise（把箱子拿下来）。","et":"来自拉丁语 descendere（de 向下 + scandere 攀登）。反义：monter。同源：ascendant。","ex":[["Je descends l'escalier.","我走下楼梯。"],["Tu descends à la prochaine station ?","你在下一站下车吗？"],["Elle est descendue du train.","她下了火车。"]],"co":[["descendre du bus / du train","下公交 / 下火车"],["descendre l'escalier","下楼梯"],["descendre à la station X","在 X 站下车"],["descendre en ville","进城"]],"sy":[["baisser","courant","降低"],["monter","courant","上去（反义）"],["dévaler","soutenu","飞奔而下"]],"fq":"高频，坐交通工具时常用。","me":"de-（向下）+ scend：de 就是「往下」，和 monter 相对。","tr":{"zh":"我在下一站下车。","fr":"Je descends à la prochaine station.","alt":"Moi, je descends au prochain arrêt.","note":"下车用 descendre à + 站名。"}},
 "Dormir": {"pos":"v.i. 不及物动词，第三组（-ir），助动词 avoir，过去分词 dormi；je dors, nous dormons","s":"睡觉；睡着。je dors, tu dors, il dort, nous dormons。dormir 是「睡着的状态」；「入睡」用 s'endormir；「躺下准备睡」用 se coucher。","ipa":"[dɔʁ.miʁ]","ph":"o 读开音 [ɔ]；r 喉音 [ʁ]；结尾 -ir 读 [iʁ]。je dors [dɔʁ]，s 不发音。","pi":"dors / dort 读音相同 [dɔʁ]，s 和 t 都不发。dormir 和 s'endormir（入睡）、se coucher（上床）不同。","et":"来自拉丁语 dormire（睡觉）。同源：dortoir（宿舍）, dormant。","ex":[["Je dors huit heures par nuit.","我每晚睡八小时。"],["Le bébé dort dans sa chambre.","宝宝在自己房间里睡觉。"],["Tu as bien dormi ?","你睡得好吗？"]],"co":[["bien / mal dormir","睡得好 / 睡不好"],["dormir tard","睡得晚"],["dormir comme un bébé","睡得很香"],["avoir envie de dormir","想睡觉"]],"sy":[["se reposer","courant","休息"],["somnoler","soutenu","打瞌睡"],["roupiller","familier","睡觉"]],"fq":"极高频，日常常用。","me":"dormir ≈ dormitory（宿舍）：睡觉的地方。","tr":{"zh":"昨晚我睡得不好。","fr":"Je n'ai pas bien dormi cette nuit.","alt":"J'ai mal dormi cette nuit.","note":"完成时：avoir + dormi；bien / mal 放在助动词和分词之间。"}},
 "Économiser": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir，过去分词 économisé","s":"省钱；节省；存钱。économiser de l'argent = 存钱；économiser l'énergie = 节能。常用 économiser pour + 名词 / 动词 = 为……存钱。","ipa":"[e.kɔ.nɔ.mi.ze]","ph":"é [e]；co [kɔ]；no [nɔ]；mi [mi]；结尾 -er 读 [e]。五个音节，重音在最后。","pi":"第一个 é 有重音符号，别漏。词里的 o 读开音 [ɔ]，不是 [o]。","et":"来自 économie，源自希腊语 oikonomia（管理家庭，oikos 家 + nomos 规则）+ 后缀 -iser。","ex":[["J'économise pour les vacances.","我为假期存钱。"],["Il économise de l'argent chaque mois.","他每个月都存一点钱。"],["Il faut économiser l'eau.","要节约用水。"]],"co":[["économiser de l'argent","存钱；省钱"],["économiser pour + 名词","为……存钱"],["économiser l'énergie / l'eau","节约能源 / 用水"]],"sy":[["épargner","soutenu","积蓄（银行存款）"],["mettre de côté","courant","存起来"],["dépenser","courant","花钱（反义）"]],"fq":"中频，谈钱、环保时常用。","me":"économiser = économie + -iser：让开销变小。","tr":{"zh":"我每个月存一点钱买电脑。","fr":"J'économise un peu chaque mois pour acheter un ordinateur.","alt":"Je mets un peu d'argent de côté chaque mois pour un ordinateur.","note":"pour + 动词原形表示目的。"}},
 "Monter": {"pos":"v. 动词，第一组（-er），不及物用 être，及物用 avoir，过去分词 monté","s":"上去；上来；登上；上车。monter dans le train / la voiture = 上火车 / 上车；monter à pied = 走上去；monter l'escalier = 爬楼梯。不及物完成时用 être：Je suis monté；带宾语用 avoir：J'ai monté la valise。","ipa":"[mɔ̃.te]","ph":"on 鼻化 [ɔ̃]；结尾 -er 读 [e]。monter 的 on 后面是 t，所以仍是鼻化音（不是 [ɔn]）。","pi":"monter dans 一般接交通工具（火车、汽车）；骑马、骑车用 monter à cheval / à vélo。注意完成时助动词的选择。","et":"来自通俗拉丁语 *montare，由 mons, montis（山）而来。同源：montagne, monter。","ex":[["Je monte dans le train.","我上了火车。"],["Elle monte l'escalier lentement.","她慢慢爬楼梯。"],["Les prix montent.","物价在上涨。"]],"co":[["monter dans le train / le bus","上火车 / 公交"],["monter l'escalier","爬楼梯"],["monter à cheval / à vélo","骑马 / 骑车"],["monter à pied","走上去"]],"sy":[["grimper","courant","攀爬"],["gravir","soutenu","攀登"],["descendre","courant","下去（反义）"]],"fq":"极高频，日常常用。","me":"monter ← mont（山）：上山就是 monter。","tr":{"zh":"我上了地铁。","fr":"Je monte dans le métro.","alt":"Je prends le métro, je monte dedans.","note":"上交通工具用 monter dans + 名词。"}},
 "Pouvoir": {"pos":"v. 动词（情态），第三组，助动词 avoir，过去分词 pu，高度不规则","s":"能；可以；有可能。je peux, tu peux, il peut, nous pouvons, ils peuvent。用于能力、许可、请求：Je peux t'aider ? Tu peux fermer la porte ? 后接动词原形。","ipa":"[pu.vwaʁ]","ph":"pou [pu]；voi 读 [vwa]；结尾 -ir 读 [aʁ]。je peux [pø]，x 不发音。","pi":"je peux / tu peux 的 x 不发音；il peut 的 t 也不发。提问时第一人称用 puis-je ? 而不是 *peux-je ?。","et":"来自通俗拉丁语 *potere，替代拉丁语 posse（能）。同源：puissant（强大的）, pouvoir（权力）。","ex":[["Je peux t'aider.","我可以帮你。"],["Tu peux me passer le sel ?","你能把盐递给我吗？"],["On ne peut pas entrer ici.","这里不能进去。"]],"co":[["pouvoir + 动词原形","能……；可以……"],["Je peux entrer ?","我可以进来吗？"],["Vous pouvez répéter ?","您能重复一遍吗？"],["il se peut que + 虚拟式","有可能……"]],"sy":[["savoir","courant","会（有学来的能力）"],["être capable de","courant","有能力做"],["devoir","courant","必须"]],"fq":"极高频，日常常用。","me":"peux / peut 读 [pø]：像「破」；pouvoir = 有 power。","tr":{"zh":"你能帮我一下吗？","fr":"Tu peux m'aider, s'il te plaît ?","alt":"Tu peux me donner un coup de main ?","note":"请求用 pouvoir + 动词原形；加 s'il te plaît 更礼貌。"}},
 "Prendre": {"pos":"v.t. 及物动词，第三组，助动词 avoir，过去分词 pris；je prends, nous prenons, ils prennent","s":"拿；带；乘坐；吃喝；洗澡。prendre le bus = 坐公交；prendre un café = 喝杯咖啡；prendre une douche = 洗澡；prendre une décision = 做决定。是极常用的万能动词。","ipa":"[pʁɑ̃dʁ]","ph":"pr [pʁ]；en 鼻化 [ɑ̃]；结尾 dre [dʁ]。je prends [pʁɑ̃]，d 和 s 不发。nous prenons [pʁə.nɔ̃]，这里 en 读 [ə]。","pi":"变位的词干会变：je prends / nous prenons / ils prennent（双 n）。过去分词 pris，不是 prendu。","et":"来自拉丁语 prehendere（抓住）。同源：apprendre, comprendre, entreprendre, surprendre。","ex":[["Je prends un café.","我喝杯咖啡。"],["Elle prend le métro tous les jours.","她每天坐地铁。"],["Qu'est-ce que vous prenez ?","您要点什么？"]],"co":[["prendre le bus / le train / un taxi","坐公交 / 火车 / 出租车"],["prendre un café / un verre","喝咖啡 / 喝一杯"],["prendre une douche","洗澡"],["prendre une photo","拍照"]],"sy":[["saisir","soutenu","抓住"],["emporter","courant","带走"],["attraper","courant","抓；赶上"]],"fq":"极高频，日常常用。","me":"prendre 是「拿」；apprendre = 往身边拿 = 学；comprendre = 拿在一起 = 懂。","tr":{"zh":"我们坐火车去里昂。","fr":"Nous prenons le train pour aller à Lyon.","alt":"On prend le train pour Lyon.","note":"交通工具用 prendre，不加介词。"}},
 "Rester": {"pos":"v.i. 不及物动词，第一组（-er），助动词 être，过去分词 resté","s":"留；待；停留；剩下。rester à la maison = 待在家里；rester + 形容词 = 保持（某状态）：rester calme。il reste du pain = 还剩一些面包。完成时用 être：Je suis resté。","ipa":"[ʁɛs.te]","ph":"r 喉音 [ʁ]；e 读 [ɛ]；st 都发 [s][t]；结尾 -er 读 [e]。","pi":"完成时用 être（je suis resté, elle est restée），不用 avoir。注意：rester 是「留下」，不是「休息」。","et":"来自拉丁语 restare（停住、站住）。同源：reste（其余）, restant。","ex":[["Je reste à la maison ce soir.","今晚我待在家里。"],["Reste calme, ce n'est pas grave.","保持冷静，没什么大事。"],["Il reste du pain ?","还剩面包吗？"]],"co":[["rester à la maison","待在家里"],["rester calme / tranquille","保持冷静 / 安静"],["rester en contact","保持联系"],["il reste + 名词","还剩……"]],"sy":[["demeurer","soutenu","停留；居住"],["séjourner","soutenu","逗留"],["partir","courant","离开（反义）"]],"fq":"极高频，日常常用。","me":"rester ≈ rest（休息、剩下）：留在原地。","tr":{"zh":"周末我留在家里。","fr":"Ce week-end, je reste à la maison.","alt":"Ce week-end, je reste chez moi.","note":"rester à la maison / chez + 人称。"}},
 "Se déplacer": {"pos":"v.pron. 代词式动词，第一组（-er），助动词 être，过去分词 déplacé","s":"出行；移动；走动。se déplacer en ville / à vélo / en transports en commun = 在城里 / 骑车 / 坐公共交通出行。也指「亲自跑一趟」：Je me suis déplacé pour rien。","ipa":"[sə.de.pla.se]","ph":"se [sə]；dé [de]；pla [pla]；ce 读 [se]（c 在 e 前读 [s]）；结尾 -er 读 [e]。","pi":"变位时 c 要变 ç：nous nous déplaçons。人称代词 me / te / se 要跟着变：je me déplace, tu te déplaces。","et":"dé-（分开）+ placer（放置），来自 place（地方），而 place 源自拉丁语 platea（宽街）。déplacer = 把位置挪开。","ex":[["C'est facile de se déplacer en ville.","在城里出行很方便。"],["Je me déplace à vélo.","我骑车出行。"],["Elle a du mal à se déplacer.","她行动不便。"]],"co":[["se déplacer à pied / à vélo","步行 / 骑车出行"],["se déplacer en transports en commun","坐公共交通出行"],["se déplacer en voiture","开车出行"],["les déplacements","出行；移动"]],"sy":[["bouger","courant","动；挪动"],["voyager","courant","旅行"],["circuler","courant","通行；流动"]],"fq":"中频，谈交通时常用。","me":"dé-（离开）+ place（位置）：离开原来的位置 = 移动。","tr":{"zh":"在巴黎坐地铁出行很方便。","fr":"À Paris, c'est facile de se déplacer en métro.","alt":"À Paris, on se déplace facilement en métro.","note":"se déplacer en + 交通工具；步行用 à pied。"}},
 "Se promener": {"pos":"v.pron. 代词式动词，第一组（-er），助动词 être，过去分词 promené","s":"散步；闲逛。je me promène, tu te promènes, nous nous promenons。注意 e → è 的变化。promener quelqu'un / un chien 则是「带……散步」。","ipa":"[sə.pʁɔm.ne]","ph":"se [sə]；pro [pʁɔ]；me [m]；ner [ne]。在 je me promène 里 è 读 [ɛ]：[pʁɔ.mɛn]。","pi":"单数和 ils 形式要写 è：je me promène, ils se promènent；nous / vous 不变：nous nous promenons。","et":"来自 mener（带领）加前缀 pro-，原指把牲口赶往前走。","ex":[["Je me promène dans le parc.","我在公园散步。"],["On se promène au bord de la mer.","我们在海边散步。"],["Il promène son chien tous les soirs.","他每天晚上遛狗。"]],"co":[["se promener dans le parc","在公园散步"],["se promener en ville","在城里闲逛"],["promener le chien","遛狗"],["une promenade","散步（名词）"]],"sy":[["se balader","familier","闲逛"],["flâner","littéraire","闲逛、漫步"],["marcher","courant","走路"]],"fq":"中频，日常常用。","me":"promener ≈ promenade：promenade 是「散步」，动词形式 se promener。","tr":{"zh":"星期天我们在公园散步。","fr":"Le dimanche, nous nous promenons dans le parc.","alt":"Le dimanche, on se balade dans le parc.","note":"代词式动词：nous nous promenons。"}},
 "Sortir": {"pos":"v. 动词，第三组（-ir），不及物用 être，及物用 avoir，过去分词 sorti；je sors, nous sortons","s":"出去；外出；出门玩。sortir de + 地点 = 从某处出来；sortir avec quelqu'un = 和某人出去 / 交往；sortir quelque chose = 把某物拿出来。不及物完成时用 être：Je suis sorti。","ipa":"[sɔʁ.tiʁ]","ph":"s [s]；o 读 [ɔ]；r 喉音 [ʁ]；结尾 -ir [iʁ]。je sors [sɔʁ]，s 不发。","pi":"单数变位 sors / sort 不发 s 和 t；复数 sortons 才发 t。完成时：Je suis sorti，带宾语：J'ai sorti la poubelle。","et":"来源不确定（古法语 sortir，原义「抽签」或「出来」，来源有争议）。词族：sortie（出口）。","ex":[["Je sors avec mes amis.","我和朋友出去。"],["Elle sort de la maison à huit heures.","她八点出门。"],["Ce film sort demain.","这部电影明天上映。"]],"co":[["sortir avec des amis","和朋友出去玩"],["sortir de + 地点","从……出来"],["sortir le chien","出去遛狗"],["la sortie","出口；出游"]],"sy":[["quitter","courant","离开（接地点）"],["partir","courant","出发；走"],["entrer","courant","进入（反义）"]],"fq":"极高频，日常常用。","me":"sortir = 出口 sortie 的动词：看到 SORTIE 的绿灯牌就是「出口」。","tr":{"zh":"今晚你出去吗？","fr":"Tu sors ce soir ?","alt":"Tu sors ce soir, ou tu restes à la maison ?","note":"tu sors 里的 s 不发音。"}},
 "Tourner": {"pos":"v. 动词，第一组（-er），助动词 avoir，过去分词 tourné","s":"转；转弯；转动。tourner à gauche / à droite = 向左 / 向右转。也指「拍电影」：tourner un film；以及「运转」：le moteur tourne。","ipa":"[tuʁ.ne]","ph":"ou 读 [u]；r 喉音 [ʁ]；ner 读 [ne]。结尾 -er 读 [e]。","pi":"ou 读 [u]（像中文「乌」），不要读成 [ɔ]。问路时用 tourner à gauche，介词是 à。","et":"来自拉丁语 tornare（用车床加工），由 tornus（车床）而来，源自希腊语。同源：tour（一圈；塔）, détour。","ex":[["Tourne à gauche.","向左转。"],["Vous tournez à droite au feu.","您在红绿灯处向右转。"],["Ils tournent un film à Paris.","他们在巴黎拍电影。"]],"co":[["tourner à gauche / à droite","向左 / 向右转"],["tourner un film","拍电影"],["tourner la page","翻页；翻篇"],["tourner en rond","原地打转"]],"sy":[["virer","courant","拐弯"],["pivoter","courant","转动（绕轴）"],["retourner","courant","翻转；回去"]],"fq":"高频，问路时必学。","me":"tourner ≈ tour：tour 是「一圈」。tourisme 也是「转一圈」。","tr":{"zh":"在红绿灯处向右转。","fr":"Au feu, tournez à droite.","alt":"Au feu rouge, tourne à droite.","note":"tourner à + gauche / droite。"}},
 "Venir": {"pos":"v.i. 不及物动词，第三组，助动词 être，过去分词 venu，不规则：je viens, nous venons, ils viennent","s":"来；过来。venir de + 地点 = 来自某地；venir de + 动词原形 = 刚刚做完（近过去）：Je viens d'arriver。venir + 动词原形 = 来做某事。","ipa":"[və.niʁ]","ph":"ve [və]；ni [ni]；结尾 -ir 读 [iʁ]。je viens [vjɛ̃]，ien 读 [jɛ̃]，s 不发。ils viennent [vjɛn]，n 要发。","pi":"viens / vient 读 [vjɛ̃]；viennent 读 [vjɛn]，注意鼻音有无。完成时用 être：Je suis venu(e)。","et":"来自拉丁语 venire（来）。同源：avenir（未来）, convenir, devenir, revenir。","ex":[["Tu viens avec nous ?","你跟我们一起来吗？"],["Je viens de Chine.","我来自中国。"],["Elle vient d'arriver.","她刚到。"]],"co":[["venir de + 地点","来自……"],["venir de + 动词原形","刚刚……"],["venir chercher quelqu'un","来接某人"],["viens ici !","过来！"]],"sy":[["arriver","courant","到达"],["aller","courant","去（反义）"],["rappliquer","familier","赶来；跑来"]],"fq":"极高频，日常常用。","me":"venir = come；avenir = à + venir = 未来「要来」的事。","tr":{"zh":"你明天来我家吗？","fr":"Tu viens chez moi demain ?","alt":"Tu passes chez moi demain ?","note":"venir chez + 人 = 到某人家来。"}},
 "Visiter": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir，过去分词 visité","s":"参观；游览（地方或景点）。visiter un musée / une ville = 参观博物馆 / 游览城市。看人不用 visiter，用 rendre visite à quelqu'un 或 aller voir quelqu'un。","ipa":"[vi.zi.te]","ph":"vi [vi]；si 里的 s 在元音间读 [z]；结尾 -er 读 [e]。","pi":"中文「看望朋友」不能说 visiter un ami，应说 rendre visite à un ami。s 读 [z]，不是 [s]。","et":"来自拉丁语 visitare（常去看），由 videre（看）而来。同源：visite, visiteur, vision。","ex":[["Je visite le musée.","我参观博物馆。"],["Nous visitons Paris cet été.","今年夏天我们游览巴黎。"],["Il rend visite à sa grand-mère.","他去看望奶奶。"]],"co":[["visiter un musée / une ville","参观博物馆 / 游览城市"],["une visite guidée","导游带领的参观"],["rendre visite à quelqu'un","看望某人"]],"sy":[["découvrir","courant","发现；探索"],["se promener","courant","散步"],["rendre visite à","courant","拜访人"]],"fq":"高频，旅行时常用。","me":"visiter ≈ visit，但只用于地方；看人要 rendre visite à。","tr":{"zh":"明天我们参观卢浮宫。","fr":"Demain, nous visitons le Louvre.","alt":"Demain, on va visiter le Louvre.","note":"visiter + 地点；近将来：aller + visiter。"}},
 "Ancien(ne)": {"pos":"adj. 形容词，阴性 ancienne，复数 anciens / anciennes","s":"古老的；旧的（有历史的）；以前的。放在名词后 = 古老：un bâtiment ancien；放在名词前 = 以前的、前任的：mon ancien professeur（我以前的老师）。","ipa":"[ɑ̃.sjɛ̃]","ph":"an [ɑ̃]；ci 读 [sj]；en 读鼻化 [ɛ̃]。阴性 ancienne 读 [ɑ̃.sjɛn]，n 要发。","pi":"位置改变意思：un ancien élève（以前的学生）vs un livre ancien（古书）。阴性 ancienne 双 n。","et":"来自通俗拉丁语 *anteanus，由拉丁语 ante（在……之前）而来。同源：antique 是另一支。","ex":[["C'est un bâtiment ancien.","这是一座古老的建筑。"],["Mon ancien professeur habite à Lyon.","我以前的老师住在里昂。"],["Ils vendent des meubles anciens.","他们卖古董家具。"]],"co":[["un bâtiment ancien","古老的建筑"],["mon ancien + 名词","我以前的……"],["un ancien élève","校友；以前的学生"],["l'ancien temps","过去；旧时"]],"sy":[["vieux","courant","老的；旧的"],["antique","soutenu","古代的；古董的"],["ex-","courant","前任（ex-mari）"]],"fq":"高频，日常常用。","me":"ancien ≈ ancient（古老）：但放在名词前变成「前任」。","tr":{"zh":"这是一座很古老的教堂。","fr":"C'est une très ancienne église.","alt":"Cette église est très ancienne.","note":"ancienne 在名词前时可表示古老，也可表示前任；放名词后只表示古老。"}},
 "Beau / Belle": {"pos":"adj. 形容词，阳性 beau（元音前 bel），阴性 belle，复数 beaux / belles","s":"美丽的；漂亮的；英俊的；（天气）好。il fait beau = 天气好。beau 放在名词前：un beau jardin。阳性单数名词以元音或哑音 h 开头时用 bel：un bel homme。","ipa":"[bo] / [bɛl]","ph":"beau [bo]（eau 读 [o]）；belle [bɛl]（e 开口，ll 读 [l]）；bel [bɛl]。","pi":"四种形式：beau / bel / belle / beaux。复数阳性 beaux 读 [bo]，x 不发。阴性 belle 要读出 l。","et":"来自拉丁语 bellus（漂亮的）。同源：embellir（美化）, beauté（美）。","ex":[["Il fait beau aujourd'hui.","今天天气很好。"],["C'est un bel appartement.","这是一套漂亮的公寓。"],["Elle est très belle.","她非常美。"]],"co":[["il fait beau","天气好"],["un bel homme / une belle femme","英俊的男人 / 美丽的女人"],["un beau jardin","漂亮的花园"],["Il y a de beaux paysages.","有美丽的风景。"]],"sy":[["joli","courant","漂亮；好看（更小巧）"],["magnifique","courant","壮丽的"],["laid","courant","丑（反义）"]],"fq":"极高频，日常常用。","me":"bel 用在元音前，读 [bɛl]，和 belle 同音，好记。","tr":{"zh":"今天天气真好！","fr":"Il fait vraiment beau aujourd'hui !","alt":"Quel beau temps aujourd'hui !","note":"天气好用 il fait beau，不用 est。"}},
 "Charmant(e)": {"pos":"adj. 形容词，阴性 charmante，复数 charmants / charmantes","s":"迷人的；讨人喜欢的；可爱的。可形容人（友善、有魅力）或地方（小巧可爱）。Charmant ! 单独说时也可以反讽。","ipa":"[ʃaʁ.mɑ̃]","ph":"ch 读 [ʃ]；ar [aʁ]；an 鼻化 [ɑ̃]；结尾 t 不发。阴性 charmante 读 [ʃaʁ.mɑ̃t]。","pi":"ch 读 [ʃ]，不要读成 [tʃ]。结尾 -ant 读 [ɑ̃]，t 不发；阴性 -ante 才发 t。","et":"来自 charme（魅力），源自拉丁语 carmen（咒语、歌）+ 后缀 -ant。英语 charm 来自法语。","ex":[["Cette petite maison est charmante.","这间小房子很迷人。"],["Votre fils est charmant.","您的儿子很讨人喜欢。"],["C'est un village charmant.","这是一个迷人的小村庄。"]],"co":[["un village charmant","迷人的小村庄"],["un homme charmant","讨人喜欢的男人"],["Charmé de vous connaître.","很高兴认识您。"],["avoir du charme","有魅力"]],"sy":[["mignon","familier","可爱（小巧）"],["adorable","courant","可爱极了"],["séduisant","courant","有魅力的"]],"fq":"中频，描述人或地方时常用。","me":"charmant ≈ charming：英语几乎一样，但 ch 读 [ʃ]。","tr":{"zh":"这家小旅馆很迷人。","fr":"Ce petit hôtel est charmant.","alt":"Ce petit hôtel a beaucoup de charme.","note":"形容词要与名词配合：hôtel 阳性，用 charmant。"}},
 "Gratuit(e)": {"pos":"adj. 形容词，阴性 gratuite，复数 gratuits / gratuites","s":"免费的；不收费的。L'entrée est gratuite = 入场免费。注意 gratuit 是形容词，不能当副词用；「免费地」说 gratuitement。","ipa":"[gʁa.tɥi]","ph":"gr [gʁ]；a [a]；tuit 读 [tɥi]（u 是半元音，后面接 i）；结尾 t 不发。阴性 gratuite 读 [gʁa.tɥit]。","pi":"-uit 读 [ɥi]，不是 [ɥit]。阳性结尾 t 不发，阴性 gratuite 才发 t。","et":"来自拉丁语 gratuitus（自愿给的、不求回报的），由 gratis（免费）而来。同源：gratis, gratuité。","ex":[["L'entrée est gratuite.","入场免费。"],["Le café est gratuit.","咖啡免费。"],["Ce musée est gratuit le dimanche.","这座博物馆周日免费。"]],"co":[["l'entrée gratuite","免费入场"],["gratuit le dimanche","周日免费"],["un cadeau gratuit","免费赠品"],["gratuitement","免费地（副词）"]],"sy":[["gratis","familier","免费"],["offert","courant","赠送的"],["payant","courant","收费的（反义）"]],"fq":"高频，购物、旅游时常用。","me":"gratuit ≈ gratis：都是「免费」。","tr":{"zh":"这个展览周日免费。","fr":"Cette exposition est gratuite le dimanche.","alt":"Le dimanche, l'exposition est gratuite.","note":"exposition 是阴性，所以用 gratuite。"}},
 "Intéressant(e)": {"pos":"adj. 形容词，阴性 intéressante，复数 intéressants / intéressantes","s":"有趣的；有意思的；有吸引力的。形容书、人、想法、工作等。注意：不用来形容「好笑」（那是 drôle）。","ipa":"[ɛ̃.te.ʁɛ.sɑ̃]","ph":"in [ɛ̃]；té [te]；res [ʁɛ]；sant [sɑ̃]；五个音节中 ss 读 [s]；结尾 t 不发。","pi":"词很长，要拆成 in-té-res-sant。ss 读 [s]，不要读成 [z]。阴性 intéressante 读 [ɛ̃.te.ʁɛ.sɑ̃t]。","et":"来自动词 intéresser（拉丁语 interesse，在……之间、有关系）+ 后缀 -ant。同源：intérêt（兴趣；利息）。","ex":[["Ce livre est intéressant.","这本书很有趣。"],["Il a un travail très intéressant.","他有一份很有意思的工作。"],["C'est une idée intéressante.","这是个有意思的想法。"]],"co":[["un livre intéressant","有趣的书"],["C'est intéressant !","真有意思！"],["trouver ça intéressant","觉得这很有趣"],["un prix intéressant","优惠的价格"]],"sy":[["passionnant","courant","引人入胜的"],["captivant","soutenu","吸引人的"],["ennuyeux","courant","无聊的（反义）"]],"fq":"高频，日常常用。","me":"intéressant ≈ interesting：去掉 -ing，加 -ant。","tr":{"zh":"这部电影很有意思。","fr":"Ce film est très intéressant.","alt":"J'ai trouvé ce film vraiment intéressant.","note":"film 阳性，用 intéressant。"}},
 "Joli(e)": {"pos":"adj. 形容词，阴性 jolie，复数 jolis / jolies","s":"漂亮的；好看的（多指小巧、可爱的东西）。比 beau 更轻松，常用于花、衣服、房子、女孩。放在名词前：une jolie fleur。","ipa":"[ʒɔ.li]","ph":"j 读 [ʒ]（像「日」的浊音）；o 开口 [ɔ]；li [li]。阴性 jolie 读音相同 [ʒɔ.li]。","pi":"j 读 [ʒ]，不是英语 [dʒ]。阴阳性读音一样，只靠拼写 -e 区别。","et":"来源不确定（古法语 jolif，可能与古北欧语 jól「冬至节」有关，有争议）。","ex":[["C'est une jolie fleur.","这是一朵漂亮的花。"],["Tu as une jolie robe.","你有一条漂亮的裙子。"],["Quel joli village !","多么漂亮的村庄！"]],"co":[["une jolie fille / robe","漂亮的女孩 / 裙子"],["Quel joli ... !","多漂亮的……！"],["C'est joli !","真好看！"],["un joli cadeau","漂亮的礼物"]],"sy":[["beau","courant","美丽（更强）"],["mignon","familier","可爱"],["laid","courant","丑（反义）"]],"fq":"高频，日常常用。","me":"joli ≈ jolly：想成「开心好看」。","tr":{"zh":"你的裙子真漂亮！","fr":"Ta robe est très jolie !","alt":"Elle est vraiment jolie, ta robe !","note":"robe 阴性，用 jolie。"}},
 "Local(e)": {"pos":"adj. 形容词，阴性 locale，复数阳 locaux / 阴 locales","s":"当地的；本地的；局部的。nourriture locale = 本地食物；les produits locaux = 本地产品；une anesthésie locale = 局部麻醉。","ipa":"[lɔ.kal]","ph":"lo [lɔ]；cal [kal]。阴性 locale 读 [lɔ.kal]，和阳性同音。复数阳性 locaux 读 [lɔ.ko]。","pi":"阳性复数是 locaux（不是 locals），和 journal → journaux 相同规律。阴阳性读音相同。","et":"来自拉丁语 localis，由 locus（地方）而来。同源：lieu, localiser, location。","ex":[["Je mange de la nourriture locale.","我吃当地的食物。"],["Ce marché vend des produits locaux.","这个市场卖本地产品。"],["Les journaux locaux parlent de ça.","本地报纸报道了这件事。"]],"co":[["la nourriture locale","当地食物"],["les produits locaux","本地产品"],["la cuisine locale","当地菜"],["un journal local","地方报纸"]],"sy":[["régional","courant","地区的"],["typique","courant","有特色的"],["étranger","courant","外国的（反义）"]],"fq":"中频，旅游、饮食话题常用。","me":"local ≈ locality：lieu（地方）的形容词。","tr":{"zh":"我喜欢吃当地的菜。","fr":"J'aime manger la cuisine locale.","alt":"J'adore goûter la cuisine locale.","note":"cuisine 阴性，用 locale。"}},
 "Pas cher/chère": {"pos":"adj. 形容词，阴性 pas chère，复数 pas chers / pas chères","s":"不贵的；便宜的。pas cher 是 ne ... pas + cher；口语常省略 ne。cher 也可指「亲爱的」：Cher ami（亲爱的朋友），放在名词前。","ipa":"[pa.ʃɛʁ]","ph":"pas [pa]，s 不发；ch 读 [ʃ]；er 读 [ɛʁ]。阴性 chère [ʃɛʁ] 读音相同。","pi":"阴性 chère 带重音符号，复数要加 s：pas chers / pas chères。cher 读 [ʃɛʁ]，不是 [ʃe]。","et":"cher 来自拉丁语 carus（珍贵的、亲爱的）。因此既有「亲爱」又有「贵」的意思。","ex":[["Ce n'est pas cher.","这不贵。"],["Ces chaussures ne sont pas chères.","这些鞋子不贵。"],["On cherche un hôtel pas cher.","我们在找便宜的旅馆。"]],"co":[["un restaurant pas cher","便宜的餐厅"],["Ce n'est pas cher !","这不贵！"],["pas trop cher","不太贵"],["bon marché","便宜的（固定表达，不变形）"]],"sy":[["bon marché","courant","便宜的"],["économique","courant","经济实惠的"],["radin","familier","小气的（不是价格）"]],"fq":"极高频，购物时常用。","me":"cher = 贵 = 珍贵；pas cher = 不贵。","tr":{"zh":"这家餐厅不贵。","fr":"Ce restaurant n'est pas cher.","alt":"Ce resto est pas cher.","note":"口语常省略 ne；书写用 n'est pas cher。"}},
 "Traditionnel(le)": {"pos":"adj. 形容词，阴性 traditionnelle，复数 traditionnels / traditionnelles","s":"传统的；惯常的。une danse traditionnelle = 传统舞蹈；un plat traditionnel = 传统菜肴。表示按老习惯做的事。","ipa":"[tʁa.di.sjɔ.nɛl]","ph":"tra [tʁa]；di [di]；tion 读 [sjɔ]；nel 读 [nɛl]。双 n 只读一个 [n]，结尾 el 读 [ɛl]。","pi":"拼写有两个 n 两个 l：traditionnel / traditionnelle。注意 tion 读 [sj]，不是 [ʃ]。","et":"来自 tradition（拉丁语 traditio，交付、传授）+ 后缀 -el。tradition 来自 tradere（传递）。","ex":[["C'est une danse traditionnelle.","这是一种传统舞蹈。"],["Nous mangeons un repas traditionnel.","我们吃一顿传统的饭菜。"],["Le costume traditionnel est très beau.","传统服装很漂亮。"]],"co":[["la cuisine traditionnelle","传统菜"],["un costume traditionnel","传统服装"],["une fête traditionnelle","传统节日"],["la médecine traditionnelle","传统医学"]],"sy":[["classique","courant","经典的；传统的"],["ancien","courant","古老的"],["moderne","courant","现代的（反义）"]],"fq":"中频，谈文化时常用。","me":"traditionnel = tradition + -nel：双 n 双 l 记两个 nn / ll。","tr":{"zh":"这是一道传统的法国菜。","fr":"C'est un plat traditionnel français.","alt":"C'est un plat typique de la cuisine française.","note":"plat 阳性，用 traditionnel。"}},
 "Vivant(e)": {"pos":"adj. 形容词，阴性 vivante，复数 vivants / vivantes","s":"活着的；有生气的；热闹的。un quartier vivant = 热闹有生气的街区；un animal vivant = 活的动物。反义 mort（死的）。名词 un vivant = 生者。","ipa":"[vi.vɑ̃]","ph":"vi [vi]；vant 读 [vɑ̃]；结尾 t 不发。阴性 vivante 读 [vi.vɑ̃t]。","pi":"不要读成 [vi.vɑ̃t]（阳性无 t）。vivant 来自 vivre，但变位不同（je vis）。","et":"来自 vivre（拉丁语 vivere，活着）的现在分词，用作形容词。同源：vie（生命）, vivre, survivre。","ex":[["Ce quartier est vivant.","这个街区很有生气。"],["Mon grand-père est encore vivant.","我爷爷还活着。"],["C'est une ville très vivante.","这是一座很有活力的城市。"]],"co":[["un quartier vivant","热闹的街区"],["une ville vivante","有活力的城市"],["de son vivant","在世时"],["un bon vivant","爱享受生活的人"]],"sy":[["animé","courant","热闹的"],["actif","courant","有活力的"],["mort","courant","死的（反义）"]],"fq":"中频，描述地方或人时常用。","me":"vivant ← vivre：像 alive 里的 live。","tr":{"zh":"这座城市夜里很热闹。","fr":"Cette ville est très vivante la nuit.","alt":"La nuit, cette ville est super animée.","note":"ville 阴性，用 vivante。"}},
 "Cent": {"pos":"adj.num. 数词，不变数词形容词；在整百且后面无其他数字时加 s：deux cents","s":"一百。cent euros = 一百欧元。deux cents = 两百（整百加 s）；deux cent trois = 203（后接数字不加 s）。注意 un cent 不说，直接说 cent。","ipa":"[sɑ̃]","ph":"c 在 e 前读 [s]；en 读鼻化 [ɑ̃]；t 不发。cent euros 连读 [sɑ̃.t‿ø.ʁo]（这里 t 要连读）。","pi":"cent / sans / sang / sens 同音 [sɑ̃]。cent 后接元音时 t 要连读：cent euros。拼写：整百加 s，其后有数字则不加。","et":"来自拉丁语 centum（一百）。同源：pour cent, centime, centimètre。","ex":[["Ça coûte cent euros.","这个值一百欧元。"],["Il y a deux cents personnes.","有两百个人。"],["J'ai cent cinquante livres.","我有一百五十本书。"]],"co":[["cent pour cent","百分之百"],["deux cents / trois cents","两百 / 三百"],["cent un","一百零一"],["un pourcentage","百分比"]],"sy":[["centaine","courant","一百左右（名词）"],["centime","courant","分（欧元的百分之一）"],["mille","courant","一千"]],"fq":"极高频，数字必学。","me":"cent ≈ century：一百年；cent = 100。","tr":{"zh":"这件衣服一百欧元。","fr":"Ce vêtement coûte cent euros.","alt":"Ça fait cent euros.","note":"cent euros 连读：t 要读出来。"}},
 "Mille": {"pos":"adj.num. 数词，不变，永远不加 s（mille，不是 milles）","s":"一千。mille euros = 一千欧元；deux mille = 两千（mille 不变）。不说 un mille，直接说 mille。注意：mille 作名词「英里」时才有复数 milles。","ipa":"[mil]","ph":"m [m]；i 读 [i]；ll 在这里读 [l]；结尾 e 不发。整词 [mil]。","pi":"mille 永不加 s：trois mille，不是 trois milles。ll 读 [l]，不是 [j]（ville / mille 都读 [l]）。","et":"来自拉丁语 mille（一千）。同源：million, millier, millimètre。","ex":[["Il y a mille personnes.","有一千个人。"],["Ça coûte deux mille euros.","这个值两千欧元。"],["Cette ville a dix mille habitants.","这座城市有一万居民。"]],"co":[["mille euros","一千欧元"],["deux mille","两千"],["mille fois merci","千万次感谢"],["des milliers de + 名词","成千上万的……"]],"sy":[["millier","courant","一千左右（名词）"],["million","courant","百万"],["cent","courant","一百"]],"fq":"极高频，数字必学。","me":"mille ≈ mill-：mile、million 都从 mille 来。","tr":{"zh":"这辆车值一万欧元。","fr":"Cette voiture coûte dix mille euros.","alt":"Cette voiture vaut dix mille euros.","note":"mille 不变：dix mille。"}},
 "Bien": {"pos":"adv. 副词，不变；也可作名词 un bien（财产）","s":"好；很好；确实；相当。Je vais bien = 我很好。bien 修饰动词：Il parle bien。也用于强调：C'est bien ! = 不错！。比较级是 mieux，不说 plus bien。","ipa":"[bjɛ̃]","ph":"b [b]；ien 读 [jɛ̃]（鼻化）；整词一个音节。n 不单独发，只让 e 变鼻音。","pi":"bien（副词，好地）≠ bon（形容词，好的）。Il parle bien；C'est un bon livre。比较级是 mieux，不是 plus bien。","et":"来自拉丁语 bene（好地）。同源：bénéfice, bénir, bienvenue。","ex":[["Je vais très bien.","我很好。"],["Elle parle bien français.","她法语说得好。"],["C'est bien, merci !","很好，谢谢！"]],"co":[["aller bien","身体好；顺利"],["très bien","非常好"],["bien sûr","当然"],["bien + 形容词","相当……"]],"sy":[["mal","courant","不好（反义）"],["super","familier","太棒了"],["correctement","courant","正确地"]],"fq":"极高频，日常最常用的词之一。","me":"bien ≈ bene（拉丁语 好）：bien 记「好」，mal 记「坏」。","tr":{"zh":"他法语说得很好。","fr":"Il parle très bien français.","alt":"Il parle super bien français.","note":"bien 修饰动词，放在动词后。"}},
 "À pied": {"pos":"loc.adv. 副词短语，不变","s":"步行；走路。aller à pied = 走着去；venir à pied = 走路来。与交通工具对比：en voiture（开车）, en bus, à vélo（骑车）。","ipa":"[a.pje]","ph":"à [a]；pied 读 [pje]；结尾 d 不发。整句 [a.pje]。","pi":"pied 的 d 不发音。介词用 à，不是 en：à pied，à vélo，但 en voiture, en train。","et":"pied 来自拉丁语 pes, pedis（脚）。同源：pédale, piéton（行人）, pédestre。","ex":[["Je vais au travail à pied.","我走路上班。"],["On y va à pied ?","我们走着去吗？"],["Il rentre à pied.","他走路回家。"]],"co":[["aller à pied","走路去"],["rentrer à pied","走路回家"],["à pied ou à vélo","步行或骑车"],["un piéton","行人"]],"sy":[["en marchant","courant","边走边"],["à vélo","courant","骑车"],["en voiture","courant","开车"]],"fq":"极高频，日常常用。","me":"pied = 脚；à pied = 靠脚。pedal 也来自 pes。","tr":{"zh":"我每天走路去学校。","fr":"Je vais à l'école à pied tous les jours.","alt":"Je vais à l'école à pied, chaque jour.","note":"à pied 放在句尾或动词后。"}},
 "Avoir chaud": {"pos":"loc.v. 固定短语（avoir + 名词），助动词 avoir","s":"觉得热（人的感觉）。J'ai chaud = 我觉得热。说人觉得热用 avoir chaud，不用 être chaud；il fait chaud 专指天气热。","ipa":"[a.vwaʁ.ʃo]","ph":"avoir [a.vwaʁ]，oi 读 [wa]；chaud 读 [ʃo]，au 读 [o]，d 不发。j'ai chaud 读 [ʒe.ʃo]。","pi":"中文说「我热」，法语不能说 je suis chaud（那有别的意思）。要说 j'ai chaud。chaud 的 d 不发音。","et":"chaud 来自拉丁语 calidus（热的）。同源：chaleur（热）, chauffer（加热）。","ex":[["J'ai chaud en été.","夏天我觉得热。"],["Tu as chaud ? Ouvre la fenêtre.","你热吗？把窗户打开。"],["Il fait chaud et nous avons chaud.","天气热，我们觉得热。"]],"co":[["avoir très chaud","觉得很热"],["il fait chaud","天气热"],["avoir trop chaud","觉得太热"],["Ça me donne chaud.","这让我觉得热。"]],"sy":[["avoir froid","courant","觉得冷（反义）"],["étouffer","courant","闷得喘不过气"],["transpirer","courant","出汗"]],"fq":"极高频，日常常用。","me":"avoir chaud = 拥有「热」；感觉都用 avoir（avoir faim, avoir soif）。","tr":{"zh":"房间里太热了，我觉得很热。","fr":"Il fait trop chaud dans la pièce, j'ai très chaud.","alt":"J'ai trop chaud ici !","note":"天气热 il fait chaud，人觉得热 j'ai chaud。"}},
 "Avoir de la chance": {"pos":"loc.v. 固定短语（avoir + 名词），助动词 avoir","s":"运气好；走运。Tu as de la chance ! = 你真幸运！反义：ne pas avoir de chance（运气不好）。bonne chance ! = 祝你好运！","ipa":"[a.vwaʁ.də.la.ʃɑ̃s]","ph":"avoir [a.vwaʁ]；de la [də.la]；chance 读 [ʃɑ̃s]，ch 读 [ʃ]，an 鼻化，ce 读 [s]。","pi":"ch 读 [ʃ]，不是 [tʃ]。「运气好」说 avoir de la chance，不要说 avoir chance。否定时 de 变 de chance：Je n'ai pas de chance。","et":"chance 来自古法语 cheance，源自通俗拉丁语 *cadentia（「掉落」，指掷骰子）。","ex":[["Tu as de la chance.","你运气真好。"],["Il a eu de la chance hier.","他昨天运气不错。"],["Je n'ai pas de chance aujourd'hui.","我今天运气不好。"]],"co":[["avoir de la chance","运气好"],["Bonne chance !","祝你好运！"],["avoir la chance de + 动词原形","有幸……"],["par chance","幸运地"]],"sy":[["avoir du bol","familier","走运（口语）"],["avoir du pot","familier","走运（口语）"],["être malchanceux","courant","倒霉的（反义）"]],"fq":"高频，日常常用。","me":"chance ≈ chance（英语一样）：de la chance = 有一点运气。","tr":{"zh":"你真幸运，天气这么好！","fr":"Tu as de la chance, il fait si beau !","alt":"Tu as du bol, il fait super beau !","note":"否定：pas de chance。"}},
 "Avoir froid": {"pos":"loc.v. 固定短语（avoir + 名词），助动词 avoir","s":"觉得冷（人的感觉）。J'ai froid = 我觉得冷。il fait froid = 天气冷。不要用 être froid 说人冷。","ipa":"[a.vwaʁ.fʁwa]","ph":"avoir [a.vwaʁ]；froid 读 [fʁwa]，oi 读 [wa]，d 不发。j'ai froid 读 [ʒe.fʁwa]。","pi":"froid 的 d 不发音；oi 读 [wa]。人感觉冷用 avoir froid，天气冷用 il fait froid。","et":"froid 来自拉丁语 frigidus（冷的）。同源：frigo（冰箱）, réfrigérateur, frigide。","ex":[["J'ai froid en hiver.","冬天我觉得冷。"],["Tu as froid ? Mets ton manteau.","你冷吗？穿上外套。"],["Les enfants ont froid aux mains.","孩子们的手冷。"]],"co":[["avoir très froid","觉得很冷"],["il fait froid","天气冷"],["avoir froid aux mains / aux pieds","手 / 脚冷"],["mourir de froid","冻得要死"]],"sy":[["avoir chaud","courant","觉得热（反义）"],["grelotter","courant","冷得发抖"],["geler","courant","冻"]],"fq":"极高频，日常常用。","me":"froid ≈ frigo（冰箱）：都是「冷」。","tr":{"zh":"外面很冷，我觉得很冷。","fr":"Il fait froid dehors, j'ai très froid.","alt":"Dehors, il fait glacial, j'ai super froid.","note":"天气 il fait froid；感觉 j'ai froid。"}},
 "Boire un verre": {"pos":"loc.v. 固定短语（boire + un verre），boire 为第三组不规则动词，过去分词 bu","s":"喝一杯（通常指喝酒或饮料、社交场合）。On va boire un verre ? = 我们去喝一杯吗？比 boire 单独用更口语、更友好。","ipa":"[bwaʁ.œ̃.vɛʁ]","ph":"boire 读 [bwaʁ]，oi 读 [wa]；un 读 [œ̃]；verre 读 [vɛʁ]，rr 只读一个 [ʁ]；结尾 -re 不发 e。","pi":"un verre 要连读为 [œ̃.vɛʁ]。boire 变位不规则：je bois, nous buvons, ils boivent。","et":"boire 来自拉丁语 bibere；verre 来自拉丁语 vitrum（玻璃）。","ex":[["On va boire un verre ?","我们去喝一杯吗？"],["Après le travail, nous buvons un verre.","下班后，我们去喝一杯。"],["Tu veux boire un verre d'eau ?","你要喝杯水吗？"]],"co":[["boire un verre avec des amis","和朋友喝一杯"],["un verre d'eau / de vin","一杯水 / 酒"],["prendre un verre","喝一杯"],["boire un coup","喝一杯（口语）"]],"sy":[["prendre un verre","courant","喝一杯"],["boire un coup","familier","喝一杯"],["trinquer","courant","干杯"]],"fq":"高频，日常社交常用。","me":"boire = 喝；un verre = 一个杯子，也是一杯的量。","tr":{"zh":"下班后去喝一杯吧？","fr":"On va boire un verre après le travail ?","alt":"Et si on allait boire un verre après le boulot ?","note":"On va + 动词原形，口语邀请。"}},
 "Il pleut": {"pos":"loc.v. 无人称动词 pleuvoir，只用 il：il pleut, il a plu","s":"下雨。il pleut = 正在下雨；Il pleut beaucoup = 雨很大。il va pleuvoir = 要下雨了；il a plu = 下过雨。只有 il 一个主语（无人称）。","ipa":"[il.plø]","ph":"il [il]；pleut 读 [plø]，eu 读 [ø]，t 不发。整句 [il.plø]。","pi":"pleut 的 t 不发音。il 在这里没有实际含义，不指人。不要说 elle pleut。","et":"pleuvoir 来自拉丁语 pluere（下雨）。同源：pluie（雨）, parapluie（雨伞）, pluvieux。","ex":[["Prends un parapluie, il pleut.","带把伞，下雨了。"],["Il pleut depuis ce matin.","从早上起就一直在下雨。"],["Il va pleuvoir demain.","明天会下雨。"]],"co":[["il pleut beaucoup","雨下得很大"],["il va pleuvoir","要下雨了"],["la pluie","雨"],["un parapluie","雨伞"]],"sy":[["il bruine","courant","下毛毛雨"],["il pleut des cordes","familier","倾盆大雨"],["il fait beau","courant","天气好（反义）"]],"fq":"极高频，谈天气时最常用。","me":"pleuvoir → pluie → parapluie（挡雨）。","tr":{"zh":"外面在下雨，带上伞吧。","fr":"Il pleut dehors, prends ton parapluie.","alt":"Dehors, il pleut, prends un parapluie.","note":"天气动词无人称：主语永远是 il。"}},
 "Tout droit": {"pos":"loc.adv. 副词短语，不变","s":"一直往前；笔直地。aller tout droit = 一直走；continuer tout droit = 继续直走。问路和指路时必学。","ipa":"[tu.dʁwa]","ph":"tout 读 [tu]，t 不发；droit 读 [dʁwa]，oi 读 [wa]，t 不发。整词 [tu.dʁwa]。","pi":"两个词结尾的 t 都不发音。tout droit 不加介词。droit 还有「右（边）」之意（à droite）和「权利」，别混淆。","et":"tout 来自拉丁语 totus（全部）；droit 来自拉丁语 directus（笔直的）。同源：direct, direction。","ex":[["Va tout droit.","一直往前走。"],["Allez tout droit, puis tournez à gauche.","一直往前走，然后向左转。"],["La gare est tout droit.","火车站一直往前走就到。"]],"co":[["aller tout droit","一直走"],["continuer tout droit","继续直走"],["tout droit puis à gauche","直走然后左转"],["à droite / à gauche","向右 / 向左"]],"sy":[["directement","courant","直接地"],["en ligne droite","courant","走直线"],["à droite","courant","向右（不同）"]],"fq":"极高频，问路必学。","me":"droit ≈ direct：tout droit = directly ahead。","tr":{"zh":"一直往前走，银行就在右边。","fr":"Allez tout droit, la banque est à droite.","alt":"Va tout droit, la banque est sur ta droite.","note":"问路用祈使句：Allez（vous）/ Va（tu）。"}},
 "X fois par ...": {"pos":"loc. 短语，X 为数字，par 后接时间单位","s":"每……X 次。une fois par jour = 每天一次；deux fois par semaine = 每周两次；trois fois par mois = 每月三次。表示频率的万能格式。","ipa":"[fwa.paʁ]","ph":"fois 读 [fwa]，oi 读 [wa]，s 不发；par 读 [paʁ]，r 喉音。前面的数字和 fois 连读：deux fois [dø.fwa]。","pi":"fois 的 s 不发音。times 说成 fois，不是 temps。par 后面不加冠词：par jour，par semaine。","et":"fois 来自拉丁语 vices（次，轮换）。同源：parfois（有时）, autrefois。","ex":[["Je vais au marché deux fois par semaine.","我每周去两次市场。"],["Il mange une fois par jour au restaurant.","他每天在餐厅吃一次。"],["Nous voyons nos amis trois fois par mois.","我们每月见朋友三次。"]],"co":[["une fois par jour","每天一次"],["deux fois par semaine","每周两次"],["trois fois par mois","每月三次"],["une fois par an","每年一次"]],"sy":[["par jour / semaine / mois / an","courant","按天 / 周 / 月 / 年"],["chaque jour","courant","每天"],["souvent","courant","经常"]],"fq":"极高频，说频率必学。","me":"fois = times；par = per：deux fois par jour = twice per day。","tr":{"zh":"我每周游泳三次。","fr":"Je nage trois fois par semaine.","alt":"Je vais à la piscine trois fois par semaine.","note":"par + 时间单位，不加冠词。"}},
 "Combien de temps ?": {"pos":"loc. 疑问短语","s":"多长时间？问持续的时长。Combien de temps dure le film ? = 电影有多长？Ça prend combien de temps ? = 要花多久？","ipa":"[kɔ̃.bjɛ̃.də.tɑ̃]","ph":"com 读 [kɔ̃]；bien 读 [bjɛ̃]；de 读 [də]；temps 读 [tɑ̃]，ps 不发。","pi":"temps 的 p 和 s 都不发。combien 里第一个 on 是鼻化 [ɔ̃]，第二个是 [jɛ̃]。问「几点」用 Quelle heure，不用 combien de temps。","et":"combien ← comme + bien；temps 来自拉丁语 tempus（时间）。同源：temporel, tempo。","ex":[["Combien de temps dure le film ?","这部电影有多长？"],["Tu restes combien de temps à Paris ?","你在巴黎待多久？"],["Ça prend combien de temps ?","这要花多长时间？"]],"co":[["Combien de temps dure ... ?","……持续多久？"],["Combien de temps faut-il ?","需要多长时间？"],["pendant combien de temps ?","持续多久？"],["depuis combien de temps ?","从多久以前起？"]],"sy":[["Ça dure combien ?","familier","要多久？"],["Quelle durée ?","soutenu","多长时间？"],["Quelle heure est-il ?","courant","几点了（不同）"]],"fq":"极高频，问时间长度时常用。","me":"combien = how much；temps = time：how much time。","tr":{"zh":"从你家到车站要多久？","fr":"Combien de temps faut-il de chez toi à la gare ?","alt":"Ça prend combien de temps de chez toi à la gare ?","note":"il faut + 时间 = 需要多长时间。"}},
 "Du coton": {"pos":"n.m. 阳性名词（不可数），部分冠词 du，复数少用","s":"棉；棉花。du coton = 一些棉（部分冠词，表示材料）。en coton = 棉质的。coton 还指药棉：un morceau de coton。","ipa":"[kɔ.tɔ̃]","ph":"co [kɔ]，o 开口音；ton 读 [tɔ̃]，鼻化 [ɔ̃]，n 不发。","pi":"两个 o 都读 [ɔ]，结尾 on 鼻化。「du」是部分冠词（de + le），表示不可数的材料。","et":"来自意大利语 cotone，源自阿拉伯语 qutn。英语 cotton 也出自同源。","ex":[["Ce t-shirt est 100% coton.","这件 T 恤是纯棉的。"],["Je mets une chemise en coton.","我穿一件棉衬衫。"],["Le coton est doux et léger.","棉布柔软轻薄。"]],"co":[["en coton","棉质的"],["100% coton","纯棉"],["un t-shirt en coton","棉 T 恤"],["du coton hydrophile","药棉"]],"sy":[["laine","courant","羊毛"],["lin","courant","亚麻"],["tissu","courant","布料"]],"fq":"中频，买衣服时常用。","me":"coton = cotton：几乎一样，只少一个 t。","tr":{"zh":"我喜欢穿棉衬衫。","fr":"J'aime porter des chemises en coton.","alt":"Je préfère les chemises en coton.","note":"材料用 en：en coton。"}},
 "Du cuir": {"pos":"n.m. 阳性名词（不可数），部分冠词 du","s":"皮革；皮。du cuir = 一些皮革。en cuir = 皮质的：une veste en cuir（皮夹克）。cuir chevelu = 头皮（比较少见）。","ipa":"[kɥiʁ]","ph":"c [k]；ui 读 [ɥi]（u 半元音 + i）；r 喉音 [ʁ]。一个音节，不发 e。","pi":"cuir 读 [kɥiʁ]，u 和 i 要连成一个音，不是 [ky.iʁ]。r 要读出来。","et":"来自拉丁语 corium（皮、革）。同源：cuirasse（胸甲）。","ex":[["C'est une veste en cuir.","这是一件皮夹克。"],["Ce sac est en cuir véritable.","这个包是真皮的。"],["Il porte des chaussures en cuir.","他穿皮鞋。"]],"co":[["en cuir","皮质的"],["une veste en cuir","皮夹克"],["du cuir véritable","真皮"],["un sac en cuir","皮包"]],"sy":[["peau","courant","皮肤；兽皮"],["similicuir","courant","人造革"],["daim","courant","麂皮"]],"fq":"中频，买衣服、包时常用。","me":"cuir [kɥiʁ]：像「葵尔」连读。","tr":{"zh":"我想买一条皮带。","fr":"Je voudrais acheter une ceinture en cuir.","alt":"Je cherche une ceinture en cuir.","note":"ceinture 阴性，en cuir 不变。"}},
 "Un chapeau": {"pos":"n.m. 阳性名词，复数 chapeaux","s":"帽子（有帽檐的）。口语感叹 Chapeau ! = 「佩服！真有你的！」，字面是「向你脱帽致敬」。","ipa":"[ʃa.po]","ph":"ch 读 [ʃ]；a [a]；peau 读 [po]，eau 读 [o]。","pi":"复数是 chapeaux，不是 chapeaus。eau 读 [o]，不发 e、a、u。","et":"来自 chape（斗篷）加小称后缀 -eau，chape 源自晚期拉丁语 cappa。","ex":[["Il porte un chapeau noir.","他戴一顶黑色帽子。"],["Elle met un chapeau de paille.","她戴一顶草帽。"],["Tu as réussi ? Chapeau !","你成功了？佩服！"]],"co":[["mettre un chapeau","戴帽子"],["un chapeau de paille","草帽"],["Chapeau !","佩服！"],["enlever son chapeau","脱帽"]],"sy":[["casquette","courant","鸭舌帽"],["bonnet","courant","毛线帽"],["béret","courant","贝雷帽"]],"fq":"中频。","me":"Chapeau ! = 脱帽致敬 = 「服了」。","tr":{"zh":"他戴着一顶红色帽子。","fr":"Il porte un chapeau rouge.","alt":"Il a un chapeau rouge sur la tête.","note":"穿戴用 porter 或 mettre。"}},
 "Un costume": {"pos":"n.m. 阳性名词，复数 costumes","s":"西装（男士套装）；服装；戏服。un costume pour le travail = 上班穿的西装。也指民族服装、舞台服装：un costume traditionnel。","ipa":"[kɔs.tym]","ph":"cos 读 [kɔs]；tume 读 [tym]，u 读 [y]（嘴圆如吹口哨说「衣」），结尾 e 不发。","pi":"u 读 [y]，不是 [u]。不要和英语 costume（戏服）混；法语 costume 主要指男士西装。","et":"来自意大利语 costume（习俗），源自拉丁语 consuetudo（习惯）。英语 custom 同源。","ex":[["Il porte un costume pour le travail.","他穿西装上班。"],["Il met un costume noir.","他穿一套黑西装。"],["Les enfants portent un costume de pirate.","孩子们穿海盗服。"]],"co":[["un costume cravate","西装领带"],["un costume de bain","游泳衣"],["un costume traditionnel","传统服装"],["un costume de théâtre","戏服"]],"sy":[["complet","courant","男士套装"],["tailleur","courant","女士套装"],["vêtement","courant","衣服"]],"fq":"中频。","me":"costume ≈ custom：穿的是「习惯」的服装。","tr":{"zh":"他穿一套蓝色西装去上班。","fr":"Il va au travail en costume bleu.","alt":"Il porte un costume bleu pour aller au travail.","note":"en + 衣着名词：en costume。"}},
 "Un débardeur": {"pos":"n.m. 阳性名词，复数 débardeurs","s":"背心；无袖上衣（夏天穿）。débardeur 也指「码头工人」（旧义）。穿 débardeur 一般是在热天。","ipa":"[de.baʁ.dœʁ]","ph":"dé [de]；bar [baʁ]；deur 读 [dœʁ]，eu 读 [œ]；结尾 r 要读出。","pi":"r 在词尾要读出：[dœʁ]。-eur 的开口比 [ø] 大，读 [œʁ]。","et":"来自动词 débarder（卸货），原指搬运木材的工人；后来因为这些工人穿无袖衫，衣服也叫 débardeur。","ex":[["Il fait chaud, je mets un débardeur.","天气很热，我穿背心。"],["Elle porte un débardeur blanc.","她穿一件白色背心。"],["J'ai acheté un débardeur noir.","我买了一件黑色背心。"]],"co":[["mettre un débardeur","穿背心"],["un débardeur blanc","白色背心"],["un débardeur en coton","棉质背心"]],"sy":[["tee-shirt","courant","T 恤"],["maillot","courant","运动衫；背心"],["chemisier","courant","女式衬衫"]],"fq":"中频，买夏装时常用。","me":"débardeur：原来是搬运工，现在是夏天的无袖背心。","tr":{"zh":"夏天我常穿背心。","fr":"En été, je porte souvent un débardeur.","alt":"L'été, je mets souvent un débardeur.","note":"季节用 en été（元音前用 en）。"}},
 "Un degré": {"pos":"n.m. 阳性名词，复数 degrés","s":"度（温度、角度）；程度；等级。Il fait 25 degrés = 25 度。degré 也指酒精度和程度：à un certain degré。","ipa":"[də.gʁe]","ph":"de 读 [də]；gré 读 [gʁe]，é 读 [e]。两个音节。","pi":"é 有重音符号。注意 degré 重音在最后一个音节。温度说法：Il fait vingt-cinq degrés，不说 il est。","et":"来自拉丁语 gradus（步、级）加前缀 de-，同源：grade, graduel, gradué。","ex":[["Aujourd'hui, il fait 25°C (25 degrés).","今天 25 度。"],["L'eau est à vingt degrés.","水温二十度。"],["Il fait moins cinq degrés.","零下五度。"]],"co":[["il fait ... degrés","（天气）……度"],["moins dix degrés","零下十度"],["à quel degré ?","到什么程度？"],["un degré Celsius","摄氏度"]],"sy":[["niveau","courant","水平"],["température","courant","温度"],["étape","courant","阶段"]],"fq":"高频，谈天气时常用。","me":"degré ≈ degree：英语 degree 的法语版，少一个 e。","tr":{"zh":"今天有三十度，很热。","fr":"Aujourd'hui, il fait trente degrés, c'est chaud.","alt":"Il fait trente degrés aujourd'hui, c'est chaud !","note":"温度用 il fait + 数字 + degrés。"}},
 "Un dessin": {"pos":"n.m. 阳性名词，复数 dessins","s":"图画；素描；设计。un beau dessin = 一幅漂亮的画。faire un dessin = 画画。dessin animé = 动画片。","ipa":"[de.sɛ̃]","ph":"de 读 [de]；ssin 读 [sɛ̃]，ss 读 [s]，in 鼻化 [ɛ̃]；结尾 n 不发。","pi":"ss 读 [s]，不是 [z]。dessin（图画）和 dessein（意图，古词）同音，别混淆。","et":"来自动词 dessiner，源自意大利语 disegnare，拉丁语 designare（标出）。同源：design, désigner。","ex":[["C'est un beau dessin.","这是一幅漂亮的画。"],["Mon fils fait un dessin.","我儿子在画画。"],["Les enfants regardent un dessin animé.","孩子们在看动画片。"]],"co":[["faire un dessin","画画"],["un dessin animé","动画片"],["un dessin d'enfant","儿童画"],["dessiner","画（动词）"]],"sy":[["peinture","courant","绘画（上色）"],["croquis","courant","草图"],["image","courant","图像"]],"fq":"高频，日常常用。","me":"dessin → dessiner：画画的人叫 dessinateur。","tr":{"zh":"我女儿画了一幅漂亮的画。","fr":"Ma fille a fait un beau dessin.","alt":"Ma fille a dessiné un beau dessin.","note":"faire un dessin = 画一幅画。"}},
 "Un gilet": {"pos":"n.m. 阳性名词，复数 gilets","s":"开衫；背心（马甲）。un gilet 在法国多指前面开口的针织开衫，也可指西装马甲或救生衣：un gilet de sauvetage。","ipa":"[ʒi.lɛ]","ph":"gi 读 [ʒi]，g 在 i 前读 [ʒ]；le 读 [lɛ]；结尾 t 不发。","pi":"g 读 [ʒ]（日），不是 [g]。结尾 t 不发音。","et":"一般认为经西班牙语从土耳其语 yelek 传入；来源不完全确定。","ex":[["Elle porte un gilet gris.","她穿一件灰色开衫。"],["Il fait frais, mets un gilet.","有点凉，穿件开衫。"],["Il y a un gilet de sauvetage sur le bateau.","船上有一件救生衣。"]],"co":[["un gilet en laine","羊毛开衫"],["un gilet de sauvetage","救生衣"],["un gilet jaune","黄色反光背心"],["mettre un gilet","穿开衫"]],"sy":[["cardigan","courant","开衫（外来词）"],["pull","courant","套头毛衣"],["veste","courant","外套"]],"fq":"中频，穿搭时常用。","me":"gilet [ʒi.lɛ]：ʒi-lè，像「给累」，t 不发。","tr":{"zh":"天气有点凉，穿上你的开衫吧。","fr":"Il fait un peu frais, mets ton gilet.","alt":"Il fait un peu frais, prends ton gilet.","note":"天气凉 il fait frais；穿上用 mettre。"}},
 "Un jean": {"pos":"n.m. 阳性名词，复数 jeans（单数也常写 jean）","s":"牛仔裤；也指牛仔布。法语里 un jean 通常指一条牛仔裤，也常说 des jeans（几条）。指「牛仔布」时用 en jean：une veste en jean。","ipa":"[dʒin]","ph":"j 读 [dʒ]（和英语一样）；ea 不出现，整词 [dʒin]；结尾 n 要读出来。","pi":"j 在这个词里读 [dʒ]，不是法语常见的 [ʒ]；一条牛仔裤用单数 un jean，不是 des jean。","et":"来自英语 jeans，源头是 Gênes（热那亚）一带出产的粗布。","ex":[["J'adore ce jean.","我喜欢这条牛仔裤。"],["Elle porte un jean et un pull.","她穿牛仔裤和毛衣。"],["Cette veste en jean est trop grande.","这件牛仔外套太大了。"]],"co":[["un jean slim / droit","修身 / 直筒牛仔裤"],["une veste en jean","牛仔外套"],["un jean troué","破洞牛仔裤"]],"sy":[["pantalon","courant","裤子（更宽泛，不限牛仔布）"],["denim","courant","牛仔布（英语借词）"]],"fq":"高频，日常常用。","me":"jean 读起来像英语 gin（金酒）。","tr":{"zh":"我在找一条蓝色牛仔裤。","fr":"Je cherche un jean bleu.","alt":"Je veux un jean bleu foncé.","note":"一条牛仔裤用单数 un jean。"}},
 "Un jogging": {"pos":"n.m. 阳性名词，复数 joggings","s":"运动裤；运动服套装。也可指「慢跑」这项运动：faire du jogging。指衣服时是 un jogging（一条运动裤），指运动时是 le jogging。","ipa":"[dʒɔ.ɡiŋ]","ph":"j 读 [dʒ]；o [ɔ]；g 读 [ɡ]；-ing 读 [iŋ]，ng 是后鼻音。","pi":"ng 读 [ŋ]，注意别加上 [ɡ]；这个词是英语借词，但读音是法语化的。","et":"来自英语 jogging（慢跑），法语里把「慢跑服」变成了衣服的名字。","ex":[["Il met un jogging pour courir.","他穿运动裤跑步。"],["Je reste à la maison en jogging.","我穿着运动裤待在家。"],["Tu fais du jogging le dimanche ?","你周日慢跑吗？"]],"co":[["faire du jogging","慢跑"],["un jogging gris","灰色运动裤"],["en jogging","穿着运动裤"]],"sy":[["survêtement","courant","运动服（整套）"],["pantalon de sport","courant","运动长裤"]],"fq":"中高频，日常常用。","me":"一个词两个意思：运动 + 运动裤。","tr":{"zh":"他穿着一条灰色运动裤。","fr":"Il porte un jogging gris.","alt":"Il est en jogging gris.","note":"porter + 衣服；en + 衣服也可以。"}},
 "Un legging": {"pos":"n.m. 阳性名词，复数 leggings（常用复数；也有人说 une legging）","s":"打底裤；紧身裤。在法语里单数 un legging 指一条，说「一条打底裤」多用单数，穿了好几条或泛指时用 des leggings。","ipa":"[lə.ɡiŋ]","ph":"le 读 [lə] 或 [le]；gg 读 [ɡ]；-ing 读 [iŋ]。整词 [lə.ɡiŋ]。","pi":"性别有点不稳，常见 un legging，也能听到 une legging。别把 gg 读成 [dʒ]。","et":"来自英语 legging（leg + -ing，腿部包裹）。","ex":[["Elle fait du yoga en legging.","她穿打底裤做瑜伽。"],["J'ai acheté un legging noir.","我买了一条黑色打底裤。"],["Ce legging est très confortable.","这条打底裤很舒服。"]],"co":[["un legging noir","黑色打底裤"],["mettre un legging","穿打底裤"],["un legging de sport","运动紧身裤"]],"sy":[["collant","courant","连裤袜（不是打底裤）"],["pantalon moulant","courant","紧身裤"]],"fq":"中频，常用。","me":"leg（腿）+ -ing，读 [lə.ɡiŋ]。","tr":{"zh":"我穿打底裤运动。","fr":"Je mets un legging pour faire du sport.","alt":"Pour le sport, je prends un legging.","note":"法语通常用单数 un legging 指一条。"}},
 "Un maillot de bain": {"pos":"n.m. 阳性名词，复数 maillots de bain","s":"泳衣；游泳衣（男女都用，泳裤、连体、比基尼上衣都可以）。单独说 un maillot 还可以是「运动衫、球衣」：un maillot de foot。","ipa":"[ma.jo.də.bɛ̃]","ph":"maillot 里 ill 读 [j]：[ma.jo]；t 不发音；de 弱读 [də]；bain 是 [bɛ̃]。","pi":"maillot 结尾 t 不读；bain 的 ain 是鼻化 [ɛ̃]，不读出 n。","et":"maillot 来自 maille（针织的网眼），原指针织的紧身衣。","ex":[["J'ai oublié mon maillot de bain.","我忘了带泳衣。"],["Elle a un nouveau maillot de bain rouge.","她有一件新的红色泳衣。"],["Il met son maillot de bain pour nager.","他换上泳衣去游泳。"]],"co":[["mettre son maillot de bain","穿泳衣"],["un maillot de bain une pièce","连体泳衣"],["un maillot de foot","足球球衣"]],"sy":[["bikini","courant","比基尼（分体）"],["slip de bain","courant","男士三角泳裤"]],"fq":"中频，夏天常用。","me":"maillot = 针织衣；泳衣是水边的 maillot。","tr":{"zh":"别忘了你的泳衣。","fr":"N'oublie pas ton maillot de bain.","alt":"T'as pris ton maillot de bain ?","note":"maillot 单数；复数 maillots de bain。"}},
 "Un manteau": {"pos":"n.m. 阳性名词，复数 manteaux","s":"大衣；外套（冬天穿的较长较厚）。比 une veste 厚，比 un blouson 长。","ipa":"[mɑ̃.to]","ph":"an [ɑ̃] 鼻化；eau 读 [o]；t 不发音。整词 [mɑ̃.to]。","pi":"复数 manteaux（加 x，不是 s）；结尾 eau 只读 [o]。","et":"来自拉丁语 mantellum（斗篷）。","ex":[["J'ai un manteau chaud.","我有一件暖和的大衣。"],["Il fait froid, mets ton manteau.","天冷，穿上你的大衣。"],["Elle cherche un long manteau noir.","她在找一件黑色长大衣。"]],"co":[["mettre / enlever son manteau","穿上 / 脱下大衣"],["un manteau d'hiver","冬天的大衣"],["un manteau en laine","羊毛大衣"]],"sy":[["veste","courant","外套（较短）"],["blouson","courant","短夹克"],["imperméable","courant","雨衣"]],"fq":"高频，日常常用。","me":"manteau 像「盖在身上的 mantle」。","tr":{"zh":"她穿上大衣出门了。","fr":"Elle met son manteau et sort.","alt":"Elle prend son manteau et elle part.","note":"mettre = 穿上（动作）。"}},
 "Un objet": {"pos":"n.m. 阳性名词，复数 objets","s":"物品；东西。指你能拿在手里的具体东西。也有「目的、对象」的意思：l'objet de la réunion（会议的主题）。","ipa":"[ɔb.ʒɛ]","ph":"b 与 j 连读：[ɔb.ʒɛ]；j 读 [ʒ]；et 读 [ɛ]，t 不发音。","pi":"j 读 [ʒ]（像 sh 的浊音），不是 [dʒ]；结尾 t 不读；不要读成英语 object。","et":"来自拉丁语 objectum（放在前面的东西），与英语 object 同源。","ex":[["Quel est cet objet ?","这是什么东西？"],["Cet objet est très ancien.","这件东西很古老。"],["J'ai perdu un objet important.","我丢了一件重要的东西。"]],"co":[["un objet perdu","失物"],["les objets trouvés","失物招领处"],["un objet connecté","智能设备"]],"sy":[["chose","courant","事物（更泛）"],["truc","familier","东西、玩意儿"]],"fq":"高频，日常常用。","me":"object 去掉 c 加 -et 就是 objet。","tr":{"zh":"我不认识这个东西。","fr":"Je ne connais pas cet objet.","alt":"C'est quoi, cet objet ?","note":"cet objet：阳性名词前用 cet（元音前）。"}},
 "Un ordinateur (portable)": {"pos":"n.m. 阳性名词，复数 ordinateurs（portable 也可单独当名词）","s":"电脑；（笔记本）电脑。un ordinateur portable = 笔记本电脑。注意：单说 un portable 在法国通常是「手机」。","ipa":"[ɔʁ.di.na.tœʁ]","ph":"or [ɔʁ]；i [i]；na [na]；teur [tœʁ]；r 是小舌音。","pi":"portable 里的 -able 读 [pɔʁ.tabl]；不要把 ordinateur 和 order 联想成英语读法。","et":"来自拉丁语 ordinator（整理者），1950 年代由语言学家 Jacques Perret 为 IBM 提出。","ex":[["Je travaille sur mon ordinateur.","我用电脑工作。"],["Mon ordinateur portable est en panne.","我的笔记本电脑坏了。"],["Elle éteint l'ordinateur et part.","她关掉电脑就走了。"]],"co":[["allumer / éteindre l'ordinateur","开 / 关电脑"],["un ordinateur portable","笔记本电脑"],["sur ordinateur","在电脑上"]],"sy":[["PC","courant","个人电脑，日常说法"],["portable","courant","笔记本 / 手机，要看语境"]],"fq":"极高频，日常常用。","me":"ordinateur = 把东西「排好序」的机器。","tr":{"zh":"我有一台新的笔记本电脑。","fr":"J'ai un nouvel ordinateur portable.","alt":"J'ai un nouveau PC portable.","note":"元音前 nouvel（阳性）。"}},
 "Un pantalon": {"pos":"n.m. 阳性名词，复数 pantalons","s":"裤子；长裤。法语里一条裤子用单数 un pantalon，不是复数。短裤是 un short。","ipa":"[pɑ̃.ta.lɔ̃]","ph":"an [ɑ̃]；t 读 [t]；on [ɔ̃]；两个鼻化元音，n 都不读出。","pi":"两个鼻化元音 [ɑ̃] 和 [ɔ̃] 容易混；是单数，别说 des pantalon 来指一条裤子。","et":"来自意大利喜剧中的角色 Pantalone，他穿长裤；后来泛指长裤。","ex":[["Je cherche un pantalon noir.","我在找黑裤子。"],["Ce pantalon est trop petit.","这条裤子太小了。"],["Il a un pantalon en jean.","他穿一条牛仔裤。"]],"co":[["mettre / enlever un pantalon","穿上 / 脱下裤子"],["un pantalon court / long","短裤 / 长裤"],["un pantalon troué","破裤子"]],"sy":[["jean","courant","牛仔裤"],["short","courant","短裤"],["falzar","argot","裤子（俚语）"]],"fq":"高频，日常常用。","me":"pantalon = 一条裤子，一个 un。","tr":{"zh":"我的裤子太长了。","fr":"Mon pantalon est trop long.","alt":"Ce pantalon est un peu long pour moi.","note":"一条裤子用单数 pantalon，动词也用单数 est。"}},
 "Un porte-clé": {"pos":"n.m. 阳性名词，复数 porte-clés（标准拼写常为 un porte-clés，单复数同形）","s":"钥匙扣；钥匙链。词典里标准拼写是 un porte-clés（单数也有 s），书里写成 porte-clé 也被接受。","ipa":"[pɔʁt.kle]","ph":"porte 读 [pɔʁt]（t 要发音）；clé 读 [kle]；c 读 [k]。","pi":"porte 的 t 要读出来；clé 结尾的 é 是 [e]；别把 porte 当成「门」，这里是动词 porter 的形式。","et":"porter（拿着）+ clé（钥匙）：拿着钥匙的东西。同类词：porte-monnaie（零钱包）。","ex":[["J'ai perdu mon porte-clé.","我丢了钥匙扣。"],["Elle a un petit porte-clés en forme de chat.","她有一个猫形的小钥匙扣。"],["Mes clés sont sur mon porte-clés.","我的钥匙挂在钥匙扣上。"]],"co":[["un porte-clés en cuir","皮质钥匙扣"],["accrocher ses clés","把钥匙挂上"],["un porte-clés souvenir","纪念钥匙扣"]],"sy":[["anneau porte-clés","courant","钥匙圈"],["clé","courant","钥匙（本体）"]],"fq":"中频，日常。","me":"porte(拿着) + clé(钥匙) = 钥匙扣。","tr":{"zh":"我有一个新的钥匙扣。","fr":"J'ai un nouveau porte-clés.","alt":"J'ai un porte-clés tout neuf.","note":"porte-clés 单复数同形。"}},
 "Un portefeuille": {"pos":"n.m. 阳性名词，复数 portefeuilles","s":"钱包（装钞票和卡的长方形钱夹）。还有「部长职位」和「投资组合」的意思：un portefeuille ministériel。","ipa":"[pɔʁt.fœj]","ph":"porte 的 t 读 [t]；feuille 读 [fœj]（eu 读 [œ]，ill 读 [j]），e 不读。","pi":"feuille 拼写难：e-u-i-l-l-e，读音只有 [fœj]；别把 portefeuille 和 porte-monnaie（零钱包）混。","et":"porter（拿着）+ feuille（纸张，这里指钞票）。","ex":[["Mon portefeuille est dans mon sac.","我的钱包在包里。"],["On m'a volé mon portefeuille.","我的钱包被偷了。"],["Il sort son portefeuille de sa poche.","他从口袋里掏出钱包。"]],"co":[["perdre son portefeuille","丢了钱包"],["un portefeuille en cuir","皮钱包"],["un portefeuille d'actions","股票组合"]],"sy":[["porte-monnaie","courant","零钱包"],["pochette","courant","小包、卡包"]],"fq":"中高频，日常。","me":"portefeuille = 带着「纸」的东西。","tr":{"zh":"我把钱包忘在家里了。","fr":"J'ai oublié mon portefeuille à la maison.","alt":"J'ai laissé mon portefeuille chez moi.","note":"oublier qqch：忘带某物。"}},
 "Un pull": {"pos":"n.m. 阳性名词，复数 pulls（全称 un pull-over）","s":"毛衣；套头衫。pull 是 pull-over 的缩写。法国人说 un pull 就是一件套头针织衫。","ipa":"[pyl]","ph":"u 读 [y]（嘴唇圆，发 i 的位置）；ll 在这里读 [l]；整词 [pyl]。","pi":"u 不是 [u]，也不是英语的 [ʌ]；结尾的 l 要读出来。","et":"来自英语 pull-over（pull + over，从头上套下去）。","ex":[["J'aime ce pull en laine.","我喜欢这件羊毛衫。"],["Mets un pull, il fait frais.","穿件毛衣，天有点凉。"],["Mon pull est trop grand.","我的毛衣太大了。"]],"co":[["un pull en laine","羊毛衫"],["un pull à col roulé","高领毛衣"],["mettre un pull","穿毛衣"]],"sy":[["pull-over","courant","全称"],["sweat","courant","卫衣（棉）"],["gilet","courant","开衫"]],"fq":"极高频，日常常用。","me":"pull = pull-over：「从头套下去」。","tr":{"zh":"带件毛衣，今晚冷。","fr":"Prends un pull, il fait froid ce soir.","alt":"Prends un pull, il fait frisquet ce soir.","note":"天气用 il fait froid。"}},
 "Un rayon": {"pos":"n.m. 阳性名词，复数 rayons","s":"货架；柜台、部门（超市或商店里一个品类的区域）。还可以是「光线」un rayon de soleil、「半径」、「（自行车）辐条」。","ipa":"[ʁɛ.jɔ̃]","ph":"ay 在这里读 [ɛj]：[ʁɛ.jɔ̃]；on 是鼻化 [ɔ̃]，n 不读。","pi":"r 是小舌音；ay 读 [ɛj]，不是英语 ray 的 [eɪ]。","et":"来自古法语 rai（光线），拉丁语 radius（光线、辐条）。","ex":[["Où est le rayon des vêtements pour enfants ?","儿童服装区在哪里？"],["Le rayon fruits est au fond du magasin.","水果区在店里面。"],["Un rayon de soleil entre par la fenêtre.","一束阳光从窗户照进来。"]],"co":[["le rayon fruits et légumes","果蔬区"],["un rayon de soleil","一缕阳光"],["C'est mon rayon.","这是我的专长。"]],"sy":[["département","courant","（商场里的）部门"],["étagère","courant","架子（家里）"]],"fq":"中高频，购物时常用。","me":"rayon = 光线 = 一束一束的架子。","tr":{"zh":"鞋类区在二楼。","fr":"Le rayon des chaussures est au premier étage.","alt":"Les chaussures, c'est au premier, au rayon du fond.","note":"法国 premier étage = 中国说的二楼。"}},
 "Un sac": {"pos":"n.m. 阳性名词，复数 sacs","s":"包；袋子（一切装东西的袋或包）。比 un sac à main 更泛。也可以是「塑料袋」un sac plastique、「麻袋」。","ipa":"[sak]","ph":"a [a]；结尾 c 要读 [k]：[sak]；复数 s 不读。","pi":"结尾 c 要读出来：sac [sak]，和 sa 不一样；复数 sacs 也读 [sak]。","et":"来自拉丁语 saccus（袋子），与英语 sack 同源。","ex":[["Elle a un grand sac.","她有一个大包。"],["Mon sac est très lourd.","我的包很重。"],["Tu veux un sac plastique ?","你要塑料袋吗？"]],"co":[["un sac en cuir","皮包"],["un sac plastique","塑料袋"],["un sac de courses","购物袋"]],"sy":[["sachet","courant","小袋子"],["cabas","courant","购物篮包"]],"fq":"极高频，日常常用。","me":"sac = sack，结尾 c 要读 [k]。","tr":{"zh":"把你的包放这里。","fr":"Pose ton sac ici.","alt":"Mets ton sac là.","note":"poser = 放下；mettre = 放。"}},
 "Un sac à dos": {"pos":"n.m. 阳性名词，复数 sacs à dos","s":"背包；双肩包。字面是「背上的包」：sac + à（用于）+ dos（背）。","ipa":"[sa.ka.do]","ph":"sac 的 c 与后面的 à 连在一起读 [sa.ka.do]；dos 的 s 不读。","pi":"dos 结尾 s 不读：[do]，不要读成 [dos]；复数只在 sac 加 s：sacs à dos。","et":"sac（包）+ à（带）+ dos（背）；dos 来自拉丁语 dorsum 的后期形式。","ex":[["Je mets mes livres dans mon sac à dos.","我把书放进背包。"],["Il porte un sac à dos pour l'école.","他背着书包上学。"],["Mon sac à dos est trop lourd.","我的背包太重了。"]],"co":[["mettre son sac à dos","背上背包"],["un sac à dos de randonnée","登山包"],["voyager avec un sac à dos","背包旅行"]],"sy":[["cartable","courant","书包（学生）"],["besace","soutenu","挎包"]],"fq":"高频，日常常用。","me":"sac + 到背上（à dos）= 背包。","tr":{"zh":"我把电脑放进背包了。","fr":"J'ai mis mon ordinateur dans mon sac à dos.","alt":"J'ai rangé mon ordi dans mon sac à dos.","note":"mettre ... dans + 容器。"}},
 "Un sac à main": {"pos":"n.m. 阳性名词，复数 sacs à main","s":"手提包；女包（用手拎的包）。字面是「手里的包」：sac + à + main。","ipa":"[sa.ka.mɛ̃]","ph":"c 与 à 连读：[sa.ka]；main 读 [mɛ̃]，ain 是鼻化元音，n 不读。","pi":"main 读 [mɛ̃]，不是 [man]；整个词里 sac 的 c 要读出来。","et":"sac（包）+ à（用于）+ main（手）；main 来自拉丁语 manus。","ex":[["Où est mon sac à main ?","我的手提包在哪里？"],["Elle cherche ses clés dans son sac à main.","她在手提包里找钥匙。"],["J'ai acheté un nouveau sac à main rouge.","我买了一个新的红色手提包。"]],"co":[["un sac à main en cuir","皮手提包"],["ouvrir son sac à main","打开手提包"],["un sac à main de luxe","奢侈品手提包"]],"sy":[["sac","courant","包（更泛）"],["pochette","courant","小手包"]],"fq":"中频，日常。","me":"手(main)里的包 = 手提包。","tr":{"zh":"她把手提包忘在出租车里了。","fr":"Elle a oublié son sac à main dans le taxi.","alt":"Elle a laissé son sac à main dans le taxi.","note":"oublier 与 laisser：忘记 / 留下。"}},
 "Un sac de sport": {"pos":"n.m. 阳性名词，复数 sacs de sport","s":"运动包；健身包。装运动服和鞋的大包。sac de sport 是 de + 名词，表示用途。","ipa":"[sak.də.spɔʁ]","ph":"sac 的 c 读 [k]；de 轻读 [də]；sport 读 [spɔʁ]，t 不读，r 要发。","pi":"sport 结尾 t 不读，但 r 要读：[spɔʁ]；不要加 e。","et":"sac + de + sport；sport 来自英语，原自古法语 desport（娱乐）。","ex":[["Il prend son sac de sport.","他拿起他的运动包。"],["Mon sac de sport est dans la voiture.","我的运动包在车里。"],["N'oublie pas ton sac de sport demain.","明天别忘了带运动包。"]],"co":[["faire son sac de sport","收拾运动包"],["un sac de sport noir","黑色运动包"],["un sac de sport pour la piscine","游泳包"]],"sy":[["sac de gym","courant","健身包"],["sac de voyage","courant","旅行包"]],"fq":"中频，日常。","me":"sport 结尾 t 不读，r 读。","tr":{"zh":"你把我的运动包放哪了？","fr":"Où as-tu mis mon sac de sport ?","alt":"T'as vu mon sac de sport ?","note":"疑问句中 tu 与动词倒装。"}},
 "Un sandwich": {"pos":"n.m. 阳性名词，复数 sandwichs 或 sandwiches","s":"三明治；夹馅面包。法国最常见的是法棍夹火腿或奶酪：un sandwich jambon-beurre。","ipa":"[sɑ̃d.witʃ]","ph":"an [ɑ̃]；ch 读 [tʃ]（像英语 church），整词 [sɑ̃d.witʃ]；d 读出来。","pi":"ch 读 [tʃ]，不是法语常见的 [ʃ]；an 是鼻化元音。","et":"来自英语 sandwich，得名于第四代三明治伯爵 Earl of Sandwich。","ex":[["Je mange un sandwich à midi.","我中午吃三明治。"],["Il prend un sandwich au poulet.","他点了一个鸡肉三明治。"],["On fait des sandwichs pour le pique-nique.","我们为野餐做三明治。"]],"co":[["un sandwich jambon-fromage","火腿奶酪三明治"],["manger un sandwich","吃三明治"],["un sandwich au thon","金枪鱼三明治"]],"sy":[["casse-croûte","familier","（简单的）点心、便当"],["panini","courant","帕尼尼（热压）"]],"fq":"高频，日常常用。","me":"sandwich 的 ch 读 [tʃ]，像英语。","tr":{"zh":"我们在长椅上吃三明治好吗？","fr":"On mange un sandwich sur le banc ?","alt":"Un sandwich sur le banc, ça te dit ?","note":"On = 我们（口语）。"}},
 "Un short": {"pos":"n.m. 阳性名词，复数 shorts","s":"短裤。法语里一条短裤用单数 un short，不像英语 shorts 只用复数。游泳裤：un short de bain。","ipa":"[ʃɔʁt]","ph":"sh 读 [ʃ]（像「希」），o [ɔ]，r 是小舌音，t 要读：[ʃɔʁt]。","pi":"t 要读出来；别把 short 当成形容词，「短」的形容词是 court。","et":"来自英语 shorts，词源是 short（短的）。","ex":[["Je porte un short à la plage.","我在海滩穿短裤。"],["Il fait chaud, je mets un short.","天热，我穿短裤。"],["Elle a un short en jean.","她有一条牛仔短裤。"]],"co":[["un short de bain","泳裤"],["un short en jean","牛仔短裤"],["mettre un short","穿短裤"]],"sy":[["bermuda","courant","及膝短裤"],["pantacourt","courant","七分裤"]],"fq":"中高频，夏天常用。","me":"short = 短裤，t 也要读。","tr":{"zh":"夏天我穿短裤。","fr":"En été, je porte un short.","alt":"L'été, je suis toujours en short.","note":"en été：夏天用 en。"}},
 "Un sweat": {"pos":"n.m. 阳性名词，复数 sweats（全称 sweat-shirt）","s":"卫衣；运动衫。是 sweat-shirt 的缩写。带帽子的叫 un sweat à capuche。","ipa":"[swɛt]","ph":"sw 读 [sw]；ea 在这里读 [ɛ]；t 读出来：[swɛt]。","pi":"t 要读出来；不要把 sweat 当成「汗」，汗是 la sueur。","et":"来自英语 sweatshirt（sweat 出汗 + shirt），原为运动后吸汗的衣服。","ex":[["Il porte un sweat pour faire du sport en hiver.","他冬天穿卫衣运动。"],["Mets un sweat, il fait frais.","穿件卫衣，天有点凉。"],["J'ai acheté un sweat à capuche.","我买了一件连帽卫衣。"]],"co":[["un sweat à capuche","连帽卫衣"],["un sweat gris","灰色卫衣"],["mettre un sweat","穿卫衣"]],"sy":[["sweat-shirt","courant","全称"],["pull","courant","毛衣"],["hoodie","familier","连帽卫衣（英语借词）"]],"fq":"中高频，日常。","me":"sweat = sweat-shirt，但不是「汗」。","tr":{"zh":"他穿卫衣去跑步。","fr":"Il met un sweat pour aller courir.","alt":"Il enfile un sweat pour aller courir.","note":"aller + 动词原形。"}},
 "Un t-shirt": {"pos":"n.m. 阳性名词，复数 t-shirts（也写 tee-shirt）","s":"T 恤。简称 un tee-shirt。圆领短袖上衣。","ipa":"[ti.ʃœʁt]","ph":"t 读 [ti]；shirt 读 [ʃœʁt]，不是英语 [ʃɜːt]；r 是小舌音，t 要读。","pi":"shirt 中 ir 读 [œʁ]；t 要读；听起来像「蒂-舍尔特」。","et":"来自英语 T-shirt，形状像字母 T。","ex":[["Je mets un t-shirt en été.","夏天我穿 T 恤。"],["Ce t-shirt est trop petit pour moi.","这件 T 恤对我来说太小了。"],["Elle porte un t-shirt blanc.","她穿一件白色 T 恤。"]],"co":[["un t-shirt à manches courtes","短袖 T 恤"],["un t-shirt blanc","白 T 恤"],["mettre un t-shirt","穿 T 恤"]],"sy":[["tee-shirt","courant","同一个词的另一种写法"],["débardeur","courant","背心"]],"fq":"极高频，日常常用。","me":"T-shirt：像字母 T 的衣服。","tr":{"zh":"我更喜欢棉质 T 恤。","fr":"Je préfère les t-shirts en coton.","alt":"J'aime mieux les t-shirts en coton.","note":"préférer les + 复数名词表泛指。"}},
 "De la laine": {"pos":"n.f. 阴性名词，不可数（常用 de la laine），复数 laines 少用","s":"羊毛；毛线；毛料。不可数时用部分冠词 de la：de la laine = 一些羊毛。en laine = 羊毛制的。","ipa":"[lɛn]","ph":"ai 读 [ɛ]；n 要读出来；结尾 e 不读。整词 [lɛn]，只有一个音节。","pi":"ain（如 main）鼻化，但 laine 里 n 后面有 e，所以 n 要读，ai 不鼻化。","et":"来自拉丁语 lana（羊毛）。同族词：lainage（毛织物）。","ex":[["Un pull en laine.","一件羊毛衫。"],["Ce manteau est en laine.","这件大衣是羊毛的。"],["Elle tricote avec de la laine bleue.","她用蓝色毛线织东西。"]],"co":[["en laine","羊毛制的"],["de la laine de mouton","羊毛"],["une pelote de laine","一团毛线"]],"sy":[["coton","courant","棉（对比）"],["cachemire","courant","羊绒"]],"fq":"中频，日常。","me":"laine 单音节，n 读出来。","tr":{"zh":"这件毛衣是羊毛的还是棉的？","fr":"Ce pull est en laine ou en coton ?","alt":"Ce pull, c'est de la laine ou du coton ?","note":"en + 材料；de la/du + 物质。"}},
 "La météo": {"pos":"n.f. 阴性名词，通常单数 la météo","s":"天气预报；气象。是 météorologie 的缩写。说「今天天气好」多用 il fait beau，而 la météo 更常指「预报」：la météo annonce de la pluie。","ipa":"[me.te.o]","ph":"三个音节 me-te-o：é [e]，é [e]，o [o]，没有二合元音。","pi":"météo 有两个 é；météo 是「预报」，天气本身用 le temps（il fait beau）。","et":"météo 是 météorologie 的缩写，来自希腊语 meteoros（高空）+ logos（学问）。","ex":[["La météo annonce de la pluie demain.","天气预报说明天有雨。"],["Tu as regardé la météo ?","你看天气预报了吗？"],["La météo est bonne pour le week-end.","周末的天气预报不错。"]],"co":[["regarder la météo","看天气预报"],["la météo du week-end","周末天气预报"],["selon la météo","根据天气预报"]],"sy":[["le temps","courant","天气本身"],["les prévisions","courant","预报"]],"fq":"高频，日常常用。","me":"météo：三个音节 me-te-o。","tr":{"zh":"天气预报说明天怎么样？","fr":"Qu'est-ce que la météo dit pour demain ?","alt":"La météo, elle dit quoi pour demain ?","note":"dire pour + 日期。"}},
 "La pointure": {"pos":"n.f. 阴性名词，复数 pointures","s":"鞋码；鞋的尺码（也用于手套、帽子，但通常指鞋）。问鞋码：Tu fais quelle pointure ? 或 Quelle est ta pointure ? 说「我穿 40 码」：Je chausse du 40 / Je fais du 40。","ipa":"[pwɛ̃.tyʁ]","ph":"oin 读 [wɛ̃]；t 读 [t]；u 读 [y]；结尾 re 读 [ʁ]，e 不读。","pi":"和 taille 不同：pointure 只用于鞋；oin 的 n 不读。","et":"来自 pointe（点、尖）加后缀 -ure；家族词：point、pointu。更早的来源不太确定。","ex":[["Tu fais quelle pointure ?","你穿多大码的鞋？"],["Je fais du 38 en pointure.","我穿 38 码的鞋。"],["Cette pointure est trop petite.","这个鞋码太小了。"]],"co":[["quelle pointure ?","多大鞋码？"],["faire du 40","穿 40 码"],["changer de pointure","换鞋码"]],"sy":[["taille","courant","衣服尺码"],["chausser","courant","穿多大码（动词）"]],"fq":"中频，买鞋时常用。","me":"鞋 = pointure，衣服 = taille。","tr":{"zh":"我想找这双鞋的 42 码。","fr":"Je cherche ces chaussures en pointure 42.","alt":"Vous les avez en 42 ?","note":"en + 尺码：en pointure 42。"}},
 "La taille": {"pos":"n.f. 阴性名词，复数 tailles","s":"尺码；个头；腰围。Tu fais quelle taille ? = 你穿什么码？de grande taille = 个子高大。tour de taille = 腰围。","ipa":"[taj]","ph":"ill 在这里读 [j]：[taj]；结尾 e 不读。","pi":"ill 读 [j]，不是 [il]；taille 听起来像英语 tie，不像 tail。","et":"来自动词 tailler（切、剪）。同族词：tailleur（裁缝；套装）。","ex":[["Tu fais quelle taille ?","你穿什么尺码？"],["Je fais du M, taille moyenne.","我穿 M 码，中号。"],["Elle est de petite taille.","她个子不高。"]],"co":[["quelle taille ?","什么尺码？"],["taille unique","均码"],["un tour de taille","腰围"]],"sy":[["pointure","courant","鞋码"],["grandeur","courant","大小（泛指）"]],"fq":"极高频，日常常用。","me":"taille 读 [taj]，像英语 tie。","tr":{"zh":"我想要这件 M 码的毛衣。","fr":"Je voudrais ce pull en taille M.","alt":"Vous l'avez en M, ce pull ?","note":"en taille M：指定尺码。"}},
 "Une batterie": {"pos":"n.f. 阴性名词，复数 batteries","s":"电池；电量。手机、汽车里的可充电电池叫 batterie；遥控器用的一次性小电池叫 pile。也指鼓：la batterie（架子鼓）。","ipa":"[ba.tʁi]","ph":"tt 是一个 [t]；rie 读 [ʁi]：[ba.tʁi]，三个音节；e 不读。","pi":"和 pile 区分：手机、汽车用 batterie；遥控器用的小电池是 pile。","et":"来自动词 battre（打击），加后缀 -erie；最初指一组炮、一组「击打」的东西。","ex":[["Je n'ai plus de batterie.","我没电了。"],["La batterie de mon téléphone est faible.","我手机的电量低了。"],["Mon frère joue de la batterie.","我哥哥打鼓。"]],"co":[["recharger la batterie","给电池充电"],["une batterie faible","电量低"],["jouer de la batterie","打架子鼓"]],"sy":[["pile","courant","一次性小电池"],["autonomie","courant","续航"]],"fq":"高频，日常常用。","me":"battre 打 → batterie：电池像一排会「打」的东西。","tr":{"zh":"我的手机没电了。","fr":"Mon téléphone n'a plus de batterie.","alt":"Mon portable est à plat.","note":"ne ... plus de + 名词。"}},
 "Une batterie externe": {"pos":"n.f. 阴性名词，复数 batteries externes","s":"充电宝；外接电池。外接充电器。也常直接说 une batterie externe 或英语 power bank。","ipa":"[ba.tʁi.ɛk.stɛʁn]","ph":"batterie [ba.tʁi]；externe [ɛk.stɛʁn]：x 读 [ks]，e 不读。","pi":"externe 阴阳性同形（外接的）；batterie 阴性，所以是 une batterie externe。","et":"batterie + externe（拉丁语 externus，外面的）。","ex":[["Je peux emprunter ta batterie externe ?","我可以借你的充电宝吗？"],["Ma batterie externe est vide.","我的充电宝没电了。"],["J'emporte toujours une batterie externe en voyage.","出门旅行我总带充电宝。"]],"co":[["recharger une batterie externe","给充电宝充电"],["brancher le téléphone à la batterie externe","把手机连到充电宝"],["batterie externe de secours","备用充电宝"]],"sy":[["power bank","familier","英语借词，口语"],["chargeur portable","courant","便携充电器"]],"fq":"中频，现代常用。","me":"外面的电池 = 充电宝。","tr":{"zh":"请借我你的充电宝。","fr":"Prête-moi ta batterie externe, s'il te plaît.","alt":"T'aurais une batterie externe à me prêter ?","note":"prêter qqch à qqn。"}},
 "Une cabine d'essayage": {"pos":"n.f. 阴性名词，复数 cabines d'essayage","s":"试衣间。在商店里试穿衣服的小隔间。essayage = 试穿（来自 essayer）。","ipa":"[ka.bin.de.sɛ.jaʒ]","ph":"d' 是 de 的省音；essayage 读 [e.sɛ.jaʒ]：ay 读 [ɛj]；ge 读 [ʒ]，e 不读。","pi":"essayage 的 ss 与 ay 要拼清：e-ss-ay-age；别写成 cabine de essayage（要省音 d'）。","et":"cabine + essayage；essayage 由 essayer（试）加 -age 构成，essayer 来自拉丁语 exagium（称重、检验）。","ex":[["Où sont les cabines d'essayage ?","试衣间在哪里？"],["La cabine d'essayage est libre.","试衣间是空的。"],["Je peux essayer ce pantalon en cabine ?","我可以去试衣间试这条裤子吗？"]],"co":[["aller en cabine d'essayage","去试衣间"],["essayer un vêtement","试穿衣服"],["la cabine d'essayage libre","空的试衣间"]],"sy":[["cabine","courant","试衣间（简称）"],["salon d'essayage","soutenu","试衣厅（高档）"]],"fq":"中频，购物时常用。","me":"essayer 试 → essayage 试穿 → cabine d'essayage。","tr":{"zh":"我去试衣间试这条裙子。","fr":"Je vais essayer cette robe en cabine.","alt":"J'essaie cette robe, la cabine est où ?","note":"aller + 原形；essayer = 试穿。"}},
 "Une ceinture": {"pos":"n.f. 阴性名词，复数 ceintures","s":"腰带；皮带。另有「安全带」ceinture de sécurité、「武术段位带」ceinture noire。","ipa":"[sɛ̃.tyʁ]","ph":"c 在 e 前读 [s]；ein 读 [ɛ̃]（鼻化）；u [y]；r [ʁ]。整词 [sɛ̃.tyʁ]。","pi":"ein 读鼻化 [ɛ̃]，n 不读；不要读成英语 sin-ture。","et":"来自拉丁语 cinctura（系腰），源自 cingere（系、环绕）。","ex":[["J'ai besoin d'une ceinture pour mon pantalon.","我的裤子需要一条腰带。"],["Attache ta ceinture dans la voiture.","在车里系好安全带。"],["Il a une ceinture noire de judo.","他是柔道黑带。"]],"co":[["une ceinture en cuir","皮带"],["une ceinture de sécurité","安全带"],["une ceinture noire","黑带"]],"sy":[["ceinturon","courant","军用宽皮带"],["sangle","courant","带子、背带"]],"fq":"中频，日常。","me":"ceinture 里有 ein 鼻化音。","tr":{"zh":"系好安全带，我们出发。","fr":"Attache ta ceinture, on démarre.","alt":"Mets ta ceinture, on y va.","note":"attacher / mettre sa ceinture。"}},
 "Une chemise": {"pos":"n.f. 阴性名词，复数 chemises","s":"衬衫（有领、有扣的）。还有「文件夹」chemise cartonnée、「睡衣」chemise de nuit。女式衬衫更常叫 un chemisier。","ipa":"[ʃə.miz]","ph":"ch 读 [ʃ]；e 读 [ə]；mi 读 [mi]；s 在两个元音间读 [z]：[ʃə.miz]。","pi":"ch 读 [ʃ]（像「西」）；s 读 [z]；结尾 e 不读。","et":"来自晚期拉丁语 camisia（衬衣）。","ex":[["C'est une belle chemise blanche.","这是一件漂亮的白衬衫。"],["Il repasse sa chemise.","他在熨衬衫。"],["Elle met une chemise à carreaux.","她穿一件格子衬衫。"]],"co":[["une chemise blanche","白衬衫"],["une chemise à manches longues","长袖衬衫"],["repasser une chemise","熨衬衫"]],"sy":[["chemisier","courant","女式衬衫"],["t-shirt","courant","T 恤（无领）"]],"fq":"高频，日常常用。","me":"chemise 是阴性：une chemise。","tr":{"zh":"这件衬衫对我来说太小了。","fr":"Cette chemise est trop petite pour moi.","alt":"Cette chemise me va pas, elle est trop petite.","note":"trop + 形容词。"}},
 "Une coque de téléphone": {"pos":"n.f. 阴性名词，复数 coques de téléphone","s":"手机壳。coque 本来是「壳」：coque d'œuf（蛋壳）、coque de bateau（船体）。","ipa":"[kɔk.də.te.le.fɔn]","ph":"coque 读 [kɔk]（qu = k）；de [də]；téléphone：ph 读 [f]，结尾 e 不读。","pi":"coque 里 qu 读 [k]；téléphone 有三个 é；ph 读 [f]。","et":"coque 的来源不太确定；téléphone 来自希腊语 tele（远）+ phone（声音）。","ex":[["J'ai une nouvelle coque de téléphone.","我有一个新手机壳。"],["Ma coque de téléphone est transparente.","我的手机壳是透明的。"],["Elle cherche une coque pour son téléphone.","她在找手机壳。"]],"co":[["une coque transparente","透明壳"],["mettre une coque","装手机壳"],["une coque d'œuf","蛋壳"]],"sy":[["housse","courant","保护套（软）"],["étui","courant","皮套"]],"fq":"中频，现代常用。","me":"coque = 壳，手机的「壳」。","tr":{"zh":"我在找手机壳。","fr":"Je cherche une coque pour mon téléphone.","alt":"Vous avez des coques pour ce modèle ?","note":"pour + 名词：为……。"}},
 "Une couleur": {"pos":"n.f. 阴性名词，复数 couleurs","s":"颜色。问颜色：De quelle couleur est ... ? 颜色形容词通常放名词后：une robe rouge。","ipa":"[ku.lœʁ]","ph":"ou 读 [u]；eu 读 [œ]；r 读 [ʁ]：[ku.lœʁ]。","pi":"拼写以 -eur 结尾，不是 -or；ou 读 [u]，不是 [o]；是阴性词。","et":"来自拉丁语 color（颜色）。","ex":[["Quelle est ta couleur préférée ?","你最喜欢的颜色是什么？"],["De quelle couleur est ta voiture ?","你的车是什么颜色的？"],["Cette robe existe en plusieurs couleurs.","这条裙子有好几种颜色。"]],"co":[["de quelle couleur","什么颜色"],["une couleur vive / claire / foncée","鲜艳 / 浅 / 深色"],["en couleur(s)","彩色的"]],"sy":[["teinte","soutenu","色调"],["nuance","courant","色度"]],"fq":"极高频，日常常用。","me":"couleur：ou-eu 两个元音。","tr":{"zh":"你的包是什么颜色的？","fr":"Quelle est la couleur de ton sac ?","alt":"C'est de quelle couleur, ton sac ?","note":"la couleur de + 名词。"}},
 "Une cravate": {"pos":"n.f. 阴性名词，复数 cravates","s":"领带。穿西装、正式场合戴。成语：mettre une cravate = 系领带。","ipa":"[kʁa.vat]","ph":"cr 读 [kʁ]；a [a]；v [v]；结尾 -ate 读 [at]，t 要读出来。","pi":"结尾 t 要读：cravate [kʁa.vat]；是阴性名词。","et":"来自 Croate（克罗地亚人）：17 世纪克罗地亚雇佣兵脖子上系的布巾。","ex":[["Il a une cravate bleue.","他有一条蓝色领带。"],["Mon père met une cravate pour le travail.","我爸爸上班系领带。"],["Il ne porte jamais de cravate.","他从不戴领带。"]],"co":[["mettre / porter une cravate","系 / 戴领带"],["une cravate en soie","真丝领带"],["un costume-cravate","西装领带"]],"sy":[["nœud papillon","courant","领结"],["foulard","courant","丝巾"]],"fq":"中频，日常。","me":"cravate ← Croate：克罗地亚兵的围巾。","tr":{"zh":"他系领带去面试。","fr":"Il met une cravate pour son entretien.","alt":"Il enfile une cravate pour son entretien.","note":"mettre une cravate = 系领带。"}},
 "Une écharpe": {"pos":"n.f. 阴性名词，复数 écharpes","s":"围巾（长条形，冬天保暖）。更薄的丝巾叫 un foulard。另有「肩带、绶带」：écharpe de maire（市长的绶带）。","ipa":"[e.ʃaʁp]","ph":"é [e]；ch 读 [ʃ]；a [a]；r [ʁ]；p 读 [p]，结尾 e 不读：[e.ʃaʁp]。","pi":"p 要读出来，e 不读；écharpe 以元音开头，所以说 l'écharpe。","et":"来源不太确定：古法语 escherpe，可能与法兰克语有关。","ex":[["Il fait froid, mets ton écharpe.","天冷，戴上你的围巾。"],["Elle a une écharpe rouge.","她有一条红围巾。"],["J'ai oublié mon écharpe chez toi.","我把围巾落在你家了。"]],"co":[["mettre / enlever une écharpe","戴上 / 取下围巾"],["une écharpe en laine","羊毛围巾"],["un bonnet et une écharpe","帽子和围巾"]],"sy":[["foulard","courant","丝巾、薄围巾"],["cache-nez","courant","护脖围巾"]],"fq":"中频，冬天常用。","me":"écharpe：e-charpe，围着的「charpe」。","tr":{"zh":"别忘了你的围巾和帽子。","fr":"N'oublie pas ton écharpe et ton bonnet.","alt":"Prends ton écharpe et ton bonnet.","note":"n'oublie pas + 名词。"}},
 "Une enceinte (bluetooth)": {"pos":"n.f. 阴性名词，复数 enceintes（形容词 enceinte 另有「怀孕」意思）","s":"音箱（enceinte bluetooth = 蓝牙音箱）。是 enceinte acoustique 的缩写。同一个词作形容词是「怀孕的」，也可以是「围墙」：l'enceinte du château。","ipa":"[ɑ̃.sɛ̃t]","ph":"en [ɑ̃]，ein [ɛ̃]，两个鼻化元音；结尾 te 读 [t]（t 要读出来）：[ɑ̃.sɛ̃t]。","pi":"Elle est enceinte = 她怀孕了！说「音箱」时别说错语境；ein 是鼻化元音，t 要读。","et":"来自拉丁语 incincta / incingere（围起来）。「围墙」的意思是本义，「音箱」是现代用法。","ex":[["On écoute de la musique sur l'enceinte.","我们用音箱听音乐。"],["J'ai acheté une enceinte bluetooth.","我买了一个蓝牙音箱。"],["Elle est enceinte de cinq mois.","她怀孕五个月了。"]],"co":[["une enceinte bluetooth","蓝牙音箱"],["une enceinte connectée","智能音箱"],["l'enceinte du château","城堡的围墙"]],"sy":[["haut-parleur","courant","扬声器"],["baffle","familier","音箱（口语）"]],"fq":"中高频，日常（音箱义）。","me":"enceinte 两义：音箱 / 怀孕。","tr":{"zh":"我们用音箱放音乐吧？","fr":"On met de la musique sur l'enceinte ?","alt":"On met la musique sur l'enceinte ?","note":"on = 我们（口语）。"}},
 "Une friperie": {"pos":"n.f. 阴性名词，复数 friperies","s":"旧货店；二手服装店。卖二手衣服的店。fripes = 二手衣服。","ipa":"[fʁip.ʁi]","ph":"fr 读 [fʁ]；i [i]；p [p]；rie 读 [ʁi]：[fʁip.ʁi]；e 不读。","pi":"有两个 r 音，容易读乱：fri-pe-rie 中间的 e 通常不读。","et":"来自 fripier（旧衣商），古法语 freperie，更早的来源不太确定。","ex":[["J'achète mes vêtements dans une friperie.","我在旧货店买衣服。"],["Cette friperie vend de beaux manteaux.","这家旧货店卖漂亮的大衣。"],["Elle trouve toujours des pulls en friperie.","她总能在旧货店找到毛衣。"]],"co":[["aller en friperie","去旧货店"],["acheter en friperie","在二手店买"],["les fripes","二手衣服"]],"sy":[["dépôt-vente","courant","寄卖店"],["vide-dressing","courant","衣橱清仓（二手衣服集市）"]],"fq":"中频，年轻人常用。","me":"fripe 是旧衣服，friperie 是卖它的店。","tr":{"zh":"这个周末我去旧货店。","fr":"Je vais à la friperie ce week-end.","alt":"Ce week-end, on va en friperie ?","note":"aller à la / en friperie 都可以。"}},
 "Une jupe": {"pos":"n.f. 阴性名词，复数 jupes","s":"裙子（半身裙）。连衣裙是 une robe。jupe-culotte = 裙裤。","ipa":"[ʒyp]","ph":"j 读 [ʒ]；u 读 [y]；p 要读：[ʒyp]；结尾 e 不读，但 p 读出来。","pi":"u 读 [y]，不是 [u]；jupe 和 jus（果汁，[ʒy]）只差一个 p。","et":"来自阿拉伯语 jubba（长袍），经意大利语进入法语。","ex":[["Elle porte une jupe courte.","她穿一条短裙。"],["J'ai acheté une jupe noire.","我买了一条黑色半身裙。"],["Cette jupe est trop longue.","这条裙子太长了。"]],"co":[["une jupe courte / longue","短裙 / 长裙"],["une jupe plissée","百褶裙"],["mettre une jupe","穿裙子"]],"sy":[["robe","courant","连衣裙"],["minijupe","courant","迷你裙"]],"fq":"高频，日常常用。","me":"jupe 的 p 要读出来。","tr":{"zh":"她夏天穿裙子。","fr":"Elle met une jupe en été.","alt":"L'été, elle est toujours en jupe.","note":"porter / mettre 一条裙子。"}},
 "Une montre": {"pos":"n.f. 阴性名词，复数 montres","s":"手表。montre 来自动词 montrer（展示），字面是「显示时间的东西」。一般的钟是 une horloge / un réveil。","ipa":"[mɔ̃tʁ]","ph":"on 鼻化 [ɔ̃]；t 与 r 连读 [tʁ]，结尾 e 弱读或不读：[mɔ̃tʁ]。","pi":"montre（表）和 montrer（展示）读音接近：[mɔ̃tʁ] / [mɔ̃.tʁe]；on 不读 n。","et":"来自动词 montrer（展示），拉丁语 monstrare。","ex":[["Sa montre coûte cher.","他的表很贵。"],["Quelle heure est-il à ta montre ?","你的表几点了？"],["Il regarde sa montre.","他看了看手表。"]],"co":[["regarder sa montre","看手表"],["une montre en or","金表"],["une course contre la montre","与时间赛跑"]],"sy":[["horloge","courant","挂钟、大钟"],["réveil","courant","闹钟"]],"fq":"高频，日常常用。","me":"montre = 会「show」时间的表。","tr":{"zh":"我的表慢了五分钟。","fr":"Ma montre est en retard de cinq minutes.","alt":"Ma montre retarde de cinq minutes.","note":"être en retard / retarder 都可。"}},
 "Une montre connectée": {"pos":"n.f. 阴性名词，复数 montres connectées","s":"智能手表。connectée = 联网的（connecter 的过去分词作形容词，随 montre 用阴性）。","ipa":"[mɔ̃tʁ.kɔ.nɛk.te]","ph":"montre [mɔ̃tʁ]；connectée [kɔ.nɛk.te]：nn 读一个 [n]，结尾 ée 读 [e]。","pi":"connectée 要和 montre 一致用阴性（有 e）；connecté 是阳性。","et":"montre + connectée（拉丁语 connectere，连接）。","ex":[["J'ai acheté une montre connectée.","我买了一块智能手表。"],["Ma montre connectée compte mes pas.","我的智能手表会记步。"],["Elle recharge sa montre connectée chaque soir.","她每晚给智能手表充电。"]],"co":[["une montre connectée sportive","运动智能手表"],["recharger sa montre","给手表充电"],["compter ses pas","记步"]],"sy":[["smartwatch","familier","英语借词"],["bracelet connecté","courant","智能手环"]],"fq":"中频，现代常用。","me":"connectée：和 montre 一样是阴性。","tr":{"zh":"我的智能手表告诉我时间和脉搏。","fr":"Ma montre connectée me dit l'heure et mon pouls.","alt":"Ma montre connectée affiche l'heure et mon pouls.","note":"dire qqch à qqn。"}},
 "Une photo": {"pos":"n.f. 阴性名词，复数 photos","s":"照片。photo 是 photographie 的缩写。拍照：prendre une photo 或 faire une photo。","ipa":"[fɔ.to]","ph":"ph 读 [f]；第一个 o 读 [ɔ]，第二个 o 读 [o]；复数 s 不读：[fɔ.to]。","pi":"ph 读 [f]；两个 o 读音不同；复数 photos 的 s 不读。","et":"photographie 的缩写；希腊语 phos / photos（光）+ graphein（写）。","ex":[["On prend une photo ?","我们拍张照吧？"],["J'ai une photo de mes parents.","我有一张我父母的照片。"],["Cette photo est très belle.","这张照片很美。"]],"co":[["prendre une photo","拍照"],["une photo de profil","头像"],["sur la photo","在照片上"]],"sy":[["cliché","soutenu","照片（较书面）"],["selfie","familier","自拍"]],"fq":"极高频，日常常用。","me":"photo = phot(光) + 写，ph = f。","tr":{"zh":"你可以给我拍张照吗？","fr":"Tu peux me prendre en photo ?","alt":"Tu me prends en photo, s'il te plaît ?","note":"prendre qqn en photo。"}},
 "Une robe": {"pos":"n.f. 阴性名词，复数 robes","s":"连衣裙。另有 robe de chambre（睡袍）、robe de mariée（婚纱）。注意：法语 robe 是「连衣裙」，不是英语 robe（浴袍 = peignoir）。","ipa":"[ʁɔb]","ph":"r [ʁ]；o 读 [ɔ]；b 读 [b]；结尾 e 不读：[ʁɔb]。","pi":"robe 不是浴袍；o 是开口 [ɔ]，不是 [o]；b 要读。","et":"来自法兰克语 *rauba（战利品、衣服），与英语 rob、robe 同源。","ex":[["C'est une belle robe rouge.","这是一条漂亮的红裙子。"],["Elle met une robe pour la fête.","她穿裙子去参加聚会。"],["Cette robe est trop courte.","这条裙子太短了。"]],"co":[["une robe de soirée","晚礼服"],["une robe de mariée","婚纱"],["une robe d'été","夏装连衣裙"]],"sy":[["jupe","courant","半身裙"],["peignoir","courant","浴袍"]],"fq":"高频，日常常用。","me":"robe = 连衣裙，不是浴袍。","tr":{"zh":"她晚上穿一条红裙子。","fr":"Elle a une robe rouge pour la soirée.","alt":"Elle porte une petite robe rouge ce soir.","note":"rouge 在名词后。"}},
 "Une surprise": {"pos":"n.f. 阴性名词，复数 surprises","s":"惊喜；意外。可好可坏：une bonne / mauvaise surprise。感叹用法：Surprise ! = 惊喜！也可作形容词性定语：un voyage surprise。","ipa":"[syʁ.pʁiz]","ph":"su 读 [sy]；r [ʁ]；p；ri [ʁi]；s 读 [z]；结尾 e 不读：[syʁ.pʁiz]。","pi":"u 读 [y]（不是 [u]）；s 在 ri 后读 [z]；e 不读。","et":"sur- + prise（prendre 的过去分词：抓住），原义「被突然抓住」。","ex":[["J'ai une surprise pour toi.","我有个惊喜给你。"],["Quelle bonne surprise !","真是个惊喜！"],["Ils organisent une fête surprise.","他们办了个惊喜派对。"]],"co":[["faire une surprise à quelqu'un","给某人惊喜"],["une bonne / mauvaise surprise","惊喜 / 坏消息"],["par surprise","出其不意"]],"sy":[["étonnement","soutenu","惊讶"],["cadeau","courant","礼物"]],"fq":"高频，日常常用。","me":"surprise：sur(上) + prise(抓)。","tr":{"zh":"我为你的生日准备了一个惊喜。","fr":"Je te prépare une surprise pour ton anniversaire.","alt":"Pour ton anniv, j'ai une surprise pour toi !","note":"préparer qqch pour qqn。"}},
 "Une tablette": {"pos":"n.f. 阴性名词，复数 tablettes","s":"平板电脑；也指一块巧克力（une tablette de chocolat）。一块巧克力和平板电脑，靠语境区分。","ipa":"[ta.blɛt]","ph":"ta [ta]；ble 读 [blɛ]（e 读 [ɛ]，bl 连读）；tt 读一个 [t]：[ta.blɛt]。","pi":"结尾的 t 要读：tablette [ta.blɛt]；注意与 table [tabl] 不同。","et":"table（来自拉丁语 tabula）加指小后缀 -ette：「小板」。","ex":[["Je regarde un film sur ma tablette.","我在平板上看电影。"],["Il lit sur une tablette.","他用平板阅读。"],["Elle mange une tablette de chocolat.","她吃了一块巧克力。"]],"co":[["une tablette tactile","触屏平板"],["une tablette de chocolat","一块巧克力"],["jouer sur une tablette","在平板上玩"]],"sy":[["iPad","familier","品牌名，口语也指平板"],["ordinateur","courant","电脑（对比）"]],"fq":"中高频，现代常用。","me":"tablette = 小 table（板）。","tr":{"zh":"孩子们在平板上玩。","fr":"Les enfants jouent sur la tablette.","alt":"Les enfants sont sur la tablette.","note":"jouer sur + 设备。"}},
 "Une valise": {"pos":"n.f. 阴性名词，复数 valises","s":"行李箱。faire sa valise / ses valises = 收拾行李。défaire sa valise = 打开行李整理。","ipa":"[va.liz]","ph":"va [va]；li [li]；s 在两个元音之间读 [z]：[va.liz]；结尾 e 不读。","pi":"valise 的 s 读 [z]，别读 [s]；是阴性名词。","et":"借自意大利语 valigia，更早的来源不太确定。","ex":[["Je prépare ma valise pour les vacances.","我为假期收拾行李。"],["Ma valise est trop lourde.","我的行李箱太重了。"],["Il traîne sa valise dans la gare.","他在火车站拖着行李箱。"]],"co":[["faire sa valise","收拾行李"],["une valise à roulettes","拉杆箱"],["défaire sa valise","整理行李（拆箱）"]],"sy":[["bagage","courant","行李（总称）"],["malle","courant","大箱子"]],"fq":"高频，旅行时常用。","me":"valise：s 读 [z]。","tr":{"zh":"我还没收拾好行李。","fr":"Je n'ai pas encore fait ma valise.","alt":"J'ai pas encore fait ma valise.","note":"ne ... pas encore + passé composé。"}},
 "Une veste": {"pos":"n.f. 阴性名词，复数 vestes","s":"夹克；外套；西装上衣。比 un manteau 轻，比 un blouson 正式。veste de costume = 西装上衣。","ipa":"[vɛst]","ph":"ve 读 [vɛ]；s 与 t 都要读：[vɛst]；结尾 e 不读。","pi":"s 和 t 都读出来；veste（外套）不要和 veston（西装上衣）搞混，也不是英语 vest（背心）。","et":"借自意大利语 veste，来自拉丁语 vestis（衣服）。同族：vêtement。","ex":[["Il porte une veste noire.","他穿黑色夹克。"],["Je mets ma veste, il pleut.","我穿上外套，下雨了。"],["Cette veste est trop petite pour moi.","这件外套对我来说太小了。"]],"co":[["une veste en cuir","皮夹克"],["une veste de costume","西装上衣"],["retourner sa veste","改变立场（成语）"]],"sy":[["manteau","courant","大衣"],["blouson","courant","短夹克"],["veston","soutenu","西装上衣（较书面）"]],"fq":"高频，日常常用。","me":"veste 不是 vest：它是外套。","tr":{"zh":"天冷，带上你的外套。","fr":"Il fait froid, prends ta veste.","alt":"Il fait frais, prends ta veste.","note":"prendre = 带上、拿。"}},
 "Des accessoires": {"pos":"n.m. 阳性名词，常用复数 accessoires（单数 un accessoire）","s":"配饰；配件（围巾、帽子、包、首饰等）。也可以是电器的「配件」或戏剧里的「道具」。","ipa":"[ak.sɛ.swaʁ]","ph":"cc 读 [ks]；oi 读 [wa]；复数 s 不读；des accessoires 要连读：[de.z‿ak.sɛ.swaʁ]。","pi":"cc 读 [ks]，不是 [k]；是阳性名词（un accessoire）。","et":"来自拉丁语 accessorius（附带的），与英语 accessory 同源。","ex":[["J'aime les accessoires de mode.","我喜欢时尚配饰。"],["Elle porte des accessoires colorés.","她戴着色彩鲜艳的配饰。"],["Où sont les accessoires pour téléphone ?","手机配件在哪里？"]],"co":[["des accessoires de mode","时尚配饰"],["des accessoires pour téléphone","手机配件"],["un accessoire utile","有用的配件"]],"sy":[["bijou","courant","首饰"],["accessoire","courant","配件（单数）"]],"fq":"中频，日常。","me":"accessoires 在 s 前有 ks 音。","tr":{"zh":"这些配饰很漂亮。","fr":"Ces accessoires sont très jolis.","alt":"Ces accessoires sont trop beaux !","note":"ces 复数指示词。"}},
 "Des baskets": {"pos":"n.f. 阴性名词，常用复数 baskets（单数 une basket）","s":"运动鞋；球鞋。口语里很常用，一双是 une paire de baskets。le basket = 篮球。","ipa":"[bas.kɛt]","ph":"a [a]；s 读 [s]；k [k]；e [ɛ]；t 要读：[bas.kɛt]。","pi":"复数 baskets 的 s 不读；单数 basket 的 t 要读；是阴性（une basket）。","et":"来自 basket-ball（篮球鞋）的缩写。","ex":[["Je mets mes baskets pour le sport.","我穿运动鞋运动。"],["Elle a de nouvelles baskets blanches.","她有一双新的白色运动鞋。"],["Mes baskets sont dans mon sac.","我的运动鞋在包里。"]],"co":[["une paire de baskets","一双运动鞋"],["mettre des baskets","穿运动鞋"],["être bien dans ses baskets","感觉自在（成语）"]],"sy":[["tennis","courant","球鞋（旧称）"],["sneakers","familier","英语借词"]],"fq":"高频，日常常用。","me":"basket 是鞋，panier 才是篮子。","tr":{"zh":"我在找白色运动鞋。","fr":"Je cherche des baskets blanches.","alt":"Je veux des baskets blanches.","note":"des baskets blanches：形容词后置并配合。"}},
 "Des bottes": {"pos":"n.f. 阴性名词，常用复数 bottes（单数 une botte）","s":"靴子。bottes en caoutchouc = 雨靴。botte 还可以是「一束」：une botte de radis（一把萝卜）。","ipa":"[bɔt]","ph":"o 读 [ɔ]；tt 读一个 [t]；复数 s 不读：[bɔt]；整词只有一个音节。","pi":"botte 和 boîte（盒子，[bwat]）不同；o 是开口 [ɔ]，不是 [u]。","et":"来源不太确定；同族词：botter（踢）、bottine（短靴）。","ex":[["Elle a de belles bottes d'hiver.","她有一双漂亮的冬靴。"],["Il pleut, mets tes bottes.","下雨了，穿上你的靴子。"],["Ces bottes sont trop petites.","这双靴子太小了。"]],"co":[["des bottes en cuir","皮靴"],["des bottes en caoutchouc","胶靴、雨靴"],["une paire de bottes","一双靴子"]],"sy":[["bottines","courant","短靴"],["chaussures","courant","鞋（总称）"]],"fq":"中频，冬天常用。","me":"bottes 读 [bɔt]，不是 boat。","tr":{"zh":"穿上靴子，外面下雨。","fr":"Mets tes bottes, il pleut dehors.","alt":"Prends tes bottes, y a de la pluie.","note":"mettre = 穿上。"}},
 "Des chaussettes": {"pos":"n.f. 阴性名词，常用复数 chaussettes（单数 une chaussette）","s":"袜子。一双袜子是 une paire de chaussettes。长筒袜是 des collants 或 des bas。","ipa":"[ʃo.sɛt]","ph":"ch 读 [ʃ]；au 读 [o]；ss 读 [s]；e [ɛ]；t 读 [t]：[ʃo.sɛt]。","pi":"chau- 读 [ʃo]；ss 读 [s]；和 chaussures（鞋）区分，词尾不同。","et":"chausse（长袜，来自拉丁语 calceus）+ 指小后缀 -ette。","ex":[["Où sont mes chaussettes ?","我的袜子在哪里？"],["Je mets des chaussettes noires.","我穿黑袜子。"],["Une chaussette est dans la machine à laver.","一只袜子在洗衣机里。"]],"co":[["une paire de chaussettes","一双袜子"],["mettre des chaussettes","穿袜子"],["des chaussettes en laine","羊毛袜"]],"sy":[["collants","courant","连裤袜"],["socquettes","courant","短袜"]],"fq":"高频，日常常用。","me":"chaussettes：chausse + -ette：小的「鞋套」。","tr":{"zh":"我需要新袜子。","fr":"J'ai besoin de nouvelles chaussettes.","alt":"Il me faut de nouvelles chaussettes.","note":"avoir besoin de + 名词。"}},
 "Des chaussures": {"pos":"n.f. 阴性名词，常用复数 chaussures（单数 une chaussure）","s":"鞋。鞋的总称。一双鞋 = une paire de chaussures。穿多大码：Je chausse du 40。","ipa":"[ʃo.syʁ]","ph":"ch 读 [ʃ]；au 读 [o]；ss 读 [s]；u 读 [y]；r 读 [ʁ]：[ʃo.syʁ]。","pi":"结尾 -ure 读 [yʁ]，e 不读；复数 s 不读；别和 chaussettes 混。","et":"chausser（穿鞋，拉丁语 calceare）+ 后缀 -ure。","ex":[["Je dois acheter de nouvelles chaussures.","我得买新鞋。"],["Ces chaussures sont très confortables.","这双鞋很舒服。"],["Il enlève ses chaussures à la maison.","他在家脱鞋。"]],"co":[["une paire de chaussures","一双鞋"],["des chaussures de sport","运动鞋"],["essayer des chaussures","试鞋"]],"sy":[["souliers","soutenu","鞋（较书面）"],["godasses","familier","鞋（口语）"]],"fq":"极高频，日常常用。","me":"chaussures：chausser(穿鞋) + -ure。","tr":{"zh":"我在找黑色的鞋。","fr":"Je cherche des chaussures noires.","alt":"Je veux des chaussures noires.","note":"des chaussures noires：形容词配合复数。"}},
 "Des écouteurs (sans fil)": {"pos":"n.m. 阳性名词，常用复数 écouteurs（单数 un écouteur）","s":"耳机（入耳式）。sans fil = 无线。头戴式大耳机叫 un casque。","ipa":"[e.ku.tœʁ]","ph":"é [e]；ou 读 [u]；eur 读 [œʁ]；复数 s 不读；des écouteurs 连读：[de.z‿e.ku.tœʁ]。","pi":"écouteurs 是阳性复数；sans fil 里 sans 的 s 不读：[sɑ̃ fil]。","et":"écouter（听，拉丁语 auscultare）+ 后缀 -eur：「听的东西」。","ex":[["J'écoute de la musique avec mes écouteurs.","我用耳机听音乐。"],["Mes écouteurs sans fil sont dans leur boîte.","我的无线耳机在盒子里。"],["Il a perdu un écouteur.","他丢了一只耳机。"]],"co":[["des écouteurs sans fil","无线耳机"],["mettre ses écouteurs","戴耳机"],["écouter de la musique","听音乐"]],"sy":[["casque","courant","头戴式耳机"],["oreillettes","courant","耳麦"]],"fq":"高频，日常常用。","me":"écouteurs = 「écouter」的东西。","tr":{"zh":"戴上耳机，别打扰别人。","fr":"Mets tes écouteurs pour ne pas déranger.","alt":"Mets tes écouteurs, tu dérangeras pas.","note":"pour ne pas + 原形。"}},
 "Des fringues": {"pos":"n.f.pl. 阴性名词，常用复数；单数 une fringue，复数 fringues","s":"衣服（俚语），比 vêtements 随意，朋友之间常说。多用复数，单数 une fringue 指一件衣服，较少用。正式场合请用 vêtements。","ipa":"[fʁɛ̃g]","ph":"gu 在 i 前读 [g]，u 不发音；fr 连读成 [fʁ]；in 读鼻音 [ɛ̃]；结尾 -es 不发音。","pi":"结尾 -gues 只读 [g]，不要读成「fringue-es」。不要在正式文章或工作场合用这个词。","et":"来源不确定。同家族：动词 se fringuer（穿衣打扮，口语）。","ex":[["J'achète des fringues.","我去买衣服。"],["Elle a plein de fringues neuves.","她有很多新衣服。"],["On va acheter des fringues samedi.","我们星期六去买衣服。"]],"co":[["acheter des fringues","买衣服"],["se fringuer","穿衣打扮（口语）"],["des fringues de marque","名牌衣服"]],"sy":[["vêtements","courant","中性、日常的「衣服」"],["sapes","argot","俚语，年轻人用"],["frusques","familier","旧的、破的衣服，略带贬义"]],"fq":"中频，口语，年轻人常用。","me":"fringue 听起来有点「随便」，和 fringant（精神抖擞的）没关系，只记它是口语里的「衣服」。","tr":{"zh":"我夏天需要一些新衣服。","fr":"J'ai besoin de nouvelles fringues pour l'été.","alt":"Il me faut de nouvelles fringues pour cet été.","note":"Il me faut ... 是更口语的说法，意思是「我需要……」。"}},
 "Des lunettes": {"pos":"n.f.pl. 阴性名词，几乎总是复数","s":"眼镜。法语里「眼镜」永远用复数 des lunettes，一副眼镜是 une paire de lunettes。lunette 单数一般指望远镜等镜筒。","ipa":"[ly.nɛt]","ph":"u 读 [y]（嘴唇圆，发 i 的音）；tt 只读一个 [t]；结尾 e 不发音，但 t 要读出来。des 后面是辅音 l，不连读。","pi":"u 是 [y]，不是 [u]。中文说「一副眼镜」，法语说 une paire de lunettes，不能说 une lunette。","et":"来自 lune（月亮）加指小后缀 -ette，字面是「小月亮」，指圆形镜片。","ex":[["Je porte des lunettes pour lire.","我戴眼镜看书。"],["J'ai perdu mes lunettes.","我把眼镜弄丢了。"],["Tu as vu mes lunettes ?","你看到我的眼镜了吗？"]],"co":[["une paire de lunettes","一副眼镜"],["mettre / enlever ses lunettes","戴上 / 摘下眼镜"],["des lunettes de vue","近视镜"]],"sy":[["besicles","littéraire","古雅或开玩笑的说法"],["binocles","familier","口语，略带玩笑"],["verres","courant","镜片"]],"fq":"高频，日常常用。","me":"lune（月亮）+ -ette：圆圆的「小月亮」放在眼前。","tr":{"zh":"我的眼镜在哪里？我什么都看不见。","fr":"Où sont mes lunettes ? Je ne vois rien.","alt":"Elles sont où, mes lunettes ? Je vois rien.","note":"「看不见」用 ne ... rien；口语常省略 ne。"}},
 "Des lunettes de soleil": {"pos":"n.f.pl. 阴性名词，复数","s":"太阳镜，墨镜。字面是「太阳的眼镜」。和 des lunettes（普通眼镜）一样永远用复数。","ipa":"[ly.nɛt də sɔ.lɛj]","ph":"soleil 读 [sɔ.lɛj]，结尾 eil 读 [ɛj]；de 读 [də]，很轻。","pi":"soleil 的 -eil 不是 [ɛl]，而是 [ɛj]。soleil 是阳性：le soleil。","et":"soleil 来自拉丁语 soliculus（小太阳），源于 sol。lunettes 见 lunettes 条。","ex":[["Il y a du soleil, je mets mes lunettes de soleil.","有太阳，我戴墨镜。"],["Elle porte toujours des lunettes de soleil.","她总是戴着墨镜。"],["N'oublie pas tes lunettes de soleil.","别忘了你的墨镜。"]],"co":[["une paire de lunettes de soleil","一副太阳镜"],["mettre / porter des lunettes de soleil","戴太阳镜"],["des lunettes noires","墨镜"]],"sy":[["lunettes noires","courant","最常用的同义说法"],["solaires","familier","口语缩写 les solaires"],["lunettes de vue","courant","对比：近视 / 普通眼镜"]],"fq":"中高频，夏天常用。","me":"lunettes + 太阳（soleil）= 太阳镜。","tr":{"zh":"天气很好，我带上墨镜。","fr":"Il fait beau, je prends mes lunettes de soleil.","alt":"Il fait beau, je prends mes solaires.","note":"il fait beau 是天气好的固定说法。"}},
 "Des sous-vêtements": {"pos":"n.m.pl. 阳性名词，单数 un sous-vêtement，复数 sous-vêtements","s":"内衣，贴身穿的衣物（内裤、背心等）。女士内衣常说 la lingerie。字面是「在下面的衣服」。","ipa":"[su.vɛt.mɑ̃]","ph":"sous 读 [su]，s 不发音（后面是辅音）；vê 读 [vɛ]；-ment 读 [mɑ̃]；结尾 -ts 不发音。","pi":"-ent 在这里读 [ɑ̃]（-ment 是名词后缀），不是动词词尾。复数 s 不读。","et":"sous（在……下，拉丁语 subtus）+ vêtement（衣服，来自 vêtir，拉丁语 vestire）。","ex":[["Il achète des sous-vêtements.","他买内衣。"],["Je range mes sous-vêtements dans le tiroir.","我把内衣放在抽屉里。"],["Il lui faut des sous-vêtements chauds pour le ski.","他滑雪需要保暖内衣。"]],"co":[["acheter des sous-vêtements","买内衣"],["des sous-vêtements en coton","纯棉内衣"],["un sous-vêtement thermique","保暖内衣"]],"sy":[["lingerie","courant","女士内衣的常用词"],["slip","courant","内裤"],["caleçon","courant","宽松的平角内裤"]],"fq":"中频。","me":"sous（下面）+ vêtements（衣服）= 下面的衣服。","tr":{"zh":"我买了纯棉内衣。","fr":"J'ai acheté des sous-vêtements en coton.","alt":"J'ai pris des sous-vêtements en coton.","note":"穿在里面的叫 sous-vêtements，穿在外面的叫 vêtements。"}},
 "Des tongs / Des claquettes": {"pos":"n.f.pl. 阴性名词，单数 une tong / une claquette","s":"tongs 是夹脚的人字拖，claquettes 是没有夹脚的拖鞋（一条宽带，水边、家里穿）。两者都多用复数。claquettes 还有另一个意思：踢踏舞。","ipa":"[tɔ̃g] / [kla.kɛt]","ph":"tongs 的 g 要读：[tɔ̃g]；on 是鼻音 [ɔ̃]。claquettes 读 [kla.kɛt]，qu = [k]，tt 一个 [t]。","pi":"tongs 末尾的 g 发音，别丢掉。法语 string 才是丁字裤，不要把 tongs 和英语 thongs 的意思混淆（英语在美国常指丁字裤）。","et":"tong 借自英语 thong（皮带，细带）。claquette 来自 claquer（啪嗒响）加 -ette，因为走路会啪嗒作响。","ex":[["Je porte des tongs à la piscine.","我在泳池穿拖鞋。"],["Il met ses claquettes pour aller à la plage.","他穿着拖鞋去海滩。"],["Ne viens pas au bureau en tongs.","别穿人字拖来办公室。"]],"co":[["une paire de tongs","一双人字拖"],["mettre des claquettes","穿拖鞋"],["en tongs","穿着人字拖"]],"sy":[["sandales","courant","凉鞋，有绑带"],["pantoufles","courant","室内拖鞋"],["savates","familier","旧鞋、破鞋，口语"]],"fq":"中频，夏天常用。","me":"tong 是夹在脚趾间的「细带」（thong）；claquette 走路会 clac clac 响。","tr":{"zh":"夏天我穿人字拖去海滩。","fr":"En été, je porte des tongs à la plage.","alt":"L'été, je mets des tongs pour aller à la plage.","note":"en tongs = 穿着人字拖，en + 衣物表示穿着的状态。"}},
 "Des vêtements": {"pos":"n.m.pl. 阳性名词，单数 un vêtement，复数 vêtements","s":"衣服（总称）。单数 un vêtement 指一件衣服（衬衫、裤子都可以），复数 des vêtements 是泛指衣服。","ipa":"[vɛt.mɑ̃]","ph":"ê 读 [ɛ]；-ment 读 [mɑ̃]（不是 [mɛnt]）；结尾 -s 不发音。","pi":"-ment 在名词里读 [mɑ̃]，e 不发音。注意拼写有 ê。","et":"来自动词 vêtir（穿衣，拉丁语 vestire）加后缀 -ment。","ex":[["J'achète des vêtements.","我买衣服。"],["Il a plein de vêtements dans son armoire.","他衣柜里有很多衣服。"],["Ce magasin vend des vêtements pour enfants.","这家店卖童装。"]],"co":[["acheter des vêtements","买衣服"],["des vêtements de sport","运动服"],["un magasin de vêtements","服装店"]],"sy":[["habits","courant","日常的「衣服」，复数最常用"],["fringues","familier","口语、随意"],["tenue","courant","一身搭配好的衣服"]],"fq":"极高频，日常常用。","me":"vêtir（穿）+ -ment：穿在身上的东西。","tr":{"zh":"我买了新衣服。","fr":"J'ai acheté de nouveaux vêtements.","alt":"J'ai pris de nouveaux vêtements.","note":"新衣服用 de nouveaux vêtements（复数形容词前常用 de）。"}},
 "Un imperméable / Un k-way": {"pos":"n.m. 阳性名词，复数 imperméables（k-way 不变）","s":"雨衣；风衣式防水外套。imperméable 是长一点的雨衣，k-way（品牌名，已成普通名词）是可折叠的轻薄防水外套。口语缩写 un imper。","ipa":"[ɛ̃.pɛʁ.me.abl] / [ka.wɛ]","ph":"im 在 p 前读鼻音 [ɛ̃]；per 读 [pɛʁ]；mé-a-ble 三个音节 [me.abl]。k-way 读 [ka.wɛ]。","pi":"imperméable 很长，分三段记：im-per-méable。词尾 -able 读 [abl]，不要加元音。","et":"imperméable = in-（不）+ perméable（可渗透，拉丁语 permeabilis）。k-way 是商标名，后来变成了普通名词。","ex":[["Il pleut, je prends mon imperméable.","下雨了，我拿雨衣。"],["Mets ton k-way, il va pleuvoir.","穿上你的轻便雨衣，要下雨了。"],["Elle porte un imperméable beige.","她穿着一件米色风衣。"]],"co":[["mettre un imperméable","穿雨衣"],["un imperméable beige","米色风衣"],["un k-way jaune","黄色轻便雨衣"]],"sy":[["imper","familier","口语缩写"],["ciré","courant","橡胶或油布雨衣"],["coupe-vent","courant","防风外套"]],"fq":"中频。","me":"im-（不）+ perméable（水能渗过）= 水渗不过。","tr":{"zh":"带上你的雨衣，要下雨了。","fr":"Prends ton imperméable, il va pleuvoir.","alt":"Prends ton k-way, il va pleuvoir.","note":"il va pleuvoir 是近未来，表示马上要发生。"}},
 "Écrire": {"pos":"v. 第三组不规则动词，助动词 avoir；j'écris, nous écrivons；过去分词 écrit","s":"写：写字、写信、写邮件、写书。écrire à qqn = 给某人写信；écrire un mail / un message = 写邮件 / 发消息。也有「拼写」的意思：Comment ça s'écrit ? = 这个怎么拼？","ipa":"[e.kʁiʁ]","ph":"é 读 [e]；cr 连读 [kʁ]；-ire 读 [iʁ]，r 要读出来。je 变位 écris [e.kʁi]，s 不发音。","pi":"单数 j'écris 的 s 不发音，复数 nous écrivons 突然出现 v。「写给某人」要用 écrire à qqn，不能直接说 écrire qqn。","et":"来自拉丁语 scribere（书写）。同源：écriture（书写）、écrivain（作家）、décrire（描述）、inscrire（登记）。","ex":[["J'écris un message.","我写一条消息。"],["Il m'écrit tous les jours.","他每天给我写信。"],["Elle a écrit un livre.","她写了一本书。"]],"co":[["écrire à quelqu'un","给某人写信"],["écrire un mail","写邮件"],["écrire au stylo / au crayon","用钢笔 / 铅笔写"]],"sy":[["rédiger","soutenu","正式，写作 / 起草"],["noter","courant","记下"],["taper","courant","打字"]],"fq":"极高频，日常常用。","me":"écrire 像「用 crayon 写」：cr 在两个词里都有。","tr":{"zh":"我明天给你写信确认。","fr":"Je t'écris demain pour confirmer.","alt":"Je t'écris demain, pour te confirmer ça.","note":"écrire à qqn；现在时表示近期要做的事也很自然。"}},
 "Essayer": {"pos":"v. 第一组动词，助动词 avoir；j'essaie / j'essaye，nous essayons","s":"试穿；尝试；试一试。essayer un vêtement = 试穿衣服；essayer de + 动词原形 = 努力做某事；也可以指试吃、试用。","ipa":"[e.sɛ.je]","ph":"ess 读 [ɛs]；ay 读 [ɛj]，所以 essayer = [e.sɛ.je]；词尾 -er 读 [e]，r 不发音。","pi":"y 在 e 前可以变成 i：j'essaie 或 j'essaye 都对。「努力做某事」用 essayer de，不是 essayer à。","et":"来自 essai（尝试，拉丁语 exagium「称重」），再加动词词尾 -er。essayer 的同源词：essai（尝试；文章）。","ex":[["Je voudrais essayer cette chemise.","我想试穿这件衬衫。"],["J'essaie de comprendre.","我努力去理解。"],["Tu peux essayer ce gâteau, il est très bon.","你可以尝尝这个蛋糕，很好吃。"]],"co":[["essayer de + infinitif","尝试做……"],["essayer un vêtement","试穿衣服"],["essayer un plat","试吃一道菜"]],"sy":[["tenter","courant","试图，努力"],["tester","courant","测试、试用"],["goûter","courant","品尝、尝一口"]],"fq":"极高频，日常常用。","me":"essai（试）+ -yer：和 essay 看着像，但这个词重点是「试」。","tr":{"zh":"我可以试穿这件外套吗？","fr":"Je peux essayer cette veste, s'il vous plaît ?","alt":"Je peux l'essayer, cette veste ?","note":"试穿用 essayer + 衣服；要加 de 的是 essayer de + 动词。"}},
 "Faire les magasins / Faire du shopping": {"pos":"v. 动词短语，faire 是不规则动词，助动词 avoir；je fais, nous faisons [fə.zɔ̃]","s":"逛街，逛商店买东西。faire les magasins 用复数，意思是去几家店逛；faire du shopping 是借自英语的说法，更口语。注意：faire des courses 是买日常用品，不是逛街。","ipa":"[fɛʁ le ma.ga.zɛ̃] / [fɛʁ dy ʃɔ.piŋ]","ph":"faire 读 [fɛʁ]；magasin 读 [ma.ga.zɛ̃]，s 在两个元音间读 [z]，in 是鼻音 [ɛ̃]；shopping 读 [ʃɔ.piŋ]，ing 读 [iŋ]。","pi":"nous faisons 中 ai 读 [ə]：[fə.zɔ̃]，是不规则读音。faire les courses 是买菜，faire les magasins 才是逛街。","et":"magasin 来自意大利语 magazzino，最早源于阿拉伯语 makhāzin（仓库）。shopping 借自英语。","ex":[["J'adore faire les magasins.","我喜欢逛街。"],["On fait du shopping samedi après-midi ?","星期六下午我们去逛街好吗？"],["Elle fait les magasins avec sa sœur.","她和姐姐一起逛街。"]],"co":[["faire les magasins","逛商店"],["faire du shopping","逛街购物"],["faire les boutiques","逛小店"]],"sy":[["faire les boutiques","courant","逛小店"],["faire du lèche-vitrines","courant","只看橱窗不买"],["faire des courses","courant","买日常用品（不同）"]],"fq":"中高频，日常常用。","me":"magasin = 仓库（阿拉伯语），逛很多个「仓库」就是逛街。","tr":{"zh":"星期六我要和朋友去逛街。","fr":"Samedi, je vais faire les magasins avec une amie.","alt":"Samedi, on va faire du shopping, une copine et moi.","note":"faire les magasins 常用复数 magasins。"}},
 "Pleuvoir": {"pos":"v. 无人称动词（只用 il），第三组不规则，助动词 avoir；il pleut, il pleuvait, il a plu, il pleuvra","s":"下雨。只用 il 作主语：il pleut（正在下雨），il va pleuvoir（要下雨了）。比喻义：les coups pleuvent（拳头如雨点般落下）。","ipa":"[plø.vwaʁ]","ph":"pleu 读 [plø]；-voir 读 [vwaʁ]，oi = [wa]，r 要读。","pi":"只有 il，没有 je / tu。过去分词是 plu（和 plaire 的过去分词一样）。Il pleut 不要说成 C'est pleuvoir。","et":"来自拉丁语 pluere（下雨）。同源：pluie（雨）、pluvieux（多雨的）、parapluie（雨伞）。","ex":[["Il va pleuvoir demain.","明天会下雨。"],["Il pleut depuis ce matin.","从早上起一直在下雨。"],["Il a plu toute la nuit.","雨下了一整夜。"]],"co":[["il pleut","下雨"],["il pleut à verse","下大雨"],["il pleut des cordes","倾盆大雨（口语）"]],"sy":[["bruiner","courant","下毛毛雨"],["pleuvoir des cordes","familier","倾盆大雨"],["faire beau","courant","反义：天气好"]],"fq":"极高频，日常常用。","me":"pluie（雨）和 pleuvoir 都有 pl-：一听就是下雨。","tr":{"zh":"从早上开始一直下雨，我待在家里。","fr":"Il pleut depuis ce matin, je reste à la maison.","alt":"Il pleut depuis ce matin, donc je reste chez moi.","note":"il pleut depuis ... 表示「从……起一直在下」。"}},
 "Porter": {"pos":"v. 第一组规则动词，助动词 avoir；je porte, nous portons","s":"穿；戴；带着；搬、扛。衣服、眼镜、首饰都用 porter（穿着的状态）。porter qqch = 拿着、扛着；porter bonheur = 带来好运；se porter bien = 身体好。穿上的动作用 mettre。","ipa":"[pɔʁ.te]","ph":"p [p]；o 是开口 [ɔ]；r 读 [ʁ]；-er 读 [e]，r 不发音。","pi":"porter 是「穿着」的状态，mettre 是「穿上」的动作：Je mets un manteau（我正在穿上）；Je porte un manteau（我穿着）。","et":"来自拉丁语 portare（搬运）。同源：apporter、emporter、transporter、support、importer、exporter、porte-monnaie。","ex":[["Je porte un manteau.","我穿着大衣。"],["Il porte des lunettes.","他戴着眼镜。"],["Elle porte son sac sur l'épaule.","她把包背在肩上。"]],"co":[["porter un manteau","穿大衣"],["porter des lunettes","戴眼镜"],["porter bonheur / porter chance","带来好运"],["se porter bien","身体好"]],"sy":[["mettre","courant","穿上（动作）"],["apporter","courant","带来（东西）"],["revêtir","soutenu","穿上、披上（书面）"]],"fq":"极高频，日常常用。","me":"port- 是「搬」：porter 把东西搬在身上，所以是穿着。","tr":{"zh":"今天她穿一条红裙子。","fr":"Aujourd'hui, elle porte une robe rouge.","alt":"Aujourd'hui, elle est en robe rouge.","note":"porter 描述状态；alt 用 être en + 衣服 也很自然。"}},
 "Blanc / Blanche": {"pos":"adj. 形容词，阳性 blanc，阴性 blanche，复数 blancs / blanches；也是名词 le blanc","s":"白色的。阴性 blanche。名词 le blanc = 白色、白葡萄酒、蛋白（le blanc d'œuf）。une nuit blanche = 通宵没睡。","ipa":"[blɑ̃] / [blɑ̃ʃ]","ph":"bl [bl]；an 是鼻音 [ɑ̃]；阳性结尾 c 不发音；阴性 blanche 的 ch 读 [ʃ]。","pi":"阳性 blanc 的 c 不发音。阴性 blanche 读 [blɑ̃ʃ]，ch 不读 [tʃ]。","et":"来自法兰克语 *blank（发亮的，白的）。同源：blanchir（漂白）、blancheur（白色）、blanchisserie（洗衣店）。","ex":[["La neige est blanche.","雪是白色的。"],["J'aime le vin blanc.","我喜欢白葡萄酒。"],["Il porte une chemise blanche.","他穿一件白衬衫。"]],"co":[["du vin blanc","白葡萄酒"],["le blanc d'œuf","蛋白"],["une nuit blanche","一夜没睡"]],"sy":[["blême","soutenu","苍白的（脸色）"],["immaculé","soutenu","洁白无瑕"],["noir","courant","反义：黑色"]],"fq":"极高频，日常常用。","me":"blanc 的 -anc 是鼻音，像「白」字的 an：blanc。","tr":{"zh":"她穿一条白裙子。","fr":"Elle porte une robe blanche.","alt":"Elle est en robe blanche.","note":"裙子是阴性，所以用 blanche。"}},
 "Bleu(e)": {"pos":"adj. 形容词，阳性 bleu，阴性 bleue（读音相同），复数 bleus / bleues；也是名词 le bleu","s":"蓝色的。bleu et bleue 读音一样，只是拼写不同。名词 un bleu = 瘀青；un bleu 也可指新手。复合颜色不变：bleu clair、bleu foncé、bleu marine。","ipa":"[blø]","ph":"bl [bl]；eu 读 [ø]（嘴唇圆，发 é 的音）；结尾 e 不发音。","pi":"eu 是 [ø]，不是 [u]。bleu clair 不用加 e、不用加 s：des robes bleu clair。","et":"来自法兰克语 *blāo（蓝色，发亮的）。同源：bleuet（矢车菊）、bleuir（变蓝）、bleuâtre（淡蓝的）。","ex":[["Le ciel est bleu.","天空是蓝色的。"],["Elle a les yeux bleus.","她有一双蓝眼睛。"],["J'ai un pull bleu marine.","我有一件藏青色毛衣。"]],"co":[["bleu clair / bleu foncé","浅蓝 / 深蓝"],["bleu marine","藏青色"],["avoir une peur bleue","吓得要命"],["un bleu (sur la jambe)","瘀青"]],"sy":[["azur","littéraire","诗歌里的天蓝色"],["turquoise","courant","绿松石色"],["bleuâtre","courant","淡蓝的"]],"fq":"极高频，日常常用。","me":"bleu 像英语 blue：一个 b 一个 l，再加 eu。","tr":{"zh":"今天天空是蓝色的。","fr":"Le ciel est bleu aujourd'hui.","alt":"Il fait beau, le ciel est tout bleu.","note":"ciel 是阳性，所以用 bleu。"}},
 "Carré(e)": {"pos":"adj. 形容词，阳性 carré，阴性 carrée，复数 carrés / carrées；也是名词 un carré","s":"方形的，正方形的。mètre carré = 平方米；racine carrée = 平方根；un carré de chocolat = 一小块巧克力；un carré de soie = 方巾。","ipa":"[ka.ʁe]","ph":"ca [ka]；rr 读一个 [ʁ]；é 读 [e]；阴性 carrée 读音相同。","pi":"rr 只读一个 r，不要读两遍。é 在结尾读 [e]，别读成 ay。","et":"来自拉丁语 quadratus（四方形的，来自 quadrus）。同源：carreau（方块；瓷砖）。","ex":[["Une valise carrée.","一个方形的行李箱。"],["Cette table est carrée.","这张桌子是方的。"],["Ma chambre fait vingt mètres carrés.","我的房间有二十平方米。"]],"co":[["un mètre carré","一平方米"],["une racine carrée","平方根"],["un carré de chocolat","一小块巧克力"]],"sy":[["rectangulaire","courant","长方形的"],["rond","courant","反义：圆的"],["quadrangulaire","soutenu","四边形的，书面"]],"fq":"中高频。","me":"carré 和 quatre（四）：四条边。","tr":{"zh":"我想要一张四人的方桌。","fr":"Je voudrais une table carrée pour quatre personnes.","alt":"Je cherche une table carrée, pour quatre.","note":"pour quatre personnes 说明人数。"}},
 "Chaud(e)": {"pos":"adj. 形容词，阳性 chaud，阴性 chaude，复数 chauds / chaudes；也是名词 le chaud（热）","s":"热的；暖和的。注意用法：il fait chaud = 天气热；avoir chaud = 人觉得热；物体热用 être chaud（l'eau est chaude）。je suis chaud 在口语里是「我很来劲」。","ipa":"[ʃo] / [ʃod]","ph":"ch [ʃ]；au [o]；阳性结尾 d 不发音，阴性 chaude 读 [ʃod]，d 要发。","pi":"说「我热」要用 j'ai chaud，不能说 je suis chaud。天气用 il fait chaud。","et":"来自拉丁语 calidus（暖的）。同源：chaleur（热）、chauffer（加热）、chauffage（暖气）、chaudière（锅炉）。","ex":[["L'eau est très chaude.","水很烫。"],["Il fait chaud aujourd'hui.","今天很热。"],["J'ai chaud, j'ouvre la fenêtre.","我觉得热，我去开窗。"]],"co":[["avoir chaud","觉得热"],["il fait chaud","天气热"],["une boisson chaude","热饮"],["chaud devant !","小心，热的过来（厨房用语）"]],"sy":[["brûlant","courant","滚烫的"],["bouillant","courant","沸腾的"],["tiède","courant","温的，不凉不热"]],"fq":"极高频，日常常用。","me":"chaud 和 chauffer（加热）同一家：chauffe！","tr":{"zh":"我觉得热，我去开窗。","fr":"J'ai chaud, je vais ouvrir la fenêtre.","alt":"J'ai trop chaud, j'ouvre la fenêtre.","note":"感觉用 avoir chaud，不要用 être。"}},
 "Clair(e)": {"pos":"adj. 形容词，阳性 clair，阴性 claire（读音相同），复数 clairs / claires","s":"浅色的；明亮的；清楚的。颜色：bleu clair（浅蓝）；光线：une pièce claire（明亮的房间）；意思：c'est clair（很清楚）。il fait clair = 天色亮。反义词：foncé（深色）、sombre（暗）。","ipa":"[klɛʁ]","ph":"cl [kl]；ai 读 [ɛ]；r 要读出来；clair 和 claire 读音一样。","pi":"颜色里 clair 不变：une chemise bleu clair（不是 bleue claire）。r 一定要读。","et":"来自拉丁语 clarus（明亮的，清楚的）。同源：clarté（光亮）、éclairer（照亮）、clarifier（弄清楚）。","ex":[["J'aime le bleu clair.","我喜欢浅蓝色。"],["C'est clair, merci.","清楚了，谢谢。"],["La pièce est très claire.","这个房间很明亮。"]],"co":[["bleu clair","浅蓝色"],["il fait clair","天色亮"],["de l'eau claire","清澈的水"],["c'est clair","很清楚"]],"sy":[["pâle","courant","苍白的，浅的"],["lumineux","courant","明亮的"],["limpide","soutenu","清澈透明（书面）"]],"fq":"极高频，日常常用。","me":"clair 像 clear：英语 clear 也来自同一个词。","tr":{"zh":"我在找一件浅蓝色衬衫。","fr":"Je cherche une chemise bleu clair.","alt":"Je voudrais une chemise bleu clair.","note":"颜色加 clair 后整体不变。"}},
 "Classe": {"pos":"adj. 形容词，口语，不变形（阴性、复数都是 classe）；另有名词 la classe（班级；等级）","s":"有档次的；有型的；优雅的。口语里的形容词，不随性数变化：il est classe, elle est classe, ils sont classe。名词 la classe 是「班级、教室」，avoir de la classe 是「有气质」。","ipa":"[klas]","ph":"cl [kl]；a 是短 [a]；ss 读 [s]；结尾 e 不发音。","pi":"作形容词时不变形：elle est classe（不写 classée）。正式场合换成 élégant。","et":"来自拉丁语 classis（等级，群体）。同源：classer（分类）、classique、classement。","ex":[["Il est très classe dans ce costume.","他穿这套西装很有型。"],["Elle est vraiment classe.","她真有气质。"],["Cette robe fait très classe.","这条裙子看起来很高级。"]],"co":[["avoir de la classe","有气质"],["très classe","很有型"],["ça fait classe","看起来很高级"],["une tenue classe","有型的穿搭"]],"sy":[["élégant","courant","优雅"],["chic","courant","时尚，雅致"],["stylé","familier","时髦、酷，口语"]],"fq":"中频，口语。","me":"classe = 高「班」：有档次的人。","tr":{"zh":"你穿这件外套很有型。","fr":"Tu es très classe dans cette veste.","alt":"Tu fais classe, avec cette veste.","note":"faire classe 也可以说「看起来很有档次」。"}},
 "Classique": {"pos":"adj. 形容词，阴阳性相同，复数 classiques；也是名词 un classique（经典作品）","s":"经典的；传统的；常规的。la musique classique = 古典音乐；un classique = 经典之作；c'est un classique = 这是老套路。形容衣服时指款式简单、不过时。","ipa":"[kla.sik]","ph":"cl [kl]；a 读 [a]；ss 读 [s]；qu 读 [k]；词尾 -ique 读 [ik]，e 不发音。","pi":"qu 读 [k]，不是 [kw]。重音在最后一个音节：kla-SIK。","et":"来自拉丁语 classicus（第一等级的），来自 classis。","ex":[["C'est un style très classique.","这是很经典的风格。"],["J'aime la musique classique.","我喜欢古典音乐。"],["Il porte toujours une chemise classique.","他总穿一件经典款衬衫。"]],"co":[["la musique classique","古典音乐"],["un style classique","经典风格"],["un grand classique","一部经典"],["une coupe classique","经典发型 / 剪裁"]],"sy":[["traditionnel","courant","传统的"],["intemporel","courant","不过时的"],["sobre","courant","朴素的"]],"fq":"高频，日常常用。","me":"classique：qu = k，重音在最后：klaSIK。","tr":{"zh":"我更喜欢经典风格。","fr":"Je préfère un style classique.","alt":"Moi, j'aime mieux le style classique.","note":"préférer + 名词表示偏好。"}},
 "Confortable": {"pos":"adj. 形容词，阴阳性相同，复数 confortables","s":"舒服的，舒适的。只用于物（鞋子、床、沙发）。说人「感觉舒服」不能说 je suis confortable，要说 je suis bien 或 je suis à l'aise。反义词：inconfortable。","ipa":"[kɔ̃.fɔʁ.tabl]","ph":"con 是鼻音 [kɔ̃]；for [fɔʁ]；ta [ta]；结尾 -ble 读 [bl]，不加元音。","pi":"拼写是 con-，不是 com-（英语是 comfortable）。形容人时不能用 confortable。","et":"借自英语 comfortable（18 世纪），英语又来自古法语 conforter（鼓励，安慰）。名词 confort（舒适）。","ex":[["Ces chaussures sont très confortables.","这双鞋很舒服。"],["Ce fauteuil est confortable.","这把扶手椅很舒服。"],["J'ai un lit très confortable.","我有一张很舒服的床。"]],"co":[["un lit confortable","舒服的床"],["un fauteuil confortable","舒服的扶手椅"],["être à l'aise","感觉自在"],["le confort","舒适"]],"sy":[["agréable","courant","令人愉快的"],["douillet","courant","柔软温暖的"],["cosy","courant","温馨的（外来词）"]],"fq":"高频，日常常用。","me":"con-fort-able：中间的 fort 是「力量」，舒服让你有力气。","tr":{"zh":"这个沙发很舒服。","fr":"Ce canapé est très confortable.","alt":"Ce canapé, il est super confortable.","note":"形容物体舒服，主语必须是物。"}},
 "Court(e)": {"pos":"adj. 形容词，阳性 court，阴性 courte，复数 courts / courtes","s":"短的（长度或时间）：cheveux courts（短发）；une courte pause（短暂休息）。être à court de = 缺……；un court-métrage = 短片。副词形式 court：couper court（打断）。","ipa":"[kuʁ] / [kuʁt]","ph":"ou 读 [u]；r 要读；阳性 court [kuʁ]，t 不发音；阴性 courte [kuʁt]，t 要发音。","pi":"court、cour、cours、courent 读音相同（同音词）：[kuʁ]。看拼写才知道意思。","et":"来自拉丁语 curtus（截短的）。同源：raccourcir（缩短）、écourter（缩短）、courtaud（矮胖的）。","ex":[["Mes cheveux sont courts.","我的头发很短。"],["Cette jupe est trop courte.","这条裙子太短了。"],["Je vais faire une courte pause.","我会稍微休息一下。"]],"co":[["des cheveux courts","短发"],["une jupe courte","短裙"],["être à court d'argent","缺钱"],["un court-métrage","短片"]],"sy":[["bref","courant","简短的"],["petit","courant","小的、矮的"],["long","courant","反义：长的"]],"fq":"极高频，日常常用。","me":"court 的反面 long 也是单音节：court vs long。","tr":{"zh":"我的裙子太短，我得再买一条。","fr":"Ma jupe est trop courte, je dois en acheter une autre.","alt":"Ma jupe est trop courte, il m'en faut une autre.","note":"裙子是阴性，所以用 courte。"}},
 "Foncé(e)": {"pos":"adj. 形容词，阳性 foncé，阴性 foncée，复数 foncés / foncées","s":"深色的。常和颜色连用：bleu foncé（深蓝）、vert foncé（深绿）。反义词：clair（浅色）。","ipa":"[fɔ̃.se]","ph":"fon 是鼻音 [fɔ̃]；c 在 é 前读 [s]；é 读 [e]。","pi":"颜色 + foncé 不变形：une chemise bleu foncé。foncé 只说颜色深，不说人「心情沉重」。","et":"foncé 是动词 foncer（使颜色变深）的过去分词。foncer 的另一个意思是「冲过去」。颜色义的来历不太确定。","ex":[["Il porte un costume bleu foncé.","他穿一套深蓝色西装。"],["Je préfère les couleurs foncées.","我更喜欢深色。"],["Elle a les cheveux foncés.","她的头发颜色很深。"]],"co":[["bleu foncé","深蓝色"],["vert foncé","深绿色"],["une couleur foncée","深色"],["des cheveux foncés","深色头发"]],"sy":[["sombre","courant","暗的，阴沉的"],["clair","courant","反义：浅的"],["obscur","soutenu","昏暗的（书面，不指颜色）"]],"fq":"中频，日常常用。","me":"foncé 是深颜色，和 clair 成对记。","tr":{"zh":"我在找一条深蓝色长裤。","fr":"Je cherche un pantalon bleu foncé.","alt":"Je voudrais un pantalon bleu foncé.","note":"颜色加 foncé 后整体不变形。"}},
 "Froid(e)": {"pos":"adj. 形容词，阳性 froid，阴性 froide，复数 froids / froides；也是名词 le froid","s":"冷的。三种用法：il fait froid（天气冷）；avoir froid（人觉得冷）；être froid（物体冷：la soupe est froide）。名词 le froid = 寒冷。froid 还可形容人「冷漠」。","ipa":"[fʁwa] / [fʁwad]","ph":"fr [fʁ]；oi 读 [wa]；阳性 d 不发音：[fʁwa]；阴性 froide 读 [fʁwad]，d 要发。","pi":"说「我冷」用 j'ai froid，不能说 je suis froid（那是「我很冷漠」）。","et":"来自拉丁语 frigidus（冷的）。同源：frigo（冰箱）、réfrigérateur、refroidir（变冷）。","ex":[["Il fait froid dehors.","外面很冷。"],["J'ai froid aux mains.","我的手冷。"],["La soupe est froide.","汤凉了。"]],"co":[["avoir froid","觉得冷"],["il fait froid","天气冷"],["de l'eau froide","冷水"],["garder la tête froide","保持冷静"]],"sy":[["frais","courant","凉爽的"],["glacial","courant","冰冷的"],["frisquet","familier","有点冷，口语"]],"fq":"极高频，日常常用。","me":"froid 和 frigo（冰箱）同一家：fr- 就是冷。","tr":{"zh":"我冷，请把窗户关上。","fr":"J'ai froid, ferme la fenêtre, s'il te plaît.","alt":"J'ai froid, tu peux fermer la fenêtre ?","note":"感觉用 avoir froid。"}},
 "Gris(e)": {"pos":"adj. 形容词，阳性 gris，阴性 grise，复数 gris / grises","s":"灰色的。il fait gris = 天色阴沉；avoir les cheveux gris = 头发灰白；faire grise mine = 面露不悦。名词 la grisaille = 灰蒙蒙的天气。","ipa":"[gʁi] / [gʁiz]","ph":"g 在 r 前读 [g]；r 读 [ʁ]；阳性 s 不发音：[gʁi]；阴性 grise 读 [gʁiz]，s 读 [z]。","pi":"阳性结尾 s 不发音，阴性 s 变 [z]。gris 的 g 是硬的 [g]，不是 [ʒ]。","et":"来自法兰克语 *grīs（灰色）。同源：grisâtre（灰蒙蒙的）、grisaille（灰色调）、griser（使微醉）。","ex":[["Le ciel est gris aujourd'hui.","今天天空是灰色的。"],["Il porte un pull gris clair.","他穿一件浅灰色毛衣。"],["Elle a les cheveux gris.","她的头发是灰白的。"]],"co":[["il fait gris","天色阴沉"],["gris clair / gris foncé","浅灰 / 深灰"],["gris souris","鼠灰色"],["faire grise mine","面露不悦"]],"sy":[["cendré","soutenu","灰烬色，书面"],["argenté","courant","银灰色"],["grisâtre","courant","灰蒙蒙的"]],"fq":"高频，日常常用。","me":"gris 的 -s：阳性不发音，阴性才发 [z]。","tr":{"zh":"天空是灰色的，我想会下雨。","fr":"Le ciel est gris, je pense qu'il va pleuvoir.","alt":"Le ciel est tout gris, il va sûrement pleuvoir.","note":"je pense que + 将来表示预测。"}},
 "Jaune": {"pos":"adj. 形容词，阴阳性相同，复数 jaunes；也是名词 le jaune","s":"黄色的。名词 un jaune d'œuf = 蛋黄；le maillot jaune = 环法领先者黄衫；rire jaune = 苦笑。","ipa":"[ʒon]","ph":"j 读 [ʒ]（像 je）；au 读 [o]；n 要读；结尾 e 不发音。","pi":"j 是 [ʒ]，不是 [dʒ]。au = [o]，不读「jao」。阴阳性相同。","et":"来自古法语 jalne，源于拉丁语 galbinus（淡绿黄色的）。同源：jaunir（变黄）、jaunisse（黄疸）；英语 jaundice 就来自它。","ex":[["Le soleil est jaune.","太阳是黄色的。"],["Elle porte un imperméable jaune.","她穿着一件黄色雨衣。"],["Je mange un yaourt au citron jaune.","我吃一杯柠檬酸奶。"]],"co":[["jaune citron","柠檬黄"],["un jaune d'œuf","蛋黄"],["le maillot jaune","黄色领骑衫"],["rire jaune","苦笑"]],"sy":[["doré","courant","金黄色"],["blond","courant","金色（头发、麦子）"],["jaunâtre","courant","淡黄的"]],"fq":"高频，日常常用。","me":"jaune 和 jaundice（黄疸）：黄皮肤。","tr":{"zh":"她买了一个黄色的包。","fr":"Elle a acheté un sac jaune.","alt":"Elle s'est pris un sac jaune.","note":"sac 是阳性，所以 jaune。"}},
 "Léger / Légère": {"pos":"adj. 形容词，阳性 léger，阴性 légère，复数 légers / légères","s":"轻的；轻薄的；轻微的。une veste légère = 轻薄夹克；un repas léger = 清淡的一餐；un léger retard = 稍微迟到；prendre à la légère = 不当回事。反义词：lourd（重）。","ipa":"[le.ʒe] / [le.ʒɛʁ]","ph":"阳性 léger [le.ʒe]：é 读 [e]，g 在 e 前读 [ʒ]；阴性 légère [le.ʒɛʁ]：è 读 [ɛ]，r 要发。","pi":"光线「浅」用 clair，重量「轻」用 léger，别混。阴性有 è 重音：légère。","et":"来自拉丁语 leviarius（轻的），来自 levis。同源：légèreté（轻）、alléger（减轻）。","ex":[["C'est une veste légère.","这是一件轻薄夹克。"],["J'ai un sac très léger.","我的包很轻。"],["Il y a un léger retard.","有一点晚点。"]],"co":[["un repas léger","清淡的一餐"],["un léger retard","稍微晚点"],["à la légère","不当回事"],["avoir le sommeil léger","睡得浅"]],"sy":[["fin","courant","薄的"],["faible","courant","弱的、轻微的"],["lourd","courant","反义：重的"]],"fq":"高频，日常常用。","me":"léger 里有 lève（lever 抬起）：轻到可以抬起来。","tr":{"zh":"这个行李箱很轻，很方便。","fr":"Cette valise est légère, c'est pratique.","alt":"Elle est super légère, cette valise.","note":"alt 里 super 是口语的「特别」。"}},
 "Long / Longue": {"pos":"adj. 形容词，阳性 long，阴性 longue，复数 longs / longues","s":"长的（长度或时间）。une robe longue = 长裙；une longue journée = 漫长的一天；longtemps = 很久；le long de = 沿着。反义词：court。","ipa":"[lɔ̃] / [lɔ̃g]","ph":"on 是鼻音 [ɔ̃]；阳性 long [lɔ̃]，g 不发音；阴性 longue [lɔ̃g]，g 要发，u 不发。","pi":"阳性 long 不发 g，阴性 longue 发 [g]。longue 里的 u 只是让 g 保持硬音。","et":"来自拉丁语 longus（长的）。同源：longueur（长度）、allonger（拉长）、longitude（经度）。","ex":[["Elle a une longue robe.","她有一条长裙。"],["J'ai les cheveux longs.","我是长发。"],["La journée a été très longue.","这一天非常漫长。"]],"co":[["une robe longue","长裙"],["longtemps","很久"],["le long de la rivière","沿着河"],["à la longue","久而久之"]],"sy":[["interminable","courant","无休止的"],["allongé","courant","拉长的"],["court","courant","反义：短的"]],"fq":"极高频，日常常用。","me":"long 阳性静音，longue 发 [g]：加 e 就开口。","tr":{"zh":"他有黑色长发。","fr":"Il a les cheveux longs et noirs.","alt":"Il a de longs cheveux noirs.","note":"cheveux 是阳性复数，所以 longs。"}},
 "Marron": {"pos":"adj. 形容词，不变形（颜色）：des yeux marron；也是名词 un marron（大栗子）","s":"棕色的，栗色的。作颜色时不变形：des chaussures marron。名词 un marron = 栗子（大的那种）；marrons chauds = 糖炒栗子。头发、皮肤的棕色常用 brun。","ipa":"[ma.ʁɔ̃]","ph":"ma [ma]；rr 读一个 [ʁ]；on 是鼻音 [ɔ̃]；n 不读。","pi":"颜色 marron 不变形，不写 marrons。头发 / 皮肤棕色常说 brun，不说 marron。","et":"借自意大利语 marrone（栗子），再早的来源不确定。英语 maroon 也来自法语 marron。","ex":[["Il a les yeux marron.","他的眼睛是棕色的。"],["Elle porte des chaussures marron.","她穿着棕色鞋子。"],["J'adore les marrons chauds en hiver.","我很喜欢冬天的糖炒栗子。"]],"co":[["des yeux marron","棕色眼睛"],["un marron chaud","糖炒栗子"],["la crème de marrons","栗子酱"],["un marron glacé","糖渍栗子"]],"sy":[["brun","courant","棕色（头发、皮肤）"],["châtain","courant","栗色（头发）"],["noisette","courant","榛子色（眼睛）"]],"fq":"高频，日常常用。","me":"marron = 栗子的颜色，英语 maroon 也是它。","tr":{"zh":"他穿棕色的鞋。","fr":"Il porte des chaussures marron.","alt":"Il a des chaussures marron.","note":"颜色 marron 不加 s。"}},
 "Moche": {"pos":"adj. 形容词，口语，阴阳性相同，复数 moches","s":"丑的，难看的。口语词。也可形容天气差：il fait moche；或形容行为恶劣：c'est moche de dire ça（这样说很不好）。正式用 laid。","ipa":"[mɔʃ]","ph":"m [m]；o 是开口 [ɔ]；ch 读 [ʃ]；结尾 e 不发音。","pi":"口语词，不要在作文或工作邮件里用，换成 laid。ch = [ʃ]，不是 [tʃ] 或 [k]。","et":"来源不确定。","ex":[["Ce pull est un peu moche.","这件毛衣有点难看。"],["Il fait moche aujourd'hui.","今天天气很糟。"],["C'est moche de dire ça.","这么说不太好。"]],"co":[["c'est moche","很难看"],["il fait moche","天气很糟"],["moche comme un pou","非常难看（口语）"],["c'est moche de + infinitif","做某事很不好"]],"sy":[["laid","courant","标准说法：丑"],["affreux","courant","糟糕、可怕"],["dégueulasse","familier","很恶心、很糟糕（俚语）"]],"fq":"中频，口语。","me":"moche 像「糟」：一说出来就是不好看。","tr":{"zh":"这个壁纸真难看。","fr":"Ce papier peint est vraiment moche.","alt":"Ce papier peint, il est trop moche.","note":"moche 不分阴阳性，papier peint 是阳性也不用改。"}},
 "Noir(e)": {"pos":"adj. 形容词，阳性 noir，阴性 noire（读音相同），复数 noirs / noires；也是名词 le noir","s":"黑色的。名词 le noir = 黑暗；un café noir = 黑咖啡；le marché noir = 黑市；voir tout en noir = 看什么都悲观。","ipa":"[nwaʁ]","ph":"n [n]；oi 读 [wa]；r 要读出来；noir 和 noire 读音一样。","pi":"oi = [wa]，不是 [oi]。r 一定要发音。","et":"来自拉丁语 niger（黑的）。同源：noircir（弄黑）、noirceur（黑）；英语 film noir 直接借自法语。","ex":[["Le chat est noir.","猫是黑色的。"],["Je prends un café noir.","我喝黑咖啡。"],["Il porte une veste noire.","他穿一件黑外套。"]],"co":[["un café noir","黑咖啡"],["le marché noir","黑市"],["voir tout en noir","什么都悲观"],["noir et blanc","黑白"]],"sy":[["sombre","courant","暗的"],["ténébreux","littéraire","阴暗神秘的，文学"],["blanc","courant","反义：白色"]],"fq":"极高频，日常常用。","me":"noir 像 nuit（夜）：n 开头，都是黑。","tr":{"zh":"我在找一条黑色长裤。","fr":"Je cherche un pantalon noir.","alt":"Il me faut un pantalon noir.","note":"pantalon 是阳性，所以 noir。"}},
 "Parfait(e)": {"pos":"adj. 形容词，阳性 parfait，阴性 parfaite，复数 parfaits / parfaites；也可作感叹词 Parfait !","s":"完美的，完全的。Parfait ! 是口语回应，意思是「好的，太好了」。parfaitement = 完全地；也可答 Parfaitement ! = 当然！","ipa":"[paʁ.fɛ] / [paʁ.fɛt]","ph":"par [paʁ]；ai 读 [ɛ]；阳性结尾 -ait 的 t 不发音：[paʁ.fɛ]；阴性 parfaite 读 [paʁ.fɛt]。","pi":"阳性 t 不发音。ai 读 [ɛ]，不是 [ai]。Parfait ! 也用来回答「可以」。","et":"来自拉丁语 perfectus（完成的），是 perficere（完成）的过去分词。","ex":[["C'est parfait !","太完美了！"],["Ce plan est parfait.","这个计划很完美。"],["Elle parle un français parfait.","她的法语说得很完美。"]],"co":[["Parfait !","好的！太好了！"],["nul n'est parfait","没有人是完美的"],["parfaitement","完全地"],["un jour parfait","完美的一天"]],"sy":[["idéal","courant","理想的"],["impeccable","courant","无可挑剔的"],["nickel","familier","绝了、完美，口语"]],"fq":"极高频，日常常用。","me":"parfait 像 perfect：中间多了 f，最后的 t 不发音。","tr":{"zh":"这家餐厅很适合今晚。","fr":"Le restaurant est parfait pour ce soir.","alt":"Ce resto est parfait pour ce soir.","note":"pour ce soir 表示「今晚用」。"}},
 "Rectangulaire": {"pos":"adj. 形容词，阴阳性相同，复数 rectangulaires","s":"长方形的。来自 rectangle（长方形）。可以形容桌子、镜子、盘子、场地。反义词不多，常对比 carré（正方形）和 rond（圆）。","ipa":"[ʁɛk.tɑ̃.gy.lɛʁ]","ph":"r 读 [ʁ]；ec 读 [ɛk]；tan 读 [tɑ̃]；gu 在这里读 [gy]（u 要发音）；aire 读 [ɛʁ]。","pi":"这个词长，分四段：rec-tan-gu-laire。gu 后接 l，u 要读 [y]，和 guerre 里的 gu 不同。词尾 r 要读。","et":"rectangle（拉丁语 rectus angulus，直角）+ 后缀 -aire。同源：rectifier、angle（角）。","ex":[["La table est rectangulaire.","桌子是长方形的。"],["J'ai un miroir rectangulaire.","我有一面长方形的镜子。"],["Le terrain est rectangulaire.","这块场地是长方形的。"]],"co":[["une table rectangulaire","长方形的桌子"],["une forme rectangulaire","长方形"],["un plat rectangulaire","长方形盘子"],["un miroir rectangulaire","长方形镜子"]],"sy":[["allongé","courant","长的，拉长的"],["carré","courant","对比：正方形"],["oblong","soutenu","长圆形，书面"]],"fq":"低频，日常偶尔用。","me":"rectangle + -aire：直角（rect-）+ 角（angle）。","tr":{"zh":"我想要一张长方形的桌子。","fr":"Je voudrais une table rectangulaire.","alt":"Il me faut une table rectangulaire.","note":"rectangulaire 形容桌子，不分阴阳性。"}},
 "Rond(e)": {"pos":"adj. 形容词，阳性 rond，阴性 ronde，复数 ronds / rondes；也是名词 un rond（圆圈）","s":"圆的。un rond-point = 环岛；tourner en rond = 原地打转；une table ronde = 圆桌。口语里 il est rond 是「他喝醉了」，要小心。","ipa":"[ʁɔ̃] / [ʁɔ̃d]","ph":"r 读 [ʁ]；on 是鼻音 [ɔ̃]；阳性 d 不发音：[ʁɔ̃]；阴性 ronde 读 [ʁɔ̃d]，d 要发。","pi":"阳性 rond 里的 d 不发音；阴性 ronde 的 d 发音，但 e 不读。il est rond（口语）= 醉了。","et":"来自拉丁语 rotundus（圆的），来自 rota（轮子）。同源：arrondir（弄圆）、rotonde。","ex":[["Il porte des lunettes rondes.","他戴着圆眼镜。"],["La table est ronde.","桌子是圆的。"],["Je tourne en rond.","我在原地打转。"]],"co":[["tourner en rond","原地打转"],["un rond-point","环岛"],["une table ronde","圆桌"],["faire des ronds dans l'eau","在水里画圆圈"]],"sy":[["circulaire","courant","圆形的"],["arrondi","courant","变圆的、圆润的"],["rondelet","courant","胖乎乎的"]],"fq":"高频，日常常用。","me":"rond 来自「轮子」，轮子当然是圆的。","tr":{"zh":"她圆脸，戴着圆眼镜。","fr":"Elle a un visage rond et des lunettes rondes.","alt":"Elle a la tête ronde, avec des lunettes rondes.","note":"visage 是阳性，lunettes 是阴性复数，所以 rondes。"}},
 "Rose": {"pos":"adj. 形容词，阴阳性相同，复数 roses；也是名词 une rose（玫瑰，阴性）和 le rose（粉红色，阳性）","s":"粉红色的。作形容词时和 rose（玫瑰花）同形，可加 s：des robes roses。voir la vie en rose = 乐观地看人生。","ipa":"[ʁoz]","ph":"r [ʁ]；o 读 [o]；s 在两个元音间读 [z]；结尾 e 不发音。","pi":"s 是 [z]，不是 [s]。une rose（花）是阴性，le rose（颜色）是阳性。作形容词可以加 s：roses。","et":"来自拉丁语 rosa（玫瑰）。同源：rosé（粉红酒）、rosier（玫瑰丛）。","ex":[["Elle a un vélo rose.","她有一辆粉红色自行车。"],["J'offre une rose rouge à ma mère.","我送给妈妈一朵红玫瑰。"],["Il porte une chemise rose.","他穿一件粉红色衬衫。"]],"co":[["voir la vie en rose","乐观看人生"],["rose bonbon","糖果粉"],["rose pâle","浅粉"],["un vin rosé","桃红葡萄酒"]],"sy":[["rosé","courant","偏粉的；桃红酒"],["rosâtre","courant","偏粉的，略带贬义"],["fuchsia","courant","玫红色"]],"fq":"高频，日常常用。","me":"rose 里的 s 读 z，像「玫瑰」的发音 [ʁoz]。","tr":{"zh":"她为晚会买了一条粉红色裙子。","fr":"Elle a acheté une robe rose pour la fête.","alt":"Elle s'est pris une robe rose pour la fête.","note":"robe 是阴性，rose 不变化。"}},
 "Rouge": {"pos":"adj. 形容词，阴阳性相同，复数 rouges；也是名词 le rouge","s":"红色的。名词 le rouge = 红色；le rouge à lèvres = 口红；un feu rouge = 红灯；du vin rouge = 红葡萄酒。rougir = 变红、脸红。","ipa":"[ʁuʒ]","ph":"r 读 [ʁ]；ou 读 [u]；g 在 e 前读 [ʒ]；结尾 e 不发音。","pi":"ou = [u]，不是 [o]。g 在 e 前读 [ʒ]，不是 [g]。","et":"来自拉丁语 rubeus（红色的）。同源：rougir（变红）、rougeur（红）；英语 rouge 借自法语。","ex":[["La pomme est rouge.","苹果是红色的。"],["Le feu est rouge, on s'arrête.","红灯，我们停车。"],["Je bois un verre de vin rouge.","我喝一杯红酒。"]],"co":[["un feu rouge","红灯"],["du vin rouge","红酒"],["le rouge à lèvres","口红"],["être dans le rouge","在赤字中"]],"sy":[["écarlate","soutenu","猩红色"],["pourpre","soutenu","紫红色"],["vermeil","littéraire","红润的，文学"]],"fq":"极高频，日常常用。","me":"rouge：rou- 里的 ou 是 u，嘴要圆。","tr":{"zh":"我想要一条红色连衣裙去参加派对。","fr":"Je voudrais une robe rouge pour la fête.","alt":"Il me faut une robe rouge pour la fête.","note":"pour la fête 表示用途。"}},
 "Simple": {"pos":"adj. 形容词，阴阳性相同，复数 simples","s":"简单的；朴素的；单纯的。放在名词前表示「仅仅」：un simple coup de fil = 只是个电话。un aller simple = 单程票。simple comme bonjour = 非常简单。","ipa":"[sɛ̃pl]","ph":"s 读 [s]；im 在 p 前是鼻音 [ɛ̃]；p 要读；结尾 -ple 读 [pl]，e 不发音。","pi":"im 是鼻音 [ɛ̃]，m 不单独读。词尾 e 不发音，所以是 [sɛ̃pl]。","et":"来自拉丁语 simplex（单一的，简单的）。同源：simplifier（简化）、simplicité（简单）。","ex":[["La recette est simple.","食谱很简单。"],["C'est tout simple.","这很简单。"],["Je veux un aller simple pour Lyon.","我要一张到里昂的单程票。"]],"co":[["un aller simple","单程票"],["simple comme bonjour","简单得很"],["un simple coup de fil","只是个电话"],["c'est tout simple","很简单"]],"sy":[["facile","courant","容易的"],["modeste","courant","朴素的、谦逊的"],["compliqué","courant","反义：复杂的"]],"fq":"极高频，日常常用。","me":"simple 来自 sim-（一）：只有一层，所以简单。","tr":{"zh":"这个食谱很简单，你可以做。","fr":"Cette recette est très simple, tu peux la faire.","alt":"C'est une recette hyper simple, tu peux la faire.","note":"tu peux la faire：la 指代食谱。"}},
 "Vert(e)": {"pos":"adj. 形容词，阳性 vert，阴性 verte，复数 verts / vertes；也是名词 le vert","s":"绿色的。le feu vert = 绿灯，也指同意放行；avoir la main verte = 会种花草；un espace vert = 绿地。口语里 vert 还可指环保（le parti vert）。","ipa":"[vɛʁ] / [vɛʁt]","ph":"v 读 [v]；er 读 [ɛʁ]；阳性 t 不发音：[vɛʁ]；阴性 verte 读 [vɛʁt]，t 要发。","pi":"vert、ver（虫）、verre（玻璃杯）、vers（朝向）读音相同：[vɛʁ]，看拼写才知道意思。阴性 verte 要发 t。","et":"来自拉丁语 viridis（绿的）。同源：verdure（绿色植物）、verdoyant（绿油油的）、verdir（变绿）。","ex":[["L'herbe est verte.","草是绿色的。"],["Le feu est vert, on peut passer.","绿灯了，可以走。"],["J'aime le vert clair.","我喜欢浅绿色。"]],"co":[["le feu vert","绿灯 / 放行"],["avoir la main verte","会种花草"],["un espace vert","绿地"],["vert clair","浅绿"]],"sy":[["verdoyant","soutenu","绿意盎然，书面"],["écolo","familier","环保的，口语"],["vert pomme","courant","苹果绿"]],"fq":"极高频，日常常用。","me":"vert 同音词很多：vert、ver、verre、vers，只能靠上下文。","tr":{"zh":"她穿着绿裙子和绿鞋子。","fr":"Elle a une robe verte et des chaussures vertes.","alt":"Sa robe est verte, ses chaussures aussi.","note":"robe 和 chaussures 都是阴性，所以 verte / vertes。"}},
 "Violet / Violette": {"pos":"adj. 形容词，阳性 violet，阴性 violette，复数 violets / violettes；也是名词 le violet、la violette（紫罗兰）","s":"紫色的。名词 la violette = 紫罗兰（花）；le violet = 紫色。devenir violet = 因冷或怒而脸发紫。pourpre 偏红，mauve 偏浅。","ipa":"[vjɔ.lɛ] / [vjɔ.lɛt]","ph":"vio 读 [vjɔ]（v + j + 开口 o）；let 读 [lɛ]；阳性 t 不发音：[vjɔ.lɛ]；阴性 violette 读 [vjɔ.lɛt]，t 要发。","pi":"io 读 [jɔ]，不是两个音节的 [i.o]。阳性 t 不发音，阴性 violette 发 t。","et":"violet 来自 violette（紫罗兰，指小形式），来自拉丁语 viola。","ex":[["C'est une fleur violette.","这是一朵紫色的花。"],["Il porte un pull violet.","他穿一件紫色毛衣。"],["Elle devient violette de froid.","她冻得脸发紫。"]],"co":[["une fleur violette","紫色的花"],["violet foncé","深紫"],["devenir violet de colère","气得脸发紫"],["une violette","紫罗兰"]],"sy":[["mauve","courant","淡紫色"],["pourpre","soutenu","紫红色"],["lilas","courant","丁香色"]],"fq":"中频。","me":"violet 像「紫罗兰」violette：同一个词的阳性和阴性。","tr":{"zh":"她买了一条紫色的裙子。","fr":"Elle a acheté une jupe violette.","alt":"Elle s'est pris une jupe violette.","note":"jupe 是阴性，所以 violette。"}},
 "À la mode": {"pos":"loc. 固定短语，不变形（形容词性）","s":"流行的，时髦的。字面是「按照潮流」。être à la mode = 流行；passer de mode = 过时；démodé = 过时的。名词 la mode = 时尚。形容词 tendance（不变形）也常用。","ipa":"[a.la.mɔd]","ph":"à [a]；la [la]；mode 读 [mɔd]，o 是开口 [ɔ]，d 要发音；三个词连着读。","pi":"mode 的 d 要发音，e 不读。在法语里 à la mode 只表示「流行」，没有英语「配冰淇淋」的意思。","et":"mode 来自拉丁语 modus（方式，样式）。同源：moderne（现代的）、modèle（模型）、commode（方便的）。","ex":[["Cette couleur est à la mode.","这个颜色很流行。"],["Les bottes sont à la mode cet hiver.","今年冬天靴子很流行。"],["Il aime s'habiller à la mode.","他喜欢穿得时髦。"]],"co":[["être à la mode","流行"],["passer de mode","过时"],["un vêtement à la mode","时髦的衣服"],["c'est la mode","这是潮流"]],"sy":[["tendance","courant","流行的（形容词，不变）"],["branché","familier","赶潮流，口语"],["démodé","courant","反义：过时的"]],"fq":"高频，日常常用。","me":"à la mode = 按「模式」，大家都这样。","tr":{"zh":"这种风格现在很流行。","fr":"Ce style est très à la mode en ce moment.","alt":"Ce style est très tendance en ce moment.","note":"en ce moment = 此刻，现在。"}},
 "Bof !": {"pos":"interj. 感叹词，口语，不变形","s":"一般般；不怎么样；无所谓。表示不太热情、有点怀疑、不感兴趣。常常伴随耸肩、撇嘴。只在口语中使用。","ipa":"[bɔf]","ph":"b [b]；o 是开口 [ɔ]；f 要读出来 [bɔf]，一个音节。","pi":"f 要读：[bɔf]，不要读成「波」。这是口语，写文章或正式场合不要用。","et":"拟声感叹词（模仿耸肩时的呼气声），确切来源不确定。","ex":[["\"Tu aimes cette veste ?\" - \"Bof !\"","「你喜欢这件夹克吗？」「一般吧！」"],["Bof, ce n'est pas terrible.","一般，不怎么样。"],["Bof, je ne sais pas.","嗯……我不知道。"]],"co":[["Bof, pas terrible.","一般般，不怎么样。"],["Bof, je sais pas.","嗯，我不知道。"],["comme ci, comme ça","马马虎虎"],["Bof, bof.","无所谓，无所谓。"]],"sy":[["mouais","familier","嗯……（半信半疑）"],["bah","familier","那个……（犹豫）"],["moyen","familier","一般，不怎么样"]],"fq":"高频，口语。","me":"bof 的声音就像耸肩时嘴里吹出的气。","tr":{"zh":"「你喜欢这部电影吗？」「不太喜欢。」","fr":"\"Tu as aimé le film ?\" - \"Bof, pas trop.\"","alt":"\"Le film t'a plu ?\" - \"Bof, moyen.\"","note":"回答时用 Bof, pas trop = 不太怎么样。"}},
 "C'est pas donné !": {"pos":"loc. 口语固定短语；标准形式 Ce n'est pas donné","s":"可不便宜！字面是「不是白送的」，意思是价格很高。口语里常省略 ne。反义说法：C'est donné ! = 便宜得像白送。","ipa":"[sɛ pa dɔ.ne]","ph":"c'est 读 [sɛ]，t 不发音；pas 读 [pa]；donné 读 [dɔ.ne]，nn 只读一个 [n]，o 是开口 [ɔ]。","pi":"口语去掉了 ne。别把 C'est donné ! 当成「很贵」：它正好相反，是「很便宜」。","et":"donner 来自拉丁语 donare（赠送），来自 donum（礼物）。同源：donation、pardonner。","ex":[["Ce sac coûte 200 euros, c'est pas donné !","这个包 200 欧元，可不便宜！"],["Ce restaurant est bon, mais ce n'est pas donné.","这家餐厅不错，但不便宜。"],["C'est donné !","这简直是白送！"]],"co":[["Ce n'est pas donné.","不便宜。"],["C'est donné !","便宜得像白送！"],["ça coûte les yeux de la tête","贵得要命"]],"sy":[["c'est cher","courant","很贵"],["c'est salé","familier","挺贵的（口语）"],["c'est donné","familier","反义：便宜得像白送"]],"fq":"中高频，口语。","me":"pas donné = 没人白送给你：要付钱，而且付得多。","tr":{"zh":"这家餐厅很棒，但可不便宜！","fr":"Ce restaurant est excellent, mais c'est pas donné !","alt":"Ce resto est top, mais c'est pas donné !","note":"口语省略 ne，写作时用 Ce n'est pas donné。"}},
 "C'est pas grave": {"pos":"loc. 口语固定短语；标准形式 Ce n'est pas grave","s":"没关系；没什么大不了。对别人道歉时的常用回答。口语去掉 ne，甚至只说 Pas grave !。形容词 grave 本义是「严重的」。","ipa":"[sɛ pa gʁav]","ph":"c'est 读 [sɛ]；pas 读 [pa]；grave 读 [gʁav]，a 是 [a]，v 读出来，结尾 e 不发音。","pi":"grave 是「严重」，不是英语 grave（坟墓）的意思。口语省略 ne：C'est pas grave。","et":"grave 来自拉丁语 gravis（重的，严重的）。同源：gravité（严重性）、aggraver（使恶化）。","ex":[["Désolé ! - C'est pas grave.","对不起！——没关系。"],["J'ai oublié mon livre. - Pas grave !","我忘了带书。——没关系！"],["Ce n'est pas grave du tout.","完全没关系。"]],"co":[["Pas grave !","没关系！"],["Ce n'est pas bien grave.","不太严重。"],["une maladie grave","严重的病"],["une erreur grave","严重的错误"]],"sy":[["ce n'est rien","courant","没什么"],["pas de souci","familier","没问题（口语）"],["il n'y a pas de mal","soutenu","没有伤害，书面"]],"fq":"极高频，口语。","me":"pas grave = 不重：别放在心上。","tr":{"zh":"我忘了你的书，对不起。——没关系。","fr":"J'ai oublié ton livre, désolé. - C'est pas grave.","alt":"J'ai oublié ton livre, pardon. - Pas grave !","note":"答道歉时 C'est pas grave 最自然。"}},
 "En promotion / En solde": {"pos":"loc. 固定短语；promotion n.f.，solde n.m. / les soldes n.m.pl.","s":"打折，特价。en promotion = 商店的促销（任何时候）；en solde = 官方打折季的折扣；les soldes（复数）= 打折季，每年两次（冬季、夏季）。口语缩写 en promo。","ipa":"[ɑ̃ pʁɔ.mo.sjɔ̃] / [ɑ̃ sɔld]","ph":"en [ɑ̃]；promotion 读 [pʁɔ.mo.sjɔ̃]，-tion 读 [sjɔ̃]；solde 读 [sɔld]，l 和 d 都发音。","pi":"-tion 读 [sjɔ̃]，不是 [ʃən]。solde 里 l、d 都要读。les soldes 是打折季，un solde 还可以指账户余额。","et":"promotion 来自拉丁语 promotio（前进，提升）。solde 与动词 solder（清仓）同族，来源可追溯到意大利语。","ex":[["Ces chaussures sont en solde.","这双鞋在打折。"],["Le fromage est en promotion cette semaine.","这周奶酪在促销。"],["Les soldes d'hiver commencent demain.","冬季打折明天开始。"]],"co":[["tout est en promotion","全场打折"],["les soldes d'été / d'hiver","夏季 / 冬季大减价"],["une promo","促销（口语）"],["à prix réduit","降价"]],"sy":[["en promo","familier","促销，口语"],["à prix réduit","courant","降价后的价格"],["en réduction","courant","打折"]],"fq":"高频，购物时常用。","me":"en solde = 价格「被清」；en promotion = 价格被「推」。","tr":{"zh":"这些球鞋在打折，我买两双。","fr":"Ces baskets sont en solde, j'en prends deux paires.","alt":"Ces baskets sont en promo, j'en prends deux.","note":"j'en prends deux = 我要两双，en 指代鞋。"}},
 "Joyeux anniversaire !": {"pos":"loc. 祝福语；joyeux 阳性 / joyeuse 阴性；anniversaire n.m.","s":"生日快乐！也可以说 Bon anniversaire !，更常用。anniversaire 在法语里默认是「生日」；结婚纪念日要说 anniversaire de mariage。","ipa":"[ʒwa.jø.za.ni.vɛʁ.sɛʁ]","ph":"joyeux 读 [ʒwa.jø]；anniversaire 读 [a.ni.vɛʁ.sɛʁ]；x 在元音前常连读成 [z]：[ʒwa.jø.za.ni...]。","pi":"joyeux 里的 oy 读 [wa.j]。anniversaire 很长，分段记：a-ni-ver-saire。说「生日」用 anniversaire 就够了，不必加 de naissance。","et":"joyeux 来自 joie（拉丁语 gaudia，gaudium 的复数）。anniversaire 来自拉丁语 anniversarius（每年回来的），由 annus（年）和 versus（转）组成。","ex":[["Joyeux anniversaire pour tes 30 ans !","三十岁生日快乐！"],["Bon anniversaire, Léa !","生日快乐，蕾雅！"],["On fête son anniversaire samedi.","我们星期六庆祝他的生日。"]],"co":[["bon anniversaire !","生日快乐！"],["un gâteau d'anniversaire","生日蛋糕"],["fêter son anniversaire","庆祝生日"],["un cadeau d'anniversaire","生日礼物"]],"sy":[["Bon anniversaire !","courant","最常用的说法"],["Meilleurs vœux","soutenu","书面致意语"]],"fq":"极高频，日常常用。","me":"anniversaire = 每年（anni）回来（versaire）的日子。","tr":{"zh":"生日快乐，玛丽！你几岁了？","fr":"Joyeux anniversaire, Marie ! Tu as quel âge ?","alt":"Bon anniversaire, Marie ! Tu as quel âge ?","note":"Tu as quel âge ? 是问年龄的常用句。"}},
 "Plein de": {"pos":"loc. 数量短语，口语；后面直接接名词（不加冠词）。作形容词时：plein / pleine de = 充满……","s":"很多；充满。plein de + 名词 = 很多（口语）：plein de monde（很多人）。plein(e) de = 装满……：une valise pleine de vêtements。比 beaucoup de 随意。","ipa":"[plɛ̃ də]","ph":"pl [pl]；ein 读鼻音 [ɛ̃]；de 读弱的 [də]；n 和 i 一起组成鼻音，不分开。","pi":"plein de 后面不加 des / les：plein de livres（不是 plein des livres）。表示「很多」时 plein 不变形。","et":"来自拉丁语 plenus（满的）。同源：plénitude（充实）、compléter。","ex":[["Il y a plein de monde.","有好多人。"],["J'ai plein de choses à faire.","我有很多事要做。"],["La valise est pleine de vêtements.","行李箱里装满了衣服。"]],"co":[["plein de monde","很多人"],["plein de choses","很多东西"],["faire le plein","加满油"],["en plein air","户外"]],"sy":[["beaucoup de","courant","很多（标准）"],["un tas de","familier","一大堆"],["énormément de","courant","非常多"]],"fq":"极高频，口语。","me":"plein 就是「满」，像 plenty：满满的。","tr":{"zh":"街上有好多人。","fr":"Il y a plein de gens dans la rue.","alt":"Y a plein de monde dans la rue.","note":"plein de gens 比 beaucoup de gens 更口语。"}},
 "L'après-midi": {"pos":"n.m. 阳性名词（也可作阴性 une après-midi），复数 des après-midi（不变）","s":"下午。l'après-midi = 每天下午，或在下午；cet après-midi = 今天下午；demain après-midi = 明天下午。口语缩写 l'aprèm。表示几点钟下午：trois heures de l'après-midi。","ipa":"[la.pʁɛ.mi.di]","ph":"l'après-midi：l' 省音；après 读 [a.pʁɛ]；midi 读 [mi.di]；d 要发音。","pi":"「今天下午」说 cet après-midi。après-midi 复数不加 s：des après-midi。性别阴阳都可，但阳性更常见。","et":"après（拉丁语 ad pressum「靠近」）+ midi（拉丁语 medius dies「中间的日子」）。midi 是中午。","ex":[["J'étudie l'après-midi.","我下午学习。"],["Cet après-midi, je vais au marché.","今天下午我去市场。"],["On se voit à trois heures de l'après-midi.","我们下午三点见。"]],"co":[["cet après-midi","今天下午"],["demain après-midi","明天下午"],["trois heures de l'après-midi","下午三点"],["en fin d'après-midi","傍晚时分"]],"sy":[["matin","courant","对比：早上"],["soir","courant","对比：晚上"],["soirée","courant","晚会，傍晚时段"]],"fq":"极高频，日常常用。","me":"après-midi = 在中午（midi）之后（après）。","tr":{"zh":"今天下午我约了牙医。","fr":"Cet après-midi, j'ai rendez-vous chez le dentiste.","alt":"Cet aprèm, j'ai rendez-vous chez le dentiste.","note":"avoir rendez-vous chez + 职业 = 去看某个职业的人。"}},
 "Le sirop": {"pos":"n.m. 阳性名词，复数 sirops","s":"糖浆。两种常见用法：加水喝的果味糖浆（un sirop de menthe / de grenadine）；药用止咳糖浆（un sirop contre la toux）。咖啡馆点 un sirop，就是糖浆兑水。sirop d'érable = 枫糖浆。","ipa":"[si.ʁo]","ph":"s [s]；i [i]；r [ʁ]；o 读 [o]；结尾 p 不发音。","pi":"结尾 p 不发音（和 trop、beaucoup 一样）。重音在最后一个音节：si-RO。","et":"来自中世纪拉丁语 siropus，源于阿拉伯语 sharāb（饮料）。同源：英语 syrup、sherbet、sorbet。","ex":[["Je bois du sirop.","我喝糖浆水。"],["Je prends un sirop de menthe.","我要一杯薄荷糖浆。"],["J'ai du sirop contre la toux.","我有止咳糖浆。"]],"co":[["un sirop de menthe / de grenadine","薄荷 / 石榴糖浆"],["du sirop d'érable","枫糖浆"],["un sirop contre la toux","止咳糖浆"],["de l'eau avec du sirop","糖浆兑水"]],"sy":[["jus","courant","果汁，不是糖浆"],["grenadine","courant","红色石榴糖浆"],["mélasse","courant","糖蜜，更浓更黑"]],"fq":"中频。","me":"sirop 的 p 不发音：「西-萝」。","tr":{"zh":"我想要一杯加薄荷糖浆的水。","fr":"Je voudrais un verre d'eau avec du sirop de menthe.","alt":"Un sirop à la menthe, s'il vous plaît.","note":"alt 中 à la menthe = 薄荷味的。"}},
 "Minuit": {"pos":"n.m. 阳性名词，复数 minuits（很少用）","s":"午夜，夜里十二点。à minuit = 在午夜；minuit pile = 正好十二点；minuit et demi = 十二点半。官方时间常说 zéro heure。反义对比：midi（中午十二点）。","ipa":"[mi.nɥi]","ph":"m [m]；i [i]；ui 读 [ɥi]（半元音 + i）；结尾 t 不发音，整词两个音节。","pi":"结尾 t 不发音（minuit 像 nuit 一样）。ui 是 [ɥi]，是一个音节，不要拆成「u-i」。","et":"来自古法语 mienuit，由 mi（中间，拉丁语 medius）+ nuit（夜，拉丁语 nox, noctis）组成。","ex":[["Il dort à minuit.","他午夜睡觉。"],["Il est minuit et demi.","现在十二点半。"],["Je me couche vers minuit.","我大约十二点睡觉。"]],"co":[["à minuit","在午夜"],["minuit pile","正好午夜"],["vers minuit","接近午夜"],["minuit et demi","十二点半"]],"sy":[["zéro heure","courant","零点（官方说法）"],["midi","courant","对比：中午"],["milieu de la nuit","courant","半夜"]],"fq":"高频，日常常用。","me":"minuit = mi（中间）+ nuit（夜）：夜的中间。","tr":{"zh":"电影在午夜结束。","fr":"Le film finit à minuit.","alt":"Le film se termine vers minuit.","note":"film 是阳性，finit 是 finir 的第三人称。"}},
 "Un banc": {"pos":"n.m. 阳性名词，复数 bancs","s":"长椅，长凳（公园里、学校里）。其他意思：un banc de poissons = 鱼群；un banc de sable = 沙洲；le banc des accusés = 被告席。","ipa":"[bɑ̃]","ph":"b [b]；an 读鼻音 [ɑ̃]；结尾 c 不发音。","pi":"banc 的 c 不发音；banque（银行）才读 [bɑ̃k]。两个词容易混。","et":"来自法兰克语 *bank（长凳）。同源：banque（银行）、banquet（宴会）、banquette（长座椅）；英语 bench 和 bank 同族。","ex":[["Je m'assois sur le banc.","我坐在长椅上。"],["Il y a un banc dans le parc.","公园里有一张长椅。"],["Un banc de poissons nage près du bateau.","一群鱼在船边游。"]],"co":[["un banc public","公共长椅"],["s'asseoir sur un banc","坐在长椅上"],["un banc de poissons","鱼群"],["un banc de sable","沙洲"]],"sy":[["siège","courant","座位"],["banquette","courant","带软垫的长座椅"],["chaise","courant","单人椅子"]],"fq":"中高频，日常常用。","me":"banc 的 c 不发音，banque 才发 k。","tr":{"zh":"我们坐在公园的长椅上。","fr":"Nous nous asseyons sur un banc dans le parc.","alt":"On s'assoit sur un banc dans le parc.","note":"s'asseoir 是代动词，nous nous asseyons 是现在时。"}},
 "Un concert": {"pos":"n.m. 阳性名词，复数 concerts","s":"音乐会，演唱会。aller à un concert = 去听音乐会；donner un concert = 举办音乐会；un concert de jazz = 爵士音乐会。de concert = 一起，一致地（书面）。","ipa":"[kɔ̃.sɛʁ]","ph":"con 读鼻音 [kɔ̃]；c 在 e 前读 [s]；ert 读 [ɛʁ]；结尾 t 不发音，r 要读。","pi":"结尾 t 不发音：[kɔ̃.sɛʁ]，不像英语 concert 那样发 t。注意 c 读 [s]。","et":"借自意大利语 concerto（协调，和谐），法语 16 世纪起使用。同源：concerter（商议）。","ex":[["Le concert est super.","音乐会很棒。"],["On va à un concert samedi soir.","我们星期六晚上去听音乐会。"],["Le concert commence à vingt heures.","音乐会晚上八点开始。"]],"co":[["aller à un concert","去听音乐会"],["donner un concert","举办音乐会"],["un concert de jazz","爵士音乐会"],["une place de concert","音乐会门票"]],"sy":[["spectacle","courant","演出"],["récital","courant","独奏音乐会"],["festival","courant","音乐节"]],"fq":"高频，日常常用。","me":"concert 的 t 不发音：「宽-赛」。","tr":{"zh":"我想去听爵士音乐会。","fr":"Je voudrais aller à un concert de jazz.","alt":"J'aimerais bien aller voir un concert de jazz.","note":"aimerais bien + 不定式：委婉地说想做某事。"}},
 "Un film (d'action, d'amour, d'horreur, ...)": {"pos":"n.m. 阳性名词，复数 films","s":"电影。后面常用 de 加类型：un film d'action（动作片）、un film d'amour（爱情片）、un film d'horreur（恐怖片）。电视剧不叫 film，叫 une série。","ipa":"[film]","ph":"f [f]；i；l 和 m 都要发音，结尾 m 不鼻化，读 [film]。","pi":"结尾 -lm 要读出来 [lm]，不要吞掉 m；不是 [fi]。","et":"借自英语 film（胶片、影片），19 世纪末进入法语。","ex":[["Je regarde un film.","我在看电影。"],["On regarde un film ce soir ?","我们今晚看电影吧？"],["J'ai adoré ce film d'horreur.","我特别喜欢这部恐怖片。"]],"co":[["un film d'action / d'amour / d'horreur","动作片 / 爱情片 / 恐怖片"],["aller voir un film au cinéma","去电影院看电影"],["un film en version originale (VO)","原声版电影（法语 VO 指原语言配字幕）"],["un film doublé","配音版电影"]],"sy":[["long métrage","courant","长片，较正式的说法"],["navet","familier","烂片（口语，带讽刺）"],["série","courant","电视剧，不是电影"]],"fq":"极高频，日常常用。","me":"film 的 l 和 m 都发音，像英语 film。","tr":{"zh":"今晚我们看一部恐怖片。","fr":"Ce soir, on regarde un film d'horreur.","alt":"Ce soir, on se fait un film d'horreur ?","note":"看电影用 regarder un film；去电影院看用 aller voir un film。"}},
 "Un groupe": {"pos":"n.m. 阳性名词，复数 groupes","s":"团体；一组人；乐队。un groupe de musique = 乐队；un groupe d'amis = 一群朋友；un groupe sanguin = 血型。","ipa":"[ɡʁup]","ph":"gr [ɡʁ]；ou [u]；p 要发音 [p]；结尾 e 不发音。","pi":"结尾的 p 要读出来：[ɡʁup]。对比 loup（狼）的 p 不发音。","et":"来自意大利语 gruppo，16 世纪进入法语。","ex":[["Le groupe chante bien.","乐队唱得很好。"],["Nous partons en groupe.","我们一起出发。"],["Mon groupe préféré joue samedi soir.","我最喜欢的乐队星期六晚上演出。"]],"co":[["un groupe de musique / de rock","音乐乐队 / 摇滚乐队"],["en groupe","成组地；集体地"],["un groupe d'amis","一群朋友"],["un groupe sanguin","血型"]],"sy":[["bande","familier","一帮人（口语）"],["équipe","courant","团队、队伍"],["formation","soutenu","乐团、阵容（较正式）"]],"fq":"极高频，日常常用。","me":"groupe：p 要发音，不像 loup。","tr":{"zh":"我最喜欢的乐队星期六晚上演出。","fr":"Mon groupe préféré joue samedi soir.","alt":"Mon groupe préféré fait un concert samedi soir.","note":"乐队演出：jouer 或 faire un concert 都可以。"}},
 "Un TGV": {"pos":"n.m. 阳性名词，复数 des TGV（不变）","s":"法国高速列车，全称 train à grande vitesse。因为是 un train，所以用阳性：un TGV。","ipa":"[te.ʒe.ve]","ph":"按字母读：T [te]，G [ʒe]，V [ve]，合起来 [te.ʒe.ve]。","pi":"字母 G 在法语里读 [ʒe]，不是 [ɡe]；缩写按字母名读，不要拼成一个词。","et":"缩写自 train à grande vitesse；1981 年起在巴黎—里昂线运营。","ex":[["Je prends le TGV.","我坐高铁。"],["Le TGV part à huit heures.","高铁八点开。"],["Il y a un TGV direct pour Marseille.","有一趟去马赛的直达高铁。"]],"co":[["prendre le TGV","坐高铁"],["un billet de TGV","高铁票"],["le TGV Paris-Lyon","巴黎—里昂高铁"],["rater son TGV","错过高铁"]],"sy":[["train","courant","火车（总称）"],["Intercités","courant","城际列车，比高铁慢"],["TER","courant","区域列车"]],"fq":"高频，在法国日常常用。","me":"T-G-V = [te ʒe ve]，三个字母名。","tr":{"zh":"明天我坐高铁去马赛。","fr":"Demain, je prends le TGV pour Marseille.","alt":"Demain, je vais à Marseille en TGV.","note":"坐某种交通工具：prendre le TGV 或 aller en TGV。"}},
 "Un zoo": {"pos":"n.m. 阳性名词，复数 zoos","s":"动物园。zoo 是 jardin zoologique 的缩写。","ipa":"[zo]","ph":"z [z]；oo 合起来读一个 [o]，不是 [u]。","pi":"不要按英语读成 [zu]。法语是 [zo]，口型更圆更短。","et":"缩写自 jardin zoologique；zoologique 来自希腊语 zôon（动物）。","ex":[["Nous allons au zoo.","我们去动物园。"],["Les enfants adorent le zoo de Vincennes.","孩子们都爱万塞讷动物园。"],["Samedi, on a visité un zoo.","星期六我们去参观了一家动物园。"]],"co":[["aller au zoo","去动物园"],["visiter un zoo","参观动物园"],["une sortie au zoo","去动物园的出游"],["les animaux du zoo","动物园里的动物"]],"sy":[["parc zoologique","soutenu","动物园（较正式）"],["ménagerie","soutenu","（旧式）动物展览"]],"fq":"中频。","me":"zoo = [zo]，不是英语的 [zu]。","tr":{"zh":"星期六我们带孩子去动物园。","fr":"Samedi, nous allons au zoo avec les enfants.","alt":"Samedi, on emmène les enfants au zoo.","note":"带某人去：emmener qqn quelque part。"}},
 "La nuit": {"pos":"n.f. 阴性名词，复数 nuits","s":"夜晚；黑夜。la nuit = 在夜里；Il fait nuit = 天黑了；Bonne nuit ! = 晚安。","ipa":"[nɥi]","ph":"n [n]；ui 合成一个滑音 [ɥi]；结尾 t 不发音。","pi":"结尾 t 不发音，读 [nɥi]；ui 是一个音节，像快读的「于-i」，不是 [wi]。","et":"拉丁语 nox, noctis（夜）。同源：nocturne（夜曲）。","ex":[["La nuit est noire.","夜晚是黑色的。"],["Il fait nuit à cinq heures en hiver.","冬天五点天就黑了。"],["Bonne nuit, à demain !","晚安，明天见！"]],"co":[["Bonne nuit !","晚安！"],["la nuit dernière","昨夜"],["de nuit / la nuit","在夜里"],["passer la nuit à l'hôtel","在酒店过夜"]],"sy":[["jour","courant","白天（反义）"],["soir","courant","晚上（日落后到睡觉前）"],["obscurité","soutenu","黑暗"]],"fq":"极高频，日常常用。","me":"nuit ← nox：夜曲 nocturne 同源。","tr":{"zh":"晚安，明天见！","fr":"Bonne nuit, à demain !","alt":"Dors bien, à demain !","note":"睡前说 Bonne nuit；晚上见面分别说 Bonne soirée。"}},
 "La rentrée": {"pos":"n.f. 阴性名词，复数 rentrées","s":"开学；假期后回到学校或工作岗位（法国多指九月）。还有 la rentrée littéraire（秋季出新书季）、la rentrée politique。","ipa":"[ʁɑ̃.tʁe]","ph":"r [ʁ]；en [ɑ̃]；tr [tʁ]；ée [e]。","pi":"en 是鼻化元音 [ɑ̃]，n 不单独发音；结尾 -ée 读 [e]。","et":"来自 rentrer（re- + entrer）的名词，形式像阴性过去分词。","ex":[["La rentrée scolaire est en septembre.","新学年在九月开始。"],["À la rentrée, je change d'école.","开学时我换学校。"],["Après la rentrée, il y a beaucoup de travail.","开学后有很多功课。"]],"co":[["la rentrée des classes","开学（学校）"],["la rentrée scolaire","新学年"],["à la rentrée","开学的时候"],["la rentrée littéraire","秋季新书季"]],"sy":[["reprise","courant","重新开始"],["retour","courant","返回"]],"fq":"高频，九月前后很常用。","me":"rentrer + ée：「再进来」= 回到学校。","tr":{"zh":"开学时我有一位新老师。","fr":"À la rentrée, j'ai un nouveau professeur.","alt":"À la rentrée, je vais avoir un nouveau prof.","note":"à la rentrée = 到开学时（通常指九月）。"}},
 "Une activité": {"pos":"n.f. 阴性名词，复数 activités","s":"活动；（职业）工作领域。une activité sportive = 体育活动；son activité professionnelle = 他的职业；en activité = 在职、在运转。","ipa":"[ak.ti.vi.te]","ph":"c [k]；ti [ti]；v [v]；é [e]；重音落在最后音节。","pi":"ti 读 [ti]，不是 [si]；重音在最后一个音节 -té。","et":"来自 actif（拉丁语 activus，源自 agere「做、行动」）。同源：agir、acte。","ex":[["C'est une bonne activité.","这是个好活动。"],["Quelle est ton activité préférée ?","你最喜欢的活动是什么？"],["Il y a beaucoup d'activités pour les enfants.","有很多适合孩子的活动。"]],"co":[["une activité sportive","体育活动"],["une activité manuelle","手工活动"],["des activités extrascolaires","课外活动"],["être en pleine activité","正忙碌、正在运转"]],"sy":[["occupation","courant","事情、消遣"],["loisir","courant","休闲活动"],["passe-temps","courant","消遣、爱好"]],"fq":"高频，日常常用。","me":"activité = actif + -ité：「正在做的事」。","tr":{"zh":"你星期三做什么活动？","fr":"Quelle activité fais-tu le mercredi ?","alt":"Tu fais quoi comme activité, le mercredi ?","note":"faire une activité = 参加一项活动。"}},
 "Une bande dessinée (BD)": {"pos":"n.f. 阴性名词，复数 bandes dessinées / BD","s":"漫画；连环画。常缩写为 une BD，口语 une bédé。在法国和比利时是一种重要文化（Tintin、Astérix）。","ipa":"[bɑ̃d.de.si.ne]","ph":"bande [bɑ̃d]，d 在这里要读出来；dessinée [de.si.ne]；BD 读字母 [be.de]。","pi":"an 是鼻化音 [ɑ̃]；dessinée 里 ss 读 [s]；BD 按字母读，不是 [bd]。","et":"bande（带状）+ dessinée（dessiner「画」的阴性过去分词）：「画出来的条带」。","ex":[["Je lis une BD.","我读漫画。"],["J'adore les BD de Tintin.","我特别喜欢丁丁历险记。"],["Il lit une BD dans sa chambre.","他在房间里看漫画。"]],"co":[["lire une BD","看漫画"],["un album de BD","漫画册"],["un auteur de BD","漫画作者"],["le festival de la bande dessinée d'Angoulême","昂古莱姆国际漫画节"]],"sy":[["bédé","familier","漫画（口语缩写）"],["manga","courant","日本漫画"],["comics","courant","美式漫画"]],"fq":"中高频。","me":"bande + dessinée = 「画出来的条」，缩写 BD = [be.de]。","tr":{"zh":"我把这本漫画借给朋友。","fr":"Je prête cette BD à mon ami.","alt":"Je prête cette bédé à mon copain.","note":"BD 是阴性：cette BD；prêter qqch à qqn。"}},
 "Une heure": {"pos":"n.f. 阴性名词，复数 heures","s":"小时；点钟。Il est trois heures = 现在三点；à quelle heure ? = 几点？；une heure = 一个小时 / 一点钟。","ipa":"[œʁ]","ph":"h 不发音；eu 在 r 前读 [œ]；结尾 r 要发音，读 [œʁ]。","pi":"h 不发音，所以 l'heure、une heure 要连读 [y.nœʁ]；deux heures 读 [dø.zœʁ]（连读 z）。","et":"拉丁语 hora，源自希腊语 hôra（时间）。","ex":[["J'ai une heure.","我有一个小时。"],["À quelle heure tu pars ?","你几点走？"],["Il est une heure de l'après-midi.","现在是下午一点。"]],"co":[["À quelle heure ?","几点？"],["une heure et demie","一点半"],["à l'heure","准时"],["dans une heure","一个小时之后"]],"sy":[["minute","courant","分钟"],["horaire","courant","时间表、班次"],["moment","courant","时刻"]],"fq":"极高频，日常常用。","me":"heure：h 不发音，开头是元音 [œ]。","tr":{"zh":"火车一小时后出发。","fr":"Le train part dans une heure.","alt":"Dans une heure, le train part.","note":"dans + 时间段 = 多久之后；表示准时用 à l'heure。"}},
 "Une personne": {"pos":"n.f. 阴性名词，复数 personnes（永远是阴性）","s":"人。永远是阴性：即使指男人也说 une personne gentille。数人数用 personnes：trois personnes。另外 personne 作代词时是「没有人」：Personne ne vient。","ipa":"[pɛʁ.sɔn]","ph":"e [ɛ]；rs [ʁs]；o [ɔ]；nn 读一个 [n]；结尾 e 不发音。","pi":"指男人也是阴性，形容词要用阴性：C'est une personne gentille。别和 gens（一些人）混淆。","et":"拉丁语 persona（演员的面具），后指「人物、角色」。","ex":[["C'est une bonne personne.","这是个好人。"],["C'est une personne très gentille.","这是一个很友善的人。"],["Nous sommes cinq personnes.","我们一共五个人。"]],"co":[["une personne âgée","老年人"],["par personne","每人"],["en personne","亲自"],["une grande personne","成年人、大人"]],"sy":[["gens","courant","人们（复数，不带数字）"],["individu","soutenu","个人、个体（较正式）"],["type","familier","家伙（口语）"]],"fq":"极高频，日常常用。","me":"personne 永远阴性：「那个人」是 une personne，不管男女。","tr":{"zh":"车里有四个人。","fr":"Il y a quatre personnes dans la voiture.","alt":"On est quatre dans la voiture.","note":"数字 + personnes；泛指一群人用 les gens。"}},
 "Une série": {"pos":"n.f. 阴性名词，复数 séries","s":"系列；电视剧（une série télé）；一连串。une série de = 一系列；hors série = 特刊、特别的。","ipa":"[se.ʁi]","ph":"s [s]；é [e]；r [ʁ]；i [i]。","pi":"第一个 é 读 [e]，不是 [ɛ]；r 在喉咙发音。","et":"拉丁语 series（一串、序列）。","ex":[["J'aime cette série.","我喜欢这部剧。"],["On regarde une série le soir.","我们晚上看一部剧。"],["Cette série a quatre saisons.","这部剧有四季。"]],"co":[["une série télévisée / une série télé","电视剧"],["regarder une série","追剧"],["une série de questions","一连串问题"],["fabriqué en série","批量生产的"]],"sy":[["feuilleton","courant","连续剧"],["saison","courant","（剧集的）一季"],["suite","courant","后续、接下来的部分"]],"fq":"高频，日常常用。","me":"série = 一连串：剧集一集接一集。","tr":{"zh":"你最近在看哪部剧？","fr":"Tu regardes quelle série en ce moment ?","alt":"Tu regardes quoi comme série en ce moment ?","note":"quelle série (阴性)；quoi comme série 是口语说法。"}},
 "Les cheveux": {"pos":"n.m.pl. 阳性复数名词（单数 un cheveu = 一根头发）","s":"头发。法语里「头发」一般用复数 les cheveux，不是单数。un cheveu 指一根头发。动物的毛或身体的毛是 poils，不是 cheveux。","ipa":"[ʃə.vø]","ph":"ch [ʃ]；e [ə] 很轻；eu [ø]；结尾 x 不发音。","pi":"头发永远用复数 les cheveux，说「他有短发」用 Il a les cheveux courts。结尾 x 不发音。","et":"拉丁语 capillus（头发），经古法语 chevel 演变成 cheveu。","ex":[["Il a les cheveux courts.","他的头发很短。"],["Elle a de longs cheveux bruns.","她有一头棕色长发。"],["Je me lave les cheveux.","我在洗头。"]],"co":[["avoir les cheveux longs / courts","有长发 / 短发"],["se laver les cheveux","洗头"],["se couper les cheveux","剪头发"],["des cheveux frisés / raides","卷发 / 直发"]],"sy":[["chevelure","soutenu","一头秀发，较正式"],["crinière","familier","（动物的）鬃毛，口语指蓬松的头发"],["tignasse","familier","乱糟糟的头发（口语）"]],"fq":"极高频，日常常用。","me":"头发是复数：les cheveux；一根是 un cheveu。","tr":{"zh":"她留着棕色长发。","fr":"Elle a les cheveux longs et bruns.","alt":"Elle a de longs cheveux bruns.","note":"avoir les cheveux + 形容词（复数 longs、bruns）。"}},
 "L'oeil / Les yeux": {"pos":"n.m. 阳性名词，复数 yeux（不规则）","s":"眼睛。单数 un œil，复数 des yeux，不是 œils。œil 的 œ 是 o 和 e 连写。口语 Mon œil ! =「才怪！」；à vue d'œil =「肉眼可见地」。","ipa":"[œj] / [jø]","ph":"œil：œ + il 合读 [œj]；yeux：y [j] + eux [ø]，x 不发音；les yeux 要连读 [le.zjø]。","pi":"复数不规则，不能说 œils。œil 的 l 不单独读，读 [œj]；yeux 开头 y 读 [j]。","et":"拉丁语 oculus，经古法语 oel 演变；复数 yeux 是不规则形式。","ex":[["Elle a les yeux bleus.","她有一双蓝眼睛。"],["J'ai mal à l'œil droit.","我右眼疼。"],["Ferme les yeux et compte jusqu'à dix.","闭上眼睛，数到十。"]],"co":[["avoir les yeux bleus / verts / marron","有蓝 / 绿 / 棕色眼睛"],["fermer les yeux","闭上眼睛"],["un coup d'œil","瞥一眼"],["Mon œil ! (familier)","才怪！（口语）"]],"sy":[["regard","courant","目光、眼神"],["mirettes","familier","眼睛（俚语）"],["prunelle","littéraire","瞳孔、眼珠（文学）"]],"fq":"极高频，日常常用。","me":"un œil → des yeux：单数和复数完全不同的词形。","tr":{"zh":"她的眼睛是绿色的。","fr":"Elle a les yeux verts.","alt":"Elle a de beaux yeux verts.","note":"marron 作眼睛颜色时不变形；yeux 后接形容词复数。"}},
 "Midi / Le midi": {"pos":"n.m. 阳性名词，无复数","s":"中午；十二点。à midi = 中午；le midi = 每天中午吃饭的时候；le Midi（大写）= 法国南部。","ipa":"[mi.di]","ph":"m [m]；i；d [d]；i：[mi.di]。","pi":"midi 是阳性名词；说「中午」用 à midi，中间不加冠词。le Midi 大写指南法。","et":"古法语 mi di，由拉丁语 medius（中间）+ dies（日）构成。","ex":[["Il est midi.","现在是中午。"],["Le midi, je mange à la cantine.","中午我在食堂吃饭。"],["On se retrouve à midi et demi.","我们十二点半见。"]],"co":[["à midi","在中午"],["midi et demi","十二点半"],["midi pile","正好十二点"],["le Midi (de la France)","法国南部"]],"sy":[["minuit","courant","午夜（反义）"],["déjeuner","courant","午饭（déjeuner 是午餐，midi 是时间）"]],"fq":"极高频，日常常用。","me":"mi + di = 「日子的中间」。","tr":{"zh":"我们中午在咖啡馆门口见面。","fr":"On se retrouve à midi devant le café.","alt":"Rendez-vous à midi devant le café.","note":"à midi 不加冠词；半点用 midi et demi。"}},
 "Un billet / Un ticket": {"pos":"n.m. 阳性名词，复数 billets / tickets","s":"票。billet 多指火车票、飞机票、演出票，也指纸币（un billet de 20 euros）；ticket 多指小票据：地铁票（ticket de métro）、收据（ticket de caisse）。","ipa":"[bi.jɛ] / [ti.kɛ]","ph":"billet：ll 读 [j]，t 不发音，[bi.jɛ]；ticket：ck 读 [k]，t 不发音，[ti.kɛ]。","pi":"两个词结尾的 t 都不发音；billet 里的 ll 是 [j]，不是 [l]。","et":"billet：古法语 billette，意为「小字条」，来源较早；ticket：借自英语 ticket。","ex":[["J'ai acheté mes billets pour le concert de demain.","我买了明天音乐会的票。"],["Un ticket de métro, s'il vous plaît.","请给我一张地铁票。"],["Garde le ticket de caisse.","收好购物小票。"]],"co":[["un billet de train / d'avion","火车票 / 机票"],["un billet de vingt euros","一张二十欧元的纸币"],["un ticket de métro / de caisse","地铁票 / 购物小票"],["un billet aller-retour","往返票"]],"sy":[["titre de transport","soutenu","交通票据（较正式）"],["place","courant","座位、位置"],["reçu","courant","收据"]],"fq":"极高频，日常常用。","me":"billet = 大票和纸币；ticket = 小票据。","tr":{"zh":"我把火车票弄丢了。","fr":"J'ai perdu mon billet de train.","alt":"J'ai paumé mon billet de train.","note":"perdre qqch；paumer 是口语的「弄丢」。"}},
 "Un serveur / Une serveuse": {"pos":"n.m./n.f. 服务员；男 serveur，女 serveuse（复数 serveurs / serveuses）","s":"餐厅、咖啡馆的服务员。还有「服务器」的意思：un serveur informatique。叫服务员时说 S'il vous plaît, monsieur / madame，不要直接喊 Serveur !。","ipa":"[sɛʁ.vœʁ] / [sɛʁ.vøz]","ph":"er [ɛʁ]；v [v]；男性结尾 eur [œʁ]，r 要发音；女性 euse 读 [øz]。","pi":"男性 -eur 的 r 要发音；女性 -euse 的 s 读 [z]。叫人别用 Serveur !，用 Excusez-moi。","et":"来自 servir（拉丁语 servire）+ -eur / -euse。","ex":[["Le serveur est gentil.","服务员很友好。"],["La serveuse nous apporte la carte.","女服务员给我们拿来菜单。"],["Il travaille comme serveur dans un café.","他在咖啡馆当服务员。"]],"co":[["appeler le serveur","叫服务员"],["travailler comme serveur / serveuse","当服务员"],["S'il vous plaît, monsieur / madame !","劳驾，先生 / 女士！"],["un serveur informatique","服务器"]],"sy":[["garçon","courant","（旧式）服务员，现在叫人不用"],["barman","courant","酒吧调酒师"],["maître d'hôtel","soutenu","餐厅领班（较正式）"]],"fq":"高频，餐厅常用。","me":"servir（服务）+ -eur：服务的人。","tr":{"zh":"女服务员给我们拿来菜单。","fr":"La serveuse nous apporte la carte.","alt":"La serveuse vient avec la carte.","note":"carte = 菜单（逐项点菜）；menu = 套餐。"}},
 "Une / De la barbe": {"pos":"n.f. 阴性名词，复数 barbes","s":"胡子（下巴上的）。une barbe = 一把胡子；avoir de la barbe = 有胡茬、留着胡子（泛指）。口语 La barbe ! =「烦死了！」；la barbe à papa = 棉花糖。","ipa":"[baʁb]","ph":"b [b]；a [a]；r [ʁ]；b [b]；结尾 e 不发音。","pi":"两个 b 都要发音：[baʁb]；是阴性名词 la barbe，虽然指男人的胡子。","et":"拉丁语 barba（胡子）。","ex":[["Il a une barbe.","他留着胡子。"],["Mon père a une grande barbe blanche.","我爸爸留着一把白色大胡子。"],["Il se rase la barbe tous les matins.","他每天早上刮胡子。"]],"co":[["se raser / se faire la barbe","刮胡子"],["une barbe de trois jours","三天没刮的胡茬"],["la barbe à papa","棉花糖"],["La barbe ! (familier)","烦死了！（口语）"]],"sy":[["bouc","courant","山羊胡"],["favoris","courant","鬓角"],["moustache","courant","小胡子"]],"fq":"中频。","me":"la barbe：阴性，两个 b 都读。","tr":{"zh":"我爸爸的胡子全白了。","fr":"Mon père a la barbe toute blanche.","alt":"Mon père a une barbe blanche.","note":"porter la barbe = 留胡子；胡子用 la barbe。"}},
 "Une / De la moustache": {"pos":"n.f. 阴性名词，复数 moustaches","s":"小胡子（上唇的胡子）。也用于猫的胡须：les moustaches du chat。用单数 une moustache 指一撮小胡子，复数 des moustaches 常指猫须。","ipa":"[mus.taʃ]","ph":"ou [u]；s 发音 [s]；t [t]；ch [ʃ]；结尾 e 不发音：[mus.taʃ]。","pi":"s 要读出来 [s]；是阴性 la moustache；不要和 barbe（下巴上的胡子）搞混。","et":"借自意大利语 mostaccio，16 世纪。","ex":[["Il a une moustache.","他留着小胡子。"],["Le chat a de longues moustaches.","猫有长长的胡须。"],["Mon oncle porte la moustache.","我叔叔留小胡子。"]],"co":[["porter la moustache","留小胡子"],["se raser la moustache","刮掉小胡子"],["les moustaches du chat","猫的胡须"],["une moustache grise","灰色的小胡子"]],"sy":[["barbe","courant","下巴的胡子"],["bouc","courant","山羊胡"]],"fq":"中频。","me":"mous + tache：想成 tache（斑点）一样粘在嘴上的小胡子。","tr":{"zh":"我叔叔留小胡子已经二十年了。","fr":"Ça fait vingt ans que mon oncle porte la moustache.","alt":"Mon oncle a la moustache depuis vingt ans.","note":"Ça fait + 时间 + que = 已经……了。"}},
 "Accoucher": {"pos":"v.i. 不及物动词，第一组，助动词 avoir","s":"生孩子；分娩。后面加 d'un garçon / d'une fille 表示生了谁：accoucher d'un garçon。口语 Alors, accouche ! =「快说吧！」。","ipa":"[a.ku.ʃe]","ph":"cc 读一个 [k]；ou [u]；ch [ʃ]；er [e]：[a.ku.ʃe]。","pi":"双 c 只读一个 [k]；accoucher 通常不直接带宾语，用 accoucher de + 孩子。","et":"来自 à + coucher（躺下），所以是「躺下待产」的说法。同源：couche、se coucher。","ex":[["Elle va accoucher bientôt.","她很快就要生了。"],["Elle a accouché d'une petite fille hier.","她昨天生了个女儿。"],["Il faut aller à l'hôpital pour accoucher.","生孩子要去医院。"]],"co":[["accoucher d'un garçon / d'une fille","生了个男孩 / 女孩"],["accoucher à l'hôpital","在医院生产"],["accoucher à la maison","在家里生产"],["Alors, accouche ! (familier)","快说吧！（口语）"]],"sy":[["donner naissance (à)","soutenu","生下（较正式）"],["mettre au monde","courant","生下，使出世"],["enfanter","littéraire","生育（文学）"]],"fq":"中频。","me":"accoucher = à + coucher：躺下把孩子生出来。","tr":{"zh":"我姐姐五月份要生孩子。","fr":"Ma sœur va accoucher en mai.","alt":"Ma sœur doit accoucher en mai.","note":"aller + 不定式 = 即将；devoir + 不定式 = 预产期在。"}},
 "Allumer": {"pos":"v.t. 及物动词，第一组，助动词 avoir","s":"打开（灯、电视、电脑）；点燃（火、蜡烛、香烟）。反义词是 éteindre。在法国，灯和电器用 allumer，不用 ouvrir。","ipa":"[a.ly.me]","ph":"a [a]；ll 在这里读 [l]；u [y]；m；er [e]：[a.ly.me]。","pi":"u 读 [y]（嘴唇圆，像「于」），不是 ou；ll 读 [l]，不是 [j]。灯和电器用 allumer，门窗用 ouvrir。","et":"来自 lumière 一族（拉丁语 lumen「光」）。同源：lumière、illuminer。","ex":[["J'allume la lumière.","我开灯。"],["Tu peux allumer la télé ?","你能开一下电视吗？"],["Il allume une bougie.","他点了一支蜡烛。"]],"co":[["allumer la lumière / la télé","开灯 / 开电视"],["allumer l'ordinateur","开电脑"],["allumer le feu / une bougie","生火 / 点蜡烛"],["allumer le chauffage","开暖气"]],"sy":[["mettre","courant","打开、开启（常说 mettre la télé）"],["enclencher","soutenu","启动（机械，较正式）"],["éteindre","courant","关闭（反义）"]],"fq":"高频，日常常用。","me":"allumer ← lumière：让它有「光」。","tr":{"zh":"开灯吧，天黑了。","fr":"Allume la lumière, il fait noir.","alt":"Tu peux allumer la lumière ? On n'y voit rien.","note":"命令式 allume（-er 动词的 tu 命令式不加 s）。"}},
 "Changer": {"pos":"v.t./v.i. 第一组，助动词 avoir","s":"改变；更换；换。changer de + 名词 = 换（不带冠词）：changer de voiture（换车）、changer d'avis（改变主意）；changer + 名词 = 把……改了、更换。也可指换车换乘、兑换货币。","ipa":"[ʃɑ̃.ʒe]","ph":"ch [ʃ]；an [ɑ̃]；g 在 e 前读 [ʒ]；er [e]：[ʃɑ̃.ʒe]。","pi":"nous changeons 要保留 e，保持 [ʒ] 的音；changer de 后面不加冠词：changer de voiture，不是 changer la voiture（那是「改装这辆车」）。","et":"晚期拉丁语 cambiare（交换），可能源自高卢语。同源：échanger、change。","ex":[["Je veux changer de voiture.","我想换辆车。"],["Il a changé d'avis.","他改变了主意。"],["Il faut changer de train à Lyon.","你得在里昂换乘。"]],"co":[["changer de voiture / d'avis","换车 / 改变主意"],["changer de l'argent","换钱、兑换货币"],["se changer (mettre d'autres vêtements)","换衣服"],["changer d'air","换个环境"]],"sy":[["modifier","courant","修改"],["remplacer","courant","代替、更换"],["échanger","courant","交换"]],"fq":"极高频，日常常用。","me":"changer de + 名词：换成另一个。","tr":{"zh":"我改主意了。","fr":"J'ai changé d'avis.","alt":"Finalement, j'ai changé d'avis.","note":"changer d'avis = 改主意，de 后不加冠词。"}},
 "Devoir": {"pos":"v.t. 不规则动词，助动词 avoir，过去分词 dû","s":"必须；应该（devoir + 不定式）；欠（devoir + 名词：Je te dois 10 euros）；也表示推测：Il doit être là =「他应该在那里」。名词 les devoirs = 作业。","ipa":"[də.vwaʁ]","ph":"d [d]；e [ə]；oi [wa]；r [ʁ] 要发音：[də.vwaʁ]。","pi":"变位不规则：je dois, tu dois, il doit, nous devons, ils doivent。dois、doit 的 s、t 不发音；doivent 读 [dwav]。过去分词 dû。","et":"拉丁语 debere。同源：dette（债）、dû。","ex":[["Je dois aller au consulat demain.","我明天得去领事馆。"],["Tu dois te reposer.","你得休息。"],["Je te dois dix euros.","我欠你十欧元。"]],"co":[["devoir faire qqch","必须做某事"],["devoir de l'argent à qqn","欠某人钱"],["faire ses devoirs","做作业"],["Il doit être tard.","应该已经很晚了"]],"sy":[["falloir","courant","必须（il faut）"],["être obligé de","courant","不得不"],["avoir à","soutenu","要（较正式）"]],"fq":"极高频，日常常用。","me":"devoir：必须、欠、应该，三个意思。","tr":{"zh":"我得在六点前走。","fr":"Je dois partir avant six heures.","alt":"Il faut que je parte avant six heures.","note":"Il faut que + 虚拟式；devoir + 不定式更简单。"}},
 "Partir": {"pos":"v.i. 不规则动词，第三组，助动词 être","s":"离开；出发。partir en vacances = 去度假；partir de = 从……离开；partir pour / à = 前往。à partir de = 从……起。C'est parti ! =「开始吧！」。","ipa":"[paʁ.tiʁ]","ph":"ar [aʁ]；t [t]；ir [iʁ]，结尾 r 要发音：[paʁ.tiʁ]。","pi":"单数变位不发 t：je pars, tu pars, il part（[paʁ]）；复合时态助动词用 être：je suis parti(e)。partir 后面不带宾语直接加地点用 pour / à，离开某地用 partir de。","et":"拉丁语 partire「分开」，古法语里「分开」演变成「离开」。同源：départ、part。","ex":[["Je pars en vacances.","我去度假。"],["Le train part à huit heures.","火车八点开。"],["Elle est partie hier.","她昨天走了。"]],"co":[["partir en vacances / en voyage","去度假 / 去旅行"],["partir pour Paris / à Paris","前往巴黎"],["à partir de demain","从明天起"],["C'est parti !","出发！开始！"]],"sy":[["quitter","courant","离开（及物）"],["s'en aller","courant","走开"],["filer","familier","溜走（口语）"]],"fq":"极高频，日常常用。","me":"pars / part：t 不发音；复合过去时用 être。","tr":{"zh":"我们明天去度假。","fr":"Nous partons en vacances demain.","alt":"On part en vacances demain.","note":"on = nous（口语）；助动词 être：Nous sommes partis。"}},
 "Pleurer": {"pos":"v.i./v.t. 第一组，助动词 avoir","s":"哭；流泪。pleurer de joie = 高兴得哭；pleurer sur = 为……叹息；pleurer qqn = 为某人逝去而哀悼。","ipa":"[plœ.ʁe]","ph":"pl [pl]；eu [œ]；r [ʁ]；er [e]：[plœ.ʁe]。","pi":"pleurer（哭）和 pleuvoir（下雨）开头一样：il pleure 是「他哭」，il pleut 是「下雨」。eu 读 [œ]，嘴唇略圆。","et":"拉丁语 plorare。同源：déplorer、implorer。","ex":[["Le bébé pleure.","宝宝在哭。"],["Elle pleure de joie.","她高兴得哭了。"],["Ne pleure pas, ça va aller.","别哭，会好起来的。"]],"co":[["pleurer de joie / de rire","高兴得哭 / 笑到流泪"],["pleurer à chaudes larmes","痛哭流涕"],["fondre en larmes","泪流满面"],["pleurer sur son sort","自怨自艾"]],"sy":[["sangloter","soutenu","抽泣"],["chialer","familier","哭（口语）"],["verser des larmes","littéraire","流泪（文学）"]],"fq":"高频，日常常用。","me":"pleurer 哭，pleuvoir 下雨：il pleure ≠ il pleut。","tr":{"zh":"别哭，没什么大不了的。","fr":"Ne pleure pas, ce n'est pas grave.","alt":"Pleure pas, c'est pas grave.","note":"否定命令式 Ne pleure pas；口语常省略 ne。"}},
 "Proposer": {"pos":"v.t. 第一组，助动词 avoir","s":"提议；建议；提供。proposer qqch à qqn = 向某人提议某事；proposer de + 不定式 = 提议做某事。商店和餐厅也说 proposer 来表示「供应」。","ipa":"[pʁɔ.pɔ.ze]","ph":"pr [pʁ]；o [ɔ]；p；o [ɔ]；s 在两个元音之间读 [z]；er [e]：[pʁɔ.pɔ.ze]。","pi":"s 读 [z]，不是 [s]。proposer 不等于「求婚」，求婚说 demander en mariage。","et":"pro-（向前）+ poser（放置）。同源：proposition、poser。","ex":[["Je propose une idée.","我提一个想法。"],["Il nous propose de dîner ensemble.","他提议我们一起吃晚饭。"],["Le restaurant propose un menu à quinze euros.","这家餐厅有十五欧元的套餐。"]],"co":[["proposer qqch à qqn","向某人提议某事"],["proposer de + infinitif","提议做某事"],["proposer son aide","提出帮忙"],["Je te propose de...","我提议……"]],"sy":[["suggérer","courant","建议"],["offrir","courant","提供"],["soumettre","soutenu","提交（较正式）"]],"fq":"高频，日常常用。","me":"pro + poser：把想法「放到前面」。","tr":{"zh":"我提议一起去看电影。","fr":"Je te propose d'aller au cinéma.","alt":"Ça te dit d'aller au cinéma ?","note":"proposer à qqn de + 不定式。"}},
 "Rentrer": {"pos":"v.i./v.t. 第一组；不及物用助动词 être，及物用 avoir","s":"回家；回来；再进去。rentrer chez soi = 回家；rentrer du travail = 下班回家。及物时是「把……拿进来」：rentrer le linge。rentrer dans = 撞上。","ipa":"[ʁɑ̃.tʁe]","ph":"r [ʁ]；en [ɑ̃]；tr [tʁ]；er [e]：[ʁɑ̃.tʁe]。","pi":"不及物时助动词用 être：je suis rentré(e)；及物时用 avoir：j'ai rentré la voiture。回家不需要 à：rentrer chez moi。","et":"re- + entrer（拉丁语 intrare）。同源：rentrée、entrer。","ex":[["Je rentre à la maison.","我回家。"],["À quelle heure tu rentres ce soir ?","你今晚几点回家？"],["Il est rentré tard hier.","他昨天很晚才回来。"]],"co":[["rentrer chez soi / à la maison","回家"],["rentrer du travail / de l'école","下班 / 放学回家"],["rentrer tard","很晚才回家"],["rentrer dans (un mur)","撞上（墙）"]],"sy":[["revenir","courant","回来"],["retourner","courant","回去"],["regagner","soutenu","回到（较正式）"]],"fq":"极高频，日常常用。","me":"rentrer = re + entrer：再进门 = 回家。","tr":{"zh":"我六点回家。","fr":"Je rentre à la maison à six heures.","alt":"Je rentre chez moi vers six heures.","note":"助动词 être：je suis rentré。"}},
 "Rire": {"pos":"v.i. 不规则动词，第三组，助动词 avoir，过去分词 ri","s":"笑。rire de qqn = 嘲笑某人；rire aux éclats = 大笑；pour rire = 开玩笑、不当真。名词 le rire = 笑声。","ipa":"[ʁiʁ]","ph":"r [ʁ]；i；r [ʁ]：[ʁiʁ]，两个 r 都发音。","pi":"中国学习者容易把 rire（笑）和 lire（读）弄混：r / l 要分开。变位不规则：je ris, tu ris, il rit, nous rions, ils rient。","et":"拉丁语 ridere。同源：ridicule、risible。","ex":[["Nous aimons rire.","我们爱笑。"],["Il rit tout le temps.","他总是笑个不停。"],["Elle a ri aux éclats.","她哈哈大笑。"]],"co":[["rire aux éclats","哈哈大笑"],["rire de qqn / qqch","笑某人 / 笑某事"],["éclater de rire","爆笑"],["pour rire","开玩笑的"]],"sy":[["rigoler","familier","笑（口语）"],["s'esclaffer","soutenu","放声大笑（较正式）"],["sourire","courant","微笑"]],"fq":"高频，日常常用。","me":"rire（笑）≠ lire（读）：r 和 l 要分清。","tr":{"zh":"他总是逗我们笑。","fr":"Il nous fait toujours rire.","alt":"Il nous fait tout le temps rigoler.","note":"faire rire qqn = 逗某人笑。"}},
 "S'asseoir": {"pos":"v.pr. 代词式动词，不规则，助动词 être，过去分词 assis","s":"坐下（动作）。表示「坐着」（状态）用 être assis(e)。Asseyez-vous = 请坐。","ipa":"[sa.swaʁ]","ph":"s'a [sa]；ss [s]；eoi 读 [wa]，其中 e 不发音：[sa.swaʁ]。","pi":"asseoir 中的 e 不发音。变位有两种：je m'assois / je m'assieds，nous nous asseyons / nous assoyons。过去分词 assis 要配合主语：elle s'est assise。","et":"拉丁语 assidere（ad + sedere）。同源：sédentaire、session、assidu。","ex":[["Je m'assois sur la chaise.","我坐在椅子上。"],["Asseyez-vous, je vous en prie.","请坐。"],["Elle s'est assise près de la fenêtre.","她坐在窗边。"]],"co":[["s'asseoir sur une chaise / par terre","坐在椅子上 / 坐在地上"],["Asseyez-vous !","请坐！"],["être assis(e)","坐着（状态）"],["faire asseoir qqn","让某人坐下"]],"sy":[["se poser","familier","坐下（口语）"],["prendre place","soutenu","就座（较正式）"],["s'installer","courant","安顿下来、坐好"]],"fq":"高频，日常常用。","me":"s'asseoir 是动作；être assis 是状态。","tr":{"zh":"坐吧，别客气。","fr":"Assieds-toi, je t'en prie.","alt":"Assois-toi, vas-y.","note":"命令式反身动词：Assieds-toi（toi 放在动词后）。"}},
 "S'endormir": {"pos":"v.pr. 代词式动词，不规则，助动词 être","s":"入睡；睡着。s'endormir 是「从醒到睡」的动作；dormir 是「在睡着」。也可指肢体发麻：Ma jambe s'endort。","ipa":"[sɑ̃.dɔʁ.miʁ]","ph":"s'en [sɑ̃]；dor [dɔʁ]；mir [miʁ]。","pi":"变位像 dormir：je m'endors, tu t'endors, il s'endort（t 不发音），nous nous endormons。复合时态助动词用 être：je me suis endormi(e)。","et":"en-（进入）+ dormir（拉丁语 dormire）。同源：dortoir。","ex":[["Je m'endors vite.","我很快就睡着。"],["Le bébé s'est endormi dans mes bras.","宝宝在我怀里睡着了。"],["Je m'endors devant la télé.","我在电视前睡着了。"]],"co":[["s'endormir tard / vite","很晚才睡着 / 很快睡着"],["s'endormir devant la télé","在电视前睡着"],["avoir du mal à s'endormir","难以入睡"],["s'endormir comme une masse","睡得像死猪"]],"sy":[["s'assoupir","soutenu","打盹（较正式）"],["piquer du nez","familier","打瞌睡（口语）"],["se réveiller","courant","醒来（反义）"]],"fq":"高频，日常常用。","me":"s'endormir（睡着）≠ dormir（在睡）。","tr":{"zh":"晚上我很难入睡。","fr":"J'ai du mal à m'endormir le soir.","alt":"Le soir, je n'arrive pas à m'endormir.","note":"avoir du mal à + 不定式 = 很难做某事。"}},
 "S'étirer": {"pos":"v.pr. 代词式动词，第一组，助动词 être","s":"伸懒腰；伸展身体。也可指事物拉长：Le temps s'étire（时间被拉长）。名词 un étirement = 拉伸动作。","ipa":"[se.ti.ʁe]","ph":"s'é [se]；ti [ti]；r [ʁ]；er [e]：[se.ti.ʁe]。","pi":"ti 读 [ti]，不是 [si]。代词式：je m'étire, tu t'étires, il s'étire。别和 tirer（拉、射击）搞混。","et":"é-（向外）+ tirer（拉）。同源：tirer、étirement。","ex":[["Le chat s'étire.","猫在伸懒腰。"],["Je m'étire quand je me lève.","我起床时伸个懒腰。"],["Elle s'étire au soleil.","她在阳光下伸懒腰。"]],"co":[["s'étirer les jambes / les bras","伸展腿 / 手臂"],["s'étirer au soleil","在阳光下伸展"],["faire des étirements","做拉伸运动"],["s'étirer en longueur","拖得很长"]],"sy":[["s'allonger","courant","躺下"],["se dégourdir","courant","活动活动腿脚"],["bâiller","courant","打哈欠"]],"fq":"中频。","me":"é + tirer：把身体向外「拉长」。","tr":{"zh":"每天早上我的猫都会伸个长长的懒腰。","fr":"Le matin, mon chat s'étire longuement.","alt":"Chaque matin, mon chat s'étire avant de manger.","note":"代词式动词：mon chat s'étire。"}},
 "S'habiller": {"pos":"v.pr. 代词式动词，第一组，助动词 être","s":"穿衣服；穿着（某种风格）。s'habiller en noir = 穿黑色；s'habiller chic = 穿得讲究。及物时是「给……穿衣」：habiller un enfant。","ipa":"[sa.bi.je]","ph":"s'ha [sa]（h 不发音）；bi；ill 读 [j]；er [e]：[sa.bi.je]。","pi":"h 不发音，要省音：je m'habille；ill 读 [j]，不是 [l]。「穿衣服」整体用 s'habiller，穿某一件用 mettre。","et":"与 habit（衣服）同族。同源：déshabiller。","ex":[["Je m'habille pour sortir.","我穿好衣服出门。"],["Habille-toi, on part dans cinq minutes !","快穿衣服，我们五分钟后走！"],["Elle s'habille toujours en noir.","她总是穿黑色。"]],"co":[["s'habiller en noir / en rouge","穿黑色 / 红色"],["s'habiller chic / décontracté","穿得讲究 / 随意"],["s'habiller pour sortir","穿好衣服出门"],["habiller un enfant","给孩子穿衣"]],"sy":[["se vêtir","littéraire","穿衣（文学）"],["se changer","courant","换衣服"],["se déshabiller","courant","脱衣服（反义）"]],"fq":"高频，日常常用。","me":"s'habiller：穿整身衣服；mettre：穿一件。","tr":{"zh":"快点穿衣服，我们要迟到了。","fr":"Habille-toi vite, on va être en retard.","alt":"Dépêche-toi de t'habiller, on va être en retard.","note":"命令式反身动词：Habille-toi；Dépêche-toi de + 不定式。"}},
 "Se brosser les dents": {"pos":"v.pr. 代词式动词，第一组，助动词 être","s":"刷牙。se brosser les cheveux = 梳头；口语 Tu peux te brosser ! =「你别想了！」。身体部位前用 les，不用 mes。","ipa":"[sə.bʁɔ.se.le.dɑ̃]","ph":"se [sə]；br [bʁ]；o [ɔ]；ss [s]；er [e]；les dents [le dɑ̃]，dents 结尾 -ents 读 [ɑ̃]，t、s 不发音。","pi":"身体部位前用 les：Je me brosse les dents，不说 mes dents。dents 的 -ents 不发音，读 [dɑ̃]。","et":"来自 brosse（刷子）。brosse 本身的来源不太确定。","ex":[["Je me brosse les dents.","我刷牙。"],["Brosse-toi les dents avant de dormir !","睡前去刷牙！"],["Il se brosse les dents trois fois par jour.","他一天刷三次牙。"]],"co":[["une brosse à dents","牙刷"],["le dentifrice","牙膏"],["se brosser les cheveux","梳头"],["Tu peux te brosser ! (familier)","想得美！（口语）"]],"sy":[["se laver les dents","courant","洗牙（较口语的说法）"],["se brosser","familier","（口语）别想了，没你的份"]],"fq":"高频，日常常用。","me":"身体部位前用 les：me brosse les dents。","tr":{"zh":"晚饭后我刷牙。","fr":"Je me brosse les dents après le dîner.","alt":"Après le dîner, je me lave les dents.","note":"身体部位前用 les 而不是 mes。"}},
 "Se coiffer": {"pos":"v.pr. 代词式动词，第一组，助动词 être","s":"梳头；整理发型。coiffer qqn = 给某人做头发；se faire coiffer = 请人做头发。名词：un coiffeur / une coiffeuse = 理发师；une coiffure = 发型。","ipa":"[sə.kwa.fe]","ph":"se [sə]；c [k]；oi [wa]；ff 读一个 [f]；er [e]：[sə.kwa.fe]。","pi":"oi 读 [wa]；ff 只读一个 f。se coiffer 不一定用梳子，指整理发型的整个动作。","et":"与 coiffe（头饰、帽）同族。同源：coiffeur、coiffure。","ex":[["Je me coiffe.","我梳头。"],["Elle se coiffe devant le miroir.","她在镜子前梳头。"],["Il se coiffe avec du gel.","他用发胶梳头。"]],"co":[["se coiffer devant le miroir","在镜子前梳头"],["se faire coiffer","请人做头发"],["un coiffeur / une coiffeuse","理发师"],["une coiffure","发型"]],"sy":[["se peigner","courant","梳头（用梳子）"],["se brosser les cheveux","courant","用刷子梳头"]],"fq":"中频。","me":"se coiffer：coiffe 是头饰，头上的事。","tr":{"zh":"她出门前梳头。","fr":"Elle se coiffe avant de partir.","alt":"Elle se coiffe avant de sortir.","note":"se coiffer 不及物；coiffer qqn 是替别人梳头。"}},
 "Se coucher": {"pos":"v.pr. 代词式动词，第一组，助动词 être","s":"上床睡觉；躺下；（太阳）落山。se coucher tard = 睡得晚。le coucher du soleil = 日落。别和 dormir（睡着）混淆。","ipa":"[sə.ku.ʃe]","ph":"se [sə]；c [k]；ou [u]；ch [ʃ]；er [e]：[sə.ku.ʃe]。","pi":"se coucher 是「上床 / 躺下」的动作，不是「睡着」。ou 读 [u]；复合时态助动词用 être：je me suis couché(e)。","et":"拉丁语 collocare（放置），经 colcher 演变成 coucher。","ex":[["Je me couche tard.","我睡得很晚。"],["Les enfants se couchent à huit heures.","孩子们八点睡觉。"],["Le soleil se couche vers neuf heures en été.","夏天太阳九点左右落山。"]],"co":[["se coucher tôt / tard","早睡 / 晚睡"],["aller se coucher","去睡觉"],["le coucher du soleil","日落"],["se coucher par terre","躺在地上"]],"sy":[["aller au lit","courant","上床"],["s'allonger","courant","躺下"],["se pieuter","familier","睡觉（口语）"]],"fq":"极高频，日常常用。","me":"se coucher = 上床；se lever = 起床。","tr":{"zh":"今晚我早点睡。","fr":"Ce soir, je me couche tôt.","alt":"Ce soir, je vais au lit de bonne heure.","note":"tôt / tard 修饰：se coucher tôt。"}},
 "Se laver": {"pos":"v.pr. 代词式动词，第一组，助动词 être","s":"洗（自己）；洗澡。se laver les mains = 洗手；se laver les cheveux = 洗头。洗别的东西是 laver：laver la voiture。","ipa":"[sə.la.ve]","ph":"se [sə]；l；a [a]；v [v]；er [e]：[sə.la.ve]。","pi":"洗自己的身体部位用 les：Je me lave les mains，不说 mes mains。命令式：Lave-toi。","et":"拉丁语 lavare。同源：lavabo、lavande。","ex":[["Je me lave les mains.","我洗手。"],["Lave-toi les mains avant de manger !","吃饭前先洗手！"],["Il se lave tous les matins.","他每天早上洗澡。"]],"co":[["se laver les mains / les cheveux / les dents","洗手 / 洗头 / 刷牙"],["un lavabo","洗手池"],["se laver à l'eau froide","用冷水洗"],["se laver avant de dîner","晚饭前洗洗"]],"sy":[["faire sa toilette","courant","洗漱"],["prendre une douche","courant","冲个澡"],["se débarbouiller","familier","洗把脸（口语）"]],"fq":"极高频，日常常用。","me":"se laver：自己洗自己，加 se。","tr":{"zh":"吃饭前先洗手。","fr":"Lave-toi les mains avant de manger.","alt":"Va te laver les mains avant de manger.","note":"身体部位用 les；laver qqch 是洗东西。"}},
 "Se lever": {"pos":"v.pr. 代词式动词，第一组，助动词 être","s":"起床；站起来；（太阳）升起。se lever tôt = 早起。le lever du soleil = 日出。se lever du pied gauche =「起床气」，一整天不顺。","ipa":"[sə.lə.ve]","ph":"se [sə]；l；e [ə]（常省略）；v；er [e]：[sə.lə.ve]。","pi":"重读时拼写会变：je me lève, tu te lèves, il se lève, ils se lèvent，nous nous levons。注意 se lever（起床）≠ se réveiller（醒来）。","et":"拉丁语 levare（抬起），源自 levis（轻）。同源：élever、lever。","ex":[["Je me lève vite.","我起床很快。"],["À quelle heure tu te lèves ?","你几点起床？"],["Levez-vous, s'il vous plaît.","请站起来。"]],"co":[["se lever tôt / tard","早起 / 晚起"],["se lever du pied gauche","起床气（字面：左脚先下床）"],["le lever du soleil","日出"],["se lever de table","离开饭桌"]],"sy":[["sortir du lit","courant","起床"],["se mettre debout","courant","站起来"],["se réveiller","courant","醒来（不等于起床）"]],"fq":"极高频，日常常用。","me":"se lever ← levare：「抬起自己」= 起床。","tr":{"zh":"明天我六点起床。","fr":"Demain, je me lève à six heures.","alt":"Demain, je dois me lever à six heures.","note":"devoir + se lever：Je dois me lever。"}},
 "Se maquiller": {"pos":"v.pr. 代词式动词，第一组，助动词 être","s":"化妆。名词：le maquillage = 化妆品、妆容。maquiller 也可指「篡改」：maquiller les chiffres（做假账）。反义：se démaquiller（卸妆）。","ipa":"[sə.ma.ki.je]","ph":"se [sə]；ma；qui 读 [ki]（qu = [k]）；ill 读 [j]；er [e]：[sə.ma.ki.je]。","pi":"qu 读 [k]；ill 读 [j]，不是 [l]。注意 se maquiller 是反身，maquiller qqn 是替别人化妆。","et":"来源不太确定；同族词：maquillage、maquilleur。","ex":[["Elle se maquille.","她在化妆。"],["Je me maquille les yeux avec du mascara.","我用睫毛膏化眼妆。"],["Elle se maquille avant d'aller au travail.","她上班前化妆。"]],"co":[["se maquiller les yeux","化眼妆"],["du maquillage","化妆品、妆"],["se démaquiller","卸妆"],["maquiller les chiffres","做假账"]],"sy":[["se farder","soutenu","化妆（较正式）"],["se démaquiller","courant","卸妆（反义）"]],"fq":"中频。","me":"se maquiller：qu = [k]，ill = [j]。","tr":{"zh":"她去上班前化妆。","fr":"Elle se maquille avant d'aller travailler.","alt":"Avant d'aller au travail, elle se maquille un peu.","note":"aller + 不定式；avant de + 不定式。"}},
 "Se préparer": {"pos":"v.pr. 代词式动词，第一组，助动词 être","s":"准备好；做好准备。se préparer pour + 名词 = 为……做准备；se préparer à + 不定式 / 名词 = 准备好做某事。préparer qqch 是准备某物：préparer le dîner。","ipa":"[sə.pʁe.pa.ʁe]","ph":"se [sə]；pré [pʁe]；pa [pa]；rer [ʁe]：[sə.pʁe.pa.ʁe]。","pi":"三个音节都不难，注意 pré 读 [pʁe]，é 带重音符；se préparer（准备自己）和 préparer（准备东西）要分开。","et":"拉丁语 praeparare（prae- 在前 + parare 准备）。同源：préparation、prêt。","ex":[["Elle se prépare.","她在准备。"],["Je me prépare pour la fête.","我在为聚会做准备。"],["Prépare-toi, on part dans dix minutes.","快准备好，十分钟后出发。"]],"co":[["se préparer à partir","准备出发"],["se préparer pour un entretien","为面试做准备"],["se préparer au pire","做好最坏的打算"],["être prêt(e)","准备好了"]],"sy":[["s'apprêter","soutenu","准备（较正式，常指即将做某事）"],["s'organiser","courant","安排好自己"],["se tenir prêt","courant","随时待命"]],"fq":"高频，日常常用。","me":"préparer + se：准备好自己。","tr":{"zh":"我在为今晚的聚会做准备。","fr":"Je me prépare pour la fête de ce soir.","alt":"Je suis en train de me préparer pour la fête de ce soir.","note":"être en train de + 不定式 = 正在做。"}},
 "Se reposer": {"pos":"v.pr. 代词式动词，第一组，助动词 être","s":"休息；放松。se reposer sur qqn = 依靠某人。名词 le repos = 休息。「休息」说 se reposer；「放松」说 se détendre。","ipa":"[sə.ʁə.po.ze]","ph":"se [sə]；re [ʁə]；po [po]；s 在元音间读 [z]；er [e]：[sə.ʁə.po.ze]。","pi":"s 读 [z]，不是 [s]：[ʁə.po.ze]。se reposer sur 是「依赖」，不是「休息在……上」。","et":"re- + poser（拉丁语 pausare「停止」）。同源：repos、pause、poser。","ex":[["Je me repose le dimanche.","我星期天休息。"],["Repose-toi, tu as l'air fatigué.","好好休息，你看起来很累。"],["Tu peux te reposer sur moi.","你可以信赖我。"]],"co":[["se reposer un peu","休息一会儿"],["se reposer sur qqn","依靠某人"],["un moment de repos","休息时间"],["Repose-toi bien !","好好休息！"]],"sy":[["se détendre","courant","放松"],["souffler","familier","喘口气（口语）"],["faire une pause","courant","休息一下"]],"fq":"高频，日常常用。","me":"re + poser：再次「停下来放好」。","tr":{"zh":"星期天我在家休息。","fr":"Le dimanche, je me repose à la maison.","alt":"Le dimanche, je ne fais rien, je me repose.","note":"se reposer sur qqn = 依靠某人。"}},
 "Se retrouver": {"pos":"v.pr. 代词式动词，第一组，助动词 être","s":"碰面；重聚（互相）：On se retrouve au café = 我们在咖啡馆见。还可指「发现自己处于……」：Je me suis retrouvé seul = 我发现只剩我一个人。名词 les retrouvailles = 重逢。","ipa":"[sə.ʁə.tʁu.ve]","ph":"se [sə]；re [ʁə]；tr [tʁ]；ou [u]；v；er [e]：[sə.ʁə.tʁu.ve]。","pi":"互相的动作用 se：on se retrouve = 我们互相找到、碰面。retrouver qqn 是「找回某人」，se retrouver 是「大家碰头」。","et":"re- + trouver（找到）。同源：retrouvailles。","ex":[["On se retrouve au café.","我们在咖啡馆见。"],["On se retrouve devant la gare à huit heures.","我们八点在车站前面碰头。"],["Je me suis retrouvé seul à la maison.","我发现自己一个人在家。"]],"co":[["On se retrouve où ?","我们在哪里碰头？"],["se retrouver chez qqn","在某人家重聚"],["se retrouver seul / sans argent","落得孤身一人 / 身无分文"],["les retrouvailles","重逢"]],"sy":[["se rejoindre","courant","会合"],["se voir","courant","见面"],["se donner rendez-vous","courant","约好见面"]],"fq":"高频，日常常用。","me":"re + trouver：再次找到彼此 = 碰面。","tr":{"zh":"我们八点在电影院门口见。","fr":"On se retrouve devant le cinéma à huit heures.","alt":"Rendez-vous devant le cinéma à huit heures.","note":"on = nous（口语）；互相：on se retrouve。"}},
 "Se réveiller": {"pos":"v.pr. 代词式动词，第一组，助动词 être","s":"醒来。réveiller qqn = 叫醒某人；un réveil = 闹钟。se réveiller（醒来）和 se lever（起床）是两件事。","ipa":"[sə.ʁe.ve.je]","ph":"se [sə]；ré [ʁe]；v；ill 读 [j]；er [e]：[sə.ʁe.ve.je]。","pi":"ill 读 [j]，不是 [l]；se réveiller 只是「醒」，不一定起床。复合时态助动词用 être。","et":"re- + éveiller；同族：réveil、éveil、veiller。","ex":[["Je me réveille à sept heures.","我七点醒来。"],["Le bébé se réveille souvent la nuit.","宝宝晚上经常醒。"],["Il s'est réveillé en pleine nuit.","他半夜醒了。"]],"co":[["se réveiller tôt / en retard","早醒 / 睡过头"],["réveiller qqn","叫醒某人"],["un réveil / un réveille-matin","闹钟"],["se réveiller en sursaut","惊醒"]],"sy":[["s'éveiller","littéraire","苏醒（文学）"],["se lever","courant","起床（不等于醒）"],["ouvrir l'œil","familier","睁开眼睛（口语）"]],"fq":"高频，日常常用。","me":"réveil = 闹钟，也是「醒来」。","tr":{"zh":"我每天七点左右醒来。","fr":"Je me réveille vers sept heures chaque jour.","alt":"Tous les jours, je me réveille vers sept heures.","note":"vers + 时间 = 大约。"}},
 "Voler": {"pos":"v.i./v.t. 第一组，助动词 avoir","s":"飞；偷。voler dans le ciel = 在天上飞；voler qqch à qqn = 偷某人的东西。名词：un voleur = 小偷，un vol = 飞行 / 盗窃。靠上下文区分两个意思。","ipa":"[vɔ.le]","ph":"v；o [ɔ]；l；er [e]：[vɔ.le]。","pi":"同一个动词有两个意思：「飞」和「偷」，要看有没有宾语（voler un portable = 偷手机；voler = 飞）。un vol 也同样既是「航班」又是「盗窃」。","et":"拉丁语 volare（飞）。「偷」的意思是后来引申出来的，具体过程有争议。","ex":[["Quelqu'un vient de voler mon téléphone !","有人刚偷了我的手机！"],["Les oiseaux volent vers le sud.","鸟向南飞。"],["On m'a volé mon vélo.","有人偷了我的自行车。"]],"co":[["voler un portefeuille","偷钱包"],["voler dans le ciel","在天空飞"],["voler qqch à qqn","偷某人的东西"],["un voleur / un vol","小偷 / 盗窃、航班"]],"sy":[["dérober","soutenu","偷窃（较正式）"],["piquer","familier","顺手牵羊（口语）"],["faucher","familier","偷走（口语）"]],"fq":"高频，日常常用。","me":"voler：飞（空中）或偷（东西），看有没有宾语。","tr":{"zh":"我的自行车昨天被偷了。","fr":"On m'a volé mon vélo hier.","alt":"Quelqu'un m'a piqué mon vélo hier.","note":"On m'a volé = 被偷了（on 作泛指的主语）。"}},
 "Amoureux / Amoureuse": {"pos":"adj. 形容词，阴性 amoureuse，复数 amoureux / amoureuses（也可作名词）","s":"恋爱的；热恋的。être amoureux de qqn = 爱上某人；tomber amoureux = 坠入爱河。名词 un amoureux = 恋人，les amoureux = 一对恋人。也可表示热爱：amoureux de la nature。","ipa":"[a.mu.ʁø] / [a.mu.ʁøz]","ph":"a；mou [mu]；r [ʁ]；男性 eux 读 [ø]，x 不发音；女性 euse 读 [øz]。","pi":"男性 amoureux 的 x 不发音：[a.mu.ʁø]；女性 s 读 [z]。后面接人用 de：amoureux de Paul。","et":"amour + -eux；amour 来自拉丁语 amor。","ex":[["Il est amoureux.","他恋爱了。"],["Elle est tombée amoureuse de son voisin.","她爱上了邻居。"],["Les amoureux se promènent au bord de la Seine.","恋人们在塞纳河边散步。"]],"co":[["tomber amoureux (de)","爱上（某人）"],["être amoureux de qqn","爱着某人"],["un couple d'amoureux","一对恋人"],["être fou amoureux","爱得发狂"]],"sy":[["épris(e) de","soutenu","迷恋（较正式）"],["fou / folle de","familier","为……着迷（口语）"],["aimant","courant","多情的、喜爱的"]],"fq":"高频，日常常用。","me":"amour + -eux：充满爱的人。","tr":{"zh":"她爱上了一位同事。","fr":"Elle est tombée amoureuse d'un collègue.","alt":"Elle a craqué pour un collègue.","note":"tomber amoureux de qqn；craquer pour = 一下就迷上（口语）。"}},
 "Arabe": {"pos":"adj. 形容词，阴阳性同形，复数 arabes（也可作名词）","s":"阿拉伯的；阿拉伯语。作形容词和语言名时小写：l'arabe（阿拉伯语）、la langue arabe；指人时大写：un Arabe。des chiffres arabes = 阿拉伯数字。","ipa":"[a.ʁab]","ph":"a；r [ʁ]；a；b [b] 要发音；结尾 e 不发音：[a.ʁab]。","pi":"结尾的 b 要读出来 [ab]。阴阳性同形：un homme arabe、une femme arabe。语言名小写，人名大写：l'arabe / un Arabe。","et":"来自拉丁语 Arabus。同族：Arabie、arabesque。","ex":[["L'écriture arabe est un art.","阿拉伯书法是一门艺术。"],["Elle parle arabe et français.","她会说阿拉伯语和法语。"],["Il apprend la langue arabe.","他在学阿拉伯语。"]],"co":[["la langue arabe / l'arabe","阿拉伯语"],["le monde arabe","阿拉伯世界"],["des chiffres arabes","阿拉伯数字"],["la calligraphie arabe","阿拉伯书法"]],"sy":[["arabophone","courant","说阿拉伯语的"],["arabique","soutenu","阿拉伯半岛的（咖啡豆等）"],["maghrébin","courant","马格里布的（北非）"]],"fq":"中频。","me":"arabe：阴阳性同形，语言名小写。","tr":{"zh":"我的朋友在大学学阿拉伯语。","fr":"Mon ami apprend l'arabe à l'université.","alt":"Mon copain étudie l'arabe à la fac.","note":"语言名前用定冠词 l'arabe；apprendre + 语言。"}},
 "Bête": {"pos":"adj. 形容词，阴阳性同形，复数 bêtes（也是名词：une bête = 动物）","s":"笨的；傻的；愚蠢的。C'est bête ! =「真可惜 / 真傻！」；pas bête =「不坏、挺聪明」（反话）。名词 une bête = 动物，野兽。叫人 bête 比较直接，不太礼貌。","ipa":"[bɛt]","ph":"b；ê [ɛ]；t 要发音 [t]；结尾 e 不发音：[bɛt]。","pi":"ê 读 [ɛ]，不是 [e]；t 要读出来。阴阳性同形：un garçon bête、une fille bête。用在人身上较冲，用在事情上（C'est bête）比较轻松。","et":"拉丁语 bestia（野兽）。同源：bestial、bête noire。","ex":[["Ce chien n'est pas bête.","这条狗并不笨。"],["C'est bête, j'ai oublié mon parapluie.","真可惜，我忘了带伞。"],["J'ai fait une erreur bête.","我犯了个愚蠢的错误。"]],"co":[["C'est bête !","真可惜、真傻！"],["bête comme ses pieds","笨得要命"],["pas bête","不坏、挺聪明"],["une bête noire","最讨厌的人或事"]],"sy":[["idiot","courant","傻瓜，常用"],["sot","soutenu","愚蠢（较正式）"],["intelligent","courant","聪明（反义）"]],"fq":"高频，日常常用。","me":"bête ← bestia：像「野兽」一样不会想事情。","tr":{"zh":"你这个主意不坏！","fr":"Ce n'est pas bête, ton idée !","alt":"Ton idée, c'est pas bête !","note":"pas bête = 不错、挺聪明（反话）。"}},
 "Blond(e)": {"pos":"adj. 形容词，阴性 blonde，复数 blonds / blondes（也是名词）","s":"金发的；浅色的。des cheveux blonds = 金发；une bière blonde = 淡色啤酒；une blonde = 金发女人 / 淡啤酒。blond 多用来形容头发。","ipa":"[blɔ̃] / [blɔ̃d]","ph":"bl [bl]；on 鼻化元音 [ɔ̃]；男性 d 不发音：[blɔ̃]；女性 blonde d 发音：[blɔ̃d]。","pi":"阳性 blond 的 d 不发音，阴性 blonde 的 d 要发音。on 是鼻化元音，n 不单独发音。","et":"来源不确定，可能是日耳曼语词。","ex":[["Il est blond.","他是金发。"],["Elle a les cheveux blonds et courts.","她有一头金色短发。"],["Je prends une bière blonde.","我要一杯淡啤酒。"]],"co":[["des cheveux blonds","金发"],["blond clair / blond platine","浅金色 / 铂金色"],["une bière blonde","淡色啤酒"],["blond comme les blés","金黄的（如麦色）"]],"sy":[["clair","courant","浅色的"],["roux","courant","红发的（不是金发）"],["châtain","courant","栗色的"]],"fq":"高频，日常常用。","me":"blond：阳性 d 不发音，阴性 d 发音。","tr":{"zh":"我哥哥是金发，蓝眼睛。","fr":"Mon frère est blond et il a les yeux bleus.","alt":"Mon frère a les cheveux blonds et les yeux bleus.","note":"avoir les cheveux blonds 与 être blond 都可以。"}},
 "Brun(e)": {"pos":"adj. 形容词，阴性 brune，复数 bruns / brunes（也是名词）","s":"棕色的；深色头发的。une brune = 深发色的女人；une bière brune = 黑啤。形容头发时 brun 指深棕到黑的颜色；眼睛的棕色用 marron。","ipa":"[bʁœ̃] / [bʁyn]","ph":"br [bʁ]；阳性 un 读鼻化元音 [œ̃]：[bʁœ̃]；阴性 brune 读 [bʁyn]（u [y]，n 发音）。","pi":"阴阳性读音不同：brun [bʁœ̃] / brune [bʁyn]，阴性的元音变了、n 要读。眼睛不说 brun，说 marron。","et":"来自日耳曼语 *brun（法兰克语）。同源：brown。","ex":[["Elle est brune.","她是深色头发。"],["Il a les cheveux bruns et les yeux marron.","他的头发是深棕色，眼睛是棕色。"],["Je prends une bière brune.","我要一杯黑啤。"]],"co":[["une femme brune","深发色的女人"],["les cheveux bruns","深色头发"],["une bière brune","黑啤"],["brun clair / foncé","深棕 / 浅棕"]],"sy":[["châtain","courant","栗色"],["marron","courant","棕色（物品、眼睛）"],["blond","courant","金色（对比）"]],"fq":"高频，日常常用。","me":"brun [bʁœ̃] → brune [bʁyn]：阴性变音。","tr":{"zh":"我姐姐是深色头发，我哥哥是金发。","fr":"Ma sœur est brune et mon frère est blond.","alt":"Ma sœur a les cheveux bruns, mon frère est blond.","note":"brune 是阴性；avoir les cheveux bruns。"}},
 "Châtain": {"pos":"adj. 形容词，阴阳性常同形（也有 châtaine），复数 châtains","s":"栗色的；浅棕色头发的。châtain 只用于头发（和胡子、眉毛），不用于眼睛和物品。比 brun 浅。","ipa":"[ʃɑ.tɛ̃]","ph":"ch [ʃ]；â [ɑ]（也可读 [a]）；t；ain 鼻化元音 [ɛ̃]：[ʃɑ.tɛ̃]。","pi":"ain 是鼻化元音 [ɛ̃]，n 不单独发音。阴性通常也说 châtain（elle est châtain），châtaine 少见。眼睛的棕色不用 châtain，用 marron。","et":"来自 châtaigne（板栗），拉丁语 castanea。","ex":[["J'ai les cheveux châtains.","我的头发是浅棕色。"],["Elle est châtain clair.","她是浅栗色头发。"],["Mon frère est châtain, ma sœur est blonde.","我哥哥是栗色头发，我姐姐是金发。"]],"co":[["des cheveux châtains","栗色头发"],["châtain clair / foncé","浅栗色 / 深栗色"],["avoir les cheveux châtains","有栗色头发"],["un châtain doré","金栗色"]],"sy":[["brun","courant","深色头发的"],["marron","courant","棕色（物品、眼睛）"],["blond","courant","金发的"]],"fq":"中频，主要用来形容头发。","me":"châtain ← châtaigne：像板栗一样的颜色。","tr":{"zh":"我爸爸是栗色头发，我妈妈是红发。","fr":"Mon père est châtain et ma mère est rousse.","alt":"Mon père a les cheveux châtains, ma mère est rousse.","note":"头发颜色：être châtain 或 avoir les cheveux châtains。"}},
 "Chauve": {"pos":"adj. 形容词，阴阳性同形，复数 chauves（也可作名词）","s":"秃的；没有头发的。devenir chauve = 变秃；chauve comme un œuf =「光溜溜」。还有 chauve-souris = 蝙蝠（字面：秃老鼠）。","ipa":"[ʃov]","ph":"ch [ʃ]；au [o]；v [v] 要发音；结尾 e 不发音：[ʃov]。","pi":"au 读 [o]；v 要发音。和 chaud（热，[ʃo]）区分：chaud 结尾 d 不发音，chauve 结尾 v 要发音。","et":"拉丁语 calvus（秃的）。","ex":[["Mon oncle est chauve.","我叔叔是秃头。"],["Il devient chauve à trente ans.","他三十岁就秃了。"],["La chauve-souris dort le jour.","蝙蝠白天睡觉。"]],"co":[["devenir chauve","变秃"],["chauve comme un œuf","光溜溜的"],["la chauve-souris","蝙蝠"],["un crâne chauve","光秃秃的头"]],"sy":[["dégarni","courant","头发稀疏的"],["rasé","courant","剃光头的"],["déplumé","familier","秃了的（口语）"]],"fq":"中频。","me":"chauve 秃 / chaud 热：chauve 要读 v。","tr":{"zh":"我爷爷四十岁起就秃了。","fr":"Mon grand-père est chauve depuis ses quarante ans.","alt":"Mon grand-père n'a plus de cheveux depuis ses quarante ans.","note":"depuis + 时间点 / 时间段，用现在时。"}},
 "Courageux / Courageuse": {"pos":"adj. 形容词，阴性 courageuse，复数 courageux / courageuses","s":"勇敢的；有毅力的。也常指勤奋、不怕累。名词 le courage = 勇气。Bon courage ! =「加油！」（对正在辛苦做事的人说）。","ipa":"[ku.ʁa.ʒø] / [ku.ʁa.ʒøz]","ph":"cou [ku]；ra [ʁa]；g 在 e / u 前读 [ʒ]：[ʒø]；男性结尾 eux [ø]，x 不发音；女性 euse 读 [øz]。","pi":"男性 x 不发音；女性 s 读 [z]。ou 读 [u]。courage 的 g 读 [ʒ]，不是 [ɡ]。Bon courage ! 不是祝人勇敢，而是「加油、辛苦了」。","et":"courage + -eux；courage 来自古法语 corage，源自拉丁语 cor（心）。","ex":[["Le pompier est courageux.","消防员很勇敢。"],["C'est courageux de dire la vérité.","说出真相很需要勇气。"],["Elle est très courageuse.","她非常勇敢。"]],"co":[["un homme courageux","勇敢的人"],["Bon courage !","加油！"],["avoir du courage","有勇气"],["être courageux de + infinitif","敢于做某事"]],"sy":[["brave","courant","勇敢的"],["vaillant","soutenu","英勇的（较正式）"],["lâche","courant","懦弱的（反义）"]],"fq":"高频，日常常用。","me":"courage ← cor（心）：有「心」的人。","tr":{"zh":"在大家面前发言，真勇敢。","fr":"C'est courageux de parler devant tout le monde.","alt":"T'es courageux de parler devant tout le monde.","note":"C'est courageux de + 不定式。"}},
 "Curieux / Curieuse": {"pos":"adj. 形容词，阴性 curieuse，复数 curieux / curieuses","s":"好奇的；爱打听的；奇怪的。être curieux de + 动词原形 = 很想知道。有时带贬义，指爱管闲事；放在名词前（un curieux phénomène）还可指「奇特的」。","ipa":"[ky.ʁjø] / [ky.ʁjøz]","ph":"cu [ky]；rieu [ʁjø]；阳性结尾 x 不发音，阴性 -euse 读 [øz]。","pi":"u 是 [y]（圆唇），不是 [u]；阳性 x 不发音。","et":"拉丁语 curiosus（细心的、好奇的），来自 cura（关心）。同源：curiosité。","ex":[["L'enfant est curieux.","这个孩子很好奇。"],["Je suis curieux de savoir la suite.","我很想知道后来怎么样了。"],["Elle est curieuse de tout.","她对什么都好奇。"]],"co":[["être curieux de + inf.","很想知道……"],["un esprit curieux","好奇的头脑"],["C'est curieux.","真奇怪。"]],"sy":[["bizarre","courant","奇怪（curieux 也有此义）"],["indiscret","courant","爱打听、不知分寸"],["fouineur","familier","爱到处打听的人"]],"fq":"高频。","me":"curieux 里有 cure 的味道：什么都想「探究」。","tr":{"zh":"我很想知道你在做什么。","fr":"Je suis curieux de savoir ce que tu fais.","alt":"Je me demande ce que tu fais, ça m'intrigue.","note":"curieux de + 动词原形。"}},
 "Drôle": {"pos":"adj. 形容词，阴阳同形，复数 drôles","s":"有趣的，好笑的。放在名词前并用 drôle de + 名词，意思变成「奇怪的」：une drôle d'idée = 一个怪主意。Ce n'est pas drôle = 这一点也不好笑（也可表示「很烦」）。","ipa":"[dʁol]","ph":"ô 带帽子，读 [o]；r 是小舌音 [ʁ]；结尾 e 不发音。","pi":"drôle de + 名词是「奇怪」，不是「好笑」，要看语境。","et":"来源不确定（可能来自荷兰语/古北欧语的借词）。同源词：drôlement（非常，口语）。","ex":[["Ce film est drôle.","这部电影很好笑。"],["Ce n'est pas drôle !","这一点也不好笑！"],["Quelle drôle d'idée !","多么古怪的主意！"]],"co":[["une histoire drôle","一个笑话"],["drôle de + nom","奇怪的……"],["pas drôle","不好笑；让人不快"]],"sy":[["amusant","courant","有趣、逗乐"],["marrant","familier","好玩、搞笑"],["comique","courant","滑稽的（戏剧/场面）"]],"fq":"极高频，日常常用。","me":"drôle 带圆帽 ô：像小丑脸，好笑也古怪。","tr":{"zh":"你的朋友很搞笑。","fr":"Ton ami est très drôle.","alt":"Ton copain est vraiment marrant.","note":"drôle 阴阳同形。"}},
 "Dynamique": {"pos":"adj. 形容词，阴阳同形，复数 dynamiques；也作 n.f. une dynamique（动力、发展趋势）","s":"有活力的，积极主动的，精力充沛的。形容人、团队、公司都可以。名词 la dynamique de groupe = 团体动力。","ipa":"[di.na.mik]","ph":"y 读 [i]；-que 读 [k]；重音落在最后一个音节。","pi":"y 读 [i]，不读 [ai]；结尾 que 读 [k]，e 不发音。","et":"希腊语 dunamikos，来自 dunamis（力量）。同源：dynamisme。","ex":[["Elle est très dynamique.","她非常有活力。"],["Nous cherchons une personne dynamique.","我们在找一个有干劲的人。"],["L'équipe est jeune et dynamique.","这支团队年轻又有活力。"]],"co":[["une équipe dynamique","有活力的团队"],["un jeune cadre dynamique","年轻有为的管理人员"],["la dynamique de groupe","团体动力"]],"sy":[["énergique","courant","精力充沛"],["actif","courant","积极的、爱活动的"],["mou","courant","反义：无精打采"]],"fq":"中高频。","me":"dynamique ≈ dynamite：充满爆发力。","tr":{"zh":"我们的新老师很有活力。","fr":"Notre nouveau professeur est très dynamique.","alt":"Notre nouveau prof a beaucoup d'énergie.","note":"nouveau professeur：阳性；prof 是口语缩写。"}},
 "Fatigué(e)": {"pos":"adj. 形容词，阴性 fatiguée，复数 fatigués / fatiguées","s":"累的，疲倦的。也可指东西旧了、不好使（une voix fatiguée 疲惫的声音）。être fatigué de + 动词原形 / 名词 = 厌倦了……。名词是 la fatigue，动词是 fatiguer。","ipa":"[fa.ti.ge] / [fa.ti.ge]","ph":"gu 读 [g]（u 不发音）；é 读 [e]；阴阳性读音相同。","pi":"gu 里的 u 不读；阴阳性同音，只看拼写。","et":"拉丁语 fatigare（使疲劳）。同源：fatigue, infatigable。","ex":[["Je suis fatigué.","我累了。"],["Elle est fatiguée après le travail.","她下班后很累。"],["Tu as l'air fatigué.","你看起来很累。"]],"co":[["être fatigué de + inf.","厌倦做……"],["avoir l'air fatigué","看起来很累"],["fatigué par le voyage","旅途劳累"]],"sy":[["épuisé","courant","筋疲力尽"],["crevé","familier","累坏了"],["exténué","soutenu","精疲力竭"]],"fq":"极高频，日常常用。","me":"fatigué 的 gu 像 fatigue：疲劳。","tr":{"zh":"今晚我很累，我要早点睡。","fr":"Ce soir, je suis très fatigué : je me couche tôt.","alt":"Ce soir, je suis crevé, je vais me coucher tôt.","note":"fatigué 和主语性数一致。"}},
 "Fort(e)": {"pos":"adj. 形容词，阴性 forte，复数 forts / fortes；也可作副词（parler fort，不变）","s":"强壮的；强烈的；擅长的。être fort en + 科目 = 在某科上很强。副词用法：parler fort = 大声说话。un café fort = 浓咖啡。","ipa":"[fɔʁ] / [fɔʁt]","ph":"o 读 [ɔ]（开口）；r 读 [ʁ]；阳性 t 不发音，阴性 forte 的 t 要发 [t]。","pi":"阳性 fort 的 t 不发音，阴性 forte 才发。","et":"拉丁语 fortis（强壮的）。同源：force, fortifier, réconfort。","ex":[["Il est très fort.","他很强壮。"],["Elle est forte en maths.","她数学很好。"],["Parle plus fort, je n'entends pas.","说大声点，我听不见。"]],"co":[["être fort en maths","数学很强"],["parler fort","大声说话"],["un café fort","浓咖啡"],["c'est plus fort que moi","我控制不住"]],"sy":[["costaud","familier","结实、壮实"],["robuste","courant","强健、结实"],["faible","courant","反义：弱的"]],"fq":"极高频。","me":"fort = 有 force（力量）。","tr":{"zh":"我弟弟数学很强。","fr":"Mon petit frère est fort en maths.","alt":"Mon petit frère est super bon en maths.","note":"être fort en + 科目。"}},
 "Frisé(e)": {"pos":"adj. 形容词，阴性 frisée，复数 frisés / frisées","s":"（头发）卷曲的、小卷的。比 bouclé（大卷）更紧、更细；非常卷的头发叫 crépu。动词是 friser（使卷曲）。une salade frisée = 卷叶菊苣。","ipa":"[fʁi.ze] / [fʁi.ze]","ph":"fri [fʁi]；s 在两个元音之间读 [z]；é 读 [e]。","pi":"s 读 [z]，不读 [s]；阴阳性同音。","et":"来自动词 friser（使卷曲），词源不确定。同源：frisure, frisottis。","ex":[["Elle a les cheveux frisés.","她的头发是卷的。"],["Ma sœur est frisée, moi je suis lisse.","我姐姐是卷发，我是直发。"],["Il a la tête toute frisée.","他满头都是小卷发。"]],"co":[["avoir les cheveux frisés","有卷发"],["une salade frisée","卷叶菊苣"],["se faire friser les cheveux","烫卷头发"]],"sy":[["bouclé","courant","（大）卷的"],["crépu","courant","非常卷的（如非洲式卷发）"],["lisse","courant","反义：直的"]],"fq":"中频，描述外貌时常用。","me":"frisé ≈ frizzy：一卷一卷的头发。","tr":{"zh":"她是卷发，我是直发。","fr":"Elle a les cheveux frisés, moi j'ai les cheveux lisses.","alt":"Ses cheveux sont frisés, les miens sont lisses.","note":"avoir les cheveux + 形容词。"}},
 "Gai / Gaie": {"pos":"adj. 形容词，阴性 gaie，复数 gais / gaies","s":"快乐的，开朗的，欢快的。可形容人，也可形容颜色、音乐、气氛（une couleur gaie 明快的颜色）。反义：triste。","ipa":"[ɡɛ] / [ɡɛ]","ph":"g 读 [ɡ]；ai 读 [ɛ]；阴性 gaie 读音相同（e 不发音）。","pi":"gai（快乐）和 gay（同性恋）拼写不同，别混淆。","et":"古法语 gai，可能来自日耳曼语，细节有争议。同源：gaieté / gaité。","ex":[["Elle est toujours gaie.","她总是很快乐。"],["Il chante d'un air gai.","他一脸高兴地唱歌。"],["Cette couleur est gaie.","这个颜色很明快。"]],"co":[["avoir l'air gai","看起来很高兴"],["une ambiance gaie","欢快的气氛"],["gai comme un pinson","像雀鸟一样快活"]],"sy":[["joyeux","courant","快乐的、欢乐的"],["content","courant","高兴的"],["triste","courant","反义：悲伤的"]],"fq":"中频，有点书面/文学色彩，日常多说 de bonne humeur。","me":"gai：短短一个音 [ɡɛ]，轻快，像人一样开朗。","tr":{"zh":"我们的邻居总是很快乐。","fr":"Nos voisins sont toujours gais.","alt":"Nos voisins sont toujours de bonne humeur.","note":"gai 的复数阳性是 gais。"}},
 "Gazeux / Gazeuse": {"pos":"adj. 形容词，阴性 gazeuse，复数 gazeux / gazeuses","s":"含气的，有气泡的。常见：eau gazeuse（气泡水）、boisson gazeuse（碳酸饮料）。反义：plat(e)（不含气）。口语也说 pétillant。","ipa":"[ɡa.zø] / [ɡa.zøz]","ph":"gaz [ɡaz] + -eux [ø]；z 读 [z]；阳性 x 不发音。","pi":"z 要读 [z]；阳性末尾 x 不发音。","et":"gaz（17 世纪由化学家 van Helmont 据希腊语 chaos 造出）+ 后缀 -eux。","ex":[["Perrier est une marque d'eau gazeuse.","佩里埃是一个气泡水品牌。"],["Je préfère l'eau plate à l'eau gazeuse.","比起气泡水，我更喜欢无气水。"],["Je ne bois pas de boissons gazeuses.","我不喝碳酸饮料。"]],"co":[["de l'eau gazeuse","气泡水"],["une boisson gazeuse","碳酸饮料"],["eau plate / eau gazeuse","无气水 / 气泡水"]],"sy":[["pétillant","courant","起泡的（葡萄酒、水）"],["plat","courant","反义：不含气"],["effervescent","soutenu","冒泡的（药片等）"]],"fq":"中高频，点饮料时常用。","me":"gazeux = 有 gaz 的水。","tr":{"zh":"请给我一瓶气泡水。","fr":"Une bouteille d'eau gazeuse, s'il vous plaît.","alt":"Je voudrais une eau gazeuse, s'il vous plaît.","note":"eau 是阴性，所以用 gazeuse。"}},
 "Généreux / Généreuse": {"pos":"adj. 形容词，阴性 généreuse，复数 généreux / généreuses","s":"慷慨的，大方的，也指「分量足的」：une portion généreuse = 很大一份。être généreux avec / envers qqn = 对某人大方。","ipa":"[ʒe.ne.ʁø] / [ʒe.ne.ʁøz]","ph":"gé [ʒe]；né [ne]；reux [ʁø]；阳性 x 不发音。","pi":"g 在 e 前读 [ʒ]（像 j），不读 [g]；三个音节都轻。","et":"拉丁语 generosus（出身高贵的），来自 genus（出身、家族）。","ex":[["Il est généreux.","他很慷慨。"],["Elle est généreuse avec ses amis.","她对朋友很大方。"],["Voilà une portion généreuse !","这一份量真足！"]],"co":[["être généreux avec qqn","对某人大方"],["une portion généreuse","分量足的一份"],["un cœur généreux","宽厚的心"]],"sy":[["prodigue","soutenu","挥霍的、给予多的"],["avare","courant","反义：吝啬的"],["radin","familier","反义：小气"]],"fq":"中高频。","me":"généreux = 给出很多 (génér- ≈ give a lot)。","tr":{"zh":"我奶奶对每个人都很大方。","fr":"Ma grand-mère est généreuse avec tout le monde.","alt":"Mamie est très généreuse avec tout le monde.","note":"généreuse 与 grand-mère 阴性一致。"}},
 "Gentil / Gentille": {"pos":"adj. 形容词，阴性 gentille，复数 gentils / gentilles","s":"善良的，亲切的，有礼貌的。对小孩常说 Sois gentil（乖一点）。C'est gentil de ta part = 你真好。放名词前 un gentil petit chat = 一只可爱的小猫。","ipa":"[ʒɑ̃.ti] / [ʒɑ̃.tij]","ph":"g [ʒ]；en [ɑ̃] 鼻化；阳性 -il 读 [i]（l 不发音），阴性 -ille 读 [ij]。","pi":"阳性 gentil 的 l 不读；阴性 gentille 的 ll 读 [j]。","et":"拉丁语 gentilis（同族的、高贵的），来自 gens（氏族）。","ex":[["Le garçon est gentil.","这个男孩很善良。"],["Elle est très gentille avec moi.","她对我很好。"],["C'est gentil de ta part.","你真好。"]],"co":[["être gentil avec qqn","对某人友善"],["c'est gentil de ta part","你真好"],["sois gentil !","乖一点！"]],"sy":[["aimable","courant","和蔼可亲的"],["sympa","familier","友好、好相处"],["méchant","courant","反义：坏心的"]],"fq":"极高频。","me":"gentil 的软音 [ʒɑ̃]：像温柔的人说话。","tr":{"zh":"谢谢你来，你真好。","fr":"Merci d'être venu, c'est très gentil.","alt":"Merci d'être venu, c'est sympa.","note":"gentil 也可表示感谢。"}},
 "Gros / Grosse": {"pos":"adj. 形容词，阴性 grosse，复数 gros / grosses","s":"胖的；大的；粗的；严重的。指人时较直接，可能冒犯人；委婉可说 fort 或 rond。un gros mot = 脏话；un gros problème = 大问题。","ipa":"[ɡʁo] / [ɡʁos]","ph":"gr [ɡʁ]；o 读 [o]；阳性 s 不发音；阴性 grosse 的 ss 读清音 [s]。","pi":"阳性 gros 的 s 不读，阴性要读 [s]。","et":"晚期拉丁语 grossus（厚的）。同源：grossir（变胖）, grossesse（怀孕）。","ex":[["Le chat est gros.","这只猫很胖。"],["Elle a une grosse valise.","她有一个大行李箱。"],["Il y a un gros problème.","有个大问题。"]],"co":[["un gros mot","脏话"],["une grosse somme","一大笔钱"],["un gros plan","特写"],["le gros lot","头奖"]],"sy":[["énorme","courant","巨大的"],["épais","courant","厚的、粗的"],["mince","courant","反义：瘦的、薄的"]],"fq":"极高频。","me":"gros = 大；grosse = 加 e 出现 s 声。","tr":{"zh":"我有一个大行李箱。","fr":"J'ai une grosse valise.","alt":"J'ai une énorme valise.","note":"valise 阴性，用 grosse。"}},
 "Impatient(e)": {"pos":"adj. 形容词，阴性 impatiente，复数 impatients / impatientes","s":"没耐心的；迫不及待的。être impatient de + 动词原形 = 迫不及待想……（这是积极含义）。名词 l'impatience；副词 avec impatience = 急切地。","ipa":"[ɛ̃.pa.sjɑ̃] / [ɛ̃.pa.sjɑ̃t]","ph":"im [ɛ̃] 鼻化，m 不单独发音；ti 读 [sj]；-ent 读 [ɑ̃]；阴性 t 读出。","pi":"ti 读 [sj]，不是 [ti]；-ent 读 [ɑ̃]，n 和 t 不发。","et":"拉丁语 impatiens（不能忍受的），in- 否定 + patiens。反义：patient。","ex":[["Je suis impatient.","我很不耐烦。"],["Il est impatient de partir en vacances.","他迫不及待想去度假。"],["Elle est impatiente de te voir.","她迫不及待想见你。"]],"co":[["être impatient de + inf.","迫不及待想……"],["attendre avec impatience","急切地等待"],["un enfant impatient","没耐心的孩子"]],"sy":[["pressé","courant","赶时间的"],["avoir hâte","courant","期待、等不及（常用）"],["patient","courant","反义：有耐心的"]],"fq":"中高频。","me":"im-patient = 不 patient；等不及。","tr":{"zh":"孩子们迫不及待想看这部电影。","fr":"Les enfants sont impatients de voir ce film.","alt":"Les enfants ont hâte de voir ce film.","note":"avoir hâte de ≈ être impatient de。"}},
 "Intelligent(e)": {"pos":"adj. 形容词，阴性 intelligente，复数 intelligents / intelligentes","s":"聪明的，有头脑的；（想法、回答）明智的。名词 l'intelligence；l'intelligence artificielle = 人工智能（IA）。反义：bête。","ipa":"[ɛ̃.te.li.ʒɑ̃] / [ɛ̃.te.li.ʒɑ̃t]","ph":"in [ɛ̃]；tel [te]；li；gent [ʒɑ̃]（g 读 [ʒ]）；阴性 t 读出。","pi":"-gent 读 [ʒɑ̃]，t 不发音（阴性 -gente 才读 t）；重音在最后。","et":"拉丁语 intelligens，来自 intelligere（理解）= inter + legere（在……之间挑选/阅读）。","ex":[["Elle est intelligente.","她很聪明。"],["Ton idée est très intelligente.","你的想法很聪明。"],["Ce chien est vraiment intelligent.","这只狗真聪明。"]],"co":[["une réponse intelligente","聪明的回答"],["l'intelligence artificielle (IA)","人工智能"],["assez intelligent pour + inf.","聪明得足以……"]],"sy":[["malin","courant","机灵、精明"],["futé","familier","聪明、鬼灵精"],["bête","courant","反义：笨的"]],"fq":"高频。","me":"intelli + gent：intelligent 就是「智」+ 人。","tr":{"zh":"他的女儿聪明又有礼貌。","fr":"Sa fille est intelligente et polie.","alt":"Sa fille est super intelligente et très polie.","note":"形容词与 fille 一致，用阴性。"}},
 "Joyeux / Joyeuse": {"pos":"adj. 形容词，阴性 joyeuse，复数 joyeux / joyeuses","s":"快乐的，欢乐的，喜气洋洋的。节日祝福里常用：Joyeux Noël ! Joyeux anniversaire ! 注意 joyeux 是表现出来的欢乐，比 heureux（幸福）更外露。","ipa":"[ʒwa.jø] / [ʒwa.jøz]","ph":"joy 读 [ʒwa.j]（oy = [waj]）；eux 读 [ø]；阴性 -euse 读 [øz]。","pi":"oy 不读 [oi]，读 [waj]；阳性 x 不读。","et":"joie（古法语 joie，来自拉丁语 gaudia）+ -eux。","ex":[["Joyeux anniversaire !","生日快乐！"],["Les enfants chantent d'une voix joyeuse.","孩子们快乐地唱着歌。"],["Nous avons passé un joyeux Noël.","我们过了一个快乐的圣诞节。"]],"co":[["Joyeux Noël !","圣诞快乐！"],["Joyeux anniversaire !","生日快乐！"],["de joyeuses fêtes","节日快乐"]],"sy":[["gai","courant","欢快的"],["heureux","courant","幸福的、开心的"],["triste","courant","反义：悲伤的"]],"fq":"高频，祝福语里极常见。","me":"joyeux Noël：joy + eux，满是 joie。","tr":{"zh":"孩子们在唱歌，他们很快乐。","fr":"Les enfants chantent, ils sont joyeux.","alt":"Les enfants chantent, ils ont l'air joyeux.","note":"ils sont joyeux：复数阳性。"}},
 "Lisse": {"pos":"adj. 形容词，阴阳同形，复数 lisses","s":"光滑的；（头发）直的。cheveux lisses = 直发；une peau lisse = 光滑的皮肤；une surface lisse = 平滑的表面。动词 lisser = 抚平、使光滑。反义：frisé / rugueux。","ipa":"[lis]","ph":"ss 读 [s]；结尾 e 不发音；读 [lis]。","pi":"和 lys（百合）同音；两个 s 不读 [z]。","et":"来源不确定，可能是日耳曼语借词。同源词：lisser, lissage。","ex":[["Ses cheveux sont lisses.","她的头发是直的。"],["Elle a la peau lisse.","她的皮肤很光滑。"],["Le verre est lisse et froid.","玻璃又光滑又冰凉。"]],"co":[["des cheveux lisses","直发"],["une surface lisse","光滑的表面"],["la peau lisse","光滑的皮肤"]],"sy":[["plat","courant","平的"],["uni","courant","平整无纹路的"],["frisé","courant","反义：卷的"]],"fq":"中频，描述头发和表面时常用。","me":"lisse：声音光滑，/lis/ 一滑就过。","tr":{"zh":"她的头发又长又直。","fr":"Elle a les cheveux longs et lisses.","alt":"Ses cheveux sont longs et bien lisses.","note":"lisse 阴阳同形。"}},
 "Maghrébin(e)": {"pos":"adj. 形容词，也作名词；阴性 maghrébine，复数 maghrébins / maghrébines","s":"马格里布（北非西部）的；马格里布人。Maghreb 通常指摩洛哥、阿尔及利亚、突尼斯。作名词时首字母常大写：un Maghrébin。和 arabe 不同：语言/民族不是同一概念。","ipa":"[ma.ɡʁe.bɛ̃] / [ma.ɡʁe.bin]","ph":"gh 读 [ɡ]；é 读 [e]；-in 阳性 [ɛ̃]，阴性 -ine 读 [in]。","pi":"gh 读 [ɡ]（h 不发音）；阴阳性读音不同：阳性鼻化 [ɛ̃]，阴性 [in]。","et":"来自阿拉伯语 maghrib（日落处、西方）。le Maghreb = 「西方」。","ex":[["Il est maghrébin.","他是北非人。"],["La cuisine maghrébine est délicieuse.","马格里布菜很好吃。"],["Elle a des origines maghrébines.","她有北非血统。"]],"co":[["un pays maghrébin","马格里布国家"],["la cuisine maghrébine","马格里布菜"],["d'origine maghrébine","北非裔"]],"sy":[["nord-africain","courant","北非的（范围更广）"],["arabe","courant","阿拉伯的，不等于 maghrébin"]],"fq":"中频。","me":"Maghreb = 「西边」，maghrébin 是那一带的人。","tr":{"zh":"我的邻居是北非人。","fr":"Mon voisin est maghrébin.","alt":"Mon voisin vient du Maghreb.","note":"作形容词不大写，作名词首字母大写。"}},
 "Malade": {"pos":"adj. 形容词 / n. 名词，阴阳同形，复数 malades（un malade = 病人）","s":"生病的。作名词：un malade / une malade = 病人。tomber malade = 生病；se sentir malade = 觉得不舒服（也指想吐）。注意 être malade 是病了，不是 mal（糟糕地）。","ipa":"[ma.lad]","ph":"ma [ma]；la [la]；d 发音 [d]；结尾 e 不发音。","pi":"阴阳同形同音；d 要发音，不要读成 [ma.la]。","et":"来自拉丁语 male（坏地）的复合，后半部分来源有争议。同源：maladie, maladif。","ex":[["Je suis malade.","我生病了。"],["Il est malade depuis lundi.","他从星期一起就病了。"],["Le médecin voit un malade.","医生在看一位病人。"]],"co":[["tomber malade","生病"],["se sentir malade","觉得不舒服"],["un malade / une malade","病人"],["un malade imaginaire","疑病症患者"]],"sy":[["souffrant","soutenu","身体不适（较书面）"],["patraque","familier","有点不舒服"],["en forme","courant","反义：状态好"]],"fq":"极高频。","me":"mal + ade：状态不好的人 = malade。","tr":{"zh":"我生病了，我待在家里。","fr":"Je suis malade, je reste à la maison.","alt":"Je ne me sens pas bien, je reste à la maison.","note":"être malade：形容词，无需冠词。"}},
 "Méchant(e)": {"pos":"adj. 形容词，阴性 méchante，复数 méchants / méchantes","s":"坏心的，刻薄的；（孩子）调皮、不听话；（动物）凶的。chien méchant = 恶犬。Il n'est pas méchant = 他没有恶意（不会伤人）。反义：gentil。","ipa":"[me.ʃɑ̃] / [me.ʃɑ̃t]","ph":"mé [me]；ch 读 [ʃ]；-ant 读 [ɑ̃]；阴性 t 读出。","pi":"ch 读 [ʃ]，不是 [tʃ]；-ant 读 [ɑ̃]，没有 n 或 t。","et":"古法语 mescheant（不幸的），来自 mes-（坏）+ cheoir（落下）。","ex":[["Le loup est méchant.","狼很凶。"],["Ne sois pas méchant avec ton frère !","别对你弟弟那么坏！"],["Attention, chien méchant.","小心，恶犬。"]],"co":[["chien méchant","恶犬"],["être méchant avec qqn","对某人很坏"],["pas méchant","没有恶意"]],"sy":[["cruel","courant","残忍的"],["vilain","courant","顽皮的（对孩子）；难看的"],["gentil","courant","反义：善良的"]],"fq":"高频。","me":"méchant ≠ mécanique；méchant = 心坏。","tr":{"zh":"别对你妹妹这么凶！","fr":"Ne sois pas méchant avec ta sœur !","alt":"Arrête d'être méchant avec ta sœur !","note":"méchant avec qqn。"}},
 "Mince": {"pos":"adj. 形容词，阴阳同形，复数 minces；感叹词 Mince ! (哎呀！)","s":"瘦的，苗条的（褒义）；薄的、细的：une mince couche。Mince ! = 哎呀！糟糕！（温和的感叹）。比 maigre（偏瘦、带贬义）更好听。","ipa":"[mɛ̃s]","ph":"m；in 读鼻化 [ɛ̃]；ce 在词尾读 [s]；整词 [mɛ̃s]。","pi":"in 是鼻化元音，不要读出 n；结尾 ce 读 [s]。","et":"来源不确定，可能与拉丁语 minutus（小的）有关。同源词：amincir（变瘦）, minceur。","ex":[["Elle est très mince.","她很瘦。"],["Il y a une mince couche de neige.","有薄薄的一层雪。"],["Mince ! J'ai oublié mes clés.","哎呀！我忘带钥匙了。"]],"co":[["une mince couche","薄薄一层"],["Mince alors !","哎呀！"],["un mince espoir","一线微弱的希望"]],"sy":[["svelte","soutenu","苗条、修长"],["maigre","courant","瘦（常带贬义）"],["gros","courant","反义：胖的"]],"fq":"中高频。","me":"mince 与 minus（少）同音头：变少、变薄。","tr":{"zh":"我弟弟又高又瘦。","fr":"Mon frère est grand et mince.","alt":"Mon frère est grand et fin.","note":"mince 阴阳同形。"}},
 "Musclé(e)": {"pos":"adj. 形容词，阴性 musclée，复数 musclés / musclées","s":"肌肉发达的，强壮的。des bras musclés = 肌肉结实的手臂。比喻用法：un discours musclé = 强硬的言论。动词 se muscler = 增肌、锻炼。","ipa":"[mys.kle] / [mys.kle]","ph":"mu [my]；scl 紧凑连读 [skl]；é [e]；阴阳性同音。","pi":"u 读 [y]，不是 [u]；s 在 sc- 前读 [s]；é 在词尾读 [e]。","et":"拉丁语 musculus（小老鼠）。古人觉得收缩的肌肉像在皮下游走的小老鼠。","ex":[["Il est musclé.","他很结实。"],["Elle a des bras musclés.","她的手臂肌肉结实。"],["Ce footballeur est très musclé.","这位足球运动员非常强壮。"]],"co":[["des bras musclés","肌肉发达的手臂"],["un corps musclé","健壮的身体"],["se muscler","增肌"]],"sy":[["costaud","familier","强壮结实"],["baraqué","familier","身材高大壮实"],["athlétique","courant","健美的、运动员体型"]],"fq":"中频。","me":"muscle + é：有 muscle 的。","tr":{"zh":"我的教练肌肉很发达。","fr":"Mon entraîneur est très musclé.","alt":"Mon coach est vraiment costaud.","note":"entraîneur 阳性。"}},
 "Patient(e)": {"pos":"adj. 形容词 / n. 名词，阴性 patiente，复数 patients / patientes（un patient = 病人）","s":"有耐心的；名词：病人（医院里被治疗的人）。il faut être patient = 要有耐心。动词 patienter = 耐心等待，常用在 Veuillez patienter（请稍候）。","ipa":"[pa.sjɑ̃] / [pa.sjɑ̃t]","ph":"pa [pa]；ti 读 [sj]；-ent 读 [ɑ̃]；阴性 t 读出。","pi":"ti 读 [sj]，不是 [ti]；末尾 -ent 读 [ɑ̃]，不读 t。","et":"拉丁语 patiens（忍受的），来自 pati（忍受、承受）。同源：patience, passion。","ex":[["Il faut être patient.","要有耐心。"],["Elle est très patiente avec les enfants.","她对孩子很有耐心。"],["Le médecin reçoit un patient.","医生在接待一位病人。"]],"co":[["être patient avec qqn","对某人有耐心"],["un patient / une patiente","病人"],["Veuillez patienter.","请稍候。"]],"sy":[["calme","courant","冷静的"],["tolérant","courant","宽容的"],["impatient","courant","反义：没耐心的"]],"fq":"中高频。","me":"patient ← pati：「忍」得住，也是「忍受病痛」的人。","tr":{"zh":"请耐心点，医生马上就到。","fr":"Soyez patient, le médecin arrive tout de suite.","alt":"Un peu de patience, le médecin arrive.","note":"Soyez 是 être 的命令式（vous）。"}},
 "Plat / Plate": {"pos":"adj. 形容词，阴性 plate，复数 plats / plates；也作 n.m. un plat（一道菜；盘子）","s":"平的；不含气的：eau plate = 无气水。un pneu à plat = 没气的轮胎。名词 un plat = 一道菜（le plat du jour 今日特餐）；注意「盘子」是 une assiette。","ipa":"[pla] / [plat]","ph":"pl [pl]；a [a]；阳性 t 不发音，阴性 plate 读 [plat]。","pi":"阳性 plat 的 t 不读；une assiette ≠ un plat，plat 是「菜」。","et":"通俗拉丁语 *plattus，源自希腊语 platus（平的）。同源：plateau, plateforme。","ex":[["Tu préfères l'eau plate ou l'eau gazeuse ?","你要无气水还是气泡水？"],["La région est très plate.","这个地区非常平坦。"],["J'ai un pneu à plat.","我的轮胎没气了。"]],"co":[["de l'eau plate","无气水"],["un pneu à plat","没气的轮胎"],["le plat du jour","今日特餐"],["à plat ventre","趴着"]],"sy":[["uni","courant","平整的"],["gazeux","courant","反义：含气的"],["creux","courant","反义：凹的"]],"fq":"极高频。","me":"plat 像英语 plate，但意思是「平」或「一道菜」。","tr":{"zh":"我想要无气水，谢谢。","fr":"Je voudrais de l'eau plate, s'il vous plaît.","alt":"Une eau plate, s'il vous plaît.","note":"eau 阴性，plate。"}},
 "Roux / Rousse": {"pos":"adj. 形容词 / n. 名词，阴性 rousse，复数 roux / rousses","s":"红棕色头发的（红发）；也指动物毛色。un roux / une rousse = 红发的人。烹饪里 un roux = 油面糊（白酱的基底）。taches de rousseur = 雀斑。","ipa":"[ʁu] / [ʁus]","ph":"r [ʁ]；ou [u]；阳性 x 不发音；阴性 rousse 读 [ʁus]（ss = [s]）。","pi":"阳性 x 不发音；阴性 rousse 的 ss 读 [s]；ou 读 [u]。","et":"拉丁语 russus（红色的）。同源：rousseur, rouquin, roussir（烤焦）。","ex":[["Mon frère est roux.","我哥哥是红头发。"],["Elle a les cheveux roux et des taches de rousseur.","她有红头发，还有雀斑。"],["La femme rousse porte un chapeau.","那位红发女子戴着一顶帽子。"]],"co":[["avoir les cheveux roux","有红发"],["des taches de rousseur","雀斑"],["un roux / une rousse","红发的人"],["un roux (cuisine)","油面糊"]],"sy":[["rouquin","familier","红发（口语，有时带玩笑）"],["blond","courant","金发的"],["brun","courant","棕/黑发的"]],"fq":"中频。","me":"rousse 想成 rouge：红头发。","tr":{"zh":"她有红头发，还有雀斑。","fr":"Elle a les cheveux roux et des taches de rousseur.","alt":"Elle est rousse, avec des taches de rousseur.","note":"cheveux 是阳性复数，所以用 roux。"}},
 "Sociable": {"pos":"adj. 形容词，阴阳同形，复数 sociables","s":"善于交际的，外向的，喜欢和人相处的。也用于动物：un animal sociable。反义：timide、solitaire。","ipa":"[sɔ.sjabl]","ph":"so [sɔ]；cia 读 [sja]；-ble 读 [bl]；结尾 e 不发音。","pi":"ci 读 [sj]，不是 [ki]；最后的 -ble 要轻读，不要加元音。","et":"拉丁语 sociabilis，来自 socius（同伴）。同源：société, associer。","ex":[["Elle est sociable.","她很外向。"],["Mon voisin est très sociable, il parle à tout le monde.","我的邻居很爱交际，他和所有人说话。"],["Les chats ne sont pas très sociables.","猫不太合群。"]],"co":[["être sociable","善于交际"],["peu sociable","不太合群"],["un enfant sociable","合群的孩子"]],"sy":[["extraverti","courant","外向的"],["ouvert","courant","开朗的"],["timide","courant","反义：害羞的"]],"fq":"中频。","me":"sociable = 愿意做 social 的人。","tr":{"zh":"我的同事很外向，认识所有人。","fr":"Ma collègue est très sociable, elle connaît tout le monde.","alt":"Ma collègue est super sociable, elle connaît tout le monde.","note":"sociable 阴阳同形。"}},
 "Solidaire": {"pos":"adj. 形容词，阴阳同形，复数 solidaires","s":"团结的，互相支持的，同舟共济的。être solidaire de qqn = 声援、与某人站在一起。名词 la solidarité；une économie solidaire = 社会互助经济。","ipa":"[sɔ.li.dɛʁ]","ph":"so [sɔ]；li；dai 读 [dɛ]；r 读 [ʁ]；重音在最后。","pi":"-aire 读 [ɛʁ]，r 要发音。","et":"与 solide、solidarité 同源（拉丁语 solidus，坚固的）。","ex":[["L'équipe est solidaire.","这支团队很团结。"],["Nous sommes solidaires avec les victimes.","我们声援受害者。"],["Il reste solidaire de ses collègues.","他与同事站在一起。"]],"co":[["être solidaire de qqn","声援某人"],["se montrer solidaire","表现出团结"],["une économie solidaire","互助经济"]],"sy":[["uni","courant","团结一致的"],["soudé","courant","紧密团结的"],["égoïste","courant","反义：自私的"]],"fq":"中频。","me":"solidaire：像 solide 一样紧紧抱团。","tr":{"zh":"邻居们在困难时互相支持。","fr":"Les voisins sont solidaires dans les moments difficiles.","alt":"Les voisins s'entraident quand c'est dur.","note":"solidaire 复数加 s。"}},
 "Stressé(e)": {"pos":"adj. 形容词，阴性 stressée，复数 stressés / stressées","s":"压力大的，紧张的。感受到压力用 stressé；让人有压力用 stressant。名词 le stress；动词 stresser（紧张；使紧张）。","ipa":"[stʁɛ.se] / [stʁɛ.se]","ph":"s-t-r 连读 [stʁ]，不加元音；ss 读 [s]；é [e]。","pi":"stress 开头不要加 e；r 是小舌音 [ʁ]。","et":"来自英语 stress（20 世纪借入）+ -é。同源：stressant。","ex":[["Je suis stressé.","我压力很大。"],["Elle est stressée avant l'examen.","她考试前很紧张。"],["Ne sois pas stressé, tout va bien.","别紧张，一切都好。"]],"co":[["être stressé par qqch","因某事而压力大"],["se sentir stressé","觉得紧张"],["un travail stressant","让人压力大的工作"]],"sy":[["anxieux","courant","焦虑的"],["tendu","courant","紧绷的"],["zen","familier","反义：很放松"]],"fq":"高频，口语常用。","me":"stressé：受到 stress 的人。","tr":{"zh":"考试前我很紧张。","fr":"Avant l'examen, je suis très stressé.","alt":"Avant l'examen, je stresse.","note":"stresser 也可用作自动词：je stresse。"}},
 "Vieux / Vieil / Vieille": {"pos":"adj. 形容词，阳性 vieux；阳性单数元音/哑 h 前用 vieil；阴性 vieille；阳性复数 vieux","s":"老的，旧的，年长的。un vieil homme / un vieil ami / un vieil arbre（元音前用 vieil）；une vieille dame。mon vieux = 老兄（口语）。对人用 âgé 更礼貌。","ipa":"[vjø] / [vjɛj] / [vjɛj]","ph":"vieux [vjø]（x 不发音）；vieil / vieille 都读 [vjɛj]；ill = [j]。","pi":"vieux 的 x 不读；vieil 在元音前，和 vieille 同音。","et":"拉丁语 vetulus（有点老的），vetus（老）的指小形式。同源：vétéran。","ex":[["Mon chien est vieux.","我的狗老了。"],["Un vieil ami m'a appelé.","一位老朋友给我打了电话。"],["Elle a une vieille voiture.","她有一辆旧车。"]],"co":[["un vieil homme","老人"],["une vieille dame","老太太"],["mon vieux / ma vieille","老兄 / 老友"],["vieux jeu","过时的"]],"sy":[["âgé","courant","年长的（对人更礼貌）"],["ancien","courant","从前的、古老的"],["jeune","courant","反义：年轻的"]],"fq":"极高频。","me":"元音前用 vieil，其余 vieux，阴性 vieille：记 3 形。","tr":{"zh":"我爷爷有一位老朋友。","fr":"Mon grand-père a un vieil ami.","alt":"Mon grand-père a un vieux copain.","note":"元音前阳性单数用 vieil。"}},
 "Maintenant": {"pos":"adv. 副词，不变","s":"现在，此刻。maintenant que + 句子 = 既然/现在……了。dès maintenant = 从现在起。比 actuellement（目前）更强调「此刻」。","ipa":"[mɛ̃t.nɑ̃]","ph":"main [mɛ̃]；te [t]；nant [nɑ̃]；常读 [mɛ̃t.nɑ̃]，e 可省略。","pi":"ain 是鼻化元音 [ɛ̃]，不读 [ain]；nant 读 [nɑ̃]，t 不发音。","et":"main（手）+ tenant（tenir 的现在分词）：本义「手里握着」，即「此刻」。同源：maintenir。","ex":[["Je mange maintenant.","我现在吃饭。"],["Maintenant, tu peux partir.","现在你可以走了。"],["Maintenant que tu es là, on commence.","既然你来了，我们开始吧。"]],"co":[["dès maintenant","从现在起"],["maintenant que + phrase","既然……"],["à partir de maintenant","从现在开始"],["jusqu'à maintenant","到目前为止"]],"sy":[["à présent","soutenu","目前、此刻"],["actuellement","courant","目前（一段时期）"],["là","familier","这会儿（口语）"]],"fq":"极高频。","me":"main + tenant：手里正拿着 = 现在。","tr":{"zh":"我现在得走了。","fr":"Je dois partir maintenant.","alt":"Là, il faut que j'y aille.","note":"devoir + 动词原形。"}},
 "Rarement": {"pos":"adv. 副词，不变","s":"很少，难得。放在动词后：Il pleut rarement。复合时态放在助动词和过去分词之间：Je n'ai rarement vu ça。反义：souvent。","ipa":"[ʁaʁ.mɑ̃]","ph":"rare [ʁaʁ] + ment [mɑ̃]；两个 r 都读小舌音；-ment 读 [mɑ̃]。","pi":"-ment 读 [mɑ̃]，不读 [mənt]；rare 的 e 不发音。","et":"形容词 rare（拉丁语 rarus）+ 副词后缀 -ment。","ex":[["Il pleut rarement ici.","这里很少下雨。"],["Je mange rarement au restaurant.","我很少在餐馆吃饭。"],["Elle sort rarement le soir.","她晚上很少出门。"]],"co":[["très rarement","极少"],["ne… que rarement","只是偶尔"],["plus rarement","更少地"]],"sy":[["peu souvent","courant","不常"],["presque jamais","courant","几乎从不"],["souvent","courant","反义：常常"]],"fq":"中高频。","me":"rare + ment：就是「稀有地」。","tr":{"zh":"我很少看电视。","fr":"Je regarde rarement la télé.","alt":"Je ne regarde presque jamais la télé.","note":"rarement 放在动词后。"}},
 "Tard": {"pos":"adv. 副词，不变；也可作 n.m.（sur le tard 到晚年）","s":"晚，迟。指时间晚：Il est tard = 很晚了。plus tard = 以后；tard dans la nuit = 深夜。和 en retard（迟到，晚于约定时间）不同。","ipa":"[taʁ]","ph":"t [t]；a [a]；r [ʁ]；d 不发音。","pi":"拼写有 d 但不读，读 [taʁ]；tard ≠ en retard。","et":"拉丁语 tarde（慢地），来自 tardus（慢的）。同源：retard, tardif。","ex":[["Il rentre tard.","他回家晚。"],["Il est tard, je vais me coucher.","很晚了，我去睡觉了。"],["On se voit plus tard.","我们回头见。"]],"co":[["plus tard","以后"],["trop tard","太晚了"],["tôt ou tard","迟早"],["au plus tard","最迟"]],"sy":[["tardivement","soutenu","较晚地、迟迟地"],["en retard","courant","迟到（晚于约定）"],["tôt","courant","反义：早"]],"fq":"极高频。","me":"tard 的 d 不读：[taʁ]，像 tar。","tr":{"zh":"昨晚我睡得很晚。","fr":"Hier soir, je me suis couché tard.","alt":"Hier, je me suis couché très tard.","note":"se coucher tard。"}},
 "Tôt": {"pos":"adv. 副词，不变","s":"早。se lever tôt = 早起；trop tôt = 太早；au plus tôt = 最早。tôt ou tard = 迟早。反义：tard。指「比约定时间早」要用 en avance。","ipa":"[to]","ph":"ô 带帽子，读 [o]；结尾 t 不发音。","pi":"ô 带帽子，t 不读，读 [to]；和 tard 对比：tôt 早，tard 晚。","et":"古法语 tost；现代 ô 的帽子代替了失去的 s。来源不确定。","ex":[["Je me lève tôt.","我起得早。"],["Il est trop tôt pour partir.","现在走还太早。"],["On se couche tôt ce soir.","今晚我们早睡。"]],"co":[["se lever tôt","早起"],["trop tôt","太早"],["tôt le matin","清晨"],["au plus tôt","最早"]],"sy":[["de bonne heure","courant","一大早、很早"],["en avance","courant","提前（相对约定时间）"],["tard","courant","反义：晚"]],"fq":"极高频。","me":"tôt 的帽子：早起戴帽子出门。","tr":{"zh":"明天我得早起。","fr":"Demain, je dois me lever tôt.","alt":"Demain, il faut que je me lève de bonne heure.","note":"il faut que + 虚拟式。"}},
 "Toujours": {"pos":"adv. 副词，不变","s":"总是，一直；还在，仍然。Il habite toujours à Lyon = 他还住在里昂。toujours pas = 仍然没有。pour toujours = 永远。注意不要和 tous les jours（每天）混。","ipa":"[tu.ʒuʁ]","ph":"tou [tu]；jours [ʒuʁ]；j 读 [ʒ]；末尾 s 不发音。","pi":"toujours 末尾 s 不读；ou 读 [u]，不是 [au]。","et":"tous + jours（古法语 toz jors）= 所有的日子。","ex":[["Je suis toujours en retard.","我总是迟到。"],["Il habite toujours à Lyon.","他还住在里昂。"],["Elle n'est toujours pas là.","她还没到。"]],"co":[["pour toujours","永远"],["comme toujours","和往常一样"],["toujours pas","仍然没有"],["depuis toujours","从来就"]],"sy":[["tout le temps","courant","一直、老是"],["encore","courant","还、仍然"],["jamais","courant","反义：从不"]],"fq":"极高频。","me":"tou-jours = 所有的 jours：天天 = 总是。","tr":{"zh":"他总是迟到。","fr":"Il arrive toujours en retard.","alt":"Il est toujours en retard.","note":"toujours 在动词后。"}},
 "À quelle heure ?": {"pos":"loc. 疑问短语","s":"几点？问事情发生的时间：À quelle heure tu pars ? 回答用 à + 时刻：À huit heures。注意和 Quelle heure est-il ?（现在几点？）不同。","ipa":"[a kɛl œʁ]","ph":"quelle [kɛl]；heure [œʁ]，h 不发音，两词连读 [kɛ.lœʁ]。","pi":"heure 的 h 不读，eu 读 [œ]；à 带重音符号，不要写成 a。","et":"quel（拉丁语 qualis）+ heure（拉丁语 hora）。","ex":[["À quelle heure tu arrives ?","你几点到？"],["À quelle heure commence le film ?","电影几点开始？"],["À quelle heure est-ce que tu te lèves ?","你几点起床？"]],"co":[["Quelle heure est-il ?","现在几点？"],["à huit heures","八点钟"],["à l'heure","准时"],["de bonne heure","一大早"]],"sy":[["Tu viens vers quelle heure ?","courant","你大约几点来？"],["Quand ?","courant","什么时候？"],["Quelle heure est-il ?","courant","现在几点（不同问题）"]],"fq":"极高频，日常问时间用。","me":"À quelle heure：「在什么钟点」。","tr":{"zh":"电影几点开始？","fr":"À quelle heure commence le film ?","alt":"Le film commence à quelle heure ?","note":"疑问词放前时，主语与动词倒装或加 est-ce que。"}},
 "Bon voyage !": {"pos":"loc. 祝福语","s":"旅途愉快！对出发的人说。其他类似：Bonne route !（开车）、Bon vol !（飞机）、Bon séjour !（逗留愉快）。也可说 souhaiter bon voyage à qqn。","ipa":"[bɔ̃ vwa.jaʒ]","ph":"bon [bɔ̃] 鼻化；voyage [vwa.jaʒ]；voy = [vwa.j]；g 读 [ʒ]。bon 与 voyage 之间不连读。","pi":"oy 读 [waj]；bon 的 n 不发音；ge 读 [ʒ]，不是 [dʒ]。","et":"voyage ← 晚期拉丁语 viaticum（旅途用品，源自 via 路）。bon = 好。","ex":[["Bon voyage en France !","法国之行愉快！"],["Elle part demain, je lui souhaite bon voyage.","她明天出发，我祝她旅途愉快。"],["Merci ! À bientôt !","谢谢！回头见！"]],"co":[["Bonne route !","一路顺风！（开车）"],["Bon vol !","飞行愉快！"],["souhaiter bon voyage à qqn","祝某人旅途愉快"],["un voyage organisé","跟团旅行"]],"sy":[["Bonne route !","courant","一路顺风（驾车）"],["Bon séjour !","courant","逗留愉快"],["Bon vol !","courant","飞行愉快"]],"fq":"极高频，告别时用。","me":"bon + voyage：就是「好的旅程」。","tr":{"zh":"你们明天出发吗？旅途愉快！","fr":"Vous partez demain ? Bon voyage !","alt":"Vous partez demain ? Bonne route !","note":"bon + 阳性名词。"}},
 "Faire une nuit blanche": {"pos":"loc. 动词短语；faire 不规则（j'ai fait），nuit 阴性，blanche 是 blanc 的阴性","s":"熬夜，通宵不睡。字面是「白色的夜」，blanc 在这里表示「空白、没睡」。也说 passer une nuit blanche。注意：不是白夜（极地的夜晚不黑）。","ipa":"[fɛʁ yn nɥi blɑ̃ʃ]","ph":"faire [fɛʁ]；nuit [nɥi]；blanche [blɑ̃ʃ]。une nuit 连读。","pi":"nuit 读 [nɥi]（嘴唇圆再放开），不要读成 [nwi]；blanche 的 an 是 [ɑ̃]。","et":"blanc 在这里指「空白、没睡」的说法来源不确定。同类说法：carte blanche, voter blanc。","ex":[["J'ai fait une nuit blanche.","我熬了一整夜。"],["Il a passé une nuit blanche à réviser.","他通宵复习。"],["Avant les examens, les étudiants font des nuits blanches.","考试前，学生们会熬夜。"]],"co":[["passer une nuit blanche","熬一整夜"],["une nuit blanche à + inf.","通宵做……"],["la Nuit blanche (Paris)","巴黎的通宵艺术节"]],"sy":[["ne pas fermer l'œil","courant","一夜没合眼"],["veiller toute la nuit","courant","整夜不睡"],["passer une nuit blanche","courant","同义说法"]],"fq":"中高频，学生生活里常用。","me":"blanche = 一片空白：没闭眼，一夜白。","tr":{"zh":"为了赶完报告，我熬了通宵。","fr":"J'ai fait une nuit blanche pour finir mon rapport.","alt":"J'ai passé la nuit à finir mon rapport.","note":"pour + 动词原形 = 为了。"}},
 "(Faire) la lessive": {"pos":"loc. 动词短语；lessive 是 n.f. 阴性名词（洗衣；洗衣液/洗衣粉）","s":"洗衣服。faire la lessive = 做洗衣这件事；lessive 也指洗衣液/洗衣粉（de la lessive）。口语常说 faire une machine（洗一机衣服）。","ipa":"[fɛʁ la lɛ.siv]","ph":"lessive [lɛ.siv]；ss 读 [s]；结尾 e 不发音。","pi":"ss 读 [s]，不是 [z]；lessive 不是「课」。","et":"拉丁语 lixivia（碱水、灰水，旧时用来洗衣）。","ex":[["Je fais la lessive le samedi.","我每个星期六洗衣服。"],["Il n'y a plus de lessive.","洗衣液用完了。"],["Elle étend la lessive sur le balcon.","她在阳台上晾衣服。"]],"co":[["faire la lessive","洗衣服"],["étendre la lessive","晾衣服"],["de la lessive en poudre / liquide","洗衣粉 / 洗衣液"],["une machine à laver","洗衣机"]],"sy":[["laver le linge","courant","洗衣物"],["faire une machine","familier","洗一机衣服"],["le linge","courant","衣物"]],"fq":"中高频。","me":"lessive：洗衣液，faire la lessive：把脏衣服洗干净。","tr":{"zh":"周末我在家洗衣服。","fr":"Le week-end, je fais la lessive à la maison.","alt":"Le week-end, je fais une machine à la maison.","note":"faire la lessive：不加 de。"}},
 "(Faire) un jogging/footing": {"pos":"loc. 动词短语；jogging 和 footing 都是阳性名词（un jogging / un footing）","s":"慢跑。faire un footing / faire du jogging = 去慢跑。注意：un jogging 也指运动服（运动裤）：Il met son jogging。footing 是法语自造的「伪英语」词，英语里不这么说。","ipa":"[dʒɔ.ɡiŋ] / [fu.tiŋ]","ph":"jogging [dʒɔ.ɡiŋ]；footing [fu.tiŋ]；-ing 读 [iŋ]。","pi":"-ing 读 [iŋ]，ng 是鼻音；foo 读 [fu]。","et":"jogging 借自英语；footing 是法国人用 foot + -ing 造的词（伪英语）。","ex":[["Il fait un jogging tous les matins.","他每天早上慢跑。"],["Je vais faire un footing au parc.","我去公园慢跑。"],["Il met son jogging pour rester à la maison.","他穿着运动裤待在家里。"]],"co":[["faire un footing","慢跑"],["faire du jogging","做慢跑运动"],["un pantalon de jogging","运动裤"],["aller courir","去跑步"]],"sy":[["courir","courant","跑步"],["faire de la course à pied","courant","跑步运动"],["un survêtement","courant","运动服"]],"fq":"中频。","me":"footing = 用 foot（脚）跑。","tr":{"zh":"星期天早上我去慢跑。","fr":"Le dimanche matin, je fais un footing.","alt":"Le dimanche matin, je vais courir.","note":"faire un footing / du jogging。"}},
 "Aller sur internet": {"pos":"loc. 动词短语；aller 不规则，助动词 être","s":"上网。aller sur internet = 去网上（上网查东西、浏览）。介词用 sur，不是 dans。internet 前一般不加冠词。口语说 aller en ligne、surfer sur le net。","ipa":"[a.le syʁ ɛ̃.tɛʁ.nɛt]","ph":"aller [a.le]；sur [syʁ]；internet [ɛ̃.tɛʁ.nɛt]；in 读 [ɛ̃]。","pi":"sur 的 u 读 [y]；internet 开头 in 是鼻化元音，t 要读出。","et":"internet 借自英语（inter + net，「网络之间」）。aller ← 拉丁语 ambulare 等的混合，来源复杂。","ex":[["J'aime aller sur internet.","我喜欢上网。"],["Je vais sur internet pour chercher une recette.","我上网找一个食谱。"],["Tu peux aller sur internet avec ton téléphone ?","你能用手机上网吗？"]],"co":[["chercher sur internet","在网上找"],["acheter sur internet","网购"],["une connexion internet","网络连接"],["aller en ligne","上网"]],"sy":[["surfer sur le net","familier","上网冲浪"],["naviguer sur internet","courant","浏览网页"],["se connecter","courant","连接（登录）"]],"fq":"极高频。","me":"sur internet：像在「网面上」滑行。","tr":{"zh":"晚上我常上网找资料。","fr":"Le soir, je vais souvent sur internet pour chercher des infos.","alt":"Le soir, je surfe souvent sur le net pour chercher des infos.","note":"sur internet，不用 dans。"}},
 "Du bruit": {"pos":"n.m. 阳性名词，复数 bruits；du = de + le（部分冠词，不可数）","s":"噪音，响声。du bruit = 噪音（不可数）；un bruit = 一声响。faire du bruit = 制造噪音；le bruit court que… = 传闻……。","ipa":"[bʁɥi]","ph":"br [bʁ]；ui 读 [ɥi]；结尾 t 不发音。","pi":"ui 读 [ɥi]，不是 [wi]；结尾 t 不读。","et":"来自动词 bruire（发出嗡嗡/轰鸣声），更早的词源有争议。同源：bruyant, bruitage。","ex":[["Il y a beaucoup de bruit ici.","这里很吵。"],["Je n'entends rien avec tout ce bruit.","有这么多噪音我什么都听不见。"],["J'ai entendu un bruit dans la cuisine.","我在厨房里听到一个声响。"]],"co":[["faire du bruit","发出噪音"],["un bruit de fond","背景噪音"],["sans bruit","悄悄地"],["le bruit court que…","传闻……"]],"sy":[["vacarme","courant","喧闹声、吵闹"],["boucan","familier","吵闹声"],["silence","courant","反义：安静"]],"fq":"极高频。","me":"bruit ≈ brute：粗大的响声。","tr":{"zh":"邻居们吵得很厉害。","fr":"Les voisins font beaucoup de bruit.","alt":"Les voisins font un boucan d'enfer.","note":"faire du bruit / beaucoup de bruit。"}},
 "Le rez-de-chaussée": {"pos":"n.m. 阳性名词，复数不变 des rez-de-chaussée；缩写 RDC","s":"底楼，一楼。法国的楼层从 rez-de-chaussée 开始：二楼 = le premier étage，三楼 = le deuxième étage。和美式「first floor」不同。","ipa":"[ʁe.d(ə).ʃo.se]","ph":"rez 读 [ʁe]（z 不发音）；de [də] 常弱化；chaussée [ʃo.se]。","pi":"rez 的 z 不读；chaussée 的 ch 读 [ʃ]；整词很长，分成 rez / de / chaus / sée。","et":"rez（古法语 res，「贴着、齐平」）+ de + chaussée（路面）：「与路面齐平」。","ex":[["Il habite au rez-de-chaussée.","他住在一楼。"],["L'ascenseur s'arrête au rez-de-chaussée.","电梯停在一楼。"],["Mon appartement est au premier étage.","我的公寓在二楼（法国楼层）。"]],"co":[["au rez-de-chaussée","在一楼"],["un appartement en rez-de-chaussée","一楼的公寓"],["le premier étage","二楼（法国说法）"]],"sy":[["RDC","courant","缩写"],["le rez-de-jardin","courant","与花园齐平的一层"],["l'étage","courant","楼层"]],"fq":"中高频，住房话题必用。","me":"rez = 贴地；chaussée = 路：与地面齐平。","tr":{"zh":"我的公寓在一楼，带一个小花园。","fr":"Mon appartement est au rez-de-chaussée, avec un petit jardin.","alt":"J'habite en rez-de-chaussée, avec un petit jardin.","note":"au = à + le（楼层用 à / au）。"}},
 "Un appareil électroménager": {"pos":"n.m. 阳性名词，复数 des appareils électroménagers","s":"家用电器（冰箱、洗衣机等）。le gros électroménager = 大家电；le petit électroménager = 小家电。appareil 本身也指「器具；相机；助听器」，électroménager 常单独作名词。","ipa":"[a.pa.ʁɛj e.lɛk.tʁo.me.na.ʒe]","ph":"appareil [a.pa.ʁɛj]；électroménager [e.lɛk.tʁo.me.na.ʒe]；eil 读 [ɛj]。","pi":"-eil 读 [ɛj]，l 不读；électroménager 很长，分成 é-lec-tro-mé-na-gé。","et":"appareil ← appareiller（准备、配备）；électro-（希腊语 elektron）+ ménager（家务的）。","ex":[["J'achète un nouvel appareil électroménager.","我买了一件新家电。"],["Le frigo et le lave-linge sont des appareils électroménagers.","冰箱和洗衣机都是家用电器。"],["Il y a un magasin d'électroménager près de chez moi.","我家附近有一家家电店。"]],"co":[["un magasin d'électroménager","家电店"],["le gros électroménager","大家电"],["le petit électroménager","小家电"]],"sy":[["l'électroménager","courant","家电（总称）"],["un appareil","courant","器具、设备（也指相机）"],["une machine","courant","机器"]],"fq":"中频，购物和家居话题常用。","me":"électro（电）+ ménager（家务）= 电动家务机。","tr":{"zh":"我们得买一件新家电。","fr":"Nous devons acheter un nouvel appareil électroménager.","alt":"Il faut qu'on achète un nouvel appareil électroménager.","note":"元音前 nouveau → nouvel。"}},
 "Un balcon": {"pos":"n.m. 阳性名词，复数 balcons","s":"阳台。sur le balcon = 在阳台上。也指剧院的包厢/楼座（le balcon）。比 terrasse（露台，更大）小，一般挂在楼外。","ipa":"[bal.kɔ̃]","ph":"bal [bal]；con 读 [kɔ̃]；c 读 [k]；n 不发音。","pi":"on 是鼻化元音 [ɔ̃]，不读 n；重音在最后。","et":"意大利语 balcone，源自日耳曼语 balk（横梁）。","ex":[["Il y a des fleurs sur le balcon.","阳台上有花。"],["Je prends mon café sur le balcon.","我在阳台上喝咖啡。"],["Notre appartement a un grand balcon.","我们的公寓有一个大阳台。"]],"co":[["sur le balcon","在阳台上"],["un balcon fleuri","开满花的阳台"],["un appartement avec balcon","带阳台的公寓"]],"sy":[["terrasse","courant","露台（更大）"],["loggia","courant","凹进去的阳台"],["véranda","courant","玻璃封闭阳台/暖房"]],"fq":"中高频，住房话题常用。","me":"balcon 去掉 y：balcony → balcon。","tr":{"zh":"夏天我们在阳台上吃饭。","fr":"En été, on mange sur le balcon.","alt":"L'été, nous dînons sur le balcon.","note":"sur le balcon。"}},
 "Un barbecue": {"pos":"n.m. 阳性名词，复数 barbecues；口语 un barbeuc","s":"烧烤，烤肉。可指烧烤炉，也指烧烤聚会。faire un barbecue = 办烧烤。也说 faire des grillades（烤肉）。","ipa":"[baʁ.bə.kju]","ph":"bar [baʁ]；be [bə]；cue 读 [kju]；r 是小舌音。","pi":"拼写和英语相同但读音不同：r 要发 [ʁ]；cue 读 [kju]。","et":"经西班牙语 barbacoa 借自泰诺语（加勒比）。","ex":[["Nous faisons un barbecue dimanche.","星期天我们烧烤。"],["Ils allument le barbecue dans le jardin.","他们在花园里点燃烧烤炉。"],["On mange des saucisses au barbecue.","我们吃烤香肠。"]],"co":[["faire un barbecue","办烧烤"],["allumer le barbecue","点燃烧烤炉"],["un barbecue au charbon / à gaz","炭烤 / 燃气烧烤炉"]],"sy":[["grillade","courant","烤肉"],["plancha","courant","铁板烧"],["barbeuc","familier","烧烤（口语）"]],"fq":"中高频。","me":"barbecue = 一起 bar-be-cue：派对感。","tr":{"zh":"这个周末我们在花园里烧烤。","fr":"Ce week-end, on fait un barbecue dans le jardin.","alt":"Ce week-end, on fait des grillades dans le jardin.","note":"on = nous（口语）。"}},
 "Un bureau": {"pos":"n.m. 阳性名词，复数 bureaux（-eau 的复数加 x）","s":"办公室；书桌。Il travaille dans son bureau = 他在办公室工作。也指某些机构：un bureau de poste（邮局）、un bureau de tabac（烟草店）。","ipa":"[by.ʁo]","ph":"bu [by] 圆唇音；reau 读 [ʁo]；复数 bureaux 读音不变。","pi":"bu 的 u 读 [y]，不是 [u]；复数是 bureaux，不是 bureaus。","et":"古法语 burel（粗呢料，铺在桌上的布），因此指书桌，后指办公室。","ex":[["Il travaille dans son bureau.","他在他的办公室工作。"],["Mon bureau est près de la fenêtre.","我的书桌靠窗。"],["Je vais au bureau en métro.","我坐地铁去上班。"]],"co":[["aller au bureau","去上班（去办公室）"],["un bureau de poste","邮局"],["un bureau de tabac","烟草店"],["un employé de bureau","办公室职员"]],"sy":[["cabinet","courant","医生/律师的诊所/事务所"],["agence","courant","代理处、办事处"],["table de travail","courant","书桌（泛称）"]],"fq":"极高频。","me":"bureau 里有 u：用 u 圆嘴发 [y]，像在办公。","tr":{"zh":"我的办公室在二楼。","fr":"Mon bureau est au premier étage.","alt":"Mon bureau se trouve au premier étage.","note":"法国：premier étage = 二楼。"}},
 "Un cafard": {"pos":"n.m. 阳性名词，复数 cafards","s":"蟑螂。avoir le cafard = 情绪低落、闷闷不乐（常因天气或孤独）。儿童语里 cafard 还可指「告密者」。","ipa":"[ka.faʁ]","ph":"ca [ka]；fard 读 [faʁ]；d 不发音。","pi":"d 不读：cafard [ka.faʁ]，不要和 café 混。","et":"来自阿拉伯语 kāfir（异教徒），先指伪善者，后指蟑螂，再引申出「情绪低落」。细节有争议。","ex":[["Il y a un cafard dans la cuisine !","厨房里有一只蟑螂！"],["J'ai peur des cafards.","我怕蟑螂。"],["Aujourd'hui, j'ai le cafard.","今天我情绪低落。"]],"co":[["avoir le cafard","情绪低落"],["donner le cafard à qqn","让人沮丧"],["un nid de cafards","蟑螂窝"]],"sy":[["blatte","soutenu","蟑螂（更书面/专业）"],["cancrelat","courant","大蟑螂（热带）"],["avoir le blues","familier","情绪低落"]],"fq":"中频。","me":"cafard ≠ café：cafard 在墙缝里，café 在杯子里。","tr":{"zh":"厨房里有蟑螂，我好怕！","fr":"Il y a un cafard dans la cuisine, j'ai peur !","alt":"Y a un cafard dans la cuisine ! J'ai peur !","note":"Il y a → 口语 Y a。"}},
 "Un camion": {"pos":"n.m. 阳性名词，复数 camions","s":"卡车，货车。un chauffeur de camion = 卡车司机。较小的货车叫 une camionnette（小货车）。un camion de pompiers = 消防车。","ipa":"[ka.mjɔ̃]","ph":"ca [ka]；mi [mj]；on [ɔ̃] 鼻化；n 不发音。","pi":"ion 读 [jɔ̃]，不要读出 n；重音在最后。","et":"来源不确定。同源词：camionnette, camionneur。","ex":[["Le camion est rouge.","卡车是红色的。"],["Un camion bloque la rue.","一辆卡车堵住了街道。"],["Mon père est chauffeur de camion.","我爸爸是卡车司机。"]],"co":[["un chauffeur de camion","卡车司机"],["un camion de livraison","送货卡车"],["un camion de pompiers","消防车"]],"sy":[["poids lourd","courant","重型货车"],["camionnette","courant","小货车"],["fourgon","courant","厢式货车"]],"fq":"高频。","me":"camion ≈ 大车，别和 camping 混。","tr":{"zh":"一辆大卡车堵住了路。","fr":"Un gros camion bloque la route.","alt":"Il y a un gros camion qui bloque la route.","note":"bloquer = 堵住。"}},
 "Un canapé": {"pos":"n.m. 阳性名词，复数 canapés","s":"沙发。un canapé-lit = 沙发床。另有「开胃小点心」的意思（一小片面包上放食物）。","ipa":"[ka.na.pe]","ph":"ca [ka]；na [na]；pé [pe]；每个音节同样轻重，é 读 [e]。","pi":"é 在词尾读 [e]，不是 [ei]。","et":"拉丁语 conopeum（蚊帐），来自希腊语 konopeion。最初指带蚊帐的床。","ex":[["Le canapé est très confortable.","沙发很舒服。"],["Il dort sur le canapé.","他睡在沙发上。"],["Nous avons un canapé-lit pour les invités.","我们有一张给客人用的沙发床。"]],"co":[["un canapé-lit","沙发床"],["un canapé en cuir","皮沙发"],["un canapé d'angle","转角沙发"]],"sy":[["sofa","courant","沙发（同义）"],["divan","soutenu","长沙发（略旧式）"],["canap'","familier","沙发（缩略）"]],"fq":"高频。","me":"canapé ← canopy：床上的纱帐。","tr":{"zh":"孩子们在沙发上看电视。","fr":"Les enfants regardent la télé sur le canapé.","alt":"Les gamins regardent la télé sur le canapé.","note":"sur le canapé。"}},
 "Un congélateur": {"pos":"n.m. 阳性名词，复数 congélateurs","s":"冰柜，冷冻柜。mettre au congélateur = 放进冷冻。冷藏是 le réfrigérateur（口语 le frigo）。动词 congeler = 冷冻；surgelé = 速冻的。","ipa":"[kɔ̃.ʒe.la.tœʁ]","ph":"con [kɔ̃]；gé [ʒe]；la；teur [tœʁ]；g 读 [ʒ]。","pi":"con 是鼻化元音；-eur 读 [œʁ]，r 要发音；g 读 [ʒ]。","et":"congeler ← 拉丁语 congelare（con + gelare，冻结），gelu = 霜、冰。","ex":[["Il y a de la glace dans le congélateur.","冷冻柜里有冰淇淋。"],["Je mets le poisson au congélateur.","我把鱼放进冷冻柜。"],["Le congélateur est plein.","冰柜满了。"]],"co":[["mettre au congélateur","放进冷冻"],["congeler des aliments","冷冻食物"],["un plat surgelé","速冻食品"]],"sy":[["réfrigérateur","courant","冰箱（冷藏）"],["frigo","familier","冰箱"],["freezer","familier","冷冻室（借自英语）"]],"fq":"中频，厨房话题常用。","me":"congélateur = 「让东西 congeal」。","tr":{"zh":"别忘了把肉放进冷冻柜。","fr":"N'oublie pas de mettre la viande au congélateur.","alt":"Mets la viande au congélateur, s'il te plaît.","note":"oublier de + 动词原形。"}},
 "Un couloir": {"pos":"n.m. 阳性名词，复数 couloirs","s":"走廊，过道。au bout du couloir = 走廊尽头。un couloir de bus = 公交专用道；un couloir de nage = 泳道。corridor 也是走廊，更长更正式。","ipa":"[ku.lwaʁ]","ph":"cou [ku]；loir [lwaʁ]；oi 读 [wa]；r 小舌音。","pi":"ou 读 [u]，oi 读 [wa]；不是「颜色 color」。","et":"来自动词 couler（流动）+ -oir（表示场所/工具）：「通道」。","ex":[["Le couloir est long.","走廊很长。"],["Ma chambre est au bout du couloir.","我的房间在走廊尽头。"],["Ne laisse pas tes affaires dans le couloir.","别把东西放在走廊里。"]],"co":[["au bout du couloir","在走廊尽头"],["un couloir étroit","窄走廊"],["un couloir de bus","公交专用道"],["un couloir de nage","泳道"]],"sy":[["corridor","courant","走廊（更长）"],["passage","courant","通道"],["allée","courant","过道（座位间）"]],"fq":"高频。","me":"couloir ≈ 流过的路：走廊像小河。","tr":{"zh":"洗手间在走廊尽头。","fr":"Les toilettes sont au bout du couloir.","alt":"Les toilettes, c'est tout au bout du couloir.","note":"au bout de + 名词。"}},
 "Un cours": {"pos":"n.m. 阳性名词，单复数同形 des cours","s":"课，课程。avoir cours = 有课；suivre un cours = 听课；donner un cours = 授课。另有：le cours du dollar（汇率）、au cours de（在……期间）、un cours d'eau（河流）。","ipa":"[kuʁ]","ph":"cou [ku]；r 小舌音 [ʁ]；s 不发音；读 [kuʁ]。","pi":"cours、court、cour、course 的读音相近：cours [kuʁ] 课；court 短；cour 院子。","et":"拉丁语 cursus（奔跑；路线）。同源：courir, course, concours。","ex":[["Le cours commence à 9h.","课九点开始。"],["Elle donne des cours de piano.","她教钢琴课。"],["Au cours de l'année, nous visitons Paris.","这一年里我们参观巴黎。"]],"co":[["suivre un cours","听课"],["un cours de français","法语课"],["au cours de","在……期间"],["le cours du dollar","美元汇率"]],"sy":[["leçon","courant","一课（具体的一节）"],["classe","courant","班级；课时"],["cours magistral","courant","大课、讲座"]],"fq":"极高频。","me":"cours = 一段「跑道」：上课就是跑一程。","tr":{"zh":"我下午有一节法语课。","fr":"J'ai un cours de français cet après-midi.","alt":"Cet après-midi, j'ai cours de français.","note":"avoir cours：不加冠词。"}},
 "Un coussin": {"pos":"n.m. 阳性名词，复数 coussins","s":"靠垫；垫子。放在沙发、椅子或床上的软垫，也可以是坐垫（un coussin de chaise）。","ipa":"[ku.sɛ̃]","ph":"ou [u]；ss [s]；-in 读鼻化元音 [ɛ̃]。","pi":"-in 是鼻音 [ɛ̃]，不要读出 n；ou 读 [u]，不是 [o]。","et":"一般认为来自拉丁语 coxa（髋、大腿），指放在腿下的垫子；来源不完全确定。","ex":[["Il y a un coussin sur le canapé.","沙发上有个靠垫。"],["Mets un coussin derrière ton dos.","在你背后放个靠垫。"],["Le chat dort sur un coussin.","猫睡在一个垫子上。"]],"co":[["un coussin de canapé","沙发靠垫"],["un coussin moelleux","软软的靠垫"],["un coussin chauffant","电热垫"]],"sy":[["oreiller","courant","枕头（睡觉用）"],["pouf","courant","软凳、坐墩"]],"fq":"中频，家居常用。","me":"coussin 像「库-三」：库(ku)里堆着软软的垫子。","tr":{"zh":"把靠垫放在沙发上。","fr":"Mets le coussin sur le canapé.","alt":"Pose le coussin sur le canapé.","note":"mettre / poser + 物 + sur + 地方。"}},
 "Un étage": {"pos":"n.m. 阳性名词，复数 étages","s":"楼层。注意法国楼层算法：rez-de-chaussée 是一楼，le premier étage 是二楼（中国叫二楼），le deuxième étage 是三楼。","ipa":"[e.taʒ]","ph":"é [e]；-ge 读 [ʒ]；结尾 e 不发音。","pi":"premier étage = 二楼，不是一楼；一楼叫 rez-de-chaussée。结尾 -age 读 [aʒ]，不读 [ɑ̃]。","et":"来自古法语 estage（住处、层），与拉丁语 stare（站立）有关。","ex":[["Mon appartement est au premier étage.","我的公寓在二楼。"],["Il habite au troisième étage.","他住在四楼。"],["Il n'y a pas d'ascenseur jusqu'à l'étage.","上楼没有电梯。"]],"co":[["au premier étage","在二楼"],["un immeuble de cinq étages","五层楼的楼房"],["monter à l'étage","上楼"],["l'étage du dessus / du dessous","楼上 / 楼下"]],"sy":[["niveau","courant","层级、水平"],["palier","courant","楼梯平台、楼层门口"]],"fq":"高频，住宅话题必备。","me":"étage ≈ 一层一层「站」(stare) 着的楼。","tr":{"zh":"我家在这栋楼的二楼。","fr":"J'habite au premier étage de cet immeuble.","alt":"Je suis au premier étage de cet immeuble.","note":"premier étage = 二楼（一楼是 rez-de-chaussée）。"}},
 "Un fauteuil": {"pos":"n.m. 阳性名词，复数 fauteuils","s":"扶手椅；单人沙发。有扶手、能靠着坐的椅子。和 chaise（无扶手的普通椅子）区分。","ipa":"[fo.tœj]","ph":"au [o]；-euil 读 [œj]；整词 [fo.tœj]。","pi":"结尾 -euil 读 [œj]，不要把 l 读出来。","et":"法兰克语 faldistôl（折叠椅），经古法语 faudestuel 演变而来。","ex":[["Il lit dans son fauteuil.","他坐在扶手椅里看书。"],["Assieds-toi dans ce fauteuil, il est confortable.","坐这把椅子，很舒服。"],["Mon père dort dans le fauteuil.","我爸爸在扶手椅里睡着了。"]],"co":[["un fauteuil roulant","轮椅"],["un fauteuil de bureau","办公椅"],["s'asseoir dans un fauteuil","坐进扶手椅"]],"sy":[["chaise","courant","无扶手的椅子"],["canapé","courant","沙发"],["siège","courant","座位（泛指）"]],"fq":"中频，家居常用。","me":"fauteuil = 有扶手的；chaise = 没扶手的。","tr":{"zh":"她坐在窗边的扶手椅上。","fr":"Elle est assise dans le fauteuil près de la fenêtre.","alt":"Elle s'est installée dans le fauteuil près de la fenêtre.","note":"dans un fauteuil（用 dans，不用 sur）。"}},
 "Un four": {"pos":"n.m. 阳性名词，复数 fours","s":"烤箱；炉。cuire au four = 在烤箱里烤。口语 faire un four = 演出或电影票房惨败（familier）。","ipa":"[fuʁ]","ph":"f [f]；ou [u]；r 是喉音 [ʁ]，要读出来。","pi":"结尾 r 要发音：four [fuʁ]；fou（疯的）[fu] 不发 r，别混。","et":"拉丁语 furnus（炉、窑）。同族词：fournée（一炉）、fournil（烤面包的作坊）。","ex":[["Le gâteau est dans le four.","蛋糕在烤箱里。"],["Allume le four à 180 degrés.","把烤箱调到 180 度。"],["Ce poulet cuit au four pendant une heure.","这只鸡在烤箱里烤一个小时。"]],"co":[["cuire au four","用烤箱烤"],["allumer / éteindre le four","打开 / 关掉烤箱"],["un four électrique","电烤箱"],["un four à pain","面包炉"]],"sy":[["micro-onde","courant","微波炉"],["cuisinière","courant","炉灶（带烤箱）"],["fourneau","soutenu","旧式炉灶、熔炉"]],"fq":"高频，厨房常用。","me":"four 里的 r 要读：不是「fou」。","tr":{"zh":"蛋糕要在烤箱里烤四十分钟。","fr":"Le gâteau cuit quarante minutes au four.","alt":"Il faut laisser le gâteau quarante minutes au four.","note":"cuire au four（用 à + 定冠词 le → au）。"}},
 "Un grille-pain": {"pos":"n.m. 阳性名词，复数不变 des grille-pain","s":"烤面包机。由 griller（烤）和 pain（面包）组成的复合词；单复数同形。","ipa":"[ɡʁij.pɛ̃]","ph":"grille 中的 -ille 读 [ij]；pain 读 [pɛ̃]，ai 与 n 合成鼻音。","pi":"grille 的 ill 读 [ij]，不是 [il]；pain 的 n 不发音。复数不加 s：des grille-pain。","et":"griller（烤）+ pain（面包，拉丁语 panis）；griller 来自 gril（烤架，拉丁语 craticula）。","ex":[["Je fais du pain grillé avec le grille-pain.","我用烤面包机烤面包。"],["Mets deux tranches dans le grille-pain.","往烤面包机里放两片面包。"],["Le grille-pain est cassé.","烤面包机坏了。"]],"co":[["mettre du pain dans le grille-pain","把面包放进烤面包机"],["du pain grillé","烤面包片"],["une tranche de pain","一片面包"]],"sy":[["toasteur","courant","烤面包机的另一说法（借自英语）"],["pain grillé","courant","烤好的面包片（不是机器）"]],"fq":"中频，厨房家电。","me":"grille + pain：把面包「烤」一下。","tr":{"zh":"我的烤面包机坏了。","fr":"Mon grille-pain est cassé.","alt":"Mon grille-pain ne marche plus.","note":"ne marche plus = 不再能用。"}},
 "Un hall": {"pos":"n.m. 阳性名词，复数 halls（h 不发音但不连读）","s":"大厅；门厅。楼房入口处的 hall d'immeuble，也指车站、酒店、机场的大厅。","ipa":"[ol]","ph":"h 不发音，但是「有声 h」：le hall，不能说成 l'hall；a 读 [o]，ll 读 [l]。","pi":"读 [ol]，不是英语的 hall [hɔːl]；开头没有 h 音。","et":"借自英语 hall（大厅），19 世纪进入法语。","ex":[["Attends-moi dans le hall de l'immeuble.","在楼里的大厅等我。"],["Le hall de la gare est immense.","火车站大厅非常大。"],["Les boîtes aux lettres sont dans le hall.","邮箱在门厅里。"]],"co":[["le hall d'entrée","入口大厅"],["le hall d'immeuble","楼房门厅"],["le hall de gare","车站大厅"],["le hall d'un hôtel","酒店大堂"]],"sy":[["entrée","courant","入口、玄关"],["vestibule","soutenu","门厅（较正式）"],["réception","courant","前台、接待处"]],"fq":"中频，住宅与交通场景常见。","me":"hall 读「奥尔」：像 haut 里的 [o]。","tr":{"zh":"我们在楼里的大厅碰面吧。","fr":"On se retrouve dans le hall de l'immeuble.","alt":"Rendez-vous dans le hall de l'immeuble.","note":"se retrouver = 碰面；le hall（不能 l'hall）。"}},
 "Un immeuble": {"pos":"n.m. 阳性名词，复数 immeubles","s":"楼房；大楼（多层住宅或办公楼）。不是 maison（独栋房子）。","ipa":"[i.mœbl]","ph":"im- 读 [i]，mm 只读一个 [m]；-euble 读 [œbl]，e 不发音。","pi":"im 开头不读鼻音，是 [i.m]；和 meuble（家具）只差一个 im-，意思完全不同。","et":"拉丁语 immobilis（不可移动的），法律上指不动产；与 meuble（可移动的家具）相对。","ex":[["J'habite dans un grand immeuble.","我住在一栋大楼里。"],["Il y a un ascenseur dans l'immeuble.","楼里有电梯。"],["Cet immeuble a dix étages.","这栋楼有十层。"]],"co":[["un immeuble de dix étages","十层的楼房"],["un immeuble ancien","老楼"],["un immeuble de bureaux","办公楼"],["le gardien de l'immeuble","楼房管理员"]],"sy":[["bâtiment","courant","建筑物（泛指）"],["tour","courant","高层塔楼"],["résidence","courant","住宅小区"]],"fq":"高频，城市生活常用。","me":"im-meuble：不能「动」的楼；meuble：可以搬动的家具。","tr":{"zh":"我家在这栋楼的二楼。","fr":"J'habite au premier étage de cet immeuble.","alt":"Mon appartement est au premier étage de cet immeuble.","note":"premier étage = 二楼。"}},
 "Un journal": {"pos":"n.m. 阳性名词，复数 journaux","s":"报纸；日记（journal intime）；电视新闻（le journal de 20 h）。最常用的意思是报纸。","ipa":"[ʒuʁ.nal]","ph":"j [ʒ]；ou [u]；r [ʁ]；-al 读 [al]。复数 -aux 读 [o]。","pi":"j 读 [ʒ]，不是 [dʒ]；复数是 journaux [ʒuʁ.no]，不是 journals。","et":"拉丁语 diurnalis（每日的），来自 diurnus；同源：jour（日）。","ex":[["Il lit le journal tous les matins.","他每天早上读报。"],["Le journal de 20 heures commence.","晚八点的新闻开始了。"],["Elle écrit son journal chaque soir.","她每天晚上写日记。"]],"co":[["lire le journal","读报"],["un journal intime","日记"],["le journal télévisé","电视新闻"],["un journal en ligne","网络报纸"]],"sy":[["quotidien","courant","日报"],["magazine","courant","杂志"],["les infos","familier","新闻（口语）"]],"fq":"极高频，日常常用。","me":"journal ← jour：每天出的东西，所以是「日报」。","tr":{"zh":"你看今晚的新闻了吗？","fr":"Tu as regardé le journal de ce soir ?","alt":"Tu as vu les infos ce soir ?","note":"le journal = 电视新闻；les infos 更口语。"}},
 "Un lit": {"pos":"n.m. 阳性名词，复数 lits","s":"床。注意 lit 的 t 不发音，读 [li]，和动词 lire 的变位 il lit（他读）同形同音。","ipa":"[li]","ph":"t 不发音；整词只读 [li]。","pi":"il lit un livre（他读书）和 un lit（一张床）同音同形，靠语境分辨。","et":"拉丁语 lectus（床）。同源：literie（床上用品）。","ex":[["Je vais au lit.","我去睡觉。"],["Fais ton lit avant de partir !","走之前把床铺好！"],["On a un lit double.","我们有一张双人床。"]],"co":[["aller au lit","去睡觉"],["faire son lit","整理床铺"],["un lit double / simple","双人床 / 单人床"],["un lit superposé","上下铺"]],"sy":[["dodo","familier","睡觉（儿语）"],["pieu","argot","床（俚语）"],["couchette","courant","火车卧铺"]],"fq":"极高频，日常常用。","me":"在床上看书：lit 和 lit 一模一样。","tr":{"zh":"孩子们已经在床上了。","fr":"Les enfants sont déjà au lit.","alt":"Les enfants sont déjà couchés.","note":"être au lit / être couché。"}},
 "Un local à poubelles": {"pos":"n.m. 阳性名词，复数 locaux à poubelles","s":"垃圾房；楼里放垃圾桶的公共房间。un local 是「场所、房间」的名词，也可以说 un local poubelles。","ipa":"[lɔ.kal a pu.bɛl]","ph":"local 读 [lɔ.kal]；à 读 [a]；poubelles 读 [pu.bɛl]，ou [u]，-elles [ɛl]。","pi":"local 的复数是 locaux [lɔ.ko]，不是 locals。","et":"local 来自拉丁语 localis（locus「地方」）；poubelle 得名于巴黎警察局长 Eugène Poubelle，1884 年他下令使用垃圾桶。","ex":[["Je mets le sac dans le local à poubelles.","我把垃圾袋放进垃圾房。"],["Descends les sacs au local à poubelles.","把垃圾袋拿到垃圾房去。"],["Le local à poubelles est fermé à clé.","垃圾房上了锁。"]],"co":[["le local à poubelles","垃圾房"],["un local technique","设备间"],["un local commercial","商铺"],["sortir les poubelles","把垃圾拿出去"]],"sy":[["local poubelles","courant","同一个词的简写"],["local à vélos","courant","自行车房"]],"fq":"中频，公寓生活常用。","me":"local：locus（地方）；poubelle 来自一个人名。","tr":{"zh":"垃圾房在一楼。","fr":"Le local à poubelles est au rez-de-chaussée.","alt":"Le local à poubelles se trouve au rez-de-chaussée.","note":"rez-de-chaussée = 一楼（地面层）。"}},
 "Un local à vélo": {"pos":"n.m. 阳性名词，复数 locaux à vélos","s":"自行车房；楼里专门停自行车的房间，常要钥匙或密码。也常写 local à vélos。","ipa":"[lɔ.kal a ve.lo]","ph":"vélo 读 [ve.lo]：é [e]，o [o]；local 读 [lɔ.kal]。","pi":"vélo 末尾 o 不发 [ou]；单数 vélo 和复数 vélos 发音相同。","et":"local 来自拉丁语 localis；vélo 是 vélocipède 的缩写（拉丁语 velox 「快」+ pes 「脚」）。","ex":[["Mon vélo est dans le local à vélo.","我的自行车在自行车房里。"],["Il faut un code pour entrer dans le local à vélos.","进自行车房需要密码。"],["Je range mon vélo dans le local.","我把自行车停在车房里。"]],"co":[["ranger son vélo","把自行车放好"],["un local à vélos sécurisé","有门禁的自行车房"],["un antivol","车锁"],["un abri à vélos","自行车棚"]],"sy":[["abri à vélos","courant","户外自行车棚"],["garage à vélos","courant","自行车库"]],"fq":"中频，公寓生活常用。","me":"local + vélo：放「车轮」的房间。","tr":{"zh":"请把你的自行车停在车房里。","fr":"Range ton vélo dans le local à vélos, s'il te plaît.","alt":"Mets ton vélo dans le local à vélos.","note":"单数 à vélo 和复数 à vélos 都可以。"}},
 "Un loyer": {"pos":"n.m. 阳性名词，复数 loyers","s":"房租（每月付给房东的钱）。动词是 louer（租；出租）。","ipa":"[lwa.je]","ph":"oy 读 [waj] 中的 [wa]，loyer 读 [lwa.je]；结尾 -er 读 [e]。","pi":"不要读成 [lɔ.jɛʁ]；oy 是 [wa]；结尾 r 不发音。","et":"古法语 loier，来自拉丁语 locarium（出租费），源自 locare（安置、出租）。同族：louer。","ex":[["Le loyer est cher.","房租很贵。"],["Je paie mon loyer le 5 de chaque mois.","我每月 5 号付房租。"],["Le loyer comprend les charges.","房租包含物业费。"]],"co":[["payer le loyer","付房租"],["un loyer mensuel","月租"],["le loyer + les charges","房租加物业费"],["augmenter le loyer","涨房租"]],"sy":[["location","courant","租赁；出租"],["charges","courant","物业费、水电杂费"],["bail","courant","租约"]],"fq":"高频，租房必备。","me":"loyer ← louer：「租」出来的钱。","tr":{"zh":"我每个月付七百欧元房租。","fr":"Je paie sept cents euros de loyer par mois.","alt":"Mon loyer est de sept cents euros par mois.","note":"payer + 金额 + de loyer。"}},
 "Un mètre carré (m²)": {"pos":"n.m. 阳性名词，复数 mètres carrés（符号 m²）","s":"平方米。说房子面积用 faire + 数字 + mètres carrés；价格常说 le prix au mètre carré。","ipa":"[mɛtʁ ka.ʁe]","ph":"mètre 读 [mɛtʁ]，è [ɛ]，-tre 读 [tʁ]；carré 读 [ka.ʁe]，é [e]。","pi":"mètre 的 è 带重音；复数两个词都加 s：mètres carrés；不要把 carré 读成 car。","et":"mètre 来自希腊语 metron（尺度）；carré 来自拉丁语 quadratus（四方形的）。","ex":[["L'appartement fait 50 mètres carrés.","这套公寓有 50 平方米。"],["Quel est le prix au mètre carré ?","每平方米多少钱？"],["Ma chambre fait douze mètres carrés.","我的房间有十二平方米。"]],"co":[["50 m²","50 平方米"],["le prix au mètre carré","每平方米价格"],["faire 40 m²","面积有 40 平方米"],["un mètre cube","立方米"]],"sy":[["surface","courant","面积"],["superficie","courant","面积（较正式）"]],"fq":"高频，租房买房常用。","me":"mètre + carré：一个「四方形」的米。","tr":{"zh":"我的房间有十二平方米。","fr":"Ma chambre fait douze mètres carrés.","alt":"Ma chambre fait 12 m².","note":"面积用 faire，不用 avoir。"}},
 "Un meuble": {"pos":"n.m. 阳性名词，复数 meubles","s":"家具（一件）。法语里 un meuble 是可数的，说「家具」整体用 des meubles 或 le mobilier。形容词 meublé = 带家具的。","ipa":"[mœbl]","ph":"eu [œ]；-ble 读 [bl]，结尾 e 不发音；整词一个音节 [mœbl]。","pi":"不要在末尾加元音；和 immeuble（楼房）只差 im-，意思不同。","et":"古法语 meuble，来自拉丁语 mobilis（可移动的），因为家具可以搬动。","ex":[["C'est un beau meuble.","这是一件漂亮的家具。"],["On a acheté de nouveaux meubles.","我们买了新家具。"],["Cet appartement est loué sans meubles.","这套公寓不带家具出租。"]],"co":[["un meuble de rangement","收纳柜"],["un appartement meublé","带家具的公寓"],["acheter des meubles","买家具"],["un meuble de cuisine","厨房柜子"]],"sy":[["mobilier","courant","家具（整体）"],["ameublement","soutenu","家具陈设"]],"fq":"高频，家居常用。","me":"meuble ← mobilis：能「动」的东西。","tr":{"zh":"我们需要几件新家具。","fr":"Nous avons besoin de nouveaux meubles.","alt":"On a besoin de quelques meubles neufs.","note":"meuble 可数：un / des meuble(s)。"}},
 "Un micro-onde": {"pos":"n.m. 阳性名词，复数 micro-ondes（也说 un micro-ondes）","s":"微波炉，是 four à micro-ondes 的简称。注意：une micro-onde（阴性）指微波这种电磁波，微波炉则是阳性。","ipa":"[mi.kʁo.ɔ̃d]","ph":"micro [mi.kʁo]，onde 读 [ɔ̃d]：on 是鼻化元音，d 要读出来。","pi":"onde 的 d 要读；micro 里的 o 与 onde 的 on 分成两个音节。","et":"希腊语 mikros（小）+ 拉丁语 unda（波）。","ex":[["Je chauffe mon plat au micro-onde.","我用微波炉热饭。"],["Mets la soupe deux minutes au micro-onde.","把汤放进微波炉热两分钟。"],["Ça passe au micro-onde ?","这个能放微波炉吗？"]],"co":[["chauffer au micro-onde","用微波炉加热"],["passer au micro-onde","可进微波炉"],["un four à micro-ondes","微波炉（全称）"],["décongeler au micro-onde","用微波炉解冻"]],"sy":[["four à micro-ondes","courant","全称"],["micro-ondes","courant","常见说法，带 s"]],"fq":"中频，家用电器。","me":"micro（小）+ onde（波）：用「小波」加热。","tr":{"zh":"你可以用微波炉热汤。","fr":"Tu peux chauffer la soupe au micro-onde.","alt":"Fais chauffer la soupe au micro-onde.","note":"au micro-onde（à + le）。"}},
 "Un problème": {"pos":"n.m. 阳性名词，复数 problèmes","s":"问题；麻烦。Pas de problème ! = 没问题！也可指数学题。以 -ème 结尾但是阳性。","ipa":"[pʁɔ.blɛm]","ph":"o [ɔ]；bl 连读 [bl]；è [ɛ]；m 要读出来 [m]。","pi":"-ème 结尾仍是阳性：un problème，不是 une problème。结尾 m 要发。","et":"希腊语 problêma（放在前面的东西、难题），经拉丁语进入法语。","ex":[["J'ai un petit problème.","我有个小问题。"],["Il n'y a pas de problème.","没有问题。"],["Quel est le problème ?","怎么了？问题是什么？"]],"co":[["avoir un problème","有问题"],["Pas de problème !","没问题！"],["résoudre un problème","解决问题"],["un problème de santé","健康问题"]],"sy":[["souci","courant","烦心事、担忧"],["ennui","courant","麻烦（常用复数 ennuis）；也指无聊"],["difficulté","courant","困难"]],"fq":"极高频，日常常用。","me":"problème 和 système、thème 一样：-ème 结尾的阳性词。","tr":{"zh":"没问题，我来帮你。","fr":"Pas de problème, je vais t'aider.","alt":"Aucun problème, je t'aide.","note":"pas de + 名词（不加冠词）。"}},
 "Un salon": {"pos":"n.m. 阳性名词，复数 salons","s":"客厅。还指展览会（le salon du livre）、美发店（salon de coiffure）、茶室（salon de thé）。","ipa":"[sa.lɔ̃]","ph":"s [s]；a [a]；-on 读鼻化元音 [ɔ̃]。","pi":"结尾 on 是鼻音，n 不读出来；重音在最后一个音节。","et":"意大利语 salone（大厅，sala 的放大形式）。","ex":[["Nous regardons la télé dans le salon.","我们在客厅看电视。"],["Le salon est grand et lumineux.","客厅又大又亮。"],["Il y a un salon du livre à Paris en mars.","三月巴黎有图书展。"]],"co":[["salon de coiffure","美发店"],["salon de thé","茶室"],["le salon du livre","图书展"],["un canapé de salon","客厅沙发"]],"sy":[["séjour","courant","起居室（租房广告用语）"],["living","familier","起居室（借自英语）"],["salle de séjour","courant","起居室"]],"fq":"极高频，日常常用。","me":"salon ← sala：一个很大的「厅」。","tr":{"zh":"客厅里有一张大沙发。","fr":"Il y a un grand canapé dans le salon.","alt":"Dans le salon, on a un grand canapé.","note":"dans le salon（在……里面）。"}},
 "Un studio": {"pos":"n.m. 阳性名词，复数 studios","s":"单间公寓（一间房带小厨房和卫生间）。还指录音棚、摄影棚、舞蹈室。","ipa":"[sty.djo]","ph":"u 读 [y]；di 读 [dj]；结尾 o 读 [o]；两个音节。","pi":"u 是 [y]（嘴唇圆起来，像「鱼」的音），不是 [u]；两个音节而非三个。","et":"意大利语 studio（学习、工作室），来自拉丁语 studium。","ex":[["Elle loue un petit studio.","她租了一个小单间。"],["Mon studio fait vingt mètres carrés.","我的单间有二十平方米。"],["Ils enregistrent dans un studio à Lyon.","他们在里昂的一个录音棚录音。"]],"co":[["louer un studio","租单间"],["un studio meublé","带家具的单间"],["un studio d'enregistrement","录音棚"],["un studio de danse","舞蹈室"]],"sy":[["T1 / F1","courant","房产广告里的一居室代号"],["appartement","courant","公寓（更大的）"],["chambre de bonne","courant","顶楼小房间"]],"fq":"高频，租房常用。","me":"studio：u 要圆唇 [y]，两拍读完。","tr":{"zh":"我想在巴黎租一个单间。","fr":"Je voudrais louer un studio à Paris.","alt":"Je cherche à louer un studio à Paris.","note":"je voudrais + 动词原形 = 礼貌的「我想要」。"}},
 "Un tableau": {"pos":"n.m. 阳性名词，复数 tableaux","s":"画；黑板（tableau noir）；表格（un tableau de chiffres）。在教室里 le tableau 就是黑板或白板。","ipa":"[ta.blo]","ph":"ta [ta]；-bleau 读 [blo]，eau 读 [o]。","pi":"复数是 tableaux，不是 tableaus；eau 读 [o]。","et":"table 的指小词（古法语 tablel），源自拉丁语 tabula（木板）。","ex":[["C'est un beau tableau.","这是一幅美丽的画。"],["Le professeur écrit au tableau.","老师在黑板上写字。"],["Regarde le tableau des horaires.","看一下时刻表。"]],"co":[["accrocher un tableau","挂一幅画"],["un tableau noir / blanc","黑板 / 白板"],["écrire au tableau","在黑板上写"],["un tableau de bord","仪表盘"]],"sy":[["peinture","courant","绘画（泛指）"],["toile","courant","画布、油画"],["table","courant","桌子（不是画）"]],"fq":"高频，教室和家居常用。","me":"tableau = 小「table」：一块板，画在板上。","tr":{"zh":"墙上挂着一幅很漂亮的画。","fr":"Il y a un très beau tableau sur le mur.","alt":"Un très beau tableau est accroché au mur.","note":"accroché = 挂着（被动，过去分词）。"}},
 "Un tapis": {"pos":"n.m. 阳性名词，复数不变 tapis","s":"地毯；垫子。日常指铺在地上的毯子，也有 tapis de bain（浴室垫）、tapis de souris（鼠标垫）、tapis roulant（跑步机 / 传送带）。","ipa":"[ta.pi]","ph":"ta [ta]；pi [pi]；结尾 s 不发音。","pi":"结尾 s 不发音；单复数同形，复数也是 tapis。","et":"古法语 tapiz，可追溯到希腊语 tapēs（毯子）。","ex":[["Le chien dort sur le tapis.","狗睡在地毯上。"],["Le tapis du salon est très doux.","客厅的地毯很柔软。"],["Je fais du yoga sur mon tapis.","我在垫子上做瑜伽。"]],"co":[["un tapis de bain","浴室垫"],["un tapis de souris","鼠标垫"],["un tapis roulant","跑步机；传送带"],["un tapis rouge","红毯"]],"sy":[["moquette","courant","满铺地毯"],["carpette","courant","小地毯；也可指软弱的人"],["paillasson","courant","门口脚垫"]],"fq":"中频，家居常用。","me":"tapis 的 s 不读：像「塔皮」。","tr":{"zh":"把地毯放在桌子下面。","fr":"Mets le tapis sous la table.","alt":"Pose le tapis sous la table.","note":"sous = 在……下面。"}},
 "La cafétéria": {"pos":"n.f. 阴性名词，复数 cafétérias","s":"自助餐厅；食堂。学校、医院、商场里的自助式餐厅。学校食堂也常说 cantine。","ipa":"[ka.fe.te.ʁja]","ph":"ca [ka]；fé [fe]；té [te]；-ria 读 [ʁja]，共 4 个音节。","pi":"两个 é 都读 [e]；末尾 ia 是 [ja]，重音落在最后一个音节。","et":"借自美式英语 cafeteria，英语又来自西班牙语 cafetería（咖啡馆）。","ex":[["Nous mangeons à la cafétéria.","我们在食堂吃饭。"],["La cafétéria ferme à 14 heures.","食堂两点关门。"],["On se retrouve à la cafétéria de l'université.","我们在大学食堂碰面。"]],"co":[["manger à la cafétéria","在食堂吃饭"],["la cafétéria de l'école","学校食堂"],["la cafétéria de l'hôpital","医院餐厅"]],"sy":[["cantine","courant","学校或公司食堂（固定菜单）"],["self","familier","自助食堂（口语）"],["resto U","familier","大学食堂"]],"fq":"中频，学校和工作场合。","me":"cafétéria：café 里有两个 é 要读清。","tr":{"zh":"午饭我们在食堂见面。","fr":"On se retrouve à la cafétéria pour déjeuner.","alt":"Rendez-vous à la cafétéria pour le déjeuner.","note":"pour + 动词原形 = 为了做……"}},
 "La température": {"pos":"n.f. 阴性名词，复数 températures","s":"温度；气温；体温。avoir de la température 口语指发烧。","ipa":"[tɑ̃.pe.ʁa.tyʁ]","ph":"tem 读鼻化元音 [tɑ̃]；pé [pe]；ra [ʁa]；tu 读 [ty]，r 读 [ʁ]。","pi":"开头 tem 是鼻音，m 不读；-ure 读 [yʁ]，u 是圆唇的 [y]。","et":"拉丁语 temperatura（调和、适度），来自 temperare（混合）。","ex":[["La température est basse aujourd'hui.","今天气温很低。"],["Quelle est la température dehors ?","外面多少度？"],["Le médecin prend ma température.","医生给我量体温。"]],"co":[["la température extérieure","室外温度"],["prendre la température","量体温"],["une température de vingt degrés","二十度的气温"],["la température baisse / monte","气温下降 / 上升"]],"sy":[["chaleur","courant","热、热度"],["fièvre","courant","发烧"]],"fq":"高频，日常常用。","me":"température ≈ temperature：只是 -ure 读 [yʁ]，重音在最后。","tr":{"zh":"房间的温度是二十度。","fr":"La température de la pièce est de vingt degrés.","alt":"Il fait vingt degrés dans la pièce.","note":"il fait + 度数 = 气温是……度。"}},
 "Une armoire": {"pos":"n.f. 阴性名词，复数 armoires","s":"衣柜；大柜子。也有 armoire à pharmacie（药柜）。口语 armoire à glace = 身材魁梧的人。","ipa":"[aʁ.mwaʁ]","ph":"ar [aʁ]；moi 读 [mwa]；结尾 r 要读 [ʁ]。","pi":"oi 读 [wa]；结尾 r 要发音；阴性：une armoire。","et":"拉丁语 armarium（放工具、武器的柜子），来自 arma（武器）。","ex":[["Mes vêtements sont dans l'armoire.","我的衣服在衣柜里。"],["Il y a une armoire ancienne dans la chambre.","卧室里有一个老衣柜。"],["Range ton pull dans l'armoire.","把你的毛衣放进衣柜。"]],"co":[["ranger dans l'armoire","放进衣柜"],["une armoire à pharmacie","药柜"],["une armoire à glace","壮汉（口语）"],["une armoire normande","诺曼底大衣柜"]],"sy":[["placard","courant","壁橱"],["penderie","courant","挂衣橱"],["commode","courant","五斗柜"]],"fq":"中频，家居常用。","me":"armoire 里原来放「武器」(arma)，现在放衣服。","tr":{"zh":"我的外套在衣柜里。","fr":"Mon manteau est dans l'armoire.","alt":"J'ai rangé mon manteau dans l'armoire.","note":"dans l'armoire（l' 是省音）。"}},
 "Une bouilloire": {"pos":"n.f. 阴性名词，复数 bouilloires","s":"水壶（烧水用，常为电热水壶）。不是泡茶的茶壶 théière。","ipa":"[bu.jwaʁ]","ph":"bou [bu]；-illoire 读 [jwaʁ]：ill [j]，oi [wa]，结尾 r 要读。","pi":"ill 读 [j]，不是 [il]；oi 读 [wa]；结尾 r 要发。","et":"由 bouillir（沸腾，拉丁语 bullire）加后缀 -oire（表示工具）构成。","ex":[["L'eau bout dans la bouilloire.","水在壶里烧开了。"],["Je mets la bouilloire pour le thé.","我烧水泡茶。"],["Cette bouilloire est électrique.","这个水壶是电热的。"]],"co":[["une bouilloire électrique","电热水壶"],["mettre la bouilloire","烧水"],["faire bouillir de l'eau","把水烧开"]],"sy":[["théière","courant","茶壶"],["cafetière","courant","咖啡壶、咖啡机"],["casserole","courant","炖锅"]],"fq":"中频，厨房常用。","me":"bouilloire ← bouillir：「烧开」的工具。","tr":{"zh":"请把水倒进水壶里。","fr":"Verse l'eau dans la bouilloire, s'il te plaît.","alt":"Mets de l'eau dans la bouilloire, s'il te plaît.","note":"verser / mettre + de l'eau + dans。"}},
 "Une cave": {"pos":"n.f. 阴性名词，复数 caves","s":"地窖；地下储藏室。法国公寓楼里每户常有一间 cave 放杂物，也指酒窖（une cave à vin）。","ipa":"[kav]","ph":"ca [ka]，v [v]；结尾 e 不发音：[kav]。","pi":"cave 不是山洞（山洞是 grotte）；一个音节 [kav]。","et":"拉丁语 cava（空的、洞），来自 cavus（凹的）。","ex":[["Le vin est dans la cave.","酒放在地窖里。"],["J'ai un vélo dans la cave.","我有一辆自行车放在地下室。"],["Il descend à la cave chercher une bouteille.","他下地窖去拿一瓶酒。"]],"co":[["descendre à la cave","下地下室"],["une cave à vin","酒窖"],["une cave voûtée","拱顶地窖"],["mettre à la cave","放进地下室"]],"sy":[["sous-sol","courant","地下层（也指停车层）"],["cellier","soutenu","地面储藏室（放酒和食物）"],["grotte","courant","天然山洞"]],"fq":"中频，公寓生活常用。","me":"cave = 洞（cavus）：在地下挖出来的「空」间。","tr":{"zh":"我的旧自行车放在地下室里。","fr":"Mon vieux vélo est dans la cave.","alt":"J'ai laissé mon vieux vélo à la cave.","note":"dans la cave / à la cave 都可以。"}},
 "Une chaise": {"pos":"n.f. 阴性名词，复数 chaises","s":"椅子（没有扶手的普通椅子）。有扶手用 fauteuil，长凳用 banc，凳子用 tabouret。","ipa":"[ʃɛz]","ph":"ch [ʃ]；ai [ɛ]；s 在两个元音之间读 [z]：[ʃɛz]。","pi":"ch 读 [ʃ]，不是英语的 [tʃ]；s 读 [z]；不要和 chaîne（链子 [ʃɛn]）混。","et":"拉丁语 cathedra（座位），源自希腊语 kathedra。同源：chaire（讲席）、cathédrale。","ex":[["Assieds-toi sur cette chaise.","坐在这把椅子上。"],["Il y a quatre chaises autour de la table.","桌子周围有四把椅子。"],["Cette chaise est cassée.","这把椅子坏了。"]],"co":[["s'asseoir sur une chaise","坐在椅子上"],["une chaise haute","婴儿高脚椅"],["une chaise longue","躺椅"],["une chaise de bureau","办公椅"]],"sy":[["fauteuil","courant","扶手椅"],["tabouret","courant","凳子"],["siège","courant","座位（泛指）"]],"fq":"极高频，日常常用。","me":"chaise 读「谢兹」：s 嗡嗡响成 z。","tr":{"zh":"请从厨房拿一把椅子过来。","fr":"Apporte une chaise de la cuisine, s'il te plaît.","alt":"Va chercher une chaise dans la cuisine, s'il te plaît.","note":"apporter = 带来；aller chercher = 去拿。"}},
 "Une chambre": {"pos":"n.f. 阴性名词，复数 chambres","s":"卧室；客房（une chambre d'hôtel）。法语里 chambre 特指睡觉的房间，泛指房间用 pièce。","ipa":"[ʃɑ̃bʁ]","ph":"ch [ʃ]；am 读鼻化元音 [ɑ̃]，m 不读；-bre 读 [bʁ]。","pi":"chambre 的 m 不发音，a 是鼻音；结尾 -bre 轻读，不加元音。","et":"拉丁语 camera（拱顶房间），源自希腊语 kamara。","ex":[["Je dors dans ma chambre.","我在卧室睡觉。"],["Ma chambre donne sur la cour.","我的卧室朝向院子。"],["J'ai réservé une chambre double.","我订了一间双人房。"]],"co":[["une chambre d'hôtel","酒店房间"],["une chambre double / simple","双人房 / 单人房"],["ranger sa chambre","收拾卧室"],["une chambre d'amis","客房"]],"sy":[["pièce","courant","房间（泛指）"],["piaule","argot","小房间（俚语）"]],"fq":"极高频，日常常用。","me":"chambre = 睡觉的房间；pièce = 任何房间。","tr":{"zh":"请你整理一下你的房间。","fr":"Range ta chambre, s'il te plaît.","alt":"Tu peux ranger ta chambre ?","note":"ranger = 整理、收拾。"}},
 "Une clé": {"pos":"n.f. 阴性名词，复数 clés（也写 clef）","s":"钥匙。还指乐谱谱号（clé de sol）、扳手（clé à molette）、U 盘（clé USB）和「关键」（la clé du succès）。","ipa":"[kle]","ph":"cl [kl]；é 读 [e]；整词 [kle]，不发 f 或 s。","pi":"结尾 é 读 [e]，嘴巴微笑；clef 的 f 不发音，和 clé 同音。","et":"拉丁语 clavis（钥匙）。同族词：clavier（键盘）、clavicule（锁骨，「小钥匙」）。","ex":[["J'ai perdu mes clés.","我丢了钥匙。"],["Où est la clé de la voiture ?","车钥匙在哪儿？"],["J'ai une clé USB dans mon sac.","我包里有一个 U 盘。"]],"co":[["fermer à clé","锁上"],["la clé de la maison","家门钥匙"],["une clé USB","U 盘"],["la clé du succès","成功的关键"]],"sy":[["clef","courant","同一个词的另一种拼法"],["serrure","courant","锁"],["badge","courant","门禁卡"]],"fq":"极高频，日常常用。","me":"clé 像英语 clay：开门要「克蕾」一声。","tr":{"zh":"你把钥匙放哪儿了？","fr":"Où as-tu mis les clés ?","alt":"T'as mis les clés où ?","note":"mis 是 mettre 的过去分词。"}},
 "Une cuisine": {"pos":"n.f. 阴性名词，复数 cuisines","s":"厨房；烹饪；菜系。faire la cuisine = 做饭；la cuisine française = 法国菜。","ipa":"[kɥi.zin]","ph":"cui 读 [kɥi]；s 在元音间读 [z]；-ine 读 [in]，i 不是鼻音。","pi":"ui 读 [ɥi]：嘴唇先圆再放开；s 读 [z]；结尾 n 要读出来。","et":"拉丁语 coquina（厨房），来自 coquere（煮、烹）。","ex":[["Je prépare le repas dans la cuisine.","我在厨房做饭。"],["Il aime faire la cuisine.","他喜欢做饭。"],["J'adore la cuisine italienne.","我爱意大利菜。"]],"co":[["faire la cuisine","做饭"],["une cuisine équipée","配备齐全的厨房"],["la cuisine française","法国菜"],["un livre de cuisine","食谱书"]],"sy":[["cuisinière","courant","炉灶；女厨师"],["popote","familier","做饭（口语）"],["gastronomie","soutenu","美食文化"]],"fq":"极高频，日常常用。","me":"cuisine 开头像「歪」(wi)：嘴唇圆着读 [ɥi]。","tr":{"zh":"我妈妈每天晚上做饭。","fr":"Ma mère fait la cuisine tous les soirs.","alt":"Ma mère prépare le dîner tous les soirs.","note":"faire la cuisine = 做饭（不是「做厨房」）。"}},
 "Une cuisinière": {"pos":"n.f. 阴性名词，复数 cuisinières","s":"炉灶（带烤箱的灶具）；也是女厨师（cuisinier 的阴性）。常见搭配：cuisinière à gaz / électrique。","ipa":"[kɥi.zi.njɛʁ]","ph":"cui [kɥi]；si [zi]；-nière 读 [njɛʁ]：ni [nj]，è [ɛ]，r 要读。","pi":"-ière 读 [jɛʁ]，结尾 r 要发；两个意思同一个词，看语境。","et":"由 cuisine 加后缀 -ière 构成，原指「女厨师」，后来指灶具。","ex":[["C'est une cuisinière à gaz.","这是一个燃气灶。"],["Elle est cuisinière dans un grand restaurant.","她是一家大餐厅的厨师。"],["La cuisinière est en panne.","炉灶坏了。"]],"co":[["une cuisinière à gaz","燃气灶"],["une cuisinière électrique","电灶"],["une cuisinière à bois","烧柴的灶"],["allumer la cuisinière","点火开灶"]],"sy":[["plaque de cuisson","courant","灶台、电磁炉"],["gazinière","courant","燃气灶"],["cuisinier","courant","男厨师"]],"fq":"中频，厨房常用。","me":"cuisinière = 做饭的人，也是做饭的灶。","tr":{"zh":"我们的炉灶坏了。","fr":"Notre cuisinière est en panne.","alt":"Notre cuisinière ne marche plus.","note":"en panne = 坏了、出故障。"}},
 "Une douche": {"pos":"n.f. 阴性名词，复数 douches","s":"淋浴；淋浴间。prendre une douche = 冲澡。口语 une douche froide 也指「泼冷水」，失望的消息。","ipa":"[duʃ]","ph":"ou [u]；ch [ʃ]；结尾 e 不发音：[duʃ]。","pi":"ou 读 [u]，不是 [dau]；ch 读 [ʃ]，嘴唇微圆；一个音节。","et":"意大利语 doccia（水管、喷水），传入法语。","ex":[["Je prends une douche le matin.","我早上冲澡。"],["La douche est en panne.","淋浴坏了。"],["Il y a une douche et une baignoire.","有淋浴也有浴缸。"]],"co":[["prendre une douche","冲澡"],["une douche chaude / froide","热水 / 冷水澡"],["une cabine de douche","淋浴房"],["un gel douche","沐浴露"]],"sy":[["bain","courant","盆浴"],["baignoire","courant","浴缸"],["salle d'eau","courant","只有淋浴的浴室"]],"fq":"高频，日常常用。","me":"douche 读「杜许」：水喷出来的声音。","tr":{"zh":"我晚上洗澡，因为早上没时间。","fr":"Je prends une douche le soir parce que je n'ai pas le temps le matin.","alt":"Le matin, je n'ai pas le temps : je me douche le soir.","note":"se doucher = 洗澡（代词式动词）。"}},
 "Une fenêtre": {"pos":"n.f. 阴性名词，复数 fenêtres","s":"窗户；电脑上的窗口。regarder par la fenêtre = 看窗外。","ipa":"[fə.nɛtʁ]","ph":"fe 读 [fə]（说话时常省略）；ê [ɛ]；-tre 读 [tʁ]。","pi":"拼写有 ê；第一个 e 很弱；结尾 -tre 不加元音。","et":"拉丁语 fenestra（窗）。同族词：défenestrer（把人扔出窗外）。","ex":[["Ouvre la fenêtre.","打开窗户。"],["Il regarde par la fenêtre.","他看着窗外。"],["La fenêtre donne sur la rue.","窗户朝着街。"]],"co":[["ouvrir / fermer la fenêtre","开 / 关窗户"],["regarder par la fenêtre","看窗外"],["à la fenêtre","在窗边"],["donner sur","朝向"]],"sy":[["baie vitrée","courant","落地大窗"],["vitre","courant","窗玻璃"],["lucarne","courant","屋顶小窗"]],"fq":"极高频，日常常用。","me":"fenêtre ← fenestra：帽子 ê 是「去掉了 s」的痕迹。","tr":{"zh":"关上窗户，我觉得冷。","fr":"Ferme la fenêtre, j'ai froid.","alt":"Tu peux fermer la fenêtre ? J'ai froid.","note":"avoir froid = 觉得冷。"}},
 "Une fuite (d'eau, de gaz)": {"pos":"n.f. 阴性名词，复数 fuites","s":"漏；泄漏（水、气）。也指逃跑（prendre la fuite）和信息泄露（une fuite d'informations）。","ipa":"[fɥit]","ph":"ui 读 [ɥi]；t 要读出来 [t]；结尾 e 不发音。","pi":"fuite 不是 fruit（水果）；ui 嘴唇先圆再放开；t 要发音。","et":"来自动词 fuir（逃；漏），拉丁语 fugere。","ex":[["Il y a une fuite d'eau dans la salle de bain.","浴室漏水了。"],["Il y a une fuite de gaz dans l'immeuble.","楼里有煤气泄漏。"],["Le voleur a pris la fuite.","小偷逃跑了。"]],"co":[["une fuite d'eau / de gaz","漏水 / 漏气"],["réparer une fuite","修漏"],["une fuite d'informations","信息泄露"],["prendre la fuite","逃跑"]],"sy":[["fuir","courant","动词：漏；逃"],["évasion","courant","越狱、逃脱"]],"fq":"中频，住房问题常见。","me":"fuite ← fuir：水「逃」走了。","tr":{"zh":"水管工在修厨房的漏水。","fr":"Le plombier est en train de réparer la fuite dans la cuisine.","alt":"Le plombier répare la fuite de la cuisine.","note":"être en train de + 动词原形 = 正在做。"}},
 "Une laisse": {"pos":"n.f. 阴性名词，复数 laisses","s":"牵狗绳。en laisse = 拴着绳子。常见于公园告示：Chiens tenus en laisse。","ipa":"[lɛs]","ph":"ai 读 [ɛ]；ss 读 [s]；结尾 e 不发音：[lɛs]。","pi":"一个音节 [lɛs]；和 laisser（让）[le.se] 不同；je laisse 的发音与它相同。","et":"派生自动词 laisser（放开、让）；古法语 laisse 指能放长的绳子。","ex":[["Tenez votre chien en laisse.","请牵好您的狗。"],["Mon chien tire sur sa laisse.","我的狗拉着牵引绳。"],["Les chiens doivent être tenus en laisse.","狗必须拴着绳子。"]],"co":[["tenir un chien en laisse","牵着狗"],["promener le chien en laisse","牵着狗散步"],["tirer sur la laisse","拉扯牵引绳"],["sans laisse","不拴绳"]],"sy":[["harnais","courant","胸背带"],["collier","courant","项圈"],["longe","courant","长绳、牵马绳"]],"fq":"中频，养狗时常用。","me":"laisse ← laisser：给狗「放」一点长度。","tr":{"zh":"公园里的狗必须拴着绳子。","fr":"Au parc, les chiens doivent être en laisse.","alt":"Dans le parc, les chiens doivent être tenus en laisse.","note":"devoir + être（必须……）。"}},
 "Une lampe": {"pos":"n.f. 阴性名词，复数 lampes","s":"灯；台灯。灯具本身是 lampe，光是 lumière。lampe de poche = 手电筒。","ipa":"[lɑ̃p]","ph":"am 读鼻化元音 [ɑ̃]，p 要读出来：[lɑ̃p]。","pi":"鼻化元音后的 p 要读，不是 [lamp]；a 不是 [a]，而是 [ɑ̃]。","et":"希腊语 lampas（火把），经拉丁语进入法语。","ex":[["Allume la lampe.","开灯。"],["Il y a une lampe sur mon bureau.","我的桌上有一盏灯。"],["J'ai besoin d'une lampe de poche.","我需要一只手电筒。"]],"co":[["allumer / éteindre la lampe","开 / 关灯"],["une lampe de bureau","台灯"],["une lampe de chevet","床头灯"],["une lampe de poche","手电筒"]],"sy":[["lumière","courant","光；电灯（allume la lumière）"],["lampadaire","courant","落地灯；路灯"],["ampoule","courant","灯泡"]],"fq":"高频，日常常用。","me":"lampe：鼻音 an + p，嘴巴最后闭上。","tr":{"zh":"请关掉床头灯。","fr":"Éteins la lampe de chevet, s'il te plaît.","alt":"Tu peux éteindre la lampe de chevet ?","note":"chevet = 床头。"}},
 "Une pelouse": {"pos":"n.f. 阴性名词，复数 pelouses","s":"草坪（修剪过的草地）。告示 Pelouse interdite = 禁止踩草坪。体育场和音乐会也有 la pelouse（草地区域）。","ipa":"[pə.luz]","ph":"pe 读 [pə]（常省略）；ou [u]；s 在元音间读 [z]：[pə.luz]。","pi":"s 读 [z]，不是 [s]；ou 读 [u]；结尾 e 不发音。","et":"一般认为来自拉丁语 pilosus（多毛的），意思是「毛茸茸的草地」；来源不完全确定。","ex":[["La pelouse est verte.","草坪是绿的。"],["Pelouse interdite !","禁止踩草坪！"],["Les enfants jouent sur la pelouse.","孩子们在草坪上玩。"]],"co":[["tondre la pelouse","修剪草坪"],["arroser la pelouse","给草坪浇水"],["une pelouse bien entretenue","维护得好的草坪"],["pelouse interdite","禁止踩草坪"]],"sy":[["gazon","courant","草皮、草坪"],["herbe","courant","草"],["prairie","courant","草地、牧场"]],"fq":"中频，花园和公园常见。","me":"pelouse：s 像 z，「波露斯」读作 [pə.luz]。","tr":{"zh":"请不要踩草坪。","fr":"Ne marchez pas sur la pelouse, s'il vous plaît.","alt":"Pelouse interdite, merci.","note":"ne ... pas + 命令式（vous）。"}},
 "Une pièce": {"pos":"n.f. 阴性名词，复数 pièces","s":"房间（泛指）；硬币（une pièce de deux euros）；零件；戏剧（une pièce de théâtre）；证件（une pièce d'identité）。一个多义词。","ipa":"[pjɛs]","ph":"pi 读 [pj]；è [ɛ]；c 在 e 前读 [s]：[pjɛs]。","pi":"一个音节 [pjɛs]，不是两个；pièce 指任何房间，chambre 只指卧室。","et":"来自高卢-罗曼语 *pettia（一块），原为高卢语词。","ex":[["Cet appartement a trois pièces.","这套公寓有三个房间。"],["Tu as une pièce de deux euros ?","你有两欧元的硬币吗？"],["On va voir une pièce de théâtre.","我们去看一出戏。"]],"co":[["un trois-pièces","三居室（不含厨房、浴室）"],["une pièce de monnaie","硬币"],["une pièce de théâtre","戏剧"],["une pièce d'identité","身份证件"]],"sy":[["salle","courant","专用房间：salle de bain"],["chambre","courant","卧室"],["morceau","courant","一块"]],"fq":"极高频，日常常用。","me":"pièce：房间、硬币、戏剧……一个词，多个「块」。","tr":{"zh":"我们的公寓有四个房间。","fr":"Notre appartement a quatre pièces.","alt":"On a un quatre-pièces.","note":"房间数一般不含厨房和浴室。"}},
 "Une plante (verte)": {"pos":"n.f. 阴性名词，复数 plantes (vertes)","s":"绿植；植物。une plante verte 专指室内观叶植物。plante 也指脚掌（la plante du pied）。","ipa":"[plɑ̃t vɛʁt]","ph":"plan 读 [plɑ̃]；t 要读 [t]；verte 读 [vɛʁt]，t 也要读。","pi":"两个词的结尾 t 都要发音（因为后面有 e）；plan 是鼻音。","et":"拉丁语 planta（嫩枝；脚掌）。同源：planter（种）。","ex":[["J'arrose ma plante verte.","我给绿植浇水。"],["Cette plante a besoin de lumière.","这盆植物需要光。"],["Il y a beaucoup de plantes dans le salon.","客厅里有很多植物。"]],"co":[["arroser une plante","给植物浇水"],["une plante d'intérieur","室内植物"],["une plante grasse","多肉植物"],["la plante du pied","脚掌"]],"sy":[["plante d'intérieur","courant","室内植物"],["fleur","courant","花"],["végétal","soutenu","植物（学术语气）"]],"fq":"高频，日常常用。","me":"plante ← planta：「种」下去的东西。","tr":{"zh":"别忘了给绿植浇水。","fr":"N'oublie pas d'arroser la plante verte.","alt":"Pense à arroser la plante.","note":"oublier de / penser à + 动词原形。"}},
 "Une poêle": {"pos":"n.f. 阴性名词，复数 poêles","s":"平底锅。注意：un poêle（阳性）是取暖炉，写法和读音都一样，只看冠词分辨。","ipa":"[pwal]","ph":"oê 读 [wa]；l 要读：[pwal]，一个音节。","pi":"la poêle（平底锅）和 le poêle（取暖炉）同音，靠冠词区分；ê 读 [wa]，不是 [ɛ]。","et":"拉丁语 patella（小盘、小锅）。取暖炉 le poêle 是另一个词。","ex":[["Je cuis un œuf dans la poêle.","我用平底锅煎蛋。"],["Mets un peu d'huile dans la poêle.","往锅里放一点油。"],["On a un poêle à bois dans le salon.","客厅里有一个烧柴的取暖炉。"]],"co":[["faire cuire à la poêle","用平底锅煎"],["une poêle antiadhésive","不粘锅"],["une poêle à frire","煎锅"],["un poêle à bois","烧柴取暖炉"]],"sy":[["casserole","courant","有柄的炖锅"],["sauteuse","courant","炒锅"],["wok","courant","炒菜锅"]],"fq":"中频，厨房常用。","me":"la poêle 煎蛋；le poêle 烧柴取暖。","tr":{"zh":"把鸡蛋打到平底锅里。","fr":"Casse l'œuf dans la poêle.","alt":"Mets l'œuf dans la poêle.","note":"casser = 打破，鸡蛋也用 casser。"}},
 "Une porte": {"pos":"n.f. 阴性名词，复数 portes","s":"门；大门；登机口（porte d'embarquement）。巴黎的地名 Porte de Versailles 指城门位置。","ipa":"[pɔʁt]","ph":"o 读开口的 [ɔ]；r [ʁ]；t 要读 [t]。","pi":"t 要读出来：[pɔʁt]；和 porter（拿，[pɔʁ.te]）不同。","et":"拉丁语 porta（门）。同源：portier、portail。","ex":[["Ferme la porte, s'il te plaît.","请关上门。"],["Quelqu'un frappe à la porte.","有人在敲门。"],["La porte d'embarquement est la 12.","登机口是 12 号。"]],"co":[["ouvrir / fermer la porte","开 / 关门"],["frapper à la porte","敲门"],["la porte d'entrée","大门；入户门"],["mettre à la porte","赶出去；开除"]],"sy":[["portail","courant","院子的大门"],["portière","courant","车门"],["issue","courant","出口"]],"fq":"极高频，日常常用。","me":"porte 的 t 要读，像「泡特」。","tr":{"zh":"有人在敲门，你去开一下。","fr":"On frappe à la porte, va ouvrir.","alt":"Quelqu'un frappe, tu peux aller ouvrir ?","note":"on frappe = 有人敲门（on 不指具体的人）。"}},
 "Une poubelle": {"pos":"n.f. 阴性名词，复数 poubelles","s":"垃圾桶。jeter à la poubelle = 扔进垃圾桶；sortir la poubelle = 把垃圾拿出去倒。","ipa":"[pu.bɛl]","ph":"ou [u]；b [b]；-elle 读 [ɛl]，l 要读。","pi":"ou 读 [u]，不是 [au]；结尾 -elle 的 l 要发音；阴性：une poubelle。","et":"得名于巴黎警察局长 Eugène Poubelle，他在 1884 年下令使用垃圾桶。","ex":[["La poubelle est pleine.","垃圾桶满了。"],["N'oublie pas de sortir la poubelle.","别忘了倒垃圾。"],["Jette ça à la poubelle.","把这个扔进垃圾桶。"]],"co":[["jeter à la poubelle","扔进垃圾桶"],["sortir la poubelle","倒垃圾"],["la poubelle jaune","黄色可回收桶"],["un sac poubelle","垃圾袋"]],"sy":[["corbeille","courant","小纸篓"],["benne","courant","大垃圾箱"],["conteneur","courant","大型垃圾箱"]],"fq":"极高频，日常常用。","me":"poubelle：以人名命名，「布贝尔先生」的桶。","tr":{"zh":"请你把垃圾拿出去倒，好吗？","fr":"Peux-tu sortir la poubelle, s'il te plaît ?","alt":"Tu sors la poubelle, s'il te plaît ?","note":"sortir 在这里是及物动词：sortir + 物。"}},
 "Une résidence": {"pos":"n.f. 阴性名词，复数 résidences","s":"住宅区；公寓楼；住所。résidence principale = 主要住所；résidence universitaire = 大学宿舍。","ipa":"[ʁe.zi.dɑ̃s]","ph":"ré [ʁe]；si [zi]；-dence 读 [dɑ̃s]：en 是鼻音，c 读 [s]。","pi":"中间 s 读 [z]；-ence 读鼻音 [ɑ̃s]，不是 [ɛns]；重音在最后。","et":"拉丁语 residentia，来自 residere（留下、居住）。","ex":[["C'est une résidence calme.","这是一个安静的住宅区。"],["Il vit en résidence universitaire.","他住在大学宿舍。"],["Ma résidence principale est à Lyon.","我的主要住所在里昂。"]],"co":[["une résidence universitaire","大学宿舍"],["la résidence principale / secondaire","主要 / 次要住所"],["une résidence étudiante","学生公寓"],["une résidence de vacances","度假屋"]],"sy":[["immeuble","courant","楼房"],["domicile","soutenu","住所（正式）"],["cité U","familier","大学宿舍（口语）"]],"fq":"中频，租房和行政文件常见。","me":"résidence ≈ residence：重音放到最后一个音节。","tr":{"zh":"我住在一个安静的小区。","fr":"J'habite dans une résidence tranquille.","alt":"Je vis dans une résidence très calme.","note":"habiter dans + 地方。"}},
 "Une salle à manger": {"pos":"n.f. 阴性名词，复数 salles à manger","s":"餐厅（家里吃饭的房间）。salle 是「厅、室」，à manger 说明用途「用来吃饭」。","ipa":"[sal a mɑ̃.ʒe]","ph":"salle 读 [sal]，ll 读 [l]；à [a]；manger 读 [mɑ̃.ʒe]：an 鼻音，g 读 [ʒ]。","pi":"manger 的 g 读 [ʒ]，结尾 -er 读 [e]；复数 salles à manger，manger 不变。","et":"salle 来自法兰克语 *sal（大厅）；manger 来自拉丁语 manducare（咀嚼）。","ex":[["Nous mangeons dans la salle à manger.","我们在餐厅吃饭。"],["La salle à manger est à côté de la cuisine.","餐厅在厨房旁边。"],["Mets la table dans la salle à manger.","在餐厅摆桌子。"]],"co":[["une table de salle à manger","餐桌"],["manger dans la salle à manger","在餐厅吃饭"],["une salle à manger moderne","现代风格的餐厅"],["mettre la table","摆桌子"]],"sy":[["salon","courant","客厅"],["séjour","courant","起居室"],["réfectoire","courant","学校或修道院的食堂"]],"fq":"中频，家居常用。","me":"salle + à manger：用来「吃」的房间。","tr":{"zh":"餐厅里有一张很长的桌子。","fr":"Il y a une très longue table dans la salle à manger.","alt":"Dans la salle à manger, il y a une table très longue.","note":"long 的阴性是 longue；table 是阴性。"}},
 "Une salle de bain": {"pos":"n.f. 阴性名词，复数 salles de bain(s)（也写 salle de bains）","s":"浴室。两种写法都可以：salle de bain 和 salle de bains。可以有浴缸或淋浴。","ipa":"[sal də bɛ̃]","ph":"salle [sal]；de 弱读 [də]；bain 读鼻音 [bɛ̃]，n 不读。","pi":"bain 的 ain 是鼻音 [ɛ̃]，不要读 n；salle de bain 里没有厕所也很常见（厕所叫 toilettes）。","et":"salle（来自法兰克语 *sal「厅」）+ de + bain（拉丁语 balneum「浴」）。","ex":[["La salle de bain est petite.","浴室很小。"],["Elle est dans la salle de bain, elle se brosse les dents.","她在浴室里刷牙。"],["Il y a une fuite d'eau dans la salle de bain.","浴室漏水了。"]],"co":[["une salle de bain équipée","设施齐全的浴室"],["une serviette de bain","浴巾"],["un tapis de bain","浴室垫"],["prendre un bain","泡澡"]],"sy":[["salle d'eau","courant","只有淋浴的浴室"],["toilettes","courant","厕所"],["WC","courant","厕所"]],"fq":"高频，住宅话题常用。","me":"salle de bain(s)：有 bain 就是「洗澡」的房间。","tr":{"zh":"浴室里有一面大镜子。","fr":"Il y a un grand miroir dans la salle de bain.","alt":"La salle de bains a un grand miroir.","note":"salle de bain 和 salle de bains 都对。"}},
 "Une table": {"pos":"n.f. 阴性名词，复数 tables","s":"桌子；餐桌；表格。À table ! = 开饭了！table des matières = 目录。","ipa":"[tabl]","ph":"ta [ta]；-ble 读 [bl]，结尾 e 不发音：一个音节 [tabl]。","pi":"a 是 [a]，不是英语的 [eɪ]；结尾不加元音。","et":"拉丁语 tabula（木板、桌板）。同族：tableau、tablette。","ex":[["Le livre est sur la table.","书在桌子上。"],["À table ! Le dîner est prêt.","开饭了！晚饭好了。"],["J'ai réservé une table pour deux.","我订了一张两人桌。"]],"co":[["mettre la table","摆桌子"],["débarrasser la table","收拾桌子"],["À table !","开饭了！"],["la table des matières","目录"]],"sy":[["bureau","courant","书桌"],["comptoir","courant","柜台"],["guéridon","soutenu","小圆桌"]],"fq":"极高频，日常常用。","me":"table 读「他布」：一个音节。","tr":{"zh":"请帮我摆桌子。","fr":"Peux-tu mettre la table, s'il te plaît ?","alt":"Tu m'aides à mettre la table ?","note":"mettre la table = 摆餐具。"}},
 "Une table basse": {"pos":"n.f. 阴性名词，复数 tables basses","s":"茶几；矮桌。放在沙发前面的矮桌子。basse 是 bas（低）的阴性。","ipa":"[tabl bas]","ph":"table [tabl]；basse 读 [bas]，ss 读 [s]，结尾 e 不发音。","pi":"basse 的 ss 读 [s]，不是 [z]；形容词要放在名词后并与之同性数：tables basses。","et":"table（拉丁语 tabula）+ basse（bas，来自晚期拉丁语 bassus「矮的」）。","ex":[["Le café est sur la table basse.","咖啡放在茶几上。"],["Les enfants jouent près de la table basse.","孩子们在茶几旁玩。"],["On a mis les magazines sur la table basse.","我们把杂志放在茶几上。"]],"co":[["une table basse en bois","木茶几"],["poser sur la table basse","放在茶几上"],["une table de chevet","床头柜"],["une table de salon","客厅桌"]],"sy":[["table de salon","courant","茶几的另一说法"],["guéridon","soutenu","小圆桌"],["table de chevet","courant","床头柜"]],"fq":"中频，家居常用。","me":"table + basse：低低的桌子，像 bass（低音）。","tr":{"zh":"请把杯子放在茶几上。","fr":"Pose les tasses sur la table basse, s'il te plaît.","alt":"Mets les tasses sur la table basse.","note":"poser = 放（平放）。"}},
 "Une télé (télévision)": {"pos":"n.f. 阴性名词，复数 télés","s":"电视。télé 是 télévision 的口语缩写，指电视机，也指电视节目。regarder la télé = 看电视。","ipa":"[te.le]","ph":"télé 读 [te.le]，两个 é 都是 [e]；télévision 读 [te.le.vi.zjɔ̃]。","pi":"télévision 的 -sion 读 [zjɔ̃]，s 读 [z]；télé 结尾是 [e]，不是 [i]。","et":"希腊语 tele（远）+ 拉丁语 visio（看见）；télé 是缩写。","ex":[["Nous avons une grande télé.","我们有一台大电视。"],["Il regarde la télé tous les soirs.","他每天晚上看电视。"],["Éteins la télé, il est tard.","把电视关了，很晚了。"]],"co":[["regarder la télé","看电视"],["allumer / éteindre la télé","开 / 关电视"],["à la télé","在电视上"],["une chaîne de télévision","电视频道"]],"sy":[["téléviseur","courant","电视机"],["écran","courant","屏幕"],["téloche","familier","电视（口语）"]],"fq":"极高频，日常常用。","me":"télé：两个 é，都读 [e]，像「泰勒」。","tr":{"zh":"今晚电视上有什么节目？","fr":"Qu'est-ce qu'il y a à la télé ce soir ?","alt":"Y a quoi à la télé ce soir ?","note":"à la télé = 在电视上。"}},
 "Une terrasse": {"pos":"n.f. 阴性名词，复数 terrasses","s":"露台；平台；咖啡馆门口的露天座位（en terrasse）。比 balcon（阳台）更大，常在地面或屋顶。","ipa":"[te.ʁas]","ph":"te [te]；rr 只读一个 [ʁ]；-asse 读 [as]。","pi":"rr 只读一个 r；结尾 -asse 读 [as]，不读 [ɪs]；重音在最后。","et":"来自 terre（土地），拉丁语 terra；原指堆起的平地。","ex":[["Nous dînons sur la terrasse.","我们在露台吃晚饭。"],["On prend un café en terrasse ?","我们去露天座喝杯咖啡吧？"],["L'appartement a une grande terrasse.","这套公寓有一个大露台。"]],"co":[["manger en terrasse","在露天座吃饭"],["une terrasse de café","咖啡馆的露天座"],["une terrasse ensoleillée","阳光充足的露台"],["une terrasse sur le toit","屋顶露台"]],"sy":[["balcon","courant","阳台"],["toit-terrasse","courant","屋顶露台"],["véranda","courant","玻璃阳光房"]],"fq":"高频，住宅和餐厅都常用。","me":"terrasse ← terre：踩在「土地」上的平台。","tr":{"zh":"我们在露台上喝咖啡。","fr":"Nous buvons le café sur la terrasse.","alt":"On prend le café sur la terrasse.","note":"prendre un café = 喝咖啡。"}},
 "Des déchets": {"pos":"n.m.pl. 阳性复数名词，单数 un déchet","s":"垃圾；废物；废料。多用复数 les déchets。trier les déchets = 垃圾分类。","ipa":"[de.ʃɛ]","ph":"dé [de]；ch [ʃ]；-et 读 [ɛ]；结尾 ts 不发音。","pi":"结尾 -ts 都不发音；单数 déchet 和复数 déchets 发音相同；ch 读 [ʃ]，不是 [k]。","et":"来自 déchoir（掉下、衰落），拉丁语 de- + cadere（落）。","ex":[["Il faut jeter les déchets.","要扔掉垃圾。"],["Trions nos déchets : le verre, le papier.","我们把垃圾分类吧：玻璃、纸。"],["Les déchets plastiques polluent la mer.","塑料垃圾污染大海。"]],"co":[["trier les déchets","垃圾分类"],["réduire les déchets","减少垃圾"],["les déchets ménagers","生活垃圾"],["les déchets recyclables","可回收垃圾"]],"sy":[["ordures","courant","垃圾（日常，复数）"],["détritus","courant","废弃物、碎屑"],["résidus","soutenu","残渣"]],"fq":"高频，环保和日常话题常用。","me":"déchet ← déchoir：「掉」出有用范围的东西。","tr":{"zh":"要把可回收垃圾分类。","fr":"Il faut trier les déchets recyclables.","alt":"On doit trier les déchets pour le recyclage.","note":"il faut + 动词原形 = 必须。"}},
 "Des escaliers": {"pos":"n.m.pl. 阳性复数名词，单数 un escalier","s":"楼梯。法语常用复数 les escaliers，也可以说单数 l'escalier；意思相同。prendre l'escalier = 走楼梯。","ipa":"[ɛs.ka.lje]","ph":"es [ɛs]；ca [ka]；-lier 读 [lje]；des 与它连读成 [de.zɛs.ka.lje]。","pi":"结尾 -ers 读 [e]，r 与 s 都不读；des 后要连读 z。","et":"拉丁语 scalarium，来自 scala（梯子）。同族：escalator、escalade。","ex":[["Je prends les escaliers.","我走楼梯。"],["L'ascenseur est en panne : montez par les escaliers.","电梯坏了，请走楼梯。"],["Attention, les escaliers sont glissants.","小心，楼梯很滑。"]],"co":[["monter / descendre les escaliers","上楼 / 下楼"],["prendre l'escalier","走楼梯"],["un escalier roulant","自动扶梯"],["un escalier de secours","消防楼梯"]],"sy":[["ascenseur","courant","电梯（相对的选择）"],["marches","courant","台阶"],["escalator","courant","自动扶梯"]],"fq":"高频，住宅和公共场所常用。","me":"escaliers 里有 scala（梯子）：一级一级爬。","tr":{"zh":"电梯坏了，我们走楼梯吧。","fr":"L'ascenseur est en panne, on prend les escaliers.","alt":"Comme l'ascenseur ne marche pas, prenons l'escalier.","note":"escalier 单数或复数都可以。"}},
 "Des toilettes": {"pos":"n.f.pl. 阴性名词，几乎只用复数 les toilettes","s":"厕所；洗手间。法语几乎总用复数 les toilettes，哪怕只有一间。礼貌问路就说 Où sont les toilettes ?，也常说 les WC。","ipa":"[twa.lɛt]","ph":"oi 读 [wa]；-ette 的 t 要发音，结尾 e 不发，s 也不发。","pi":"oi 读 [wa]，不是「奥伊」；虽然指一间，动词仍用复数：les toilettes sont…","et":"来自 toile（布）加指小后缀 -ette：原指梳洗用的小布，后来指梳洗打扮，再引申为梳洗的房间。","ex":[["Où sont les toilettes ?","厕所在哪里？"],["Les toilettes sont au fond du couloir.","厕所在走廊尽头。"],["Je vais aux toilettes.","我去一下洗手间。"]],"co":[["aller aux toilettes","去厕所"],["les toilettes publiques","公共厕所"],["le papier toilette","卫生纸"],["faire sa toilette","梳洗"]],"sy":[["les WC","courant","最常见的说法，读 [ve.se]"],["les sanitaires","courant","公共场所、营地的卫生设施"],["le petit coin","familier","委婉说法，「小角落」"]],"fq":"极高频，日常必备。","me":"toile（布）+ ette = 小布 → 梳洗 → 洗手间；永远是复数。","tr":{"zh":"请问，洗手间在哪里？","fr":"Excusez-moi, où sont les toilettes ?","alt":"Pardon, les toilettes, c'est où ?","note":"toilettes 用复数，动词也用 sont。"}},
 "Un frigo / Un réfrigérateur": {"pos":"n.m. 阳性名词，复数 frigos / réfrigérateurs","s":"冰箱。frigo 是口语简称，réfrigérateur 是完整说法，两者都很常用。冷冻室叫 le congélateur。","ipa":"[fʁi.ɡo] / [ʁe.fʁi.ʒe.ʁa.tœʁ]","ph":"frigo：g 在 o 前读硬音 [ɡ]。réfrigérateur：g 在 é 前读 [ʒ]；-eur 读 [œʁ]。","pi":"frigo 的 g 是 [ɡ]，réfrigérateur 的 g 是 [ʒ]，同一词根两种读法；两个词都是阳性。","et":"frigo 是 Frigidaire（早期冰箱品牌）的缩写；réfrigérateur 来自拉丁语 refrigerare（使变凉），同源 frais。","ex":[["Le lait est dans le frigo.","牛奶在冰箱里。"],["Mets le beurre au réfrigérateur.","把黄油放进冰箱。"],["Il n'y a plus rien dans le frigo.","冰箱里什么都没有了。"]],"co":[["mettre au frigo","放进冰箱"],["ouvrir le frigo","打开冰箱"],["un frigo vide / plein","空 / 满的冰箱"],["le frigo et le congélateur","冷藏室和冷冻室"]],"sy":[["le congélateur","courant","冷冻柜，不是冷藏"],["la glacière","courant","保温冷藏箱（野餐用）"],["le frigidaire","familier","老一辈的说法，来自品牌名"]],"fq":"极高频，口语多用 frigo。","me":"frigo 听起来像 frigid（冰冷的）：冷冷的小盒子。","tr":{"zh":"把牛奶放进冰箱里。","fr":"Mets le lait dans le frigo.","alt":"Range le lait au frigo, s'il te plaît.","note":"放进冰箱可说 dans le frigo 或 au frigo。"}},
 "Un(e) plombier / plombière": {"pos":"n.m./n.f. 名词，男 plombier，女 plombière（实际常说 une plombier / une femme plombier）","s":"水管工；管道工。负责修水管、暖气、卫生间漏水。阴性 plombière 很少用，女性水管工常说 une plombière 或 une plombier。","ipa":"[plɔ̃.bje]","ph":"om 后接 b，鼻化 [ɔ̃]，m 不单独发音；-ier 读 [je]；结尾 r 不发。","pi":"plomb 的 b 在词内要发 [b]，结尾 -ier 的 r 不发音；注意 [ɔ̃] 不是「翁」。","et":"来自 plomb（铅，拉丁语 plumbum）加后缀 -ier：最初用铅管，所以叫「铅工」。","ex":[["J'appelle un plombier pour la fuite.","我叫水管工来修漏水。"],["Le plombier arrive demain matin.","水管工明天早上来。"],["Il travaille comme plombier.","他当水管工。"]],"co":[["appeler un plombier","叫水管工"],["une fuite d'eau","漏水"],["un plombier-chauffagiste","水管暖气工"]],"sy":[["le chauffagiste","courant","暖气安装工"],["le bricoleur","courant","自己动手修的人"],["le dépanneur","courant","抢修师傅"]],"fq":"中频，家里出问题时常用。","me":"plomb（铅）→ 铅管 → 水管工；英语 plumber 同源。","tr":{"zh":"厨房漏水，我要叫水管工。","fr":"Il y a une fuite dans la cuisine, j'appelle un plombier.","alt":"Ça fuit dans la cuisine, je vais appeler le plombier.","note":"il y a une fuite = 有漏水；fuite 为阴性。"}},
 "Un(e) propriétaire": {"pos":"n.m./n.f. 名词，阴阳同形：un propriétaire / une propriétaire，复数 propriétaires","s":"房东；业主；所有者。出租房子的人叫 propriétaire，租房的人叫 locataire。也可指狗、车等的主人。","ipa":"[pʁɔ.pʁi.e.tɛʁ]","ph":"两个 pr 都是小舌音 [ʁ]；-ié- 分成 [i.e]（四个音节）；结尾 -aire 读 [ɛʁ]。","pi":"音节很多，别吞音：pro-pri-é-taire；结尾 -aire 是 [ɛʁ]，不是「爱」；阴阳同形，靠冠词分男女。","et":"来自拉丁语 proprietarius（所有者），源自 proprius（自己的）。同族：propre（自己的；干净的）、propriété（财产）。","ex":[["Le propriétaire est très gentil.","房东人很好。"],["Elle est propriétaire de deux appartements.","她拥有两套公寓。"],["Je paie le loyer au propriétaire.","我把房租付给房东。"]],"co":[["le propriétaire d'un appartement","公寓的业主"],["être propriétaire de","拥有……"],["propriétaire ou locataire","房主还是租客"]],"sy":[["le bailleur","soutenu","出租人，合同里常用"],["le locataire","courant","反义：租客"],["le patron","familier","房东的口语叫法，也指老板"]],"fq":"中高频，租房、买房时常用。","me":"proprié-taire：拥有 propre（自己的）东西的人。","tr":{"zh":"我的房东住在楼下。","fr":"Mon propriétaire habite au rez-de-chaussée.","alt":"Le propriétaire vit en bas, juste en dessous de chez moi.","note":"propriétaire 阴阳同形，说女房东用 ma propriétaire。"}},
 "Brûler": {"pos":"v. 第一组规则动词（-er），助动词 avoir；代词式 se brûler","s":"烧；烧焦；烧伤。可以是及物（brûler du bois 烧木头）或不及物（le feu brûle 火在烧）。se brûler = 烫伤自己。","ipa":"[bʁy.le]","ph":"û 读 [y]（嘴唇圆起，发「雨」的音）；-er 读 [e]，r 不发。","pi":"û 不是「乌」[u]，要读 [y]；û 上的帽子表示以前有个 s，不改变读音。","et":"来源不确定（有拉丁语与日耳曼语两种说法）。构词：brûlure（烧伤）、brûlant（滚烫的）、brûleur（燃烧器）。","ex":[["Attention à ne pas brûler le repas.","小心别把饭烧焦了。"],["Le bois brûle dans la cheminée.","木头在壁炉里燃烧。"],["Je me suis brûlé la main.","我烫伤了手。"]],"co":[["se brûler la main","烫伤手"],["brûler un feu rouge","闯红灯"],["brûler de + 动词原形","迫不及待想……"],["brûler les étapes","跳步骤；操之过急"]],"sy":[["cramer","familier","烧焦，烧着"],["flamber","courant","起火燃烧"],["calciner","soutenu","烧成灰"]],"fq":"高频，日常和烹饪常用。","me":"û 的帽子像一顶「火焰帽」：brûler = 起火了。","tr":{"zh":"小心，汤会烧焦的！","fr":"Attention, la soupe va brûler !","alt":"Fais gaffe, la soupe va cramer !","note":"aller + 原形表示即将发生。"}},
 "Commencer": {"pos":"v. 第一组规则动词（-er），助动词 avoir；nous commençons","s":"开始。commencer à + 动词原形 = 开始做某事；commencer par + 名词/原形 = 以……开始，先做……。及物与不及物都可。","ipa":"[kɔ.mɑ̃.se]","ph":"om 读 [ɔ] 加 m；en 读鼻化 [ɑ̃]；c 在 e 前读 [s]；结尾 r 不发。","pi":"第一人称复数拼成 commençons（c 下加小钩，保持 [s] 音）；注意 commencer 后面用 à，不是 de（也可用 de，但 à 更常见）。","et":"来自晚期拉丁语 cominitiare（com- + initiare，开始），同源 initial。","ex":[["Le film va commencer.","电影要开始了。"],["Je commence à travailler à huit heures.","我八点开始工作。"],["Nous commençons par la première page.","我们从第一页开始。"]],"co":[["commencer à + 原形","开始做……"],["commencer par","先从……开始"],["pour commencer","首先；一开始"],["commencer la journée","开始新的一天"]],"sy":[["débuter","courant","起步，开始（事情或职业）"],["démarrer","courant","启动，发动"],["finir","courant","反义：结束"]],"fq":"极高频，日常常用。","me":"com-mencer：和 commence 一样，ç 给你「开始」的信号。","tr":{"zh":"我们十点开始开会。","fr":"On commence la réunion à dix heures.","alt":"La réunion commence à dix heures.","note":"commencer 后接时间用 à 十点：à dix heures。"}},
 "Écouter": {"pos":"v. 第一组规则动词（-er），助动词 avoir","s":"听；认真地听。écouter 是主动、专心地听（音乐、别人说话），后面直接接宾语，不加介词。被动听见用 entendre。","ipa":"[e.ku.te]","ph":"é 读 [e]；cou 读 [ku]；-ter 读 [te]，r 不发。","pi":"écouter la musique，不是 écouter à la musique：直接接宾语，不加介词；和 entendre（听见）要区分。","et":"来自拉丁语 auscultare（听）。医学词 ausculter（听诊）是同一个词的学术形式。","ex":[["J'aime écouter de la musique.","我喜欢听音乐。"],["Écoute-moi bien.","你好好听我说。"],["Il n'écoute jamais ses parents.","他从不听父母的话。"]],"co":[["écouter de la musique","听音乐"],["écouter la radio","听广播"],["écouter quelqu'un","听某人说；听某人的话"],["Écoutez !","听着！"]],"sy":[["entendre","courant","听见（不是故意听）"],["prêter l'oreille","soutenu","侧耳倾听"],["obéir","courant","écouter 也有「听话」的意思，常换成 obéir"]],"fq":"极高频，日常常用。","me":"écouter：用耳朵（oreille）专心地听，和 entendre 不同。","tr":{"zh":"晚上我喜欢听广播。","fr":"Le soir, j'aime écouter la radio.","alt":"Le soir, j'écoute la radio.","note":"écouter 直接接宾语，不加介词。"}},
 "Entrer": {"pos":"v. 第一组规则动词（-er），助动词 être：je suis entré(e)","s":"进入；进来。entrer dans + 地点 = 进入某地；entrer 的复合时态用 être。命令式 Entrez ! = 请进！。","ipa":"[ɑ̃.tʁe]","ph":"en 读鼻化 [ɑ̃]；tr 连读 [tʁ]；-er 读 [e]，r 不发。","pi":"复合过去时用 être：Elle est entrée，不是 a entré；过去分词要和主语性数一致；entrer 后面用 dans，不直接接地点。","et":"来自拉丁语 intrare（进入），同源英语 enter。派生：rentrer（回去；回家）、entrée（入口；前菜）。","ex":[["Vous pouvez entrer.","您可以进来。"],["Elle est entrée dans la cuisine.","她走进了厨房。"],["Entrez, je vous en prie !","请进！"]],"co":[["entrer dans la pièce","走进房间"],["entrer en classe","进教室"],["Entrez !","请进！"],["entrer en vigueur","生效；开始实施"]],"sy":[["rentrer","courant","回去；回家；再进去"],["pénétrer","soutenu","进入，渗入"],["sortir","courant","反义：出去"]],"fq":"极高频，日常常用。","me":"entrer ← intrare：In 和 en 一样，都是「进」。","tr":{"zh":"他们走进了餐厅。","fr":"Ils sont entrés dans le restaurant.","alt":"Ils sont rentrés dans le restaurant.","note":"entrer 用 être，分词与主语一致：entrés。"}},
 "Fermer": {"pos":"v. 第一组规则动词（-er），助动词 avoir","s":"关；关闭；打烊。可以关门、窗、灯、水龙头，也可指商店下班：Le magasin ferme à 19 h。反义词是 ouvrir。","ipa":"[fɛʁ.me]","ph":"fer 读 [fɛʁ]，r 要发小舌音；-mer 读 [me]，r 不发。","pi":"e 在 fer- 中读 [ɛ]，不是「福」；词尾 r 不发音；Ferme-la ! 很粗鲁，意思是「闭嘴」。","et":"来自拉丁语 firmare（使牢固），源自 firmus（牢固的）。同族：ferme（牢固的；农场）、fermeture（关闭）、fermeture éclair（拉链）。","ex":[["Ferme la porte en sortant.","出去时把门关上。"],["Le magasin ferme à dix-neuf heures.","商店十九点关门。"],["Ferme les yeux !","闭上眼睛！"]],"co":[["fermer la porte à clé","把门锁上"],["fermer les yeux","闭上眼睛"],["fermer le robinet","关水龙头"],["fermer un compte","注销账户"]],"sy":[["verrouiller","courant","插上门闩；锁死"],["clore","soutenu","结束，关闭"],["ouvrir","courant","反义：打开"]],"fq":"极高频，日常常用。","me":"fermer ← firmus：关上之后就「牢固」了（firm）。","tr":{"zh":"请关上窗户，外面太吵了。","fr":"Ferme la fenêtre, s'il te plaît, il y a trop de bruit.","alt":"Tu peux fermer la fenêtre ? Ça fait trop de bruit.","note":"命令式 tu 形：ferme，没有 s。"}},
 "Fumer": {"pos":"v. 第一组规则动词（-er），助动词 avoir","s":"吸烟；抽烟。可以说 fumer une cigarette，也可单用：Il fume trop。不用于电子烟，电子烟用 vapoter。","ipa":"[fy.me]","ph":"u 读 [y]（圆唇的「雨」音）；-mer 读 [me]。","pi":"u 读 [y]，不要说成「福」[u]；Défense de fumer 是常见禁烟标志；不要和 fumée（烟）混淆。","et":"来自拉丁语 fumare，源自 fumus（烟）。同族：fumée（烟）、fumeur（吸烟者）、parfum（香水，原指「穿过烟」）。","ex":[["Il est interdit de fumer ici.","这里禁止吸烟。"],["Mon père a arrêté de fumer.","我爸爸戒烟了。"],["Vous fumez ?","您抽烟吗？"]],"co":[["Défense de fumer","禁止吸烟"],["fumer une cigarette","抽一支烟"],["arrêter de fumer","戒烟"],["un fumeur / une zone fumeur","吸烟者 / 吸烟区"]],"sy":[["griller une cigarette","familier","抽根烟"],["vapoter","courant","抽电子烟"],["tirer sur","familier","抽（一口）"]],"fq":"高频，公共场所标志常见。","me":"fumer ← fumus：有烟（fumée）就是 fumer。","tr":{"zh":"这里不能抽烟。","fr":"Ici, on ne peut pas fumer.","alt":"C'est interdit de fumer ici.","note":"on ne peut pas + 原形：口语中的「不可以」。"}},
 "Oublier": {"pos":"v. 第一组规则动词（-er），助动词 avoir","s":"忘记；忘了带。oublier + 名词 = 忘了某物（也可指忘带）；oublier de + 原形 = 忘了做某事。反义是 se souvenir / se rappeler。","ipa":"[u.bli.je]","ph":"ou 读 [u]；bl 连读 [bl]；-ier 读 [je]，r 不发。","pi":"oublier de + 原形，不是 à；ou 读 [u]，三个音节 [u.bli.je]；j'ai oublié 可表示「忘了做」或「忘了带」。","et":"来自晚期拉丁语 oblitare，源自 oblitus（oblivisci「忘记」的分词）。同源英语 oblivion。","ex":[["J'ai oublié mon livre.","我忘了带书。"],["N'oublie pas ton parapluie !","别忘了带伞！"],["J'ai oublié de fermer la porte.","我忘了关门。"]],"co":[["oublier de + 原形","忘了做……"],["oublier son téléphone","忘了带手机"],["Je n'oublierai jamais ça.","我永远不会忘记这个。"],["Oublie !","算了！别提了！"]],"sy":[["omettre","soutenu","漏掉，省略"],["négliger","courant","疏忽，忽视"],["se souvenir de","courant","反义：记得"]],"fq":"极高频，日常常用。","me":"oublier：东西从脑子里「溜」出去；ou-bli-er 三个音节顺着念。","tr":{"zh":"我忘了给你打电话。","fr":"J'ai oublié de t'appeler.","alt":"J'ai complètement oublié de te téléphoner.","note":"oublier de + 原形；t' 是 te 的省音形式。"}},
 "Perdre": {"pos":"v. 第三组不规则动词，助动词 avoir：je perds，nous perdons，过去分词 perdu","s":"丢失；输（比赛）；浪费（时间）。perdre du poids = 减肥；perdre son temps = 浪费时间；se perdre = 迷路。","ipa":"[pɛʁdʁ]","ph":"per 读 [pɛʁ]；dre 读 [dʁ]，结尾 e 不发，所以只有一个音节。","pi":"je perds / tu perds / il perd 同音 [pɛʁ]，s、d 都不发；过去分词 perdu 的 u 读 [y]。","et":"来自拉丁语 perdere（毁掉，丢失）。同源英语 perdition。","ex":[["J'ai peur de perdre mon téléphone.","我怕丢手机。"],["Notre équipe a perdu le match.","我们队输了比赛。"],["Ne perds pas ton temps !","别浪费时间！"]],"co":[["perdre ses clés","丢钥匙"],["perdre du poids","减重"],["perdre son temps","浪费时间"],["se perdre","迷路"]],"sy":[["égarer","courant","放错地方、一时找不到"],["paumer","familier","弄丢"],["gagner","courant","反义：赢；获得"]],"fq":"极高频，日常常用。","me":"je perds 里 d 也不读：丢东西，连字母 d 也一起「丢」了。","tr":{"zh":"别丢了你的钥匙。","fr":"Ne perds pas tes clés.","alt":"Fais attention à ne pas perdre tes clés.","note":"否定命令式：ne + 动词 + pas。"}},
 "Recommencer": {"pos":"v. 第一组规则动词（-er），助动词 avoir；nous recommençons","s":"重新开始；再做一遍；又开始。recommencer à + 原形 = 又开始做……；recommencer à zéro = 从头再来。","ipa":"[ʁə.kɔ.mɑ̃.se]","ph":"re- 读弱元音 [ʁə]；其余同 commencer：[kɔ.mɑ̃.se]；c 在 e 前读 [s]。","pi":"re- 读 [ʁə]，不是「累」；nous recommençons 也要加 ç；和 commencer 的构词一一对应。","et":"re-（再）+ commencer（开始）：前缀 re- 表示重复，同样的结构见于 refaire、relire、redire。","ex":[["Je dois recommencer mon travail.","我得重做我的工作。"],["Il recommence à pleuvoir.","又开始下雨了。"],["On recommence à zéro ?","我们从头再来？"]],"co":[["recommencer à + 原形","又开始……"],["recommencer à zéro","从零开始"],["Ne recommence pas !","别再这样了！"],["tout recommencer","全部重来"]],"sy":[["refaire","courant","重做"],["reprendre","courant","继续，恢复"],["répéter","courant","重复"]],"fq":"高频，日常常用。","me":"re + commencer = 再开始；re- 就是「再一次」。","tr":{"zh":"这一页我得重写。","fr":"Je dois recommencer cette page.","alt":"Il faut que je refasse cette page.","note":"devoir + 原形表示「必须」。"}},
 "Regarder": {"pos":"v. 第一组规则动词（-er），助动词 avoir","s":"看；注视；观看。regarder 是主动地看（电影、电视、人），后面直接接宾语，不加介词。「看见」用 voir；「看起来」用 avoir l'air。","ipa":"[ʁə.ɡaʁ.de]","ph":"re- 读 [ʁə]；gar 读 [ɡaʁ]，g 是硬音 [ɡ]；-der 读 [de]。","pi":"regarder la télé，不是 regarder à la télé；和 voir（看见）区分：regarder 是有意去看。","et":"re- + garder（注意，保护），garder 来自日耳曼语（法兰克语）。原意是「再看护」，后来变成「看」。同族：regard（目光）、garde（守卫）。","ex":[["Je regarde un film.","我在看电影。"],["Regarde ! Il neige.","看！下雪了。"],["Elle regarde par la fenêtre.","她朝窗外看。"]],"co":[["regarder la télévision","看电视"],["regarder un film","看电影"],["regarder par la fenêtre","往窗外看"],["Ça ne te regarde pas.","这不关你的事。"]],"sy":[["voir","courant","看见，眼睛所见"],["observer","soutenu","观察"],["mater","familier","偷看，盯着看"]],"fq":"极高频，日常必备。","me":"regarder = re + garder：「再 + 守着」，眼睛一直盯着。","tr":{"zh":"我们今晚看电影吧。","fr":"On regarde un film ce soir ?","alt":"Si on regardait un film ce soir ?","note":"on = 我们（口语）。"}},
 "Régler": {"pos":"v. 第一组规则动词（-er），助动词 avoir；je règle，nous réglons","s":"处理；解决（问题）；调节（音量、温度）；付款。régler un problème = 解决问题；régler l'addition = 买单；régler le volume = 调音量。","ipa":"[ʁe.ɡle]","ph":"é 读 [e]；gl 连读 [ɡl]，g 是硬音；-er 读 [e]。","pi":"变位时 é 变 è：je règle, ils règlent，但 nous réglons 仍是 é；gl 要连着读，别加元音。","et":"来自拉丁语 regula（规则、尺子），同源英语 regulate。同族：règle（规则；尺子）、règlement（规章）、réglage（调节）。","ex":[["Je vais régler ce problème.","我来解决这个问题。"],["Je règle l'addition.","我来买单。"],["Peux-tu régler le volume ?","你能调一下音量吗？"]],"co":[["régler un problème","解决问题"],["régler l'addition","买单"],["régler par carte","刷卡付款"],["régler le réveil","调闹钟"]],"sy":[["résoudre","courant","解决（难题、问题）"],["payer","courant","付钱"],["ajuster","courant","调整"]],"fq":"高频，办事与付款时常用。","me":"régler ← règle（规则）：按规则把事情弄「顺」。","tr":{"zh":"我可以刷卡付款吗？","fr":"Je peux régler par carte ?","alt":"Je peux payer par carte ?","note":"régler par + 付款方式。"}},
 "Rencontrer": {"pos":"v. 第一组规则动词（-er），助动词 avoir；se rencontrer = 彼此相遇","s":"遇见；认识（新朋友）；碰到。rencontrer qqn = 偶然或第一次见到某人；约好见面要用 retrouver 或 voir。","ipa":"[ʁɑ̃.kɔ̃.tʁe]","ph":"ren 读 [ʁɑ̃]；con 读 [kɔ̃]（两个不同的鼻化元音）；-tre 读 [tʁe]。","pi":"ren [ɑ̃] 和 con [ɔ̃] 是两个不同的鼻音，别都读成「ong」；约好见面不用 rencontrer，用 retrouver。","et":"re- + encontrer（古法语，来自 en- + contre）：原意是「面对面碰上」。同源英语 encounter。","ex":[["J'aime rencontrer de nouvelles personnes.","我喜欢认识新朋友。"],["Je l'ai rencontré à Paris.","我是在巴黎遇见他的。"],["Nous nous sommes rencontrés à l'école.","我们在学校认识的。"]],"co":[["rencontrer quelqu'un","遇见某人"],["se rencontrer","彼此相遇"],["rencontrer des difficultés","遇到困难"],["une rencontre","一次相遇；会面"]],"sy":[["retrouver","courant","和某人会合（事先约好）"],["croiser","courant","擦肩而过地碰见"],["faire la connaissance de","soutenu","初次认识"]],"fq":"高频，日常常用。","me":"re + en + contre：迎面（contre）碰上 = 遇见。","tr":{"zh":"我昨天在街上遇见了我的老师。","fr":"Hier, j'ai rencontré mon professeur dans la rue.","alt":"Hier, j'ai croisé mon prof dans la rue.","note":"croiser 更强调只是碰见。"}},
 "Renverser": {"pos":"v. 第一组规则动词（-er），助动词 avoir","s":"打翻；洒出；撞倒。renverser un verre = 打翻杯子；renverser un piéton = 撞倒行人；renverser un gouvernement = 推翻政府。","ipa":"[ʁɑ̃.vɛʁ.se]","ph":"ren 读 [ʁɑ̃]；ver 读 [vɛʁ]，r 要发；-ser 读 [se]，s 读 [s]。","pi":"多是「不小心」打翻：Il a renversé son café；故意倒用 verser。别和 renvoyer（退回；解雇）混淆。","et":"re- + enverser（en- + 同族 vers、envers）：意思是「翻过来」。同族：verser（倒）、envers（背面）。","ex":[["Il a renversé son verre d'eau.","他打翻了水杯。"],["Attention, tu vas renverser le café !","小心，你会把咖啡洒了！"],["Une voiture a renversé un piéton.","一辆车撞倒了一名行人。"]],"co":[["renverser un verre","打翻杯子"],["renverser du café sur la table","把咖啡洒在桌上"],["renverser un piéton","撞倒行人"],["renverser un gouvernement","推翻政府"]],"sy":[["verser","courant","倒（有意地）"],["répandre","soutenu","洒出，使散开"],["faire tomber","courant","使掉落"]],"fq":"中频，日常小意外常用。","me":"re + en + vers：把杯子「翻」过来，水就洒了。","tr":{"zh":"我不小心把牛奶洒在了桌子上。","fr":"J'ai renversé du lait sur la table.","alt":"J'ai fait tomber du lait sur la table sans faire exprès.","note":"不小心可加 sans faire exprès。"}},
 "Réparer": {"pos":"v. 第一组规则动词（-er），助动词 avoir","s":"修理；修复；弥补。réparer un vélo = 修自行车；réparer une erreur = 弥补错误。请别人修理要说 faire réparer。","ipa":"[ʁe.pa.ʁe]","ph":"每个音节清楚：ré [ʁe]、pa [pa]、rer [ʁe]；两个 r 都是小舌音。","pi":"第一个 é 读 [e]，不是「雷」；去修车店说 faire réparer sa voiture，而不是自己动手。","et":"来自拉丁语 reparare（重新准备、修复），同源英语 repair。同族：réparation（修理）。","ex":[["Je dois réparer mon vélo.","我得修自行车。"],["Le garagiste a réparé la voiture.","修车师傅修好了车。"],["Il veut réparer son erreur.","他想弥补自己的错误。"]],"co":[["réparer une voiture","修车"],["faire réparer","找人修"],["réparer une erreur","弥补错误"],["un atelier de réparation","修理铺"]],"sy":[["dépanner","courant","抢修；也指临时帮人解围"],["arranger","courant","整理好；修好（小毛病）"],["bricoler","familier","自己动手凑合修"]],"fq":"高频，日常常用。","me":"ré + parer：「重新」(re) 弄好 (pare) = 修理。","tr":{"zh":"你能帮我修一下这台电脑吗？","fr":"Tu peux m'aider à réparer cet ordinateur ?","alt":"Tu peux me réparer cet ordi ?","note":"aider à + 原形；ordinateur 是阳性，所以用 cet。"}},
 "Tenir": {"pos":"v. 第三组不规则动词，助动词 avoir：je tiens，nous tenons，ils tiennent，过去分词 tenu，将来时 tiendrai","s":"拿着；握住；支撑；容纳。tenir à = 很在意，坚持；Tiens ! = 喏，给你；咦。se tenir = 站好、举止。tenir bon = 坚持住。","ipa":"[tə.niʁ]","ph":"te 读弱元音 [tə]；-nir 读 [niʁ]。变位时 tiens 读 [tjɛ̃]，tenons 读 [tə.nɔ̃]。","pi":"变位陷阱：je tiens [tjɛ̃]，nous tenons [tə.nɔ̃]，词干会变；tenir à + 名词/原形（很想），tenir de 表示「像」。","et":"来自拉丁语 tenere（握住）。同族：retenir、obtenir、maintenir、contenir。英语中的 -tain 词（contain、retain）同源。","ex":[["Peux-tu tenir mon sac ?","你能帮我拿一下包吗？"],["Je tiens à te remercier.","我想特别感谢你。"],["Tiens, voilà ton café.","喏，这是你的咖啡。"]],"co":[["tenir la main","握着手"],["tenir à + 名词/原形","非常看重；一定要……"],["tenir compagnie","陪伴"],["tenir bon","坚持住"]],"sy":[["porter","courant","拿着、提着；穿戴"],["garder","courant","保留，看管"],["saisir","soutenu","抓住"]],"fq":"极高频，日常常用。","me":"tenir：手「握」住不放，想到英语 tenant（租户）、retain。","tr":{"zh":"你能帮我拿一下我的包吗？","fr":"Tu peux me tenir mon sac, s'il te plaît ?","alt":"Tu peux tenir mon sac deux minutes ?","note":"me tenir 是「替我拿」的口语用法。"}},
 "Trier": {"pos":"v. 第一组规则动词（-er），助动词 avoir","s":"分类；挑选；整理。trier les déchets = 垃圾分类；trier le courrier = 整理信件；trier les photos = 挑选照片。名词 le tri = 分类，如 le tri sélectif。","ipa":"[tʁi.je]","ph":"tri 读 [tʁi]；-er 读 [je]，注意 i 和 e 之间有一个 [j] 滑音。","pi":"读音是两个音节 [tʁi.je]，不要拼成「try」；trier 是分类，不是「尝试」（尝试用 essayer）。","et":"来源不确定（古法语 trier，可能与日耳曼语或拉丁语有关）。构词：tri（分类）、trieur（分拣员）、triage（分拣）。","ex":[["Merci de trier vos déchets.","请把垃圾分类。"],["Je trie mes vêtements avant le déménagement.","搬家前我整理衣服。"],["On trie le courrier tous les matins.","我们每天早上整理信件。"]],"co":[["trier les déchets","垃圾分类"],["le tri sélectif","分类回收"],["trier le courrier","整理信件"],["trier sur le volet","精挑细选"]],"sy":[["classer","courant","按类别归档"],["ranger","courant","把东西收拾整齐"],["sélectionner","courant","挑选"]],"fq":"中高频，环保与整理时常用。","me":"trier = tri + er：一堆东西「三」(tri) 个盒子分开放。","tr":{"zh":"你在家分类垃圾吗？","fr":"Tu tries tes déchets à la maison ?","alt":"Tu fais le tri de tes déchets chez toi ?","note":"faire le tri 也是「分类」。"}},
 "Vapoter": {"pos":"v. 第一组规则动词（-er），助动词 avoir","s":"吸电子烟；抽电子烟。名词：un vapoteur（吸电子烟的人）、une vapoteuse（电子烟）、la cigarette électronique。普通香烟用 fumer。","ipa":"[va.pɔ.te]","ph":"va 读 [va]；po 读 [pɔ]；-ter 读 [te]；三个音节。","pi":"别和 vaporiser（喷雾）混淆；三个音节 [va.pɔ.te]，va 里的 a 读 [a]。","et":"构词：由 vapeur（蒸汽）加后缀 -oter 形成，类似 siffler → siffloter（轻吹）。同族：vapeur、vapoteuse。","ex":[["Beaucoup de jeunes aiment vapoter.","很多年轻人爱抽电子烟。"],["Il est interdit de vapoter dans le train.","火车上禁止抽电子烟。"],["Elle a arrêté de fumer et elle vapote.","她戒烟了，改抽电子烟。"]],"co":[["une cigarette électronique","电子烟"],["un vapoteur / une vapoteuse","吸电子烟的人 / 电子烟"],["vapoter dans un lieu public","在公共场所抽电子烟"]],"sy":[["fumer","courant","抽普通香烟"],["la vape","familier","电子烟（口语简称）"]],"fq":"中频，近年越来越常见。","me":"vapeur（蒸汽）+ oter：吐出一小口「蒸汽」。","tr":{"zh":"他想戒烟，所以开始抽电子烟。","fr":"Il veut arrêter de fumer, alors il vapote.","alt":"Il veut arrêter la cigarette, donc il s'est mis à vapoter.","note":"arrêter de + 原形 = 戒掉……"}},
 "À gauche/droite/côté de": {"pos":"loc.prép. 介词短语：à gauche de / à droite de / à côté de","s":"在……左边 / 右边 / 旁边。后面接名词：à gauche de la porte。单独使用时是副词：Tournez à gauche（向左转）。","ipa":"[a ɡoʃ də] / [a dʁwat də] / [a ko.te də]","ph":"gauche 读 [ɡoʃ]（au = [o]，ch = [ʃ]）；droite 读 [dʁwat]（oi = [wa]）；côté 读 [ko.te]。","pi":"de + le = du，de + les = des：à côté du parc、à droite des escaliers；de 后面省音：à côté d'un café。","et":"droite 来自拉丁语 directus（直的）。côté 来自拉丁语 costa（肋骨；侧面）。gauche 来源不确定。英语 gauche（笨拙）借自法语。","ex":[["La banque est à côté de la poste.","银行在邮局旁边。"],["Le café est à gauche de la gare.","咖啡馆在火车站左边。"],["Tournez à droite, puis allez tout droit.","向右转，然后一直走。"]],"co":[["à gauche de + 名词","在……的左边"],["à droite de + 名词","在……的右边"],["à côté de + 名词","在……旁边"],["tourner à gauche / à droite","向左 / 向右转"]],"sy":[["près de","courant","靠近，不一定紧挨"],["juste à côté","courant","就在旁边"],["en face de","courant","在对面"]],"fq":"极高频，问路、描述位置时必备。","me":"droite ← directus：右手是「直」(direct) 手；gauche 则是「笨」手。","tr":{"zh":"药店在面包店的右边。","fr":"La pharmacie est à droite de la boulangerie.","alt":"La pharmacie, c'est juste à droite de la boulangerie.","note":"à droite de + 名词；de + la 不缩合。"}},
 "Dans": {"pos":"prép. 介词","s":"在……里（空间）；在……之后（时间）。dans la boîte = 在盒子里；dans cinq minutes = 五分钟后。表示「用多久完成」要用 en：en cinq minutes。","ipa":"[dɑ̃]","ph":"an 读鼻化 [ɑ̃]，s 不发音。整词只有一个音节。","pi":"dans 的 s 不发音；和 dent（牙齿）同音；dans 后面通常要加冠词：dans la rue，dans mon sac。","et":"来自古法语 dens，源自拉丁语 de intus（从里面）。","ex":[["Mes clés sont dans mon sac.","我的钥匙在包里。"],["Il habite dans le centre-ville.","他住在市中心。"],["Je pars dans dix minutes.","我十分钟后出发。"]],"co":[["dans la rue","在街上"],["dans le train / le bus","在火车 / 公交车上"],["dans cinq minutes","五分钟后"],["dans l'eau","在水里"]],"sy":[["en","courant","用于国家、材料、时长：en France"],["à l'intérieur de","courant","在……里面（更强调内部）"],["au sein de","soutenu","在……内部（组织、团体）"]],"fq":"极高频，日常必备。","me":"dans = dent 同音：牙齿在嘴巴「里」。","tr":{"zh":"我的手机在包里。","fr":"Mon téléphone est dans mon sac.","alt":"Mon portable est dans mon sac.","note":"dans + 限定词 + 名词。"}},
 "Derrière": {"pos":"prép. 介词；也可作副词，名词 le derrière（屁股）","s":"在……后面。Le jardin est derrière la maison。单独使用时是副词：Il est resté derrière。名词 le derrière 是「屁股」的委婉说法。","ipa":"[dɛ.ʁjɛʁ]","ph":"de 读 [dɛ]；rrière 读 [ʁjɛʁ]：双 r 只发一个 [ʁ]；结尾 e 不发。","pi":"双 r 写成 rr，但只发一个小舌音；ière 读 [jɛʁ]，不是「爱」；别和 arrière（后部）混淆。","et":"来自晚期拉丁语 deretro（de + retro，向后）。同族：arrière、rétro。","ex":[["Le jardin est derrière la maison.","花园在房子后面。"],["Cache-toi derrière l'arbre.","躲在树后面。"],["Elle marche derrière lui.","她走在他后面。"]],"co":[["derrière la porte","在门后"],["par derrière","从后面"],["laisser derrière soi","抛在身后"],["de derrière","从后面来的"]],"sy":[["à l'arrière de","courant","在……的后部（车、房子）"],["en arrière","courant","向后"],["devant","courant","反义：在……前面"]],"fq":"高频，日常描述位置常用。","me":"de + rrière：背靠背——derrière 与 devant 正好相反。","tr":{"zh":"车库在房子后面。","fr":"Le garage est derrière la maison.","alt":"Le garage, c'est derrière la maison.","note":"derrière + 定冠词 + 名词。"}},
 "Devant": {"pos":"prép. 介词；也可作副词，名词 le devant（前部）","s":"在……前面；当着……的面。Ma voiture est devant la maison。devant tout le monde = 当着大家的面。注意：只指位置，不指时间（时间用 avant）。","ipa":"[də.vɑ̃]","ph":"de 读弱元音 [də]；vant 读 [vɑ̃]，nt 不发；整词两个音节。","pi":"devant 只表示空间位置，时间「之前」要用 avant；devant 的 t 不发音。","et":"由 de + avant 构成（avant 来自拉丁语 abante，「在前」）。","ex":[["Ma voiture est devant la maison.","我的车在房子前面。"],["Il attend devant la porte.","他在门前等。"],["Ne parle pas comme ça devant les enfants.","别在孩子们面前这样说话。"]],"co":[["devant la porte","在门前"],["passer devant","走到前面；超过"],["devant tout le monde","当着大家的面"],["par devant","从前面"]],"sy":[["face à","courant","面对着"],["en face de","courant","在对面"],["derrière","courant","反义：在……后面"]],"fq":"高频，日常描述位置常用。","me":"devant = de + avant：在「前」面。","tr":{"zh":"我在电影院门口等你。","fr":"Je t'attends devant le cinéma.","alt":"Je t'attends à l'entrée du cinéma.","note":"attendre 后直接接人，不加介词。"}},
 "Entre ... et ...": {"pos":"prép. 介词，固定搭配 entre A et B","s":"在……和……之间。用于两者之间的位置、时间、数量：entre Paul et Marie；entre midi et deux；entre dix et douze euros。后面也可接复数名词：entre amis。","ipa":"[ɑ̃tʁ]","ph":"en 读鼻化 [ɑ̃]；tre 读 [tʁ]，结尾 e 不发；整词一个音节。","pi":"要搭配 et，不是 ou 或 à；和动词 entre（entrer 的变位）同音同形；entre 不是「进入」。","et":"来自拉丁语 inter（在……之间），同源英语 inter-（international）。","ex":[["Je suis assis entre Paul et Marie.","我坐在保罗和玛丽之间。"],["On se voit entre midi et deux.","我们午休时见。"],["Ça coûte entre dix et douze euros.","这个要十到十二欧元。"]],"co":[["entre ... et ...","在……和……之间"],["entre nous","只限我们之间"],["entre amis","朋友之间"],["entre midi et deux","午休时间"]],"sy":[["parmi","soutenu","在……之中（三者及以上）"],["au milieu de","courant","在……中间"],["de ... à ...","courant","从……到……"]],"fq":"极高频，日常常用。","me":"entre ← inter：「国际」(international) 就是「国与国之间」。","tr":{"zh":"银行在药店和邮局之间。","fr":"La banque est entre la pharmacie et la poste.","alt":"La banque, c'est entre la pharmacie et la poste.","note":"entre A et B 中，A、B 前各带冠词。"}},
 "Sous": {"pos":"prép. 介词","s":"在……下面（紧贴或被覆盖）；在……影响下。sous la table = 桌子下面；sous la pluie = 在雨中；sous la douche = 在淋浴时。","ipa":"[su]","ph":"ou 读 [u]；s 在结尾不发音。整词只有一个音节。","pi":"sous [su] 和 sur [syʁ] 只差一个元音和 r：ou 与 u 要分清；sous 的 s 不发音。","et":"来自拉丁语 subtus（在下面）。同族：sous-sol（地下室）、sous-titre（字幕）、dessous（下面）。","ex":[["Le chien est sous la chaise.","狗在椅子下面。"],["Il pleut, on marche sous la pluie.","在下雨，我们在雨中走。"],["Elle chante sous la douche.","她在淋浴时唱歌。"]],"co":[["sous la table","在桌子下面"],["sous la pluie","在雨中"],["sous peu","不久之后"],["sous la main","近在手边"]],"sy":[["au-dessous de","courant","在……之下（位置较低）"],["en dessous de","courant","在……下方"],["sur","courant","反义：在……上面"]],"fq":"极高频，日常必备。","me":"sous 读 [su]，下面的「苏」；和 sur 对照记：ou 在下，u 在上。","tr":{"zh":"球在床下面。","fr":"Le ballon est sous le lit.","alt":"Le ballon, il est sous le lit.","note":"sous + 定冠词 + 名词。"}},
 "Sur": {"pos":"prép. 介词","s":"在……上面（接触）；关于；在某个平台上。sur la table = 桌上；un livre sur la France = 一本关于法国的书；sur Internet = 在网上；trois sur cinq = 五分之三。","ipa":"[syʁ]","ph":"u 读 [y]（圆唇的「雨」音）；r 是小舌音 [ʁ]。整词一个音节。","pi":"sur [syʁ] 与 sous [su] 要分清；sur 与 sûr（肯定的）同音，区别只在 û 的符号。","et":"来自拉丁语 super（在……之上），同源英语 super-。同族前缀 sur-：surface、surprise、surpris。","ex":[["Le chat est sur la table.","猫在桌子上。"],["Je cherche un livre sur la France.","我在找一本关于法国的书。"],["Je regarde une vidéo sur Internet.","我在网上看视频。"]],"co":[["sur la table","在桌上"],["sur Internet","在网上"],["sur place","就地；现场"],["sur mesure","量身定做"]],"sy":[["au-dessus de","courant","在……上方（不接触）"],["à propos de","courant","关于"],["sous","courant","反义：在……下面"]],"fq":"极高频，日常必备。","me":"sur ← super：Superman 在你头「上」(sur)。","tr":{"zh":"我的书在桌子上。","fr":"Mon livre est sur la table.","alt":"Mon bouquin est sur la table.","note":"sur 接触，au-dessus de 不接触。"}},
 "Beurk !": {"pos":"interj. 感叹词（拟声）","s":"呕！恶心！表示厌恶，对象可以是食物、气味、画面。也可写成 Berk !。口语中 C'est beurk 也可当形容词说「真恶心」。","ipa":"[bœʁk]","ph":"eu 读 [œ]（在 r 前开口）；r 小舌音；k 要发出来：[bœʁk]。","pi":"eu 在 r 前读 [œ]，不是「乌」；结尾 -k 要读清楚，是个短促的感叹。","et":"拟声词（模仿呕吐声），无确切词源。","ex":[["Beurk ! C'est dégoûtant.","呕！真恶心。"],["Beurk, ça sent mauvais.","呕，味道真难闻。"],["Beurk, il y a un cheveu dans ma soupe !","呕，我的汤里有根头发！"]],"co":[["Beurk, c'est dégoûtant !","呕，真恶心！"],["C'est beurk.","好恶心。"],["Beurk, quelle horreur !","呕，太可怕了！"]],"sy":[["pouah","familier","呸，嫌恶声"],["berk","familier","Beurk 的另一种写法"],["dégoûtant","courant","令人恶心的"]],"fq":"高频口语，孩子和年轻人常用。","me":"beurk 的发音像呕吐的声音。","tr":{"zh":"呕，这汤味道真难闻！","fr":"Beurk, cette soupe sent mauvais !","alt":"Berk, ça sent mauvais, cette soupe !","note":"sentir mauvais = 闻起来难闻。"}},
 "En avoir assez / En avoir marre / Ne plus en pouvoir": {"pos":"loc.v. 动词短语（三种说法同义）：en avoir assez（courant）/ en avoir marre（familier）/ ne plus en pouvoir","s":"受够了；忍无可忍。en 代替「这件事」，后面可加 de + 名词/原形：J'en ai marre de attendre → d'attendre。ne plus en pouvoir 也可指累得不行。","ipa":"[ɑ̃.na.vwaʁ.a.se] / [ɑ̃.na.vwaʁ.maʁ] / [nə ply ɑ̃ pu.vwaʁ]","ph":"en 与 avoir 连读：en‿avoir [ɑ̃.na.vwaʁ]；assez 读 [a.se]；marre 读 [maʁ]。","pi":"en 不能省：J'ai assez 的意思是「我够了（数量足够）」，J'en ai assez 才是「受够了」；marre 的 rr 只发一个 [ʁ]。","et":"assez 来自拉丁语 ad satis（足够）。marre 来源不确定。","ex":[["J'en ai marre ! Je n'en peux plus !","我受够了！我受不了了！"],["J'en ai assez de ce bruit.","我受够了这种噪音。"],["Elle en a marre d'attendre.","她等得受够了。"]],"co":[["en avoir assez de + 名词/原形","受够了……"],["en avoir marre de","烦透了……"],["Je n'en peux plus.","我受不了了。"],["en avoir ras le bol","受够了（更口语）"]],"sy":[["en avoir ras le bol","familier","受够了，很强烈"],["en avoir plein le dos","familier","烦透了"],["ne plus supporter","courant","不能再忍受"]],"fq":"高频口语，表达烦恼时极常用。","me":"en（这件事）+ avoir marre：这件事我「有」一肚子 marre。","tr":{"zh":"我受够了这场雨！","fr":"J'en ai marre de cette pluie !","alt":"J'en ai assez de cette pluie !","note":"en avoir marre de + 名词；de + cette → de cette。"}},
 "Être un ange": {"pos":"loc.v. 动词短语：être un ange，ange 为阳性名词，复数 anges","s":"是个天使；心地善良、乐于助人。感谢别人时常说 Tu es un ange !（你真是太好了！）。une patience d'ange = 天使般的耐心。","ipa":"[ɛtʁ‿œ̃n‿ɑ̃ʒ]","ph":"ange 读 [ɑ̃ʒ]：an 为鼻化 [ɑ̃]，g 在 e 前读 [ʒ]；un 与 ange 连读：un‿ange [œ̃.nɑ̃ʒ]。","pi":"ange 是阳性，即使说女生也用 un ange（Tu es un ange）；an 是鼻音，不要读成「安格」。","et":"来自拉丁语 angelus，源自希腊语 angelos（信使）。同源英语 angel。","ex":[["Merci pour ton aide, tu es un ange !","谢谢你帮忙，你真是天使！"],["Ma voisine est un ange.","我的邻居是个大好人。"],["Il a une patience d'ange.","他有天使般的耐心。"]],"co":[["Tu es un ange !","你真好！"],["une patience d'ange","天使般的耐心"],["une voix d'ange","天使般的嗓音"],["un ange passe","（冷场时）一个天使飞过"]],"sy":[["être adorable","courant","非常可爱、亲切"],["être un amour","familier","真可爱 / 真好"],["être un trésor","courant","是个宝贝"]],"fq":"中高频口语，表达感谢时常用。","me":"ange [ɑ̃ʒ]：英语 angel 的前半部分，天使帮了你。","tr":{"zh":"你帮我拿行李，你真是天使！","fr":"Tu m'aides avec les valises, tu es un ange !","alt":"Tu me portes mes valises ? Tu es un ange !","note":"女生也用 un ange（阳性）。"}},
 "Être/Tomber en panne": {"pos":"loc.v. 动词短语：être en panne（状态）/ tomber en panne（发生故障）；panne 为阴性名词","s":"抛锚；出故障；停机。être en panne 描述「现在坏着」，tomber en panne 描述「刚刚坏了」。可用于车、电梯、电脑，也可说 en panne d'essence（没油了）。","ipa":"[ɛtʁ‿ɑ̃ pan] / [tɔ̃.be ɑ̃ pan]","ph":"en 读 [ɑ̃]；panne 读 [pan]（nn 只发一个 n，结尾 e 不发）。","pi":"panne 不读 [pɑ̃]；panne 的 an 不是鼻化，是 [a] 加 [n]；在 en panne 里 en 与 panne 之间不连读。","et":"panne（故障）来源不确定。词族：dépanner（抢修；临时帮人）、dépanneuse（拖车）。","ex":[["Ma voiture est en panne.","我的车抛锚了。"],["L'ascenseur est tombé en panne.","电梯坏了。"],["Je suis en panne d'idées.","我想不出点子了。"]],"co":[["tomber en panne","出故障"],["une panne de courant","停电"],["une panne d'essence","没油了"],["être en panne d'inspiration","灵感枯竭"]],"sy":[["ne plus marcher","courant","不能用了"],["être hors service","courant","停止服务"],["lâcher","familier","（机器）突然坏了"]],"fq":"高频，交通、设备故障时常用。","me":"panne 像 pan：「砰」的一声，机器停了。","tr":{"zh":"我的电脑坏了。","fr":"Mon ordinateur est en panne.","alt":"Mon ordi ne marche plus.","note":"être en panne = 坏着；tomber en panne = 刚坏。"}},
 "Poser une question": {"pos":"loc.v. 动词短语：poser（第一组规则动词，助动词 avoir）+ une question（阴性名词）","s":"提问；问问题。法语用 poser une question à quelqu'un，不能说 demander une question。礼貌问法：Je peux vous poser une question ?","ipa":"[po.ze yn kɛs.tjɔ̃]","ph":"poser 读 [po.ze]，s 在元音间读 [z]；question 读 [kɛs.tjɔ̃]，qu = [k]，-tion = [tjɔ̃]。","pi":"question 的 -tion 读 [tjɔ̃]，不是 [ʃɔ̃]；s 在 poser 中读 [z]；不要说 faire une question 或 demander une question。","et":"poser 来自晚期拉丁语 pausare（停下，放下），与 ponere（放置）混合；question 来自拉丁语 quaestio（询问）。同源英语 question。","ex":[["Je peux poser une question ?","我可以问个问题吗？"],["Il pose beaucoup de questions.","他问很多问题。"],["Je voudrais vous poser une question.","我想问您一个问题。"]],"co":[["poser une question à quelqu'un","向某人提问"],["répondre à une question","回答问题"],["Avez-vous des questions ?","您有问题吗？"],["une bonne question","一个好问题"]],"sy":[["demander","courant","问；要求（后面接内容，不接「问题」）"],["interroger","soutenu","审问，询问"],["questionner","courant","向某人提问"]],"fq":"极高频，课堂与日常对话必备。","me":"poser + question：把问题「放」到桌面上。","tr":{"zh":"老师，我可以问一个问题吗？","fr":"Madame, je peux vous poser une question ?","alt":"Madame, j'ai une question, s'il vous plaît.","note":"poser une question à + 人。"}},
 "Du citron": {"pos":"n.m. 阳性名词，复数 citrons（du = 部分冠词）","s":"柠檬；柠檬味。du citron 指不可数的「柠檬」，un citron 指一个柠檬。citron vert = 青柠。口语中 un citron 也指「质量差的二手车」。","ipa":"[si.tʁɔ̃]","ph":"c 在 i 前读 [s]；tr 读 [tʁ]；on 读鼻化 [ɔ̃]，n 不单独发音。","pi":"c 读 [s]，不是 [k]；结尾 on 是鼻音 [ɔ̃]，不是「翁」；阳性：le citron。","et":"来自拉丁语 citrus（柑橘类植物），经普罗旺斯语传入。同源英语 citrus。","ex":[["Je bois du jus de citron.","我喝柠檬汁。"],["Tu veux du citron dans ton thé ?","你的茶里要放柠檬吗？"],["Elle presse un citron.","她在挤柠檬。"]],"co":[["du jus de citron","柠檬汁"],["une tranche de citron","一片柠檬"],["un thé au citron","柠檬茶"],["un citron vert","青柠"]],"sy":[["le citron vert","courant","青柠，另一种水果"],["l'orange","courant","橙子，不同水果"],["la lime","courant","较少用的「青柠」别称"]],"fq":"中高频，饮食日常常用。","me":"citron ← citrus：英语 citrus 的亲戚，酸酸的。","tr":{"zh":"我想要一杯加柠檬的水。","fr":"Je voudrais un verre d'eau avec du citron.","alt":"Je prendrais de l'eau avec un peu de citron.","note":"du citron = 一点柠檬（部分冠词）。"}},
 "Du miel": {"pos":"n.m. 阳性名词，不可数，du miel（复数 miels 指不同种类）","s":"蜂蜜。du miel 指不可数的蜂蜜；常见：miel de fleurs（花蜜）、miel de lavande（薰衣草蜜）。lune de miel = 蜜月。","ipa":"[mjɛl]","ph":"ie 读 [jɛ]；l 要发出来。整词只有一个音节。","pi":"miel 不是两个音节「mi-el」，而是 [mjɛl]；l 不能省；和 ciel（天空）的结构相似。","et":"来自拉丁语 mel（蜂蜜）。同族英语 mellifluous（甜美的）。","ex":[["J'aime le miel.","我喜欢蜂蜜。"],["Je mets du miel dans mon thé.","我在茶里放蜂蜜。"],["Ils sont en lune de miel.","他们在度蜜月。"]],"co":[["du miel de fleurs","花蜜"],["une lune de miel","蜜月"],["une tartine au miel","蜂蜜面包片"],["doux comme le miel","甜如蜜"]],"sy":[["la confiture","courant","果酱，不是蜂蜜"],["le sirop","courant","糖浆"],["le sucre","courant","糖"]],"fq":"中频，饮食日常常用。","me":"miel [mjɛl]：像「蜜尔」，蜜蜂酿的甜东西。","tr":{"zh":"我早餐吃面包和蜂蜜。","fr":"Au petit-déjeuner, je mange du pain avec du miel.","alt":"Le matin, je prends du pain et du miel.","note":"manger / prendre du miel：用部分冠词。"}},
 "Du sirop pour la toux/gorge": {"pos":"n.m. 阳性名词 sirop；pour la toux / pour la gorge 为用途补语","s":"止咳糖浆；喉咙糖浆。sirop pour la toux = 止咳糖浆；sirop pour la gorge = 缓解喉咙痛的糖浆。sirop 也指加水喝的果味糖浆：un sirop de menthe。","ipa":"[si.ʁo]","ph":"sirop 读 [si.ʁo]：结尾 p 不发音；toux 读 [tu]，x 不发；gorge 读 [ɡɔʁʒ]。","pi":"sirop 的 p 不发，toux 的 x 不发；toux 与 tout、tous 同音 [tu]，别混淆。","et":"经中世纪拉丁语 sirupus，来自阿拉伯语 sharab（饮料）。同源英语 syrup、sherbet。","ex":[["Prends du sirop.","喝点糖浆。"],["Le médecin m'a donné un sirop pour la toux.","医生给我开了止咳糖浆。"],["Je bois un sirop de menthe.","我喝一杯薄荷糖浆水。"]],"co":[["un sirop pour la toux","止咳糖浆"],["un sirop de menthe","薄荷糖浆水"],["avoir mal à la gorge","喉咙痛"],["un sirop contre la toux","止咳糖浆"]],"sy":[["le médicament","courant","药，更宽泛"],["la pastille","courant","润喉糖"],["la tisane","courant","草本茶"]],"fq":"中频，生病看药时常用。","me":"sirop：和英语 syrup 同源，结尾 p 不发。","tr":{"zh":"我咳嗽，需要止咳糖浆。","fr":"Je tousse, j'ai besoin de sirop pour la toux.","alt":"Je tousse beaucoup, il me faut du sirop.","note":"avoir besoin de + 名词；il me faut 更口语。"}},
 "Le \"football américain\"": {"pos":"n.m. 阳性名词，复数 footballs américains；le football 单用时指足球","s":"美式橄榄球。法语 le football（常说 le foot）单用指足球；美式橄榄球必须加 américain。引号表示这是借用的概念。橄榄球是 le rugby。","ipa":"[fut.bol a.me.ʁi.kɛ̃]","ph":"football 读 [fut.bol]；oo 不读长音；américain 读 [a.me.ʁi.kɛ̃]，ain 读 [ɛ̃]。","pi":"le football = 足球，不是美式橄榄球；ball 读 [bol]；américain 的 ain 是鼻化 [ɛ̃]。","et":"借自英语 football，由 foot + ball 构成。法语口语简称 le foot。","ex":[["Je regarde le football américain.","我看美式橄榄球。"],["Le football américain est peu connu en France.","美式橄榄球在法国不太有名。"],["En France, le foot, c'est le sport numéro un.","在法国，足球是头号运动。"]],"co":[["regarder le football américain","看美式橄榄球"],["un match de football américain","一场美式橄榄球赛"],["jouer au football","踢足球"],["le Super Bowl","超级碗"]],"sy":[["le foot","familier","足球的口语简称，不是美式橄榄球"],["le rugby","courant","橄榄球（英式 / 法国常见）"]],"fq":"中低频，谈论运动时用。","me":"football 单用 = 足球；要美式橄榄球必须加 américain。","tr":{"zh":"我周末看美式橄榄球比赛。","fr":"Le week-end, je regarde des matchs de football américain.","alt":"Le week-end, je regarde du football américain à la télé.","note":"regarder du football：运动前用 du。"}},
 "Le corps": {"pos":"n.m. 阳性名词，单复数同形：le corps / les corps","s":"身体；躯体；尸体。le corps humain = 人体。也可指「团体」：le corps enseignant = 教师队伍。corps et âme = 全身心。","ipa":"[kɔʁ]","ph":"ps 都不发音；整词读 [kɔʁ]，r 要发小舌音。一个音节。","pi":"corps 的 p、s 都不发音，读 [kɔʁ]；与 cor（鸡眼）、cors 同音；英语 corps 读音也是类似的。","et":"来自拉丁语 corpus（身体）。同族英语 corpse、corporal、corporation；p 是拉丁语遗留的字母。","ex":[["Le corps humain est complexe.","人体很复杂。"],["Elle a mal partout dans le corps.","她浑身疼。"],["Le sport est bon pour le corps.","运动对身体好。"]],"co":[["le corps humain","人体"],["avoir mal partout","浑身疼"],["le corps enseignant","教师群体"],["corps et âme","全身心地"]],"sy":[["l'organisme","courant","身体（作为生物机体）"],["le physique","courant","体质；外貌"],["le cadavre","courant","尸体"]],"fq":"高频，谈健康和身体时常用。","me":"corps：和英语 corpse（尸体）、corporal（身体的）同源；p 和 s 都不读。","tr":{"zh":"运动对身体有好处。","fr":"Le sport est bon pour le corps.","alt":"Faire du sport, c'est bon pour la santé.","note":"être bon pour + 名词。"}},
 "Le cyclisme": {"pos":"n.m. 阳性名词，复数 cyclismes（几乎不用复数）","s":"自行车运动；公路自行车赛。faire du cyclisme = 骑行运动。le Tour de France 是最有名的 cyclisme 赛事。自行车本身叫 le vélo。","ipa":"[si.klism]","ph":"cy 读 [si]；-clisme 读 [klism]：s 要发 [s]，结尾 e 不发。两个音节。","pi":"cy 读 [si]；cyclisme 的 s 要发音，不要读成「cy-cli-me」；日常骑车说 faire du vélo。","et":"cycle（来自希腊语 kyklos，圆圈）+ 后缀 -isme，表示运动、实践。同族：cycliste、bicyclette、cyclone。","ex":[["J'aime le cyclisme.","我喜欢自行车运动。"],["Le cyclisme est très populaire en France.","自行车运动在法国很受欢迎。"],["Elle fait du cyclisme tous les week-ends.","她每个周末都骑车锻炼。"]],"co":[["faire du cyclisme","骑自行车运动"],["le cyclisme sur route","公路自行车赛"],["une course cycliste","自行车赛"],["le Tour de France","环法自行车赛"]],"sy":[["le vélo","courant","自行车；骑车也叫 faire du vélo"],["le cyclotourisme","soutenu","骑行旅游"]],"fq":"中频，谈运动与体育赛事时用。","me":"cycl- = 圆圈：轮子转圈 = cyclisme。","tr":{"zh":"我爸爸很喜欢自行车运动。","fr":"Mon père adore le cyclisme.","alt":"Mon père est un fan de cyclisme.","note":"aimer / adorer + le + 运动名词。"}},
 "Le dos": {"pos":"n.m. 阳性名词，单复数同形：le dos / les dos","s":"背；背部。J'ai mal au dos = 我背疼。dos 还可指物体的背面：le dos de la main（手背）。下背部（腰）多说 les reins。","ipa":"[do]","ph":"o 读 [o]；s 结尾不发音。整词只有一个音节。","pi":"dos 的 s 不发音，读 [do]；mal au dos 里用 au（à + le），不是 à le；背和腰要分开：dos / reins。","et":"来自拉丁语 dossum（dorsum 的变体，「背」）。同族英语 dorsal、endorse。","ex":[["J'ai mal au dos.","我背疼。"],["Il dort sur le dos.","他仰着睡。"],["Elle porte un sac à dos.","她背着一个背包。"]],"co":[["avoir mal au dos","背疼"],["un sac à dos","背包"],["tourner le dos à","背对着；不理睬"],["en avoir plein le dos","烦透了"]],"sy":[["les reins","courant","腰；下背部"],["l'arrière","courant","后部"],["l'épaule","courant","肩膀"]],"fq":"高频，谈健康和身体时常用。","me":"dos = 英语 dorsal（背部的）：背部的 d 开头。","tr":{"zh":"我今天背很疼。","fr":"J'ai très mal au dos aujourd'hui.","alt":"Mon dos me fait très mal aujourd'hui.","note":"avoir mal à + 身体部位：au dos。"}},
 "Le front": {"pos":"n.m. 阳性名词，复数 fronts","s":"额头；前线；锋面。avoir le front plissé = 皱着眉；front de mer = 海滨大道；le front populaire = 人民阵线。de front = 迎面；并排。","ipa":"[fʁɔ̃]","ph":"fr 读 [fʁ]；on 读鼻化 [ɔ̃]；结尾 t 不发音。整词一个音节。","pi":"front 的 t 不发音，读 [fʁɔ̃]；别和 fond（底部，[fɔ̃]）混淆，front 多了一个 [ʁ]。","et":"来自拉丁语 frons, frontis（额头）。同族英语 front、frontal、confront、affront。","ex":[["Il a un grand front.","他额头很宽。"],["Elle pose sa main sur mon front.","她把手放在我的额头上。"],["Nous marchons sur le front de mer.","我们在海滨大道上散步。"]],"co":[["avoir le front plissé","皱着额头"],["le front de mer","海滨大道"],["de front","迎面；并排"],["faire front","正面应对"]],"sy":[["la tempe","courant","太阳穴"],["le visage","courant","脸"],["la façade","courant","（建筑）正面"]],"fq":"中频，谈身体时常用。","me":"front ← frons：和英语 front（前面）同源：额头长在脸的最「前」面。","tr":{"zh":"他的额头上有一道疤。","fr":"Il a une cicatrice sur le front.","alt":"Il a une marque sur le front.","note":"sur le front：在额头上用 sur。"}},
 "Le judo": {"pos":"n.m. 阳性名词，不可数","s":"柔道。faire du judo = 练柔道。练柔道的人叫 un judoka。ceinture noire = 黑带。日语 jūdō，意思是「柔」之「道」。","ipa":"[ʒy.do]","ph":"j 读 [ʒ]；u 读 [y]（圆唇的「雨」音）；o 读 [o]。重音在最后一个音节。","pi":"j 是 [ʒ]，不是 [dʒ]；u 是 [y]，不是 [u]，英语读 /dʒuːdoʊ/，法语完全不同；末尾 o 要发 [o]。","et":"借自日语 jūdō（柔道），「柔」+「道」。","ex":[["Il fait du judo.","他练柔道。"],["Mon fils fait du judo le mercredi.","我儿子每周三练柔道。"],["Elle a une ceinture noire de judo.","她有柔道黑带。"]],"co":[["faire du judo","练柔道"],["un cours de judo","柔道课"],["une ceinture noire","黑带"],["un judoka","柔道运动员"]],"sy":[["le karaté","courant","空手道，另一种武术"],["l'aïkido","courant","合气道"],["les arts martiaux","courant","武术的统称"]],"fq":"中频，法国学生常学的运动。","me":"judo [ʒy.do]：j 像「zhi」，u 圆唇，o 在最后。","tr":{"zh":"我儿子每周练两次柔道。","fr":"Mon fils fait du judo deux fois par semaine.","alt":"Mon fils pratique le judo deux fois par semaine.","note":"faire du + 运动；deux fois par semaine = 每周两次。"}},
 "Le nez": {"pos":"n.m. 阳性名词，单复数同形：le nez / les nez","s":"鼻子。J'ai le nez bouché = 我鼻塞；J'ai le nez qui coule = 我流鼻涕。mettre son nez dans = 多管闲事。","ipa":"[ne]","ph":"n 读 [n]；e 读 [e]；结尾 z 不发音。整词只有一个音节。","pi":"nez 的 z 不发音，读 [ne]，和 né（出生）同音；复数 nez 不加 s。","et":"来自拉丁语 nasus（鼻子）。同族英语 nasal，法语 narine（鼻孔）。","ex":[["Mon nez coule.","我流鼻涕。"],["J'ai le nez bouché.","我鼻子堵住了。"],["Il a un petit nez.","他的鼻子小小的。"]],"co":[["avoir le nez qui coule","流鼻涕"],["avoir le nez bouché","鼻塞"],["se moucher le nez","擤鼻涕"],["mettre son nez partout","到处插手"]],"sy":[["le pif","familier","鼻子，口语"],["le tarin","argot","鼻子，俚语"],["le museau","courant","（动物的）口鼻部"]],"fq":"高频，谈身体和健康时常用。","me":"nez 和 né（出生）同音：出生时有个小鼻子。","tr":{"zh":"我感冒了，鼻子不通气。","fr":"Je suis enrhumé, j'ai le nez bouché.","alt":"Je suis malade, mon nez est bouché.","note":"avoir le nez bouché：鼻塞。"}},
 "Le poids": {"pos":"n.m. 阳性名词，复数 poids（单复数同形）","s":"体重；重量；负担。Vous faites quel poids ? = 您多重？prendre du poids = 增重；perdre du poids = 减重。poids lourd = 重型卡车。","ipa":"[pwa]","ph":"oi 读 [wa]；d、s 结尾都不发音。整词一个音节。","pi":"poids 的 d 和 s 都不发音，读 [pwa]；与 pois（豌豆）、poix（沥青）同音；d 是后加的假词源字母。","et":"来自拉丁语 pensum（称出的东西）；写成 poids 时，d 是受拉丁语 pondus 影响而加的。","ex":[["Vous faites quel poids ?","您多重？"],["Il a pris du poids cet hiver.","他今年冬天长胖了。"],["Elle veut perdre du poids.","她想减肥。"]],"co":[["prendre du poids","增重"],["perdre du poids","减重"],["un poids lourd","重型卡车"],["le poids d'un colis","包裹的重量"]],"sy":[["la masse","soutenu","质量（物理、科学用语）"],["les kilos","familier","公斤，口语常说「胖了几公斤」"],["la charge","courant","负载，重担"]],"fq":"中高频，谈健康和身材时常用。","me":"poids：d 和 s 都不读，三个字母只出一个音。","tr":{"zh":"我最近长胖了。","fr":"J'ai pris du poids récemment.","alt":"J'ai pris quelques kilos ces derniers temps.","note":"prendre du poids = 增重（部分冠词）。"}},
 "Le rugby": {"pos":"n.m. 阳性名词，不可数","s":"橄榄球。jouer au rugby = 打橄榄球。法国西南部很盛行。英式橄榄球和美式橄榄球不同：美式叫 le football américain。","ipa":"[ʁyɡ.bi]","ph":"ru 读 [ʁy]（u 圆唇）；g 读 [ɡ]；by 读 [bi]。两个音节，重音在最后。","pi":"u 读 [y]，不是 [u]；-by 的 y 读 [i]；英语读 /ˈrʌɡbi/，法语 ru 读圆唇音。","et":"来自英国 Rugby 镇的 Rugby School，这项运动在那里诞生。","ex":[["Il joue au rugby.","他打橄榄球。"],["Le rugby est très populaire dans le sud-ouest.","橄榄球在西南部很受欢迎。"],["On regarde le match de rugby ce soir.","我们今晚看橄榄球比赛。"]],"co":[["jouer au rugby","打橄榄球"],["un match de rugby","一场橄榄球赛"],["une équipe de rugby","橄榄球队"],["le rugby à XV","十五人制橄榄球"]],"sy":[["le ballon ovale","courant","「椭圆球」，新闻里指橄榄球"],["le football américain","courant","美式橄榄球"]],"fq":"中频，法国体育话题常见。","me":"rugby：来自 Rugby 这个地名，椭圆形的球。","tr":{"zh":"我哥哥打橄榄球。","fr":"Mon frère joue au rugby.","alt":"Mon frère fait du rugby.","note":"jouer à + 球类；jouer au = à + le。"}},
 "Le tennis": {"pos":"n.m. 阳性名词，单复数同形；des tennis 另指运动鞋（口语）","s":"网球。jouer au tennis = 打网球。le tennis de table = 乒乓球。des tennis（复数）在口语里也指「运动鞋」。","ipa":"[te.nis]","ph":"te 读 [te]；nis 读 [nis]：结尾 s 要发 [s]。重音在最后一个音节。","pi":"结尾 s 要发音，读 [te.nis]，重音在最后一个音节；英语 tennis 重音在前，法语不同。","et":"借自英语 tennis，英语可能来自古法语 tenez（「接着！」，发球时喊的话）。","ex":[["Je joue au tennis.","我打网球。"],["Il y a un court de tennis près de chez moi.","我家附近有一个网球场。"],["Elle porte des tennis blancs.","她穿着白色的运动鞋。"]],"co":[["jouer au tennis","打网球"],["un court de tennis","网球场"],["une raquette de tennis","网球拍"],["le tennis de table","乒乓球"]],"sy":[["le ping-pong","familier","乒乓球，口语"],["le badminton","courant","羽毛球，另一种运动"],["les baskets","courant","运动鞋，常用说法"]],"fq":"高频，谈运动时常用。","me":"tennis 的 s 要读：[te.nis]，最后一个音重读。","tr":{"zh":"我们周六一起打网球吧。","fr":"On joue au tennis ensemble samedi ?","alt":"Ça te dit de jouer au tennis samedi ?","note":"Ça te dit de + 原形 = 你想不想……"}},
 "Le ventre": {"pos":"n.m. 阳性名词，复数 ventres","s":"肚子；腹部。J'ai mal au ventre = 我肚子疼。ventre 指肚子这一块；胃这个器官叫 l'estomac。à plat ventre = 趴着。","ipa":"[vɑ̃tʁ]","ph":"ven 读鼻化 [vɑ̃]；tre 读 [tʁ]，结尾 e 不发。整词一个音节。","pi":"ventre 读 [vɑ̃tʁ]，不是「ven-tre」两个音节；与 vent（风）开头同音 [vɑ̃]；肚子疼多说 mal au ventre，胃疼说 mal à l'estomac。","et":"来自拉丁语 venter（肚子）。同族英语 ventral、ventricle、ventriloquist。","ex":[["J'ai mal au ventre.","我肚子疼。"],["Il dort sur le ventre.","他趴着睡。"],["Elle a le ventre plat.","她小腹平坦。"]],"co":[["avoir mal au ventre","肚子疼"],["à plat ventre","趴着"],["avoir le ventre plat","小腹平坦"],["avoir les yeux plus gros que le ventre","眼大肚子小"]],"sy":[["l'estomac","courant","胃（器官）"],["l'abdomen","soutenu","腹部（医学用语）"],["le bide","familier","肚子，口语"]],"fq":"高频，谈身体和健康时常用。","me":"ventre 和 vent（风）开头相同：肚子里「风」一样鼓鼓的。","tr":{"zh":"我吃得太多，肚子疼。","fr":"J'ai trop mangé, j'ai mal au ventre.","alt":"J'ai trop mangé, mon ventre me fait mal.","note":"avoir mal à + 部位：au ventre。"}},
 "Le volley(ball)": {"pos":"n.m. 阳性名词，不可数；le volley 为简称，le volley-ball 为全称","s":"排球。jouer au volley = 打排球。beach-volley = 沙滩排球。简称 le volley 在口语中最常用。","ipa":"[vɔ.lɛ] / [vɔ.lɛ.bol]","ph":"volley：o 读 [ɔ]，l 读 [l]，ey 读 [ɛ]，y 不读 [i]；ball 读 [bol]。","pi":"volley 结尾读 [lɛ]，不是英语 /ˈvɒli/；ball 读 [bol]，不是 [bɔl]；常见拼写 volley-ball 有连字符。","et":"借自英语 volleyball（volley「空中截击」+ ball）。","ex":[["Je joue au volley.","我打排球。"],["On fait un match de volley à la plage.","我们在海滩打一场排球。"],["Elle joue au volley-ball dans une équipe.","她在一支队伍里打排球。"]],"co":[["jouer au volley","打排球"],["un ballon de volley","排球"],["un match de volley-ball","一场排球赛"],["le beach-volley","沙滩排球"]],"sy":[["le volley-ball","courant","全称"],["le beach-volley","courant","沙滩排球"],["le basket","courant","篮球，另一种球类"]],"fq":"中频，谈运动时用。","me":"volley：在空中「飞」(vol) 的球。","tr":{"zh":"我们下午去海边打排球吧。","fr":"On va jouer au volley à la plage cet après-midi ?","alt":"Si on faisait un volley à la plage cet après-midi ?","note":"à la plage：在海滩。"}},
 "Le yoga": {"pos":"n.m. 阳性名词，不可数","s":"瑜伽。faire du yoga = 练瑜伽。练瑜伽的人叫 un yogi / une yogi 或 un pratiquant de yoga。常和 la méditation 一起说。","ipa":"[jo.ɡa]","ph":"y 在词首读 [j]；o 读 [o]；g 在 a 前读硬音 [ɡ]；a 读 [a]。两个音节，重音在最后。","pi":"y 读 [j]，像 yes 的 y；g 读硬音 [ɡ]，不是 [ʒ]；两个元音 o、a 都要读清楚，重音在最后。","et":"借自梵语 yoga（结合；轭）。同源英语 yoke。","ex":[["Je fais du yoga.","我练瑜伽。"],["Elle va à un cours de yoga le lundi.","她每周一去上瑜伽课。"],["Le yoga m'aide à me détendre.","瑜伽帮我放松。"]],"co":[["faire du yoga","练瑜伽"],["un cours de yoga","瑜伽课"],["un tapis de yoga","瑜伽垫"],["une séance de yoga","一次瑜伽练习"]],"sy":[["la méditation","courant","冥想，常和瑜伽相关"],["le pilates","courant","普拉提"],["la gym","familier","体操，健身"]],"fq":"中频，谈健康与放松时常用。","me":"yoga [jo.ɡa]：y 像「耶」，一个放松的单词。","tr":{"zh":"我每天早上练十分钟瑜伽。","fr":"Chaque matin, je fais dix minutes de yoga.","alt":"Tous les matins, je fais un peu de yoga.","note":"faire du yoga；dix minutes de yoga：时长 + de。"}},
 "Un complément (alimentaire)": {"pos":"n.m. 阳性名词，复数 compléments（alimentaires）","s":"营养补充剂；补充。un complément alimentaire 是维生素、矿物质等补充品。complément 单独还可指「补充物」：un complément d'information = 补充信息。","ipa":"[kɔ̃.ple.mɑ̃]","ph":"com 读鼻化 [kɔ̃]；plé 读 [ple]；ment 读 [mɑ̃]，nt 不发。三个音节。","pi":"complément（补充）与 compliment（赞美）只差一个字母：complément [kɔ̃.ple.mɑ̃]，compliment [kɔ̃.pli.mɑ̃]；ment 是 [mɑ̃]，不是「门特」。","et":"来自拉丁语 complementum，源自 complere（填满）。同族：compléter（补全）、complet（完整的）。","ex":[["La vitamine D est un complément alimentaire.","维生素 D 是一种补充剂。"],["Je prends un complément alimentaire en hiver.","冬天我吃营养补充剂。"],["Je voudrais un complément d'information.","我想要一点补充信息。"]],"co":[["un complément alimentaire","营养补充剂"],["un complément d'information","补充信息"],["en complément de","作为……的补充"],["un complément de salaire","额外收入"]],"sy":[["le supplément","courant","额外增加的（费用或物品）"],["la vitamine","courant","维生素"],["l'additif","courant","添加剂"]],"fq":"中频，健康与饮食话题常见。","me":"complément：complet（完整）+ ment：补齐缺的那一部分。","tr":{"zh":"医生建议我吃维生素补充剂。","fr":"Le médecin me conseille de prendre un complément alimentaire à base de vitamines.","alt":"Mon médecin me dit de prendre des vitamines en complément.","note":"conseiller à qqn de + 原形。"}},
 "Un hôpital": {"pos":"n.m. 阳性名词，复数 hôpitaux","s":"医院。去医院用 aller à l'hôpital；在医院里 à l'hôpital。小诊所叫 une clinique（多为私立）或 un cabinet（医生的诊室）。","ipa":"[o.pi.tal]","ph":"h 不发音；ô 读 [o]；结尾 l 要发。","pi":"h 是哑音，不能发 [h]；复数是 hôpitaux，不是 hôpitals。","et":"来自拉丁语 hospitale（招待客人的地方），同源：hôtel, hospitalité。","ex":[["Je vais à l'hôpital.","我去医院。"],["Il est à l'hôpital depuis lundi.","他从周一起就住院了。"]],"co":[["aller à l'hôpital","去医院"],["être à l'hôpital","住院"],["un hôpital public","公立医院"]],"sy":[["clinique","courant","诊所、私立医院"],["CHU","courant","大学附属医院"]],"fq":"高频，日常常用。","me":"hôpital 与 hôtel 同源：都是「接待人的地方」。","tr":{"zh":"我的朋友在医院。","fr":"Mon ami est à l'hôpital.","alt":"Mon copain est à l'hôpital.","note":"地点用 à l'hôpital，l' 是 le 的省音。"}},
 "Un litre": {"pos":"n.m. 阳性名词，复数 litres","s":"升（容量单位）。常用 un litre de + 名词，如 un litre de lait。也可简写 L。","ipa":"[litʁ]","ph":"l-i-t-r-e：结尾 -tre 读 [tʁ]，e 不发音。","pi":"结尾 e 不发音，只读 [litʁ]；法语的 r 在喉咙后部。","et":"来自希腊语 litra（重量单位），经拉丁语传入，18 世纪末公制采用。","ex":[["Je bois un litre d'eau.","我喝一升水。"],["Il faut un litre de lait pour la recette.","这个食谱需要一升牛奶。"]],"co":[["un litre de lait","一升牛奶"],["un demi-litre","半升"],["un litre d'essence","一升汽油"]],"sy":[["litron","familier","（口语）一升酒"]],"fq":"高频，购物、做菜常用。","me":"litre 像英语 liter，只是结尾 -re 读 [tʁ]。","tr":{"zh":"我每天喝一升水。","fr":"Je bois un litre d'eau par jour.","alt":"Je bois un litre d'eau chaque jour.","note":"un litre de + 名词，de 后不加冠词。"}},
 "Un match": {"pos":"n.m. 阳性名词，复数 matchs 或 matches","s":"比赛（足球、网球等球类比赛）。借自英语。看比赛用 regarder un match，踢一场比赛用 jouer un match。","ipa":"[matʃ]","ph":"tch 读 [tʃ]，像「吃」；a 读 [a]。","pi":"不要读成 [mætʃ]；结尾是 [tʃ]。球类比赛用 match，大型综合赛事用 compétition。","et":"借自英语 match，18–19 世纪进入法语。","ex":[["Je regarde le match.","我看比赛。"],["Le match commence à vingt heures.","比赛晚上八点开始。"]],"co":[["regarder un match","看比赛"],["un match de foot","足球赛"],["un match nul","平局"],["gagner / perdre un match","赢 / 输一场比赛"]],"sy":[["rencontre","soutenu","比赛（较正式）"],["partie","courant","一局、一盘"]],"fq":"高频，日常常用。","me":"英语 match 直接搬来，读成 [matʃ]。","tr":{"zh":"你想看今晚的比赛吗？","fr":"Tu veux regarder le match ce soir ?","alt":"Tu veux voir le match ce soir ?","note":"regarder 后直接接名词，不加介词。"}},
 "Un médicament": {"pos":"n.m. 阳性名词，复数 médicaments","s":"药（药片、药水等）。吃药用 prendre un médicament。口语也常说 des médocs（familier）。","ipa":"[me.di.ka.mɑ̃]","ph":"é [e]；c 在 a 前读 [k]；-ent 读鼻化元音 [ɑ̃]，t 不发音。","pi":"结尾 -ment 读 [mɑ̃]，不发 t；重音在最后一个音节。","et":"来自拉丁语 medicamentum（药物），由 medicare（治疗）加后缀 -ment 构成。","ex":[["Je prends un médicament.","我吃一种药。"],["Ce médicament est sur ordonnance.","这种药需要处方。"]],"co":[["prendre un médicament","吃药"],["un médicament contre la toux","止咳药"],["sur ordonnance","凭处方"]],"sy":[["médoc","familier","药（口语简称）"],["remède","courant","疗法、药方"]],"fq":"高频，看病、药店常用。","me":"médic- = 医，-ament = 东西：「医用的东西」。","tr":{"zh":"这个药你每天吃两次。","fr":"Tu prends ce médicament deux fois par jour.","alt":"Ce médicament, tu le prends deux fois par jour.","note":"deux fois par jour = 每天两次。"}},
 "Un mètre": {"pos":"n.m. 阳性名词，复数 mètres","s":"米（长度单位）；也指卷尺（mètre ruban）。身高常说 Je mesure 1 m 70（un mètre soixante-dix）。","ipa":"[mɛtʁ]","ph":"è [ɛ]；结尾 -tre 读 [tʁ]，e 不发音。","pi":"mètre 有重音符号 è；注意与 maître（老师）读音相近但拼写不同。","et":"来自希腊语 metron（尺度），1790 年代公制命名。同源：thermomètre, kilomètre。","ex":[["Il mesure un mètre.","他身高一米。"],["La maison est à cent mètres.","房子在一百米外。"]],"co":[["un mètre carré (m²)","平方米"],["à dix mètres","在十米远处"],["le cent mètres","一百米跑"]],"sy":[["centimètre","courant","厘米（更小的单位）"]],"fq":"高频，日常常用。","me":"-mètre 是「量」：thermo-mètre 量温度，mètre 量长度。","tr":{"zh":"超市离这里两百米。","fr":"Le supermarché est à deux cents mètres d'ici.","alt":"Le supermarché est à 200 mètres d'ici.","note":"à + 距离 + de + 地点。"}},
 "Un rendez-vous": {"pos":"n.m. 阳性名词，单复数同形 rendez-vous","s":"约会；预约；约定的见面。看医生、见朋友、谈事情都可用。avoir rendez-vous 表示「有约」。","ipa":"[ʁɑ̃.de.vu]","ph":"r 在喉咙；en 读 [ɑ̃]；z 不发音；ous 读 [u]。","pi":"复数不变：des rendez-vous；两个词之间要有连字符。","et":"来自动词命令式 rendez-vous!（请到某地）：rendre + vous，字面是「请你们到场」。","ex":[["J'ai un rendez-vous.","我有个预约。"],["J'ai rendez-vous chez le dentiste à trois heures.","我三点约了牙医。"],["On se donne rendez-vous devant le cinéma.","我们约在电影院门口见。"]],"co":[["prendre rendez-vous","预约"],["avoir rendez-vous avec","和……有约"],["un rendez-vous chez le médecin","看医生的预约"],["donner rendez-vous à quelqu'un","约某人见面"]],"sy":[["réunion","courant","会议，不是个人约会"],["date","familier","（口语）约会"]],"fq":"极高频，日常常用。","me":"rendez-vous：「请你们（vous）到场」，约定的见面。","tr":{"zh":"我想预约明天的门诊。","fr":"Je voudrais prendre rendez-vous pour demain.","alt":"Je voudrais un rendez-vous pour demain.","note":"「预约」固定说 prendre rendez-vous，rendez-vous 前不加冠词。"}},
 "Un rhume": {"pos":"n.m. 阳性名词，复数 rhumes","s":"感冒（鼻塞、流鼻涕的轻微感冒）。比 la grippe（流感）轻。attraper un rhume = 感冒；être enrhumé = 感冒了。","ipa":"[ʁym]","ph":"rh 读 [ʁ]，h 不发音；u 读 [y]（嘟嘴发「衣」）；结尾 me 的 e 不读。","pi":"u 是 [y]，不是「乌」；rh 开头的 h 不发音。","et":"来自拉丁语和希腊语 rheuma（流动），指分泌物「流出」。同源英语 rheum。","ex":[["J'ai attrapé un rhume.","我感冒了。"],["Elle a un gros rhume.","她重感冒了。"]],"co":[["attraper un rhume","感冒"],["avoir un rhume","有感冒"],["un rhume des foins","花粉症"]],"sy":[["grippe","courant","流感，比 rhume 重"],["refroidissement","soutenu","着凉"]],"fq":"高频，冬天日常常用。","me":"rhume ← 「流」：流鼻涕的病。","tr":{"zh":"我鼻子堵了，我感冒了。","fr":"J'ai le nez bouché, j'ai un rhume.","alt":"J'ai le nez bouché, je suis enrhumé.","note":"注意：un rhume 是感冒，la grippe 是流感。"}},
 "Un sauna": {"pos":"n.m. 阳性名词，复数 saunas","s":"桑拿；桑拿房。在健身房或温泉常见。去桑拿用 aller au sauna。","ipa":"[so.na]","ph":"au 读 [o]；结尾 a 读 [a]。","pi":"au 读 [o]，不是「奥」；不是 [sau.na]。","et":"借自芬兰语 sauna，20 世纪进入法语。","ex":[["J'aime le sauna.","我喜欢桑拿。"],["Il y a un sauna à la salle de sport.","健身房里有桑拿房。"]],"co":[["aller au sauna","去桑拿"],["faire un sauna","蒸桑拿"],["un sauna finlandais","芬兰桑拿"]],"sy":[["hammam","courant","土耳其浴（湿热蒸汽，不同于干热的 sauna）"]],"fq":"中频。","me":"芬兰来的词，sau-na 两个音节，au 像「哦」。","tr":{"zh":"运动以后我去桑拿。","fr":"Après le sport, je vais au sauna.","alt":"Après l'entraînement, je vais au sauna.","note":"aller à + le sauna → au sauna。"}},
 "Un symptôme": {"pos":"n.m. 阳性名词，复数 symptômes","s":"症状（病的迹象）。医生会问 Quels sont vos symptômes ?。常见症状：la toux（咳嗽）、la fièvre（发烧）。","ipa":"[sɛ̃p.tom]","ph":"sym 读 [sɛ̃p]（y 与 m 组成鼻音）；ô 读 [o]；结尾 me 的 e 不读。","pi":"拼写难：sy-m-p-t-ô-m-e，有 p 和 ô；m 在 p 前使 y 变鼻音。","et":"来自希腊语 sumptôma（偶发的事件），同源英语 symptom。","ex":[["C'est un symptôme de la grippe.","这是流感的症状。"],["Quels sont vos symptômes ?","您有什么症状？"]],"co":[["un symptôme de + 病","某病的症状"],["avoir des symptômes","有症状"],["les premiers symptômes","最初的症状"]],"sy":[["signe","courant","迹象、征兆"]],"fq":"中频，看病时常用。","me":"和英语 symptom 几乎一样，注意 ô。","tr":{"zh":"发烧是流感的一个症状。","fr":"La fièvre est un symptôme de la grippe.","alt":"La fièvre, c'est un symptôme de la grippe.","note":"un symptôme de + 疾病。"}},
 "Un thermomètre": {"pos":"n.m. 阳性名词，复数 thermomètres","s":"体温计；温度计。量体温说 prendre sa température；用体温计量。室外温度计也叫 un thermomètre。","ipa":"[tɛʁ.mɔ.mɛtʁ]","ph":"th 读 [t]，h 不发音；er 读 [ɛʁ]；o 读 [ɔ]；è 读 [ɛ]；结尾 e 不读。","pi":"th 是 [t]，不是 [s] 或 [θ]；注意词中有 mo 与 mè 两个 m。","et":"来自希腊语 thermos（热）+ metron（量），同源英语 thermometer。","ex":[["Où est le thermomètre ?","体温计在哪？"],["Je prends ma température avec le thermomètre.","我用体温计量体温。"]],"co":[["un thermomètre médical","医用体温计"],["prendre sa température","量体温"],["le thermomètre indique 38°","温度计显示 38 度"]],"sy":[["thermomètre frontal","courant","额温枪"]],"fq":"中频。","me":"thermo（热）+ mètre（量）：量热的工具。","tr":{"zh":"把体温计给我，我想量体温。","fr":"Donne-moi le thermomètre, je veux prendre ma température.","alt":"Passe-moi le thermomètre, je veux prendre ma température.","note":"prendre sa température = 量体温。"}},
 "De la fièvre": {"pos":"n.f. 阴性名词，复数 fièvres（常用单数，前加 de la）","s":"发烧；发热。表示「发烧」时用部分冠词：avoir de la fièvre。avoir 38 de fièvre = 烧到 38 度。","ipa":"[fjɛvʁ]","ph":"fi 读 [fj]；è 读 [ɛ]；v 读 [v]；结尾 -vre 读 [vʁ]，e 不读。","pi":"只有一个音节：[fjɛvʁ]，不要读成 fi-è-vre 三个音节；è 不要漏重音。","et":"来自拉丁语 febris（发烧），同源英语 fever, febrile。","ex":[["J'ai de la fièvre.","我发烧了。"],["Il a 39 de fièvre.","他烧到 39 度。"],["Elle a de la fièvre depuis hier.","她从昨天起一直发烧。"]],"co":[["avoir de la fièvre","发烧"],["avoir 38 de fièvre","烧到 38 度"],["faire de la fièvre","发烧（症状出现）"],["la fièvre monte / baisse","烧升高 / 退"]],"sy":[["température","familier","（口语）avoir de la température = 发烧"]],"fq":"高频，看病常用。","me":"fièvre ≈ fever：f-v 骨架相同。","tr":{"zh":"孩子发烧了，我们去看医生。","fr":"L'enfant a de la fièvre, nous allons chez le médecin.","alt":"Le petit a de la fièvre, on va chez le docteur.","note":"「发烧」固定用 avoir de la fièvre。"}},
 "La bouche": {"pos":"n.f. 阴性名词，复数 bouches","s":"嘴。ouvrir la bouche = 张嘴。也指出入口，如 la bouche de métro（地铁口）。","ipa":"[buʃ]","ph":"ou 读 [u]；ch 读 [ʃ]；结尾 e 不读。","pi":"ou 读 [u]，ch 读 [ʃ]，不是「奇」；不要把 bouche 与 boucher（屠夫）混淆。","et":"来自拉丁语 bucca（面颊，鼓起的腮），后来指「嘴」。","ex":[["Ouvre la bouche.","张开嘴。"],["Ferme la bouche quand tu manges.","吃饭时把嘴闭上。"]],"co":[["ouvrir / fermer la bouche","张 / 闭嘴"],["la bouche de métro","地铁出入口"],["bouche bée","目瞪口呆"],["de bouche à oreille","口口相传"]],"sy":[["gueule","argot","（粗）嘴，多用于动物"],["lèvres","courant","嘴唇"]],"fq":"高频，日常常用。","me":"bouche 像英语 mouth 的「嘴」：ou 的音。","tr":{"zh":"医生说：「请张开嘴。」","fr":"Le docteur dit : « Ouvrez la bouche. »","alt":"Le médecin dit : « Ouvrez la bouche, s'il vous plaît. »","note":"对医生用 vous：ouvrez；对孩子用 tu：ouvre。"}},
 "La course (à pied)": {"pos":"n.f. 阴性名词，复数 courses","s":"跑步。la course à pied 是「跑步」这项运动；une course 也指比赛，或 faire des courses（买东西）。","ipa":"[kuʁs]","ph":"ou 读 [u]；rs 读 [ʁs]，e 不读。à pied 读 [a pje]，d 不发音。","pi":"faire la course ≠ faire les courses：前者是赛跑，后者是买东西（常用复数）。","et":"来自拉丁语 cursus（跑），与 courir（跑）同源。","ex":[["J'aime la course à pied.","我喜欢跑步。"],["Il fait de la course à pied le dimanche.","他周日跑步。"]],"co":[["faire de la course à pied","跑步"],["une course de vitesse","短跑赛"],["faire des courses","买东西"],["faire la course","赛跑"]],"sy":[["jogging","courant","慢跑"],["footing","courant","慢跑（法式英语）"]],"fq":"中频，运动话题常用。","me":"course ← courir：「用脚（à pied）跑」。","tr":{"zh":"我每周做两次跑步。","fr":"Je fais de la course à pied deux fois par semaine.","alt":"Je cours deux fois par semaine.","note":"运动用 faire de + 部分冠词。"}},
 "La fréquence": {"pos":"n.f. 阴性名词，复数 fréquences","s":"频率；频繁程度。问「多久一次」可以说 À quelle fréquence ... ?。也指无线电频率（la fréquence de la radio）。","ipa":"[fʁe.kɑ̃s]","ph":"é 读 [e]；qu 读 [k]；en 读 [ɑ̃]；c 读 [s]。","pi":"qu 读 [k]，en 读 [ɑ̃]，不是「昂」后加 n；结尾 ce 读 [s]。","et":"来自拉丁语 frequentia（频繁，人多），形容词 fréquent。","ex":[["Quelle est la fréquence ?","频率是多少？"],["À quelle fréquence tu fais du sport ?","你多久运动一次？"]],"co":[["à quelle fréquence","多久一次"],["la fréquence cardiaque","心率"],["avec une grande fréquence","非常频繁"]],"sy":[["rythme","courant","节奏、频率"],["fois par semaine","courant","每周几次"]],"fq":"中频。","me":"fréquence ≈ frequency：fr-é-quence。","tr":{"zh":"你多久跑一次步？","fr":"À quelle fréquence tu cours ?","alt":"Tu cours à quelle fréquence ?","note":"à quelle fréquence 用来问「多久一次」。"}},
 "La gorge": {"pos":"n.f. 阴性名词，复数 gorges","s":"喉咙；嗓子。avoir mal à la gorge = 喉咙痛。也指山谷（les gorges，峡谷）。","ipa":"[gɔʁʒ]","ph":"g 在 o 前读 [g]；rge 读 [ʁʒ]；结尾 e 不读。","pi":"第一个 g 读 [g]，第二个 g 读 [ʒ]（因为后接 e）。","et":"来自晚期拉丁语 gurges（旋涡、深渊）的变体，指「吞咽的通道」。","ex":[["J'ai mal à la gorge.","我喉咙痛。"],["Il a la gorge sèche.","他嗓子很干。"]],"co":[["avoir mal à la gorge","喉咙痛"],["un mal de gorge","喉咙痛（名词）"],["avoir la gorge serrée","喉咙发紧（紧张）"],["les gorges du Verdon","凡尔登峡谷"]],"sy":[["gosier","soutenu","咽喉"]],"fq":"高频，看病常用。","me":"gorge ≈ gorge（英语「吞下」）：喉咙。","tr":{"zh":"我喉咙痛，不能说话。","fr":"J'ai mal à la gorge, je ne peux pas parler.","alt":"J'ai la gorge qui fait mal, je ne peux pas parler.","note":"avoir mal à + 身体部位。"}},
 "La grippe": {"pos":"n.f. 阴性名词，复数 grippes","s":"流感；流行性感冒。比 un rhume 严重，常伴随发烧、全身酸痛。avoir la grippe = 得了流感。","ipa":"[gʁip]","ph":"g 读 [g]；r 在喉咙后部；i 读 [i]；pp 读 [p]，e 不读。","pi":"pp 只读一个 [p]；不要把 grippe 与 rhume 混用。","et":"来自动词 gripper（抓住、攫取）；日耳曼语来源，指病「突然抓住」人。","ex":[["J'ai la grippe.","我得了流感。"],["La grippe est très forte cet hiver.","今年冬天流感很严重。"]],"co":[["avoir la grippe","得流感"],["attraper la grippe","染上流感"],["un vaccin contre la grippe","流感疫苗"],["la grippe aviaire","禽流感"]],"sy":[["rhume","courant","普通感冒，比 grippe 轻"],["crève","familier","（口语）重感冒"]],"fq":"高频，冬季常用。","me":"grippe ← gripper：被病「抓」住了。","tr":{"zh":"我得了流感，不去上班。","fr":"J'ai la grippe, je ne vais pas travailler.","alt":"J'ai la grippe, je reste à la maison.","note":"avoir la grippe 用定冠词 la。"}},
 "La gymnastique": {"pos":"n.f. 阴性名词，复数 gymnastiques（多用单数）","s":"体操；健身操。faire de la gymnastique = 做体操或锻炼。口语常缩写为 la gym。","ipa":"[ʒim.nas.tik]","ph":"g 在 y 前读 [ʒ]；y 读 [i]；mn 分开读 [m.n]；qu 读 [k]。","pi":"gy 读 [ʒi]，不是 [gi]；m 和 n 都要发音。","et":"来自希腊语 gumnos（裸体的）：古希腊人裸体锻炼，同源英语 gymnastics。","ex":[["Je fais de la gymnastique.","我做体操。"],["Elle fait de la gymnastique le matin.","她早上做体操。"]],"co":[["faire de la gymnastique","做体操、锻炼"],["la gymnastique douce","轻柔体操"],["un cours de gym","健身课"]],"sy":[["gym","familier","体操、健身（简称）"],["fitness","courant","健身"]],"fq":"中频。","me":"gym + nastique：gym 是「裸」，运动时脱衣。","tr":{"zh":"我每天早上做十分钟体操。","fr":"Je fais dix minutes de gymnastique chaque matin.","alt":"Je fais un peu de gym tous les matins.","note":"运动用 faire de la + 名词。"}},
 "La pétanque": {"pos":"n.f. 阴性名词，复数 pétanques（多用单数）","s":"地掷球（法国南部常见的金属球游戏）。玩地掷球用 jouer à la pétanque；球叫 les boules。","ipa":"[pe.tɑ̃k]","ph":"é 读 [e]；an 读 [ɑ̃]；qu 读 [k]；结尾 e 不读。","pi":"an 读鼻音 [ɑ̃]；qu 读 [k]，不读 [kw]。","et":"来自普罗旺斯语 pèd tanco（脚固定不动）：投球时双脚站定。1907 年起得名。","ex":[["Nous jouons à la pétanque.","我们玩地掷球。"],["Ils jouent à la pétanque sur la place.","他们在广场上玩地掷球。"]],"co":[["jouer à la pétanque","玩地掷球"],["une partie de pétanque","一局地掷球"],["un terrain de pétanque","地掷球场"]],"sy":[["boules","courant","滚球类游戏的总称"]],"fq":"中频，法国南部文化词。","me":"pétanque = 「脚（pèd）不动（tanco）」。","tr":{"zh":"夏天我们在广场玩地掷球。","fr":"En été, nous jouons à la pétanque sur la place.","alt":"L'été, on joue à la pétanque sur la place.","note":"jouer à + 游戏 / 运动。"}},
 "La poitrine": {"pos":"n.f. 阴性名词，复数 poitrines","s":"胸部；胸口。avoir mal à la poitrine / dans la poitrine = 胸痛。也可指女性乳房，但日常多指胸口。","ipa":"[pwa.tʁin]","ph":"oi 读 [wa]；tr 读 [tʁ]；结尾 -ine 读 [in]，n 要发音，e 不读。","pi":"oi 读 [wa]；结尾是 [in]（不是鼻音），因为 n 后有 e。","et":"来自晚期拉丁语 pectorina，源自 pectus（胸）。","ex":[["Si tu as mal dans la poitrine, va chez le docteur.","如果胸口疼，去看医生。"],["Il a une douleur dans la poitrine.","他胸口有疼痛。"]],"co":[["avoir mal à la poitrine","胸痛"],["une douleur dans la poitrine","胸口疼痛"],["une toux de poitrine","胸腔咳嗽"]],"sy":[["torse","courant","躯干上半身"],["buste","courant","上半身"]],"fq":"中频，看病常用。","me":"poitrine ← pectus（胸）：pect → poit。","tr":{"zh":"我胸口痛，呼吸困难。","fr":"J'ai mal à la poitrine, je respire mal.","alt":"J'ai mal dans la poitrine, j'ai du mal à respirer.","note":"mal à la / dans la + 部位。"}},
 "La tête": {"pos":"n.f. 阴性名词，复数 têtes","s":"头；脑袋。avoir mal à la tête = 头疼。也有「头脑、领头」意思：en tête = 在前面。","ipa":"[tɛt]","ph":"ê 读 [ɛ]；两个 t 都读 [t]；结尾 e 不读。","pi":"ê 读 [ɛ]（开口），不是 [e]；重音符号不可漏。","et":"来自拉丁语 testa（陶罐、壳），后来在通俗拉丁语里指「头」，取代了 caput。","ex":[["J'ai mal à la tête.","我头疼。"],["Elle secoue la tête.","她摇头。"]],"co":[["avoir mal à la tête","头疼"],["un mal de tête","头痛（名词）"],["en tête","领先、在前面"],["avoir la tête qui tourne","头晕"]],"sy":[["crâne","courant","头骨、脑壳"],["caboche","familier","（口语）脑袋"],["bouille","familier","（口语）脸"]],"fq":"极高频，日常常用。","me":"tête ≈ 「头」，ê 就是被省掉的 s（teste → tête）。","tr":{"zh":"我头很疼，我想休息。","fr":"J'ai très mal à la tête, je veux me reposer.","alt":"J'ai un gros mal de tête, je vais me reposer.","note":"avoir mal à + 部位；mal 前加 très。"}},
 "Une carte vitale": {"pos":"n.f. 阴性名词，复数 cartes vitales（正式写作 carte Vitale）","s":"医保卡（法国的社保健康卡）。去看医生、买药时出示，用来报销医疗费用。","ipa":"[kaʁt vi.tal]","ph":"carte 读 [kaʁt]，e 不读；vitale 读 [vi.tal]，e 不读。","pi":"vitale 结尾 -ale 读 [al]，不是鼻音；这是阴性形容词，与 carte 一致。","et":"carte（卡片）+ vital（生命的，来自拉丁语 vita 生命）。1998 年起使用。","ex":[["J'ai ma carte vitale.","我有医保卡。"],["N'oubliez pas votre carte vitale.","别忘了带您的医保卡。"]],"co":[["présenter sa carte vitale","出示医保卡"],["oublier sa carte vitale","忘带医保卡"],["mettre à jour sa carte vitale","更新医保卡"]],"sy":[["carte de sécu","familier","（口语）社保卡"]],"fq":"中频，在法国生活很常用。","me":"vitale ← vie：关系到生命（健康）的卡。","tr":{"zh":"我去看医生，要带医保卡。","fr":"Je vais chez le médecin, je dois prendre ma carte vitale.","alt":"Je vais chez le docteur, j'ai besoin de ma carte vitale.","note":"devoir + 动词原形 = 必须。"}},
 "Une compétition": {"pos":"n.f. 阴性名词，复数 compétitions","s":"比赛；竞赛（多指有排名的正式比赛，如奥运会）；也指竞争。faire de la compétition = 参加竞技比赛。","ipa":"[kɔ̃.pe.ti.sjɔ̃]","ph":"om 读 [ɔ̃]；é 读 [e]；ti 在这里读 [si]（-tion 读 [sjɔ̃]）。","pi":"-tion 读 [sjɔ̃]，不是 [tion]；m 在 p 前使 o 成为鼻音。","et":"来自拉丁语 competitio（竞争），由 competere（一起追求）而来，同源英语 competition。","ex":[["C'est une grande compétition.","这是一场大赛。"],["Elle participe à une compétition de natation.","她参加游泳比赛。"]],"co":[["participer à une compétition","参加比赛"],["faire de la compétition","参加竞技"],["une compétition sportive","体育赛事"],["en compétition avec","与……竞争"]],"sy":[["concours","courant","考试、竞赛（选拔）"],["match","courant","一场球赛"],["tournoi","courant","锦标赛"]],"fq":"中频，运动话题常用。","me":"compétition ≈ competition，-tion 读 [sjɔ̃]。","tr":{"zh":"他每年参加一场游泳比赛。","fr":"Il participe à une compétition de natation chaque année.","alt":"Il fait une compétition de natation tous les ans.","note":"participer à + 名词。"}},
 "Une corde à sauter": {"pos":"n.f. 阴性名词，复数 cordes à sauter","s":"跳绳。用来跳绳的绳子；做动作用 sauter à la corde 或 faire de la corde à sauter。","ipa":"[kɔʁd a so.te]","ph":"corde 读 [kɔʁd]，e 不读；à 读 [a]；sauter 读 [so.te]，au 读 [o]，-er 读 [e]。","pi":"sauter 结尾 -er 读 [e]，r 不发音；au 读 [o]。","et":"corde（绳，来自拉丁语 chorda，弦）+ à sauter（用来跳的）。","ex":[["Elle a une corde à sauter.","她有一根跳绳。"],["Les enfants jouent avec une corde à sauter.","孩子们玩跳绳。"]],"co":[["sauter à la corde","跳绳"],["faire de la corde à sauter","做跳绳运动"],["une corde à linge","晾衣绳"]],"sy":[["corde","courant","绳子（泛指）"]],"fq":"低频，运动话题用。","me":"corde + à sauter：「用来跳的绳」。","tr":{"zh":"我每天用跳绳锻炼十分钟。","fr":"Je fais dix minutes de corde à sauter chaque jour.","alt":"Je saute à la corde dix minutes par jour.","note":"corde à sauter 是名词；sauter à la corde 是动作。"}},
 "Une ordonnance": {"pos":"n.f. 阴性名词，复数 ordonnances","s":"处方；医嘱单。医生开的药单。sur ordonnance = 凭处方。也指法令、命令（法律用语）。","ipa":"[ɔʁ.dɔ.nɑ̃s]","ph":"or 读 [ɔʁ]；do 读 [dɔ]；-nance 读 [nɑ̃s]。","pi":"中间音节 do 读 [dɔ]，不是鼻音；结尾 -ance 读 [ɑ̃s]。","et":"来自动词 ordonner（命令，安排），源自 ordre，拉丁语 ordo。","ex":[["Le docteur me donne une ordonnance.","医生给我开处方。"],["Ce médicament est sur ordonnance.","这种药凭处方。"]],"co":[["faire / donner une ordonnance","开处方"],["sur ordonnance","凭处方"],["aller à la pharmacie avec l'ordonnance","拿处方去药房"]],"sy":[["prescription","soutenu","处方、规定（较正式）"]],"fq":"中频，看病常用。","me":"ordonnance：医生「下命令」（ordonner）该吃什么药。","tr":{"zh":"药剂师需要看您的处方。","fr":"Le pharmacien a besoin de votre ordonnance.","alt":"Il faut montrer l'ordonnance au pharmacien.","note":"avoir besoin de + 名词。"}},
 "Une radio": {"pos":"n.f. 阴性名词，复数 radios","s":"X光片；拍 X 光（radiographie 的简称）。faire une radio = 拍片。注意 la radio 也指收音机、广播。","ipa":"[ʁa.djo]","ph":"r 在喉咙；a 读 [a]；dio 读 [djo]。","pi":"同形词多义：une radio 可以是 X光片，也可以是收音机 / 电台，靠上下文判断。","et":"radiographie 的缩写，来自拉丁语 radius（光线）+ 希腊语 graphein（写）。","ex":[["Le docteur m'a fait une radio des poumons.","医生给我拍了肺部X光。"],["J'écoute la radio dans la voiture.","我在车里听广播。"]],"co":[["faire une radio","拍 X 光"],["passer une radio","去拍 X 光"],["la radio des poumons","肺部 X 光"],["écouter la radio","听广播"]],"sy":[["radiographie","soutenu","X 光检查（全称）"],["scanner","courant","CT 扫描"]],"fq":"高频，看病、日常常用。","me":"radio = radius（光线）：穿透身体的光线。","tr":{"zh":"我需要拍一张膝盖的X光。","fr":"J'ai besoin d'une radio du genou.","alt":"Il me faut une radio du genou.","note":"une radio de + 部位。"}},
 "Une salle de sport": {"pos":"n.f. 阴性名词，复数 salles de sport","s":"健身房；运动场馆。去健身房用 aller à la salle de sport。口语也说 la salle（简称）。","ipa":"[sal də spɔʁ]","ph":"salle 读 [sal]，ll 读一个 [l]；de 读 [də]；sport 读 [spɔʁ]，t 不发音。","pi":"sport 里的 t 不发音，但 r 要发；de 读轻的 [də]。","et":"salle（厅，来自日耳曼语）+ sport（来自英语 sport，最早源于古法语 desport 「消遣」）。","ex":[["Je vais à la salle de sport.","我去健身房。"],["Il y a une salle de sport près de chez moi.","我家附近有一家健身房。"]],"co":[["aller à la salle de sport","去健身房"],["s'inscrire à la salle de sport","办健身房会员"],["un abonnement à la salle de sport","健身房会员卡"]],"sy":[["salle de gym","courant","健身房"],["gymnase","courant","体育馆"],["fitness","courant","健身中心"]],"fq":"高频，日常常用。","me":"salle（房间）+ sport（运动）：直译「运动的房间」。","tr":{"zh":"我每周去健身房三次。","fr":"Je vais à la salle de sport trois fois par semaine.","alt":"Je vais à la salle trois fois par semaine.","note":"aller à + 地点；trois fois par semaine。"}},
 "Une serviette": {"pos":"n.f. 阴性名词，复数 serviettes","s":"毛巾；浴巾；餐巾。还可指公文包 une serviette。具体是什么要看上下文：serviette de bain 浴巾，serviette de table 餐巾。","ipa":"[sɛʁ.vjɛt]","ph":"e 读 [ɛ]；r 在喉咙；vi 读 [vj]；ette 读 [ɛt]，t 要发音。","pi":"ette 读 [ɛt]，结尾的 t 要发；不要把 serviette 与英语 serviette 的发音混淆。","et":"来自动词 servir（服务），指用来「伺候」的布。","ex":[["J'ai une serviette propre.","我有一条干净的毛巾。"],["Prends une serviette pour la piscine.","去游泳池要带条毛巾。"]],"co":[["une serviette de bain","浴巾"],["une serviette de table","餐巾"],["une serviette en papier","纸巾（餐巾纸）"],["se sécher avec une serviette","用毛巾擦干"]],"sy":[["essuie-mains","courant","擦手巾"],["drap de bain","courant","大浴巾"]],"fq":"高频，日常常用。","me":"serviette ← servir：随时服务你的布。","tr":{"zh":"请给我一条干净的浴巾。","fr":"Donnez-moi une serviette de bain propre, s'il vous plaît.","alt":"Je voudrais une serviette de bain propre, s'il vous plaît.","note":"形容词 propre 放在名词后（干净的）。"}},
 "Des calories": {"pos":"n.f.pl. 阴性复数名词，单数 calorie","s":"卡路里（热量单位）。谈饮食、运动时常用：compter les calories = 计算热量。","ipa":"[ka.lɔ.ʁi]","ph":"c 读 [k]；a 读 [a]；o 读 [ɔ]；r 在喉咙；结尾 ie 读 [i]。","pi":"结尾 ie 读 [i]，不读 [ie]；重音在最后一个音节，不是英语 calorie 的重音。","et":"来自拉丁语 calor（热），19 世纪创造的单位。","ex":[["Je compte les calories.","我计算卡路里。"],["Ce gâteau a beaucoup de calories.","这块蛋糕热量很高。"]],"co":[["compter les calories","计算热量"],["brûler des calories","燃烧热量"],["un repas riche en calories","高热量的一餐"],["pauvre en calories","低热量"]],"sy":[["kilocalories (kcal)","courant","千卡（食品标签上的单位）"]],"fq":"中频，饮食、运动话题常用。","me":"calorie ← calor（热）：食物给身体的「热量」。","tr":{"zh":"运动可以消耗很多热量。","fr":"Le sport brûle beaucoup de calories.","alt":"On brûle beaucoup de calories avec le sport.","note":"beaucoup de + 名词，de 后不加冠词。"}},
 "Des vitamines": {"pos":"n.f.pl. 阴性复数名词，单数 vitamine","s":"维生素。吃维生素片用 prendre des vitamines；水果、蔬菜里含有很多维生素 (riche en vitamines)。","ipa":"[vi.ta.min]","ph":"v 读 [v]；i 读 [i]；a 读 [a]；结尾 mine 读 [min]，不是鼻音。","pi":"-mine 读 [min]，因为 n 后有 e；不要读成鼻音 [mɛ̃]。","et":"来自拉丁语 vita（生命）+ amine（胺），1912 年由 Funk 创造的词。","ex":[["Je prends des vitamines.","我吃维生素。"],["Les fruits contiennent beaucoup de vitamines.","水果含有很多维生素。"]],"co":[["prendre des vitamines","吃维生素"],["riche en vitamines","富含维生素"],["la vitamine C","维生素C"],["une cure de vitamines","一个疗程的维生素"]],"sy":[["complément alimentaire","courant","营养补充剂"]],"fq":"中频，健康话题常用。","me":"vita（生命）+ amine：「生命之胺」。","tr":{"zh":"冬天我吃一点维生素。","fr":"En hiver, je prends des vitamines.","alt":"L'hiver, je prends un peu de vitamines.","note":"des vitamines：部分冠词用复数。"}},
 "Les bras": {"pos":"n.m.pl. 阳性复数名词，单数 bras（单复数同形）","s":"手臂；胳膊。注意：bras 单复数同形。avoir mal aux bras = 手臂疼。les bras ouverts = 张开双臂。","ipa":"[bʁa]","ph":"b + r 读 [bʁ]；a 读 [a]；结尾 s 不发音。","pi":"结尾 s 不发音，所以 bras 与 bra 读法一样；les bras 与 le bras 听起来相同，只靠冠词区分。","et":"来自拉丁语 bracchium，源自希腊语 brakhiōn。","ex":[["Il a de longs bras.","他的手臂很长。"],["Elle porte l'enfant dans ses bras.","她把孩子抱在怀里。"]],"co":[["avoir mal au bras","手臂疼"],["dans les bras de quelqu'un","在某人怀里"],["croiser les bras","双臂交叉"],["à bras ouverts","张开双臂（热情欢迎）"]],"sy":[["membre","soutenu","肢体"],["main","courant","手，不同于手臂"]],"fq":"高频，日常常用。","me":"bras 的 s 不发音：与 bra 一样，别和 braise 混。","tr":{"zh":"我手臂很累，因为我提了很重的包。","fr":"J'ai mal aux bras parce que j'ai porté un sac lourd.","alt":"Mes bras sont fatigués, mon sac est très lourd.","note":"mal aux + 复数身体部位（à + les = aux）。"}},
 "Les dents": {"pos":"n.f.pl. 阴性复数名词，单数 une dent","s":"牙齿。刷牙：se brosser les dents。牙医：le dentiste。说牙疼：avoir mal aux dents（多颗）或 avoir mal à une dent。","ipa":"[dɑ̃]","ph":"d 读 [d]；en 读 [ɑ̃]；t 和 s 都不发音。","pi":"结尾的 t、s 都不发音，只读 [dɑ̃]；dent 的单复数读音相同。","et":"来自拉丁语 dens（属格 dentis），同源 dentiste, dentaire。","ex":[["Je me brosse les dents.","我刷牙。"],["Il a mal aux dents.","他牙疼。"]],"co":[["se brosser les dents","刷牙"],["avoir mal aux dents","牙疼"],["une dent de lait","乳牙"],["serrer les dents","咬紧牙关"]],"sy":[["quenottes","familier","（儿语）小牙"],["crocs","familier","獠牙；（口语）牙"]],"fq":"极高频，日常常用。","me":"dent ← dens → dentiste：看牙的人。","tr":{"zh":"饭后要刷牙。","fr":"Après le repas, il faut se brosser les dents.","alt":"Après manger, on se brosse les dents.","note":"刷牙：se brosser les dents，用定冠词 les。"}},
 "Les épaules": {"pos":"n.f.pl. 阴性复数名词，单数 une épaule","s":"肩膀。avoir mal aux épaules = 肩膀疼。hausser les épaules = 耸肩。","ipa":"[e.pol]","ph":"é 读 [e]；p 读 [p]；au 读 [o]；结尾 le 的 e 不读。","pi":"au 读 [o]，不是「奥」；结尾 e 不读：épaule 读 [e.pol]。","et":"来自拉丁语 spatula（小铲，肩胛骨），经演变而来。","ex":[["J'ai mal aux épaules.","我肩膀疼。"],["Il hausse les épaules.","他耸了耸肩。"]],"co":[["avoir mal aux épaules","肩膀疼"],["hausser les épaules","耸肩"],["porter sur les épaules","扛在肩上"],["avoir de larges épaules","肩膀宽"]],"sy":[["omoplate","soutenu","肩胛骨"]],"fq":"中频，运动、看病常用。","me":"épaule 与 épaulette（肩章）同族。","tr":{"zh":"我背太久，肩膀很疼。","fr":"J'ai porté mon sac trop longtemps, j'ai mal aux épaules.","alt":"Mon sac est lourd, j'ai mal aux épaules.","note":"avoir mal à + les → aux。"}},
 "Les genoux": {"pos":"n.m.pl. 阳性复数名词，单数 un genou","s":"膝盖。复数加 x：genoux（不是 genous）。à genoux = 跪着。avoir mal aux genoux = 膝盖疼。","ipa":"[ʒə.nu]","ph":"g 在 e 前读 [ʒ]；e 读 [ə]（轻）；nou 读 [nu]；x 不发音。","pi":"复数 x 不发音，读音和单数一样；注意不要写成 genous。","et":"来自拉丁语 genuculum（小膝），源自 genu（膝）。","ex":[["Il a mal aux genoux.","他膝盖疼。"],["Elle est à genoux sur le tapis.","她跪在地毯上。"]],"co":[["avoir mal aux genoux","膝盖疼"],["être à genoux","跪着"],["se mettre à genoux","跪下"],["sur les genoux de quelqu'un","坐在某人腿上"]],"sy":[["rotule","soutenu","膝盖骨"]],"fq":"中频，运动、看病常用。","me":"genou → genoux：和 bijou → bijoux 一样加 x。","tr":{"zh":"跑完步以后，我的膝盖有点疼。","fr":"Après la course, j'ai un peu mal aux genoux.","alt":"Après avoir couru, mes genoux me font mal.","note":"faire mal 的主语可以是身体部位。"}},
 "Les jambes": {"pos":"n.f.pl. 阴性复数名词，单数 une jambe","s":"腿。大腿 la cuisse，小腿 le mollet，膝盖 le genou。avoir mal aux jambes = 腿疼。","ipa":"[ʒɑ̃b]","ph":"j 读 [ʒ]；am 读 [ɑ̃]；b 读 [b]；结尾 e 不读。","pi":"am 读鼻音 [ɑ̃]，但后面 b 仍要发音：[ʒɑ̃b]。","et":"来自晚期拉丁语 gamba（马的踝关节，腿），与意大利语 gamba 同源。","ex":[["J'ai mal aux jambes.","我腿疼。"],["Elle croise les jambes.","她翘起腿。"]],"co":[["avoir mal aux jambes","腿疼"],["croiser les jambes","翘二郎腿"],["se dégourdir les jambes","活动腿脚"],["à toutes jambes","拼命地跑"]],"sy":[["gambette","familier","（口语）小腿、腿"],["guibole","argot","（俚语）腿"]],"fq":"高频，日常常用。","me":"jambe：和 jambon（火腿）同族，都是「腿」。","tr":{"zh":"爬完楼梯，我的腿很疼。","fr":"Après les escaliers, j'ai mal aux jambes.","alt":"Après avoir monté les escaliers, j'ai les jambes qui font mal.","note":"mal aux jambes：复数用 aux。"}},
 "Les mains": {"pos":"n.f.pl. 阴性复数名词，单数 une main","s":"手。注意：main 是阴性名词。se laver les mains = 洗手；donner la main = 牵手；à la main = 手工。","ipa":"[mɛ̃]","ph":"ain 读 [ɛ̃]；结尾 s 不发音。","pi":"ain 读 [ɛ̃]，不是「艾恩」；s 不发音，复数与单数读音相同。","et":"来自拉丁语 manus（手），同源 manuel, maintenant。","ex":[["Lave-toi les mains.","把手洗干净。"],["Elle tient la main de son enfant.","她牵着孩子的手。"]],"co":[["se laver les mains","洗手"],["donner la main","牵手"],["fait à la main","手工制作"],["haut les mains !","举起手来！"]],"sy":[["paluche","familier","（口语）手"],["pogne","argot","（俚语）手"]],"fq":"极高频，日常常用。","me":"main ← manus：manuel（手动的）、maintenant（此刻，手边）。","tr":{"zh":"吃饭前要洗手。","fr":"Avant de manger, il faut se laver les mains.","alt":"Avant le repas, on se lave les mains.","note":"se laver les mains：身体部位前用定冠词，不用 mes。"}},
 "Les oreilles": {"pos":"n.f.pl. 阴性复数名词，单数 une oreille","s":"耳朵。avoir mal aux oreilles = 耳朵疼。tendre l'oreille = 竖起耳朵听。","ipa":"[ɔ.ʁɛj]","ph":"o 读 [ɔ]；r 在喉咙；eille 读 [ɛj]，ll 读 [j]；结尾 e 不读。","pi":"-eille 读 [ɛj]，是「爷」似的音，不是「雷尔」；注意 oreille 开头是 o，不是 au。","et":"来自拉丁语 auricula（小耳朵），源自 auris（耳）。","ex":[["J'ai mal aux oreilles.","我耳朵疼。"],["Il a de grandes oreilles.","他耳朵很大。"]],"co":[["avoir mal aux oreilles","耳朵疼"],["tendre l'oreille","竖起耳朵听"],["dur d'oreille","耳背"],["une infection de l'oreille","耳朵感染"]],"sy":[["esgourdes","argot","（俚语）耳朵"]],"fq":"高频，日常常用。","me":"oreille ← auricula：小小的 auris。","tr":{"zh":"孩子耳朵疼，他哭了。","fr":"L'enfant a mal aux oreilles, il pleure.","alt":"Le petit a mal aux oreilles, il pleure.","note":"il pleure：pleurer 哭。"}},
 "Les pieds": {"pos":"n.m.pl. 阳性复数名词，单数 un pied","s":"脚；足。à pied = 步行。avoir froid aux pieds = 脚冷。pied 也是旧长度单位「英尺」。","ipa":"[pje]","ph":"pi 读 [pj]；ed 读 [e]；d、s 不发音。","pi":"ied 读 [je]，结尾 d、s 都不发音；pied 与 pied(s) 读音相同。","et":"来自拉丁语 pes（属格 pedis）。同源 pédale, pédestre。","ex":[["J'ai froid aux pieds.","我脚冷。"],["On y va à pied ?","我们走路去吗？"]],"co":[["aller à pied","步行去"],["avoir mal aux pieds","脚疼"],["marcher pieds nus","光脚走路"],["mettre les pieds dans le plat","说话冒失"]],"sy":[["panard","argot","（俚语）脚"],["patte","familier","（口语）腿、脚"]],"fq":"极高频，日常常用。","me":"pied ← pes：pédale 是用脚踩的东西。","tr":{"zh":"我的脚很冷，我想穿袜子。","fr":"J'ai froid aux pieds, je veux mettre des chaussettes.","alt":"J'ai les pieds froids, je vais mettre des chaussettes.","note":"avoir froid à + les → aux。"}},
 "Les poumons": {"pos":"n.m.pl. 阳性复数名词，单数 un poumon","s":"肺。avoir un problème aux poumons = 肺部有问题。radio des poumons = 肺部 X 光。","ipa":"[pu.mɔ̃]","ph":"ou 读 [u]；m 读 [m]；on 读 [ɔ̃]；结尾 s 不发音。","pi":"第二个音节 mon 读 [mɔ̃]，n 不发音；ou 读 [u]。","et":"来自拉丁语 pulmo（属格 pulmonis），同源 pulmonaire。","ex":[["Il a un problème aux poumons.","他肺部有问题。"],["Respire à pleins poumons.","深深地吸气。"]],"co":[["un problème aux poumons","肺部问题"],["à pleins poumons","用尽全力、深深地"],["une infection des poumons","肺部感染"],["la radio des poumons","肺部 X 光"]],"sy":[["souffle","courant","呼吸、气息"]],"fq":"中频，看病话题常用。","me":"poumon ← pulmo：和 pulmonaire（肺的）同族。","tr":{"zh":"医生检查我的肺。","fr":"Le docteur examine mes poumons.","alt":"Le médecin regarde mes poumons.","note":"examiner 检查。"}},
 "Les vestiaires": {"pos":"n.m.pl. 阳性复数名词，单数 un vestiaire","s":"更衣室；衣帽间。运动场馆的 les vestiaires；剧院、餐厅里存衣的地方也叫 le vestiaire。","ipa":"[vɛs.tjɛʁ]","ph":"e 读 [ɛ]；s 读 [s]；t 读 [t]；iaire 读 [jɛʁ]；结尾 s 不发音。","pi":"-aire 读 [ɛʁ]；r 要发音；复数 s 不发音。","et":"来自拉丁语 vestiarium（衣橱），源自 vestis（衣服）。同源 vêtement。","ex":[["Je vais aux vestiaires.","我去更衣室。"],["Les vestiaires sont à droite de la piscine.","更衣室在游泳池右边。"]],"co":[["aller aux vestiaires","去更衣室"],["les vestiaires des hommes / des femmes","男 / 女更衣室"],["laisser son manteau au vestiaire","把大衣存在衣帽间"]],"sy":[["cabine","courant","更衣小间"],["consigne","courant","寄存处"]],"fq":"中频，运动、剧院常用。","me":"vestiaire ← vestis：放「衣服」的地方，同 vêtement。","tr":{"zh":"运动以后我在更衣室换衣服。","fr":"Après le sport, je me change dans les vestiaires.","alt":"Après le sport, je vais me changer aux vestiaires.","note":"se changer = 换衣服。"}},
 "Un banquier / Une banquière": {"pos":"n. 名词，阳 banquier / 阴 banquière，复数 banquiers / banquières","s":"银行职员；银行家。在银行管理你账户的人，也可指银行老板。去见银行顾问常说 mon conseiller bancaire。","ipa":"[bɑ̃.kje] / [bɑ̃.kjɛʁ]","ph":"an 读 [ɑ̃]；qu 读 [k]；ier 读 [je]（阳性），ière 读 [jɛʁ]（阴性）。","pi":"阳性结尾 -ier 的 r 不发音，阴性 -ière 的 r 要发音。","et":"来自 banque（银行），再加后缀 -ier；banque 源自意大利语 banca（长凳，钱商摆摊用的）。","ex":[["Je parle à mon banquier.","我和我的银行家谈。"],["Ma banquière me donne un rendez-vous.","我的银行职员给我约了时间。"]],"co":[["parler à son banquier","和银行职员谈"],["un banquier d'affaires","投资银行家"],["un rendez-vous avec la banquière","与银行职员的预约"]],"sy":[["conseiller bancaire","courant","银行顾问"],["guichetier","courant","柜员"]],"fq":"中频。","me":"banquier ← banque ← banca（长凳）：钱商坐在长凳上。","tr":{"zh":"我下周要见我的银行职员。","fr":"Je vois mon banquier la semaine prochaine.","alt":"J'ai rendez-vous avec ma banquière la semaine prochaine.","note":"banquier 阳性，banquière 阴性，要和性别一致。"}},
 "Un joueur / Une joueuse": {"pos":"n. 名词，阳 joueur / 阴 joueuse，复数 joueurs / joueuses","s":"运动员；玩家；选手。踢球、打牌、玩游戏的人都可用。joueur de foot = 足球运动员。","ipa":"[ʒwœʁ] / [ʒwøz]","ph":"j 读 [ʒ]；ou 读 [w]；eur 读 [œʁ]；阴性 euse 读 [øz]。","pi":"阳性 [œʁ] 与阴性 [øz] 元音不同；不要混淆。","et":"由动词 jouer（玩，来自拉丁语 iocari）加后缀 -eur / -euse 构成。","ex":[["C'est un bon joueur.","他是个好球员。"],["Cette joueuse est très rapide.","这位女选手非常快。"]],"co":[["un joueur de foot","足球运动员"],["un joueur de cartes","玩牌的人"],["une joueuse de tennis","女网球运动员"],["un bon / mauvais joueur","输得起 / 输不起的人"]],"sy":[["sportif / sportive","courant","运动员（泛指）"],["athlète","courant","田径运动员"]],"fq":"高频，运动话题常用。","me":"joueur ← jouer：玩（比赛）的人。","tr":{"zh":"这位女选手打得很好。","fr":"Cette joueuse joue très bien.","alt":"Cette joueuse est très forte.","note":"阴性 joueuse，指示词用 cette。"}},
 "Un(e) dentiste": {"pos":"n. 名词，阴阳同形 un dentiste / une dentiste，复数 dentistes","s":"牙医。男女同形，只靠冠词区分（un / une）。去看牙医：aller chez le dentiste。","ipa":"[dɑ̃.tist]","ph":"d 读 [d]；en 读 [ɑ̃]；t 读 [t]；结尾 e 不读。","pi":"t 在 -iste 里读 [t]，s 要发 [s]；前面的 dent- 里 t 不发音。","et":"由 dent（牙，来自拉丁语 dens）加后缀 -iste（从事某行业的人）构成。","ex":[["Je vais chez le dentiste.","我去看牙医。"],["Ma dentiste est très gentille.","我的牙医很和善。"]],"co":[["aller chez le dentiste","去看牙医"],["un rendez-vous chez le dentiste","看牙医的预约"],["un cabinet dentaire","牙科诊所"],["avoir peur du dentiste","害怕看牙医"]],"sy":[["chirurgien-dentiste","soutenu","牙科医生（正式名称）"]],"fq":"高频，看病话题常用。","me":"dent + iste：「牙的专家」。","tr":{"zh":"我明天要去看牙医。","fr":"Je vais chez le dentiste demain.","alt":"Demain, j'ai rendez-vous chez le dentiste.","note":"看医生、牙医用 chez + 人。"}},
 "Un(e) pharmacien(ne)": {"pos":"n. 名词，阳 pharmacien / 阴 pharmacienne，复数 pharmaciens / pharmaciennes","s":"药剂师。在药店 (la pharmacie) 工作，可以配药、给建议。去药店：aller à la pharmacie。","ipa":"[faʁ.ma.sjɛ̃] / [faʁ.ma.sjɛn]","ph":"ph 读 [f]；c 读 [s]（在 i 前）；ien 读 [jɛ̃]；阴性 ienne 读 [jɛn]。","pi":"ph 读 [f]，不是 [p]；阳性读鼻音 [jɛ̃]，阴性 n 要发 [jɛn]。","et":"来自 pharmacie，源自希腊语 pharmakon（药、毒药），加后缀 -ien。","ex":[["Je parle au pharmacien.","我和药剂师说话。"],["La pharmacienne me conseille un sirop.","女药剂师建议我吃糖浆。"]],"co":[["demander conseil au pharmacien","向药剂师咨询"],["la pharmacie de garde","值班药房"],["une pharmacienne","女药剂师"]],"sy":[["préparateur en pharmacie","courant","药房助理"]],"fq":"中频，看病话题常用。","me":"pharmacien ← pharmakon：卖药（有时也是毒）的人。","tr":{"zh":"药剂师给我开了一种药。","fr":"Le pharmacien me donne un médicament.","alt":"La pharmacienne me conseille un médicament.","note":"法国药剂师可以给建议，但处方药要医生的 ordonnance。"}},
 "Apporter": {"pos":"v. 及物动词，第一组（-er），助动词 avoir","s":"带来；拿来（把东西带到说话的地方）。apporter qch à qqn = 给某人带来。区别：amener 带人来，apporter 带物品来。","ipa":"[a.pɔʁ.te]","ph":"a 读 [a]；pp 读一个 [p]；o 读 [ɔ]；-er 读 [e]，r 不发音。","pi":"pp 只读一个 [p]；-er 结尾读 [e]；不要与 emporter（带走）混淆。","et":"来自拉丁语 apportare（ad + portare，带来）。同源 porter, importer。","ex":[["Je vais apporter un gâteau.","我带一个蛋糕。"],["Le serveur apporte le menu.","服务员把菜单拿来。"],["Apporte-moi un verre d'eau, s'il te plaît.","请给我拿杯水。"]],"co":[["apporter qch à qqn","给某人带来某物"],["apporter de l'aide","提供帮助"],["apporter un cadeau","带礼物"],["apporter du soin","用心"]],"sy":[["emporter","courant","带走（与 apporter 相反）"],["amener","courant","带（人、动物）来"],["ramener","courant","带回来"]],"fq":"高频，日常常用。","me":"apporter = ad + porter：带到（我这里）。","tr":{"zh":"你能带点水果来吗？","fr":"Tu peux apporter des fruits ?","alt":"Tu peux ramener des fruits ?","note":"apporter 带物品；带人用 amener。"}},
 "Apprendre": {"pos":"v. 及物动词，第三组，不规则，助动词 avoir（变位同 prendre：j'apprends, nous apprenons，过去分词 appris）","s":"学习；学会；得知。apprendre à + 动词原形 = 学会做某事；apprendre qch à qqn = 教某人某事。","ipa":"[a.pʁɑ̃dʁ]","ph":"a 读 [a]；pp 读 [p]；r 在喉咙；en 读 [ɑ̃]；结尾 dre 读 [dʁ]。","pi":"变位同 prendre：apprends 的 s、d 不发音；过去分词是 appris，不是 apprendu。","et":"来自拉丁语 apprehendere 的缩合形式：ad + prehendere（抓住）。同源 prendre, comprendre。","ex":[["Je veux apprendre le français.","我想学法语。"],["Elle apprend à nager.","她在学游泳。"],["Il m'apprend le piano.","他教我钢琴。"]],"co":[["apprendre à + 动词原形","学会做……"],["apprendre le français","学法语"],["apprendre qch à qqn","教某人某事"],["apprendre par cœur","背诵"]],"sy":[["étudier","courant","学习、研究（强调钻研）"],["enseigner","soutenu","教授"]],"fq":"极高频，日常常用。","me":"apprendre = à + prendre：抓住（知识）。","tr":{"zh":"我正在学法语，每天学一点。","fr":"J'apprends le français, un peu chaque jour.","alt":"Je suis en train d'apprendre le français, petit à petit.","note":"学某物直接宾语：apprendre le français，不加介词。"}},
 "Couler": {"pos":"v. 第一组（-er），助动词 avoir（沉没时也可用 avoir）","s":"流；流动。L'eau coule = 水在流。也指（船）沉没，或（鼻涕）流出：avoir le nez qui coule = 流鼻涕。","ipa":"[ku.le]","ph":"ou 读 [u]；-er 读 [e]，r 不发音。","pi":"ou 读 [u]；-er 结尾不发 r；不要与 couper（切）混淆。","et":"来自拉丁语 colare（过滤，使流过）。","ex":[["L'eau coule.","水在流。"],["Le robinet coule.","水龙头在漏水。"],["J'ai le nez qui coule.","我流鼻涕。"]],"co":[["avoir le nez qui coule","流鼻涕"],["le robinet coule","水龙头漏水"],["couler à pic","迅速沉没"],["la rivière coule","河水流淌"]],"sy":[["s'écouler","soutenu","流逝、流出"],["ruisseler","soutenu","淌流"],["fuir","courant","漏（水）"]],"fq":"中频。","me":"couler：水「流」，也能把船带到水底「沉」。","tr":{"zh":"水龙头一直在漏水。","fr":"Le robinet coule tout le temps.","alt":"Le robinet n'arrête pas de couler.","note":"n'arrête pas de + 动词原形 = 一直在……"}},
 "Éteindre": {"pos":"v. 及物动词，第三组，不规则，助动词 avoir（j'éteins, nous éteignons，过去分词 éteint）","s":"关闭（灯、电器）；熄灭（火）。éteindre la lumière / la télé / le feu。反义：allumer（打开、点燃）。","ipa":"[e.tɛ̃dʁ]","ph":"é 读 [e]；ein 读 [ɛ̃]；dre 读 [dʁ]；变位 éteignons 里 gn 读 [ɲ]。","pi":"j'éteins 的 s 不发音；nous éteignons 里 gn 读 [ɲ]；过去分词是 éteint，不是 éteindu。","et":"来自拉丁语 exstinguere（熄灭），同源英语 extinguish。","ex":[["Je vais éteindre la lumière.","我去关灯。"],["Éteins la télé, s'il te plaît.","请把电视关掉。"],["Les pompiers éteignent le feu.","消防员扑灭火。"]],"co":[["éteindre la lumière","关灯"],["éteindre la télé","关电视"],["éteindre le feu","灭火"],["éteindre son téléphone","关手机"]],"sy":[["fermer","courant","关（门、水龙头），不用于灯"],["allumer","courant","打开（灯）；反义词"]],"fq":"高频，日常常用。","me":"éteindre 与 extinguish 同源：把火 / 灯「灭」掉。","tr":{"zh":"出门前请关灯。","fr":"Éteins la lumière avant de sortir.","alt":"N'oublie pas d'éteindre la lumière avant de partir.","note":"avant de + 动词原形。"}},
 "Éternuer": {"pos":"v. 不及物动词，第一组（-er），助动词 avoir","s":"打喷嚏。感冒、过敏时常见。别人打喷嚏时，法国人说 À vos souhaits ! (祝您心想事成！)。","ipa":"[e.tɛʁ.nɥe]","ph":"é 读 [e]；ter 读 [tɛʁ]；nu 读 [nɥ]（先是 [ɥ]，嘴形像发 u 再转到 e）；-er 读 [e]。","pi":"-uer 里的 u 是半元音 [ɥ]；不要把 ter 的 r 吞掉。","et":"来自拉丁语 sternutare（打喷嚏）。","ex":[["Je vais éternuer.","我要打喷嚏了。"],["Il éternue beaucoup au printemps.","他春天经常打喷嚏。"]],"co":[["éternuer dans son coude","对着手肘打喷嚏"],["À vos souhaits !","（别人打喷嚏时）祝你健康！"],["un éternuement","一个喷嚏（名词）"]],"sy":[["atchoum","familier","阿嚏（拟声词）"]],"fq":"低频，看病、日常用。","me":"éternuer：像是「é-ter-nu-er」声音如同喷嚏。","tr":{"zh":"我感冒了，一直打喷嚏。","fr":"Je suis enrhumé, j'éternue tout le temps.","alt":"J'ai un rhume, je n'arrête pas d'éternuer.","note":"tout le temps = 一直。"}},
 "Falloir": {"pos":"v. 无人称动词（只用 il），第三组，不规则：il faut, il fallait, il faudra, il a fallu","s":"必须；需要；得。il faut + 名词 = 需要……；il faut + 动词原形 = 必须……；il faut que + 虚拟式。否定 il ne faut pas = 禁止，而不是「不必」；「不必」说 il n'est pas nécessaire de。","ipa":"[fa.lwaʁ]","ph":"fa 读 [fa]；loi 读 [lwa]；r 在喉咙。il faut 读 [il fo]，au 读 [o]，t 不发音。","pi":"il faut 里 t 不发音；il ne faut pas 是「不可以」，不是「不需要」。","et":"来自拉丁语 fallere（欺骗，使失败），后来演变为「缺少，需要」。","ex":[["Il va falloir partir.","得走了。"],["Il faut deux heures pour y aller.","去那里要两个小时。"],["Il faut que tu manges.","你得吃饭。"]],"co":[["il faut + 动词原形","必须……"],["il faut que + 虚拟式","必须……（有人称主语）"],["il faut + 名词","需要……"],["il ne faut pas","不可以……"]],"sy":[["devoir","courant","必须（有人称主语）"],["avoir besoin de","courant","需要"],["être obligé de","courant","不得不"]],"fq":"极高频，日常常用。","me":"il faut：一个固定短语，永远只有 il，没有别的主语。","tr":{"zh":"明天我们得早点起床。","fr":"Demain, il faudra se lever tôt.","alt":"Demain, il faut qu'on se lève tôt.","note":"il faudra：将来时；il faut que + 虚拟式（se lève）。"}},
 "Gagner": {"pos":"v. 及物动词，第一组（-er），助动词 avoir","s":"赢；赚（钱）；获得。gagner un match = 赢比赛；gagner de l'argent = 赚钱；gagner du temps = 节省时间。反义：perdre。","ipa":"[ga.ɲe]","ph":"g 读 [g]；a 读 [a]；gn 读 [ɲ]（像「尼」的鼻音）；-er 读 [e]。","pi":"gn 读 [ɲ]，不是 [gn]；-er 结尾不发 r。","et":"来自法兰克语（日耳曼语）*waidanjan，原义与觅食、放牧、获取食物有关，后来变成「获得、赚得」。","ex":[["Nous allons gagner.","我们会赢。"],["Il gagne bien sa vie.","他收入不错。"],["Elle a gagné un prix.","她获得了一个奖。"]],"co":[["gagner un match","赢比赛"],["gagner de l'argent","赚钱"],["gagner sa vie","谋生"],["gagner du temps","节省时间"]],"sy":[["remporter","soutenu","夺得、赢得"],["vaincre","littéraire","战胜"],["perdre","courant","反义词：输"]],"fq":"极高频，日常常用。","me":"gagner：赢 = 赚；gn 读成「尼」。","tr":{"zh":"我们今天晚上会赢这场比赛。","fr":"Nous allons gagner le match ce soir.","alt":"On va gagner le match ce soir.","note":"aller + 动词原形 = 近将来。"}},
 "Jardiner": {"pos":"v. 动词，第一组 -er，助动词 avoir","s":"做园艺，在花园或菜园里种花种菜。也可以说 faire du jardinage，意思相同。只和花园、菜园有关。","ipa":"[ʒaʁ.di.ne]","ph":"j [ʒ]；ar [aʁ]；di [di]；-er 读 [e]，r 不发音。","pi":"j 读 [ʒ]，不是 [dʒ]；结尾 -er 的 r 不发音。","et":"来自 jardin（花园）加动词后缀 -er；jardin 源自法兰克语，与英语 garden 同源。","ex":[["J'aime jardiner.","我喜欢园艺。"],["Elle jardine tous les dimanches.","她每个星期天都做园艺。"],["Mon père jardine derrière la maison.","我爸爸在房子后面莳弄花园。"]],"co":[["jardiner le week-end","周末做园艺"],["le jardinage","园艺（名词）"],["un jardinier / une jardinière","园丁"]],"sy":[["faire du jardinage","courant","做园艺，更常用的说法"],["cultiver","courant","种植（作物），范围更广"]],"fq":"中频，日常常用。","me":"jardin（花园）+ -er = 在花园里干活。","tr":{"zh":"周末我喜欢在花园里干活。","fr":"Le week-end, j'aime jardiner.","alt":"Le week-end, j'adore faire du jardinage.","note":"aimer + 动词原形。"}},
 "Jouer": {"pos":"v. 动词，第一组 -er，助动词 avoir","s":"玩；演奏；比赛；演（角色）。jouer à + 游戏/球类（jouer au foot）；jouer de + 乐器（jouer de la guitare）。","ipa":"[ʒwe]","ph":"j [ʒ]；ou 在元音前读 [w]；-er 读 [e]。","pi":"jouer à（球类、游戏）和 jouer de（乐器）介词不同，容易混；ou+er 连读成 [ʒwe]，只有一个音节。","et":"拉丁语 iocari（开玩笑，嬉戏），来自 iocus（玩笑）。同源：jeu（游戏）、joie。","ex":[["J'aime jouer.","我爱玩。"],["Les enfants jouent dans le jardin.","孩子们在花园里玩。"],["Il joue de la guitare.","他弹吉他。"]],"co":[["jouer au football / au tennis","踢足球 / 打网球"],["jouer de la guitare / du piano","弹吉他 / 弹钢琴"],["jouer aux cartes","打牌"],["jouer un rôle","扮演角色"]],"sy":[["s'amuser","courant","玩得开心"],["interpréter","soutenu","演绎，演奏"]],"fq":"极高频，日常常用。","me":"jouer ← iocus（玩笑）：jeu、joie 都是它的亲戚。","tr":{"zh":"孩子们在公园里踢足球。","fr":"Les enfants jouent au football dans le parc.","alt":"Les enfants jouent au foot au parc.","note":"jouer à + 定冠词 + 球类（au = à + le）。"}},
 "Nettoyer": {"pos":"v. 动词，第一组 -oyer，助动词 avoir","s":"打扫；清洁；洗干净（房间、桌子、伤口、屏幕等）。比 laver（用水洗）更泛，也包括擦、扫、吸尘。","ipa":"[nɛ.twa.je]","ph":"ne [nɛ]；-toy- 读 [twa.j]；-er 读 [e]。","pi":"动词变位时 y 变 i：je nettoie，nous nettoyons；不要把 oy 读成 [oj]，要读 [waj]。","et":"来自 net（干净的，拉丁语 nitidus「明亮的」）加后缀 -oyer。同源：net。","ex":[["Je dois nettoyer ma chambre.","我得打扫房间。"],["Il nettoie la cuisine tous les jours.","他每天打扫厨房。"],["Nettoie la table, s'il te plaît.","请把桌子擦干净。"]],"co":[["nettoyer la maison","打扫房子"],["nettoyer à fond","彻底打扫"],["nettoyer à sec","干洗"],["le nettoyage","清洁（名词）"]],"sy":[["laver","courant","用水洗"],["ranger","courant","整理（不是清洁）"],["salir","courant","反义：弄脏"]],"fq":"高频，日常常用。","me":"net = 干净，nettoyer = 让它变得 net。","tr":{"zh":"你得把厨房打扫干净。","fr":"Tu dois nettoyer la cuisine.","alt":"Il faut que tu nettoies la cuisine.","note":"devoir + 动词原形；alt 用 il faut que + 虚拟式。"}},
 "Ouvrir": {"pos":"v. 动词，第三组不规则，变位像 -er 动词；过去分词 ouvert，助动词 avoir","s":"打开（门、窗、瓶子、盒子、网页）；开始营业。反义 fermer。j'ouvre, tu ouvres, il ouvre, nous ouvrons。","ipa":"[u.vʁiʁ]","ph":"ou [u]；v [v]；r [ʁ]；i [i]；r [ʁ]。","pi":"虽然是 -ir 结尾，现在时变位像 -er：j'ouvre，不是 j'ouvris；过去分词是 ouvert，不是 ouvri。","et":"来自拉丁语 aperire（打开），受 cooperire 影响形成 ouvrir。同源：ouvert、ouverture。","ex":[["Je vais ouvrir la porte.","我去开门。"],["Ouvre la fenêtre, il fait chaud.","把窗户打开，好热。"],["Le magasin ouvre à neuf heures.","商店九点开门。"]],"co":[["ouvrir la porte / la fenêtre","开门 / 开窗"],["ouvrir un compte","开账户"],["ouvert / ouverte","开着的（形容词）"],["ouvrir l'appétit","开胃"]],"sy":[["fermer","courant","反义：关"],["ouvert","courant","形容词：开着的，营业中"]],"fq":"极高频，日常常用。","me":"ouvrir ≈ 「呜 v ruh」：想象拉开一扇门的声音。","tr":{"zh":"请把窗户打开。","fr":"Ouvre la fenêtre, s'il te plaît.","alt":"Tu peux ouvrir la fenêtre, s'il te plaît ?","note":"tu 命令式 ouvre 不加 s。"}},
 "Respirer": {"pos":"v. 动词，第一组 -er，助动词 avoir","s":"呼吸；呼吸（新鲜空气）；松一口气。respirer profondément = 深呼吸。名词 la respiration。","ipa":"[ʁɛs.pi.ʁe]","ph":"r [ʁ]；es [ɛs]；pi [pi]；r [ʁ]；-er 读 [e]。","pi":"开头 r 和中间 r 都是喉音 [ʁ]；结尾 -er 不发 r；重音在最后。","et":"拉丁语 respirare：re-（再）+ spirare（吹气，呼吸）。同源：inspirer（吸气）、expirer（呼气）、esprit。","ex":[["Il faut respirer.","要呼吸。"],["Respire profondément.","深呼吸。"],["Je n'arrive pas à respirer.","我喘不过气来。"]],"co":[["respirer profondément","深呼吸"],["respirer l'air frais","呼吸新鲜空气"],["la respiration","呼吸"],["respirer par le nez","用鼻子呼吸"]],"sy":[["inspirer","courant","吸气"],["expirer","courant","呼气"],["souffler","courant","吹气"]],"fq":"中频，日常、运动、医疗常用。","me":"re + spir：反复吹气。esprit（精神）也来自同一个词根。","tr":{"zh":"我在山里呼吸新鲜空气。","fr":"Je respire l'air frais à la montagne.","alt":"À la montagne, je respire un bon coup d'air frais.","note":"respirer + 直接宾语，不用介词。"}},
 "Se sentir": {"pos":"v. 代动词（pronominal），第三组；复合时态助动词 être：je me suis senti(e)","s":"感觉（自己处于某种状态）。后接副词或形容词：se sentir bien / mal / fatigué / chez soi。变位：je me sens, tu te sens, il se sent, nous nous sentons。","ipa":"[sə sɑ̃.tiʁ]","ph":"se [sə]；en [ɑ̃]，n 不发音；t [t]；ir [iʁ]。","pi":"se sentir 说自己的感觉；sentir 没有 se 时多指「闻」或「感到某物」。不要漏掉 me / te / se。","et":"se + sentir；sentir 来自拉丁语 sentire（感觉）。同源：sentiment、sens。","ex":[["Je me sens bien.","我感觉很好。"],["Elle ne se sent pas très bien aujourd'hui.","她今天感觉不太舒服。"],["Tu te sens mieux ?","你感觉好点了吗？"]],"co":[["se sentir bien / mal","感觉好 / 不舒服"],["se sentir fatigué(e)","觉得累"],["se sentir chez soi","感觉像在自己家"],["se sentir seul(e)","感到孤独"]],"sy":[["aller","courant","Comment tu vas ? 问状态"],["se porter","soutenu","身体状况：il se porte bien"]],"fq":"高频，日常常用。","me":"se = 自己：「感觉自己」。","tr":{"zh":"我今天感觉有点累。","fr":"Je me sens un peu fatigué aujourd'hui.","alt":"Aujourd'hui, je suis un peu fatigué.","note":"se sentir + 形容词；女生用 fatiguée。"}},
 "Sentir": {"pos":"v. 动词，第三组不规则，助动词 avoir；je sens, nous sentons","s":"闻到；闻起来；感觉到。sentir bon / mauvais = 闻起来香 / 臭。Ça sent bon ! = 好香！","ipa":"[sɑ̃.tiʁ]","ph":"s [s]；en [ɑ̃]，n 不发音；t [t]；ir [iʁ]。","pi":"sentir（闻）和 se sentir（感觉自己）意思不同；en 是鼻化元音 [ɑ̃]。现在时 je sens，t 不出现：il sent。","et":"拉丁语 sentire（感觉）。同源：sens、sentiment、ressentir。","ex":[["Je sens une odeur bizarre !","我闻到一股怪味！"],["Ça sent bon dans la cuisine.","厨房里好香。"],["Je sens le froid sur mon visage.","我感到脸上的冷风。"]],"co":[["sentir bon / mauvais","闻起来香 / 臭"],["sentir une odeur","闻到气味"],["Ça sent le brûlé.","有烧焦味。"],["sentir la fatigue","感到疲劳"]],"sy":[["humer","soutenu","吸气闻（香气）"],["flairer","soutenu","嗅（动物或直觉）"]],"fq":"高频，日常常用。","me":"sentir 里有 sens（感觉）：用鼻子「感觉」气味。","tr":{"zh":"我闻到蛋糕的香味。","fr":"Je sens l'odeur du gâteau.","alt":"Ça sent bon le gâteau !","note":"sentir + 名词；Ça sent + 名词。"}},
 "Tousser": {"pos":"v. 动词，第一组 -er，助动词 avoir","s":"咳嗽。名词是 la toux（咳嗽），不要和动词混用。tousser fort = 咳得厉害。","ipa":"[tu.se]","ph":"t [t]；ou [u]；ss [s]；-er 读 [e]。","pi":"ss 读 [s]，不是 [z]；名词 toux 结尾 x 不发音，读 [tu]。","et":"来自拉丁语 tussire（咳嗽），与名词 toux（拉丁语 tussis）同源。","ex":[["Je n'arrête pas de tousser.","我一直在咳嗽。"],["Il tousse depuis hier.","他从昨天开始咳嗽。"],["Quand je suis enrhumé, je tousse beaucoup.","感冒时我咳得很厉害。"]],"co":[["tousser fort","咳得厉害"],["la toux","咳嗽（名词）"],["un sirop contre la toux","止咳糖浆"],["ne pas arrêter de tousser","一直咳嗽"]],"sy":[["avoir la toux","courant","咳嗽（名词说法）"],["s'éclaircir la voix","courant","清嗓子，没那么严重"]],"fq":"中频，生病、看医生时常用。","me":"tousser 的 tou- 就像 toux：声音就像咳嗽。","tr":{"zh":"他感冒了，一直咳嗽。","fr":"Il est enrhumé, il n'arrête pas de tousser.","alt":"Il a un rhume, il tousse tout le temps.","note":"ne pas arrêter de + 动词原形 = 一直……"}},
 "Utiliser": {"pos":"v. 动词，第一组 -er，助动词 avoir","s":"使用，用（工具、手机、方法、词语）。可以和 se servir de 互换；utiliser 后直接跟宾语，不加介词。","ipa":"[y.ti.li.ze]","ph":"u [y]；ti [ti]；li [li]；-ser 读 [ze]，s 在元音间读 [z]。","pi":"u 读 [y]，嘴唇撮圆，像「于」，不是 [u]；s 读 [z]；四个音节，重音在最后。","et":"来自 utile（有用的，拉丁语 utilis）加后缀 -iser。同源：utilité、inutile。","ex":[["Je vais utiliser mon téléphone.","我要用手机。"],["Tu peux utiliser mon ordinateur.","你可以用我的电脑。"],["Comment utiliser cet appareil ?","这个设备怎么用？"]],"co":[["utiliser un outil / un logiciel","使用工具 / 软件"],["le mode d'emploi","使用说明"],["l'utilisation","使用（名词）"],["facile à utiliser","容易使用"]],"sy":[["se servir de","courant","使用，后接 de"],["employer","soutenu","使用（多指方法、词语、人）"]],"fq":"高频，日常常用。","me":"utile + -iser：让它变得「有用」，就是 use。","tr":{"zh":"我可以用你的电话吗？","fr":"Je peux utiliser ton téléphone ?","alt":"Je peux me servir de ton téléphone ?","note":"utiliser + 直接宾语；se servir de 要加 de。"}},
 "Bon / Bonne": {"pos":"adj. 形容词，阴性 bonne，复数 bons / bonnes，常放在名词前","s":"好的；好吃的；正确的；合适的。C'est bon = 好吃 / 可以。比较级用 meilleur（更好），不说 plus bon。","ipa":"[bɔ̃] / [bɔn]","ph":"阳性 bon 是鼻化元音 [ɔ̃]，n 不发音；阴性 bonne 读 [bɔn]，n 发音。","pi":"「更好」是 meilleur / meilleure，不能说 plus bon；bon 是形容词，bien 是副词，不要混用。","et":"拉丁语 bonus（好的）。同源：bonbon、bonheur、bonjour。","ex":[["C'est très bon.","这个很好。"],["Cette soupe est très bonne.","这个汤很好喝。"],["Bonne journée !","祝你今天愉快！"]],"co":[["bon appétit","祝你好胃口"],["un bon repas","一顿好饭"],["bonne chance","祝你好运"],["bon marché","便宜的"]],"sy":[["bien","courant","副词或表语，不放名词前"],["délicieux","courant","非常好吃"],["mauvais","courant","反义：坏的，不好的"]],"fq":"极高频，日常常用。","me":"bon 鼻音，bonne 要发 n：加了 e 就多一个 n 的声音。","tr":{"zh":"这家餐厅的菜很好吃。","fr":"Les plats de ce restaurant sont très bons.","alt":"On mange très bien dans ce restaurant.","note":"bons 与 plats（阳性复数）一致。"}},
 "Équilibré(e)": {"pos":"adj. 形容词，阴性 équilibrée，复数 équilibrés / équilibrées","s":"均衡的；平衡的。un repas équilibré = 营养均衡的饭；也可以形容人心态稳定、不极端。","ipa":"[e.ki.li.bʁe]","ph":"é [e]；qui [ki]；li [li]；bré [bʁe]。","pi":"qui 读 [ki]，不是 [kwi]；阳性和阴性同音（équilibré / équilibrée 都读 [e.ki.li.bʁe]）。","et":"来自 équilibre（拉丁语 aequilibrium：aequus「相等」+ libra「天平」）加过去分词后缀 -é。","ex":[["C'est un repas équilibré.","这是一顿均衡的饭。"],["Elle a une alimentation équilibrée.","她的饮食很均衡。"],["Il est calme et équilibré.","他冷静而稳重。"]],"co":[["un repas équilibré","均衡的一餐"],["une alimentation équilibrée","均衡的饮食"],["un régime équilibré","均衡的饮食方案"],["en équilibre","处于平衡状态"]],"sy":[["sain","courant","健康的，更泛"],["stable","courant","稳定的"]],"fq":"中频，健康、饮食话题常用。","me":"équi-（相等）+ libre ≈ 天平两边一样重。","tr":{"zh":"我想吃得更均衡一点。","fr":"Je veux manger de façon plus équilibrée.","alt":"Je veux avoir une alimentation plus équilibrée.","note":"de façon + 形容词阴性：équilibrée 与 façon 一致。"}},
 "Inquiet / Inquiète": {"pos":"adj. 形容词，阳性 inquiet，阴性 inquiète，复数 inquiets / inquiètes","s":"担心的；不安的。être inquiet pour + 人 / de + 事；s'inquiéter 是动词「担心」。Ne t'inquiète pas ! = 别担心！","ipa":"[ɛ̃.kjɛ] / [ɛ̃.kjɛt]","ph":"in [ɛ̃]；qu [k]；iet [jɛ]；阴性 -iète 读 [jɛt]，t 发音。","pi":"阳性结尾 -t 不发音，阴性 inquiète 才发 t；注意阴性有 è。qu 读 [k]。","et":"拉丁语 inquietus：in-（否定）+ quietus（安静的）。同源：quiet 类词，inquiétude（不安）。","ex":[["Je suis inquiet.","我很担心。"],["Ma mère est inquiète pour mon examen.","我妈妈担心我的考试。"],["Ne sois pas inquiet, tout va bien.","别担心，一切都好。"]],"co":[["être inquiet pour quelqu'un","为某人担心"],["s'inquiéter","担心"],["Ne t'inquiète pas !","别担心！"],["un regard inquiet","不安的眼神"]],"sy":[["soucieux","soutenu","忧虑的"],["angoissé","courant","焦虑的，更强"],["tranquille","courant","反义：安心的"]],"fq":"中频，日常常用。","me":"in-quiet：不 quiet（不安静），心里不安。","tr":{"zh":"她很担心她的孩子。","fr":"Elle est inquiète pour son enfant.","alt":"Elle s'inquiète pour son enfant.","note":"主语是女生，inquiète 要加 e。"}},
 "Sain(e)": {"pos":"adj. 形容词，阴性 saine，复数 sains / saines","s":"健康的；有益健康的。un repas sain = 健康的饭；也可指身心状态好。sain et sauf = 平安无事。","ipa":"[sɛ̃] / [sɛn]","ph":"阳性 sain 读 [sɛ̃]，ain 是鼻化元音；阴性 saine 读 [sɛn]，n 发音。","pi":"sain 和 saint（圣的）、sein（胸）同音，都读 [sɛ̃]，写作时要看语境。","et":"拉丁语 sanus（健康的）。同源：santé、sanitaire。","ex":[["C'est un repas sain.","这是一顿健康的饭。"],["Elle mène une vie saine.","她过着健康的生活。"],["Ils sont arrivés sains et saufs.","他们平安到达了。"]],"co":[["un repas sain","健康的饭"],["une vie saine","健康的生活"],["sain et sauf","平安无事"],["sain d'esprit","神志清醒"]],"sy":[["bon pour la santé","courant","对健康有益"],["malsain","courant","反义：不健康的"]],"fq":"中频，健康、饮食话题常用。","me":"sain ← sanus ← santé：它们是一家。","tr":{"zh":"吃水果和蔬菜是健康的。","fr":"Manger des fruits et des légumes, c'est sain.","alt":"Les fruits et les légumes, c'est sain.","note":"c'est sain：泛指时用 c'est + 形容词阳性。"}},
 "Assez": {"pos":"adv. 副词，不变","s":"足够；相当（assez + 形容词 / 副词 = 挺……）。assez de + 名词 = 足够的……；en avoir assez (familier) = 受够了。","ipa":"[a.se]","ph":"a [a]；ss [s]；ez [e]，z 不发音。","pi":"结尾 -ez 读 [e]，z 不发音；assez 作「相当」时比 très 弱；assez de 后面的名词不加冠词。","et":"拉丁语 ad satis（到足够）。同源：satisfaire（使满足）。","ex":[["J'ai assez mangé, je n'ai plus faim.","我吃饱了，不饿了。"],["Il y a assez de place ?","地方够吗？"],["Ce café est assez bon.","这家咖啡挺好喝的。"]],"co":[["assez de + 名词","足够的……"],["assez grand pour + 动词","大到足以……"],["pas assez","不够"],["J'en ai assez !","我受够了！"]],"sy":[["suffisamment","soutenu","足够地，更书面"],["plutôt","courant","相当地，倾向于"],["trop","courant","反义：太多"]],"fq":"极高频，日常常用。","me":"assez 里有 sat：satisfait（满足）= 够了。","tr":{"zh":"我吃饱了，不想再吃了。","fr":"J'ai assez mangé, je ne veux plus manger.","alt":"Ça va, j'ai assez mangé.","note":"assez 放在助动词和过去分词之间。"}},
 "Avoir le nez qui coule": {"pos":"loc. verbale 动词短语，avoir 第三组不规则","s":"流鼻涕。字面「鼻子在流」。相关说法：avoir le nez bouché = 鼻塞。","ipa":"[a.vwaʁ lə ne ki kul]","ph":"avoir [a.vwaʁ]，oi 读 [wa]；nez 读 [ne]，z 不发音；qui [ki]；coule [kul]，ou 读 [u]。","pi":"nez 的 z 不发音；qui 读 [ki]，不是 [kwi]；coule 里 ou 读 [u]，不是 [o]。","et":"avoir（有）+ nez（拉丁语 nasus）+ couler（拉丁语 colare，过滤，流过）。","ex":[["J'ai le nez qui coule.","我流鼻涕。"],["Il a le nez qui coule depuis ce matin.","他从早上起就一直流鼻涕。"],["Prends un mouchoir, tu as le nez qui coule.","拿张纸巾，你在流鼻涕。"]],"co":[["avoir le nez bouché","鼻塞"],["se moucher","擤鼻涕"],["un mouchoir","纸巾，手帕"],["être enrhumé(e)","感冒了"]],"sy":[["avoir le nez bouché","courant","鼻塞，是相反的状况"],["avoir un rhume","courant","感冒了"]],"fq":"中频，生病、看医生时常用。","me":"鼻子（nez）+ 流（couler）：直译就是「我有鼻子在流」。","tr":{"zh":"孩子感冒了，流鼻涕。","fr":"L'enfant est enrhumé, il a le nez qui coule.","alt":"Le petit est malade, il a le nez qui coule.","note":"avoir le nez + qui coule：qui 引导关系从句。"}},
 "Avoir mal à ...": {"pos":"loc. verbale 动词短语，后接 à + 定冠词 + 身体部位","s":"……疼。avoir mal à la tête = 头疼。à + le = au，à + les = aux。avoir mal partout = 到处疼。","ipa":"[a.vwaʁ mal a]","ph":"avoir [a.vwaʁ]；mal [mal]，l 发音；à [a]。","pi":"身体部位前用定冠词（la / le / les），不用 ma / mon / mes：J'ai mal à la tête，不说 à ma tête。注意 au、aux 缩合。","et":"mal 来自拉丁语 malum / male（坏的）。同源：malade、malheur。","ex":[["J'ai mal à la tête.","我头疼。"],["Elle a mal au dos.","她背疼。"],["Tu as mal aux dents ?","你牙疼吗？"]],"co":[["avoir mal au ventre","肚子疼"],["avoir mal à la gorge","喉咙痛"],["avoir mal au cœur","恶心想吐（不是心痛）"],["Où as-tu mal ?","你哪里疼？"]],"sy":[["faire mal","courant","弄疼：Ça fait mal 很疼"],["souffrir","soutenu","受苦，痛苦"]],"fq":"极高频，看医生时常用。","me":"mal = 疼；到哪里疼，就用 à 连上那个部位。","tr":{"zh":"我肚子疼，想去看医生。","fr":"J'ai mal au ventre, je voudrais voir un médecin.","alt":"J'ai mal au ventre, je dois aller chez le médecin.","note":"à + le = au；à + les = aux。"}},
 "Bon pour la santé": {"pos":"loc. 形容词短语","s":"对健康有益。bon pour + 名词 = 对……有益。反义 mauvais pour la santé。À ta santé ! 是「干杯」。","ipa":"[bɔ̃ puʁ la sɑ̃.te]","ph":"bon [bɔ̃]，鼻化；pour [puʁ]；santé：an 是鼻化元音 [ɑ̃]，é 读 [e]。","pi":"santé 的 an 是鼻化元音 [ɑ̃]，n 不单独发音；bon 与 pour 之间不连读。","et":"bon ← 拉丁语 bonus；santé ← 拉丁语 sanitas（健康）。","ex":[["Le sport est bon pour la santé.","运动对健康有益。"],["Manger des légumes, c'est bon pour la santé.","吃蔬菜对健康有益。"],["Le sucre n'est pas bon pour la santé.","糖对健康不好。"]],"co":[["bon pour le moral","对心情有好处"],["être en bonne santé","身体健康"],["À ta santé !","干杯！"],["bon pour les dents","对牙齿有益"]],"sy":[["sain","courant","健康的"],["bénéfique","soutenu","有益的"],["mauvais pour la santé","courant","反义：对健康有害"]],"fq":"高频，日常常用。","me":"bon（好）+ santé（健康）：好 = 对健康好。","tr":{"zh":"多喝水对健康有益。","fr":"Boire beaucoup d'eau est bon pour la santé.","alt":"Boire de l'eau, c'est bon pour la santé.","note":"动词原形可以作主语。"}},
 "Être en forme": {"pos":"loc. verbale 动词短语，être 不规则","s":"状态好；精力充沛；身体棒。Je ne suis pas en forme = 我状态不好。la forme 也指体能状态，garder la forme = 保持好状态。","ipa":"[ɛtʁ ɑ̃ fɔʁm]","ph":"être [ɛtʁ]，ê 读 [ɛ]；en [ɑ̃]，鼻化；forme [fɔʁm]，o 读 [ɔ]，结尾 e 不发音。","pi":"être 的 ê 读 [ɛ]；en 是鼻化元音 [ɑ̃]；forme 里的 o 是开口的 [ɔ]。","et":"forme ← 拉丁语 forma（形状）。être en forme 本义「处于好形态」。","ex":[["Je veux être en forme.","我想保持好状态。"],["Tu as l'air en forme aujourd'hui !","你今天看起来状态很好！"],["Je ne suis pas en forme ce matin.","今天早上我状态不好。"]],"co":[["garder la forme","保持好状态"],["retrouver la forme","恢复状态"],["en pleine forme","状态极佳"],["la forme physique","体能状态"]],"sy":[["aller bien","courant","身体好，状态好"],["avoir la pêche","familier","很有精神"],["fatigué","courant","反义：累的"]],"fq":"高频，日常常用。","me":"en forme = 在「好形态」中。","tr":{"zh":"你今天看起来状态很好！","fr":"Tu as l'air en forme aujourd'hui !","alt":"T'as la pêche aujourd'hui !","note":"avoir l'air + 形容词 = 看起来……；alt 是口语。"}},
 "Mauvais pour la santé": {"pos":"loc. 形容词短语；mauvais 阴性 mauvaise","s":"对健康有害；不健康。mauvais 要和主语的性数一致：Les sucreries sont mauvaises pour la santé。","ipa":"[mo.vɛ puʁ la sɑ̃.te]","ph":"mauvais：au 读 [o]，ais 读 [ɛ]，s 不发音；pour [puʁ]；santé [sɑ̃.te]。","pi":"mauvais 结尾 -ais 读 [ɛ]，s 不发音；au 读 [o]，不是 [au]；阴性 mauvaise 里的 s 读 [z]。","et":"古法语 malvais，词源不完全确定；santé ← 拉丁语 sanitas。","ex":[["Fumer est mauvais pour la santé.","吸烟有害健康。"],["Dormir peu, c'est mauvais pour la santé.","睡得少对健康不好。"],["Les boissons trop sucrées sont mauvaises pour la santé.","太甜的饮料对健康有害。"]],"co":[["mauvais pour les dents","对牙齿不好"],["une mauvaise habitude","坏习惯"],["en mauvaise santé","身体不好"],["Ça fait du mal.","这对身体不好。"]],"sy":[["nocif","soutenu","有害的"],["malsain","courant","不健康的"],["bon pour la santé","courant","反义：对健康有益"]],"fq":"高频，日常常用。","me":"mauvais（坏）对 bon（好）：成对记。","tr":{"zh":"吃太多糖对健康有害。","fr":"Manger trop de sucre est mauvais pour la santé.","alt":"Trop de sucre, c'est mauvais pour la santé.","note":"trop de + 名词 = 太多……"}},
 "Prendre rendez-vous": {"pos":"loc. verbale 动词短语；prendre 第三组不规则；rendez-vous 是 n.m.，复数不变","s":"预约；约时间。prendre rendez-vous avec + 人 / chez + 医生、理发师 / pour + 时间。","ipa":"[pʁɑ̃dʁ ʁɑ̃.de.vu]","ph":"prendre：en 读 [ɑ̃]，结尾 -dre 读 [dʁ]；rendez：en [ɑ̃]，-ez [e]，z 不发音；vous [vu]。","pi":"prendre 中的 en 是鼻化元音 [ɑ̃]，不读 [ɛn]；rendez-vous 的 -z、-s 不发音；复数 des rendez-vous 不加 s。","et":"prendre ← 拉丁语 prehendere（抓住）；rendez-vous 原为命令式「请到场」（se rendre「前往」）。","ex":[["Je vais prendre rendez-vous.","我要去预约。"],["Je voudrais prendre rendez-vous chez le dentiste.","我想预约看牙医。"],["Elle a pris rendez-vous pour mardi à 14 h.","她约了星期二下午两点。"]],"co":[["prendre rendez-vous chez le médecin","预约看医生"],["avoir rendez-vous avec quelqu'un","和某人有约"],["annuler un rendez-vous","取消预约"],["un rendez-vous","约会，预约（n.m.）"]],"sy":[["réserver","courant","预订（餐厅、房间）"],["fixer un rendez-vous","courant","定下约会时间"]],"fq":"高频，生活办事常用。","me":"prendre rendez-vous = 把一个约会「拿到手」。","tr":{"zh":"我想预约明天下午的时间。","fr":"Je voudrais prendre rendez-vous demain après-midi.","alt":"Je peux prendre rendez-vous pour demain après-midi ?","note":"prendre rendez-vous pour + 时间。"}},
 "Le ciel": {"pos":"n.m. 阳性名词，复数 cieux（书面、宗教）或 ciels（画中的天空）","s":"天空；天。日常复数很少用。le ciel est bleu / gris / dégagé / couvert 是描述天气的常用句。","ipa":"[sjɛl]","ph":"c 在 i 前读 [s]；ie 读 [jɛ]；l 发音。","pi":"ci 读 [sj]；结尾 l 要发音；不要读成 [si.ɛl] 两个音节，只有一个音节 [sjɛl]。","et":"拉丁语 caelum（天空）。同源：céleste（天上的）。","ex":[["Le ciel est bleu aujourd'hui.","今天天空是蓝色的。"],["Il y a des nuages dans le ciel.","天空中有云。"],["Regarde le ciel : il va pleuvoir.","看看天空：要下雨了。"]],"co":[["un ciel bleu / gris","蓝天 / 灰蒙蒙的天"],["un ciel étoilé","繁星满天的夜空"],["le ciel est dégagé","天空晴朗"],["à ciel ouvert","露天的"]],"sy":[["firmament","littéraire","苍穹"],["paradis","courant","天堂（宗教）"]],"fq":"极高频，日常常用。","me":"ciel ← caelum：céleste（天上的）是它的亲戚。","tr":{"zh":"天空很蓝，没有云。","fr":"Le ciel est bleu, il n'y a pas de nuages.","alt":"Il n'y a pas un nuage dans le ciel.","note":"il n'y a pas de + 名词。"}},
 "Le départ": {"pos":"n.m. 阳性名词，复数 départs","s":"出发；启程；开始。le départ du train = 火车发车；au départ = 一开始；le point de départ = 起点。反义 l'arrivée。","ipa":"[de.paʁ]","ph":"dé [de]；part [paʁ]，t 不发音，r 发音。","pi":"结尾 -t 不发音，但 r 要发 [ʁ]；注意 é 有重音符号：départ。","et":"是 partir（出发）的名词形，前缀 dé-；同族词：partir、repartir。","ex":[["Le départ est prévu demain.","出发定在明天。"],["Le départ du train est à huit heures.","火车八点发车。"],["Au départ, je ne voulais pas venir.","一开始我不想来。"]],"co":[["l'heure de départ","出发时间"],["au départ","一开始"],["le point de départ","起点"],["prendre le départ","出发，起跑"]],"sy":[["l'arrivée","courant","反义：到达"],["le début","courant","开始，更泛"]],"fq":"高频，旅行常用。","me":"départ ← partir：d + part，有 part 就有「走」。","tr":{"zh":"火车的出发时间是九点。","fr":"L'heure de départ du train est à neuf heures.","alt":"Le train part à neuf heures.","note":"l'heure de départ：名词连用不加冠词。"}},
 "Le/la wifi": {"pos":"n.m.（也常见 n.f.），常写作 wifi 或 wi-fi","s":"无线网络。官方推荐阳性 le wifi，口语里也有人说 la wifi。常用于酒店、咖啡馆等场所。","ipa":"[wi.fi]","ph":"w 读 [w]；两个 i 都读 [i]；f [f]。","pi":"w 读 [w]，不是 [v]；性别不固定，日常以 le wifi 为主。","et":"借自英语 Wi-Fi（1999 年起的商标名）。","ex":[["Le wifi ne marche pas.","Wi-Fi 不能用。"],["Quel est le mot de passe du wifi ?","Wi-Fi 密码是什么？"],["Il n'y a pas de wifi dans la chambre.","房间里没有 Wi-Fi。"]],"co":[["se connecter au wifi","连上 Wi-Fi"],["le mot de passe du wifi","Wi-Fi 密码"],["du wifi gratuit","免费的 Wi-Fi"],["une borne wifi","Wi-Fi 热点"]],"sy":[["internet","courant","网络，更泛"],["le réseau","courant","网络"]],"fq":"高频，旅行日常常用。","me":"wifi 和英语一样，只要念成 [wi.fi]。","tr":{"zh":"酒店有免费的无线网。","fr":"L'hôtel a du wifi gratuit.","alt":"Il y a du wifi gratuit à l'hôtel.","note":"du wifi：部分冠词，表示「一些」。"}},
 "Un arbre": {"pos":"n.m. 阳性名词，复数 arbres","s":"树。arbre généalogique = 家谱；arbre de Noël = 圣诞树。比 plante 更具体，指有树干的树。","ipa":"[aʁbʁ]","ph":"a [a]；rb [ʁb]；r [ʁ]；结尾 e 不发。un arbre 要连读成 [œ̃.naʁbʁ]。","pi":"-bre 读 [bʁ]，结尾 e 不发；两个 r 都是喉音；un 和 arbre 之间要连读 n。","et":"拉丁语 arbor（树）。","ex":[["Cet arbre est très grand.","这棵树很高。"],["Les oiseaux dorment dans l'arbre.","鸟睡在树上。"],["Nous mangeons sous un arbre.","我们在树下吃饭。"]],"co":[["planter un arbre","种一棵树"],["grimper à un arbre","爬树"],["un arbre fruitier","果树"],["un arbre généalogique","家谱"]],"sy":[["arbuste","courant","灌木"],["forêt","courant","森林（很多树）"]],"fq":"高频，日常常用。","me":"arbre ← arbor：想想英语 arbor。","tr":{"zh":"孩子们在树下玩。","fr":"Les enfants jouent sous l'arbre.","alt":"Les enfants s'amusent sous un arbre.","note":"sous + 名词 = 在……下面。"}},
 "Un bateau": {"pos":"n.m. 阳性名词，复数 bateaux（-eau 的复数加 x）","s":"船。泛指各种船，口语中最常用。en bateau = 坐船；bateau de pêche = 渔船。mener en bateau (familier) = 骗人。","ipa":"[ba.to]","ph":"b [b]；a [a]；eau 读 [o]；t 不发音。","pi":"复数是 bateaux，不是 bateaus；eau 读 [o]，结尾 u 不发音。","et":"古法语 batel，来源有争议（常认为与古英语 bāt 有关）。","ex":[["Le bateau est sur l'eau.","船在水上。"],["Nous traversons le lac en bateau.","我们坐船过湖。"],["Ils ont un petit bateau de pêche.","他们有一条小渔船。"]],"co":[["prendre le bateau","坐船"],["aller en bateau","乘船去"],["un bateau à voile","帆船"],["un bateau à moteur","机动船"]],"sy":[["navire","soutenu","大船，海船"],["barque","courant","小船，划艇"]],"fq":"高频，旅行常用。","me":"bateau 与英语 boat 声音相近。","tr":{"zh":"我们坐船去小岛。","fr":"Nous allons sur l'île en bateau.","alt":"On prend le bateau pour aller sur l'île.","note":"en bateau 表示交通方式，与 en voiture 同理。"}},
 "Un camping": {"pos":"n.m. 阳性名词，复数 campings","s":"露营地；也指露营这项活动。le camping = 营地（地点）；faire du camping = 去露营。注意：不是「帐篷」，帐篷是 une tente。","ipa":"[kɑ̃.piŋ]","ph":"c [k]；am [ɑ̃]，鼻化；p [p]；ing 读 [iŋ]，g 是鼻音 [ŋ]。","pi":"am 是鼻化元音 [ɑ̃]，不读 [am]；-ing 读 [iŋ]，借自英语；一定是「营地」而不是「露营这件事」。","et":"借自英语 camping（camp 的 -ing 形式）；camp 与 champ、campus 同源（拉丁语 campus）。","ex":[["L'été, nous allons au camping.","夏天我们去露营。"],["Il y a un grand camping près du lac.","湖边有一个大露营地。"],["Ils font du camping en montagne.","他们在山里露营。"]],"co":[["faire du camping","去露营"],["aller au camping","去露营地"],["planter la tente","搭帐篷"],["un camping-car","房车"]],"sy":[["camp","courant","营地（多指军营、夏令营）"],["bivouac","soutenu","野外露营"]],"fq":"中频，旅行假期常用。","me":"camping 与英语一样，但法语里首先指「营地」。","tr":{"zh":"我们在湖边的露营地过夜。","fr":"Nous passons la nuit dans un camping au bord du lac.","alt":"On dort dans un camping près du lac.","note":"dans un camping / au camping。"}},
 "Un canard": {"pos":"n.m. 阳性名词，复数 canards；母鸭 une cane","s":"鸭子。une cane 是母鸭，un caneton 是小鸭。口语里 un canard 也指小报、假消息。","ipa":"[ka.naʁ]","ph":"c [k]；a [a]；n [n]；ard 读 [aʁ]，d 不发音。","pi":"结尾 -d 不发音，但 r 要发；不要读成 canar 后面的 d。","et":"可能来自拟声（模仿鸭子叫声）；确切来源不完全确定。","ex":[["Le canard nage dans l'eau.","鸭子在水里游。"],["Les enfants donnent du pain aux canards.","孩子们给鸭子喂面包。"],["Un canard et deux oies sont au bord de l'étang.","一只鸭子和两只鹅在池塘边。"]],"co":[["un canard laqué","烤鸭"],["une mare aux canards","鸭塘"],["un caneton","小鸭"],["une cane","母鸭"]],"sy":[["cane","courant","母鸭"],["oie","courant","鹅（别混）"]],"fq":"中频，农场、动物话题常用。","me":"canard 开头 can-，想想 quack 的叫声 coin-coin。","tr":{"zh":"池塘里有三只鸭子。","fr":"Il y a trois canards dans l'étang.","alt":"Trois canards nagent dans l'étang.","note":"il y a + 数量 + 名词。"}},
 "Un car": {"pos":"n.m. 阳性名词，复数 cars","s":"长途大巴（旅游大巴、城际客车），比市内公交 bus 大，跑得更远。注意：car 另有连词义「因为」（书面）；汽车是 une voiture，不是 un car。","ipa":"[kaʁ]","ph":"c [k]；a [a]；r 发音 [ʁ]。","pi":"和英语 car（汽车）是假朋友，法语 car 是大巴；r 要发 [ʁ]，不要省略。","et":"autocar 的缩写（auto- + car）。","ex":[["Un car est un bus longue distance.","长途大巴是远距离的公交车。"],["Nous allons à Lyon en car.","我们坐大巴去里昂。"],["Le car part à neuf heures.","大巴九点出发。"]],"co":[["prendre le car","坐长途大巴"],["un car scolaire","校车"],["un car de touristes","旅游大巴"],["en car","坐大巴"]],"sy":[["autocar","courant","car 的全称"],["bus","courant","市内公交"],["autobus","soutenu","公交车全称"]],"fq":"中频，旅行常用。","me":"car 在法语里 = 大巴，不是汽车（voiture）。","tr":{"zh":"我们坐大巴去山里。","fr":"Nous allons à la montagne en car.","alt":"On prend le car pour aller à la montagne.","note":"en car = 乘大巴；car ≠ voiture。"}},
 "Un champ": {"pos":"n.m. 阳性名词，复数 champs","s":"田野；田地。引申为「领域」：champ de vision（视野）、champ d'action（活动范围）。","ipa":"[ʃɑ̃]","ph":"ch [ʃ]；amp 读 [ɑ̃]，m 和 p 都不发音。","pi":"结尾 -mp 不发音；与 chant（歌）同音 [ʃɑ̃]；拼写要记住 champ。","et":"拉丁语 campus（平地，田野）。同源：camp、camping、campagne。","ex":[["Le tracteur est dans le champ.","拖拉机在田里。"],["Les vaches sont dans le champ.","牛在田里。"],["Il travaille dans les champs.","他在田里干活。"]],"co":[["un champ de blé","麦田"],["un champ de tournesols","向日葵田"],["à travers champs","穿过田野"],["le champ de vision","视野"]],"sy":[["pré","courant","草地，牧场"],["terrain","courant","场地，土地"]],"fq":"中频，乡村话题常用。","me":"champ ← campus：和 camp、camping 是亲戚。","tr":{"zh":"农民在田里干活。","fr":"Le paysan travaille dans le champ.","alt":"L'agriculteur est dans son champ.","note":"dans le champ / dans les champs。"}},
 "Un chemin": {"pos":"n.m. 阳性名词，复数 chemins","s":"小路；路；路线。比 route（公路）窄，比 sentier（小径）宽。en chemin = 在路上；demander son chemin = 问路。","ipa":"[ʃə.mɛ̃]","ph":"ch [ʃ]；e 弱读 [ə]；in 读 [ɛ̃]，n 不发音。","pi":"in 是鼻化元音 [ɛ̃]，不读 [in]；e 在口语里常被吞掉，说成 [ʃmɛ̃]。","et":"晚期拉丁语 caminus（据说源自高卢语）。同源：cheminée、cheminer。","ex":[["Nous marchons sur le chemin.","我们在小路上走。"],["Quel est le chemin pour aller à la gare ?","去火车站怎么走？"],["En chemin, j'ai vu un lapin.","路上我看到一只兔子。"]],"co":[["demander son chemin","问路"],["en chemin / sur le chemin de","在去……的路上"],["un chemin de fer","铁路"],["un chemin de randonnée","徒步小路"]],"sy":[["route","courant","公路"],["sentier","courant","小径，更窄"],["rue","courant","街道"]],"fq":"高频，日常常用。","me":"chemin 与 cheminée 同族：都和「走的路径」有关。","tr":{"zh":"这条小路通向村子。","fr":"Ce chemin mène au village.","alt":"Ce chemin va jusqu'au village.","note":"mener à = 通向。"}},
 "Un cheval": {"pos":"n.m. 阳性名词，复数 chevaux（不是 chevals）","s":"马。faire du cheval / monter à cheval = 骑马。母马 une jument，小马 un poulain。","ipa":"[ʃə.val]","ph":"ch [ʃ]；e 弱读 [ə]；val [val]，l 发音。","pi":"复数是 chevaux [ʃə.vo]，规则同 journal → journaux；el 结尾的 l 要发音。","et":"拉丁语 caballus（驽马）。同源：chevalier、chevaucher、cavalerie。","ex":[["Elle monte sur un cheval.","她骑在马上。"],["Ils font du cheval à la campagne.","他们在乡下骑马。"],["Les chevaux courent dans le pré.","马在草地上跑。"]],"co":[["monter à cheval","骑马"],["faire du cheval","骑马（活动）"],["à cheval","骑着马"],["une course de chevaux","赛马"]],"sy":[["jument","courant","母马"],["poney","courant","矮种马"],["étalon","soutenu","种马"]],"fq":"中频，动物、乡村话题常用。","me":"cheval → chevalier：骑马的人。","tr":{"zh":"她每个周末都骑马。","fr":"Elle fait du cheval tous les week-ends.","alt":"Elle monte à cheval chaque week-end.","note":"faire du cheval / monter à cheval。"}},
 "Un hébergement": {"pos":"n.m. 阳性名词，复数 hébergements","s":"住宿；落脚处（酒店、民宿、青旅、露营地等的总称）。偏正式，旅游用语；口语更常说 logement。动词 héberger = 供……住宿。","ipa":"[e.bɛʁ.ʒə.mɑ̃]","ph":"h 不发音；é [e]；ber [bɛʁ]；ge [ʒə]；ment [mɑ̃]。","pi":"h 不发音（哑 h），所以 l'hébergement 要省音；-ment 读 [mɑ̃]；g 在 e 前读 [ʒ]。","et":"héberger 来自法兰克语 *heriberga（军队的住处），同源：英语 harbor，德语 Herberge。","ex":[["Cet hébergement est très confortable.","这个住所很舒服。"],["Nous cherchons un hébergement pas cher.","我们在找便宜的住宿。"],["L'hébergement est compris dans le prix.","住宿包含在价格里。"]],"co":[["trouver un hébergement","找住宿"],["un hébergement touristique","旅游住宿"],["héberger un ami","让朋友借住"],["l'hébergement et la restauration","住宿与餐饮"]],"sy":[["logement","courant","住处，更日常"],["gîte","courant","乡村度假屋"],["hôtel","courant","酒店"]],"fq":"中频，旅行预订常用。","me":"héberger ≈ 英语 harbor：提供停泊的港湾。","tr":{"zh":"我们需要找一个便宜的住宿。","fr":"Nous devons trouver un hébergement pas cher.","alt":"On doit trouver un hébergement pas cher.","note":"pas cher 放在名词后，不变形。"}},
 "Un hôtel": {"pos":"n.m. 阳性名词，复数 hôtels","s":"酒店；旅馆。注意：hôtel de ville 是「市政厅」，不是酒店。hôtel particulier = 大宅邸。","ipa":"[o.tɛl]","ph":"h 不发音；ô [o]；tel 读 [tɛl]，l 发音。","pi":"h 不发音，un hôtel 要连读 [œ̃.no.tɛl]；ô 带扇形符，读 [o]；l 要发音。","et":"古法语 hostel ← 拉丁语 hospitale（待客之所）；s 变成 ô。同源：hôpital、hôte。","ex":[["Nous dormons dans un hôtel.","我们住在酒店里。"],["L'hôtel est près de la gare.","酒店在火车站附近。"],["Je réserve une chambre d'hôtel.","我订一间酒店房间。"]],"co":[["réserver une chambre d'hôtel","订酒店房间"],["un hôtel de luxe","豪华酒店"],["un hôtel trois étoiles","三星酒店"],["l'hôtel de ville","市政厅"]],"sy":[["auberge","courant","小旅店"],["résidence","courant","公寓式住宿"]],"fq":"高频，旅行常用。","me":"hôtel ← hospitale：hôpital 和 hôtel 是亲戚。","tr":{"zh":"酒店离火车站很近。","fr":"L'hôtel est très près de la gare.","alt":"L'hôtel est juste à côté de la gare.","note":"près de + 名词。"}},
 "Un lac": {"pos":"n.m. 阳性名词，复数 lacs","s":"湖。au bord du lac = 在湖边。le lac Léman = 莱芒湖（日内瓦湖）。","ipa":"[lak]","ph":"l [l]；a [a]；c 在结尾读 [k]。","pi":"结尾 c 要发 [k]；不要和 la（阴性定冠词）混淆。","et":"拉丁语 lacus（湖）。","ex":[["Nous nous baignons dans le lac.","我们在湖里游泳。"],["Il y a un grand lac près de la ville.","城市附近有一个大湖。"],["En hiver, le lac est gelé.","冬天湖面结冰。"]],"co":[["au bord du lac","在湖边"],["un lac de montagne","山间湖泊"],["le lac Léman","莱芒湖"],["faire le tour du lac","绕湖一圈"]],"sy":[["étang","courant","池塘"],["mer","courant","海"],["rivière","courant","河"]],"fq":"中频，自然、旅行常用。","me":"lac 读 [lak]，像 lac 加上一个 k 的声音。","tr":{"zh":"湖水很清。","fr":"L'eau du lac est très claire.","alt":"L'eau du lac est limpide.","note":"du lac = de + le lac。"}},
 "Un lapin": {"pos":"n.m. 阳性名词，复数 lapins；母兔 une lapine","s":"兔子（家兔）。野兔是 un lièvre。poser un lapin à quelqu'un (familier) = 放某人鸽子。","ipa":"[la.pɛ̃]","ph":"l [l]；a [a]；p [p]；in 读 [ɛ̃]。","pi":"in 读 [ɛ̃]，不读 [in]；n 不发音；p 要发音。","et":"来源不确定。派生词：lapereau（小兔），lapine（母兔）。","ex":[["Le lapin court vite.","兔子跑得很快。"],["Le lapin mange une carotte.","兔子在吃胡萝卜。"],["Il m'a posé un lapin hier soir.","他昨晚放了我鸽子。"]],"co":[["poser un lapin à quelqu'un","放某人鸽子"],["un lapin blanc","白兔"],["une patte de lapin","兔脚"],["une cage à lapins","兔笼"]],"sy":[["lièvre","courant","野兔，更大跑得更快"],["lapereau","courant","小兔"]],"fq":"中频，动物话题常用。","me":"lapin = la + pin：想象「一只兔子在松树（pin）下」。","tr":{"zh":"兔子在草地上吃草。","fr":"Le lapin mange de l'herbe dans le pré.","alt":"Le lapin broute l'herbe dans le pré.","note":"manger de l'herbe：部分冠词。"}},
 "Un lit simple/double": {"pos":"n.m. 阳性名词，复数 lits；simple / double 修饰 lit，位于名词后","s":"单人床 / 双人床。lit simple 睡一个人，lit double 睡两个人。相关：lits jumeaux = 两张并排的单人床；lits superposés = 双层床。","ipa":"[li sɛ̃pl] / [li dubl]","ph":"lit：t 不发音，读 [li]；simple：im 读 [ɛ̃]，结尾 -ple 读 [pl]；double：ou [u]，结尾 -ble 读 [bl]。","pi":"lit 的 t 不发音；simple 里的 im 是鼻化元音 [ɛ̃]，不读 [im]；aller au lit 要用 au。","et":"lit ← 拉丁语 lectus（床）。","ex":[["Je voudrais une chambre avec un lit double.","我想要一间双人床的房间。"],["Les enfants dorment dans des lits superposés.","孩子们睡在双层床上。"],["Je vais au lit, je suis fatigué.","我去睡觉了，我累了。"]],"co":[["faire le lit","铺床"],["aller au lit","去睡觉"],["des lits jumeaux","两张并排的单人床"],["un lit superposé","双层床"]],"sy":[["couchage","courant","床位"],["couchette","courant","火车卧铺"]],"fq":"高频，酒店、住宿常用。","me":"lit 读 [li]：t 沉默，就像「李」。","tr":{"zh":"我想订一间有两张单人床的房间。","fr":"Je voudrais réserver une chambre avec deux lits simples.","alt":"Une chambre avec des lits jumeaux, s'il vous plaît.","note":"lits simples 复数；lits jumeaux 是两张并排的单人床。"}},
 "Un logement": {"pos":"n.m. 阳性名词，复数 logements","s":"住处；住房（公寓、房子等居住空间的总称）。le logement 也指「住房问题」。logement social = 社会保障房。","ipa":"[lɔʒ.mɑ̃]","ph":"lo [lɔ]；ge [ʒ]；ment [mɑ̃]；中间的 e 不读。","pi":"中间的 e 不发音：[lɔʒ.mɑ̃]，不是 [lɔ.ʒə.mɑ̃]；-ment 读鼻化的 [mɑ̃]。","et":"由动词 loger + -ment 构成；loger 来自法兰克语 *laubja（凉亭，小屋），同源：英语 lodge。","ex":[["Je cherche un logement pour ce soir.","我想找今晚的住处。"],["Les logements sont chers à Paris.","巴黎的住房很贵。"],["Elle a un petit logement près du centre.","她在市中心附近有一间小住所。"]],"co":[["chercher un logement","找住处"],["un logement social","社会保障房"],["un logement étudiant","学生住所"],["changer de logement","换住处"]],"sy":[["hébergement","courant","旅游语境下的住宿"],["appartement","courant","公寓"],["domicile","soutenu","住所（行政用语）"]],"fq":"高频，生活常用。","me":"loger + -ment：「住」这个动作的结果就是 logement。","tr":{"zh":"我在找离学校近的住处。","fr":"Je cherche un logement près de l'école.","alt":"Je cherche un logement pas loin de l'école.","note":"près de + 名词。"}},
 "Un oiseau": {"pos":"n.m. 阳性名词，复数 oiseaux","s":"鸟。drôle d'oiseau (familier) = 怪人。常用动词：voler（飞）、chanter（鸣叫）。","ipa":"[wa.zo]","ph":"oi [wa]；s 夹在元音间读 [z]；eau [o]。","pi":"oi 读 [wa]，s 读 [z]，不是 [s]；复数 oiseaux，不是 oiseaus；拼写较长，注意 o-i-s-e-a-u。","et":"拉丁语 avicellus（avis「鸟」的指小词），经古法语 oisel 演变而来。","ex":[["L'oiseau vole dans le ciel.","鸟在天空飞。"],["Un oiseau chante sur le toit.","一只鸟在屋顶上唱歌。"],["J'entends des oiseaux le matin.","早上我听到鸟叫。"]],"co":[["un nid d'oiseau","鸟巢"],["chanter comme un oiseau","唱得像鸟一样好"],["à vol d'oiseau","直线距离"],["un oiseau rare","稀有的鸟，难得的人"]],"sy":[["volatile","soutenu","禽类，家禽"],["moineau","courant","麻雀"]],"fq":"高频，自然话题常用。","me":"oi-seau：oi = 哇 [wa]，一只「哇哇」叫的鸟。","tr":{"zh":"早上我听到鸟叫。","fr":"Le matin, j'entends chanter les oiseaux.","alt":"Le matin, j'entends les oiseaux chanter.","note":"entendre + 名词 + 动词原形。"}},
 "Un parking": {"pos":"n.m. 阳性名词，复数 parkings","s":"停车场。une place de parking = 车位。比 garage（车库）更开放。","ipa":"[paʁ.kiŋ]","ph":"par [paʁ]；king 读 [kiŋ]，g 是鼻音 [ŋ]。","pi":"-ing 读 [iŋ]；r 要发 [ʁ]；虽然来自英语，法语里 parking 指「停车场」。","et":"借自英语 parking（park 的 -ing 形式）。","ex":[["Ma voiture est dans le parking.","我的车在停车场。"],["Il n'y a plus de place dans le parking.","停车场已经没有位置了。"],["Le parking est gratuit le dimanche.","停车场星期天免费。"]],"co":[["une place de parking","车位"],["un parking souterrain","地下停车场"],["un parking payant","收费停车场"],["se garer au parking","把车停在停车场"]],"sy":[["stationnement","soutenu","停车（行为）"],["garage","courant","车库"]],"fq":"高频，日常、旅行常用。","me":"parking = 英语 park + ing：停车的地方。","tr":{"zh":"停车场在酒店后面。","fr":"Le parking est derrière l'hôtel.","alt":"Le parking se trouve derrière l'hôtel.","note":"derrière + 名词。"}},
 "Un poisson": {"pos":"n.m. 阳性名词，复数 poissons","s":"鱼。Poissons（大写、复数）是双鱼座。poisson d'avril = 愚人节玩笑。","ipa":"[pwa.sɔ̃]","ph":"oi [wa]；ss [s]；on [ɔ̃]，n 不发音。","pi":"poisson 双 s 读 [s]，poison（毒）单 s 读 [z]，只差一个字母！","et":"拉丁语 piscis（鱼），通俗拉丁语 piscionem。同源：Pisces（双鱼座）、piscine（游泳池）。","ex":[["Le poisson nage dans le lac.","鱼在湖里游。"],["Je mange du poisson le vendredi.","我星期五吃鱼。"],["Le poisson rouge est dans l'aquarium.","金鱼在鱼缸里。"]],"co":[["un poisson rouge","金鱼"],["manger du poisson","吃鱼"],["une poissonnerie","鱼店"],["poisson d'avril","愚人节玩笑"]],"sy":[["poiscaille","familier","鱼，口语俗称"],["fruits de mer","courant","海鲜（不含鱼）"]],"fq":"高频，饮食、动物话题常用。","me":"poisson（鱼）双 s，poison（毒）单 s：鱼更多。","tr":{"zh":"我不吃鱼，我更爱吃肉。","fr":"Je ne mange pas de poisson, je préfère la viande.","alt":"Le poisson, ce n'est pas pour moi, je préfère la viande.","note":"ne... pas de + 名词：否定后用 de。"}},
 "Un souvenir": {"pos":"n.m. 阳性名词，复数 souvenirs","s":"回忆；纪念品。动词形式 se souvenir de = 记得。一个词两个意思：看语境，souvenir de voyage = 旅行纪念品。","ipa":"[suv.niʁ]","ph":"sou [su]；ve 的 e 常省略，说成 [suv.niʁ]；ir 读 [iʁ]。","pi":"名词 souvenir 与动词 se souvenir 同形；ou 读 [u]；结尾 r 要发。","et":"来自拉丁语 subvenire「浮现在脑中」，动词 se souvenir 的名词化。","ex":[["J'ai de très bons souvenirs de vacances.","我有很多度假的美好回忆。"],["Je rapporte un souvenir de Paris.","我从巴黎带回一份纪念品。"],["Ce souvenir me fait sourire.","这段回忆让我微笑。"]],"co":[["un souvenir d'enfance","童年回忆"],["un magasin de souvenirs","纪念品店"],["en souvenir de","为纪念……"],["garder un bon souvenir","留下美好的回忆"]],"sy":[["mémoire","courant","记忆（能力）"],["cadeau","courant","礼物"]],"fq":"高频，旅行常用。","me":"sou-venir：「从下面来」，记忆浮上来。","tr":{"zh":"我对这次旅行有美好的回忆。","fr":"J'ai un très bon souvenir de ce voyage.","alt":"Je garde un super souvenir de ce voyage.","note":"souvenir de + 名词。"}},
 "Un van": {"pos":"n.m. 阳性名词，复数 vans","s":"面包车；改装的露营车（van aménagé）。多用于旅行和 vanlife 话题。比 camping-car（房车）小。","ipa":"[vɑ̃n]","ph":"v [v]；an 读 [ɑ̃]；n 通常也发出来，读 [vɑ̃n]。","pi":"van 的 n 通常发出来 [vɑ̃n]，要和 vent [vɑ̃]（风）区分；v 读 [v]。","et":"借自英语 van（caravan 的缩略）。","ex":[["Nous partons voyager en van.","我们开面包车去旅行。"],["Ils dorment dans leur van.","他们睡在自己的面包车里。"],["Il a acheté un van aménagé.","他买了一辆改装的面包车。"]],"co":[["voyager en van","开面包车旅行"],["un van aménagé","改装面包车"],["vivre en van","住在面包车里"],["partir en van","开面包车出发"]],"sy":[["camping-car","courant","房车，更大"],["camionnette","courant","小货车"],["fourgon","courant","厢式货车"]],"fq":"中频，旅行话题常见。","me":"van 和英语一样，直接借词。","tr":{"zh":"夏天我们开改装面包车去旅行。","fr":"L'été, nous voyageons en van aménagé.","alt":"En été, on voyage en van aménagé.","note":"en van 表示交通方式。"}},
 "Un village": {"pos":"n.m. 阳性名词，复数 villages","s":"村庄；村子。比 ville（城市）小，比 hameau（小村落）大。les villageois = 村民。","ipa":"[vi.laʒ]","ph":"v [v]；i [i]；lage 读 [laʒ]，g 在 e 前读 [ʒ]，结尾 e 不发。","pi":"-age 读 [aʒ]，结尾 e 不发音；village 是阳性（-age 结尾多为阳性）。","et":"拉丁语 villaticum（村庄的），来自 villa（庄园）。","ex":[["Mon grand-père habite dans un petit village.","我爷爷住在小村庄里。"],["Le village est très calme.","村子很安静。"],["Il y a une petite église dans le village.","村里有一座小教堂。"]],"co":[["un petit village","小村庄"],["un village de montagne","山村"],["les habitants du village","村民"],["un village de vacances","度假村"]],"sy":[["hameau","soutenu","小村落"],["bourg","soutenu","集镇"],["ville","courant","城市"]],"fq":"高频，乡村话题常用。","me":"village ← villa：英语 village、villa 同源。","tr":{"zh":"我们去山里的一个小村庄。","fr":"Nous allons dans un petit village de montagne.","alt":"On va dans un petit village à la montagne.","note":"dans un village / au village。"}},
 "De l'herbe": {"pos":"n.f. 阴性名词，复数 herbes；de l' 是部分冠词（表示「一些草」）","s":"草；草地。les herbes = 香草、药草（herbes de Provence）。口语里 l'herbe 也可指大麻（俚语）。","ipa":"[ɛʁb]","ph":"h 不发音；er [ɛʁ]；b [b]；结尾 e 不发。","pi":"h 不发音（哑 h），所以是 l'herbe，不是 la herbe；阴性名词，une herbe。","et":"拉丁语 herba（草）。同源：英语 herb。","ex":[["L'herbe est verte.","草是绿的。"],["Les vaches mangent de l'herbe.","牛在吃草。"],["Ne marche pas sur l'herbe.","不要踩草地。"]],"co":[["de l'herbe fraîche","新鲜的草"],["tondre l'herbe","割草"],["les herbes aromatiques","香料草"],["une mauvaise herbe","杂草"]],"sy":[["gazon","courant","草坪"],["pelouse","courant","草坪"],["foin","courant","干草"]],"fq":"中频，自然话题常用。","me":"herbe ← herba：英语 herb 的老祖宗。","tr":{"zh":"孩子们坐在草地上。","fr":"Les enfants sont assis sur l'herbe.","alt":"Les enfants sont assis dans l'herbe.","note":"assis = 坐着（状态）。"}},
 "L'Alsace": {"pos":"n.f. 阴性专有名词（法国东北部地区名）","s":"阿尔萨斯，法国东北部与德国接壤的地区，现属 Grand Est 大区，首府斯特拉斯堡。以葡萄酒、choucroute 和圣诞市场闻名。","ipa":"[al.zas]","ph":"A-l-sace：ls 中的 s 读 [z]；结尾 -ce 读 [s]。","pi":"Alsace 中间的 s 读 [z]，不是 [s]；A 开头所以要省音 l'Alsace；表示「在阿尔萨斯」用 en Alsace。","et":"来源有争议：日耳曼语 Elsass，拉丁化为 Alsatia；确切含义不确定。","ex":[["L'Alsace est une région de France.","阿尔萨斯是法国的一个大区。"],["Strasbourg est la plus grande ville d'Alsace.","斯特拉斯堡是阿尔萨斯最大的城市。"],["En Alsace, on boit du vin blanc.","在阿尔萨斯，人们喝白葡萄酒。"]],"co":[["en Alsace","在阿尔萨斯"],["le vin d'Alsace","阿尔萨斯葡萄酒"],["un Alsacien / une Alsacienne","阿尔萨斯人"],["la route des vins d'Alsace","阿尔萨斯葡萄酒之路"]],"sy":[["la Lorraine","courant","相邻的东部地区，常一起被提到"]],"fq":"中频，旅游和饮食话题常见。","me":"Alsace → 圣诞市场、酸菜、白葡萄酒。","tr":{"zh":"我们去阿尔萨斯度假。","fr":"Nous partons en vacances en Alsace.","alt":"On part en Alsace pour les vacances.","note":"en + 阴性地名：en Alsace。"}},
 "L'arrivée": {"pos":"n.f. 阴性名词，复数 arrivées","s":"到达；抵达；终点（比赛）。反义 le départ。l'arrivée du train = 火车到站；la ligne d'arrivée = 终点线。","ipa":"[a.ʁi.ve]","ph":"a [a]；rri 读 [ʁi]（rr 只发一个 [ʁ]）；vée 读 [ve]。","pi":"双 r 只读一个 [ʁ]；结尾 -ée 读 [e]，e 不发；阴性名词，用 l'arrivée / une arrivée。","et":"arriver 来自通俗拉丁语 *arripare（靠岸），源自 ad + ripa（岸边）；-ée 是名词后缀。","ex":[["L'arrivée du train est à 10h.","火车十点到。"],["L'arrivée est prévue à midi.","预计中午到达。"],["Il attend l'arrivée de ses amis.","他在等朋友们到来。"]],"co":[["l'heure d'arrivée","到达时间"],["la ligne d'arrivée","终点线"],["à l'arrivée","到达时，最后"],["l'arrivée à la gare","到达火车站"]],"sy":[["le départ","courant","反义：出发"],["la venue","soutenu","到来"]],"fq":"高频，旅行常用。","me":"arriver ← ad + ripa：到岸边，就是到达。","tr":{"zh":"你几点到达？","fr":"À quelle heure est ton arrivée ?","alt":"Tu arrives à quelle heure ?","note":"à quelle heure 问几点。"}},
 "La choucroute": {"pos":"n.f. 阴性名词，不可数（多用部分冠词 de la）","s":"酸菜（发酵卷心菜），尤指阿尔萨斯名菜 choucroute garnie，配香肠、猪肉和土豆。与中国东北酸菜相近但做法和吃法不同。","ipa":"[ʃu.kʁut]","ph":"ch [ʃ]；ou [u]；cr [kʁ]；ou [u]；te [t]，结尾 e 不发。","pi":"两个 ou 都读 [u]；chou 开头是 [ʃu]；cr 连着读 [kʁ]。","et":"来自阿尔萨斯语 sürkrüt（酸菜），受 chou 和 croûte 影响改成现在的形状。","ex":[["J'aime manger de la choucroute.","我喜欢吃酸菜。"],["La choucroute est un plat d'Alsace.","酸菜是阿尔萨斯的一道菜。"],["On sert la choucroute avec des saucisses.","酸菜配香肠吃。"]],"co":[["une choucroute garnie","酸菜拼盘"],["manger de la choucroute","吃酸菜"],["avec des saucisses","配香肠"],["du chou","卷心菜"]],"sy":[["chou","courant","卷心菜（原料）"]],"fq":"低中频，饮食和地区话题。","me":"chou（卷心菜）+ croûte：酸菜。","tr":{"zh":"在阿尔萨斯，人们吃酸菜配香肠。","fr":"En Alsace, on mange de la choucroute avec des saucisses.","alt":"En Alsace, on mange la choucroute avec des saucisses.","note":"on = 人们，泛指。"}},
 "La Corse": {"pos":"n.f. 阴性专有名词（岛名）","s":"科西嘉岛，法国地中海上的岛屿，也是法国的一个行政区；拿破仑的出生地阿雅克肖（Ajaccio）在这里。形容词 corse，un Corse = 科西嘉人。","ipa":"[kɔʁs]","ph":"C [k]；o [ɔ]；r [ʁ]；s 读 [s]；结尾 e 不发音。","pi":"-rse 读 [ʁs]，s 要发音；表示「在科西嘉」用 en Corse；是阴性。","et":"拉丁语 Corsica（科西嘉）。","ex":[["Nous passons nos vacances en Corse.","我们在科西嘉度假。"],["La Corse est une île française.","科西嘉是一座法国岛屿。"],["En Corse, il y a de belles plages.","科西嘉有很美的海滩。"]],"co":[["en Corse","在科西嘉"],["un Corse / une Corse","科西嘉人"],["le maquis corse","科西嘉灌木丛"],["le ferry pour la Corse","去科西嘉的渡轮"]],"sy":[["la Sardaigne","courant","南边相邻的意大利岛屿"]],"fq":"中频，旅行话题。","me":"Corse ← Corsica：英语 Corsica。","tr":{"zh":"夏天我们去科西嘉岛。","fr":"L'été, nous allons en Corse.","alt":"En été, on va en Corse.","note":"en + 阴性地名。"}},
 "La première/seconde classe": {"pos":"n.f. 阴性名词，复数 classes","s":"头等 / 二等（舱位、车厢等级）。voyager en première classe = 坐头等舱 / 一等座。seconde classe 也可说 deuxième classe。","ipa":"[la pʁə.mjɛʁ klas] / [la sə.gɔ̃d klas]","ph":"première：pr [pʁ]，e 弱读 [ə]，ière [jɛʁ]；seconde：c 读 [g]，on [ɔ̃]，d 在结尾读 [d]；classe：cl [kl]，a [a]，ss [s]。","pi":"seconde 里的 c 读 [g]，不是 [k]；classe 的 a 读 [a]；记住是阴性：la première classe。","et":"première ← 拉丁语 primarius；seconde ← 拉丁语 secundus（跟随的）；classe ← 拉丁语 classis（等级，分类）。","ex":[["Les billets en première classe sont plus chers.","头等舱的票更贵。"],["Je voyage en seconde classe.","我坐二等座。"],["Il y a deux classes dans ce train.","这趟火车有两个等级。"]],"co":[["voyager en première classe","坐头等舱 / 一等座"],["un billet de seconde classe","二等票"],["la classe économique","经济舱"],["la classe affaires","商务舱"]],"sy":[["deuxième classe","courant","二等，也常说"],["classe éco","courant","经济舱简称"]],"fq":"中频，旅行买票常用。","me":"seconde 里的 c 读 g：se-GON-de。","tr":{"zh":"我买了一张二等座的车票。","fr":"J'ai acheté un billet en seconde classe.","alt":"J'ai pris un billet de seconde.","note":"en seconde classe / de seconde classe。"}},
 "La Suisse": {"pos":"n.f. 阴性专有名词（国名）","s":"瑞士，位于法国东边的国家，有四种官方语言（德语、法语、意大利语、罗曼什语）。法语区叫 la Suisse romande。形容词 suisse，un Suisse = 瑞士人。","ipa":"[sɥis]","ph":"S [s]；ui 读 [ɥi]（快速的「于-i」）；ss [s]；结尾 e 不发音。","pi":"ui 读 [ɥi]，不是 [wi]；ss 读 [s]；表示「在瑞士」用 en Suisse；是阴性国名。","et":"来自德语 Schweiz，源于 Schwyz 州。","ex":[["La Suisse est un beau pays.","瑞士是个美丽的国家。"],["On parle français à Genève, en Suisse.","在瑞士的日内瓦说法语。"],["En Suisse, il y a beaucoup de montagnes.","瑞士有很多山。"]],"co":[["en Suisse","在瑞士"],["la Suisse romande","法语区瑞士"],["un Suisse / une Suisse","瑞士人"],["un couteau suisse","瑞士军刀"]],"sy":[["la Belgique","courant","另一个说法语的邻国"]],"fq":"中频，旅行话题。","me":"Suisse 读 [sɥis]：想想「瑞士」的「瑞」。","tr":{"zh":"我们周末去瑞士。","fr":"Nous allons en Suisse ce week-end.","alt":"On va en Suisse ce week-end.","note":"en + 阴性国名。"}},
 "La ville": {"pos":"n.f. 阴性名词，复数 villes","s":"城市；城镇。ville 既可指大城市，也可指小城。aller en ville = 进城（去市中心）。","ipa":"[vil]","ph":"ville 里的 ill 读 [il]，v 读 [v]，e 不发音。","pi":"不要读成 [vij]；ville、mille、tranquille 是 ill 读 [il] 的少数例外。","et":"拉丁语 villa（乡间庄园），后来指聚居地。","ex":[["J'habite dans une grande ville.","我住在大城市。"],["Nous allons en ville ce soir.","我们今晚进城去。"]],"co":[["en ville","在城里；进城"],["la ville de Paris","巴黎市"],["une petite ville","小城"]],"sy":[["cité","soutenu","城邦；城区，较书面"],["village","courant","村庄，比 ville 小"]],"fq":"极高频，日常常用。","me":"ville 听起来像「威尔」，进城就是 en ville。","tr":{"zh":"我喜欢住在小城市里。","fr":"J'aime habiter dans une petite ville.","alt":"J'aime bien vivre dans une petite ville.","note":"说「在城里」用 en ville，不用 à la ville。"}},
 "Une aventure": {"pos":"n.f. 阴性名词，复数 aventures","s":"冒险；奇遇。也可指一段（感情上的）经历，如 une aventure amoureuse。","ipa":"[a.vɑ̃.tyʁ]","ph":"en 在 aventure 里读鼻化音 [ɑ̃]；结尾 -ure 读 [yʁ]，e 不发音。","pi":"-ure 是 [yʁ]（舌位像 ü），不是 [uʁ]。","et":"拉丁语 adventura（将要发生的事），与 advenire（到来）同源。","ex":[["C'est une grande aventure.","这是一次大冒险。"],["Il a vécu des aventures incroyables.","他经历过不可思议的冒险。"]],"co":[["partir à l'aventure","出发去冒险"],["un film d'aventure","冒险片"],["une aventure amoureuse","一段艳遇；恋情"]],"sy":[["expédition","courant","远征，探险队"],["péripétie","soutenu","意外波折"]],"fq":"高频，日常常用。","me":"aventure 与英语 adventure 很像，去掉 d 就是。","tr":{"zh":"这次旅行真是一场冒险！","fr":"Ce voyage est une vraie aventure !","alt":"Quelle aventure, ce voyage !","note":"说「去冒险」常用 partir à l'aventure。"}},
 "Une boîte aux lettres": {"pos":"n.f. 阴性名词，复数 boîtes aux lettres","s":"信箱；邮筒。既指家门口的信箱，也指街上的邮筒。也可指电子邮箱。","ipa":"[bwat o lɛtʁ]","ph":"boîte [bwat]，oi 读 [wa]，î 上的帽子不改变读音；aux 读 [o]；lettres 读 [lɛtʁ]，结尾 es 不发音。","pi":"核心名词是 boîte（阴性），所以用 une；lettres 要加复数 s，但不发音。","et":"boîte 来自拉丁语 buxida（木制小盒），与 buis（黄杨木）有关；lettre 来自拉丁语 littera。","ex":[["Il y a une lettre dans la boîte aux lettres.","信箱里有一封信。"],["Je vais vérifier la boîte aux lettres.","我去看看信箱。"]],"co":[["relever la boîte aux lettres","取信箱里的信"],["mettre une lettre dans la boîte","把信投进信箱"],["une boîte aux lettres électronique","电子邮箱"]],"sy":[["boîte à lettres","courant","也可以说，意思相同"],["boîte mail","familier","电子邮箱"]],"fq":"高频，日常常用。","me":"「盒子」boîte + 「给信」aux lettres = 装信的盒子。","tr":{"zh":"你看过信箱了吗？","fr":"Tu as regardé dans la boîte aux lettres ?","alt":"T'as vérifié la boîte aux lettres ?","note":"复数只有 boîte 变：des boîtes aux lettres。"}},
 "Une chambre d'hôte": {"pos":"n.f. 阴性名词，复数 chambres d'hôte(s)","s":"民宿；私人住家提供的客房（通常含早餐）。常写成 chambre d'hôtes，两种拼写都常见。","ipa":"[ʃɑ̃bʁ dot]","ph":"ch [ʃ]，am 在 b 前读鼻化音 [ɑ̃]，bre 的 e 轻读；hôte 的 h 不发音，ô 读 [o]，te 读 [t]。","pi":"hôte 里的 h 是哑音 h，要和 d' 连读：d'hôte [dot]。hôte 也可指「主人」和「客人」。","et":"chambre 来自拉丁语 camera（房间）；hôte 来自拉丁语 hospes（主人；客人）。","ex":[["J'ai réservé une chambre d'hôte à la campagne.","我订了乡间民宿。"],["Le petit-déjeuner est servi dans la chambre d'hôte.","民宿提供早餐。"]],"co":[["réserver une chambre d'hôte","预订民宿"],["tenir une chambre d'hôte","经营民宿"],["une chambre d'hôtes","民宿（也常写复数）"]],"sy":[["gîte","courant","乡村度假屋，自己做饭"],["B&B","familier","英式叫法，口语中也说"],["hôtel","courant","酒店，规模更大"]],"fq":"中频，旅游时常用。","me":"chambre（房间）+ d'hôte（主人家的）= 住在主人家里的房间。","tr":{"zh":"我们在山里订了一间民宿。","fr":"Nous avons réservé une chambre d'hôte à la montagne.","alt":"On a réservé une chambre d'hôte à la montagne.","note":"hôte 兼有「主人」和「客人」两义，要看上下文。"}},
 "Une ferme": {"pos":"n.f. 阴性名词，复数 fermes","s":"农场；农庄。同形的 ferme 还是形容词，意思是「坚定的；结实的」，也是动词 fermer 的变位（il ferme = 他关上）。","ipa":"[fɛʁm]","ph":"fe [fɛ]（è 音），rm 连读 [ʁm]，结尾 e 不发音。","pi":"不要和 fermer（关）混淆：la ferme 是名词，je ferme la porte 是动词。","et":"中世纪拉丁语 firma（约定的租金），因为农场原先是租来耕种的。","ex":[["Il y a des animaux dans la ferme.","农场里有动物。"],["Nous passons le week-end dans une ferme.","我们周末住在农场。"]],"co":[["un fermier / une fermière","农场主；农民"],["une ferme biologique","有机农场"],["la ferme familiale","家庭农场"]],"sy":[["exploitation agricole","soutenu","农业经营体，较正式"],["ferme","courant","同时是形容词「坚定的」"]],"fq":"中频。","me":"ferme 听起来像「farm」，意思也一样。","tr":{"zh":"我祖父有一个小农场。","fr":"Mon grand-père a une petite ferme.","alt":"Mon grand-père possède une petite ferme à la campagne.","note":"农民叫 un fermier，不是 un ferme。"}},
 "Une fleur": {"pos":"n.f. 阴性名词，复数 fleurs","s":"花。也可以引申为「精华」（la fleur de l'âge = 盛年）。动词 fleurir = 开花。","ipa":"[flœʁ]","ph":"fl [fl]，eu 读 [œ]（嘴圆、半开），r 在喉咙后部 [ʁ]。","pi":"eu [œ] 不同于 ou [u]：fleur ≠ flou。r 不发舌尖卷舌，而是喉音。","et":"拉丁语 flos, floris（花）。同源：fleuriste, fleurir, floral。","ex":[["Cette fleur est belle.","这朵花很美。"],["Il offre des fleurs à sa mère.","他送花给妈妈。"]],"co":[["un bouquet de fleurs","一束花"],["offrir des fleurs","送花"],["en fleur(s)","开着花的"],["un fleuriste","花店老板；花店"]],"sy":[["bouquet","courant","花束"],["plante","courant","植物，范围更大"]],"fq":"高频，日常常用。","me":"fleur 像英语 flower 的前半：fl + eur。","tr":{"zh":"我想买一束花。","fr":"Je voudrais acheter un bouquet de fleurs.","alt":"Je voudrais acheter des fleurs.","note":"fleur 是阴性：une fleur，不是 un fleur。"}},
 "Une lettre": {"pos":"n.f. 阴性名词，复数 lettres","s":"信；字母。une lettre = 一封信，也可以是一个字母（les lettres de l'alphabet）。les lettres 复数还可指「文学；文科」。","ipa":"[lɛtʁ]","ph":"e 读 [ɛ]，tt 读单个 [t]，结尾 -tre 读 [tʁ]，e 不发音。","pi":"不要和 courrier（邮件）、e-mail 混淆；lettre 是传统纸质信。","et":"拉丁语 littera（字母），复数 litterae 后来表示「书信；文学」。","ex":[["J'écris une lettre à ma mère.","我给妈妈写信。"],["Cette lettre vient d'Italie.","这封信来自意大利。"]],"co":[["écrire / envoyer une lettre","写信 / 寄信"],["recevoir une lettre","收到信"],["une lettre de motivation","求职信"],["à la lettre","按字面意思"]],"sy":[["courrier","courant","邮件（泛指）"],["mot","courant","便条、短信（un petit mot）"]],"fq":"极高频。","me":"lettre 的结尾 tre 要轻：一封信，一个字母。","tr":{"zh":"我每个月给她写一封信。","fr":"Je lui écris une lettre chaque mois.","alt":"Je lui envoie une lettre tous les mois.","note":"lettre 是阴性：une lettre。"}},
 "Une location": {"pos":"n.f. 阴性名词，复数 locations","s":"租赁；出租的东西（房子、车）。location 是「租」，不是「地点」。「地点」要说 lieu 或 endroit。","ipa":"[lo.ka.sjɔ̃]","ph":"lo [lo]，ca [ka]，tion 读 [sjɔ̃]（-tion 的 t 读 s）。","pi":"假朋友：英语 location（地点）≠ 法语 location（租赁）。-tion 读 [sjɔ̃]，不是 [ʃən]。","et":"拉丁语 locatio（出租），来自 locare（安放；出租）。同源：louer（租）。","ex":[["Nous avons pris une location au bord de la mer.","我们在海边租了房子。"],["La location de la voiture coûte cher.","租车费用很高。"]],"co":[["une location de vacances","度假出租屋"],["la location de voitures","租车"],["en location","出租中；租来的"],["un contrat de location","租赁合同"]],"sy":[["bail","soutenu","租约"],["loyer","courant","租金（月租）"]],"fq":"中高频。","me":"location 是「租」，它的动词是 louer。","tr":{"zh":"我们在夏天租了一套公寓。","fr":"Nous avons pris une location pour l'été.","alt":"On a loué un appartement pour l'été.","note":"「地点」用 un lieu / un endroit，别用 location。"}},
 "Une poule": {"pos":"n.f. 阴性名词，复数 poules","s":"母鸡。口语里 poule 也可指「(比赛的)小组」(poule A)。吃的鸡肉叫 le poulet 或 la volaille。","ipa":"[pul]","ph":"ou 读 [u]，l 清楚地发出，结尾 e 不发音。","pi":"poule [pul] 与 pull（英语）不同；也别和 poulet [pu.lɛ]（鸡肉）弄混。","et":"拉丁语 pulla（小母鸡）。同源：poulet, poulain（小马驹）。","ex":[["La poule pond un œuf.","母鸡下蛋。"],["Les poules sont dans le jardin.","母鸡们在花园里。"]],"co":[["un poulet","鸡肉；小鸡"],["un œuf de poule","鸡蛋"],["mouillé comme une poule","湿透的"],["une poule mouillée","胆小鬼"]],"sy":[["poulet","courant","做菜的鸡肉、公鸡也泛称"],["coq","courant","公鸡"],["gallinacé","soutenu","鸡形目禽类"]],"fq":"中频。","me":"poule 读「普勒」，母鸡 poule 下蛋 pond。","tr":{"zh":"农场里有十只母鸡。","fr":"Il y a dix poules dans la ferme.","alt":"Dans la ferme, on a dix poules.","note":"公鸡是 un coq，小鸡是 un poussin。"}},
 "Une tente": {"pos":"n.f. 阴性名词，复数 tentes","s":"帐篷。搭帐篷用 monter une tente，拆用 démonter。注意 tente 与动词 tenter（尝试）同形，但是不同的词。","ipa":"[tɑ̃t]","ph":"en 读鼻化音 [ɑ̃]，t 读 [t]，结尾 e 使 t 发音：[tɑ̃t]。","pi":"结尾的 t 要读出来（因为后面有 e）：tente [tɑ̃t]，与 temps [tɑ̃]（t 不发音）不同。","et":"拉丁语 tendere（拉开、绷紧）→ tenta，意思是「拉开的布」。","ex":[["Il dort dans une tente.","他睡在帐篷里。"],["Nous montons la tente près du lac.","我们在湖边搭帐篷。"]],"co":[["monter / démonter la tente","搭 / 拆帐篷"],["faire du camping sous la tente","在帐篷里露营"],["planter sa tente","扎营"]],"sy":[["bivouac","courant","野外露营"],["chapiteau","soutenu","大篷（马戏团）"]],"fq":"中频。","me":"tente 像 tent：张开的布。","tr":{"zh":"我们晚上在森林里搭帐篷。","fr":"Nous montons la tente dans la forêt le soir.","alt":"Le soir, on monte la tente dans la forêt.","note":"搭帐篷用 monter，不是 faire。"}},
 "Une vache": {"pos":"n.f. 阴性名词，复数 vaches","s":"母牛；奶牛。口语感叹 la vache ! = 天哪！但 vache 也可作骂人话，对人要小心。","ipa":"[vaʃ]","ph":"v [v]，a [a]，ch [ʃ]，结尾 e 不发音。","pi":"ch 读 [ʃ]，像「希」；不是 [k] 也不是 [tʃ]。","et":"拉丁语 vacca（母牛）。同源：vachette, vacher。","ex":[["La vache mange de l'herbe.","牛在吃草。"],["Les vaches sont dans le pré.","牛在草地上。"]],"co":[["le lait de vache","牛奶"],["une vache laitière","奶牛"],["parler français comme une vache espagnole","法语说得很差"],["la vache !","我的天！（口语）"]],"sy":[["bovin","soutenu","牛科动物，较书面"],["taureau","courant","公牛"],["veau","courant","小牛"]],"fq":"中频。","me":"vache 读「瓦什」，英语 vaccine（疫苗）就来自这个词。","tr":{"zh":"那头牛在田野里吃草。","fr":"Cette vache mange de l'herbe dans le champ.","alt":"La vache broute l'herbe dans le champ.","note":"公牛 taureau，牛肉 le bœuf，小牛 veau。"}},
 "Une voie": {"pos":"n.f. 阴性名词，复数 voies","s":"轨道；车道；站台编号。在法国火车站，voie 是铁轨的编号，常用来指「几号站台」。也可指「途径；方式」（la voie du succès）。","ipa":"[vwa]","ph":"oi 读 [wa]，voie [vwa]，结尾 e 不发音。","pi":"与 voix（声音）、vois / voit（看，变位）同音，都读 [vwa]，看上下文区分。","et":"拉丁语 via（路）。同源：voyage, voyager, voiture。","ex":[["Le train va partir de la voie n°4.","火车从四号站台出发。"],["Cette voie est réservée aux bus.","这条车道是公交专用的。"]],"co":[["la voie ferrée","铁路"],["la voie 4","四号站台/轨道"],["en voie de","正在……的过程中"],["une voie rapide","快速路"]],"sy":[["quai","courant","站台（旅客上下车的地方）"],["chemin","courant","路，小道"],["route","courant","公路"]],"fq":"中高频，车站常见。","me":"voie 与 voyage 同家族：路 = voie。","tr":{"zh":"我的火车在三号站台。","fr":"Mon train est sur la voie 3.","alt":"Mon train part de la voie 3.","note":"站台号前常用 voie：voie 4。"}},
 "Des fruits de mer": {"pos":"n.m.pl. 阳性复数名词（通常只用复数）","s":"海鲜，主要指贝类、虾蟹（huîtres, moules, crevettes），不含鱼。fruits 在这里是「(海里的)产物」，不是水果。","ipa":"[fʁɥi də mɛʁ]","ph":"fruits 读 [fʁɥi]，结尾 ts 不发音；de 读 [də]；mer 读 [mɛʁ]，r 要发。","pi":"fruits 的 ts 不读；mer 与 mère（妈妈）、maire（市长）同音，注意上下文。","et":"fruit 来自拉丁语 fructus（果实、收获），所以 fruits de mer = 「大海的收获」。","ex":[["Nous mangeons des fruits de mer au restaurant.","我们在餐厅吃海鲜。"],["Elle adore les fruits de mer.","她超爱海鲜。"]],"co":[["un plateau de fruits de mer","海鲜拼盘"],["allergique aux fruits de mer","对海鲜过敏"],["des produits de la mer","海产品"]],"sy":[["produits de la mer","courant","海产品，较中性"],["crustacés","soutenu","甲壳类"],["poisson","courant","鱼（不含贝类）"]],"fq":"中频，餐厅常用。","me":"「海的果实」：大海结的果。","tr":{"zh":"我们点了一份海鲜拼盘。","fr":"Nous avons commandé un plateau de fruits de mer.","alt":"On a pris un plateau de fruits de mer.","note":"通常用复数；吃的时候说 des fruits de mer。"}},
 "L'aller / Le retour / Un aller-retour": {"pos":"n.m. 阳性名词，复数 allers / retours / allers-retours","s":"l'aller = 去程；le retour = 回程；un aller-retour = 往返票。un aller simple = 单程票。买票时最常说 un aller simple 或 un aller-retour。","ipa":"[a.le] / [ʁə.tuʁ] / [a.le.ʁə.tuʁ]","ph":"aller [a.le]，结尾 er 读 [e]；retour [ʁə.tuʁ]，r 在喉后；aller-retour 中间连起来读。","pi":"l'aller 有省音 l'；aller 做动词是「去」，做名词是「去程」，注意区分。","et":"aller 的来源有争议；retour 来自 retourner（回头），即 re- + tourner。","ex":[["Je voudrais un billet aller-retour, s'il vous plaît.","我要一张往返票。"],["Un aller simple pour Lyon, s'il vous plaît.","请给我一张去里昂的单程票。"]],"co":[["un aller simple","单程票"],["un aller-retour","往返票"],["à l'aller / au retour","去程 / 回程时"],["le trajet retour","回程"]],"sy":[["billet","courant","票"],["trajet","courant","行程"],["voyage","courant","旅行"]],"fq":"高频，买票时常用。","me":"去 + 回 = aller-retour，像往返的一条线。","tr":{"zh":"去的时候坐火车，回来的时候坐飞机。","fr":"À l'aller, nous prenons le train, et au retour, l'avion.","alt":"À l'aller on prend le train, au retour l'avion.","note":"票上说单程 = aller simple，别说 un aller seul。"}},
 "Un canapé-lit / Un clic-clac": {"pos":"n.m. 阳性名词，复数 canapés-lits / clic-clacs","s":"沙发床：白天是沙发，晚上拉开变成床。canapé-lit 通用；clic-clac 是一种折叠方式，口语里也泛指沙发床。","ipa":"[ka.na.pe.li] / [klik.klak]","ph":"canapé [ka.na.pe]（pé 的 é 读 [e]），lit 读 [li]，t 不发音；clic-clac 来自「咔嚓」的声音 [klik.klak]。","pi":"lit 的 t 不发音；clic-clac 里 c 都读 [k]。","et":"canapé 来自拉丁语 conopeum、希腊语 kōnōpeion（蚊帐）；clic-clac 是拟声词，模仿折叠时的响声。","ex":[["Mon ami dort sur le canapé-lit.","我的朋友睡沙发床。"],["On a un clic-clac dans le salon pour les invités.","我们客厅有张沙发床给客人用。"]],"co":[["ouvrir le canapé-lit","把沙发床打开"],["dormir sur un clic-clac","睡沙发床"],["un canapé d'angle","转角沙发"]],"sy":[["canapé convertible","courant","可折叠的沙发"],["banquette-lit","courant","长凳式沙发床"],["futon","courant","日式床垫"]],"fq":"中频，租房 / 住宿时常用。","me":"咔嚓一下（clic-clac），沙发变成床。","tr":{"zh":"你可以睡客厅的沙发床。","fr":"Tu peux dormir sur le canapé-lit du salon.","alt":"Tu peux dormir sur le clic-clac, dans le salon.","note":"两个词都是阳性：un canapé-lit, un clic-clac。"}},
 "Bronzer": {"pos":"v. 第一组动词 (-er)，助动词 avoir；pp. bronzé","s":"晒黑；晒太阳。bronzer 既可单独用（Il bronze vite = 他很容易晒黑），也可用 se faire bronzer。","ipa":"[bʁɔ̃.ze]","ph":"bronzer 的 on 读鼻化音 [ɔ̃]，z 读 [z]，er 读 [e]。","pi":"on 是鼻化音，不发 n；bronzer 里的 z 要读浊音 [z]。","et":"bronze（青铜）来自意大利语 bronzo，因为古铜色肤色像青铜。","ex":[["J'aime bronzer sur la plage.","我喜欢在海滩晒太阳。"],["Elle a bronzé pendant les vacances.","她假期里晒黑了。"]],"co":[["se faire bronzer","晒太阳"],["bronzer au soleil","在阳光下晒黑"],["la crème solaire","防晒霜"],["être bronzé(e)","晒黑了"]],"sy":[["se faire bronzer","courant","更口语的说法"],["prendre des couleurs","courant","晒出好气色"],["se dorer","familier","把皮肤晒成金黄色"]],"fq":"中频，夏天常用。","me":"bronzer：皮肤变得像「青铜」一样的颜色。","tr":{"zh":"他整个夏天都在海边晒太阳。","fr":"Il a bronzé à la plage tout l'été.","alt":"Il s'est fait bronzer à la plage tout l'été.","note":"过去时：J'ai bronzé。变位规则：je bronze, nous bronzons。"}},
 "Conduire": {"pos":"v. 第三组不规则动词，助动词 avoir；pp. conduit","s":"驾驶；开车；带领、送某人去。je conduis, tu conduis, il conduit, nous conduisons, ils conduisent；过去分词 conduit。","ipa":"[kɔ̃.dɥiʁ]","ph":"on [ɔ̃]；ui 读 [ɥi]（半元音），结尾 r 要发 [ʁ]。","pi":"ui 读 [ɥi]，是个短音，不要拆成「乌-伊」；变位 conduis / conduit 结尾 s / t 不发音。","et":"拉丁语 conducere（一起带领）。同源：conducteur, conduite, produire。","ex":[["Il sait conduire.","他会开车。"],["Je conduis depuis dix ans.","我开车十年了。"]],"co":[["conduire une voiture","开车"],["le permis de conduire","驾照"],["conduire quelqu'un à","送某人去"],["une conduite","驾驶；行为"]],"sy":[["piloter","courant","驾驶飞机/赛车"],["emmener","courant","带某人去"],["mener","soutenu","引领，带领"]],"fq":"高频，日常常用。","me":"con + duire：「一起带着走」，开车就是带车走。","tr":{"zh":"你会开车吗？","fr":"Tu sais conduire ?","alt":"Tu conduis ?","note":"说「会开车」用 savoir conduire；动词不要加 de。"}},
 "Échanger": {"pos":"v. 第一组动词 (-er)，助动词 avoir；pp. échangé","s":"交换；交流；调换。échanger A contre B = 用 A 换 B。échanger des idées = 交流想法。","ipa":"[e.ʃɑ̃.ʒe]","ph":"é [e]；ch 读 [ʃ]；an 读 [ɑ̃]；g 在 e 前读 [ʒ]：[e.ʃɑ̃.ʒe]。","pi":"nous échangeons 里 g 后加 e，保持 [ʒ] 音；ch 是 [ʃ] 不是 [k]。","et":"由前缀 é-（ex-）+ changer 构成，changer 来自拉丁语 cambiare（交换）。","ex":[["Je veux échanger mon billet.","我想换我的票。"],["Nous avons échangé nos numéros de téléphone.","我们交换了电话号码。"]],"co":[["échanger A contre B","用 A 换 B"],["échanger des idées","交流想法"],["un échange","交换；交流"],["échanger un cadeau","换礼物"]],"sy":[["changer","courant","换，更常用"],["troquer","soutenu","以物易物"],["remplacer","courant","替换"]],"fq":"中高频。","me":"é + changer：把东西「换出去」。","tr":{"zh":"我想把这件衬衫换成另一个尺码。","fr":"Je voudrais échanger cette chemise contre une autre taille.","alt":"Je voudrais changer cette chemise pour une autre taille.","note":"nous échangeons（加 e）；用 contre 引出换到的东西。"}},
 "Goûter": {"pos":"v. 第一组动词 (-er)，助动词 avoir；pp. goûté","s":"尝；品尝。也可作名词 le goûter = 下午四点左右的点心（尤其给孩子吃的）。goûter à = 尝一点，goûter + 直接宾语 = 品尝这道菜。","ipa":"[gu.te]","ph":"g 读 [g]，û 读 [u]（帽子不改变读音），er 读 [e]。","pi":"û 读 [u]，不是 [y]；动词 goûter [gu.te] 与名词 goût [gu]（t 不发音）相关。","et":"拉丁语 gustare（尝）。同源：goût, dégoût, dégustation。","ex":[["Tu veux goûter ce gâteau ?","你想尝尝这个蛋糕吗？"],["Les enfants goûtent à quatre heures.","孩子们下午四点吃点心。"]],"co":[["goûter un plat","尝一道菜"],["goûter à quelque chose","尝一尝"],["un goûter","下午茶；点心"],["le goût","味道；品味"]],"sy":[["déguster","soutenu","细细品尝"],["essayer","courant","试一试"],["manger","courant","吃"]],"fq":"高频，日常常用。","me":"goûter：用「口」尝，像「goût」＋ er。","tr":{"zh":"你想尝尝我的汤吗？","fr":"Tu veux goûter ma soupe ?","alt":"Tu veux goûter à ma soupe ?","note":"goûter à 与 goûter 都可以；le goûter 作名词是「点心」。"}},
 "Louer": {"pos":"v. 第一组动词 (-er)，助动词 avoir；pp. loué","s":"租。louer 既可表示「租进」(别人的东西)，也可表示「租出」(自己的东西)，要看语境。另有一个意思：称赞（louer quelqu'un）。","ipa":"[lwe]","ph":"ou 读 [u]，但 loué 读 [lwe]：ou + é 连成一个音节 [lwe]。","pi":"ou 与 é 相连变成半元音 [w]：louer [lwe]。租出与租进用同一个词。","et":"拉丁语 locare（放置、出租），同源：location。「称赞」义来自拉丁语 laudare。","ex":[["Nous allons louer une voiture.","我们要租一辆车。"],["Il loue son appartement à des étudiants.","他把公寓租给学生。"]],"co":[["louer une voiture / un appartement","租车 / 租公寓"],["à louer","出租"],["louer à quelqu'un","租给某人"],["louer quelqu'un","称赞某人"]],"sy":[["prendre en location","courant","租下"],["affermer","soutenu","出租农地"],["féliciter","courant","称赞（louer 的另一义）"]],"fq":"高频，租房/租车时常用。","me":"louer：租 = location 的动词。","tr":{"zh":"我想租一间在市中心的公寓。","fr":"Je voudrais louer un appartement au centre-ville.","alt":"Je cherche un appartement à louer en centre-ville.","note":"à louer = 出租（招牌上常见）。"}},
 "Mourir": {"pos":"v. 第三组不规则动词，助动词 être；pp. mort","s":"死；去世。je meurs, tu meurs, il meurt, nous mourons, ils meurent；复合时态用 être：il est mort。常用来夸张：mourir de faim = 饿死了。","ipa":"[mu.ʁiʁ]","ph":"mou [mu]，ri [ʁi]，结尾 r 发 [ʁ]；变位 meurs / meurt 读 [mœʁ]。","pi":"变位时词干会变：mour- → meur-；结尾 -s / -t 不发音。复合时态用 être，不用 avoir。","et":"拉丁语 morī（死）。同源：mortel, mort, mortalité。","ex":[["Les plantes vont mourir sans eau.","没有水植物会死。"],["Mon grand-père est mort l'année dernière.","我祖父去年去世了。"]],"co":[["mourir de faim / de soif","饿死 / 渴死"],["mourir de rire","笑死"],["mourir d'envie de","极想……"],["être mort(e)","死了"]],"sy":[["décéder","soutenu","去世（官方用语）"],["disparaître","courant","消失；去世的委婉说法"],["crever","argot","咽气（人用很粗，动物用较中性）"]],"fq":"高频，日常常用，也常用于夸张。","me":"mourir ← mort：就是 mort 的动词。","tr":{"zh":"我饿死了！","fr":"Je meurs de faim !","alt":"Je crève de faim !","note":"il est mort（他死了）用 être；il est mort de rire 是夸张。"}},
 "Naître": {"pos":"v. 第三组不规则动词，助动词 être；pp. né","s":"出生。je nais, tu nais, il naît, nous naissons, ils naissent；复合时态用 être：il est né。表达「我出生于……」用 je suis né(e) en/à。","ipa":"[nɛtʁ]","ph":"n [n]，aî 读 [ɛ]，tre 读 [tʁ]：[nɛtʁ]，结尾 e 轻读。","pi":"il naît 有 î 帽子（语音不变），不要拼错；过去分词 né 要与主语一致：elle est née。","et":"拉丁语 nascī（出生）。同源：naissance, nation, natal。","ex":[["Mon fils va naître en mai.","我的儿子五月出生。"],["Elle est née à Paris en 1990.","她 1990 年出生于巴黎。"]],"co":[["être né(e) en … / à …","出生于……（年、地点）"],["la date de naissance","出生日期"],["donner naissance à","生下；产生"],["une naissance","诞生"]],"sy":[["venir au monde","courant","来到世上"],["voir le jour","soutenu","诞生"]],"fq":"高频，日常常用。","me":"naître ← naissance：新生命的开始。","tr":{"zh":"你是哪一年出生的？","fr":"Tu es né en quelle année ?","alt":"Tu es né(e) en quelle année ?","note":"说「我出生于……」用 je suis né(e)，不说 je nais。"}},
 "Réserver": {"pos":"v. 第一组动词 (-er)，助动词 avoir；pp. réservé","s":"预订；保留。订餐桌、订房、订票都用 réserver。也可表示「留给……」：réservé aux clients = 仅限顾客。","ipa":"[ʁe.zɛʁ.ve]","ph":"ré [ʁe]，ser 读 [zɛʁ]（s 在元音间读 [z]），ver 读 [ve]：[ʁe.zɛʁ.ve]。","pi":"s 读 [z] 不是 [s]；与 reverser、réserve（保留；储备）不同。","et":"拉丁语 reservare（保留），由 re- + servare（保存）构成。","ex":[["Je voudrais réserver une table pour deux.","我想订两人桌。"],["J'ai réservé un billet de train.","我订了火车票。"]],"co":[["réserver une table / une chambre","订桌 / 订房"],["une réservation","预订"],["réserver à l'avance","提前预订"],["réservé(e) à","专供……"]],"sy":[["booker","familier","订（英语借词，口语）"],["retenir","courant","订下（房间）"],["commander","courant","点餐；订货"]],"fq":"高频，旅游/餐厅常用。","me":"re + serve：「保存起来」留给你。","tr":{"zh":"我想订一间两晚的房间。","fr":"Je voudrais réserver une chambre pour deux nuits.","alt":"J'aimerais réserver une chambre pour deux nuits.","note":"réserver une table pour + 人数。"}},
 "Retourner": {"pos":"v. 第一组动词 (-er)；不及物「返回」助动词 être，及物「翻转」助动词 avoir","s":"返回（去过的地方）；翻转；退回。retourner à Paris = 回巴黎；retourner la crêpe = 把煎饼翻面。","ipa":"[ʁə.tuʁ.ne]","ph":"re [ʁə]，tour 读 [tuʁ]（ou = [u]），ner 读 [ne]：[ʁə.tuʁ.ne]。","pi":"与 revenir 的区别：retourner = 回到去过的地方；revenir = 回到说话人所在的地方。助动词：il est retourné（回去了），j'ai retourné le steak（我翻了牛排）。","et":"由 re- + tourner（转），tourner 来自拉丁语 tornare（用车床加工；转）。","ex":[["Je dois retourner à la maison.","我得回家。"],["Elle est retournée au bureau.","她回办公室了。"]],"co":[["retourner à / chez","回到某处"],["retourner un vêtement","把衣服翻过来；退回"],["se retourner","转身；回头"],["un retour","回来；返程"]],"sy":[["rentrer","courant","回家（常指回住处）"],["revenir","courant","回来（到说话人这边）"],["renvoyer","courant","寄回；退回"]],"fq":"高频。","me":"re + tourner：转回去。","tr":{"zh":"明年我们还要回意大利。","fr":"Nous retournerons en Italie l'année prochaine.","alt":"On retourne en Italie l'année prochaine.","note":"返回某地用 retourner à / en / chez。"}},
 "Revenir": {"pos":"v. 第三组不规则动词，助动词 être；pp. revenu","s":"回来；再来。变位同 venir：je reviens, nous revenons, ils reviennent；过去分词 revenu。revenir de = 从……回来。","ipa":"[ʁə.və.niʁ]","ph":"re [ʁə]，ve [və]，nir 读 [niʁ]；revient 读 [ʁə.vjɛ̃]，ent 不发音。","pi":"助动词 être：il est revenu；ils reviennent 的 -ent 不发音，nn 读 [n]。","et":"由 re- + venir 构成，venir 来自拉丁语 venīre（来）。同源：revenu（收入）, souvenir。","ex":[["Il va revenir demain.","他明天回来。"],["Reviens vite !","快点回来！"]],"co":[["revenir de voyage","旅行回来"],["revenir sur ses pas","原路返回"],["ça revient à …","合计……；相当于……"],["revenir à la maison","回家"]],"sy":[["rentrer","courant","回家"],["retourner","courant","回到去过的地方"],["repasser","familier","再来一趟"]],"fq":"高频。","me":"re + venir：再来一次。","tr":{"zh":"你什么时候回来？","fr":"Tu reviens quand ?","alt":"Quand est-ce que tu reviens ?","note":"les revenus = 收入，别和 revenir 混淆。"}},
 "Se baigner": {"pos":"v. 代动词（第一组），助动词 être；pp. baigné","s":"(在海、湖、泳池里)游泳、玩水；洗澡。强调「下水玩」而不是「会游泳」(nager)。在家洗澡泡澡用 prendre un bain。","ipa":"[sə bɛ.ɲe]","ph":"ai 读 [ɛ]，gn 读 [ɲ]（像「涅」），er 读 [e]：[bɛ.ɲe]。","pi":"gn 是一个音 [ɲ]，不是 [g] + [n]；代动词需要反身代词：je me baigne, nous nous baignons。","et":"来自拉丁语 balneare（洗浴），源自 balneum（浴室）。同源：bain。","ex":[["Nous allons nous baigner à la mer.","我们去海里游泳。"],["Les enfants se baignent dans la piscine.","孩子们在泳池里玩水。"]],"co":[["se baigner dans la mer / la piscine","在海里 / 泳池里游泳"],["un bain","洗澡；泡澡"],["un maillot de bain","泳衣"],["baignade interdite","禁止游泳"]],"sy":[["nager","courant","游泳（动作本身，会游）"],["prendre un bain","courant","泡澡"],["se tremper","familier","泡一下水"]],"fq":"中高频，夏天常用。","me":"se baigner 的 bain = 「洗澡」，下水泡一泡。","tr":{"zh":"天很热，我们去海里游泳吧。","fr":"Il fait chaud, allons nous baigner dans la mer.","alt":"Il fait chaud, on va se baigner ?","note":"不要把 se baigner 和 nager 当同义：nager 是「游」。"}},
 "Skier": {"pos":"v. 第一组动词 (-er)，助动词 avoir；pp. skié","s":"滑雪。可以直接用 skier，也常说 faire du ski。je skie, nous skions；skis 是名词复数「滑雪板」。","ipa":"[ski.e]","ph":"ski 读 [ski]，er 读 [e]，所以 skier 是两个音节：[ski.e]。","pi":"sk 读 [sk]，不要加 e 变成 [ə.ski]；nous skiions（半过去时）有两个 i。","et":"来自挪威语 ski（木片、滑雪板），19 世纪进入法语。","ex":[["Nous allons skier cet hiver.","今年冬天我们去滑雪。"],["Il skie très bien.","他滑雪滑得很好。"]],"co":[["faire du ski","滑雪"],["une station de ski","滑雪场"],["un skieur / une skieuse","滑雪者"],["les vacances de ski","滑雪假期"]],"sy":[["faire du ski","courant","更常用的说法"],["glisser","courant","滑行"],["snowboarder","courant","玩单板滑雪"]],"fq":"中频，冬天旅行时常用。","me":"ski + er：「滑雪」就是 ski 的动词。","tr":{"zh":"我们每年冬天都去滑雪。","fr":"Nous allons skier chaque hiver.","alt":"On fait du ski tous les hivers.","note":"「去滑雪」常说 faire du ski 或 aller skier。"}},
 "Surfer": {"pos":"v. 第一组动词 (-er)，助动词 avoir；pp. surfé","s":"冲浪；也可表示「上网」(surfer sur Internet)。je surfe, nous surfons。surf 是名词「冲浪运动」。","ipa":"[syʁ.fe]","ph":"sur 读 [syʁ]，u 读 [y]（圆唇的「于」），fer 读 [fe]：[syʁ.fe]。","pi":"u 读 [y]，不是 [u]；英语借词，但读音是法语式的，r 要发喉音。","et":"来自英语 to surf，18–20 世纪进入法语，用于冲浪和上网。","ex":[["Il aime surfer sur les vagues.","他喜欢在浪上冲浪。"],["Je surfe sur Internet tous les soirs.","我每天晚上上网。"]],"co":[["faire du surf","冲浪"],["surfer sur Internet","上网"],["une planche de surf","冲浪板"],["un surfeur / une surfeuse","冲浪者"]],"sy":[["faire du surf","courant","更常用的说法"],["naviguer","courant","上网浏览"],["glisser","courant","滑行"]],"fq":"中频，运动 / 上网时常用。","me":"surf + er：英语 surf 加法语动词词尾。","tr":{"zh":"他夏天在大西洋冲浪。","fr":"Il surfe dans l'Atlantique en été.","alt":"L'été, il fait du surf dans l'Atlantique.","note":"「上网」用 surfer sur Internet。"}},
 "Biologique": {"pos":"adj. 形容词，阴阳同形：biologique（复数 biologiques）","s":"有机的；生物的。日常常缩写为 bio（不变形）：des tomates bio。le bio 也可作名词，指有机食品。","ipa":"[bjɔ.lɔ.ʒik]","ph":"bi 读 [bjɔ]，o 读 [ɔ]，lo 读 [lɔ]，gi 读 [ʒik]：g 在 i 前读 [ʒ]，que 读 [k]。","pi":"-que 读 [k]，不读 [kə]；缩写 bio 作形容词不加 s。","et":"来自希腊语 bios（生命）+ logos（学问），加后缀 -ique。","ex":[["Ces tomates sont \"bio\".","这些番茄是有机的。"],["Elle achète des produits biologiques.","她买有机产品。"]],"co":[["l'agriculture biologique","有机农业"],["un produit bio","有机产品"],["un magasin bio","有机食品店"],["la biologie","生物学"]],"sy":[["bio","familier","常见简称"],["naturel","courant","天然的"],["écologique","courant","环保的"]],"fq":"高频，购物时常见。","me":"bio = 生命，bio 标志 = 有机。","tr":{"zh":"我只买有机蔬菜。","fr":"Je n'achète que des légumes bio.","alt":"J'achète seulement des légumes biologiques.","note":"bio 作形容词不变：des légumes bio。"}},
 "Chimique": {"pos":"adj. 形容词，阴阳同形：chimique（复数 chimiques）","s":"化学的；化学品的。常用来强调「人工合成、不天然」：un engrais chimique = 化肥。","ipa":"[ʃi.mik]","ph":"ch 读 [ʃ]，i 读 [i]，mi 读 [mik]：que 读 [k]，e 不发音。","pi":"ch 在这里读 [ʃ]，不是 [k]（与 chorale, chaos 不同）。","et":"来自 chimie，由中世纪拉丁语 alchimia（炼金术）来，最终出自阿拉伯语 al-kīmiyā'。","ex":[["C'est un produit chimique.","这是化学产品。"],["Il n'y a pas de produits chimiques dans ce savon.","这块肥皂不含化学成分。"]],"co":[["un produit chimique","化学品"],["une réaction chimique","化学反应"],["la chimie","化学"],["un chimiste","化学家"]],"sy":[["synthétique","courant","合成的"],["artificiel","courant","人造的"],["naturel","courant","反义：天然的"]],"fq":"中频。","me":"chimique ← chimie：化学。","tr":{"zh":"这种清洁剂含有化学成分。","fr":"Ce produit ménager contient des substances chimiques.","alt":"Ce produit contient des produits chimiques.","note":"des produits chimiques（形容词随名词变复数）。"}},
 "Compris(e)": {"pos":"adj. 形容词，阴性 comprise，复数 compris / comprises（comprendre 的过去分词）","s":"包含在内的；也是 comprendre 的过去分词（理解）。在价格里：Le service est compris = 含服务费。y compris = 包括……在内。","ipa":"[kɔ̃.pʁi] / [kɔ̃.pʁiz]","ph":"阳性 compris 读 [kɔ̃.pʁi]，s 不发音；阴性 comprise 读 [kɔ̃.pʁiz]，s 发 [z]。","pi":"阴性 comprise 的 s 要读出来 [z]；与 compris（理解）的写法相同，要看上下文。","et":"comprendre 来自拉丁语 comprehendere（抓住，包含）；compris 是它的过去分词。","ex":[["Le petit-déjeuner est compris dans le prix de la chambre.","早餐含在房价里。"],["Tout est compris, même les boissons.","一切都含在内，连饮料也是。"]],"co":[["service compris","含服务费"],["tout compris","全包"],["y compris","包括"],["non compris","不包括"]],"sy":[["inclus","courant","包括在内"],["incluse","courant","inclus 的阴性"],["exclu","courant","反义：不包括"]],"fq":"高频，订房 / 买东西时常见。","me":"com + pris：被「拿在一起」，就是包含。","tr":{"zh":"房价含早餐吗？","fr":"Le petit-déjeuner est compris dans le prix ?","alt":"Le petit-déj' est compris ?","note":"要与名词性数一致：la taxe est comprise，les repas sont compris。"}},
 "Écologique": {"pos":"adj. 形容词，阴阳同形：écologique（复数 écologiques）","s":"环保的；生态的。écologique 常表示「对环境友好」，écolo 是它的口语缩写。","ipa":"[e.kɔ.lɔ.ʒik]","ph":"é [e]，co [kɔ]，lo [lɔ]，gique 读 [ʒik]：g 在 i 前读 [ʒ]，que 读 [k]。","pi":"-gique 读 [ʒik]，不读 [gik]；缩写 écolo 才是口语。","et":"来自希腊语 oikos（家）+ logos（学问），écologie 在 19 世纪由 Haeckel 创造。","ex":[["C'est un produit écologique.","这是环保产品。"],["Le vélo est un transport écologique.","自行车是环保的交通方式。"]],"co":[["un geste écologique","环保举动"],["la crise écologique","生态危机"],["écologique / écolo","环保的 / 环保主义者"],["un transport écologique","环保交通"]],"sy":[["écolo","familier","口语：环保的"],["vert","courant","绿色的，环保的"],["durable","courant","可持续的"]],"fq":"高频，近年日常常用。","me":"éco + logique：关于「家园」的学问。","tr":{"zh":"骑自行车比开车更环保。","fr":"Faire du vélo est plus écologique que conduire.","alt":"Le vélo, c'est plus écolo que la voiture.","note":"écolo 可作形容词，也可指环保人士。"}},
 "Lent(e)": {"pos":"adj. 形容词，阴性 lente，复数 lents / lentes","s":"慢的；迟缓的。阳性 lent 读 [lɑ̃]，阴性 lente 读 [lɑ̃t]。副词是 lentement（慢慢地）。","ipa":"[lɑ̃] / [lɑ̃t]","ph":"阳性 lent 的 t 不发音：[lɑ̃]；阴性 lente 的 t 发音：[lɑ̃t]。","pi":"阴性要发出 t：lente [lɑ̃t]；副词是 lentement，注意不要把阴性 lente 的 t 漏掉。","et":"拉丁语 lentus（缓慢，粘稠）。同源：ralentir（减速）。","ex":[["Cet ordinateur est lent.","这台电脑很慢。"],["La circulation est lente ce matin.","今早交通很慢。"]],"co":[["un train lent","慢车"],["lentement","慢慢地"],["à feu lent","文火；小火"],["lent comme une tortue","慢得像乌龟"]],"sy":[["rapide","courant","反义：快的"],["lambin","familier","磨蹭的"],["posé","courant","沉稳的"]],"fq":"高频，日常常用。","me":"阴性 lente 多出一个 t，说起来也「慢」一拍。","tr":{"zh":"你说得太慢了。","fr":"Tu parles trop lentement.","alt":"Tu es trop lent quand tu parles.","note":"动词 ralentir = 放慢。"}},
 "Meilleur(e)": {"pos":"adj. 形容词，阴性 meilleure，复数 meilleurs / meilleures（bon 的比较级和最高级）","s":"更好的；最好的。le/la/les meilleur(e)(s) = 最好的。meilleur 修饰名词，副词则用 mieux（更好地）。","ipa":"[mɛ.jœʁ]","ph":"eil 读 [ɛj]，eur 读 [œʁ]：[mɛ.jœʁ]，不发 l。","pi":"不能说 plus bon；用 meilleur。meilleur 修饰名词，mieux 修饰动词/形容词。","et":"拉丁语 melior（更好的），meilleur 是由此演变而来。","ex":[["C'est le meilleur restaurant de la ville.","这是全城最好的餐厅。"],["Ce gâteau est meilleur que l'autre.","这块蛋糕比另一块好吃。"]],"co":[["le meilleur / la meilleure","最好的"],["meilleur que","比……好"],["meilleurs vœux","最美好的祝愿"],["de mieux en mieux","越来越好"]],"sy":[["mieux","courant","副词：更好地"],["excellent","courant","极好的"],["pire","courant","反义：更差的"]],"fq":"极高频。","me":"meilleur ← melior：比 bon 更高一级。","tr":{"zh":"这是我吃过最好吃的面包。","fr":"C'est le meilleur pain que j'aie jamais mangé.","alt":"C'est le meilleur pain que j'ai mangé.","note":"bon → meilleur → le meilleur。"}},
 "Rapide": {"pos":"adj. 形容词，阴阳同形：rapide（复数 rapides）","s":"快的；迅速的。修饰名词时用 rapide，副词用 vite（Il court vite）。rapidement 也是副词，略正式。","ipa":"[ʁa.pid]","ph":"ra [ʁa]，pi 读 [pi]，de 读 [d]：结尾的 e 不发音，但 d 要读出来：[ʁa.pid]。","pi":"结尾 d 要读出来，因为后面有 e；r 是喉音。","et":"拉丁语 rapidus（急速的，抓走的），同源 rapt。","ex":[["Ce train est très rapide.","这列火车很快。"],["Il a pris une douche rapide.","他匆匆冲了个澡。"]],"co":[["un train rapide","快车"],["rapidement","快速地"],["une réponse rapide","迅速的回复"],["la voie rapide","快速路"]],"sy":[["vite","courant","副词：快"],["express","courant","特快的"],["lent","courant","反义：慢的"]],"fq":"高频。","me":"rapide 像英语 rapid，意思相同。","tr":{"zh":"我想要一个快速的回答。","fr":"Je voudrais une réponse rapide.","alt":"J'aimerais une réponse rapide, s'il vous plaît.","note":"动词后用 vite，不用 rapide：Il court vite。"}},
 "Sportif / Sportive": {"pos":"adj. 形容词，阴性 sportive，复数 sportifs / sportives；也可作名词","s":"爱运动的；运动的；体育的。也可作名词：un sportif = 运动员。une sportive 是女运动员。","ipa":"[spɔʁ.tif] / [spɔʁ.tiv]","ph":"阳性 -if 读 [if]，f 发音；阴性 -ive 读 [iv]，v 发音。","pi":"阳性词尾 f 变阴性 v：sportif → sportive（与 actif → active 相同）。","et":"来自英语 sport，英语又来自古法语 desport（消遣）。-if 是法语后缀。","ex":[["Mon frère est très sportif.","我哥哥很爱运动。"],["Ma sœur est sportive : elle court tous les matins.","我姐姐爱运动，每天早上都跑步。"]],"co":[["un sportif / une sportive","运动员"],["une activité sportive","体育活动"],["faire du sport","做运动"],["des chaussures de sport","运动鞋"]],"sy":[["athlétique","courant","身材健壮的"],["actif","courant","活跃的"],["sédentaire","courant","反义：久坐不动的"]],"fq":"高频。","me":"sport + if：爱 sport 的人。","tr":{"zh":"她很爱运动，每周去三次健身房。","fr":"Elle est très sportive : elle va à la salle de sport trois fois par semaine.","alt":"Elle est hyper sportive, elle fait du sport trois fois par semaine.","note":"faire du sport = 做运动；être sportif = 爱运动。"}},
 "Une vue sur ... (la mer, la montagne, ...)": {"pos":"loc. 短语，une vue 是阴性名词，复数 vues","s":"(……的)景观；可以看到……。avoir vue sur = 面向某处。订房时常说 une chambre avec vue sur la mer。","ipa":"[vy syʁ]","ph":"vue 读 [vy]，u 读 [y]（圆唇的「于」）；sur 读 [syʁ]，r 在喉后。","pi":"vue [vy] 里的 u 不是 [u]；vue 与 vu（voir 的过去分词）同音。","et":"vue 是 voir（看）的过去分词名词化，来自拉丁语 videre。","ex":[["J'ai une chambre avec vue sur la mer.","我的房间有海景。"],["Cet appartement a une belle vue sur la montagne.","这套公寓可以看到很美的山景。"]],"co":[["une chambre avec vue sur la mer","海景房"],["avoir vue sur","面向……"],["une belle vue","好看的景观"],["en vue de","为了；以便"]],"sy":[["panorama","courant","全景"],["paysage","courant","风景"],["point de vue","courant","观点；观景点"]],"fq":"中频，订房时常用。","me":"vue：就是「看到」。vue sur la mer = 看到海。","tr":{"zh":"我想要一间有山景的房间。","fr":"Je voudrais une chambre avec vue sur la montagne.","alt":"Je cherche une chambre avec vue sur la montagne.","note":"用 avec vue sur（不加 la）：chambre avec vue sur la mer。"}},
 "Faire du tourisme": {"pos":"loc. 动词短语，faire 属第三组不规则动词，助动词 avoir","s":"观光；做游客。faire du tourisme = 到处游览景点。le tourisme（阳性）= 旅游业。","ipa":"[fɛʁ dy tu.ʁism]","ph":"fai 读 [fɛ]，re 读 [ʁ]；du 读 [dy]（u 要圆唇）；tourisme 读 [tu.ʁism]，结尾 -me 的 e 不发音。","pi":"faire 的 ai 读 [ɛ]；du 是 de + le，u 读 [y]；tourisme 的 s 读 [s]。","et":"tourisme 来自 tour（旅行，圈），源自拉丁语 tornus（转），经英语 tourism 回流。","ex":[["Nous aimons faire du tourisme.","我们喜欢观光旅游。"],["Aujourd'hui, on fait du tourisme à Paris.","今天我们在巴黎观光。"]],"co":[["un office de tourisme","旅游局；游客中心"],["un touriste / une touriste","游客"],["le tourisme de masse","大众旅游"],["visiter la ville","参观城市"]],"sy":[["visiter","courant","参观"],["se promener","courant","散步"],["voyager","courant","旅行"]],"fq":"中频，旅行时常用。","me":"faire + du + tourisme：做 + 一些 + 观光。","tr":{"zh":"我们明天去参观城市。","fr":"Demain, nous allons faire du tourisme.","alt":"Demain, on va visiter la ville.","note":"「faire du + 抽象名词」表示做某项活动：faire du sport。"}},
 "Prendre une photo/vidéo": {"pos":"loc. 动词短语，prendre 是第三组不规则动词，助动词 avoir","s":"拍照；拍视频。prendre une photo = 拍一张照片；prendre une vidéo = 拍视频。je prends, nous prenons, ils prennent。","ipa":"[pʁɑ̃dʁ yn fɔ.to / vi.de.o]","ph":"prendre 读 [pʁɑ̃dʁ]，an 读鼻化音 [ɑ̃]；une 读 [yn]；photo 读 [fɔ.to]，ph 读 [f]；vidéo 读 [vi.de.o]。","pi":"ph 读 [f]；prendre 变位时词干变化：prends / prenons / prennent。","et":"photo 来自希腊语 phōs（光）；prendre 来自拉丁语 prehendere（抓住）。","ex":[["Je vais prendre une photo.","我来拍张照片。"],["Elle prend une vidéo du coucher de soleil.","她在拍日落的视频。"]],"co":[["prendre une photo de","拍……的照片"],["se prendre en photo","自拍"],["un appareil photo","相机"],["filmer","拍视频"]],"sy":[["photographier","courant","拍照（正式）"],["filmer","courant","拍摄视频"],["shooter","familier","拍照（口语，英语借词）"]],"fq":"高频，日常常用。","me":"prendre + photo：「拿走」一张画面。","tr":{"zh":"你可以给我们拍张照吗？","fr":"Vous pouvez nous prendre en photo ?","alt":"Tu peux nous prendre en photo, s'il te plaît ?","note":"「请帮我们拍张照」用 prendre en photo。"}},
 "Du papier toilette": {"pos":"n.m. 阳性名词，不可数；du 是部分冠词 (de + le)","s":"厕纸；卫生纸。不可数名词，前面常用 du（一些）；数卷数时说 un rouleau de papier toilette。","ipa":"[pa.pje twa.lɛt]","ph":"papier 读 [pa.pje]，ier 读 [je]；toilette 读 [twa.lɛt]，oi 读 [wa]，tt 读 [t]，结尾 e 不发音。","pi":"toilette 的 oi 读 [wa]，结尾 te 里的 t 要发音。papier 是阳性：du papier。","et":"papier 来自拉丁语 papyrus（纸莎草）；toilette 是 toile（布）的小词，原指「小块布」。","ex":[["Il n'y a plus de papier toilette.","没有厕纸了。"],["Peux-tu acheter du papier toilette ?","你可以买点厕纸吗？"]],"co":[["un rouleau de papier toilette","一卷厕纸"],["acheter du papier toilette","买厕纸"],["les toilettes","厕所"],["du papier journal","报纸"]],"sy":[["papier hygiénique","courant","同义，更正式的说法"],["PQ","familier","papier cul 的缩写，口语"],["mouchoir","courant","手帕/纸巾，不是厕纸"]],"fq":"高频，日常购物时常用。","me":"papier（纸）+ toilette（厕所）= 厕纸。","tr":{"zh":"家里没有厕纸了。","fr":"Il n'y a plus de papier toilette à la maison.","alt":"On n'a plus de papier toilette.","note":"否定句：Il n'y a plus de papier toilette（de，不带 du）。"}},
 "Du télétravail": {"pos":"n.m. 阳性名词，不可数；du 是部分冠词","s":"远程办公；在家上班。动词是 télétravailler。常说 faire du télétravail 或 être en télétravail。","ipa":"[te.le.tʁa.vaj]","ph":"té [te]，lé [le]，tra [tʁa]，vail 读 [vaj]：[te.le.tʁa.vaj]。","pi":"-ail 读 [aj]，l 不单独发音；télé- 里两个 é 都读 [e]。","et":"由希腊语前缀 télé-（远）+ travail（工作）构成。travail 来自拉丁语 tripalium。","ex":[["Je fais du télétravail.","我远程办公。"],["Mon entreprise propose deux jours de télétravail par semaine.","我的公司每周有两天远程办公。"]],"co":[["faire du télétravail","远程办公"],["en télétravail","在远程办公"],["un télétravailleur","远程办公者"],["travailler à distance","远程工作"]],"sy":[["travail à distance","courant","更中性的说法"],["travailler de chez soi","courant","在家工作"],["bureau","courant","办公室"]],"fq":"近年高频，办公场景常用。","me":"télé（远）+ travail（工作）= 远处的工作。","tr":{"zh":"每周三我在家办公。","fr":"Le mercredi, je fais du télétravail.","alt":"Le mercredi, je télétravaille.","note":"télétravailler 是动词；le télétravail 是名词。"}},
 "Le design": {"pos":"n.m. 阳性名词，不变；也可作形容词 design（不变）","s":"设计（尤其指产品、工业设计）；形容词用法：un canapé design = 设计感强的沙发。","ipa":"[di.zajn]","ph":"读 [di.zajn]：d [d]，i [i]，s 读 [z]，ign 读 [ajn]（像英语 sign）。","pi":"来自英语，但读音是法语式的 [di.zajn]：不是 [de.zin]。s 读 [z]。","et":"来自英语 design，英语又来自意大利语 disegno（图样、设计）。","ex":[["Il étudie le design.","他学设计。"],["J'aime le design de ce fauteuil.","我喜欢这把扶手椅的设计。"]],"co":[["le design industriel","工业设计"],["un / une designer","设计师"],["le design graphique","平面设计"],["un objet design","设计感强的物件"]],"sy":[["conception","soutenu","设计；构思"],["stylisme","courant","时装设计"],["dessin","courant","图画；设计图"]],"fq":"中高频，学科/产品场景常见。","me":"design 保留英语拼写，读音接近英语 [di.zajn]。","tr":{"zh":"她在艺术学校学设计。","fr":"Elle étudie le design dans une école d'art.","alt":"Elle fait du design dans une école d'art.","note":"作形容词时不变：des lampes design。"}},
 "Le journalisme": {"pos":"n.m. 阳性名词，不可数","s":"新闻学；新闻工作。学科、行业都可说 le journalisme。从业者是 un(e) journaliste。","ipa":"[ʒuʁ.na.lism]","ph":"j [ʒ]，our [uʁ]，na [na]，lisme 读 [lism]：s 读 [s]，e 不发音。","pi":"j 读 [ʒ]，像「日」；结尾 isme 读 [ism]，不读 [izm]。journal 是「日报」，也有「日记」之意。","et":"来自 journal，journal 来自拉丁语 diurnalis（每日的）+ 后缀 -isme。","ex":[["Elle étudie le journalisme.","她学新闻。"],["Le journalisme demande beaucoup de rigueur.","新闻工作需要很严谨。"]],"co":[["une école de journalisme","新闻学院"],["un journaliste / une journaliste","记者"],["le journalisme d'investigation","调查性报道"],["un journal","报纸；日记"]],"sy":[["presse","courant","新闻界；报刊"],["reportage","courant","报道"],["média","courant","媒体"]],"fq":"中频，学校 / 职业场景。","me":"journal（报纸）+ isme：与报纸有关的行业。","tr":{"zh":"我想成为记者，所以学新闻。","fr":"Je veux devenir journaliste, alors j'étudie le journalisme.","alt":"Je veux être journaliste, donc je fais du journalisme.","note":"journalisme 是名词；journalistique 是形容词。"}},
 "Le lycée": {"pos":"n.m. 阳性名词，复数 lycées","s":"高中（法国 15–18 岁）。法国学校顺序：école（小学）、collège（初中）、lycée（高中）。lycée 不是「大学」。","ipa":"[li.se]","ph":"ly [li]，cée [se]：é 读 [e]，结尾的 e 不单独发音。","pi":"y 读 [i]；ce 在 é 前读 [s]；注意 lycée 里没有 [k]。","et":"来自希腊语 Lykeion（亚里士多德的学园），拿破仑时代（1802）起指中学。","ex":[["Il est au lycée.","他读高中。"],["Mon fils entre au lycée en septembre.","我儿子九月上高中。"]],"co":[["un lycéen / une lycéenne","高中生"],["un lycée professionnel","职业高中"],["aller au lycée","上高中"],["le collège","初中"]],"sy":[["école","courant","学校（泛指）"],["collège","courant","初中（11–15 岁）"],["fac","familier","大学"]],"fq":"高频，学校场景。","me":"lycée 读作「里塞」，是法国 15–18 岁学生上学的地方。","tr":{"zh":"我妹妹明年上高中。","fr":"Ma sœur entre au lycée l'année prochaine.","alt":"L'année prochaine, ma sœur va au lycée.","note":"说「在高中」用 au lycée。"}},
 "Un amphithéâtre": {"pos":"n.m. 阳性名词，复数 amphithéâtres","s":"阶梯教室；大教室；古罗马圆形剧场。大学里常说缩写 un amphi。cours en amphi = 在大教室上课。","ipa":"[ɑ̃.fi.te.ɑtʁ]","ph":"am 读 [ɑ̃]，phi 读 [fi]（ph = f），thé 读 [te]（th = t），âtre 读 [ɑtʁ]。","pi":"ph 读 [f]，th 读 [t]；â 读 [ɑ]，是长音；结尾 -tre 的 e 不发音。","et":"来自希腊语 amphi（周围）+ theatron（剧场），意为四周都是座位的剧场。","ex":[["Le cours est dans l'amphithéâtre.","课在阶梯教室。"],["L'amphithéâtre est plein d'étudiants.","阶梯教室里坐满了学生。"]],"co":[["un amphi","大阶梯教室（口语）"],["un cours en amphi","大课"],["un amphithéâtre romain","罗马斗兽场"],["l'amphithéâtre de la faculté","学院的大教室"]],"sy":[["amphi","familier","口语缩写"],["salle de cours","courant","教室"],["salle de conférence","courant","会议厅"]],"fq":"中频，大学场景。","me":"amphi（四周）+ théâtre（剧场）：四周有座位的教室。","tr":{"zh":"明天上午大课在阶梯教室。","fr":"Le cours est dans l'amphithéâtre demain matin.","alt":"Demain matin, on a cours en amphi.","note":"口语常用缩写 amphi；阳性：un amphi。"}},
 "Un campus": {"pos":"n.m. 阳性名词，复数 campus（单复数同形）","s":"校园；大学园区。le campus 指大学占地与设施的总体，法国也常有「campus」分散在城市郊区。","ipa":"[kɑ̃.pys]","ph":"cam 读 [kɑ̃]，pus 读 [pys]：u 读 [y]，结尾 s 要读出来。","pi":"结尾的 s 发音（[kɑ̃.pys]），这是少数拉丁语词尾 s 发音的例子；u 读 [y]。","et":"拉丁语 campus（田野、平地），经美国英语 campus 重新进入法语。","ex":[["Le campus est grand.","校园很大。"],["Les étudiants habitent sur le campus.","学生们住在校园里。"]],"co":[["sur le campus","在校园里"],["la vie du campus","校园生活"],["un campus universitaire","大学校园"],["la bibliothèque du campus","校园图书馆"]],"sy":[["université","courant","大学（机构）"],["cité universitaire","courant","大学宿舍区"],["fac","familier","大学"]],"fq":"中频，大学场景。","me":"campus 像英语，但 u 要圆唇读 [y]。","tr":{"zh":"我住在校园里，离教室很近。","fr":"J'habite sur le campus, près des salles de cours.","alt":"Je vis sur le campus, pas loin des cours.","note":"说「在校园」用 sur le campus，不用 dans。"}},
 "Un chauffeur": {"pos":"n.m. 阳性名词，复数 chauffeurs（女司机可说 une chauffeuse，较少用）","s":"司机，尤其是职业司机（出租车、公交、私人司机）。普通开车的人叫 un conducteur。","ipa":"[ʃo.fœʁ]","ph":"ch [ʃ]，au [o]，ff 读单个 [f]，eur 读 [œʁ]：[ʃo.fœʁ]。","pi":"ch 读 [ʃ]；au 读 [o]；eur 的 r 要读，是喉音。","et":"来自动词 chauffer（加热）：早期蒸汽车 / 蒸汽机的司炉工叫 chauffeur。","ex":[["Le chauffeur de bus est là.","公交司机在这里。"],["Mon père est chauffeur de taxi.","我爸爸是出租车司机。"]],"co":[["un chauffeur de taxi / de bus","出租车 / 公交司机"],["un chauffeur routier","货车司机"],["un chauffeur privé","私人司机"],["chauffer","加热"]],"sy":[["conducteur","courant","驾驶者（一般司机）"],["pilote","courant","飞行员 / 赛车手"],["routier","courant","长途货车司机"]],"fq":"高频，日常常用。","me":"chauffer（加热）→ chauffeur：以前负责「烧锅炉」的人。","tr":{"zh":"出租车司机很友好。","fr":"Le chauffeur de taxi est sympa.","alt":"Le chauffeur de taxi est très gentil.","note":"指职业司机用 chauffeur；一般开车的人用 conducteur。"}},
 "Un diplôme": {"pos":"n.m. 阳性名词，复数 diplômes","s":"文凭；学位证书。diplômé(e) = 已毕业的人。法国还有 le baccalauréat（高中毕业文凭，缩写 le bac）、la licence、le master。","ipa":"[di.plom]","ph":"di [di]，plô [plo]，me [m]：ô 读 [o]，结尾 e 不发音：[di.plom]。","pi":"ô 读 [o]（长音），不要读成 [ɔ]；注意结尾的 me 不发 e，所以 diplôme 只有三个音节组：di-plôm。","et":"来自希腊语 diploma（折叠成两层的纸），经拉丁语 diploma 进入法语。","ex":[["J'ai mon diplôme.","我拿到了文凭。"],["Il a un diplôme d'ingénieur.","他有工程师文凭。"]],"co":[["obtenir un diplôme","拿到文凭"],["un diplôme universitaire","大学文凭"],["être diplômé(e) de","毕业于"],["la remise des diplômes","毕业典礼"]],"sy":[["titre","courant","学衔，资格"],["licence","courant","学士学位"],["certificat","courant","证书"]],"fq":"高频，学业/求职场景。","me":"diplôme：di + plôme，像 diploma 去掉 a。","tr":{"zh":"她去年拿到了大学文凭。","fr":"Elle a obtenu son diplôme universitaire l'année dernière.","alt":"Elle a eu son diplôme l'an dernier.","note":"diplôme 阳性，注意拼写 ô。"}},
 "Un master": {"pos":"n.m. 阳性名词，复数 masters","s":"硕士(学位或课程)，法国大学 licence 之后的两年（M1, M2）。读音是法语式 [mas.tɛʁ]，不是英语 [mæstər]。","ipa":"[mas.tɛʁ]","ph":"m [m]，as 读 [as]，ter 读 [tɛʁ]：[mas.tɛʁ]，r 要读出来。","pi":"结尾的 -er 读 [ɛʁ]，不是 [e]（与 parler 的 -er 不同）；r 要发音。","et":"来自英语 master，英语来自拉丁语 magister（老师，主人）。","ex":[["Il fait un master.","他读硕士。"],["Elle a un master en droit.","她有法学硕士学位。"]],"co":[["faire un master","读硕士"],["un master en droit / en lettres","法学 / 文学硕士"],["un master 1 / un master 2","硕士一年级 / 二年级"],["la licence","学士学位"]],"sy":[["maîtrise","courant","旧制硕士（四年级）"],["bac +5","familier","读完五年高等教育"],["doctorat","courant","博士学位"]],"fq":"中高频，大学场景。","me":"master 去掉英语味，读 [mas.tɛʁ]。","tr":{"zh":"我正在读经济学硕士。","fr":"Je fais un master en économie.","alt":"Je suis en master d'économie.","note":"faire un master = 读硕士；les études vont de la licence (L1–L3) au master (M1–M2)。"}},
 "Un poste": {"pos":"n.m. 阳性名词，复数 postes","s":"职位；岗位；也指「设备」：un poste de télévision = 电视机，un poste de radio = 收音机。注意 la poste（阴性）= 邮局。","ipa":"[pɔst]","ph":"po 读 [pɔ]，ste 读 [st]：[pɔst]，s 读 [s]，e 不发音。","pi":"阳性 le poste = 职位/机器；阴性 la poste = 邮局，别混淆。","et":"来自意大利语 posto，拉丁语 positus（放置的）。","ex":[["J'ai un nouveau poste.","我有新职位。"],["Il cherche un poste à Lyon.","他在找里昂的职位。"]],"co":[["un poste de travail","工作岗位"],["occuper un poste","担任职位"],["un poste de télévision","电视机"],["un poste de police","警察局"]],"sy":[["emploi","courant","工作（总称）"],["travail","courant","工作"],["fonction","soutenu","职务"]],"fq":"高频，求职场景。","me":"poste：被「放置」的位置，也就是岗位。","tr":{"zh":"我想申请这个职位。","fr":"Je voudrais postuler à ce poste.","alt":"J'aimerais postuler pour ce poste.","note":"le poste（职位）≠ la poste（邮局）。"}},
 "Un restaurant universitaire": {"pos":"n.m. 阳性名词，复数 restaurants universitaires","s":"大学食堂，学生吃便宜午餐的地方。口语常缩写成 un resto U 或 le RU。核心词是 restaurant（餐厅），universitaire 是形容词，跟着 restaurant 用阳性。","ipa":"[ʁɛs.to.ʁɑ̃ y.ni.vɛʁ.si.tɛʁ]","ph":"restaurant 里 au 读 [o]，-ant 读鼻音 [ɑ̃]，结尾 t 不发；universitaire 里 u 读 [y]，-aire 读 [ɛʁ]。","pi":"restaurant 结尾的 -ant 是鼻音，t 不发音。u 是 [y]（嘴唇圆，发「于」），别读成 [u]。","et":"restaurant 来自动词 restaurer（使恢复体力）；universitaire 来自 université（大学），源于拉丁语 universitas。","ex":[["Je mange au restaurant universitaire.","我在大学食堂吃饭。"],["Le repas au resto U coûte trois euros.","食堂的一顿饭只要三欧元。"]],"co":[["manger au resto U","在学生食堂吃饭"],["un ticket de restaurant universitaire","食堂饭票"],["la carte d'étudiant","学生证（常用来刷食堂）"]],"sy":[["resto U","familier","最常用的口语缩写"],["cantine","courant","食堂（学校、公司都可用）"]],"fq":"对学生极高频，日常常用。","me":"RU = Restaurant Universitaire，学生一天三欧元的救星。","tr":{"zh":"中午我和朋友们在大学食堂吃饭。","fr":"À midi, je mange au restaurant universitaire avec mes amis.","alt":"Ce midi, on mange au resto U avec les copains.","note":"去某个地方吃饭用 manger à/au + 地点。"}},
 "Un salaire": {"pos":"n.m. 阳性名词，复数 salaires","s":"工资，薪水（通常指每月固定拿到的钱）。说「月薪」用 le salaire mensuel，说「工资高」用 un bon salaire / un salaire élevé。","ipa":"[sa.lɛʁ]","ph":"s 在词首读 [s]；-aire 读 [ɛʁ]，结尾 r 要发。","pi":"结尾 -aire 读 [ɛʁ]，不要念成「撒拉瑞」；注意是阳性：un salaire。","et":"来自拉丁语 salarium，与 sal（盐）有关，传说是古罗马士兵领的「盐钱」。","ex":[["Le salaire est bon.","工资不错。"],["Elle reçoit son salaire à la fin du mois.","她月底领工资。"]],"co":[["un salaire mensuel","月薪"],["le salaire minimum","最低工资"],["gagner un bon salaire","挣高工资"],["une augmentation de salaire","加薪"]],"sy":[["paie","courant","发薪；工资单上的钱"],["rémunération","soutenu","报酬（正式用语）"],["revenu","courant","收入（不一定是工资）"]],"fq":"高频，工作话题必备。","me":"salaire ← sal（盐）：古人拿盐当工资。","tr":{"zh":"我的工资不高，但我喜欢这份工作。","fr":"Mon salaire n'est pas élevé, mais j'aime mon travail.","alt":"Je ne gagne pas beaucoup, mais j'aime mon travail.","note":"「工资高」可说 un salaire élevé；口语常用动词 gagner。"}},
 "Un secrétariat": {"pos":"n.m. 阳性名词，复数 secrétariats","s":"秘书处；办公室；行政办公室（学校、医院、公司里负责接待和文件的地方）。在大学里 le secrétariat 是办手续、领证明的窗口。也指秘书这一工作。","ipa":"[sə.kʁe.ta.ʁja]","ph":"se- 读弱元音 [sə]；é 读 [e]；-ia 读 [ja]，结尾 t 不发。","pi":"结尾 -at 的 t 不发音；-iat 读 [ja]，不是「亚特」。第一音节 se 读 [sə]。","et":"来自 secrétaire（秘书）加后缀 -at。secrétaire 源于拉丁语 secretarius，意为「知道秘密的人」，与 secret 同源。","ex":[["Le secrétariat est ouvert.","办公室开门了。"],["Vous pouvez déposer votre dossier au secrétariat.","您可以把材料交到办公室。"]],"co":[["aller au secrétariat","去办公室"],["le secrétariat de l'université","大学教务办公室"],["les horaires du secrétariat","办公室开放时间"]],"sy":[["bureau","courant","办公室（更宽泛）"],["accueil","courant","前台，接待处"]],"fq":"中频，学校和办公场景常见。","me":"secret + -aire：知道秘密的人，坐在办公室里。","tr":{"zh":"请把文件交到秘书处。","fr":"Merci de déposer le document au secrétariat.","alt":"Déposez le document au secrétariat, s'il vous plaît.","note":"到某处办事用 au secrétariat（à + le）。"}},
 "Un stage": {"pos":"n.m. 阳性名词，复数 stages","s":"实习；见习；短期培训班。学生去公司实习就是 faire un stage。也可指一段进修或体育培训营，如 un stage de théâtre。","ipa":"[staʒ]","ph":"st- 连读 [st]；a 读 [a]；g 在 e 前读 [ʒ]，结尾的 e 不发。","pi":"结尾 e 不发音，整个词只有一个音节 [staʒ]。别和英语 stage（舞台）混淆，法语 stage 不指舞台。","et":"来自古法语 estage（住处、停留），引申为一段见习期。","ex":[["Il fait un stage.","他在实习。"],["Je cherche un stage de trois mois.","我在找一个三个月的实习。"]],"co":[["faire un stage","实习；参加培训"],["chercher un stage","找实习"],["un stage en entreprise","企业实习"],["un stagiaire / une stagiaire","实习生"]],"sy":[["apprentissage","courant","学徒期（时间更长、有工资）"],["formation","courant","培训（更宽泛）"]],"fq":"对学生高频，日常常用。","me":"stage 和 stagiaire（实习生）一起记。","tr":{"zh":"夏天我要在一家法国公司实习。","fr":"Cet été, je vais faire un stage dans une entreprise française.","alt":"Cet été, je fais un stage dans une boîte française.","note":"实习固定搭配 faire un stage；boîte 是 entreprise 的口语说法。"}},
 "Un voyage": {"pos":"n.m. 阳性名词，复数 voyages","s":"旅行；旅程。指整个出行的过程，可近可远。aimer voyager 是「喜欢旅行」（动词）；说「去旅行」用 partir en voyage 或 faire un voyage。","ipa":"[vwa.jaʒ]","ph":"v 是 [v]；oy 读 [wa.j]，即 [vwa.jaʒ]；g 在 e 前读 [ʒ]，结尾 e 不发。","pi":"oy 读 [waj]，不是「沃以」；结尾 e 不发，重音落在最后一个音节。","et":"来自拉丁语 viaticum（旅途所需的粮食、盘缠），与 voie（路）同源。","ex":[["J'aime le voyage.","我喜欢旅行。"],["Ils partent en voyage demain.","他们明天出发去旅行。"],["Bon voyage !","一路平安！旅途愉快！"]],"co":[["faire un voyage","旅行"],["partir en voyage","出发去旅行"],["un voyage en train / en avion","坐火车 / 飞机的旅行"],["Bon voyage !","旅途愉快！"]],"sy":[["trajet","courant","路程（A 到 B 的一段路，强调具体路线）"],["séjour","courant","逗留（在某地待一段时间）"],["périple","littéraire","长途冒险旅行"]],"fq":"极高频，日常常用。","me":"voy- 就是「路」：voie → voyage → voyager。","tr":{"zh":"这次去意大利的旅行很棒。","fr":"Ce voyage en Italie est super.","alt":"Ce voyage en Italie, c'était génial.","note":"voyage 是阳性，所以用 ce voyage。"}},
 "L'économie": {"pos":"n.f. 阴性名词，复数 économies","s":"经济；经济学。一个国家的 l'économie 是经济，在大学学的 l'économie 是经济学。复数 des économies 还有「积蓄、节省」的意思，如 faire des économies（省钱）。","ipa":"[e.kɔ.nɔ.mi]","ph":"l'économie 中 l' 与词首元音省音；é 读 [e]；两个 o 都读开口的 [ɔ]；结尾 ie 读 [i]。","pi":"重音落在最后音节 [mi]；注意拼写有重音符 é，不是 e。","et":"来自希腊语 oikonomia（家务管理），由 oikos（家）+ nomos（规则）构成。","ex":[["L'économie est intéressante.","经济学很有趣。"],["L'économie française va bien.","法国经济状况不错。"],["Je fais des économies pour voyager.","我攒钱去旅行。"]],"co":[["faire des études d'économie","学经济学"],["l'économie mondiale","世界经济"],["faire des économies","省钱，攒钱"],["un économiste","经济学家"]],"sy":[["finances","courant","财政，资金"],["épargne","soutenu","储蓄"]],"fq":"高频，学习和新闻中常见。","me":"oikos（家）+ nomos（管理）= 管好一个家的学问。","tr":{"zh":"我在大学学经济学。","fr":"J'étudie l'économie à l'université.","alt":"Je fais de l'économie à la fac.","note":"学科前用 l'économie（单数加定冠词）；口语 la fac 是大学。"}},
 "L'informatique": {"pos":"n.f. 阴性名词，只用单数","s":"信息学；计算机科学；信息技术。既可指一门学科，也可泛指电脑相关的行业。注意不是「电脑」本身，电脑是 un ordinateur。","ipa":"[ɛ̃.fɔʁ.ma.tik]","ph":"in- 读鼻音 [ɛ̃]；o 读 [ɔ]；r 要发 [ʁ]；结尾 -ique 读 [ik]，e 不发。","pi":"开头的 in 读鼻音 [ɛ̃]，不是 [in]；结尾 -que 读 [k]。","et":"1962 年由 information + automatique 合成的新词。","ex":[["J'aime l'informatique.","我喜欢计算机科学。"],["Il travaille dans l'informatique.","他在 IT 行业工作。"]],"co":[["faire de l'informatique","学计算机；搞 IT"],["un ingénieur en informatique","计算机工程师"],["un cours d'informatique","计算机课"],["un informaticien","IT 人员"]],"sy":[["numérique","courant","数字技术（更广）"],["IT","familier","来自英语，口语和职场中也能听到"]],"fq":"高频，日常常用。","me":"information + automatique = informatique。","tr":{"zh":"我的哥哥在信息技术行业工作。","fr":"Mon frère travaille dans l'informatique.","alt":"Mon frère bosse dans l'informatique.","note":"在某个行业工作用 dans + 定冠词；bosser 是 travailler 的口语。"}},
 "L'organisation": {"pos":"n.f. 阴性名词，复数 organisations","s":"组织；安排；条理。既可指一个机构（une organisation internationale），也可指把事情安排得好不好（Quelle organisation !）。","ipa":"[ɔʁ.ɡa.ni.za.sjɔ̃]","ph":"g 读 [ɡ]；s 在两个元音间读 [z]；-tion 读 [sjɔ̃]，结尾鼻化。","pi":"s 读 [z]；结尾 -tion 读 [sjɔ̃]，不是 [ʃən]。","et":"来自动词 organiser，源于 organe（器官），再往上是希腊语 organon（工具）。","ex":[["L'organisation est bonne.","组织得很好。"],["Il travaille pour une organisation humanitaire.","他为一个人道主义组织工作。"]],"co":[["une organisation internationale","国际组织"],["l'organisation d'un événement","活动的组织"],["une organisation non gouvernementale (ONG)","非政府组织"]],"sy":[["association","courant","协会，社团"],["structure","courant","机构，结构"]],"fq":"高频，日常和新闻中常见。","me":"organ + -isation：把各部分「器官」安排好。","tr":{"zh":"这个活动的组织很棒。","fr":"L'organisation de cet événement est super.","alt":"C'est très bien organisé, cet événement.","note":"organisation 是阴性名词；super 在口语中不变化。"}},
 "L'UNICEF": {"pos":"n.f. 阴性名词（专有名词，缩写）","s":"联合国儿童基金会，专门帮助世界各地儿童的国际组织。原名 United Nations International Children's Emergency Fund，现在正式名称是 United Nations Children's Fund，但缩写保留。作为机构常用 l'UNICEF，也可写 l'Unicef。","ipa":"[y.ni.sɛf]","ph":"U 读 [y]；ni 读 [ni]；ce 读 [sɛ]，最后 F 读 [f]，整个词读成一个词，不逐字母读。","pi":"u 读 [y]；c 在 i 与 e 之间读 [s]；缩写要当词读，不要念字母。","et":"缩写自英语 United Nations International Children's Emergency Fund，1946 年成立。","ex":[["Elle travaille pour l'UNICEF.","她为联合国儿童基金会工作。"],["L'UNICEF aide les enfants dans le monde.","联合国儿童基金会帮助世界各地的儿童。"]],"co":[["travailler pour l'UNICEF","为联合国儿童基金会工作"],["un don à l'UNICEF","给联合国儿童基金会的捐款"]],"sy":[["ONU","courant","联合国（UNICEF 的上级机构）"],["ONG","courant","非政府组织"]],"fq":"专有名词，新闻中常见。","me":"Uni-cef：像「uni（联合）」+ 一个简称。","tr":{"zh":"我姐姐在联合国儿童基金会工作。","fr":"Ma sœur travaille à l'UNICEF.","alt":"Ma sœur bosse pour l'UNICEF.","note":"表示在某机构工作用 travailler à 或 travailler pour。"}},
 "La pharmacie": {"pos":"n.f. 阴性名词，复数 pharmacies","s":"药房；药学。买药去 la pharmacie，学药学也说 la pharmacie（faire des études de pharmacie）。药剂师是 un pharmacien / une pharmacienne。","ipa":"[faʁ.ma.si]","ph":"ph 读 [f]；c 在 i 前读 [s]；结尾 ie 读 [i]。","pi":"ph 读 [f]，不是 [p]+[h]；结尾 -cie 读 [si]。","et":"来自希腊语 pharmakon（药、毒药），经拉丁语传入。","ex":[["Il fait des études de pharmacie.","他学药学。"],["Il y a une pharmacie près de la gare.","火车站附近有一家药房。"]],"co":[["aller à la pharmacie","去药房"],["une pharmacie de garde","值班药房"],["faire des études de pharmacie","学药学"]],"sy":[["drogue","courant","毒品，不是药，容易混淆"],["médicament","courant","药（一种药，不是药房）"]],"fq":"高频，日常常用。","me":"ph = f：farmacie 的感觉，药房的绿色十字。","tr":{"zh":"我要去药房买点药。","fr":"Je vais à la pharmacie acheter des médicaments.","alt":"Je passe à la pharmacie pour prendre des médicaments.","note":"去某地做某事：aller à + 地点 + 不定式，中间不用连词。"}},
 "Une année de césure": {"pos":"n.f. 阴性名词，复数 années de césure","s":"间隔年：学生在学业中间暂停一年，用来旅行、实习、做志愿者等，之后再回学校。césure 本义是「中断」。","ipa":"[a.ne də se.zyʁ]","ph":"année 读 [a.ne]；de 读 [də]；césure 的 s 在元音间读 [z]，u 读 [y]，结尾 r 要发。","pi":"césure 里 s 读 [z]；u 是 [y]。année 是 [a.ne]，有两个 n 但只发一个 [n]。","et":"césure 来自拉丁语 caesura（砍、切断）。année 来自拉丁语 annata，源于 annus（年）。","ex":[["Il fait une année de césure.","他休学一年。"],["Pendant ma césure, je voyage en Asie.","休学期间，我去亚洲旅行。"]],"co":[["faire une année de césure","休学一年（间隔年）"],["prendre une année de césure","休一个间隔年"],["une césure dans ses études","学业中的间断"]],"sy":[["gap year","familier","英语借词，年轻人常说"],["pause","courant","休息，暂停"]],"fq":"中频，学生话题常见。","me":"césure = 在学业里「切一刀」，停一年。","tr":{"zh":"毕业前，我想休学一年去旅行。","fr":"Avant mon diplôme, je veux faire une année de césure pour voyager.","alt":"Avant la fin de mes études, je veux prendre une année de césure.","note":"pour + 不定式表示目的；vouloir 后接不定式。"}},
 "Une entrée": {"pos":"n.f. 阴性名词，复数 entrées","s":"入口；进入；门票；（餐饮）前菜。入口 = l'entrée du bâtiment；前菜 = l'entrée（相对 le plat principal 主菜）；电影或演出的入场券也可叫 une entrée。","ipa":"[ɑ̃.tʁe]","ph":"en 读鼻音 [ɑ̃]；tr 连读 [tʁ]；-ée 读 [e]。","pi":"en 读鼻音 [ɑ̃]，别发出 n；-ée 的 e 读 [e]，结尾 e 不发。","et":"来自动词 entrer，源于拉丁语 intrare。","ex":[["Où est l'entrée de ce bâtiment ?","这栋楼的入口在哪里？"],["Comme entrée, je prends une salade.","前菜我要一份沙拉。"]],"co":[["l'entrée principale","正门"],["Entrée libre","免费入场"],["l'entrée, le plat, le dessert","前菜、主菜、甜点"],["payer l'entrée","付门票"]],"sy":[["porte","courant","门"],["sortie","courant","出口（反义）"]],"fq":"极高频，日常常用。","me":"entrer → entrée：前菜就是「进入」一餐。","tr":{"zh":"入口在右边。","fr":"L'entrée est à droite.","alt":"L'entrée, c'est sur la droite.","note":"à droite 是「在右边」；反义词是 la sortie。"}},
 "Une entreprise": {"pos":"n.f. 阴性名词，复数 entreprises","s":"公司；企业。可大可小，比 société 更泛。口语里常说 une boîte（公司，较随意）。也可指「事业；尝试」，但 A1 阶段主要记「公司」。","ipa":"[ɑ̃.tʁə.pʁiz]","ph":"en 读鼻音 [ɑ̃]；e 读弱元音 [ə]；pr 连读；-ise 读 [iz]（s 读 [z]）。","pi":"结尾 -ise 读 [iz]，不是 [is]；en 是鼻音。注意是阴性：une entreprise。","et":"entre + prise：来自 entreprendre（承担、着手做）的过去分词名词。","ex":[["C'est une grande entreprise.","这是一家大公司。"],["Il travaille dans une petite entreprise.","他在一家小公司工作。"]],"co":[["créer une entreprise","创办公司"],["une entreprise française","法国公司"],["travailler dans une entreprise","在公司工作"],["un chef d'entreprise","企业主"]],"sy":[["société","courant","公司（法律上）"],["boîte","familier","公司（口语）"],["compagnie","soutenu","公司（多用于保险、航空）"]],"fq":"极高频，工作话题必备。","me":"entre + prise：抓住机会去「着手」的地方。","tr":{"zh":"我的朋友在一家大公司工作。","fr":"Mon ami travaille dans une grande entreprise.","alt":"Mon pote bosse dans une grosse boîte.","note":"grande 是 grand 的阴性；口语里用 grosse boîte。"}},
 "Une équipe": {"pos":"n.f. 阴性名词，复数 équipes","s":"团队；小组；运动队。工作中的 une équipe 是团队，体育里是球队（l'équipe de France）。一起工作的人叫 coéquipier。","ipa":"[e.kip]","ph":"é 读 [e]；qu 读 [k]；i 读 [i]；p 读 [p]；结尾 e 不发。","pi":"qu 读 [k]，不读 [kw]；整个词是两个音节 [e.kip]。拼写开头有重音符 é。","et":"来自动词 équiper（装备）。更早的起源不确定，一般认为与北欧语的「船」有关，这里不下定论。","ex":[["C'est une bonne équipe.","这是一支好团队。"],["L'équipe de France joue ce soir.","法国队今晚比赛。"]],"co":[["travailler en équipe","团队合作"],["un chef d'équipe","组长"],["l'esprit d'équipe","团队精神"],["une équipe de football","足球队"]],"sy":[["groupe","courant","小组，团体"],["staff","familier","英语借词，指团队"]],"fq":"高频，工作和体育中常见。","me":"équipe 与 équiper（装备）一起记。","tr":{"zh":"我们的团队很棒。","fr":"Notre équipe est super.","alt":"On a une super équipe.","note":"on a 在口语中等于 nous avons。"}},
 "Une formation": {"pos":"n.f. 阴性名词，复数 formations","s":"培训；教育；专业训练；形成。formation professionnelle = 职业培训；avoir une formation en droit = 受过法律方面的训练。也可指「队形、形成」。","ipa":"[fɔʁ.ma.sjɔ̃]","ph":"o 读 [ɔ]；r 读 [ʁ]；-tion 读 [sjɔ̃]，结尾鼻化。","pi":"-tion 读 [sjɔ̃]；o 是开口 [ɔ]。别和英语 formation（队形）混淆，法语里多指培训。","et":"来自拉丁语 formatio，源于 forma（形状）。同族词：former, information。","ex":[["Je fais une formation.","我在参加培训。"],["Elle a une formation d'infirmière.","她受过护士培训。"]],"co":[["faire une formation","参加培训"],["la formation professionnelle","职业培训"],["la formation continue","继续教育"],["suivre une formation","上培训课"]],"sy":[["stage","courant","培训班；实习"],["cours","courant","课"],["éducation","courant","教育（更广）"]],"fq":"高频，工作和学习中常见。","me":"former = 塑造一个人，formation 就是「塑造」。","tr":{"zh":"我这个月参加了一次培训。","fr":"Ce mois-ci, je fais une formation.","alt":"Ce mois-ci, je suis en formation.","note":"être en formation = 在培训中，更口语。"}},
 "Une licence": {"pos":"n.f. 阴性名词，复数 licences","s":"（法国）大学学士学位，通常三年（bac+3）。也指某些许可证或执照（如体育 licence sportive），但最常用的就是学士学位。","ipa":"[li.sɑ̃s]","ph":"l 读 [l]；i 读 [i]；c 在 e 前读 [s]；en 读鼻音 [ɑ̃]；结尾 ce 读 [s]。","pi":"-ence 在这里读 [ɑ̃s]，不是 [ɛns]；别和英语 licence（执照）完全混用。","et":"来自拉丁语 licentia（许可，权限），与 licite 同族。","ex":[["Elle a une licence en droit.","她有法学学士学位。"],["Je prépare une licence d'histoire.","我在读历史学士。"]],"co":[["avoir une licence de droit","有法学学士学位"],["préparer une licence","读学士学位"],["passer une licence","攻读学士"],["une licence professionnelle","职业学士学位"]],"sy":[["master","courant","硕士（licence 之后的阶段）"],["diplôme","courant","文凭（更广）"]],"fq":"对学生高频。","me":"licence = 三年之后「被允许」毕业。","tr":{"zh":"她有经济学学士学位。","fr":"Elle a une licence d'économie.","alt":"Elle est titulaire d'une licence d'économie.","note":"学位后接专业：licence de/d' + 学科。"}},
 "Une pause": {"pos":"n.f. 阴性名词，复数 pauses","s":"休息；暂停。工作、课间的短暂休息就是 une pause。la pause déjeuner 是午休；la pause-café 是咖啡休息。也可指暂停键。","ipa":"[poz]","ph":"au 读 [o]；s 在两个元音间读 [z]；结尾 e 不发。","pi":"s 读 [z]，不是 [s]；au 读 [o]；整个词只有一个音节。","et":"来自拉丁语 pausa，源自希腊语 pausis（停止）。","ex":[["Je fais une pause.","我休息一下。"],["On prend une pause de dix minutes ?","我们休息十分钟好吗？"]],"co":[["faire une pause","休息一下"],["la pause déjeuner","午休"],["une pause-café","咖啡休息"],["appuyer sur pause","按暂停键"]],"sy":[["repos","courant","休息（较长、较放松）"],["break","familier","英语借词，年轻人口语"],["récré","familier","课间休息（小学生用语）"]],"fq":"极高频，日常常用。","me":"pause 在英语里也是 pause：停下来。","tr":{"zh":"我们先休息十分钟吧。","fr":"Faisons une pause de dix minutes.","alt":"On fait une petite pause de dix minutes ?","note":"Faisons 是 faire 的 nous 命令式，表示「我们……吧」。"}},
 "Une personne âgée": {"pos":"n.f. 阴性名词，复数 personnes âgées","s":"老年人。这是礼貌、中性的说法，男女都用 une personne âgée，名词 personne 永远是阴性。âgée 是形容词，跟着阴性变化。比 vieux 更客气。","ipa":"[pɛʁ.sɔn a.ʒe]","ph":"personne 读 [pɛʁ.sɔn]，结尾 -nne 的 e 不发；âgée 读 [a.ʒe]，â 读 [a]，g 在 é 前读 [ʒ]。","pi":"personne 和 âgée 之间不连读；âgée 的 g 读 [ʒ]。personne 即使指男人也是阴性。","et":"personne 来自拉丁语 persona（面具、角色）；âgé 来自 âge，源于古法语 aage。","ex":[["J'aide une personne âgée.","我帮助一位老人。"],["Les personnes âgées ont une place réservée.","老年人有专座。"]],"co":[["aider une personne âgée","帮助老人"],["une maison de retraite","养老院"],["les personnes âgées","老年人（复数）"]],"sy":[["senior","courant","老年人（更委婉、更商业）"],["vieux / vieille","familier","老人（可能不太礼貌）"],["aîné(e)","soutenu","年长者"]],"fq":"高频，日常和新闻中常见。","me":"personne âgée = 「有岁数的人」，比 vieux 温和。","tr":{"zh":"我在公交车上给一位老人让座。","fr":"Dans le bus, je laisse ma place à une personne âgée.","alt":"Dans le bus, je cède ma place à une personne âgée.","note":"céder sa place = 让座，更正式；laisser sa place 更口语。"}},
 "Une résidence (étudiante)": {"pos":"n.f. 阴性名词，复数 résidences","s":"学生宿舍；公寓楼。une résidence étudiante / universitaire 是专给学生住的公寓。résidence 也可泛指居住地，如 résidence principale（主要住所）。","ipa":"[ʁe.zi.dɑ̃s]","ph":"r 读 [ʁ]；é 读 [e]；s 在两个元音间读 [z]；-ence 读 [ɑ̃s]。","pi":"s 读 [z]；-ence 读 [ɑ̃s]，不是 [ɛns]。étudiante 里的 e 读 [e]。","et":"来自拉丁语 residentia，源于 residere（住下来）。同族词：résider, résident。","ex":[["Il habite dans une résidence.","他住在宿舍。"],["Ma résidence étudiante est près du campus.","我的学生公寓离校园很近。"]],"co":[["habiter en résidence étudiante","住学生公寓"],["une résidence universitaire","大学宿舍"],["la résidence principale","主要住所"],["une chambre en résidence","宿舍房间"]],"sy":[["foyer","courant","宿舍，青年之家"],["cité U","familier","大学城宿舍的口语说法"],["internat","courant","寄宿学校宿舍"]],"fq":"对学生高频。","me":"résider（住）→ résidence，意思就是「住的地方」。","tr":{"zh":"我在学生宿舍里有一个小房间。","fr":"J'ai une petite chambre dans une résidence étudiante.","alt":"J'ai une petite chambre à la cité U.","note":"dans 表示在某个建筑内；à 常与 cité U 搭配。"}},
 "Une réunion": {"pos":"n.f. 阴性名词，复数 réunions","s":"会议；聚会。工作中的 une réunion 是开会；朋友聚会也可用。La Réunion 首字母大写则是法国海外省留尼汪岛。","ipa":"[ʁe.y.njɔ̃]","ph":"r 读 [ʁ]；é 读 [e]；u 读 [y]；-ion 读 [njɔ̃]。é 和 u 之间要分开读，不连。","pi":"é 和 u 要分开读成两个音节 [e.y]；-ion 读 [njɔ̃]，鼻化。","et":"由 ré- + union 构成，来自动词 réunir（再次聚集）。","ex":[["J'ai une réunion ce matin.","今早我有个会议。"],["La réunion commence à dix heures.","会议十点开始。"]],"co":[["avoir une réunion","有会议"],["être en réunion","正在开会"],["une réunion de famille","家庭聚会"],["organiser une réunion","组织会议"]],"sy":[["rendez-vous","courant","约会，预约"],["rencontre","courant","见面，碰面"],["séance","soutenu","会议，场次"]],"fq":"极高频，工作话题必备。","me":"ré + union = 再一次「合」在一起。","tr":{"zh":"我现在在开会，晚点给你回电话。","fr":"Je suis en réunion, je te rappelle plus tard.","alt":"Là, je suis en réunion, je te rappelle tout à l'heure.","note":"être en réunion = 正在开会；rappeler = 回电话。"}},
 "Une salle de classe/cours": {"pos":"n.f. 阴性名词，复数 salles de classe / salles de cours","s":"教室。salle de classe 多用于中小学，salle de cours 常见于大学。口语也直接说 une salle。salle 本身是「房间，大厅」，常和别的词组合：salle de bains, salle à manger。","ipa":"[sal də klas]","ph":"salle 读 [sal]，ll 只发一个 [l]，结尾 e 不发；de 读 [də]；classe 读 [klas]。","pi":"salle 的结尾 e 不发，ll 读一个 [l]；classe 的 ss 读 [s]，e 不发。","et":"salle 来自法兰克语 sala（大厅）；classe 来自拉丁语 classis（类别）。","ex":[["La salle de classe est petite.","教室很小。"],["Le cours est dans la salle 204.","课在 204 教室。"]],"co":[["la salle de classe","（中小学）教室"],["la salle de cours","（大学）教室"],["la salle des profs","教师休息室"],["en salle","在教室里"]],"sy":[["classe","courant","班级；教室"],["amphi","familier","大阶梯教室"],["salle","courant","房间"]],"fq":"高频，学习话题必备。","me":"salle（大厅）+ classe（班）= 上课的大厅。","tr":{"zh":"教室里有三十个学生。","fr":"Il y a trente élèves dans la salle de classe.","alt":"Ils sont trente dans la classe.","note":"il y a 表示「有」；中小学用 élève，大学生用 étudiant。"}},
 "Des horaires": {"pos":"n.m.pl. 阳性复数名词，单数 un horaire","s":"时间表；工作时间；营业时间；班次。商店营业时间是 les horaires d'ouverture；火车班次是 les horaires de train。单数 un horaire 也是阳性。","ipa":"[ɔ.ʁɛʁ]","ph":"h 不发音；o 读 [ɔ]；r 读 [ʁ]；-aire 读 [ɛʁ]，结尾 s 不发。","pi":"h 不发音，所以可以连读（les horaires 读 [le.zɔ.ʁɛʁ]）；-aires 的 s 不发。","et":"来自拉丁语 hora（时间，小时）的形容词形式 horaire。同族词：heure。","ex":[["Quelles sont vos horaires de travail ?","你们的工作时间是什么？"],["Les horaires d'ouverture sont sur la porte.","营业时间写在门上。"]],"co":[["les horaires d'ouverture","营业时间"],["les horaires de train","火车时刻表"],["des horaires flexibles","弹性工作时间"],["un emploi du temps","课程表，日程表"]],"sy":[["emploi du temps","courant","课程表，日程"],["planning","courant","计划表（来自英语）"],["heures","courant","时间，小时"]],"fq":"高频，日常常用。","me":"horaire ← hora（小时）：每个小时的安排。","tr":{"zh":"这家商店的营业时间是什么？","fr":"Quels sont les horaires d'ouverture de ce magasin ?","alt":"Le magasin est ouvert de quelle heure à quelle heure ?","note":"horaire 是阳性，所以用 quels（阳性复数）。"}},
 "Des produits de beauté": {"pos":"n.m.pl. 阳性复数名词，单数 un produit de beauté","s":"美容产品，化妆品和护肤品的总称。主要词是 produit（阳性），所以 des produits。也说 des cosmétiques，或更口语的 du maquillage（彩妆）。","ipa":"[pʁɔ.dɥi də bo.te]","ph":"produits 里 -its 不发 t、s；ui 读 [ɥi]；de 读 [də]；beauté 里 eau 读 [o]，é 读 [e]。","pi":"produits 结尾的 t 和 s 都不发音；ui 读 [ɥi]，注意不是 [wi]；beauté 是 [bo.te]。","et":"produit 来自拉丁语 productum（produire 的过去分词）；beauté 来自拉丁语 bellus，经古法语 beauté。","ex":[["Elle achète des produits de beauté.","她买美容产品。"],["Ce magasin vend des produits de beauté naturels.","这家店卖天然美容产品。"]],"co":[["acheter des produits de beauté","买美容产品"],["un magasin de produits de beauté","美妆店"],["des produits de beauté bio","有机美容产品"]],"sy":[["cosmétiques","courant","化妆品"],["maquillage","courant","彩妆"],["soins","courant","护理用品"]],"fq":"中频，购物话题常见。","me":"produit + beauté = 让你变美的商品。","tr":{"zh":"我妹妹喜欢买美容产品。","fr":"Ma sœur aime acheter des produits de beauté.","alt":"Ma sœur adore les produits de beauté.","note":"aimer + 不定式；adorer 比 aimer 更强。"}},
 "Le travail / Le bureau": {"pos":"n.m. 阳性名词，travail 复数 travaux，bureau 复数 bureaux","s":"travail = 工作；劳动；作业。bureau = 办公室；办公桌。aller au travail 是去上班，aller au bureau 是去办公室。travail 的复数 travaux 指「工程、作业」，如 des travaux dans la rue。","ipa":"[tʁa.vaj] / [by.ʁo]","ph":"travail：-ail 读 [aj]，结尾 l 不单独发；bureau：u 读 [y]，eau 读 [o]。","pi":"travail 结尾 -ail 读 [aj]，不是 [ail]；bureau 里 u 读 [y]，别读 [u]。复数不规则：travaux, bureaux。","et":"travail 一般认为来自拉丁语 tripalium，说法有争议，来源不完全确定；bureau 来自 bure（粗呢布），指盖在桌上的布，后来指桌子再指办公室。","ex":[["Je dois aller au bureau.","我得去办公室。"],["Mon travail est intéressant.","我的工作很有趣。"]],"co":[["aller au travail","去上班"],["être au bureau","在办公室"],["chercher du travail","找工作"],["un bureau de poste","邮局"]],"sy":[["emploi","courant","职位，工作岗位"],["boulot","familier","活儿，工作"],["poste","courant","职位"]],"fq":"极高频，日常常用。","me":"travail → travaux，bureau → bureaux：词尾 -x 的复数。","tr":{"zh":"我今天要去办公室工作。","fr":"Aujourd'hui, je vais travailler au bureau.","alt":"Aujourd'hui, je bosse au bureau.","note":"travail 是名词，travailler 是动词，不要混。"}},
 "Les mathématiques (les maths)": {"pos":"n.f.pl. 阴性复数名词，常简写为 les maths","s":"数学。法语的 mathématiques 总是复数，有 s：les mathématiques。日常口语几乎都说 les maths。数学家是 un mathématicien，数学老师是 un prof de maths。","ipa":"[ma.te.ma.tik]","ph":"a 读 [a]；é 读 [e]；-ique 读 [ik]，e 不发；maths 读 [mat]，ths 的 h 不发，s 不发。","pi":"maths 只读 [mat]，不读 [maθ]；th 读 [t]，结尾 s 不发。别忘了总是复数。","et":"来自希腊语 mathēmatikē（学习，知识），经拉丁语传入法语。","ex":[["J'aime les maths.","我喜欢数学。"],["Elle est forte en mathématiques.","她数学很好。"]],"co":[["faire des maths","学数学；做数学题"],["être fort(e) en maths","数学好"],["un cours de maths","数学课"],["un prof de maths","数学老师"]],"sy":[["maths","familier","口语简称"],["calcul","courant","计算"],["arithmétique","soutenu","算术"]],"fq":"极高频，学习话题必备。","me":"maths 读 [mat]，像「马特」。","tr":{"zh":"我数学不太好。","fr":"Je ne suis pas très fort en maths.","alt":"Je suis nul en maths.","note":"说「数学好」用 être fort(e) en maths；nul 是「很差」，比较口语。"}},
 "Les sciences": {"pos":"n.f.pl. 阴性复数名词，单数 la science","s":"科学；理科。les sciences 泛指理科，如 les sciences naturelles（自然科学）；la science 单数则更强调「科学」本身。学科：les sciences humaines（人文科学）。","ipa":"[sjɑ̃s]","ph":"sc 在 i 前读 [s]；ie 读 [j]；en 读鼻音 [ɑ̃]；结尾 ce 读 [s]。","pi":"sc 在这里读 [s]，不读 [sk]；-ience 读 [jɑ̃s]。","et":"来自拉丁语 scientia（知识），源于 scire（知道）。","ex":[["Elle étudie les sciences.","她学科学。"],["Les sciences sont mon sujet préféré.","理科是我最喜欢的科目。"]],"co":[["les sciences naturelles","自然科学"],["les sciences humaines","人文科学"],["les sciences politiques","政治学"],["un scientifique","科学家"]],"sy":[["matière","courant","学科，科目"],["connaissance","courant","知识"]],"fq":"高频，学习话题常见。","me":"science ← scire（知道）：知识。","tr":{"zh":"我儿子很喜欢理科。","fr":"Mon fils aime beaucoup les sciences.","alt":"Mon fils adore les sciences.","note":"喜欢一类东西，用复数加定冠词：les sciences。"}},
 "Un agriculteur / Une agricultrice": {"pos":"n. 名词，阳性 agriculteur / 阴性 agricultrice，复数 agriculteurs / agricultrices","s":"农民；农场主。比 paysan 更正式、更现代，是官方职业名称。男性 un agriculteur，女性 une agricultrice。","ipa":"[a.ɡʁi.kyl.tœʁ]","ph":"g 读 [ɡ]；u 读 [y]；-eur 读 [œʁ]；阴性 -trice 读 [tʁis]。","pi":"-eur 读 [œʁ]，和 -euse 一样的元音；阴性变化是 -teur → -trice。","et":"来自拉丁语 agricola，由 ager（田地）和 colere（耕种）构成。","ex":[["Il est agriculteur.","他是农民。"],["Mon grand-père était agriculteur.","我爷爷以前是农民。"]],"co":[["être agriculteur","务农"],["une exploitation agricole","农场"],["l'agriculture biologique","有机农业"]],"sy":[["paysan","courant","农民，带乡土意味"],["fermier","courant","农场主，租地的人"],["cultivateur","soutenu","种田的人"]],"fq":"中频，职业话题常见。","me":"agri（田）+ culteur（耕种者）。","tr":{"zh":"我叔叔是农民，他有一个农场。","fr":"Mon oncle est agriculteur, il a une ferme.","alt":"Mon oncle travaille la terre, il a une ferme.","note":"说职业时，être 后不加冠词：Il est agriculteur。"}},
 "Un comédien / Une comédienne": {"pos":"n. 名词，阳性 comédien / 阴性 comédienne，复数 comédiens / comédiennes","s":"演员（尤指话剧、影视演员）。comédien 不只是喜剧演员，而是通用的「演员」。「喜剧人」可说 un humoriste。acteur / actrice 也是演员，更常指影视。","ipa":"[kɔ.me.djɛ̃]","ph":"c 读 [k]；o 读 [ɔ]；é 读 [e]；-dien 读 [djɛ̃]，结尾 n 不发；阴性 -dienne 读 [djɛn]。","pi":"阴性 comédienne 读 [kɔ.me.djɛn]，n 要发；阳性是鼻音 [djɛ̃]。别以为只是「喜剧演员」。","et":"来自 comédie（喜剧，戏剧），源于希腊语 kōmōidia，加后缀 -ien。","ex":[["Elle est comédienne.","她是演员。"],["Ce comédien joue au théâtre.","这位演员在剧院演出。"]],"co":[["être comédien / comédienne","当演员"],["un comédien de théâtre","戏剧演员"],["devenir comédien","成为演员"]],"sy":[["acteur / actrice","courant","演员（更常指影视）"],["artiste","courant","艺术家，艺人"],["humoriste","courant","喜剧人"]],"fq":"中频，职业和文化话题常见。","me":"comédien ← comédie：演戏的人。","tr":{"zh":"我姐姐是演员，她在巴黎的剧院演出。","fr":"Ma sœur est comédienne, elle joue dans un théâtre à Paris.","alt":"Ma sœur est actrice, elle joue au théâtre à Paris.","note":"jouer 表示演出；comédienne 双 n。"}},
 "Un directeur / Une directrice": {"pos":"n. 名词，阳性 directeur / 阴性 directrice，复数 directeurs / directrices","s":"主任；校长；总监；经理。学校里指校长（le directeur de l'école），公司里指部门主管或总监。le directeur général 是总经理。","ipa":"[di.ʁɛk.tœʁ]","ph":"di 读 [di]；r 读 [ʁ]；e 读 [ɛ]；c 读 [k]；-eur 读 [œʁ]；阴性 -trice 读 [tʁis]。","pi":"阴性是 directrice，不是 directeuse；-eur 读 [œʁ]，结尾 r 要发。","et":"来自拉丁语 director，源于 dirigere（引导，指挥）。同族词：diriger, direction。","ex":[["Le directeur est sympa.","校长人很好。"],["La directrice de l'entreprise est italienne.","公司的总监是意大利人。"]],"co":[["le directeur de l'école","校长"],["le directeur général","总经理"],["voir le directeur","去见主任"],["une directrice des ressources humaines","人力资源总监"]],"sy":[["chef","courant","领导，主管"],["patron","familier","老板"],["responsable","courant","负责人"]],"fq":"高频，工作和学校话题常见。","me":"diriger（指挥）→ directeur：负责指挥的人。","tr":{"zh":"校长想和你谈谈。","fr":"Le directeur veut te parler.","alt":"Le directeur voudrait te parler.","note":"voudrait 比 veut 更礼貌。"}},
 "Un email / courriel": {"pos":"n.m. 阳性名词，复数 emails / courriels","s":"电子邮件。email（也写 e-mail）是英语借词，法国最常用；courriel 是官方推荐、魁北克常用的说法。口语里还常说 un mail。都是阳性。","ipa":"[i.mɛl] / [kuʁ.jɛl]","ph":"email：e 读 [i]，ai 读 [ɛ]，l 读 [l]；courriel：ou 读 [u]，rr 读 [ʁ]，-iel 读 [jɛl]。","pi":"email 的 e 读 [i]（和英语相似）；不要把 émail（珐琅）混进来。courriel 里 rr 只读一个 [ʁ]。","et":"email ← 英语 e-mail；courriel 由 courrier（信件）+ électronique（电子的）合成，是魁北克创造的新词。","ex":[["J'envoie un email.","我发一封邮件。"],["Elle a reçu un courriel du directeur.","她收到了主任的邮件。"]],"co":[["envoyer un email","发邮件"],["recevoir un email","收邮件"],["une adresse email","电子邮件地址"],["répondre à un email","回复邮件"]],"sy":[["mail","familier","邮件的口语说法"],["courriel","courant","官方、魁北克说法"],["message","courant","消息"]],"fq":"极高频，日常常用。","me":"courriel = courrier + électronique。","tr":{"zh":"我给老师发了一封邮件。","fr":"J'ai envoyé un email au professeur.","alt":"J'ai envoyé un mail au prof.","note":"envoyer qqch à qqn：用 à 引出收件人。"}},
 "Un informaticien / Une informaticienne": {"pos":"n. 名词，阳性 informaticien / 阴性 informaticienne，复数 informaticiens / informaticiennes","s":"IT 人员；计算机专业人员；程序员。是对做电脑和软件相关工作的人的总称。具体的程序员常说 un développeur。","ipa":"[ɛ̃.fɔʁ.ma.ti.sjɛ̃]","ph":"in 读鼻音 [ɛ̃]；-ti- 在这里读 [ti]（不是 [si]）；-cien 读 [sjɛ̃]；阴性 -cienne 读 [sjɛn]。","pi":"-cien 读 [sjɛ̃]；阴性要双 n，读 [sjɛn]，n 要发音。","et":"由 informatique + -ien 构成，意为「搞 informatique 的人」。","ex":[["Il est informaticien.","他是 IT 工作者。"],["Elle est informaticienne dans une banque.","她是银行的 IT 人员。"]],"co":[["devenir informaticien","成为 IT 人员"],["un informaticien indépendant","自由职业 IT 人员"],["appeler l'informaticien","叫 IT 人员来"]],"sy":[["développeur / développeuse","courant","开发人员，程序员"],["ingénieur informatique","courant","计算机工程师"],["geek","familier","电脑迷"]],"fq":"中频，职业话题常见。","me":"informatique + -ien = 搞电脑的人。","tr":{"zh":"我哥哥是 IT 人员，他在一家大公司工作。","fr":"Mon frère est informaticien, il travaille dans une grande entreprise.","alt":"Mon frère est dans l'informatique, il bosse dans une grosse boîte.","note":"职业名词做表语时不加冠词。"}},
 "Un métier / Un travail": {"pos":"n.m. 阳性名词，métier 复数 métiers，travail 复数 travaux","s":"métier = 职业；行当；手艺（强调某一类专业工作）；travail = 工作（强调正在做的事或岗位）。问职业可以说 Quel est votre métier ? 或 Vous faites quoi dans la vie ?","ipa":"[me.tje] / [tʁa.vaj]","ph":"métier：é 读 [e]，-ier 读 [je]，结尾 r 不发，所以是 [me.tje]；travail 读 [tʁa.vaj]。","pi":"métier 的 r 不发音，读 [me.tje]；travail 的复数 travaux 不规则。","et":"métier 来自拉丁语 ministerium（服务，职务），古法语 mestier。travail 来源有争议，常见解释是拉丁语 tripalium，但不完全确定。","ex":[["C'est un bon métier.","这是份好工作。"],["Quel est ton métier ?","你的职业是什么？"]],"co":[["choisir un métier","选择职业"],["exercer un métier","从事一个职业"],["un métier d'avenir","有前途的职业"],["trouver un travail","找到工作"]],"sy":[["profession","soutenu","职业（表格中常见）"],["emploi","courant","职位，岗位"],["boulot","familier","工作，活儿"]],"fq":"极高频，日常常用。","me":"métier = 你的「行当」；travail = 你「做的事」。","tr":{"zh":"你想做什么职业？","fr":"Quel métier veux-tu faire ?","alt":"Tu veux faire quoi comme métier ?","note":"faire un métier 常用来说「从事某职业」。"}},
 "Un vendeur / Une vendeuse": {"pos":"n. 名词，阳性 vendeur / 阴性 vendeuse，复数 vendeurs / vendeuses","s":"售货员；店员；销售。在商店里卖东西的人。vendeur 只指卖东西的人，不是「出售者」这个宽泛概念。阴性 vendeuse。","ipa":"[vɑ̃.dœʁ]","ph":"v 读 [v]；en 读鼻音 [ɑ̃]；d 读 [d]；-eur 读 [œʁ]；阴性 -euse 读 [øz]。","pi":"vendeur 读 [vɑ̃.dœʁ]，en 是鼻音；阴性 vendeuse 的元音是 [ø]，s 读 [z]，和阳性不同。","et":"来自动词 vendre，源于拉丁语 vendere，加后缀 -eur。","ex":[["Le vendeur est occupé.","售货员很忙。"],["La vendeuse m'aide à choisir.","售货员帮我挑选。"]],"co":[["un vendeur dans un magasin","商店里的售货员"],["une vendeuse de vêtements","服装店女店员"],["demander au vendeur","问售货员"]],"sy":[["commerçant(e)","courant","商人，店主"],["employé(e)","courant","职员"],["caissier / caissière","courant","收银员"]],"fq":"中频，购物和职业话题常见。","me":"vendre → vendeur：卖东西的人。","tr":{"zh":"售货员帮我找到了合适的鞋子。","fr":"La vendeuse m'a aidé à trouver les bonnes chaussures.","alt":"La vendeuse m'a trouvé les bonnes chaussures.","note":"aider qqn à + 不定式；à 引出后面的动作。"}},
 "Une visioconférence / visio / zoom / appel vidéo": {"pos":"n.f. 阴性名词，复数 visioconférences","s":"视频会议；视频通话。visioconférence 是完整的正式说法；visio 是常用简称（une visio）；zoom 来自软件名，口语常用来指任何视频会议；appel vidéo 是视频通话。","ipa":"[vi.zjo.kɔ̃.fe.ʁɑ̃s]","ph":"vi 读 [vi]；s 在元音间读 [z]；io 读 [jo]；con 读鼻音 [kɔ̃]；fé 读 [fe]；rence 读 [ʁɑ̃s]。","pi":"visio 里的 s 读 [z]；conférence 的 on 和 en 是不同的鼻音 [ɔ̃] 和 [ɑ̃]。","et":"由 visio-（视觉，来自拉丁语 visio）+ conférence（会议）合成，是现代词。","ex":[["J'ai une visio à 10h.","我十点有个视频会议。"],["Nous faisons la réunion en visioconférence.","我们用视频会议开会。"]],"co":[["faire une visio","开视频会议"],["en visioconférence","通过视频会议"],["un appel vidéo","视频通话"],["lancer un zoom","发起视频会议（口语）"]],"sy":[["visio","familier","visioconférence 的简称"],["zoom","familier","借用软件名"],["appel vidéo","courant","视频通话"]],"fq":"近年高频，工作和学习中常见。","me":"visio（视）+ conférence（会议）= 看着开会。","tr":{"zh":"我们下午用视频会议开会吧。","fr":"On fait la réunion en visio cet après-midi.","alt":"On se retrouve en visioconférence cet après-midi.","note":"en visio = 通过视频会议。"}},
 "Un(e) collègue": {"pos":"n.m./n.f. 阴阳同形名词，复数 collègues","s":"同事。阴阳同形：un collègue（男同事）、une collègue（女同事），形式不变，只换冠词。也可指同行、同伴。","ipa":"[kɔ.lɛɡ]","ph":"c 读 [k]；o 读 [ɔ]；è 读 [ɛ]；-gue 中 g 读 [ɡ]，ue 不发。","pi":"-gue 读 [ɡ]，u 不发；è 读 [ɛ]。不要把 collège（中学）读混：collège 是 [kɔ.lɛʒ]。","et":"来自拉丁语 collega，由 con-（一起）+ legare（派遣）构成，意思是「一同被派遣的人」。","ex":[["Mon collègue est sympa.","我的同事很友好。"],["Elle déjeune avec ses collègues.","她和同事们一起吃午饭。"]],"co":[["un collègue de travail","工作同事"],["mes collègues de bureau","我办公室的同事"],["un collègue de bureau","办公室同事"]],"sy":[["camarade","courant","同学，同伴"],["ami(e)","courant","朋友"],["confrère / consœur","soutenu","同行"]],"fq":"极高频，工作话题必备。","me":"collègue 与 collège（中学）只差一个字母：g-u-e 和 g-e。","tr":{"zh":"我的同事们今天都很忙。","fr":"Mes collègues sont très occupés aujourd'hui.","alt":"Mes collègues sont débordés aujourd'hui.","note":"collègues 复数时形容词也要加 s。"}},
 "Un(e) journaliste": {"pos":"n.m./n.f. 阴阳同形名词，复数 journalistes","s":"记者；新闻工作者。阴阳同形：un journaliste（男记者）、une journaliste（女记者）。journal 是报纸，journaliste 是为报纸、电视、网站写报道的人。","ipa":"[ʒuʁ.na.list]","ph":"j 读 [ʒ]；ou 读 [u]；r 读 [ʁ]；-iste 读 [ist]，结尾 e 不发。","pi":"j 读 [ʒ]，不是 [dʒ]；-iste 读 [ist]，不读成 [iːst]。","et":"来自 journal（报纸，日报），源于 jour（日），加后缀 -iste。","ex":[["Il est journaliste.","他是记者。"],["Cette journaliste travaille pour la télévision.","这位女记者为电视台工作。"]],"co":[["être journaliste","当记者"],["un journaliste sportif","体育记者"],["interviewer un journaliste","采访记者"],["un journaliste de télévision","电视记者"]],"sy":[["reporter","courant","外勤记者"],["correspondant","courant","驻外记者"],["chroniqueur","soutenu","专栏作者"]],"fq":"高频，职业和新闻话题常见。","me":"journal（日报）+ -iste = 写日报的人。","tr":{"zh":"我妈妈是记者，她写关于文化的文章。","fr":"Ma mère est journaliste, elle écrit des articles sur la culture.","alt":"Ma mère est journaliste, elle écrit sur la culture.","note":"职业名词做表语时不加冠词。"}},
 "Un(e) libraire": {"pos":"n.m./n.f. 阴阳同形名词，复数 libraires","s":"书店店主或店员；卖书的人。不要和 une librairie（书店）混淆。un libraire / une libraire 指人，la librairie 指店。图书馆是 une bibliothèque，不是 librairie。","ipa":"[li.bʁɛʁ]","ph":"l 读 [l]；i 读 [i]；b 读 [b]；r 读 [ʁ]；-aire 读 [ɛʁ]。","pi":"librairie 是书店，bibliothèque 是图书馆，别把 libraire 当成 library。","et":"来自拉丁语 librarius（与书有关的），源于 liber（书）。","ex":[["Le libraire est gentil.","书商很友好。"],["La libraire me conseille un roman.","女书店员向我推荐一本小说。"]],"co":[["demander conseil au libraire","向书店员请教"],["devenir libraire","成为书店经营者"],["la librairie du quartier","街区书店"]],"sy":[["bibliothécaire","courant","图书管理员"],["vendeur / vendeuse","courant","售货员"]],"fq":"中频，职业话题常见。","me":"libraire = 卖 livres 的人，不是借书的 bibliothèque。","tr":{"zh":"书店员推荐我读这本书。","fr":"Le libraire m'a conseillé de lire ce livre.","alt":"Le libraire m'a recommandé ce livre.","note":"conseiller à qqn de + 不定式：建议某人做某事。"}},
 "Un(e) photographe": {"pos":"n.m./n.f. 阴阳同形名词，复数 photographes","s":"摄影师。阴阳同形：un photographe、une photographe。若指照片本身，用 une photo。常说 un photographe de mariage（婚礼摄影师）。","ipa":"[fɔ.tɔ.ɡʁaf]","ph":"ph 读 [f]；o 读 [ɔ]；g 在 r 前读 [ɡ]；结尾 -phe 读 [f]，e 不发。","pi":"ph 读 [f]，不是 [p]；-graphe 的 g 读 [ɡ]，r 要发。重音落在最后一个音节。","et":"来自希腊语 phōs（光）+ graphein（写、画），即「用光书写的人」。","ex":[["Elle est photographe.","她是摄影师。"],["Le photographe prend des photos du mariage.","摄影师为婚礼拍照。"]],"co":[["être photographe","当摄影师"],["un photographe de mariage","婚礼摄影师"],["un photographe professionnel","专业摄影师"],["prendre des photos","拍照"]],"sy":[["photographe","courant","摄影师"],["photographe amateur","courant","业余摄影师"],["reporter-photographe","courant","摄影记者"]],"fq":"中频，职业话题常见。","me":"photo（光）+ graphe（写）= 用光写字。","tr":{"zh":"她是摄影师，她拍了很多美丽的照片。","fr":"Elle est photographe, elle prend beaucoup de belles photos.","alt":"Elle est photographe, elle fait de très belles photos.","note":"beaucoup de + 名词；形容词 belles 在名词前。"}},
 "Découvrir": {"pos":"v. 动词，第三组，复合时态用 avoir，过去分词 découvert","s":"发现；探索；了解到。découvrir un pays 是「发现、游览一个国家」；découvrir que… 是「发现……（事实）」。变位：je découvre, nous découvrons, j'ai découvert，变位方式和 ouvrir 相同。","ipa":"[de.ku.vʁiʁ]","ph":"dé 读 [de]；cou 读 [ku]；-vrir 读 [vʁiʁ]，结尾 r 要发。","pi":"结尾 -ir 读 [iʁ]，r 要发；过去分词是 découvert，t 不发，读 [de.ku.vɛʁ]。变位像 ouvrir，不是 finir。","et":"由 dé-（去除）+ couvrir（盖住）构成，字面是「揭开」。","ex":[["Je veux découvrir le monde.","我想探索世界。"],["Il a découvert un nouveau café.","他发现了一家新咖啡馆。"]],"co":[["découvrir un pays","了解一个国家"],["découvrir la vérité","发现真相"],["découvrir que…","发现……"],["à découvrir","值得一看，有待发现"]],"sy":[["trouver","courant","找到"],["explorer","courant","探索"],["apprendre","courant","得知"]],"fq":"高频，旅行和学习中常见。","me":"dé + couvrir = 把盖子揭开，于是「发现」。","tr":{"zh":"这个夏天，我们要去发现一座新城市。","fr":"Cet été, nous allons découvrir une nouvelle ville.","alt":"Cet été, on va visiter une nouvelle ville.","note":"aller + 不定式表示近将来。"}},
 "Discuter": {"pos":"v. 动词，第一组 -er，复合时态用 avoir","s":"讨论；聊天；争论。discuter avec qqn 是「和某人聊」；discuter de qqch 是「谈论某事」。口语里也有「争吵」的意思，要看语境。","ipa":"[dis.ky.te]","ph":"di 读 [di]；s 读 [s]；cu 读 [ky]，u 是 [y]；结尾 -er 读 [e]。","pi":"u 读 [y]；-er 读 [e]，r 不发；变位 je discute, tu discutes, nous discutons。","et":"来自拉丁语 discutere（打碎，分开），引申为分析、讨论。","ex":[["Nous aimons discuter.","我们喜欢聊天。"],["On discute de ce projet demain.","我们明天讨论这个项目。"]],"co":[["discuter avec quelqu'un","和某人交谈"],["discuter de quelque chose","讨论某事"],["en discuter","谈这件事"],["On en discute ?","我们聊聊这个？"]],"sy":[["parler","courant","说话"],["bavarder","familier","闲聊"],["débattre","soutenu","辩论"]],"fq":"高频，日常常用。","me":"discuter ≈ 英语 discuss，但还有「聊天」的意思。","tr":{"zh":"我们晚上聊聊这个问题吧。","fr":"On discute de ce problème ce soir ?","alt":"Parlons-en ce soir.","note":"discuter de + 名词 = 谈论某事。"}},
 "Durer": {"pos":"v. 动词，第一组 -er，复合时态用 avoir","s":"持续；延续；耐用。主语多是事物：Le film dure deux heures. 问「持续多久」用 Combien de temps ça dure ? 也可用来说东西耐用。","ipa":"[dy.ʁe]","ph":"d 读 [d]；u 读 [y]；r 读 [ʁ]；-er 读 [e]。","pi":"u 读 [y]，不是 [u]；-er 结尾读 [e]；durer 只用于第三人称最多：ça dure, ça dure longtemps。","et":"来自拉丁语 durare（坚持，持续），与 dur（硬的）同族。","ex":[["Ce film dure longtemps.","这部电影持续很久。"],["Le cours dure une heure.","这节课持续一小时。"]],"co":[["durer longtemps","持续很久"],["Ça dure combien de temps ?","这要持续多久？"],["ne pas durer","不会持久"],["la durée","持续时间"]],"sy":[["continuer","courant","继续"],["se prolonger","courant","延长"],["tenir","courant","经久，撑住"]],"fq":"高频，日常常用。","me":"durer 与 dur（硬）同族：撑得久才「硬」。","tr":{"zh":"这次会议持续两个小时。","fr":"La réunion dure deux heures.","alt":"La réunion va durer deux heures.","note":"durer 后直接接时间，不加介词 pendant。"}},
 "Lire": {"pos":"v. 动词，第三组，复合时态用 avoir，过去分词 lu","s":"读；阅读。变位不规则：je lis, tu lis, il lit, nous lisons, vous lisez, ils lisent；过去分词 lu：j'ai lu。lire un livre / un journal / un message。","ipa":"[liʁ]","ph":"l 读 [l]；i 读 [i]；r 读 [ʁ]；整个词一个音节。","pi":"je lis 的 s 不发，读 [li]；vous lisez 的 s 读 [z]；复合时态 j'ai lu，不是 j'ai lis。","et":"来自拉丁语 legere（采集，读）。同族词：lecture, lecteur, légende。","ex":[["J'aime lire des livres.","我喜欢读书。"],["Elle lit le journal tous les matins.","她每天早上读报纸。"]],"co":[["lire un livre","读一本书"],["lire à voix haute","大声朗读"],["lire entre les lignes","读出言外之意"],["lire un message","看消息"]],"sy":[["parcourir","courant","浏览"],["feuilleter","courant","翻阅"],["bouquiner","familier","读书（口语）"]],"fq":"极高频，日常常用。","me":"lire → lecture：读出来的内容。","tr":{"zh":"我每天晚上读一个小时书。","fr":"Je lis pendant une heure tous les soirs.","alt":"Tous les soirs, je lis une heure.","note":"pendant + 时长表示持续的时间。"}},
 "Organiser": {"pos":"v. 动词，第一组 -er，复合时态用 avoir","s":"组织；安排；筹办。organiser une fête / une réunion / un voyage。反身形式 s'organiser 是「安排好自己的事」。","ipa":"[ɔʁ.ɡa.ni.ze]","ph":"o 读 [ɔ]；g 读 [ɡ]；s 在元音间读 [z]；-er 读 [e]。","pi":"s 读 [z]，不是 [s]；-er 结尾读 [e]，r 不发。","et":"来自 organe（器官），源于希腊语 organon（工具）；字面意思是把各部分排好，使其成为一个整体。","ex":[["Nous allons organiser une fête.","我们要办一个派对。"],["Il organise son voyage en Italie.","他在安排去意大利的旅行。"]],"co":[["organiser une fête","办派对"],["organiser une réunion","组织会议"],["s'organiser","安排好自己"],["bien organisé(e)","有条理的"]],"sy":[["préparer","courant","准备"],["arranger","courant","安排，整理"],["planifier","soutenu","制定计划"]],"fq":"高频，日常常用。","me":"organ（器官）+ -iser：让各部分井然有序。","tr":{"zh":"我们周末要办一个小聚会。","fr":"Nous allons organiser une petite fête ce week-end.","alt":"On organise une petite soirée ce week-end.","note":"organiser 是及物动词，直接接宾语。"}},
 "Présenter": {"pos":"v. 动词，第一组 -er，复合时态用 avoir","s":"介绍；展示；呈现。présenter qqn à qqn = 把某人介绍给某人；présenter un projet = 汇报项目。反身形式 se présenter = 自我介绍；注意不要和英语 present（礼物）混淆。","ipa":"[pʁe.zɑ̃.te]","ph":"pr 读 [pʁ]；é 读 [e]；s 读 [z]；en 读鼻音 [ɑ̃]；-er 读 [e]。","pi":"s 读 [z]；en 读鼻音 [ɑ̃]；-er 结尾 r 不发。présent 作形容词/名词是「在场的、现在」。","et":"来自拉丁语 praesentare（使在场），源于 praesens。同族词：présent, présentation。","ex":[["Je vais présenter mon projet.","我要介绍我的项目。"],["Je te présente ma sœur.","我给你介绍一下我姐姐。"]],"co":[["présenter un projet","介绍、汇报项目"],["présenter quelqu'un à quelqu'un","把某人介绍给某人"],["se présenter","自我介绍"],["Je vous présente…","我来介绍……"]],"sy":[["montrer","courant","展示"],["introduire","soutenu","引入"],["exposer","soutenu","陈述，展出"]],"fq":"高频，日常常用。","me":"présent（在场）→ présenter：让人「在场」，介绍给你。","tr":{"zh":"我来介绍一下我的新同事。","fr":"Je vous présente mon nouveau collègue.","alt":"Voici mon nouveau collègue.","note":"介绍人时用 Je te / vous présente…。"}},
 "Téléphoner (à)": {"pos":"v. 动词，第一组 -er，间接及物（téléphoner à qqn），复合时态用 avoir","s":"打电话（给某人）。téléphoner à qqn：打电话给某人，用 à，不能直接加宾语。「给他打电话」是 Je lui téléphone，不是 Je le téléphone。","ipa":"[te.le.fɔ.ne]","ph":"té 读 [te]；lé 读 [le]；pho 读 [fɔ]；-ner 读 [ne]。五个音节，ph 读 [f]。","pi":"间接宾语：téléphoner à + 人，用 lui / leur，不用 le / la。ph 读 [f]。","et":"由希腊语 tēle（远）+ phōnē（声音）构成，téléphone 的动词形式。","ex":[["Je dois téléphoner à ma mère.","我得给妈妈打电话。"],["Elle téléphone à son ami tous les soirs.","她每天晚上给朋友打电话。"]],"co":[["téléphoner à quelqu'un","给某人打电话"],["Je lui téléphone.","我给他 / 她打电话。"],["téléphoner de son bureau","在办公室打电话"],["un coup de téléphone","一个电话"]],"sy":[["appeler","courant","打电话给（直接及物，appeler qqn）"],["passer un coup de fil","familier","打个电话"]],"fq":"高频，日常常用。","me":"tele（远）+ phone（声音）：隔着远处的声音。","tr":{"zh":"我晚上给奶奶打电话。","fr":"Ce soir, je téléphone à ma grand-mère.","alt":"Ce soir, j'appelle ma grand-mère.","note":"appeler 是直接宾语，téléphoner 要加 à。"}},
 "Terminer": {"pos":"v. 动词，第一组 -er，复合时态用 avoir","s":"结束；完成；做完。terminer son travail = 做完工作；terminer à + 时间 = 在……结束。也可用 se terminer（事物自身结束）：Le cours se termine à midi.","ipa":"[tɛʁ.mi.ne]","ph":"t 读 [t]；e 读 [ɛ]；r 读 [ʁ]；mi 读 [mi]；-er 读 [ne]。","pi":"-er 结尾读 [e]，r 不发；变位时词干 termin- 不变：je termine, nous terminons。","et":"来自拉丁语 terminare，源于 terminus（边界，终点）。同族词：terme, terminal。","ex":[["Je dois terminer mon travail.","我得完成工作。"],["Le film se termine à minuit.","电影午夜结束。"]],"co":[["terminer son travail","完成工作"],["terminer ses études","完成学业"],["se terminer","结束"],["terminer de + infinitif","做完……"]],"sy":[["finir","courant","完成，结束（更常用）"],["achever","soutenu","完成，使圆满结束"],["arrêter","courant","停止"]],"fq":"高频，日常常用。","me":"terminer ← terminus：走到终点。","tr":{"zh":"我六点下班，所以我现在得做完工作。","fr":"Je finis à six heures, donc je dois terminer mon travail maintenant.","alt":"Je termine à dix-huit heures, donc je dois finir mon travail.","note":"finir 和 terminer 常可互换，terminer 稍正式。"}},
 "Vivre": {"pos":"v. 动词，第三组，复合时态用 avoir，过去分词 vécu","s":"生活；活着；居住。vivre à Paris = 住在巴黎；vivre bien = 生活得好。变位不规则：je vis, tu vis, il vit, nous vivons, vous vivez, ils vivent；j'ai vécu。","ipa":"[vivʁ]","ph":"v 读 [v]；i 读 [i]；-vre 读 [vʁ]，e 不发。整个词只有一个音节。","pi":"je vis 的 s 不发，读 [vi]；过去分词 vécu 读 [ve.ky]。vivre 和 voir 的 je vis 形式相同（语境区分）。","et":"来自拉丁语 vivere。同族词：vie, vivant, vital。","ex":[["Elle veut vivre à Paris.","她想住在巴黎。"],["Ils vivent ensemble depuis deux ans.","他们已经一起生活两年了。"]],"co":[["vivre à Paris","住在巴黎"],["vivre ensemble","一起生活"],["vivre seul(e)","独居"],["gagner sa vie","谋生"]],"sy":[["habiter","courant","居住（强调住所）"],["exister","courant","存在"],["résider","soutenu","居住"]],"fq":"极高频，日常常用。","me":"vivre → vie：生活就是 vie。","tr":{"zh":"我想在国外生活几年。","fr":"Je veux vivre à l'étranger pendant quelques années.","alt":"J'aimerais vivre à l'étranger quelques années.","note":"à l'étranger = 在国外；pendant 表示持续的时长。"}},
 "Difficile": {"pos":"adj. 形容词，阴阳同形：difficile；复数 difficiles","s":"困难的；不好办的；难相处的。Ce travail est difficile 是「这工作难」；C'est difficile à faire 是「做起来难」。也可形容人挑剔、不好相处：un enfant difficile。","ipa":"[di.fi.sil]","ph":"di 读 [di]；fi 读 [fi]；ci 读 [si]；l 读 [l]，结尾 e 不发。","pi":"c 在 i 前读 [s]；结尾 le 的 e 不发，l 要读出来；阴阳同形，不加 e。","et":"来自拉丁语 difficilis，由 dis-（否定）+ facilis（容易）构成。","ex":[["Ce travail est difficile.","这份工作很难。"],["C'est difficile à comprendre.","这很难理解。"]],"co":[["difficile à + infinitif","难以做……"],["une question difficile","一个难题"],["un moment difficile","艰难时刻"],["un enfant difficile","难管的孩子"]],"sy":[["dur","familier","难，艰苦"],["compliqué","courant","复杂的"],["facile","courant","反义词：容易"]],"fq":"极高频，日常常用。","me":"dif- + facile = 不容易。","tr":{"zh":"法语语法有点难，但很有意思。","fr":"La grammaire française est un peu difficile, mais intéressante.","alt":"La grammaire française, c'est un peu dur, mais c'est intéressant.","note":"difficile 阴阳同形；un peu 修饰形容词。"}},
 "Facile": {"pos":"adj. 形容词，阴阳同形：facile；复数 faciles","s":"容易的；简单的。C'est facile 是「这很容易」；facile à + 不定式 = 容易做……。也可形容人好相处：Il est facile à vivre.","ipa":"[fa.sil]","ph":"f 读 [f]；a 读 [a]；c 在 i 前读 [s]；i 读 [i]；l 读 [l]，结尾 e 不发。","pi":"c 读 [s]；结尾 l 要读出来；阴阳同形。","et":"来自拉丁语 facilis（容易做的），源于 facere（做）。同族词：facilité, faciliter。","ex":[["L'exercice est facile.","练习很容易。"],["Ce n'est pas facile de trouver un stage.","找实习并不容易。"]],"co":[["facile à + infinitif","容易做……"],["C'est facile.","这很容易。"],["Il est facile à vivre.","他很好相处。"],["plus facile","更容易"]],"sy":[["simple","courant","简单的"],["aisé","soutenu","轻松的，容易的"],["difficile","courant","反义词：困难"]],"fq":"极高频，日常常用。","me":"facile ← facere（做）：很容易就做得到。","tr":{"zh":"这个问题很简单，我可以马上回答。","fr":"Cette question est facile, je peux répondre tout de suite.","alt":"C'est facile comme question, je réponds tout de suite.","note":"question 阴性，但 facile 阴阳同形，所以不变。"}},
 "Handicapé(e)": {"pos":"adj. / n. 形容词兼名词，阳性 handicapé / 阴性 handicapée，复数 handicapés / handicapées","s":"残疾的；残障者。作形容词：Il est handicapé；作名词：un handicapé。现代更礼貌的说法是 une personne en situation de handicap（有障碍的人），正式场合多用这种说法。h 是「哈气 h」，没有连读。","ipa":"[ɑ̃.di.ka.pe]","ph":"h 不发音，也不连读；han 读鼻音 [ɑ̃]；di 读 [di]；ca 读 [ka]；pé 读 [pe]。","pi":"h 不发音，但是「h aspiré」，前面不能连读或省音：le handicapé，不是 l'handicapé。-é 结尾读 [e]；阴性 handicapée 的发音相同。","et":"来自英语 handicap，原指一种赛马或比赛的让分规则（据说与「帽子里的手」hand in cap 的游戏有关），后来引申为「障碍」。","ex":[["Il est handicapé.","他有残疾。"],["Cette place est réservée aux personnes handicapées.","这个座位是给残障人士预留的。"]],"co":[["une personne handicapée","残障人士"],["une personne en situation de handicap","有障碍的人（更礼貌）"],["une place handicapé","残疾人专用位"],["un handicap moteur","肢体残疾"]],"sy":[["en situation de handicap","soutenu","有障碍的（礼貌说法）"],["invalide","soutenu","残废（较旧，不太礼貌）"],["PMR","courant","行动不便者（personne à mobilité réduite）"]],"fq":"中频，注意礼貌用语。","me":"h 是不发音的 h 但要「挡住」前面的连读。","tr":{"zh":"这栋楼对残障人士很方便。","fr":"Ce bâtiment est accessible aux personnes handicapées.","alt":"Ce bâtiment est accessible aux personnes à mobilité réduite.","note":"accessible à + 人：对……方便进入。"}},
 "Indépendant(e)": {"pos":"adj. 形容词；阴性 indépendante，复数 indépendants / indépendantes","s":"独立的；不依赖别人的。可以说人（性格、经济上独立），也可以说国家、机构、媒体。和 dépendant（依赖的）相反。","ipa":"[ɛ̃.de.pɑ̃.dɑ̃]","ph":"in [ɛ̃]；é [e]；-pen- 的 en 和结尾 -ant 都读 [ɑ̃]；阴性 -ante 读 [ɑ̃t]，t 要发出来。","pi":"阳性结尾 -ant 的 t 不发音，阴性 indépendante 才发 [t]。后面接 de：indépendant de ses parents。","et":"前缀 in-（否定）+ dépendant（依赖的，来自拉丁语 dependere「悬挂」）。同族：indépendance（独立）。","ex":[["Elle est indépendante.","她很独立。"],["Il veut être indépendant de ses parents.","他想不再依赖父母。"],["C'est un journal indépendant.","这是一份独立的报纸。"]],"co":[["être indépendant(e) de qqn","不依赖某人"],["un pays indépendant","独立的国家"],["un travailleur indépendant","自由职业者"]],"sy":[["autonome","courant","自主的，能自己处理事情"],["libre","courant","自由的"],["dépendant","courant","反义词：依赖的"]],"fq":"中高频，日常和新闻里都常见。","me":"in-（不）+ dépendant（依赖）= 不靠别人。","tr":{"zh":"我妹妹二十岁，已经很独立了。","fr":"Ma sœur a vingt ans et elle est déjà très indépendante.","alt":"Ma sœur a vingt ans, elle est déjà bien indépendante.","note":"形容词和主语配合：sœur 是阴性，所以用 indépendante。"}},
 "Nouveau / Nouvel / Nouvelle": {"pos":"adj. 形容词；阳性 nouveau，阳性元音前 nouvel，阴性 nouvelle；复数 nouveaux / nouvelles","s":"新的（刚出现、刚买到、刚认识的）。放在名词前面：un nouveau téléphone。阳性单数名词以元音或哑音 h 开头时用 nouvel：un nouvel ami。和 neuf（全新的、没用过的）不同。","ipa":"[nu.vo]","ph":"ou [u]；-eau 读 [o]；nouvel 和 nouvelle 读音一样，都是 [nu.vɛl]，l 要发出来。","pi":"三种形式要按后面的名词选：un nouveau livre，un nouvel appartement，une nouvelle voiture。阳性复数是 nouveaux，不是 nouveaus。nouvel 和 nouvelle 听起来相同。","et":"拉丁语 novellus（novus「新」的小称形式）。同族：nouveauté（新事物）、nouvelle（消息；短篇小说）、renouveler（更新）。","ex":[["J'ai un nouveau téléphone.","我有一部新手机。"],["C'est mon nouvel ami.","这是我的新朋友。"],["Elle habite dans une nouvelle maison.","她住在一所新房子里。"]],"co":[["un nouvel an / la nouvelle année","新年"],["de nouveau","再一次，重新"],["quoi de neuf ? / rien de nouveau","有什么新鲜事？/ 没什么新消息"],["un nouveau-né","新生儿"]],"sy":[["neuf","courant","全新的（没用过）；常放在名词后：une voiture neuve"],["récent","courant","最近的"],["ancien","courant","反义词：旧的；以前的"]],"fq":"极高频，日常常用。","me":"看后面的词：元音开头用 nouvel；阴性加 -le，念 [vɛl]。","tr":{"zh":"我的新同事很友好。","fr":"Mon nouveau collègue est très sympa.","alt":"Mon nouveau collègue, il est vraiment gentil.","note":"collègue 是阳性，用 nouveau；如果是女同事，用 ma nouvelle collègue。"}},
 "Organisé(e)": {"pos":"adj. 形容词；阴性 organisée，复数 organisés / organisées（来自动词 organiser 的过去分词）","s":"有条理的；井井有条的。说人：做事有计划、不乱。也可说活动或旅行是「有组织的」：un voyage organisé = 跟团旅行。","ipa":"[ɔʁ.ɡa.ni.ze]","ph":"or [ɔʁ]；g 在 a 前读 [ɡ]；-isé 读 [i.ze]，s 在元音间读 [z]；结尾 -é 读 [e]。","pi":"s 读 [z]，不是 [s]。阴性 organisée 和阳性读音相同，只在拼写上多一个 e。","et":"来自 organiser（组织），源于 organe（器官，拉丁语 organum「工具」）。同族：organisation（组织；安排）、organisateur。","ex":[["Il est très organisé.","他很有条理。"],["Elle est organisée : elle fait toujours une liste.","她很有条理：总是列清单。"],["Nous faisons un voyage organisé en Italie.","我们去意大利跟团旅行。"]],"co":[["être bien / mal organisé(e)","有条理 / 没条理"],["un voyage organisé","跟团旅行"],["une personne organisée","有条理的人"]],"sy":[["méthodique","courant","有方法的，按步骤做事"],["rangé","courant","整洁的，收拾好的（常说东西或房间）"],["désorganisé","courant","反义词：没有条理的"]],"fq":"中频，描述性格时常用。","me":"organiser + -é：被「安排好」的人。","tr":{"zh":"我的姐姐做什么都很有条理。","fr":"Ma sœur est très organisée dans tout ce qu'elle fait.","alt":"Ma sœur, elle est hyper organisée, en tout.","note":"说女性要加 e：organisée；读音不变。"}},
 "Longtemps": {"pos":"adv. 副词（不变）","s":"很久；长时间。常放在动词后：attendre longtemps。常和 depuis、pendant 一起用：depuis longtemps（很久以来）、pendant longtemps（很长一段时间）。否定句里 pas longtemps = 没多久。","ipa":"[lɔ̃.tɑ̃]","ph":"on [ɔ̃]；-temps 读 [tɑ̃]；g 和结尾 ps 都不发音。","pi":"拼写很长，但只读两个音节。g 不发音，结尾 -ps 不发音。是一个词 longtemps，不要拆成 long temps。","et":"由 long（长）+ temps（时间）合成。long 来自拉丁语 longus，temps 来自拉丁语 tempus。","ex":[["J'attends depuis longtemps.","我等了很久。"],["On ne reste pas longtemps.","我们不会待很久。"],["Il y a longtemps que je ne l'ai pas vu.","我很久没见到他了。"]],"co":[["depuis longtemps","很久以来"],["pendant longtemps","很长一段时间"],["il y a longtemps","很久以前"],["pas longtemps","没多久"]],"sy":[["longuement","soutenu","长时间地，详细地（强调过程）"],["un moment","familier","好一会儿"],["peu de temps","courant","反义：时间不长"]],"fq":"高频，日常常用。","me":"long + temps：很「长」的「时间」，g 和 ps 都不念。","tr":{"zh":"我们很久没有在一起吃饭了。","fr":"Nous n'avons pas mangé ensemble depuis longtemps.","alt":"Ça fait longtemps qu'on n'a pas mangé ensemble.","note":"depuis longtemps 和现在完成的动作搭配时，否定句用 passé composé + depuis。"}},
 "Depuis": {"pos":"prép. 介词（也可作副词）；depuis que + 从句 = 连词短语","s":"自从；从……以来；已经（持续了……）。表示一个动作从过去开始、一直持续到现在，句子常用现在时：J'habite ici depuis un an = 我住在这里一年了。可接时间长度（depuis deux ans）或起点（depuis 2020, depuis lundi）。","ipa":"[də.pɥi]","ph":"d [d] + e [ə]（轻，常弱化）；p [p]；ui 读 [ɥi]（嘴先圆再展开）；结尾 s 不发音。","pi":"depuis 后面通常用现在时（持续到现在），不要用 passé composé 或英语的现在完成时思路。和 pendant 区分：depuis 连到现在，pendant 是一段已完成或限定的时间。结尾 s 不发音。","et":"由 de + puis 组成，puis 来自拉丁语 post（之后）。puis 本身也表示「然后」。","ex":[["J'habite ici depuis un an.","我在这里住了一年了。"],["Elle est malade depuis lundi.","她从星期一起就病了。"],["Depuis quand tu apprends le français ?","你从什么时候开始学法语的？"]],"co":[["depuis + 时间长度（depuis trois jours）","已经三天了"],["depuis + 起点（depuis 2020）","从 2020 年起"],["depuis quand ?","从什么时候起？"],["depuis que + 从句","自从……以来"]],"sy":[["il y a ... que","courant","和 depuis 意思接近：Il y a un an que j'habite ici"],["pendant","courant","在……期间（不强调连到现在）"],["dès","soutenu","一……就；从……起（强调起点）"]],"fq":"极高频，日常常用。","me":"depuis = 「自……之后」，通向「现在」的一条线。","tr":{"zh":"我学法语已经两年了。","fr":"J'apprends le français depuis deux ans.","alt":"Ça fait deux ans que j'apprends le français.","note":"持续到现在的动作用现在时 + depuis。"}},
 "Pendant": {"pos":"prép. 介词（pendant que + 从句 = 连词短语）","s":"在……期间；……的时候。后面接一段时间或一个事件：pendant les vacances, pendant le cours。也可表示持续多久：J'ai dormi pendant dix heures（我睡了十个小时），此时 pendant 可以省略。","ipa":"[pɑ̃.dɑ̃]","ph":"两个 en / an 都读鼻化音 [ɑ̃]：[pɑ̃.dɑ̃]；结尾 t 不发音。","pi":"结尾 -ant 的 t 不发音。pendant 后面接名词；接从句要用 pendant que：Pendant que je cuisine, tu mets la table。","et":"来自动词 pendre（悬挂）的现在分词：时间「悬」在那一段上。pendre 来自拉丁语 pendere。同族：pendule（钟摆），suspendre。","ex":[["Il dort pendant le cours.","他在上课期间睡觉。"],["J'ai travaillé pendant trois heures.","我工作了三个小时。"],["Pendant que tu lis, je fais le dîner.","你看书的时候，我做晚饭。"]],"co":[["pendant les vacances","假期里"],["pendant + 时间长度（pendant deux heures）","持续两个小时"],["pendant que + 从句","当……的时候"],["pendant longtemps","很长时间"]],"sy":[["durant","soutenu","在……期间（书面语）"],["au cours de","courant","在……过程中"],["depuis","courant","自从……（连到现在）"]],"fq":"极高频，日常常用。","me":"pendre 的分词：动作「悬挂」在一段时间上。","tr":{"zh":"暑假期间我在一家餐厅工作。","fr":"Pendant les vacances d'été, je travaille dans un restaurant.","alt":"Pendant l'été, je bosse dans un resto.","note":"pendant 后接名词；接动作从句用 pendant que。"}},
 "Gagner de l'argent": {"pos":"loc. 动词短语；gagner 是第一组动词（-er），助动词 avoir；argent 是阳性名词，没有复数用法（表示「钱」）","s":"赚钱；挣钱。gagner 的基本意思是「赢」或「挣得」：gagner un match（赢比赛），gagner sa vie（谋生）。「赚钱」说 gagner de l'argent，不要说 gagner l'argent。argent 还有「银；银色」的意思。","ipa":"[ɡa.ɲe də laʁ.ʒɑ̃]","ph":"gn 读 [ɲ]（像「娘」的开头，舌面抵上腭）；-er 读 [e]；de l'argent 连读：l'ar- [laʁ]；g 在 e 前读 [ʒ]；-ent 读 [ɑ̃]，t 不发音。","pi":"gagner 里 gn 读 [ɲ]，不是 [g] + [n]。argent 里 g 读 [ʒ]，t 不发音。「赚钱」用部分冠词：de l'argent，不是 l'argent。否定句里变成 ne ... pas d'argent。","et":"gagner 来自法兰克语 *waidanjan（放牧、觅食），后来转为「获利」。argent 来自拉丁语 argentum（银），因为古时用银币。","ex":[["Il veut gagner de l'argent.","他想赚钱。"],["Elle gagne bien sa vie.","她收入不错。"],["Je n'ai pas gagné beaucoup d'argent ce mois-ci.","这个月我没赚到多少钱。"]],"co":[["gagner sa vie","谋生，养活自己"],["gagner beaucoup / peu d'argent","赚很多 / 很少的钱"],["gagner 2 000 euros par mois","每月赚 2000 欧元"],["perdre de l'argent","亏钱（反义）"]],"sy":[["toucher un salaire","courant","领工资"],["se faire de l'argent","familier","挣点钱"],["dépenser de l'argent","courant","反义：花钱"]],"fq":"高频，日常常用。","me":"gagner = 赢到手；de l'argent 是「一些钱」。","tr":{"zh":"他在酒吧工作，每个月赚得不多。","fr":"Il travaille dans un bar et il ne gagne pas beaucoup d'argent.","alt":"Il bosse dans un bar, il ne gagne pas grand-chose.","note":"否定句里 de l'argent 变成 d'argent：ne ... pas d'argent；beaucoup d'argent 也用 d'。"}}
});
